INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Généalogie de Jésus-Christ, fils de David, fils d\'Abraham.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham engendra Isaac; Isaac, Jacob; Jacob, Juda et ses frères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda, Phares et Zara, qu\'il eut de Thamar; Phares, Esrom; Esrom, Aram;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram, Aminabad; Aminabad, Naasson; Naasson, Salmon;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon, Booz, qu\'il eut de Rahab; Booz, Jobed, qu\'il eut de Ruth;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jobed, Issaï; Issaï, le roi David. David engendra Salomon qu\'il eut de la femme d\'Urie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon, Roboam; Roboam, Abia; Abia, Asa;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa, Josaphat; - Josaphat, Joram; Joram, Ozias;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ozias, Joatham; Joatham, Achez; Achez, Ezéchias;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezéchias, Manassé; Manassé, Amos; Amos, Josias;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josias, Jéchonias et ses frères, lors de l\'émigration à Babylone.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Après l\'émigration à Babylone, Jéchonias engendra Salathiel; Salathiél, Zorobabel;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel, Abioud; Abioud, Eliacim; Eliacim, Azor;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor, Sadoc; Sadoc, Achim; Achim, Elioud;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Elioud, Eléazar; Eléazar, Matthan; Matthan, Jacob;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jacob, Joseph, le mari de Marie, de laquelle naquit Jésus, qu\'on appelle Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Il y a donc, en tout, quatorze générations d\'Abraham à David; quatorze, de David à l\'émigration à Babylone, et quatorze, de l\'émigration jusqu’à Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Or, voici de quelle manière Jésus-Christ vint au monde. Marie, sa mère, ayant été fiancée à Joseph, se trouva enceinte par l\'effet du Saint-Esprit, avant qu\'ils eussent habité ensemble.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Joseph, son mari, étant un homme de bien, et ne voulant pas l\'exposer à la honte, résolut de la répudier secrètement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Il y pensait, lorsqu\'un ange du Seigneur lui apparut en songe, et lui dit: «Joseph, fils de David, ne crains point de prendre chez toi Marie, ta femme; car l\'enfant qu\'elle a conçu est du Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Elle mettra au monde un fils, et tu lui donneras le nom de Jésus, parce que c\'est lui qui sauvera son peuple de ses péchés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Tout cela arriva, afin que s\'accomplît ce qu\'avait dit le Seigneur par le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '«Voici, la vierge sera enceinte; elle mettra au monde un fils à qui l’on donnera le nom d\'Emmanuel,» ce qui signifie «Dieu avec nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'A son réveil, Joseph fit comme l\'ange du Seigneur le lui avait commandé: il prit sa femme chez lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Et il ne la connut point, jusqu’à ce qu\'elle eût mis au monde un fils, et il lui donna le nom de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Jésus étant né à Bethléhem en Judée, au temps du roi Hérode, des mages d\'Orient arrivèrent à Jérusalem, et dirent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '«Où est le roi des Juifs qui vient de naître? car nous avons vu son étoile en Orient, et nous sommes venus lui rendre hommage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Le roi Hérode l\'ayant appris, en fut troublé, et tout Jérusalem avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Il fit assembler tous les principaux sacrificateurs et les scribes du peuple, et s\'informa d\'eux où devait naître le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Ils lui dirent: «C\'est à Bethléhem en Judée; car voici ce qui a été écrit par le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '«Et toi, Bethléhem, terre de Juda, tu n\'es pas la moindre entre les principales villes de Juda, car c\'est de toi que sortira un chef qui gouvernera Israël, mon peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Alors Hérode ayant fait venir secrètement les mages, sut d\'eux la date précise à laquelle l\'étoile était apparue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'et leur dit, en les envoyant à Bethléhem: «Allez, recherchez soigneusement cet enfant, et, quand vous l\'aurez trouvé, faites-le-moi savoir, afin que j\'aille aussi lui rendre hommage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Après avoir entendu le Roi, les mages partirent; et voici, l’étoile qu\'ils avaient vue en Orient, marchait devant eux, jusqu’à ce qu\'elle s\'arrêta au-dessus du lieu où était l\'enfant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'La vue de l\'étoile leur causa une grande joie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'et, étant entrés dans la maison, ils virent l\'enfant avec Marie sa mère. Ils lui rendirent hommage en se prosternant, et ayant ouvert leurs trésors, ils lui offrirent en présent de l\'or, de l\'encens et de la myrrhe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Puis, ayant été avertis en songe de ne point retourner vers Hérode, ils se retirèrent dans leur pays par un autre chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Lorsqu\'ils furent partis, un ange du Seigneur apparut en songe à Joseph, et lui dit: «Lève- toi, prends l\'enfant et sa mère, et fuis en Egypte. Restes-y jusqu’à ce que je te dise de revenir; car Hérode doit chercher l\'enfant pour le faire périr.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Joseph s\'étant levé, prit l\'enfant et sa mère pendant la nuit, et se retira en Egypte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Il y resta jusqu’à la mort d\'Hérode, afin que s\'accomplît cette parole que le Seigneur avait prononcée par le prophète: «J\'ai appelé mon Fils d\'Egypte.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Hérode, voyant qu\'il avait été joué par les mages, entra dans une violente colère, et fit tuer tous les enfants qui étaient à Bethléhem et dans tout son territoire, depuis l\'âge de deux ans et au-dessous, d\'après la date qu\'il connaissait exactement par les mages.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Alors s\'accomplit cette parole prononcée par Jérémie, le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '«Un cri a été entendu à Rama, des pleurs et de grandes lamentations: Rachel pleure ses enfants, et n’a pas voulu être consolée, parce qu\'ils ne sont plus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Hérode étant mort, un ange du Seigneur apparut en songe à Joseph en Egypte, et lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '«Lève-toi, prends l\'enfant et sa mère, et va dans le pays d\'Israël, car ceux qui en voulaient à la vie de l\'enfant sont morts.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Joseph se leva, prit l\'enfant et sa mère, et rentra dans le pays d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Mais, ayant appris qu\'Archelaüs régnait sur la Judée à la place d\'Hérode, son père, il craignit de s\'y rendre; et, ayant été averti en songe, il se retira dans le territoire de la Galilée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'et alla s\'établir dans une ville appelée Nazareth, afin que s\'accomplît ce qu\'avaient dit les prophètes, qu\'il sera appelé Nazaréen.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'En ces temps-là parut Jean-Baptiste, prêchant dans le désert de Judée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'et disant: «Repentez-vous, car le royaume des cieux est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'C\'est de lui que parle Esaïe, le prophète, quand il dit: C\'est une voix qui crie au désert: «Préparez le chemin du Seigneur, faites-lui des sentiers droits.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Jean avait un vêtement de poil de chameau, et une ceinture de cuir autour des reins; il se nourrissait de sauterelles et de miel sauvage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Les habitants de Jérusalem, de toute la Judée et de tout le pays qui avoisine le Jourdain, se rendaient vers lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'et se faisaient baptiser par lui dans le Jourdain, confessant leurs péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Or, Jean voyant un grand nombre de pharisiens et de sadducéens, qui venaient se faire baptiser, leur dit: «Race de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Produisez donc du fruit digne de la repentance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'et ne croyez pas dire en vous-mêmes: «Nous avons pour père Abraham; car je vous dis que de ces pierres, Dieu peut susciter des enfants à Abraham.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Déjà la cognée est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit, va être coupé et jeté au feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Pour moi, je vous baptise d\'eau en vue de la repentance; mais celui qui vient après moi, est plus puissant que moi, et je ne suis pas digne de lui porter ses sandales: c\'est lui qui vous baptisera d\'esprit saint et de feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Il a son van à la main, et il nettoiera son aire; il amassera son blé dans le grenier, mais il brûlera la paille dans un feu qui ne s\'éteint point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alors Jésus arriva de Galilée au Jourdain vers Jean, pour se faire baptiser par lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Mais Jean s\'y opposait en disant: «C\'est moi qui ai besoin d\'être baptisé par toi, et tu viens à moi!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jésus lui répondit: «Laisse-moi faire seulement, car il convient que nous accomplissions ainsi tout ce qui est juste.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Alors Jean le laissa faire. Jésus, ayant été baptisé, sortit immédiatement de l’eau; et voici, les cieux s\'ouvrirent à lui, et il vit l\'Esprit de Dieu descendre comme une colombe et venir sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Et une Voix sortit des cieux, disant: «Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Alors Jésus fut emmené par l\'Esprit au désert, pour être tenté par le diable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Il jeûna quarante jours et quarante nuits, après quoi il eut faim.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Et le tentateur l\'ayant abordé, lui dit: «Si tu es Fils de Dieu, ordonne que ces pierres se changent en pains.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mais Jésus répondit: Il est écrit: «l’homme ne vivra pas de pain seulement, mais de toute parole qui sort de la bouche de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Alors le diable le transporta dans la ville sainte, le posa à l\'extrémité de l\'aile du temple,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'et lui dit: «Si tu es Fils de Dieu, jette-toi en bas; car il est écrit: «Il donnera des «ordres à ses anges, à ton sujet; et ils te porteront sur leurs bras, de peur que ton pied ne heurte contre une pierre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Jésus lui dit: Il est écrit aussi: «Tu ne tenteras point le Seigneur ton Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Le diable le transporta encore sur une montagne très-haute, lui montra tous les royaumes du monde et leur gloire,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'et lui dit: «Je te donnerai tout cela, si, te jetant à mes pieds, tu m\'adores.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Jésus lui dit: Retire-toi, Satan; car il est écrit: «Tu adoreras le Seigneur ton Dieu, et tu le serviras lui seul.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Alors le diable le quitta; et des anges s\'approchèrent, et ils le servirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Jésus ayant appris que Jean avait été mis en prison, se retira en Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Il quitta Nazareth et alla s\'établir à Capernaoum, ville située au bord de la mer, dans le territoire de Zabulon et de Nephthali,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'afin que s\'accomplît ce qui a été dit par Esaïe, le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '«La terre de Zabulon et la terre de Nephthali, ce pays qui s’étend vers la mer jusqu\'au delà du Jourdain, la Galilée des Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'ce pays, qui était plongé dans les ténèbres, a vu une grande lumière, et la lumière s\'est levée sur ceux qui étaient dans la région et dans l’ombre de la mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Dès lors Jésus se mit à prêcher, disant: «Repentez-vous, car le royaume des cieux est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Comme il cheminait le long de la mer de Galilée, il vit deux frères, Simon, appelé Pierre, et André, son frère, qui jetaient leurs filets dans la mer, car ils étaient pêcheurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Et il leur dit: «Venez, suivez-moi, et je vous ferai pêcheurs d\'hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Aussitôt ils quittèrent leurs filets, et le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Puis, un peu plus loin, il vit deux autres frères, Jacques, fils de Zébédée, et Jean, son frère, qui raccommodaient leurs filets dans leur barque avec Zébédée leur père, et il les appela.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Aussitôt ils quittèrent leur barque et leur père, et le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Jésus allait par toute la Galilée, enseignant dans les synagogues, prêchant la bonne nouvelle du royaume et guérissant');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'toute maladie et toute infirmité parmi le peuple. Sa renommée se répandit dans toute la Syrie, et on lui amena tous ceux qui se portaient mal, qui étaient affligés de maladies et de douleurs diverses, des démoniaques, des lunatiques, des paralytiques, et il les guérit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Une grande foule le suivit de la Galilée, de la Décapole, de Jérusalem, de la Judée et d\'au delà du Jourdain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Jésus, voyant cette multitude, monta sur la montagne, et quand il se fut assis, ses disciples s\'approchèrent de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Alors, ouvrant la bouche, il se mit à les enseigner, disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '«Heureux les pauvres en esprit, car le royaume des cieux est à eux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, '«Heureux les affligés, car ils seront consolés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, '«Heureux ceux qui sont doux, car ils posséderont la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, '«Heureux ceux qui ont faim et soif de la justice, car ils seront rassasiés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, '«Heureux les miséricordieux, car ils obtiendront miséricorde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, '«Heureux ceux qui ont le coeur pur, car ils verront Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, '«Heureux les pacifiques, car ils seront appelés fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, '«Heureux ceux qui sont persécutés pour la justice, car le royaume des cieux est à eux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, '«Vous serez heureux, lorsqu\'on vous insultera, qu\'on vous persécutera et qu\'on dira de vous toute sorte de mal à cause de moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Réjouissez-vous alors et tressaillez de joie, car votre récompense est grande dans les cieux: c\'est ainsi qu\'on a persécuté les prophètes qui ont été avant vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, '«Vous êtes le sel de la terre; mais si le sel perd sa saveur, avec quoi la lui rendra-t-on? Il n\'est plus bon qu\'à être jeté dehors et foulé aux pieds par les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vous êtes la lumière du monde. Une ville située au sommet d\'une montagne, ne peut être cachée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'On n\'allume pas non plus une lampe pour la mettre sous le boisseau, mais on la met sur son pied, et elle brille pour tous ceux qui sont dans la maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Qu\'ainsi votre lumière brille devant les hommes, afin qu\'ils voient vos bonnes oeuvres, et qu\'ils glorifient votre Père qui est dans les cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, '«Ne pensez pas que je sois venu abolir la Loi et les Prophètes: je ne suis pas venu abolir, mais accomplir;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'car je vous dis, en vérité, que, jusqu’à ce que le ciel et la terre passent, pas un iota, pas un trait de lettre de la Loi ne passera, que tout ne soit exécuté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Celui donc qui aura violé un des moindres de ces commandements, et aura, par son exemple, appris aux hommes à les violer, sera appelé le plus petit dans le royaume des cieux; mais celui qui les aura observés, et aura appris aux hommes à les observer, celui-là sera appelé grand dans le royaume des cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Car je vous dis que si votre justice ne l\'emporte de beaucoup sur celle des scribes et des pharisiens, vous n\'entrerez pas dans le royaume des cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, '«Vous avez entendu qu\'il a été dit aux anciens: «Tu ne tueras point; celui qui aura tué sera condamné.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mais moi, je vous dis que quiconque se met en colère contre son frère, mérite la condamnation. Celui qui dira à son frère «raca,» mérite d\'être condamné par le sanhédrin; celui qui lui dira «scélérat,» mérite d\'être jeté dans la Géhenne ardente.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, '«Si donc tu présentes ton offrande à l\'autel, et que, là, il te souvienne que ton frère a quelque chose contre toi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'laisse là ton offrande, devant l\'autel; va d\'abord te réconcilier avec ton frère, puis viens présenter ton offrande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Accorde-toi promptement avec ta partie adverse, même pendant que tu es en chemin avec elle, de peur qu\'elle ne te livre au juge, le juge au sergent, et que tu ne sois jeté en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'En vérité, je te dis que tu n\'en sortiras pas que tu n\'aies payé jusqu\'au dernier sou.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, '«Vous avez entendu qu\'il a été dit: «Tu ne commettras point adultère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mais moi, je vous dis que quiconque regarde une femme pour la convoiter, a déjà commis l\'adultère dans son coeur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, '«Si ton oeil droit est pour toi une occasion de chute, arrache-le et le jette loin de toi; car il vaut mieux pour toi qu\'un seul de tes membres périsse, que si ton corps tout entier était jeté dans la Géhenne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Si ta main droite est pour toi une occasion de chute, coupe-la et la jette loin de toi; car il vaut mieux pour toi qu\'un seul de tes membres périsse, que si ton corps tout entier allait dans la Géhenne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, '«Il a été dit: «Que celui qui répudie sa femme, lui donne un acte de divorce.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mais moi, je vous dis que quiconque répudie sa femme, si ce n\'est pour raison d\'infidélité, la pousse à devenir adultère, et que celui qui épouse une femme répudiée, commet un adultère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, '«Vous avez encore entendu qu\'il a été dit aux anciens: «Tu ne te parjureras point, mais tu t\'acquitteras envers le Seigneur des serments que tu auras faits»,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mais moi, je vous dis de ne point jurer du tout, ni par le ciel, car c\'est le trône de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ni par la terre, car c\'est son marchepied; ni par Jérusalem, car c\'est la ville du grand Roi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ne jure pas non plus par ta tête, car tu ne peux rendre blanc ou noir un seul de tes cheveux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Que votre parole soit: Oui! oui! Non! non! Ce qui se dit de plus vient du malin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Vous avez entendu qu\'il a été dit: «Oeil pour oeil et dent pour dent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Mais moi, je vous dis de ne point tenir tête au méchant. Si quelqu\'un te frappe sur la joue droite, présente-lui l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Si quelqu\'un veut t\'intenter un procès pour prendre ta tunique, abandonne-lui aussi le manteau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'Si quelqu\'un te met en réquisition pour faire un mille, fais-en deux avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Donne à qui te demande, et n\'évite pas celui qui veut t\'emprunter.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Vous avez entendu qu\'il a été dit: «Tu aimeras ton prochain, et tu haïras ton ennemi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Mais moi, je vous dis: Aimez vos ennemis et priez pour ceux qui vous persécutent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'afin que vous soyez fils de votre Père qui est dans les cieux; car il fait lever son soleil sur les méchants et sur les bons, et il répand sa pluie sur les justes et sur les injustes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Si vous aimez ceux qui vous aiment, quelle récompense méritez-vous? Les publicains mêmes n\'en font-ils pas autant?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Et si vous ne saluez que vos frères, que faites-vous d\'extraordinaire? Les païens mêmes n\'en font-ils pas autant?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Soyez donc parfaits comme votre Père céleste est parfait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Gardez-vous d\'étaler votre justice devant les hommes pour en être vus; autrement, il n\'y a pas pour vous de récompense auprès de votre Père qui est dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Lors donc que vous faites l\'aumône, ne faites pas sonner la trompette devant vous, comme font les hypocrites dans les synagogues et dans les rues, pour être glorifiés des hommes. En vérité, je vous dis qu\'ils ont leur récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Pour toi, quand tu fais l\'aumône, que ta main gauche ne sache pas ce que fait ta main droite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'afin que ton aumône se fasse en secret; et ton Père, qui voit ce qui est secret, te récompensera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Lorsque vous priez, ne soyez pas comme les hypocrites, qui aiment à prier debout dans les synagogues et au coin des places. En vérité, je vous dis qu\'ils ont leur récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mais toi, quand tu pries, entre dans ta chambre, ferme ta porte à clef, et prie ton Père qui est en ce lieu secret; et ton Père, qui voit ce qui est secret, te récompensera publiquement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Quand vous priez, ne bredouillez pas, comme font les païens, qui s\'imaginent que par leur flux de paroles ils seront exaucés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne leur ressemblez point: votre Père sait ce dont vous avez besoin, avant que vous le lui demandiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vous donc priez ainsi: Notre Père qui es aux cieux, que ton nom soit sanctifié;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'que ton règne vienne; que ta volonté soit faite sur la terre comme au ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Donne-nous aujourd\'hui notre pain quotidien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Remets-nous nos dettes, comme nous avons remis leurs dettes à ceux qui nous doivent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'et ne nous induis point en tentation, mais délivre-nous du mal. [Car c\'est à toi qu’appartiennent le règne, la puissance et la gloire, éternellement. Amen],');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Si vous pardonnez aux hommes leurs offenses, votre Père céleste vous pardonnera aussi les vôtres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'mais si vous ne pardonnez pas aux hommes, votre Père ne vous pardonnera pas non plus vos offenses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Lorsque vous jeûnez, ne prenez pas un air sombre, comme font les hypocrites, qui se rendent le visage méconnaissable, pour qu\'on connaisse qu\'ils jeûnent. En vérité, je vous dis qu\'ils ont leur récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Mais toi, quand tu jeûnes, parfume- toi la tête et te lave le visage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'afin qu\'il ne paraisse pas aux hommes que tu jeûnes, mais à ton Père, qui est avec toi dans le secret; et ton Père, qui voit ce qui est secret, te récompensera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne vous amassez pas des trésors sur la terre, où la gerce et tout ce qui ronge détruit, et où les voleurs font effraction et dérobent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Amassez-vous des trésors dans le ciel, où la gerce ni rien de ce qui ronge ne détruit, et où les voleurs ne font point effraction ni ne dérobent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'car là où est ton trésor, là aussi sera ton coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'La lampe du corps, c\'est l\'oeil. Si ton oeil est bon, tout ton corps sera éclairé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'mais, si ton oeil est mauvais, tout ton corps sera dans les ténèbres. Si donc la lumière qui est en toi, est déjà ténèbres, quelles ténèbres!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nul ne peut servir deux maîtres; car, ou il haïra l\'un et aimera l\'autre, ou il s\'attachera à l\'un et méprisera l\'autre: vous ne pouvez servir Dieu et Mamon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'C\'est pourquoi je vous dis: Ne vous mettez point en souci, ni pour votre vie, de ce que vous mangerez et de ce que vous boirez; ni pour votre corps, de quoi vous vous vêtirez. La vie n\'est-elle pas plus que la nourriture, et le corps plus que le vêtement?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Regardez les oiseaux du ciel: ils ne sèment ni ne moissonnent, ils n\'amassent rien dans des greniers; et votre Père céleste les nourrit. Ne valez-vous pas bien plus qu\'eux?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'D\'ailleurs, qui de vous peut, par ses soucis, ajouter une coudée à sa taille?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Et pourquoi vous mettre en souci du vêtement? Considérez comment croissent les lis des champs: ils ne travaillent ni ne filent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'cependant je vous dis que Salomon même, dans toute sa magnificence, n\'était point vêtu comme l\'un de ces lis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Si Dieu revêt de la sorte l\'herbe des champs, qui est aujourd\'hui et qui demain sera jetée au four, combien plutôt ne vous vêtira-t-il pas, vous, ô gens de peu de foi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne vous mettez donc point en souci, et ne dites pas: «Que mangerons-nous, ou que boirons-nous, ou de quoi nous vêtirons-nous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'comme font les païens, qui recherchent toutes ces choses, car votre Père céleste sait que vous en avez besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Cherchez premièrement le royaume et sa justice, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne vous mettez pas en souci du lendemain, car le lendemain aura souci de lui-même. A chaque jour suffit sa peine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '«Ne jugez point, afin de n\'être pas jugés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'car on vous jugera comme vous aurez jugé, et l’on se servira pour vous de la mesure avec laquelle vous aurez mesuré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'D\'où vient que tu vois la paille qui est dans l\'oeil de ton frère, tandis que tu ne remarques pas la poutre qui est dans ton oeil?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ou comment peux-tu dire à ton frère: «Laisse-moi ôter cette paille qui est dans ton oeil,» quand il y a une poutre dans le tien!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hypocrite, ôte premièrement la poutre qui est dans ton oeil, et alors tu verras à ôter la paille de l\'oeil de ton frère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, '«Ne donnez point les choses saintes aux chiens; ne jetez pas non plus vos perles devant les pourceaux, de peur qu\'ils ne les foulent aux pieds, et que, se tournant contre vous, ils ne vous déchirent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Demandez, et l\'on vous donnera; cherchez, et vous trouverez; heurtez, et l\'on vous ouvrira;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'car quiconque demande, reçoit; qui cherche, trouve; et l\'on ouvre à celui qui heurte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ou bien, quel est l\'homme parmi vous qui donne une pierre à son fils, quand il lui demande du pain?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Ou, s\'il lui demande du poisson, lui donnera-t-il un serpent?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Si donc vous, tout méchants que vous êtes, vous savez donner de bonnes choses à vos enfants, combien plus votre Père qui est dans les cieux, donnera-t-il de bonnes choses à ceux qui les lui demandent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, '«Ainsi, tout ce que vous voudriez que les hommes fissent pour vous, faites-le de même pour eux: c\'est la Loi et les Prophètes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, '«Entrez par la porte étroite, car la porte large et le chemin spacieux mènent à la perdition; et bien des gens y passent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Que la porte est petite et le sentier étroit, qui mènent à la vie, et qu\'il y a peu de gens qui les trouvent!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, '«Gardez- vous des faux prophètes: ils viennent à vous sous la peau de brebis, mais au dedans, ce sont des loups ravissants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vous les connaîtrez à leurs fruits. Cueille-t-on du raisin sur des épines, ou des figues sur des chardons?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'De même, tout bon arbre donne de bons fruits, mais le mauvais arbre donne de mauvais fruits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Un bon arbre ne peut donner de mauvais fruits, ni un mauvais arbre, de bons fruits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'On coupe tout arbre qui ne donne pas de bons fruits, et on le jette au feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'C\'est donc à leurs fruits que vous les connaîtrez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ceux qui me disent: «Seigneur! Seigneur!» n\'entreront pas tous dans le royaume des cieux, mais ceux-là seulement qui font la volonté de mon Père qui est dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Plusieurs me diront en ce jour-là: «Seigneur, Seigneur, n\'est-ce pas en ton nom que nous avons prophétisé? n\'est-ce pas en ton nom que nous avons chassé les démons? n\'est-ce pas en ton nom que nous avons fait bien des miracles?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Alors je leur dirai ouvertement: «Je ne vous ai jamais connus. Retirez-vous de moi, ouvriers d\'iniquité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, '«Tout homme donc qui entend ce que je viens de dire et le met en pratique, je le comparerai à un homme sensé, qui a bâti sa maison sur le roc.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'La pluie est tombée, les torrents sont venus, les vents ont soufflé et se sont déchaînés contre cette maison; elle n\'est point tombée, parce qu\'elle était fondée sur le roc.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Et quiconque entend ce que je viens de dire et ne le met pas en pratique, sera comparé à un insensé qui a bâti sa maison sur le sable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'La pluie est tombée, les torrents sont venus, les vents ont soufflé et ont battu cette maison; elle est tombée, et la ruine en a été grande.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Quand Jésus eut fini de parler, la foule fut frappée de son enseignement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'car il l\'enseignait comme ayant autorité, et non comme les scribes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Quand Jésus descendit de la montagne, une grande foule le suivit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'et voici, un lépreux s\'étant approché, se prosterna devant lui, et lui dit: «Seigneur, si tu le veux, tu peux me rendre net.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jésus avançant la main, le toucha, disant: «Je le veux, sois net.» Aussitôt il fut purifié de sa lèpre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Et Jésus lui dit: «Garde-toi d\'en parler à personne; mais va, montre-toi au sacrificateur, et présente l\'offrande que Moïse a prescrite pour attester au peuple la guérison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Comme Jésus entrait à Capernaoum, un centurion l\'aborda, et lui adressa cette prière:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '«Seigneur, mon serviteur est au lit, chez moi, paralysé et souffrant cruellement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jésus lui dit: «J\'irai le guérir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Le centurion répondit: «Je ne suis pas digne que tu entres sous mon toit, mais dis seulement un mot, et mon serviteur sera guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Car, moi qui suis sous le commandement d\'autrui, j\'ai des soldats sous mes ordres, et je dis à celui-ci: «Va,» et il va; et à un autre: «Viens,» et il vient; et à mon esclave: «Fais cela,» et il le fait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Jésus, étonné de ce qu\'il entendait, dit à ceux qui le suivaient: «Je vous assure que je n\'ai pas trouvé une aussi grande foi même en Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Je vous dis que bien des gens viendront de l\'orient et de l\'occident, et seront à table avec Abraham, Isaac et Jacob dans le royaume des cieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'tandis que les fils du royaume seront jetés dans les ténèbres du dehors, où il y aura des pleurs et des grincements de dents.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Puis Jésus dit au centurion: «Va, et qu\'il te soit fait selon ta foi.» Et à cette heure même son serviteur fut guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Jésus entra ensuite dans la maison de Pierre, et vit sa belle-mère qui était au lit, ayant la fièvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Il lui toucha la main, et la fièvre la quitta: elle se leva et le servit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Quand le soir fut venu, on amena à Jésus plusieurs démoniaques: d\'un mot, il chassa les esprits et guérit tous les malades;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'afin que s\'accomplît ce qui a été dit par Esaïe, le prophète: «Il a pris vos infirmités et a emporte nos maladies.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Jésus se voyant entouré d\'une grande foule, donna l’ordre de passer à l\'autre bord.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Un scribe s\'approcha, et lui dit: «Maître, je te suivrai partout où tu iras.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Et Jésus lui dit: «Les renards ont des tanières et les oiseaux du ciel, des abris; mais le Fils de l’homme n\'a pas un lieu pour reposer sa tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Un de ses disciples lui dit: Seigneur, permets-moi d\'aller d\'abord ensevelir mon père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mais Jésus lui dit: «Suis-moi, et laisse les morts ensevelir leurs morts.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Il entra dans la barque, et ses disciples l’accompagnèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Tout à coup une grande tourmente s\'éleva sur la mer, au point que la barque était couverte par les vagues. Cependant Jésus dormait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Les disciples s\'approchèrent de lui, et le réveillèrent en disant: Seigneur, sauve-nous, nous périssons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Jésus leur dit: «Pourquoi avez-vous peur, gens de peu de foi?» Alors il se leva, tança les vents et la mer; et il se fit un grand calme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'L\'équipage étonné dit: «Quel est cet homme, que les vents et la mer lui obéissent?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Quand Jésus eut abordé à l\'autre rive, dans le pays des Gergéséniens, deux démoniaques vinrent à sa rencontre: ils sortaient des sépulcres, et ils étaient si méchants que personne n\'osait passer par ce chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Ils se mirent à crier: «Qu\'y a-t-il entre toi et nous, Fils de Dieu? Es-tu venu ici nous tourmenter avant le temps?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Or il y avait loin d\'eux un grand troupeau de pourceaux qui paissaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Et les démons lui adressèrent cette prière: «Si tu nous chasses, envoie-nous dans ce troupeau de pourceaux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Jésus leur dit: «Allez.» Les démons, étant sortis, allèrent dans le troupeau de pourceaux; et aussitôt le troupeau tout entier se rua du haut du précipice dans la mer, et périt dans les eaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Ceux qui le gardaient s\'enfuirent, et, s\'étant rendus dans la ville, ils rapportèrent tout ce qui venait de se passer, ainsi que ce qui concernait les démoniaques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Aussitôt tous les habitant de la ville allèrent au-devant de Jésus, et, dès qu\'ils le virent, ils le supplièrent de quitter leur territoire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Jésus, étant entré dans la barque, traversa la mer et vint en sa ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'On lui présenta un paralytique couché sur un lit; et Jésus voyant la foi de ces gens-là, dit au paralytique: «Prends courage, mon enfant, tes péchés te sont pardonnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Là-dessus, quelques scribes dirent en eux-mêmes: «Cet homme blasphème.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Et Jésus, voyant leurs pensées, dit: «Pourquoi avez-vous de mauvaises pensées dans vos coeurs?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Car, lequel est le plus aisé de dire: «Tes péchés sont pardonnés, ou de dire: Lève-toi et marche?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Or, afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés: «Lève-toi, dit-il alors au paralytique, prends ton lit, et va-t\'en dans ta maison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Le paralytique se leva, et s\'en alla dans sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'La foule, voyant cela, fut remplie de crainte, et elle glorifia Dieu qui a donné un tel pouvoir aux hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Jésus, quittant ce lieu, vit, en passant, un homme appelé Matthieu, qui était assis au bureau des péages, et il lui dit: «Suis-moi.» Celui-ci se leva, et le suivit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Et comme Jésus était à table, à la maison, beaucoup de publicains et de gens de mauvaise vie, vinrent se mettre à table avec lui et avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Les pharisiens, ayant vu cela, dirent à ses disciples: «Pourquoi votre Maître mange-t-il avec les publicains et les gens de mauvaise vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jésus les ayant entendus, leur dit: «Ce ne sont pas les bien portants qui ont besoin de médecin, mais ceux qui se portent mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Allez apprendre ce que signifie cette parole: «Je veux la miséricorde et non le sacrifice;» car je ne suis pas venu appeler les justes, mais les pécheurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Alors les disciples de Jean vinrent vers Jésus, et lui dirent: «Pourquoi les pharisiens et nous, jeûnons-nous souvent, tandis que tes disciples ne jeûnent point?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jésus leur dit: «Les amis de l\'époux peuvent-ils s\'attrister aussi longtemps que l\'époux est avec eux? Le temps viendra où l\'époux leur sera ôté, alors ils jeûneront.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Personne ne met une pièce de drap neuf à un vieux habit, car la pièce emporte un morceau de l\'habit, et il se fait une déchirure pire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'On ne met pas non plus du vin nouveau dans de vieilles outres; autrement, les outres se rompent, le vin se répand, et les outres sont perdues; mais on met le vin nouveau dans des outres neuves, de sorte que le vin et les outres se conservent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Il leur parlait ainsi, lorsqu\'un des chefs de la synagogue entra, se prosterna devant lui, et lui dit: «Ma fille vient de mourir; mais viens lui imposer les mains, et elle vivra.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Jésus se leva, et le suivit avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Alors une femme, atteinte d\'une hémorragie depuis douze ans, s\'approcha de lui par derrière, et toucha la houppe de son manteau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'car elle disait en elle-même: «Si seulement je touche son manteau, je serai guérie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jésus, s\'étant retourné, la vit, et lui dit: «Rassure-toi, ma fille, ta foi t\'a guérie.» Et cette femme fut guérie à l\'heure même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Quand Jésus fut arrivé à la maison du chef de la synagogue, et qu\'il vit les joueurs de flûte, et une foule de gens qui faisaient un grand bruit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'il leur dit: «Retirez-vous, car cette jeune fille n\'est pas morte, mais elle dort.» Et ils se moquèrent de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Lorsqu\'on eut fait sortir tout le monde, il entra dans la chambre, saisit la main de la jeune fille; et elle se leva.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Et la nouvelle s\'en répandit dans toute la contrée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Jésus s\'en alla. Comme il passait, deux aveugles le suivirent en criant: «Aie pitié de nous, Fils de David.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Lorsqu\'il fut rentré dans sa maison, ces aveugles s\'approchèrent de lui, et Jésus leur dit: «Croyez-vous que je puisse faire ce que vous demandez?» Ils lui dirent: «Oui, Seigneur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Alors il leur toucha les yeux, et leur dit: «Qu\'il vous soit fait selon votre foi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Et ils recouvrèrent la vue. Jésus ajouta d\'un ton sévère: «Prenez garde que personne ne le sache.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mais, dès qu\'ils furent dehors, ils publièrent ses louanges dans toute la contrée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Quand ils furent partis, on présenta à Jésus un démoniaque sourd-muet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Le démon ayant été chassé, le muet parla, et la foule, pleine d\'admiration, disait: «Jamais pareille chose ne s\'est vue en Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mais les pharisiens disaient: «C\'est par le prince des démons qu\'il chasse les démons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Jésus allait par toutes les villes et les villages, enseignant dans les synagogues, prêchant la bonne nouvelle du royaume et guérissant toute maladie et toute infirmité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'A la vue des foules qui le suivaient, Jésus se sentit ému de compassion pour elles, car elles étaient dans un état de lassitude et de prostration, comme le seraient des brebis qui n\'ont point de berger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Alors il dit à ses disciples: «La moisson est grande, mais il y a peu d\'ouvriers;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'priez donc le maître de la moisson d\'envoyer des ouvriers dans sa moisson.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Puis, ayant appelé ses douze disciples, il leur donna le pouvoir de chasser les esprits impurs, et de guérir toute maladie et toute infirmité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Or, voici les noms des douze Apôtres: Le premier est Simon, appelé Pierre, puis André, son frère; Jacques, fils de Zébédée, et Jean, son frère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippe et Barthélemi; Thomas et Matthieu, le publicain; Jacques, fils d\'Alphée et Lebbée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon le zélateur, et Judas l\'iscariot, celui qui livra Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Ce sont là les douze que Jésus envoya en mission, après leur avoir donné ses instructions, en disant: «N\'allez pas vers les Gentils, et n\'entrez pas dans les villes des Samaritains;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'allez plutôt vers les brebis perdues de la maison d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Partout, sur votre chemin, prêchez, et dites: «Le royaume des cieux est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Guérissez les malades, rendez nets les lépreux, chassez les démons. Vous avez reçu gratuitement, donnez gratuitement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne prenez ni or, ni argent, ni monnaie dans vos ceintures;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ni sac de voyage, ni deux tuniques, ni sandales, ni bâton; car l\'ouvrier mérite sa nourriture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'En quelque ville ou village que vous entriez, informez-vous de quelque personne respectable, et demeurez chez elle jusqu\'à ce que vous partiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'En entrant, saluez ceux de la maison;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'et, si cette maison est respectable, que votre paix vienne sur elle; mais si elle ne l\'est pas, que votre paix revienne à vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Si l’on ne vous reçoit pas, et même si l\'on n\'écoute pas vos paroles, sortez de cette maison ou de cette ville en secouant la poussière de vos pieds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'En vérité, je vous dis qu\'au jour du jugement, le sort du pays de Sodome et de Gomorrhe sera plus supportable que celui de cette ville-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Je vous envoie comme des brebis au milieu des loups; soyez donc prudents comme les serpents et simples comme les colombes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Tenez-vous en garde contre les hommes, car ils vous livreront aux tribunaux, et ils vous fouetteront dans leurs synagogues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'On vous mènera devant les gouverneurs et devant les rois, à cause de moi, et vous rendrez témoignage devant eux et devant les Gentils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Quand on vous livrera entre leurs mains, ne vous mettez pas en souci de la manière dont vous parlerez, ni de ce que vous direz; ce que vous devez dire, vous sera inspiré à l\'heure même:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'ce n\'est pas vous qui parlez, c\'est l\'Esprit de votre Père, qui parle en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Le frère livrera son frère à la mort, et le père, son enfant; les enfants s\'élèveront contre leurs pères et leurs mères, et les mettront à mort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'et vous serez haïs de tous à cause de mon nom; mais celui qui persévérera jusqu’à la fin, sera sauvé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Quand on vous persécutera dans une ville, fuyez dans une autre. En vérité, je vous dis que vous n\'aurez pas achevé de parcourir les villes d\'Israël, que le Fils de l\'homme sera venu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Le disciple n\'est pas au-dessus du maître, ni l\'esclave au-dessus de son seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'il suffit au disciple d\'être traité comme son maître, et à l\'esclave d\'être traité comme son seigneur. S\'ils ont appelé le maître de la maison Belzébuth, à combien plus forte raison appelleront-ils ainsi ses gens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne les craignez donc point, car il n\'y a rien de caché qui ne se découvre, ni rien de secret qui ne finisse par être connu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Ce que je vous dis dans les ténèbres, dites-le au grand jour; et ce que je vous dis à l\'oreille, publiez-le sur les toits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Ne craignez pas ceux qui tuent le corps, et qui ne peuvent tuer l\'âme; craignez plutôt celui qui peut faire périr l\'âme et le corps dans la Géhenne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Ne donne-t-on pas deux passereaux pour un sou? et pourtant il n\'en tombe pas un à terre sans la volonté de votre Père;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'les cheveux mêmes de votre tête sont tous comptés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne craignez donc point; vous valez plus qu\'un grand nombre de passereaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Ainsi, quiconque me confessera devant les hommes, je le confesserai aussi devant mon Père qui est dans les cieux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'mais quiconque me reniera devant les hommes, je le renierai aussi devant mon Père qui est dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, '«Ne pensez pas que je sois venu apporter la paix sur la terre; je suis venu apporter, non la paix, mais l\'épée:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'je suis venu mettre le fils contre son père, la fille contre sa mère, et la belle-fille contre sa belle-mère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'on aura pour ennemis, les gens de sa propre maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Celui qui aime son père ou sa mère plus que moi, n\'est pas digne de moi; celui qui aime son fils ou sa fille plus que moi, n\'est pas digne de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'et celui qui ne prend pas sa croix et ne me suit pas, n\'est pas digne de moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Celui qui sauvera sa vie, la perdra, et celui qui perdra sa vie à cause de moi, la retrouvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Qui vous reçoit, me reçoit, et qui me reçoit, reçoit celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Celui qui reçoit un prophète, en qualité de prophète, recevra une récompense de prophète; celui qui reçoit un juste, en qualité de juste, recevra une récompense de juste;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'et n\'eût-on donné qu\'un verre d\'eau froide à l\'un de ces petits, parce qu\'il est mon disciple, je vous dis en vérité, qu\'on ne perdra point sa récompense.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Quand Jésus eut achevé de donner ses instructions à ses douze disciples, il quitta ces lieux pour aller enseigner et prêcher dans les villes du pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Jean ayant entendu parler dans sa prison des oeuvres que Christ faisait, lui envoya dire par ses disciples:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, '«Es-tu celui qui doit venir, ou devons-nous en attendre un autre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jésus leur répondit: «Allez rapporter à Jean ce que vous entendez et ce que vous voyez:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'les aveugles voient, les boiteux marchent, les lépreux sont rendus nets, les sourds entendent, les morts ressuscitent, et la bonne nouvelle est annoncée aux pauvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Heureux celui pour qui je ne serai pas une occasion de chute!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Comme les disciples s\'en allaient, Jésus se mit à parler de Jean au peuple: «Qu\'êtes-vous allés contempler au désert? un roseau agité par le vent?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Mais encore qu’êtes-vous allés voir? un homme vêtu d\'habits somptueux? Ceux qui portent des habits somptueux se trouvent dans les maisons des rois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mais pourquoi êtes-vous allés au désert? pour voir un prophète? — Oui, vous dis-je, et plus qu\'un prophète;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'car c\'est celui dont il est écrit: «Voici, j\'envoie mon messager devant ta face, pour préparer le chemin devant toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'En vérité, je vous dis que parmi ceux qui sont nés de femme, il n\'en est point paru de plus grand que Jean-Baptiste; toutefois, le plus petit dans le royaume des cieux est plus grand que lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Depuis le temps de Jean-Baptiste jusqu’à présent, le royaume des cieux est forcé, et ce sont les violents qui s\'en emparent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Car tous les Prophètes et la Loi ont prophétisé jusqu’à Jean;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'et, si vous voulez le savoir, c\'est lui qui est l\'Elie qui devait venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Que celui qui a des oreilles pour entendre, entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Mais à qui comparerai-je cette génération? Elle ressemble à des enfants qui sont assis dans les places publiques, et qui apostrophent les autres enfants, et leur disent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, '«Nous vous avons joué de la flûte, et vous n\'avez pas dansé; nous avons chanté des complaintes, et vous ne vous êtes pas frappé la poitrine.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'En effet, Jean est venu, ne mangeant ni ne buvant, et ils disent: «C\'est un possédé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Le Fils de l\'homme est venu mangeant et buvant, et ils disent: «C\'est un mangeur et un buveur, un ami des publicains et des pécheurs»: et pourtant la Sagesse a été justifiée par ses enfants.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alors Jésus se mit à adresser des reproches aux villes où il avait fait la plupart de ses miracles, de ce qu\'elles ne s\'étaient pas repenties.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '«Malheur à toi, Chorazin! malheur à toi, Bethsaïde! car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu\'elles se seraient repenties sous le sac et la cendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Mais, je vous dis qu\'au jour du jugement, Tyr et Sidon seront traitées moins rigoureusement que vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Et toi, Capernaoum, seras-tu élevée jusqu\'au ciel? — Non, tu descendras jusqu\'aux enfers; car si les miracles qui ont eu lieu au milieu de toi avaient été faits dans Sodome, elle subsisterait encore aujourd\'hui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Aussi, je te dis qu\'au jour du jugement Sodome sera traitée moins rigoureusement que toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'En ce temps-là, Jésus prit la parole, et dit: «Je te loue, Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux enfants;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'oui, Père, je te loue de ce que tel a été ton bon plaisir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Toutes choses m\'ont été enseignées par mon Père; et nul ne connaît le Fils que le Père, et nul ne connaît le Père que le Fils, et que celui à qui le Fils le veut bien révéler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Chargez-vous de mon joug et apprenez de moi que je suis doux et humble de coeur; et vous trouverez du repos pour vos âmes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'car mon joug est doux, et mon fardeau, léger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'En ce temps-là, Jésus passait par les blés, le jour du sabbat, et ses disciples, qui avaient faim, se mirent à arracher des épis et à les manger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Les pharisiens, voyant cela, lui dirent: «Tes disciples font une chose qu\'il n\'est pas permis de faire un jour de sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Mais Jésus leur dit: «n’avez-vous pas lu ce que fit David, lorsque lui et ceux qui étaient avec lui eurent faim:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'comment il entra dans la maison de Dieu, et mangea les pains de proposition, ce qu\'il ne lui était pas permis de manger, non plus qu\'à ceux qui l\'accompagnaient, mais aux sacrificateurs seuls.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ou bien n’avez-vous pas lu dans la Loi que, le jour du sabbat, les sacrificateurs profanent le sabbat dans le temple, sans être coupables pour cela.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Or, je vous dis qu\'il y a ici plus que le temple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Si vous saviez ce que signifie cette parole: «Je veux la miséricorde et non le sacrifice,»; vous n\'auriez pas condamné des innocents;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'car le Fils de l\'homme est maître du sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Jésus, ayant quitté ce lieu, entra dans la synagogue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Il s\'y trouvait un homme qui avait la main sèche, et l’on demanda à Jésus s\'il était permis de guérir, le jour du sabbat: c\'était afin de l\'accuser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Jésus leur dit: «Quel est celui d\'entre vous, qui, n\'ayant qu\'une brebis, si elle vient à tomber, un jour de sabbat, dans une fosse, ne la prend et ne l\'en retire?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Combien un homme ne vaut-il pas mieux qu\'une brebis! Ainsi, il est permis de bien faire le jour du sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alors il dit à l\'homme: «Etends la main.» Il retendit, et elle redevint saine comme l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Les pharisiens sortirent et tinrent conseil contre lui, sur les moyens de le faire périr;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'mais Jésus, en ayant eu connaissance, s\'éloigna de ces lieux. Une grande foule le suivit, et il guérit tous leurs malades;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'et il leur commanda sévèrement de ne pas le faire connaître,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'afin que s\'accomplît ce qui a été dit par Ésaïe, le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '«Voici le serviteur que je me suis choisi, le bien-aimé, en qui j\'ai mis toute mon affection. Je lui donnerai mon Esprit, et il annoncera la justice aux nations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Il ne contestera point, il ne criera point, on n\'entendra pas sa voix dans les places publiques;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'il n\'achèvera point de briser le roseau froissé, et il n\'éteindra point le lumignon qui fume encore, jusqu’à ce qu\'il ait fait triompher la justice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Et les nations mettront leur espérance en son nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Alors on lui amena un démoniaque aveugle et sourd-muet, et il le guérit; de sorte que le muet parlait et voyait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Toute la foule était ravie en admiration, et disait: «N\'est-ce point là le Fils de David?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Les pharisiens entendant cette parole, dirent: «Il ne chasse les démons que par Belzébuth, prince des démons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jésus connaissant, leurs pensées, leur dit: «Tout royaume en proie aux divisions se détruit, et toute ville ou maison en proie aux divisions ne subsistera point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Si Satan chasse Satan, il est divisé; comment donc son royaume subsistera-il?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Et si moi, je chasse les démons par Belzébuth, par qui vos fils les chassent-ils? C\'est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mais, si je chasse les démons par l’Esprit de Dieu, le royaume de Dieu est donc venu vers vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Et comment peut-on entrer dans la maison de l\'homme fort et piller ses biens, si l’on n\'a auparavant lié cet homme fort, après quoi on pillera sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Qui n\'est pas avec moi, est contre moi; et qui n\'assemble pas avec moi, disperse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'C\'est pourquoi je vous dis que tout péché et tout blasphème seront pardonnés aux hommes; mais le blasphème contre l\'Esprit ne leur sera point pardonné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'A celui qui aura parlé contre le Fils de l\'homme, on le lui pardonnera; mais à celui qui aura parlé contre le Saint-Esprit, on ne le lui pardonnera ni dans ce temps-ci, ni dans le siècle à venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ou dites que l\'arbre est bon et que son fruit est bon, ou dites que l\'arbre est mauvais et que son fruit est mauvais; car c\'est au fruit qu\'on connaît l\'arbre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Race de vipères, comment pouvez-vous dire de bonnes choses, méchants comme vous l\'êtes? car de l\'abondance du coeur la bouche parle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'L\'homme de bien tire de bonnes choses de son bon trésor, et le méchant tire de mauvaises choses de son mauvais trésor.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Je vous déclare qu\'au jour du jugement les hommes rendront compte de toute parole mauvaise qu\'ils auront dite;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'car par vos paroles vous serez justifiés, et par vos paroles vous serez condamnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Alors des scribes et des pharisiens prirent la parole, et lui dirent: «Maître, nous voudrions te voir faire un miracle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Mais Jésus leur répondit: «Cette génération méchante et adultère, réclame un miracle; eh bien! il ne lui en sera point accordé d\'autre que celui de Jonas, le prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'de même que Jonas passa trois jours et trois nuits dans le ventre d\'un grand poisson, ainsi le Fils de l\'homme passera trois jours et trois nuits dans le sein de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Les Ninivites se lèveront au jour du jugement avec cette génération, et la condamneront; car ils se repentirent à la prédication de Jonas, et il y a ici plus que Jonas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'La reine du Midi se lèvera au jour du jugement avec cette génération, et la condamnera; car elle vint du bout du monde pour entendre la sagesse de Salomon: et il y a ici plus que Salomon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, '«Quand l\'esprit impur est sorti d\'un homme, il va par les lieux arides, cherchant du repos, et il n\'en trouve point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Alors il se dit: «Je vais retourner dans la maison d\'où je suis sorti; il revient et la trouve vacante, balayée et mise en ordre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Alors il va prendre avec lui sept autres esprits plus méchants que lui, puis ils y entrent et s\'y établissent; et la dernière condition de cet homme est pire que la première. Il en sera de même de cette méchante génération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Pendant qu\'il parlait encore à la foule, sa mère et ses frères étaient dehors, qui cherchaient à lui parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'On lui dit: «Ta mère et tes frères sont là dehors, et ils cherchent à te parler.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mais Jésus répondit à celui qui le lui disait: «Qui est ma mère, et qui sont mes frères?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Puis, étendant la main sur ses disciples, il dit: «Voici ma mère et mes frères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'car celui qui fait la volonté de mon Père qui est dans les deux, celui-là est mon frère, et ma soeur, et ma mère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Comme il sortait du temple, un de ses disciples lui dit: «Maître, vois donc, quelles pierres et quelles constructions!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Et Jésus lui dit: «Tu vois ces grandes constructions? Eh bien! il n\'y restera pierre sur pierre qui ne soit renversée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Comme il était assis sur la montagne des Oliviers, en face du temple, Pierre, Jacques, Jean et André lui demandèrent en particulier:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, '«Dis-nous quand ces événements doivent avoir lieu, et quel sera le signe précurseur de leur accomplissement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Jésus se mit à leur dire: «Prenez garde qu\'on ne vous séduise,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'car plusieurs viendront sous mon nom, disant: «C\'est moi qui suis le Messie;» et ils séduiront beaucoup de monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Quand vous entendrez parler de guerres et de bruits de guerre, ne vous alarmez pas; car il faut que cela arrive, mais ce ne sera pas encore la fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Une nation s\'élèvera, en effet, contre une nation, et un royaume contre un royaume; il y aura des tremblements de terre en divers lieux, il y aura des famines et des troubles. Ces calamités sont le commencement des douleurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, '«Prenez garde à vous-mêmes; on vous livrera aux tribunaux et aux synagogues, vous serez battus, et l’on vous traduira devant les gouverneurs et devant les rois, à cause de mon nom, pour rendre témoignage devant eux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'il faut premièrement que l\'évangile soit prêché à toutes les nations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Quand on vous conduira pour vous livrer, ne vous inquiétez pas de ce que vous direz, ne vous préparez même pas, mais dites ce qui vous sera donné au moment même: ce n\'est pas vous qui parlez, c\'est le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Le frère livrera son frère à la mort, et le père, son enfant; les enfants s\'élèveront contre leurs pères et leurs mères, et les mettront à mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'et vous serez haïs de tous à cause de mon nom; mais celui qui persévérera jusqu’à la fin sera sauvé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Or, quand vous verrez l\'abomination cause de la désolation établie là où elle ne doit pas être (que celui qui lit y réfléchisse), alors, que ceux qui sont en Judée s\'enfuient dans les montagnes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'que celui qui est sur le toit, ne descende pas dans la maison, qu\'il n\'entre pas même prendre quoi que ce soit chez lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'et que celui qui est allé dans son champ, ne revienne pas en arrière pour prendre son manteau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Priez pour que cela n\'arrive pas en hiver;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'car il y aura dans ce temps une détresse telle, qu\'il n\'y en a point eu depuis le commencement du monde que Dieu a créé, jusqu’à nos jours, et qu\'il n\'y en aura jamais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Et si le Seigneur n\'avait abrégé ce temps, nul n\'échapperait; mais il l\'a abrégé à cause des élus qu\'il a choisis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, '«Si l\'on vous dit alors: «Le Messie est ici,» ou bien «le Messie est là,» ne le croyez point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'car il s\'élèvera de faux prophètes, qui feront des miracles et des prodiges pour séduire, s\'il était possible, les élus mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Pour vous, prenez garde; vous êtes prévenus de tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, '«Mais en ce temps-là et après cette détresse, le soleil pâlira, la lune refusera sa lumière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'les étoiles tomberont du ciel et les puissances qui sont dans les cieux seront ébranlées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Alors on verra le Fils de l\'homme venir dans les nuées, revêtu d\'une grande puissance et de gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Alors il enverra les anges pour rassembler les élus, des quatre vents, d\'un bout du monde à l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, '«Tirez instruction de la comparaison avec le figuier. Dès que sa branche devient tendre et que les feuilles poussent, on connaît que l\'été est proche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'de même, quand vous verrez ces événements se produire, sachez que le Fils de l\'homme est proche: il est à vos portes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'En vérité, je vous dis que cette génération ne passera point, que tous ces événements n\'arrivent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Quant au jour ou à l\'heure, nul ne les sait, pas même les anges qui sont dans le ciel, ni même le Fils, mais le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, '«Prenez garde, veillez, car vous ne savez quand ce sera le moment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Il en est du Fils de l’homme comme d\'un homme, qui, en quittant sa maison pour aller en voyage, a laissé ses serviteurs maîtres, et qui, en assignant à chacun sa tâche, a enjoint au portier de veiller.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Veillez donc, car vous ne savez quand le maître de la maison doit arriver, si ce sera le soir, ou à minuit, ou au chant du coq, ou le matin;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'craignez qu\'en arrivant tout à coup, il ne vous trouve endormis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Ce que je vous dis, je le dis à tous: Veillez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'le champ, c\'est le monde; la bonne semence, ce sont les fils du royaume; l\'ivraie, ce sont les fils du malin;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'l\'ennemi qui l\'a semée, c\'est le diable: la moisson, c\'est la fin du monde; les moissonneurs, ce sont les anges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Comme donc on arrache l\'ivraie et qu\'on la brûle au feu, ainsi en sera-t-il à la fin du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Le Fils de l\'homme enverra ses anges arracher de son royaume tous les scandales et ceux qui commettent l\'iniquité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'et ils les jetteront dans la fournaise ardente: c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Alors les justes resplendiront comme le soleil dans le royaume de leur Père. Que celui qui a des oreilles pour entendre, entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, '«Le royaume des cieux est encore semblable à un trésor caché dans un champ: un homme l\'ayant découvert, l\'y cache de nouveau, et, dans sa joie, il s\'en va, vend tout ce qu\'il a, et il achète le champ.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, '«Le royaume des cieux est encore semblable à un marchand qui cherche de belles perles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'En ayant trouvé une de grand prix, il alla vendre tout ce qu\'il avait, et il l’acheta.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Le royaume des cieux est encore semblable à un filet qu\'on a jeté dans la mer, et qui ramasse toutes sortes de poissons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Quand il est plein, les pécheurs le tirent sur la grève, puis ils s\'asseyent, mettent ce qu\'il y a de bon dans leurs vaisseaux, et jettent le mauvais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Il en sera de même à la fin du monde: les anges viendront séparer les méchants d\'avec les justes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'et les jetteront dans la fournaise ardente. C\'est là qu\'il y aura des pleurs et des grincements de dents.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, '«Avez-vous compris toutes ces choses?» — «Oui,» lui dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Et Jésus ajouta: «Voilà pourquoi tout scribe versé dans ce qui regarde le royaume des cieux, ressemble à un père de famille qui tire de son trésor des nouveautés et des antiques.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, '- Quand Jésus eut achevé ces paraboles, il quitta ces lieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'et s\'étant rendu dans sa patrie, il enseignait ses concitoyens dans leur synagogue, de sorte qu\'ils étaient frappés d\'étonnement, et disaient: «D\'où lui viennent cette sagesse et ces miracles?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'N\'est-ce pas le fils du charpentier? Sa mère ne s\'appelle-t-elle pas Marie, et ses frères, Jacques, Joseph, Simon et Jude?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Et ses soeurs ne sont-elles pas toutes avec nous? D\'où lui viennent donc cette sagesse et cette puissance?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Et il était pour eux une pierre d\'achoppement. Mais Jésus leur dit: «Ce n\'est que dans son pays et dans sa maison qu\'un prophète n\'est pas honoré.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Et il ne fit pas beaucoup de miracles dans ce lieu à cause de leur incrédulité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'En ce temps-là, Hérode le Tétrarque entendit le bruit qui se faisait autour de Jésus, et il dit à ses serviteurs:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, '«C\'est Jean-Baptiste; il est ressuscité des morts, et c\'est pour cela que la puissance miraculeuse se déploie en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Hérode, en effet, avait fait arrêter Jean, l\'avait chargé de chaînes et mis en prison à cause d\'Hérodiade, femme de son frère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'parce que Jean lui disait: «Il ne t\'est pas permis d\'en faire ta femme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Il voulait le faire mourir, mais il craignait le peuple, parce qu\'on tenait Jean pour un prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Or, à l\'anniversaire de la naissance d\'Hérode, la fille d\'Hérodiade dansa devant les convives et charma Hérode,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'si bien qu\'il lui promit avec serment de lui donner ce qu\'elle demanderait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Poussée par sa mère, elle lui dit: «Donne-moi, ici, dans un bassin, la tête de Jean-Baptiste.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Le Roi en fut fâché; mais à cause de ses serments et de ceux qui étaient à table avec lui, il commanda qu\'on la lui donnât,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'et il envoya décapiter Jean dans la prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'On apporta la tête dans un bassin, et on la donna à la jeune fille, qui la porta à sa mère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Les disciples de Jean vinrent prendre le corps, et l\'ensevelirent, puis ils allèrent informer Jésus de ce qui s\'était passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Jésus ayant appris ce que disait Hérode, entra dans une barque, et se retira à l\'écart, en un lieu solitaire; la foule, l\'ayant su, l\'y suivit à pied, des différentes villes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Lorsqu\'il sortit de la barque, il vit une grande foule; et il en eut pitié, et il guérit leurs malades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Quand le soir fut venu, les disciples s\'approchèrent de Jésus, et lui dirent: «Ce lieu est désert, et l\'heure est déjà avancée; renvoie cette foule de gens, afin qu\'ils aillent dans les villages s\'acheter des vivres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mais Jésus leur dit: «Il n\'est pas nécessaire qu\'ils y aillent; donnez-leur vous-mêmes à manger.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Ils lui répondirent: «Nous n\'avons ici que cinq pains et deux poissons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, '— «Apportez-les-moi ici,» leur dit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Après avoir fait asseoir cette multitude sur l\'herbe, il prit les cinq pains et les deux poissons, et, levant les yeux au ciel, il prononça la bénédiction; puis, ayant rompu les pains, il les donna à ses disciples, et les disciples les donnèrent à la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Tous mangèrent et furent rassasiés; et l\'on emporta douze corbeilles pleines des morceaux qui restaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Le nombre de ceux qui mangèrent se montait à cinq mille hommes environ, sans compter les femmes et les enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Aussitôt après, Jésus pressa ses disciples d\'entrer dans la barque et de. le précéder vers l\'autre rive, pendant qu\'il renverrait la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Quand il l\'eut renvoyée, il monta sur la montagne, pour prier à l\'écart; et, la nuit venue, il était là seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Cependant la barque, qui se trouvait déjà au milieu de la mer, était tourmentée par les vagues, car le vent était contraire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'A la quatrième veille de la nuit, Jésus alla vers ses disciples, en marchant sur la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Eux, le voyant marcher sur la mer, furent bouleversés, et dirent: «C\'est un fantôme;» et ils poussèrent un cri de frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mais aussitôt Jésus leur parla, et leur dit: «Rassurez-vous, c\'est moi; n\'ayez point de peur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Pierre, ayant pris la parole, lui dit: «Seigneur, si c\'est toi, ordonne que j\'aille vers toi en marchant sur les eaux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Jésus lui dit: «Viens.» Et Pierre, étant sorti de la barque, marcha sur les eaux et s\'avança vers Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mais, voyant que le vent était fort, il eut peur, et, comme il commençait à enfoncer, il s\'écria: «Seigneur, sauve-moi!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Aussitôt Jésus étendit la main, le saisit, et lui dit: «Homme de peu de foi, pourquoi as-tu douté?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Ils entrèrent ensuite dans la barque, et le vent cessa.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Ceux qui étaient dans la barque vinrent se prosterner devant Jésus, disant: «Tu es vraiment le Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Lorsqu\'ils eurent achevé leur traversée, ils arrivèrent au pays de Génésareth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Les gens de l\'endroit, ayant reconnu Jésus, envoyèrent annoncer sa présence dans tous les environs, de sorte qu\'on lui amena tous les malades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'On le pria de leur laisser seulement toucher la houppe de son manteau; et tous ceux qui la touchèrent furent guéris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Alors des scribes et des pharisiens venus de Jérusalem s\'approchèrent de Jésus, et lui dirent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '«Pourquoi tes disciples transgressent-ils la tradition des anciens? car ils ne se lavent pas les mains, quand ils prennent leur repas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Il leur répondit: «Et vous, pourquoi transgressez-vous le commandement de Dieu par votre tradition?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Par exemple, Dieu a donné ce commandement: «Honore ton père et ta mère,» et: «Que celui qui maudit son père et sa mère, soit mis à mort;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'mais vous, vous dites: «Celui qui dira à son père ou à sa mère: «Ce dont j\'aurais pu vous assister, j\'en ai fait offrande à Dieu; eh bien! qu\'il n\'honore pas son père et sa mère!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Ainsi vous mettez à néant le commandement de Dieu par votre tradition.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hypocrites, Ésaïe a bien prophétisé sur votre compte, quand il a dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '«Ce peuple m\'honore des lèvres mais son coeur est fort éloigné de moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'C\'est vainement qu\'ils m\'honorent, en donnant des préceptes qui ne sont que des commandements d\'hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Puis, ayant appelé la foule, il lui dit: «Écoutez et comprenez:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ce n\'est pas ce qui entre dans la bouche qui souille l\'homme; c\'est ce qui sort de la bouche: voilà ce qui le ouille.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Alors les disciples s\'approchèrent de lui, et lui dirent: «Sais-tu que les pharisiens ont été scandalisés de la parole qu\'ils viennent d\'entendre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Jésus répondit: «Toute plante que mon Père céleste n\'a pas plantée, sera arrachée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Laissez-les; ce sont des aveugles qui conduisent des aveugles. Si un aveugle en conduit un autre, ils tombent tous deux dans une fosse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Pierre, prenant la parole, lui dit: «Explique-nous cette sentence.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, '— «Vous aussi, dit Jésus, vous êtes encore sans intelligence?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Vous ne comprenez pas que tout ce qui entre dans la bouche, va dans le ventre et se rejette aux lieux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'tandis que ce qui sort de la bouche, vient du coeur: voilà ce qui souille l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Car c\'est du coeur que sortent les mauvaises pensées, les meurtres, le libertinage, les vols, les faux témoignages, les calomnies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'C\'est là ce qui souille l\'homme; mais de manger sans s\'être lavé les mains, cela ne souille pas l\'homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Jésus étant parti de là, se retira dans le territoire de Tyr et de Sidon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Et une Cananéenne qui venait de ces confins, lui dit à haute voix: «Seigneur, Fils de David, aie pitié de moi; ma fille est cruellement tourmentée par un démon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Jésus ne lui répondit pas un mot. Ses disciples s\'approchèrent de lui et le prièrent de la renvoyer: «Car, disaient-ils, elle nous poursuit de ses cris.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Jésus répondit: «Je n\'ai été envoyé qu\'aux brebis perdues de la maison d\'Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Mais cette femme vint se prosterner devant lui en disant: «Seigneur, secours-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Il lui répondit: «Il n\'est pas bien de prendre le pain des enfants pour le jeter aux petits chiens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Elle repartit: «Sans doute, Seigneur, puisque les petits chiens mangent les miettes qui tombent de la table de leurs maîtres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Alors Jésus lui dit: «Femme, ta foi est grande; qu\'il te soit fait comme tu le désires.» Dès cette heure sa fille fut guérie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Jésus, ayant quitté ces lieux, se rendit près de la mer de Galilée. Il monta sur la montagne, et s\'assit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Une grande foule s\'approcha de lui, ayant avec elle des boiteux, des aveugles, des sourds-muets, des estropiés et beaucoup d\'autres malades. Elle les mit aux pieds de Jésus, et il les guérit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'de sorte que la foule était dans l\'admiration en voyant des muets parler, des estropiés être guéris, des boiteux marcher, des aveugles voir; et elle glorifia le Dieu d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jésus, avant appelé ses disciples, leur dit: «J\'ai compassion de cette foule, car voilà déjà trois jours que ces gens restent près de moi, et ils n\'ont pas de quoi manger. Je ne veux pas les renvoyer à jeun, de peur qu\'ils ne défaillent en route.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Sur quoi ses disciples lui dirent: «où trouver en un désert assez de pains, pour nourrir tant de monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Et Jésus leur dit: «Combien avez-vous de pains?» — «Sept, dirent-ils, et quelques petits poissons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Alors il fit asseoir la foule par terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'puis il prit les sept pains et les poissons, et, ayant rendu grâces, il les rompit et les donna à ses disciples, et les disciples les donnèrent à la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Tous mangèrent et furent rassasiés, et l\'on emporta sept corbeilles pleines des morceaux qui restaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Le nombre de ceux qui mangèrent s\'élevait à quatre mille hommes, sans compter les femmes et les enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Après avoir renvoyé la foule, Jésus entra dans la barque et gagna le territoire de Magadan.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Les pharisiens et les sadducéens l\'abordèrent, et, pour le mettre à l\'épreuve, lui demandèrent de leur faire voir un signe qui vînt du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Jésus leur répondit: «Quand le soir est venu, vous dites: «Beau temps! car le ciel est rouge;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'et le matin: «Mauvais temps aujourd\'hui! car le ciel est d\'un rouge sombre.» Vous savez bien discerner l\'aspect du ciel, et vous ne pouvez discerner les signes des temps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Cette génération méchante et adultère réclame un signe, eh bien! il ne lui en sera point accordé d\'autre que celui de Jonas, le prophète.» Là-dessus, il les quitta, et s\'en alla.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Les disciples, en passant à l\'autre bord, avaient oublié de prendre des pains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jésus leur dit: «Gardez-vous du levain des pharisiens et des sadducéens, et faites-y attention.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Les disciples raisonnaient entre eux, et disaient: «C\'est que nous n\'avons pas pris de pains.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jésus s\'en étant aperçu, leur dit: Quelle idée avez-vous, gens de peu de foi? «C\'est que vous n\'avez pas pris de pains!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Vous ne comprenez pas encore, et vous ne vous rappelez pas les cinq pains des cinq mille hommes, et combien de corbeilles vous en avez eues;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'non plus que les sept pains des quatre mille hommes, et combien de corbeilles vous en avez emportées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Comment ne voyez-vous pas que ce n\'est pas de pains que je vous ai parlé? Oui, gardez- vous du levain des pharisiens et des sadducéens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Ils comprirent alors que ce n\'était pas du levain du pain qu\'il avait dit de se garder, mais de l\'enseignement des pharisiens et des sadducéens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Jésus, étant arrivé dans le territoire de Césarée de Philippe, adressa cette question à ses disciples: «Qui dit-on que je suis, moi, le Fils de l\'homme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Ils lui répondirent: «Les uns disent que tu es Jean-Baptiste; les autres, que tu es Elie; d\'autres, Jérémie ou quelqu\'un des prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, '— Et vous, leur dit-il, qui dites-vous que je suis?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon-Pierre répondit: Toi, tu es le Messie, le Fils du Dieu vivant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Jésus reprit, et lui dit: «Tu es heureux, Simon, fils de Jonas, car ce n\'est pas la chair et le sang qui t\'ont révélé cela, mais mon Père qui est dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Et moi, je te dis que tu es Pierre, et que sur cette pierre je bâtirai mon église, et que les portes des enfers ne prévaudront point contre elle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Je te donnerai les clefs du royaume des cieux; ce que tu lieras sur la terre, sera lié dans les cieux, et ce que tu délieras sur la terre, sera délié dans les cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Alors il enjoignit à ses disciples de ne dire à personne qu\'il était le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Dès lors Jésus commença à leur faire connaître qu\'il fallait qu\'il allât à Jérusalem, qu\'il souffrit beaucoup de la part des anciens, des principaux sacrificateurs et des scribes, qu\'il fût mis à mort, et qu\'il ressuscitât le troisième jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Pierre le prenant à part, se mit à le reprendre, disant: «A Dieu ne plaise, Seigneur! Cela ne t\'arrivera pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mais Jésus s’étant retourné, dit à Pierre: «Arrière de moi, Satan, tu m\'es en scandale, car tes sentiments ne sont pas ceux de Dieu, mais ceux des hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Là-dessus, Jésus dit à ses disciples: «Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, qu\'il se charge de sa croix, et qu\'il me suive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Car celui qui veut sauver sa vie, la perdra; mais celui qui perdra sa vie à cause de moi, la retrouvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Que sert-il à un homme de gagner le monde entier, s\'il perd son âme? Ou, que donnera un homme pour recouvrer son âme?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'En effet, le Fils de l\'homme doit venir dans la gloire de son Père, avec ses anges, et alors il rendra à chacun selon ses oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'En vérité, je vous le dis, quelques-uns de ceux qui sont ici présents ne goûteront point la mort, qu\'ils n\'aient vu le Fils de l\'homme venir dans sa royauté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Six jours après, Jésus, ayant pris avec lui Pierre. Jacques et Jean son frère, les mena à l\'écart sur une haute montagne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'et il fut transfiguré devant eux: son visage resplendit comme le soleil, et ses vêtements devinrent blancs comme la lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Tout à coup Moïse et Élie leur apparurent, s\'entretenant avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Pierre, prenant la parole, dit à Jésus: «Seigneur, il est bon que nous soyons ici; si tu le veux, je dresserai ici trois tentes, une pour toi, une pour Moïse, et une pour Elie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Comme il parlait encore, une nuée lumineuse les enveloppa, et il en sortit une voix qui dit: «Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection, écoutez-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Les disciples, entendant cette voix, tombèrent la face contre terre, et furent saisis d\'une vive frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jésus s\'approcha d\'eux, les toucha, et leur dit: «Relevez-vous, et n\'ayez point de peur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Et eux, levant les yeux, ne virent que Jésus seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'En descendant de la montagne, Jésus leur défendit de parler à personne de cette vision, jusqu’à ce que le Fils de l\'homme fût ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Et les disciples lui adressèrent cette question: «Pourquoi donc les scribes disent-ils qu\'Elie doit venir premièrement?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Il répondit: «Elie doit venir, en effet, et rétablir toutes choses;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'mais je vous dis qu\'Elie est déjà venu. Ils ne l\'ont pas reconnu, mais ils lui ont fait tout ce qu\'ils ont voulu. Ils feront souffrir de même le Fils de l\'homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Alors les disciples comprirent qu\'il leur parlait de Jean-Baptiste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Quand ils arrivèrent vers la foule, un homme s\'approcha de Jésus, se jeta à ses genoux, et lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '«Seigneur, aie pitié de mon fils qui est lunatique et très-malade; car souvent il tombe dans le feu, souvent aussi dans l’eau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Je l\'ai amené à tes disciples, et ils n\'ont pu le guérir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jésus répondit: «Race incrédule et perverse, jusqu’à quand serai-je avec vous? Jusqu\'à quand vous supporterai-je?... Amenez-le-moi ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Jésus tança le démon: le démon sortit, et l\'enfant fut guéri sur l\'heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Alors les disciples s\'approchèrent de Jésus, et lui dirent en particulier: «Pourquoi n\'avons-nous pu chasser ce démon?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jésus leur dit: «C\'est à cause de votre manque de foi. En vérité, je vous dis que si vous aviez de la foi gros comme un grain de moutarde, vous diriez à cette montagne: Transporte-toi d\'ici là; et elle s\'y transporterait, et rien ne vous serait impossible.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Cette sorte de démon ne sort que par la prière et par le jeûne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Pendant qu\'ils parcouraient la Galilée, Jésus leur dit: «Le Fils de l\'homme doit être livré entre les mains des hommes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'ils le mettront à mort, mais, le troisième jour, il ressuscitera.» Et ils en furent vivement affligés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Lorsqu\'ils furent de retour à Capernaoum, les percepteurs de la double drachme s\'approchèrent de Pierre, et lui dirent: «Votre maître ne paie-t-il pas la double drachme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, '— «Oui,» dit-il. Quand Pierre entra dans la maison, Jésus le prévint, et lui dit: «Que t\'en semble, Simon? Sur qui les rois de la terre lèvent-ils des impôts ou des contributions? sur leurs fils ou sur les étrangers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, '— «Sur les étrangers,» lui dit-il. — «Ainsi donc, dit Jésus, les fils en sont exempts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Néanmoins, pour ne pas les scandaliser, va-t\'en à la mer, jette l\'hameçon, prends le premier poisson que tu tireras, ouvre-lui la bouche, et tu trouveras un statère. Prends-le. et donne-le-leur pour moi et pour toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'En ce même moment, les disciples s\'adressèrent à Jésus, et lui dirent: «Qui donc est le plus grand dans le royaume des cieux?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Jésus, ayant appelé un petit enfant, le plaça au milieu d\'eux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'et dit: «En vérité, je vous dis que si vous ne changez et ne devenez comme les petits enfants, vous n\'entrerez pas dans le royaume des cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Celui donc qui se rendra humble comme ce petit enfant sera le plus grand dans le royaume des cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, '«Celui qui reçoit un tel enfant en mon nom, me reçoit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mais, si quelqu\'un devait être une occasion de chute pour un seul de ces petits qui croient en moi, il vaudrait mieux pour lui qu\'on lui suspendît au cou une grosse meule de moulin et qu\'on le précipitât au plus profond de la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Malheur au monde à cause des scandales! Il est impossible qu\'il n\'y ait pas de scandales; néanmoins, malheur à l\'homme par qui le scandale arrive!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Si ta main ou ton pied est pour toi une occasion de chute, coupe-les et les jette loin de toi; il te vaut mieux entrer dans la vie, boiteux ou manchot, que d\'avoir deux mains ou deux pieds, et d\'être jeté dans le feu éternel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Et si ton oeil est pour toi une occasion de chute, arrache-le et le jette loin de toi; il te vaut mieux entrer borgne dans la vie, que d\'avoir deux yeux, et d\'être jeté dans la Géhenne ardente.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, '«Prenez garde de mépriser un seul de ces petits, car je vous déclare que leurs anges, dans les cieux, voient continuellement la face de mon Père qui est dans les cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '[Car le fils de l’homme est venu sauver ce qui était perdu.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Que vous en semble? Si un homme a cent brebis, et que l\'une d\'elles s\'égare, ne laisse-t-il pas les quatre-vingt-dix-neuf autres sur les montagnes, pour aller chercher celle qui est égarée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Et, s\'il a le bonheur de la trouver, il en a plus de joie, je vous assure, que des quatre-vingt-dix-neuf autres qui ne se sont point égarées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'De même, c\'est la volonté de votre Père qui est dans les cieux, qu\'il ne se perde pas un seul de ces petits.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, '«Si ton frère t\'a offensé, va, fais-le lui sentir seul à seul: s\'il t\'écoute, tu auras gagné ton frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'S\'il ne t\'écoute pas, prends encore une ou deux personnes avec toi, afin que toute affaire soit décidée sur la déclaration de deux ou trois témoins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'S\'il refuse de les écouter, dis-le à l\'église; et s\'il refuse aussi d\'écouter l\'église, qu\'il soit pour toi comme un païen et un publicain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'En vérité, je vous dis que tout ce que vous lierez sur la terre, sera lié dans le ciel, et que tout ce que vous délierez sur la terre, sera délié dans le ciel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, '«En vérité, je vous dis encore que si deux d\'entre vous s\'accordent sur la terre, pour demander quoi que ce soit, ils obtiendront de mon Père qui est dans les cieux, tout ce qu\'ils auront demandé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'car, où il y a deux ou trois personnes assemblées en mon nom, je suis là au milieu d\'elles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Alors Pierre s\'approcha, et lui dit: «Seigneur, combien de fois pardonnerai-je à mon frère, s\'il m\'offense? Sera-ce jusqu’à sept fois?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jésus lui dit: «Je ne dis pas jusqu’à sept fois, mais jusqu’à septante fois sept fois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, '«C\'est pourquoi le royaume des cieux ressemble à un roi qui voulut régler ses comptes avec ses serviteurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'On lui amena, pour commencer, un homme qui lui devait dix mille talents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Comme il ne pouvait payer, le maître ordonna de le vendre en paiement, lui, sa femme, ses enfants et tout ce qu\'il avait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Ce serviteur se jetant à ses pieds, se tenait prosterné, et lui disait: «Use de patience envers moi, et je te paierai tout.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Le maître de ce serviteur, ému de pitié, le laissa aller, et le tint quitte de sa dette.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mais, en sortant, ce serviteur trouva un de ses compagnons, qui lui devait cent deniers, et, le saisissant à la gorge jusqu’à l\'étrangler, il lui dit: «Paie, puisque tu dois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Son compagnon se jeta à ses pieds, et lui dit en le suppliant: «Use de patience envers moi, et je te paierai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mais l\'autre ne le voulut point, et il le fit jeter en prison, jusqu’à ce qu\'il eût payé ce qu\'il devait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Ses compagnons, témoins de ce qui s\'était passé, en ressentirent un profond chagrin, et allèrent raconter à leur maître tout ce qui s\'était passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Alors le maître, ayant fait venir ce serviteur, lui dit: «Méchant serviteur, je t\'avais remis en entier ta dette, parce que tu m\'en avais supplié;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ne devais-tu pas aussi avoir pitié de ton compagnon, comme j\'ai eu pitié de toi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Et le maître irrité, le livra aux geôliers, jusqu’à ce qu\'il eût payé tout ce qu\'il lui devait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'C\'est ainsi que mon Père céleste vous traitera, si chacun de vous ne pardonne pas à son frère de tout son coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Quand Jésus eut achevé ces discours, il quitta la Galilée, et se rendit aux confins de la Judée, de l\'autre coté du Jourdain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Une grande foule le suivit, et il guérit ceux qui étaient malades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Des pharisiens vinrent vers lui, et lui dirent, pour le mettre à l\'épreuve: «Est-il permis à un homme de répudier sa femme pour quelque motif que ce soit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Jésus répondit: «N\'avez-vous pas lu que celui qui les créa à l\'origine «les fis l’un homme l’autre femme,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'et dit: «Pour cette raison, l\'homme quittera son père et sa mère pour s’attacher à sa femme, et les deux seront une seule chair?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Ainsi ils ne sont plus deux, mais ils sont une seule chair. Que l\'homme donc ne sépare pas ce que Dieu a uni.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Ils lui dirent: «Pourquoi donc Moïse a-t-il prescrit de donner à une femme un acte de divorce, et de la répudier?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Jésus leur dit: «C\'est à cause de la dureté de votre coeur que Moïse vous a autorisés à répudier vos femmes; mais à l\'origine, il n\'en fut pas ainsi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Moi, je vous dis que celui qui répudie sa femme, si ce n\'est pour cause d\'infidélité, et en épouse une autre, commet un adultère, et que celui qui épouse une femme répudiée, commet un adultère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Ses disciples lui dirent: «Si tel est le rapport de l\'homme avec la femme, il vaut mieux ne pas se marier.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Il leur dit: «Les hommes ne sont pas tous capables de tenir ce langage, mais seulement ceux à qui cela a été donné;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'car il y a des eunuques qui sont tels dès le sein de leur mère; il y a aussi des eunuques qui le sont devenus par la main des hommes, et il y en a qui se sont faits eunuques eux-mêmes à cause du royaume des cieux. Que celui qui est capable de cette résolution, la prenne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Alors on lui amena de petits enfants, afin qu\'il leur imposât les mains, et qu\'il priât pour eux. Les disciples reprenaient ces gens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'mais Jésus dit: «Laissez ces petits enfants, et ne les empêchez pas de venir vers moi, car le royaume des cieux est à ceux qui leur ressemblent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Puis, après leur avoir imposé les mains, il continua sa route.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Un homme aborda Jésus, et lui dit: «Maître, quel bien dois-je faire pour avoir la vie éternelle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Jésus lui dit: Pourquoi me demandes-tu, à moi, le bien que tu doit faire? Un seul est le Bon. Si tu veux entrer dans la vie, garde les commandements.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, '— «Lesquels?» lui dit cet homme.— «C\'est, répondit Jésus, «tu ne tueras point: tu ne commettras point adultère; tu ne déroberas point; tu ne porteras point de faux témoignage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honore ton père et ta mère.» et «tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Le jeune homme répondit: «J\'ai gardé tous ces commandements; que me manque-t-il encore?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jésus lui dit: «Si tu veux être parfait, va, vends ce que tu as et le donne aux pauvres, et tu auras un trésor dans le ciel; puis viens, et suis-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Le jeune homme, ayant entendu cette parole, s\'en alla tout triste, car il avait de grands biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jésus dit à ses disciples: «En vérité, je vous dis qu\'il est difficile à un riche d\'entrer dans le royaume des cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Je vous le dis encore, il est plus aisé qu\'un chameau passe par le trou d\'une aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Les disciples vivement frappés de cette parole, disaient: «Qui peut donc être sauvé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jésus arrêtant son regard sur eux, dit: «Cela est impossible aux hommes, mais toutes choses sont possibles à Dieu,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Alors Pierre prenant la parole, dit: «Pour nous, tu le vois, nous avons tout quitté pour te suivre; qu\'avons-nous donc à attendre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jésus leur dit: «En vérité, je vous le dis, lors de la Renaissance, quand le Fils de l\'homme sera assis sur son trône glorieux, vous qui m\'avez suivi, vous serez aussi assis sur douze trônes, pour juger les douze tribus d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Celui qui aura quitté pour mon nom ses maisons, ou ses frères, ou ses soeurs, ou son père, ou sa mère, ou ses enfants, ou ses terres, en recevra beaucoup plus, et il héritera la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Bien des derniers seront les premiers, et bien des premiers seront les derniers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '«En effet, le royaume des cieux est semblable à un chef de famille, qui sortit dès le matin, afin de louer des ouvriers pour sa vigne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Il fit accord avec eux à raison d\'un denier par jour, et les envoya à sa vigne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Il sortit vers la troisième heure, et ayant vu d\'autres ouvriers qui étaient sur la place, sans rien faire,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'il leur dit: «Allez, vous aussi à ma vigne, et je vous donnerai ce qui sera raisonnable;» et ils y allèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Il sortit encore vers la sixième heure et vers la neuvième, et fit de même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Etant sorti vers la onzième heure, il en trouva d\'autres qui se tenaient sur la place, et leur dit: «Pourquoi vous tenez-vous ici toute la journée, sans rien faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, '— «C\'est que personne, lui dirent-ils, ne nous a loués.» Et il leur dit: «Allez, vous aussi, à ma vigne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Quand le soir fut venu, le maître de la vigne dit à son intendant: «Appelle les ouvriers, et leur donne leur salaire, en allant des derniers aux premiers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Les ouvriers loués à la onzième heure vinrent, et reçurent chacun un denier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Puis vinrent les premiers, qui croyaient recevoir davantage, et ils reçurent, eux aussi, un denier chacun.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'En le touchant, ils murmuraient contre le maître, et disaient:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, '«Ces derniers n\'ont fait qu\'une heure, et tu les mets sur le même pied que nous, qui avons supporté la fatigue et l\'ardeur brûlante du jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Mais le maître, prenant la parole, dit à l\'un d\'eux: «Mon ami, je ne te fais point de tort: n\'es-tu pas convenu d\'un denier avec moi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Prends ce qui te revient, et t\'en va. Pour moi, je veux donner à ce dernier autant qu\'à toi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ne suis-je pas libre de faire ce que je veux de mon bien? ou vois-tu de mauvais oeil que je sois bon?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Ainsi les derniers seront les premiers, et les premiers seront les derniers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Comme Jésus montait à Jérusalem, il prit à part les douze disciples, en chemin, et leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '«Voici que nous montons à Jérusalem, et le Fils de l\'homme sera livré aux principaux sacrificateurs et aux scribes: ils le condamneront à mort');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'et le livreront aux Gentils, pour le bafouer, le flageller et le crucifier; mais, le troisième jour, il ressuscitera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Alors la mère des fils de Zébédée s\'approcha de lui avec ses fils, et se prosterna pour lui faire une demande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Jésus lui dit: «Que veux-tu?» — «Ordonne, dit-elle, que mes deux fils que voici, soient assis, l\'un à ta droite, l\'autre à ta gauche, dans ton royaume.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jésus répondit: «Vous ne savez ce que vous demandez. Pouvez-vous boire le calice que je dois boire?» — «Nous le pouvons,» dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Et Jésus répondit: «Oui, vous boirez mon calice; quant à être assis à ma droite et à ma gauche, il ne m\'appartient pas de l\'accorder: cette distinction sera pour ceux à qui mon Père l\'a réservée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Les dix autres disciples, ayant entendu cette demande, furent irrités contre les deux frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Jésus les appela, et leur dit: «Vous savez que les princes des nations les maîtrisent, et que les grands les dominent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Il n\'en sera point ainsi parmi vous; mais que celui qui aspire à être grand parmi vous, soit votre serviteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'et que celui qui veut être le premier parmi vous, soit votre esclave.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'C\'est ainsi que le Fils de l\'homme est venu, non pour être servi, mais pour servir et donner sa vie pour la rançon de beaucoup.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Comme ils sortaient de Jéricho, une grande foule suivit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Deux aveugles assis au bord de la route, entendant dire que Jésus passait, se mirent à crier: «Aie pitié de nous, Seigneur, Fils de David.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'La foule les reprenait pour les faire taire; mais ils criaient plus fort: «Aie pitié de nous, Seigneur, Fils de David.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Jésus s\'arrêta, les appela, et leur dit: «Que voulez-vous que je vous fasse?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Ils lui dirent: «Seigneur, que nous recouvrions la vue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jésus, ému de compassion, leur toucha les yeux: et aussitôt ils recouvrèrent la vue et le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Lorsqu\'ils approchèrent de Jérusalem et qu\'ils eurent atteint Bethphagé, vers le mont des Oliviers. Jésus envoya deux disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'en leur disant: «Allez à ce village qui est en face de vous, et, en entrant, vous trouverez une ânesse attachée, et un ânon avec elle; détachez-les et amenez-les-moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Si l’on vous dit quelque chose, vous direz que le Seigneur en a besoin, et on les enverra tout de suite.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Cela arriva, afin que s\'accomplît la parole du prophète:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '«Dites à ta fille de Sion: Voici ton roi qui vient à toi; il est clément, et monté sur ânesse et sur un ânon, le petit d\'une bête de somme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Les disciples partirent, et firent comme Jésus le leur avait commandé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Ils amenèrent l’ânesse et l’ânon, mirent leurs manteaux sur ces animaux, et Jésus s\'assit dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'La plupart des gens étendaient leurs manteaux sur la route, tandis que d\'autres coupaient des rameaux aux arbres, et en jonchaient le chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'La foule qui allait devant, et celle qui suivait, criaient: «Hosanna au Fils de David! Béni soit celui qui vient au nom du Seigneur! Hosanna dans les lieux très-hauts!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Et quand il entra dans Jérusalem, toute la ville fut en émoi. On disait: «Qui est-ce?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Et la foule répondait: «C\'est Jésus, le prophète de Nazareth en Galilée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Jésus entra dans le temple de Dieu; il chassa tous ceux qui vendaient et qui achetaient dans le temple; il renversa les tables des changeurs et les bancs des vendeurs de pigeons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'et leur dit: «Il est écrit: «Ma maison sera appelée une maison de prière,» mais vous, vous en faites «une caverne de voleurs»,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Des aveugles et des boiteux vinrent le trouver dans le temple, et il les guérit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Les principaux sacrificateurs et les scribes voyant les merveilles qu\'il avait faites, et les enfants qui criaient dans le temple: «Hosanna au Fils de David!» s\'en indignèrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'et lui dirent: «Tu entends ce qu\'ils disent?» — «Oui, leur dit Jésus; n\'avez-vous jamais lu cette parole: «Tu as tiré des louanges de la bouche des petits enfants et de ceux qui sont à la mamelle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Et il les laissa là, et sortit de la ville pour se rendre à Béthanie, où il passa la nuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Le matin, en revenant à la ville, il eut faim,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'et ayant vu un figuier sur la route, il y monta; et n\'y trouvant que des feuilles, il lui dit: «Que jamais fruit ne naisse de toi: à l\'instant le figuier sécha.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'A cette vue, les disciples étonnés, dirent: «Comment ce figuier a-t-il séché tout à coup?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jésus leur répondit: «En vérité, je vous dis que si vous aviez de la foi et que vous ne doutiez point, non-seulement vous feriez ce qui a été fait à ce figuier, mais encore quand vous diriez à cette montagne: «Va te jeter à la mer,» cela se ferait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Tout ce que vous demanderez avec foi, dans votre prière, vous l\'obtiendrez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Lorsque Jésus fut entré dans le temple, les principaux sacrificateurs et les anciens du peuple le vinrent trouver pendant qu\'il enseignait, et lui dirent: «De quel droit fais-tu ces choses. et qui t\'a donné ce droit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jésus leur répondit: «Je vous ferai aussi une question, et, si vous y répondez, je vous dirai de quel droit je fais ces choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Le baptême de Jean, d\'où venait-il? du ciel ou des hommes?» Mais ils firent entre eux cette réflexion: Si nous disons «du ciel,» il nous dira: «Pourquoi donc n\'y avez-vous pas cru?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'et si nous disons «des hommes,» nous avons lieu de craindre le peuple, car tout le monde tient Jean pour un prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Ils répondirent à Jésus: «Nous ne savons.» Jésus leur dit aussi: «Moi non plus, je ne vous dirai pas de quel droit je fais ces choses.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, '«Mais, que vous semble-t-il de ceci? Un homme avait deux fils, et, s\'adressant au premier, il lui dit: «Mon enfant, va aujourd\'hui travailler à la vigne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Celui-ci répondit: «Non, je ne veux pas.» Mais ensuite il se repentit, et y alla.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Le père s\'adressa à l\'autre, et lui parla de la même manière. Celui-ci répondit: «J\'y vais, seigneur;» et il n\'y alla point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Lequel des deux a fait la volonté de son père?» — «C\'est le premier,» dirent-ils. Jésus ajouta: «En vérité, je vous dis que les publicains et les femmes de mauvaise vie vous devancent dans le royaume de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'car Jean est venu à vous en toute droiture, et vous ne l\'avez pas cru, tandis que les publicains et les femmes de mauvaise vie ont ajouté foi à sa parole; et ensuite, quand bien même vous en avez été témoins, vous ne vous êtes pas repentis et vous n\'avez point cru.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '«Ecoutez une autre parabole: «Il y avait un chef de famille qui avait planté une vigne; il l\'avait entourée d\'une haie, y avait creusé un pressoir, bâti une tour; puis, il la donna à cultiver à des vignerons, et quitta le pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Quand vint le temps des vendanges, il envoya ses serviteurs pour recevoir sa récolte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'mais les vignerons, ayant pris ses serviteurs, battirent l\'un, tuèrent l\'autre, et en lapidèrent un troisième.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Le maître en envoya d\'autres en plus grand nombre que les premiers, et ils les traitèrent de même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Enfin il leur envoya son fils, se disant: «Ils respecteront mon fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mais, quand les vignerons virent le fils, ils se dirent entre eux: «C\'est l\'héritier; venez, tuons-le, et gardons son héritage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Là-dessus, ils le prirent, le jetèrent hors de la vigne et le tuèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Eh bien! quand le maître de la vigne viendra, que fera-t-il à ces vignerons?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Ils dirent à Jésus: «Il fera périr misérablement ces misérables, et remettra la vigne à d\'autres vignerons, qui lui donneront le produit en la saison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jésus leur dit: «N\'avez-vous jamais lu dans les Ecritures cette parole: «La pierre, que les constructeurs avaient mise au rebut, est devenue la pierre angulaire. C\'est par la volonté du Seigneur qu\'elle l’est devenue, et elle est une merveille à nos yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'C\'est pourquoi je vous dis que le royaume de Dieu vous sera ôté, et qu\'il sera donné à une nation qui en produira les fruits.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, '[et celui qui tombera sur cette pierre, s\'y brisera, et elle écrasera celui sur qui elle tombera.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'En entendant les paraboles de Jésus, les principaux sacrificateurs et les pharisiens comprirent que c\'était d\'eux qu\'il parlait,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'et, quoiqu\'ils eussent le désir de se saisir de lui, la crainte du peuple les retint, parce qu\'on tenait Jésus pour un prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Jésus, prenant la parole, leur parla de nouveau en paraboles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '«Le royaume des cieux, dit-il, est semblable à un roi qui célébrait les noces de son fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Il envoya ses serviteurs appeler ceux qui avaient été invités aux noces, mais ils ne voulurent point venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Il envoya d\'autres serviteurs avec ordre de dire aux conviés: «J\'ai préparé mon festin; mes boeufs et mes bêtes grasses sont tués, et tout est prêt: venez aux noces.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mais ils ne s\'en soucièrent point, et s\'en allèrent, celui-ci à son champ, celui-là à son commerce;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'et les autres se saisirent de ses serviteurs, les insultèrent et les tuèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Le roi irrité envoya ses armées, fit périr ces meurtriers, et brûla leur ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Alors il dit à ses serviteurs: «Le festin des noces est prêt, mais les conviés n\'en étaient pas dignes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Allez donc dans les carrefours, et invitez aux noces tous ceux que vous trouverez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Et ces serviteurs se répandirent dans les chemins, amenèrent tous ceux qu\'ils trouvèrent, méchants et bons, et la salle des noces fut remplie de convives.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Le roi, étant entré pour voir les convives, aperçut à table un homme qui n\'avait pas mis d\'habit de noces,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'et il lui dit: «Mon ami, comment es-tu venu ici, sans avoir un habit de noces?» Et cet homme resta bouche close.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Alors le roi dit à ceux qui servaient: «Liez-lui les pieds et les mains, emportez-le, et le jetez dans les ténèbres de dehors.» C\'est là qu\'il y aura des pleurs et des grincements de dents;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'car il y a beaucoup d\'appelés, mais peu d\'élus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Alors les pharisiens, s\'étant retirés, tinrent conseil pour amener Jésus à se compromettre par quelque parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'et ils envoyèrent leurs disciples avec les hérodiens, pour lui dire: «Maître, nous savons que tu es vrai, et que tu enseignes en toute vérité la voie de Dieu, sans te soucier de qui que ce soit, car tu ne fais pas acception de personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Donne-nous donc ton avis. Est-il permis, ou non, de payer le tribut à César?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Mais Jésus connaissant leur perfidie, leur dit: «Hypocrites, pourquoi essayez-vous de me surprendre?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Montrez-moi la monnaie avec laquelle on paie le tribut.» Ils lui présentèrent un denier;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'et Jésus leur dit: «De qui est cette effigie et cette légende?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, '— «De César,» répondirent-ils. Alors il leur dit: «Rendez donc à César ce qui est à César, et à Dieu ce qui est à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Surpris de cette réponse, ils le quittèrent, et s\'en allèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Le même jour, des sadducéens, gens qui prétendent qu\'il n\'y a point de résurrection, vinrent vers Jésus, et lui posèrent cette question:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '«Maître, Moïse a dit que si un homme meurt sans enfants, son frère, en sa qualité de beau-frère, épousera sa veuve, et suscitera lignée à son frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Or, il y avait chez nous sept frères: le premier se maria, et mourut; et, comme il n\'avait pas d\'enfants, il laissa, sa femme à son frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Il en fut de même du second, du troisième et des autres, jusqu\'au septième.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Après eux tous, la femme mourut aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Duquel des sept frères sera-t-elle donc la femme dans la résurrection, car tous l\'ont eue pour femme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jésus leur répondit: «Vous êtes dans l\'erreur, parce que vous ne connaissez ni les Ecritures, ni même la puissance de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'car dans la résurrection on ne se marie point, hommes et tommes sont comme les anges de Dieu dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Quant à la résurrection des morts, n\'avez-vous pas lu ce que Dieu vous a dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Je suis le Dieu d’Abraham, le Dieu d’Isaac et le Dieu de Jacob? Dieu n\'est pas Dieu des morts, mais Dieu des vivants.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Et la foule qui l\'entendait, était frappée de son enseignement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Les pharisiens ayant appris que Jésus avait fermé la bouche aux sadducéens, se rassemblèrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'et l\'un d\'eux, qui était docteur de la Loi, posa à Jésus cette question, pour voir ce qu\'il répondrait:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '«Maître, quel est, dans la Loi, le plus grand commandement?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jésus lui dit: «Tu aimeras le Seigneur ton Dieu de tout ton coeur, de toute ton âme et de toute ta pensée;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'voilà le premier et le plus grand commandement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'et en voici un second qui lui est semblable: «Tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'De ces deux commandements dépendent toute la Loi et les Prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Comme les pharisiens se trouvaient réunis, Jésus leur adressa cette question:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '«Que pensez-vous du Messie? de qui est-il fils?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, '— «De David,» répondirent-ils. Jésus leur dit: «Comment donc David, animé de l\'Esprit, l\'appelle-t-il «Seigneur,» quand il dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '«Le Seigneur a dit à mon Seigneur: «Assieds-toi à ma droite, jusqu’à ce que j\'aie mis tes ennemis sous tes pieds?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Si donc David l\'appelle «Seigneur,» comment est-il son fils?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Personne ne put lui répondre un mot, et même, depuis ce jour, personne n\'osa plus lui poser de questions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Alors Jésus s\'adressant à la foule et à ses disciples, parla ainsi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, '«Les scribes et les pharisiens sont assis dans la chaire de Moïse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Faites donc, et observez tout ce qu\'ils vous disent; mais ne faites pas comme ils font, car ils disent et ne font pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Ils lient de lourds et accablants fardeaux, dont ils chargent les épaules des hommes, mais, pour eux, ils ne veulent pas les remuer du doigt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, '«Tout ce qu\'ils font, ils le font pour être remarqués des hommes: ils portent de larges phylactères et de grosses houppes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'ils aiment la première place dans les repas, les premiers sièges dans les synagogues,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'et les salutations dans les places publiques; ils se complaisent à être appelés par les hommes, Rabbi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Pour vous, ne vous faites pas appeler Rabbi, car vous n\'avez qu\'un seul Maître, et vous, vous êtes tous frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'N\'appelez personne sur la terre votre Père, car vous n\'avez qu\'un seul Père, celui qui est dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Ne vous faites pas appeler Directeurs, car vous n\'avez qu\'un seul Directeur, le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Le plus grand parmi vous sera votre serviteur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Quiconque s\'élève, sera abaissé; et quiconque s\'abaisse, sera élevé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, '«Malheur à vous, scribes et pharisiens hypocrites, parce que vous fermez aux hommes le royaume des cieux! Vous n\'y entrez point vous-mêmes, et vous ne laissez point entrer ceux qui veulent y entrer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '[«Malheur à vous, scribes et pharisiens hypocrites, parce que vous dévorez les maisons des veuves, sous prétexte de vos longues prières; c\'est pourquoi vous serez jugés d\'autant plus sévèrement.»]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Malheur à vous, scribes et pharisiens hypocrites, parce que vous courez la mer et la terre pour faire un prosélyte, et, quand il l\'est devenu, vous en faites un homme digne de la Géhenne deux fois plus que vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, '«Malheur à vous, conducteurs aveugles, qui dites: «Si l\'on jure par le sanctuaire, ce n\'est rien; mais si l’on jure par l\'or du sanctuaire, cela oblige!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Insensés et aveugles! lequel est le plus grand, de l\'or ou du sanctuaire qui a rendu l\'or sacré?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Vous dites encore: «Si l’on jure par l\'autel, ce n\'est rien; mais si l’on jure par l\'offrande qui est dessus, cela oblige.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Aveugles! lequel est le plus grand, de l\'offrande ou de l\'autel qui rend l\'offrande sacrée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Celui qui jure par l\'autel, jure par l\'autel et par tout ce qui est dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Celui qui jure par le sanctuaire, jure par le sanctuaire et par celui qui en a fait sa demeure;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'et celui qui jure par le ciel, jure par le trône de Dieu et par celui qui y est assis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, '«Malheur à vous, scribes et pharisiens hypocrites, parce que vous payez la dîme de la menthe, de l\'aneth et du cumin, et que vous laissez les devoirs plus importants que commande la Loi, savoir, la justice, la miséricorde et la bonne foi! Il fallait remplir ceux-ci, sans toutefois négliger ceux-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Conducteurs aveugles qui coulez le moucheron et qui avalez le chameau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, '«Malheur à vous, scribes et pharisiens hypocrites! parce que vous nettoyez le dehors de la coupe et du plat, tandis qu\'au dedans ils sont pleins de rapine et d\'intempérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Pharisien aveugle, nettoie d\'abord le dedans de la coupe, afin que le dehors aussi soit net.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, '«Malheur à vous, scribes et pharisiens hypocrites! parce que vous ressemblez à des sépulcres blanchis, qui paraissent beaux au dehors, mais qui, au dedans, sont pleins d\'ossements de morts et de toute sorte de pourriture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Vous, de même, à l’extérieur vous paraissez justes aux hommes, mais, à l\'intérieur, vous êtes remplis d\'hypocrisie et de corruption.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, '«Malheur à vous, scribes et pharisiens hypocrites! parce que vous bâtissez les tombeaux des prophètes et que vous ornez les sépulcres des justes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'et que vous dites: «Si nous avions vécu du temps de nos pères, nous n\'aurions pas pris part avec eux au meurtre des prophètes;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'de sorte que vous vous rendez le témoignage que vous êtes bien les fils de ces tueurs de prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Comblez donc la mesure de vos pères!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpents, race de vipères, comment échapperez-vous au châtiment de la Géhenne?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'C\'est pourquoi, je vais vous envoyer des prophètes, des sages et des scribes: vous tuerez et vous crucifierez les uns, vous en flagellerez d\'autres dans vos synagogues, et vous les poursuivrez de ville en ville,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'afin que tout le sang innocent versé sur la terre retombe sur vous, depuis le sang d\'Abel le juste jusqu\'au sang de Zacharie, fils de Barachie, que vous avez tué entre le sanctuaire et l\'autel:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'en vérité, je vous le dis. tous ces châtiments fondront sur cette génération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jérusalem, Jérusalem, toi qui tues les prophètes et qui lapides ceux qui te sont envoyés, que de fois j\'ai voulu rassembler tes enfants, comme une poule rassemble ses poussins sous ses ailes, et vous ne l\'avez pas voulu!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Voici, votre maison vous est laissée solitaire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'car je vous dis que vous ne me verrez plus désormais, jusqu’à ce que vous disiez: «Béni soit celui qui vient au nom du Seigneur!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Jésus sortit du temple et s\'éloigna. Ses disciples s\'approchèrent de lui, pour lui en faire remarquer les constructions;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'mais il leur répondit: «Vous voyez tous ces bâtiments? En vérité, je vous dis qu\'il n\'y restera pierre sur pierre qui ne soit renversée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Comme il était assis sur la montagne des Oliviers, ses disciples vinrent lui dire en particulier: «Dis-nous quand cela doit avoir lieu, et quel sera le signe de ton avènement et de la fin du monde?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Jésus leur répondit: «Prenez garde qu\'on ne vous séduise,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'car plusieurs viendront sous mon nom, disant: «C\'est moi qui suis le Messie;» et ils séduiront beaucoup de monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Vous entendrez parler de guerres et de bruits de guerre; gardez-vous de vous en alarmer, car il faut que toutes ces choses arrivent; mais ce ne sera pas encore la fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Une nation s\'élèvera, en effet, contre une nation, et un royaume contre un royaume, et il y aura des famines et des tremblements de terre en divers lieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Toutes ces calamités sont le commencement des douleurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alors on cherchera à vous écraser, on vous mettra à mort, et vous serez haïs de toutes les nations à cause de mon nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Dans ces circonstances, beaucoup trébucheront; ils se trahiront et se haïront les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Plusieurs faux prophètes s\'élèveront et séduiront bien des gens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'et la charité du plus grand nombre se refroidira à cause des progrès croissants de l\'iniquité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'mais celui qui persévérera jusqu’à la fin, sera sauvé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Et cette bonne nouvelle du royaume sera publiée dans le monde entier, en témoignage à toutes les nations. Alors viendra la fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Quand donc vous verrez, établie dans le lieu saint, l\'abomination cause de la désolation, dont parle le prophète Daniel (que celui qui lit y réfléchisse),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'alors, que ceux qui sont en Judée, s\'enfuient dans les montagnes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'que celui qui est sur le toit ne descende pas prendre ce qu\'il a dans sa maison,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'et que celui qui est dans son champ ne revienne pas en arrière, pour prendre son manteau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ce temps-là!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Priez pour que votre fuite n\'arrive pas en hiver, ni un jour de sabbat;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'car il y aura alors une grande détresse, une détresse telle qu\'il n\'y en a point eu depuis le commencement du monde jusqu’à nos jours, et qu\'il n\'y en aura jamais;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'et si ce temps n\'était abrégé, nul n\'échapperait; mais il sera abrégé à cause des élus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Si l\'on vous dit alors, «le Messie est ici,» ou bien «le Messie est là,» ne le croyez point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'car il s\'élèvera de faux Messies et de faux prophètes, qui feront de grands miracles et des prodiges, au point de séduire, s\'il était possible, les élus eux-mêmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'vous voilà prévenus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Si donc l\'on vous dit, «il est dans tel désert,» n\'y allez point; «il est dans tel et tel appartement,» n\'en croyez rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Car de même que l\'éclair part de l\'orient et brille jusqu\'en occident, ainsi sera l\'avènement du Fils de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Partout où sera le corps mort, les vautours s\'y rassembleront.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Aussitôt après ces temps de détresse, le soleil pâlira, la lune refusera sa lumière, les étoiles tomberont du ciel et les puissances des cieux seront ébranlées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Alors paraîtra dans le ciel le signe du Fils de l\'homme, et tous les peuples de la terre se frapperont la poitrine, et ils verront le Fils de l\'homme qui viendra sur les nuées du ciel, revêtu d\'une grande puissance et d\'une grande gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Il enverra ses anges, qui, au son éclatant de la trompette, rassembleront ses élus des quatre vents, d\'un bout du monde à l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Tirez instruction de la comparaison avec le figuier. Quand sa branche devient tendre et que les feuilles poussent, vous connaissez que l\'été est proche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'de même, quand vous verrez tous ces événements, sachez que le Fils de l\'homme est proche: il est à vos portes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'En vérité, je vous dis que cette génération ne passera point, que tous ces événements n\'arrivent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Quant au jour et à l\'heure, nul ne les sait, pas même les anges du ciel, mais mon Père seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Ce qui se passa au temps de Noé, se passera également à l\'avènement du Fils de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Dans les temps qui précédèrent le déluge, on mangeait et l\'on buvait, on se mariait et l\'on donnait en mariage, jusqu\'au jour où Noé entra dans l\'arche,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'et l\'on ne se douta de rien, jusqu’à ce que vint le déluge, qui emporta tous les hommes: il en sera de même à l’avènement du Fils de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Alors, de deux hommes qui seront dans un champ, l\'un sera pris, l\'autre laissé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'de deux femmes qui moudront à la meule, l\'une sera prise, l\'autre laissée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Veillez donc, puisque vous ne savez quel jour votre Seigneur doit venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Apprenez que si le maître de la maison savait à quelle heure de la nuit les voleurs doivent venir, il veillerait et ne laisserait pas forcer sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Vous donc aussi, tenez-vous prêts, car le Fils de l\'homme viendra à l\'heure où vous n\'y penserez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Quel est le serviteur fidèle et sensé que son maître a mis à la tête de ses gens, pour leur distribuer la nourriture quand il est temps?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Heureux ce serviteur que le maître, à son arrivée, trouvera agissant de la sorte!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'En vérité, je vous dis qu\'il lui donnera l\'administration de tous ses biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mais, si c\'est un méchant serviteur, qui dise en lui-même, «mon maître tarde à venir,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'qui se mette à battre ses camarades, et qui mange et boive avec les ivrognes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'son maître viendra le jour où il ne s\'y attend pas et à l\'heure qu\'il ne sait pas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'il le coupera en deux, et lui assignera son lot avec les hypocrites: c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Alors le royaume des cieux sera semblable à dix vierges, qui prirent leurs lampes et allèrent au-devant de l’époux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Il y en avait cinq qui étaient folles, et cinq qui étaient sages.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Celles qui étaient folles ne prirent point d\'huile avec elles en prenant leurs lampes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'tandis que les sages prirent de l\'huile dans des vases avec leurs lampes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Comme l’époux tardait à venir, elles s\'assoupirent toutes et s\'endormirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Au milieu de la nuit, un cri se fit entendre: «Voici l\'époux! Allez au-devant de lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Alors toutes ces vierges s\'éveillèrent et arrangèrent leurs lampes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Les folles dirent aux sages: «Donnez-nous de votre huile, car nos lampes s\'éteignent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mais les sages leur répondirent: «Non pas; il n\'y en aurait point assez pour nous et pour vous. Allez plutôt vers ceux qui en vendent, et achetez-en pour vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Pendant qu\'elles étaient allées en acheter, l\'époux vint; celles qui étaient prêtes entrèrent avec lui dans la salle des noces, et la porte fut fermée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Plus tard, les autres vierges vinrent, et dirent: «Seigneur, Seigneur, ouvre-nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mais il répondit: «Je vous dis en vérité que je ne vous connais pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Veillez donc, car vous ne savez ni le jour, ni l\'heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'En effet, le royaume des cieux est semblable à un homme, qui, partant pour un voyage, appela ses serviteurs et leur remit ses biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Il donna à l\'un cinq talents, à l\'autre deux, et un au troisième, à chacun selon sa capacité, et il partit aussitôt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Le maître parti, celui qui avait cinq talents trafiqua avec cette somme, et gagna cinq autres talents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'De même, celui qui en avait reçu deux en gagna aussi deux autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mais celui qui n\'en avait reçu qu\'un, alla faire un creux en terre et y cacha l\'argent de son maître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Longtemps après, le maître de ces serviteurs vint, et compta avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Celui qui avait reçu cinq talents, s\'étant approché, présenta les cinq autres talents, et dit: «Seigneur, tu m\'avais remis cinq talents, en voici cinq autres que j\'ai gagnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Son maître lui dit: «C\'est bien, bon et fidèle serviteur, tu as été fidèle en peu, je te mettrai à la tête d\'affaires plus considérables: entre dans la joie de ton maître.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Celui qui avait reçu deux talents, s\'étant aussi approché, dit: «Seigneur, tu m\'avais remis deux talents, en voici deux autres que j\'ai gagnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Son maître lui dit: «C\'est bien, bon et fidèle serviteur, tu as été fidèle en peu, je te mettrai à la tête d\'affaires plus considérables: entre dans la joie de ton maître.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Celui qui n\'avait reçu qu\'un talent, s\'approcha à son tour, et dit: «Seigneur, je savais que tu es un homme dur, que tu moissonnes là où tu n\'as pas semé, et que tu recueilles là où tu n\'as pas jeté de semence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'et, dans ma crainte, je suis allé cacher ton talent dans la terre. Tiens, le voici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Mais son maître lui répondit: «Méchant et paresseux serviteur, tu savais que je moissonne là où je n\'ai point semé, et que je recueille là où je n\'ai point jeté de semence!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'il te fallait donc porter mon argent aux banquiers, et, à mon retour, j\'aurais retiré ce qui m\'appartient avec l\'intérêt.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Otez-lui donc ce talent, et donnez-le à celui qui en a dix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Car on donnera à celui qui a, et il sera dans l\'abondance; quant à celui qui n\'a pas, on lui ôtera même ce qu\'il a.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Jetez ce serviteur, qui n\'est bon à rien, dans les ténèbres de dehors: c\'est là qu\'il y aura des pleurs et des grincements de dents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Quand le Fils de l\'homme viendra dans sa gloire, et tous les anges avec lui, il s\'assiéra sur son trône glorieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'et toutes les nations seront assemblées devant lui. Il séparera les uns d\'avec les autres, comme le berger sépare les brebis d\'avec les boucs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'et il mettra les brebis à sa droite et les boucs à sa gauche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Alors le roi dira à eaux qui sont à sa droite: «Venez, vous les bénis de mon Père, prenez possession du royaume qui vous a été préparé dès la fondation du monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'car j\'ai eu faim, et vous m\'avez donné à manger; j\'ai eu soif, et vous m\'avez donné à boire; j\'étais étranger, et vous m\'avez recueilli;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'j\'étais nu, et vous m\'avez vêtu; j\'étais malade, et vous m\'avez visité; j\'étais en prison, et vous m\'êtes venus voir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Alors les justes lui répondront: «Seigneur, quand est-ce que nous t\'avons vu avoir faim, et que nous t\'avons donné à manger; ou avoir soif, et que nous t\'avons donné à boire?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Quand t\'avons-nous vu étranger, et t\'avons-nous recueilli; ou nu, et t\'avons-nous vêtu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Quand t\'avons-nous vu malade ou en prison, et sommes-nous allés te voir?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Et le roi leur répondra, et leur dira: «En vérité, je vous le dis, toutes les fois que vous l\'avez fait à l’un de ces plus petits de mes frères, vous me l\'avez fait à moi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Ensuite il dira à ceux qui sont à sa gauche: «Retirez-vous de moi, maudits, allez dans le feu éternel qui a été préparé pour le diable et pour ses anges:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'car j\'ai eu faim, et vous ne m\'avez pas donné à manger: j\'ai eu soif, et vous ne m\'avez pas donné à boire:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'j\'étais étranger, et vous ne m\'avez pas logé; j\'étais nu, et vous ne m\'avez pas vêtu; j\'étais malade et en prison, et vous ne m\'avez pas visité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Alors ils répondront, eux aussi: «Seigneur, quand est-ce que nous t\'avons vu avoir faim ou soif, ou être étranger, ou nu, ou malade, ou en prison, et que nous ne t\'avons pas assisté?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Il leur répondra: «En vérité, je vous le dis, toutes les fois que vous ne l\'avez pas fait à l\'un de ces plus petits, c\'est à moi-même que vous ne l\'avez pas fait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Et ceux-ci s\'en iront aux peines éternelles, et les justes à la vie éternelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Lorsque Jésus eut achevé tous ces discours, il dit à ses disciples:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '«Vous savez que la Pâque se fait dans deux jours, et que le Fils de l\'homme sera livré pour être crucifié.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Alors les principaux sacrificateurs et les anciens du peuple s\'assemblèrent dans le palais du souverain sacrificateur appelé Caïphe;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'et ils tinrent conseil pour arrêter Jésus par ruse et le mettre à mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, '«Mais, disaient-ils, il ne faut pas que ce soit pendant la fête, de peur qu\'il n\'y ait du tumulte parmi le peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Comme Jésus était à Béthanie, dans la maison de Simon le lépreux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'une femme s\'approcha de lui, avec un flacon d\'albâtre contenant un parfum de grand prix, et elle le lui versa sur la tête, pendant qu\'il était à table.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Les disciples, voyant cela, en témoignèrent leur mécontentement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'et dirent: «A quoi bon cette perte? On aurait pu vendre ce parfum très cher, et en donner le prix aux pauvres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Jésus, s\'en étant aperçu, leur dit: «Pourquoi faites-vous de la peine à cette femme? car elle a fait une bonne action à mon égard.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Vous aurez toujours des pauvres avec vous, mais vous ne m\'aurez pas toujours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'En répandant ce parfum sur mon corps, elle l\'a fait pour ma sépulture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'En vérité, je vous dis que partout où cet évangile sera prêché, dans le monde entier, ce qu\'elle a fait sera aussi raconté en mémoire d\'elle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Alors l\'un des Douze, qui s\'appelait Judas Iscarïot, alla trouver les principaux sacrificateurs, et leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, '«Que voulez-vous me donner, et je vous le livrerai?» Ils lui comptèrent trente pièces d\'argent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Depuis ce moment, Judas cherchait une occasion favorable pour livrer Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Le premier jour des pains sans levain, les disciples dirent à Jésus: «où veux-tu que nous te préparions le repas de la Pâque?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Il leur dit: «Allez à la ville chez un tel, et dites-lui: «Le Maître te fait dire, mon temps est pioche: c\'est chez toi que je veux faire la Pâque avec mes disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Les disciples firent ce que Jésus leur avait commandé, et ils préparèrent la Pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Le soir étant venu, Jésus se mit à table avec ses douze disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'et pendant le repas, il dit: «En vérité, je vous dis que l\'un de vous me livrera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Ils en furent extrêmement affligés, et chacun se mit à lui dire: «Est-ce moi, Seigneur?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Il répondit: «Celui qui a mangé au même plat que moi, oui, cet homme-là me livrera!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Le Fils de l\'homme s\'en va selon ce qui est écrit de lui; mais malheur à l\'homme par qui le Fils de l\'homme est livré! Mieux vaudrait pour cet homme-là n\'être point né.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Judas, qui le livrait, prit la parole et dit: «Rabbi, est-ce moi?» — «C\'est toi-même,» lui repartit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Pendant le repas, Jésus prit le pain, et, après avoir prononcé la bénédiction, il le rompit, et le donna à ses disciples en disant: «Prenez, mangez, ceci est mon corps.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Puis, il prit une coupe, et, ayant rendu grâces, il la leur donna en disant: «Buvez-en tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'car ceci est mon sang, le sang de l\'alliance, qui sera répandu pour beaucoup de gens, en vue du pardon des péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Je vous dis que désormais je ne boirai plus de ce fruit de la vigne, jusqu\'au jour où j\'en boirai du nouveau avec vous dans le royaume de mon Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Puis ils chantèrent les cantiques, et s\'en allèrent à la montagne des Oliviers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Alors Jésus leur dit: «Je serai pour vous tous, cette nuit, une occasion de chute; car il est écrit: - Je frapperai le berger, et les brebis du troupeau seront dispersées.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mais, après que je serai ressuscité, je vous précéderai en Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Pierre prit la parole, et lui dit: «Quand tu serais pour tous une occasion de chute, tu ne le seras jamais pour moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jésus lui répondit: «En vérité, je te dis que, cette nuit même, avant que le coq chante, tu me renieras trois fois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pierre lui dit: «Quand je devrais mourir avec toi, non, je ne te renierai point.» Et tous les disciples protestèrent de même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Jésus arriva avec eux dans un lieu appelé Gethsémané, et leur dit: «Asseyez-vous ici, pendant que j\'irai là pour prier.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Il prit avec lui Pierre et les deux fils de Zébédée, et commença à être fort triste et fort angoissé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Il leur dit alors: «Mon âme est saisie d\'une tristesse mortelle; restez ici et veillez avec moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Puis, ayant fait quelques pas en avant, il tomba la face contre terre, et pria, disant: «Mon Père, s\'il est possible, que ce calice passe loin de moi; toutefois que ta volonté soit faite, et non pas la mienne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Ensuite il vint vers ses disciples, et les trouvant endormis, il dit à Pierre: «Ainsi, vous n\'avez pu veiller une heure avec moi!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Veillez et priez, de peur que vous ne tombiez en tentation: l\'esprit est plein d\'ardeur, mais la chair est faible.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Il s\'éloigna de nouveau, pour la seconde fois, et pria, disant: «Mon Père, si ce calice ne peut passer sans que je le boive, que ta volonté soit faite.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Puis il revint et les trouva endormis; car leurs yeux étaient appesantis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Il les laissa, et, s\'en étant allé, il pria de nouveau, pour la troisième fois, en répétant la même parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Alors il vint vers ses disciples, et leur dit: «C\'est trop dormir et vous reposer. L\'heure approche; le Fils de l\'homme va être livré entre les mains des pécheurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levez-vous, allons! voici celui qui me livre est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Il parlait encore, quand Judas, l\'un des Douze, arriva, et avec lui une troupe nombreuse, année d\'épées et de bâtons, qui avait été envoyée par les principaux sacrificateurs et par les anciens du peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Le traître leur donna ce signe «Celui que je baiserai, leur dit-il, c\'est lui; saisissez-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Et aussitôt, s\'approchant de Jésus, il lui dit: «Salut, Rabbi,» et il le baisa.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jésus lui dit: «Mon ami, pourquoi es-tu ici?» Alors ces gens s\'avancèrent, mirent la main sur Jésus et l\'arrêtèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Tout à coup un de ceux qui étaient avec Jésus, mettant l\'épée à la main, frappa le serviteur du souverain sacrificateur et lui emporta l\'oreille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Jésus lui dit alors: «Remets ton épée à sa place: tous ceux qui se serviront de l\'épée, périront par l\'épée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Crois-tu que je ne puisse pas sur l\'heure prier mon Père, qui me donnerait plus de douze légions d\'anges?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Comment donc s\'accompliraient les Ecritures, d\'après lesquelles il en doit être ainsi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'En même temps Jésus dit à cette troupe: «Vous êtes venus me prendre avec des épées et des bâtons, comme si vous poursuiviez un brigand. Tous les jours j\'étais assis dans le temple, y enseignant, et vous ne m\'avez pas arrêté;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'mais tout cela est arrivé, afin que les écrits des prophètes s\'accomplissent.» Alors tous ses disciples l\'abandonnèrent et s\'enfuirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Ceux qui avaient arrêté Jésus, l\'emmenèrent chez le souverain sacrificateur Caïphe, où les scribes et les anciens s\'étaient réunis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Pierre le suivit de loin, jusqu\'au palais du souverain sacrificateur; il y entra, et s\'assit avec les agents, pour voir comment cela finirait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Les principaux sacrificateurs et tout le sanhédrin cherchaient quelque fausse déposition contre Jésus, afin de le mettre à mort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'et, quoique plusieurs faux témoins se fussent présentés, ils n\'en trouvèrent point qui fût suffisante. Enfin, il vint deux faux témoins qui dirent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Il a dit: «Je puis détruire le temple de Dieu, et le rebâtir en trois jours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Alors le souverain sacrificateur se leva, et dit à Jésus: «Ne réponds-tu rien? Qu\'est-ce que ces gens déposent contre toi?» Mais Jésus garda le silence.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Le souverain sacrificateur reprit: «Je t\'adjure par le Dieu vivant de nous dire si tu es le Messie, le Fils de Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jésus lui répondit: Tu l’as dit: et même je vous déclare que désormais vous verrez le Fils de l\'homme siéger à la droite du Tout-Puissant, et venir sur les nuées du ciel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Alors le souverain sacrificateur déchira ses vêtements, disant: «Il a blasphémé: qu’avons-nous encore besoin de témoins? Vous venez d\'entendre son blasphème:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'que vous en semble?» Les sénateurs répondirent: Il mérite la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Alors ils lui crachèrent au visage et lui donnèrent des coups de poing; quelques-uns le souffletèrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'disant: «Messie, devine qui t\'a frappé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Cependant Pierre était assis dehors, dans la cour, et une servante l\'aborda, et lui dit: «Toi aussi, tu étais avec Jésus, le galiléen.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mais il le nia devant tout le monde, disant: «Je ne sais ce que tu veux dire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Comme il se dirigeait vers le porche, pour s\'en aller, une autre servante le vit, et dit aux gens qui étaient là: «Celui-là aussi était avec Jésus de Nazareth.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Et Pierre le nia encore une fois, jurant qu\'il ne connaissait pas cet homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Un instant après, ceux qui étaient là, s\'étant approchés, dirent à Pierre: «Certainement, toi aussi, tu es des leurs; on le reconnaît bien à ton langage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Alors il se mit à faire des imprécations et à jurer qu\'il ne connaissait point cet homme. Aussitôt un coq chanta;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'et Pierre se souvint de la parole que Jésus lui avait dite: «Avant que le coq chante, tu me renieras trois fois.» Et étant sorti du palais, il pleura amèrement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'De grand matin, tous les principaux sacrificateurs et les anciens du peuple tinrent conseil pour faire exécuter Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Après l\'avoir lié, ils remmenèrent et le livrèrent à Ponce-Pilate, qui était gouverneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Alors Judas, qui l\'avait livré, voyant que Jésus était condamné, se repentit, et alla rendre les trente pièces d\'argent aux principaux sacrificateurs et aux anciens,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'disant: «J\'ai péché en livrant le sang innocent.» Mais ils lui dirent: «Que nous importe? cela te regarde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Là-dessus, Judas jeta les pièces d\'argent dans le temple, se retira, et alla se pendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Les principaux sacrificateurs, ayant ramassé l\'argent, dirent: «Il n\'est pas permis de le mettre dans le trésor, puisque c\'est le prix du sang;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'et, après en avoir délibéré, ils achetèrent avec cet argent le champ du Potier pour la sépulture des étrangers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'C\'est pourquoi ce champ est appelé encore aujourd\'hui le Champ du Sang.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Alors s\'accomplit ce qui avait été dit par le prophète Jérémie: «Et ils ont reçu les trente pièces d’argent, prix de celui qui avait été mis à prix et qu’ils avaient taxé de la part des enfants d\'Israël,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'et ils les ont données pour le champ du Potier comme le Seigneur me l’avait commandé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Cependant Jésus comparut devant le gouverneur, qui l’interrogea, disant: «C\'est toi, qui es le roi des Juifs?» — «Tu le dis,» lui répondit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Quand les principaux sacrificateurs et les anciens l\'accusaient, il ne répondait rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Alors Pilate lui dit: «N\'entends-tu pas de combien de crimes ils te chargent?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Et Jésus ne répondit pas même sur un seul point, ce qui étonna fort le gouverneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'C\'était la coutume, à chaque fête, que le gouverneur relâchât un prisonnier, celui que le peuple voulait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Or, on détenait alors un prisonnier fameux, nommé Barrabas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Pilate, ayant fait assembler la multitude, lui dit: «Lequel voulez-vous que je vous relâche? Barrabas, ou Jésus, qu\'on appelle Christ?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Car il savait que c\'était par envie que les sénateurs l\'avaient livré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'D\'ailleurs, pendant qu\'il siégeait sur son tribunal, sa femme lui avait fait dire: «Ne te mêle pas de l\'affaire de ce juste, car j\'ai eu, aujourd\'hui, des rêves affreux à cause de lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Mais les principaux sacrificateurs et les anciens persuadèrent au peuple de demander Barrabas, et de faire périr Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Le gouverneur, prenant la parole, leur dit: «Lequel des deux voulez-vous que je vous relâche?» — Barrabas,» dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilate reprit: «Que ferai-je donc de Jésus, qu\'on appelle Christ?» Ils dirent tous: «Qu\'il soit crucifié!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, '— «Quel mal a-t-il donc fait?» dit le gouverneur. Mais ils crièrent encore plus fort: «Qu\'il soit crucifié!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Pilate voyant que son insistance ne servait à rien, mais que le tumulte allait croissant, prit de l\'eau, se lava les mains à la vue du peuple, et dit: «Je suis innocent du sang de ce juste: cela vous regarde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Et tout le peuple répondit: «Que son sang soit sur nous et sur nos enfants!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Alors il leur relâcha Barrabas; et, après avoir fait flageller Jésus, il le livra pour être crucifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Alors les soldats du gouverneur emmenèrent Jésus dans le prétoire et assemblèrent autour de lui toute la cohorte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Ils le dépouillèrent de ses vêtements et l\'affublèrent d\'un manteau écarlate;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'puis, ils tressèrent une couronne d\'épines, qu\'ils lui mirent sur la tête; ils lui mirent aussi un roseau dans la main droite. Ils se prosternaient devant lui, et lui disaient par dérision: «Salut, roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Puis, ils crachaient sur lui, et, prenant le roseau, ils le frappaient sur la tête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Quand ils l\'eurent ainsi bafoué, ils lui ôtèrent le manteau, lui remirent ses vêtements, et l\'emmenèrent pour le crucifier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'En sortant de la ville, ils trouvèrent un homme de Cyrène, nommé Simon, qu\'ils mirent en réquisition pour porter la croix de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Quand ils furent arrivés à la place appelée Golgotha, c’est-à-dire, la place du Crâne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'ils lui présentèrent du vin mêlé de fiel, et Jésus, l\'ayant goûté, ne le voulut point boire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Après qu\'ils l\'eurent crucifié, ils se partagèrent ses vêtements en les tirant au sort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'puis ils s\'assirent pour le garder.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Ils placèrent au-dessus de sa tête cet écriteau indiquant le sujet de sa condamnation: «Jésus, Roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'On crucifia avec lui deux brigands, l\'un à sa droite, l\'autre à sa gauche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Et les passants l\'insultaient en branlant la tête,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'et en disant: «Toi, qui détruis le temple, et qui le rebâtis en trois jours, sauve-toi toi-même. Si tu es Fils de Dieu, descends de ta croix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Les principaux sacrificateurs aussi le poursuivaient de leurs sarcasmes, ainsi que les scribes et les anciens, et disaient:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '«Il en a sauvé d\'autres, et il ne peut se sauver lui-même! Il est le roi d\'Israël! Qu\'il descende maintenant de la croix, et nous croirons en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Il s\'est confié en Dieu; que Dieu le délivre maintenant, s\'il l\'aime; car il a dit: «Je suis Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Et les brigands qui étaient crucifiés avec lui, l\'insultaient de la même manière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Depuis la sixième beure jusqu’à la neuvième, des ténèbres se répandirent sur toute la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Vers la neuvième heure, Jésus cria d\'une voix forte: «Eli, Eli, lama sabactani» c\'est-à-dire, mon Dieu, mon Dieu, pourquoi m\'as-tu abandonné?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Quelques-uns des assistants, l\'ayant entendu, dirent: «Voilà qu\'il appelle Elie;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'et aussitôt l\'un d\'eux courut prendre une éponge, qu\'il trempa dans du vinaigre, et, l\'ayant ajustée à une tige, il lui donna à boire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Mais les autres disaient: «Laisse, voyons si Élie viendra le sauver.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Mais Jésus poussa de nouveau un grand cri et rendit l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'A ce moment le voile du temple se déchira en deux, depuis le haut jusqu\'en bas; la terre trembla; les rochers se fendirent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'les sépulcres s\'ouvrirent, et plusieurs saints, dont les corps y étaient couchés, ressuscitèrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'et, étant sortis de leurs sépulcres, ils vinrent après la résurrection de Jésus, dans la ville sainte, et apparurent à un grand nombre de personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Le centurion et ceux qui étaient avec lui pour garder Jésus, voyant le tremblement de terre et ce qui venait de se passer, furent saisis d\'une grande terreur, et dirent: «Assurément, cet homme était Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Il y avait là plusieurs femmes qui regardaient de loin; elles avaient accompagné Jésus depuis la Galilée, pour le servir;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'c’étaient entre autres Marie Madeleine, Marie, mère de Jacques et de Joses, et la mère des fils de Zébédée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Sur le soir, il vint un homme riche d\'Arimathée, nommé Joseph, qui était lui-même disciple de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Cet homme s\'était rendu auprès de Pilate, pour lui demander le corps de Jésus, et Pilate avait ordonné qu\'on le lui remît.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Joseph prit le corps, l\'enveloppa d\'un linceul blanc,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'et le déposa dans un sépulcre neuf, qu\'il avait fait tailler dans le roc pour lui-même; puis il roula une grosse pierre à l\'entrée du sépulcre, et s\'en alla.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Marie Madeleine et l\'autre Marie étaient là, assises en face du tombeau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Le lendemain, c’est-à-dire, le jour qui suivait la préparation, les principaux sacrificateurs et les pharisiens se rendirent ensemble auprès de Pilate,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'et lui dirent: «Seigneur, nous nous sommes rappelés que, lorsqu\'il vivait encore, cet imposteur a dit: «Après trois jours je ressusciterai»,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'donne donc l\'ordre qu\'on s\'assure du tombeau jusqu\'au troisième jour, de peur que ses disciples ne viennent dérober le corps, et ne disent au peuple: «Il est ressuscité des morts;» cette dernière imposture serait pire que la première».');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilate leur dit: Une garde est à vos ordres; allez, assurez-vous du tombeau comme vous l\'entendrez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Ils allèrent s\'assurer du tombeau à l\'aide de la garde, après avoir scellé la pierre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Après le sabbat, à l\'aube du premier jour de la semaine, Marie Madeleine et l\'autre Marie allèrent visiter le tombeau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Tout à coup un tremblement de terre se fit sentir, car un ange du Seigneur descendit du ciel, s\'approcha, roula la pierre, et s\'assit dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Son visage était brillant comme l\'éclair, et son vêtement, blanc comme la neige.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Ceux qui faisaient la garde, furent bouleversés et comme morts de la peur qu\'il leur causa.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mais l\'ange, prenant la parole, dit aux femmes: «Pour vous, n\'ayez point de peur; je sais que vous cherchez Jésus qui a été crucifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Il n\'est point ici; il est ressuscité, comme il l\'avait dit. Venez, voyez le lieu où il gisait,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'et hâtez-vous d\'aller dire à ses disciples qu\'il est ressuscité des morts. Il vous précède en Galilée, c\'est là que vous le verrez: vous voilà prévenues.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Elles se hâtèrent de sortir du sépulcre, et coururent, pleines de crainte et de joie, porter la nouvelle aux disciples de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Tout à coup Jésus vint au-devant d\'elles, et leur dit: «Salut.» Les femmes s\'approchèrent pour embrasser ses pieds, et se prosternèrent devant lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Alors Jésus leur dit: «N\'ayez point de peur; allez dire à mes frères de se rendre en Galilée: c\'est là qu\'ils me verront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Pendant qu\'elles étaient en chemin, quelques hommes de la garde vinrent à la ville rapporter aux principaux sacrificateurs tout ce qui s\'était passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Ceux-ci, réunis aux anciens, tinrent conseil, et dirent aux soldats, en leur donnant une forte somme d\'argent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, '«Dites que ses disciples sont venus de nuit, et qu\'ils l\'ont enlevé pendant que vous dormiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Et si cela vient à la connaissance du gouverneur, nous lui parlerons, et nous vous tirerons de peine.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Les soldats prirent l\'argent et firent ce qu\'on leur avait suggéré; et ce bruit a couru chez les Juifs jusqu\'à ce jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Les onze disciples se rendirent en Galilée, sur la montagne où Jésus leur avait ordonné de se rendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Quand ils le virent, ils se prosternèrent; mais quelques-uns eurent des doutes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Jésus s\'approcha d\'eux, leur adressa la parole, et leur dit: «Tout pouvoir m\'a été donné au ciel et sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Allez, instruisez toutes les nations, baptisez-les au nom du Père, du Fils et du Saint-Esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'leur enseignant à garder tout ce que je vous ai commandé; pour moi, je suis tous les jours avec vous jusqu’à la fin du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Commencement de l\'Evangile de Jésus-Christ, Fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Selon ce qui est écrit dans Esaïe, le prophète, «voici j\'envoie devant toi mon messager pour te préparer le chemin;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'C\'est une voie qui crie au désert: «Préparez le chemin du Seigneur faites-lui des sentiers droits,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jean parut, baptisant au désert, et prêchant le baptême de repentance pour le pardon des péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Toutes les campagnes de la Judée et tous les habitants de Jérusalem se rendaient vers lui, et se faisaient baptiser par lui dans le fleuve du Jourdain, confessant leurs péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Jean avait un vêtement de poil de chameau, et une ceinture de cuir autour des reins; il mangeait des sauterelles et du miel sauvage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Il prêchait, disant: «Il vient après moi, celui qui est plus puissant que moi, et je ne suis pas digne de délier, en me baissant, la courroie de ses sandales.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Pour moi, je vous ai baptisés d\'eau, mais il vous baptisera d\'esprit saint.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'En ce temps-là, Jésus vint de Nazareth ville de Galilée, et il fut baptisé par Jean dans le Jourdain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Au moment où il sortait de l\'eau, il vit les cieux s\'entr\'ouvrir, et l\'Esprit, comme une colombe, descendre sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Et une voix sortit des cieux, disant: «Tu es mon Fils bien-aimé; c\'est en toi que j\'ai mis toute mon affection.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Aussitôt après, Jésus fut poussé par l\'Esprit au désert,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'et il y passa quarante jours, tenté par Satan. Il était avec les bêtes sauvages, et les anges le servaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Après que Jean eut été mis en prison, Jésus se rendit en Galilée, prêchant l\'évangile de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'et disant: «Le temps est venu, et le royaume de Dieu est proche. Repentez- vous, et croyez à la bonne nouvelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Comme il passait le long de la mer de Galilée, il vit Simon et André, frère de Simon, qui péchaient au filet dans la mer, car ils étaient pêcheurs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'et Jésus leur dit: «Venez, suivez-moi, et je vous ferai pêcheurs d\'hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Aussitôt ils quittèrent leurs filets, et le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Étant allé un peu plus loin, il vit Jacques, fils de Zébédée, et Jean, son frère, qui raccommodaient leurs filets dans leur barque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Il les appela aussitôt; et eux, laissant Zébédée, leur père, dans la barque avec les ouvriers, le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Ils se rendirent à Capernaoum. Dès le sabbat, Jésus entra dans la synagogue, et y enseigna.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Et l\'on était frappé de son enseignement; car il enseignait avec autorité, et non comme les scribes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Dès que Jésus eut parlé, un homme qui avait un esprit impur, et qui se trouvait dans la synagogue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 's\'écria: «Qu\'y a-t-il entre nous et toi, Jésus de Nazareth? Tu es venu nous faire périr. Je te connais, tu es le Saint de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Jésus le tança. «Tais-toi, lui dit-il, et sors de cet homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Et l\'esprit impur, ayant jeté cet homme dans des convulsions, sortit en poussant un grand cri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Tous les assistants furent dans la stupéfaction, de sorte qu\'ils discutaient entre eux, et disaient: «Qu\'est-ce donc? Un enseignement nouveau! Il commande avec autorité même aux esprits impurs, et ils lui obéissent!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Et sa renommée se répandit aussitôt de tous côtés, dans tous les lieux qui avoisinent la Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'En sortant de la synagogue, ils allèrent avec Jacques et Jean dans la maison de Simon et d\'André.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'La belle-mère de Simon était couchée, ayant la fièvre. Aussitôt on parla d\'elle à Jésus:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'il s\'approcha, et la saisissant par la main, il la fit lever. A l\'instant la fièvre la quitta, et elle les servit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Le soir, quand le soleil fut couché, on amena à Jésus tous ceux qui étaient malades, ainsi que les démoniaques;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'et toute la ville se pressait à sa porte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Il guérit un grand nombre de malades atteints de divers maux, et il chassa beaucoup de démons. Il imposait silence aux démons, parce qu\'ils le connaissaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Le lendemain matin, s’étant levé bien avant le jour, il sortit, alla dans un lieu solitaire, et il y pria.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon et ceux qui étaient ordinairement avec lui, se mirent à sa recherche,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'et l\'ayant trouvé, ils lui dirent: «Tout le monde te cherche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Il leur répondit: «Allons ailleurs, dans les bourgades qui sont plus loin, afin que j\'y prêche aussi, car c\'est dans ce but que je suis sorti.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Et il allait par toute la Galilée, prêchant dans les synagogues et chassant les démons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Un lépreux vint vers lui, pour lui adresser une prière; il se jeta à ses pieds, et lui dit: «Si tu le veux, tu peux me rendre net.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Jésus, ému de compassion, avança la main, le toucha et lui dit: «Je le veux, sois net.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'A peine eut-il parlé, que la lèpre quitta cet homme, et il devint net.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Jésus le renvoya sur-le-champ, en lui disant d\'un ton sévère:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, '«Garde-toi d\'en rien dire à personne; mais, va, montre-toi au sacrificateur, et offre pour ta guérison, ce que Moïse a ordonné pour l\'attester au peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Cet homme s\'en étant allé, se mit à publier et à répandre partout la nouvelle, de sorte que Jésus ne pouvait plus entrer publiquement dans une ville, mais il se tenait en dehors, dans des lieux solitaires; et l’on venait vers lui de toutes parts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Après une absence de quelques jours, Jésus rentra à Capernaoum. Aussitôt qu\'on sut qu\'il était de retour chez lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'il se fit un tel attroupement, que la place même qui est devant sa porte ne suffisait plus. Jésus leur annonça la Parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Il vint des gens qui lui amenèrent un paralytique porté par quatre hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Comme ils ne pouvaient arriver jusqu’à lui, à cause de la foule, ils découvrirent le toit à l\'endroit où était Jésus, et par cette ouverture, ils descendirent le lit sur lequel le paralytique était couché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Jésus voyant leur foi, dit au paralytique: «Mon enfant, tes péchés sont pardonnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Or il y avait là, assis, des scribes qui se disaient en eux-mêmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '«Pourquoi cet homme profère-t-il ainsi des blasphèmes? Qui peut pardonner les péchés, que Dieu seul?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Jésus, ayant immédiatement connu, par son esprit, quelles étaient leurs pensées, leur dit: «Pourquoi avez-vous ces pensées dans vos coeurs?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Lequel est le plus aisé, de dire au paralytique: Tes péchés sont pardonnés, ou de dire: Lève-toi, prends ton lit et marche?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Or, afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '«Je te le commande, dit-il au paralytique, lève-toi, prends ton lit et t\'en va dans ta maison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'A l\'instant, le paralytique se leva, prit son lit, et sortit en présence de tout le monde, de sorte qu\'ils étaient tous stupéfaits, et glorifiaient Dieu, disant: «Nous n\'avons jamais rien vu de pareil.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Jésus sortit de nouveau pour aller au bord de la mer: tout le peuple venait vers lui, et il l\'enseignait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'En passant, il vit Lévi, fils d\'Alphée, qui était assis au bureau des péages, et il lui dit: Suis-moi. Celui-ci se leva et le suivit. e');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Jésus était à table dans sa maison, et plusieurs publicains et gens de mauvaise vie — car il y en avait beaucoup à Capernaoum, et ils suivaient. Jésus — se trouvaient à table avec lui et avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Les scribes et les pharisiens le voyant manger avec, des publicains et des gens de mauvaise vie, dirent à ses disciples: «Comment se fait-il qu\'il mange et boive avec les gens de mauvaise vie et les publicains?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Jésus, les ayant entendus, leur dit: «Ce ne sont pas les bien portants qui ont besoin de médecin, mais ceux qui se portent mal: je ne suis pas venu appeler les justes, mais les pécheurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Les disciples de Jean et les pharisiens qui jeûnaient, vinrent vers Jésus, et lui dirent: «Pourquoi les disciples de Jean et ceux des pharisiens jeûnent-ils, tandis que tes disciples ne jeûnent point?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Et Jésus leur dit: «Les amis de l\'époux peuvent-ils jeûner pendant que l\'époux est avec eux? Tant qu\'ils ont l\'époux avec eux, ils ne peuvent jeûner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Le temps viendra où l’époux leur sera ôté; et ils jeûneront en ce jour-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'On ne coud pas une pièce de drap neuf à un vieux habit; autrement, la pièce de drap neuf mise au vieux habit en emporte un morceau, et il se fait une déchirure pire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Et l\'on ne met pas du vin nouveau dans de vieilles outres; autrement, le vin fait rompre les outres, et le vin est perdu, ainsi que les outres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Un jour de sabbat, Jésus passait par les blés, et, chemin faisant, ses disciples se mirent à arracher des épis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Les pharisiens lui dirent: «Vois donc! pourquoi font-ils ce qui n\'est pas permis le jour du sabbat?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Et Jésus leur dit: «N\'avez-vous jamais lu ce que fit David dans le besoin où il se trouva, lorsqu\'il eut faim, lui et ceux qui étaient avec lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'comment il entra dans la maison de Dieu, du temps du souverain sacrificateur Abiathar, et mangea les pains de proposition, que les sacrificateurs seuls ont le droit de manger, et en donna même à ceux qui l\'accompagnaient?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Le sabbat, ajouta Jésus, a été fait pour l\'homme, non l\'homme pour le sabbat,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'de sorte que le Fils de l\'homme est maître même du sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Il entra de nouveau dans la synagogue de Capernaoum. Il s\'y trouvait un homme qui avait la main sèche,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'et l\'on observait Jésus, pour voir s\'il le guérirait le jour du sabbat, afin de l\'accuser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Jésus dit à l\'homme qui avait la main sèche: «Lève-toi, et mets-toi là au milieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Puis il leur dit: «Est-il permis, le jour du sabbat, de faire bien ou de faire mal, de sauver la vie ou de l\'ôter?» Mais ils gardèrent le silence.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Alors, promenant ses regards sur eux avec indignation, affligé qu\'il était de l\'aveuglement de leurs coeurs, il dit à cet homme: «Étends la main.» Il retendit, et sa main fut guérie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Aussitôt les pharisiens sortirent et tinrent conseil contre lui avec les hérodiens, sur les moyens de le faire périr.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Jésus se retira avec ses disciples vers la mer, et il fut suivi d\'une grande foule venue de la Galilée, ainsi que de la Judée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'de Jérusalem, de l\'Idumée et de delà le Jourdain. Les gens des environs de Tyr et de Sidon, ayant entendu parler de tout ce qu\'il faisait, vinrent aussi vers lui en grand nombre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Il ordonna à ses disciples de tenir toujours un bateau à sa disposition, pour que la foule ne l\'accablât pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'car, par suite des nombreuses guérisons qu\'il avait faites, tous ceux qui avaient des infirmités se jetaient sur lui pour le toucher;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'et, quand les esprits impurs le voyaient, ils se précipitaient à ses pieds, et s\'écriaient: «Tu es le Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Jésus leur recommandait fort sévèrement de ne pas le faire connaître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Ensuite, étant monté sur la montagne, il appela ceux qu\'il lui plut; et ils vinrent vers lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Il en désigna douze pour être avec lui, et pour les envoyer prêcher');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'avec le pouvoir de chasser les démons:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'ce furent Simon, à qui il donna le nom de Pierre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Jacques fils de Zébédée, et Jean frère de Jacques, auxquels il donna le nom de Boanerges, c’est-à-dire, fils du tonnerre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'André, Philippe, Barthélémy, Matthieu, Thomas, Jacques, fils d\'Alphée, Thaddée, Simon le zélateur');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'et Judas Iscariot, qui le livra.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Ils rentrèrent à la maison, et il s\'assembla de nouveau une si grande foule, qu\'ils ne pouvaient pas même prendre leur repas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Les parents de Jésus, ayant appris ce qui se passait, partirent pour se saisir de lui; car ils disaient: «Il a perdu l\'esprit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Les scribes qui étaient venus de Jérusalem, disaient: «Il est possédé de Belzébuth,» et: «C\'est par le prince des démons, qu\'il chasse les démons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Jésus les appela, et leur dit en se servant de comparaisons: «Comment Satan peut-il chasser Satan?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Si un royaume est en proie aux divisions, ce royaume ne peut subsister;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'et si une maison est en proie aux divisions, cette maison ne peut subsister.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'S\'il est vrai que Satan s\'est soulevé contre lui-même, et qu\'il est en proie aux divisions, il ne peut subsister, mais c\'en est fait de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'D\'ailleurs, personne ne peut entrer dans la maison de l\'homme fort, pour piller ses biens, s\'il n\'a auparavant lié cet homme fort, après quoi il pillera sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'En vérité, je vous dis que tous les péchés seront pardonnés aux fils des hommes, et tous les blasphèmes qu\'ils auront pu proférer;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mais celui qui aura blasphémé contre le Saint-Esprit, n\'obtiendra jamais de pardon; il est coupable d\'un péché éternel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Jésus leur parla ainsi, parce qu\'ils disaient: «Il est possédé d\'un esprit impur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Ses frères et sa mère arrivèrent donc, et se tenant dehors, ils le firent appeler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'La foule était assise autour de lui, lorsqu\'on lui dit: «Ta mère, tes frères et tes soeurs sont là dehors, qui te cherchent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Et Jésus répondit: «Qui est ma mère, et qui sont mes frères?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Puis, promenant ses regards sur ceux qui étaient assis tout autour de lui: «Voici, dit-il, ma mère et mes frères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'car celui qui fait la volonté de Dieu, celui-là est mon frère, et ma soeur, et ma mère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Jésus se mit de nouveau à enseigner au bord de la mer; et il s\'assembla près de lui une si grande foule, qu\'il entra et s\'assit dans une barque, sur l\'eau, et toute la foule était près de la mer, sur le rivage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Il leur enseignait beaucoup de choses en paraboles, et leur disait dans son enseignement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '«Écoutez: Un semeur sortit pour semer;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'et, comme il semait, il arriva qu\'une partie de la semence tomba le long du chemin: les oiseaux vinrent et la mangèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Une autre partie tomba sur un sol pierreux, où elle n\'avait pas beaucoup de terre; elle leva aussitôt, parce que le sol n\'avait pas de profondeur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'et, lorsque le soleil fut levé, elle fut brûlée, et sécha, faute de racines.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Une autre partie tomba parmi les épines: les épines crurent et l\'étouffèrent; et elle ne donna point de fruit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Une autre partie tomba dans la bonne terre: elle donna un blé grand et bien développé, et rapporta jusqu’à trente, soixante et cent pour un.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Et il ajouta: «Que celui qui a des oreilles pour entendre, entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Quand la foule se fut retirée, ceux qui entouraient Jésus avec les Douze, le questionnèrent sur les paraboles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'et il leur dit: «C\'est à vous qu\'a été donné le mystère du royaume de Dieu, mais pour eux, qui sont en dehors, tout se dit en paraboles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'afin qu\'en regardant, ils regardent, et ne voient point, et qu\'en entendant, ils entendent et ne comprennent point; de peur qu’ils ne se convertissent, et que leurs péchés ne soient pardonnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Et il ajouta: «Vous n\'entendez pas cette parabole! comment donc comprendrez-vous toutes les autres?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Celui qui sème, sème la Parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Ceux qui reçoivent la semence le long du chemin, quand la Parole est semée, ce sont ceux qui l\'ont à peine entendue, que Satan vient et enlève la Parole qui a été semée en eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'De même, ceux qui reçoivent la semence dans les endroits pierreux, ce sont ceux qui, dès qu\'ils entendent la Parole, la reçoivent avec joie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'mais il n\'y a point en eux de racines; ils sont sans consistance: qu\'ensuite l\'affliction ou la persécution survienne à cause de la Parole. elle est aussitôt pour eux une occasion de chute.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Autres sont ceux qui reçoivent, la semence parmi les épines: ce sont ceux qui entendent la Parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'et en qui les soucis du temps présent, la séduction des richesses et toutes les autres passions qui les envahissent, étouffent la Parole et la rendent infructueuse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Enfin ceux qui ont reçu la semence dans la bonne terre, ce sont ceux qui entendent la Parole, la reçoivent et portent du fruit à raison de trente, de soixante et de cent pour un.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Et il ajouta: «Apporte-t-on la lampe, pour la mettre sous le boisseau ou sous le lit? N\'est-ce pas pour la mettre sur son pied?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Car rien n\'est caché, qui ne doive être révélé, rien même n\'a été tenu secret, que pour venir au grand jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Si quelqu\'un a des oreilles pour entendre, qu\'il entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Et il ajouta: «Prenez garde à ce que vous entendez. On se servira pour vous de la mesure avec laquelle vous aurez mesuré, en y ajoutant encore pour vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'car on donnera à celui qui a, mais pour celui qui n\'a pas, on lui ôtera même ce qu\'il a.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Il dit encore: «Il en est du royaume de Dieu comme de la semence qu\'un homme a jetée en terre:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'qu\'il dorme ou qu\'il veille, nuit et jour, la semence pousse et grandit sans qu\'il sache comment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'La terre produit d\'elle-même du fruit: d\'abord de l\'herbe, puis un épi, puis voilà un grain bien nourri dans l\'épi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Aussitôt que le fruit le permet, on y met la faucille, parce que c\'est la moisson.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Il dit encore: «A quoi devons-nous comparer le royaume de Dieu, ou par quelle parabole faut-il le représenter?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, '— Nous le comparerons à un grain de moutarde, qui, lorsqu\'on le sème, est la plus petite des graines de la terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'puis, quand il a été semé, il croit et devient la plus grande des plantes potagères; il pousse des branches assez grandes pour que les oiseaux du ciel puissent s\'abriter à son ombre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'C\'était par beaucoup de paraboles de ce genre, qu\'il leur annonçait la Parole, selon qu\'ils étaient capables de l\'entendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Il ne leur parlait qu\'en paraboles; mais, en particulier, il expliquait tout à ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Ce même jour, vers le soir, il leur dit: «Passons à l\'autre bord.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Après avoir renvoyé la foule, ses disciples l\'emmenèrent dans la barque, sans le déranger: d\'autres petites embarcations l\'accompagnaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Il s\'éleva un violent orage, et les vagues déferlaient sur la barque, de sorte qu\'elles menaçaient de la remplir:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'et Jésus était à la poupe, dormant sur l\'oreiller. Les disciples le réveillèrent et lui dirent: «Maître, tu ne t\'inquiètes pas de ce que nous périssons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Jésus étant réveillé, tança le vent, et dit à la mer: «Tais-toi! Silence!» et le vent cessa, et il se fit un grand calme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Alors il dit à ses disciples: «Pourquoi avez-vous peur? Comment? n\'avez-vous point de foi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Et ils furent saisis d\'une grande terreur, et ils se dirent les uns aux autres: «Quel est donc cet homme, que le vent et la mer lui obéissent?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Ils abordèrent à l\'autre rive de la mer, dans le pays des Gadaréniens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'A peine Jésus fut-il sorti de la barque, qu\'un homme possédé d\'un esprit impur vint au devant de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Il sortait des sépulcres, dont il avait fait sa demeure. Personne ne pouvait plus le tenir attaché, même avec une chaîne;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'car on l\'avait souvent chargé de liens aux pieds, et de chaînes, et il avait brisé les chaînes, rompu les liens, de sorte que personne ne pouvait en être maître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Il ne cessait, nuit et jour, dans les sépulcres et sur les montagnes, de pousser des cris et de se meurtrir avec des pierres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Il courut vers Jésus, d\'aussi loin qu\'il l\'aperçut, se prosterna devant lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'et, ayant poussé un cri, il dit d\'une voix forte: «Qu\'y a-t-il entre toi et moi, Jésus. Fils du Dieu Très-Haut? Je t\'en conjure, au nom de Dieu, ne me tourmente pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Jésus, en effet, lui avait dit: «Esprit impur, sors de cet homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, '— Quel est ton nom? lui demanda Jésus. Le démoniaque lui dit: «Mon nom est Légion, car nous sommes nombreux:»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'et il le priait instamment de ne pas les envoyer hors du pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Or il y avait là, vers la montagne, un grand troupeau de pourceaux qui paissaient,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'et les démons lui adressèrent cette prière: «Envoie-nous dans ces pourceaux, afin que nous y entrions.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Jésus le leur permit aussitôt. Et les esprits impurs étant sortis, entrèrent dans les pourceaux; et le troupeau, au nombre d\'environ deux mille pourceaux, se rua du haut du précipice dans la mer, et s\'y noya.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Ceux qui les gardaient s\'enfuirent, et répandirent la nouvelle dans la ville et dans la campagne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Beaucoup de gens allèrent voir ce qui était arrivé; ils vinrent vers Jésus, et virent le démoniaque, le même qui avait eu la légion, assis, vêtu et dans son bon sens; ce qui les remplit de frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Lorsque les témoins de ce fait leur eurent raconté comment les choses s\'étaient passées pour le démoniaque, et ce qui concernait les pourceaux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'ils se mirent à supplier Jésus de s\'éloigner de leur pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Comme Jésus entrait dans la barque, le démoniaque lui demanda la permission de rester avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Et Jésus ne le lui permit pas, mais il lui dit: «Va-t\'en chez toi, vers les tiens, et rapporte-leur tout ce que le Seigneur a fait pour toi, et comme il a eu compassion de toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Il s\'en alla et se mit à publier dans la Décapole tout ce que Jésus avait fait pour lui; et tout le monde en était étonné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Quand Jésus eut regagné l\'autre rive, dans la barque, une grande foule s\'assembla près de lui. Il était au bord de la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Alors vint un des chefs de la synagogue, nommé Jaïrus, qui, en le voyant, se jeta à ses pieds');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'et lui adressa cette instante prière: «Ma fille est à toute extrémité; viens lui imposer les mains, afin qu\'elle soit guérie et qu\'elle vive;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Jésus partit avec lui, et une grande foule le suivait et le pressait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Une femme malade d\'une hémorragie depuis douze ans,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'qui avait beaucoup souffert entre les mains de plusieurs médecins, et qui, après avoir dépensé tout son bien, n\'avait point été soulagée, mais avait vu plutôt son mal empirer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'ayant entendu parler de Jésus, vint se mêler à la foule et toucha par derrière son manteau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'car elle se disait: «Si je puis seulement toucher ses vêtements, je serai guérie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Au même instant sa perte s\'arrêta, et elle sentit dans son corps qu\'elle était guérie de son infirmité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'A l\'instant aussi Jésus sentit intérieurement qu\'une vertu était sortie de lui, et, se retournant au milieu de la foule, il dit: «Qui est-ce qui a touché mes vêtements?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Ses disciples lui dirent: «Tu vois que la foule te presse, et tu demandes qui t\'a touché!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Et Jésus regardait tout autour de lui, pour voir celle qui l\'avait touché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'La femme effrayée et tremblante, sachant ce qui s\'était passé en elle, vint se jeter à ses pieds, et lui dit toute la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Jésus lui dit: «Ma fille, ta foi t\'a guérie; va en paix, et sois délivrée de ton infirmité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Il parlait encore, lorsqu\'on vint dire an chef de la synagogue: «Ta fille est morte; pourquoi fatiguer encore le maître?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mais Jésus, sans s\'arrêter à cette parole, dit tout de suite au chef de la synagogue: «Ne crains point, crois seulement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Et il ne permit à personne de l\'accompagner, si ce n\'est à Pierre, à Jacques et à Jean, frère de Jacques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Quand ils furent arrivés à la maison du chef de la synagogue, Jésus entendit un grand bruit, des gens qui pleuraient et criaient beaucoup;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'et, étant entré, il leur dit: «Pourquoi faites-vous ce bruit et pleurez-vous? L\'enfant n\'est pas morte, mais elle dort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Et ils se moquèrent de lui. Mais, ayant fait sortir tout le monde, il prit avec lui le père de l\'enfant, la mère et les disciples qui l\'accompagnaient, et entra dans la chambre où était l\'enfant;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'puis, la saisissant par la main, il lui dit: «Talitha Koumi;» ce qui signifie: Jeune fille, je te le commande, lève-toi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'A l\'instant la jeune fille se leva, et se mit à marcher, car elle avait douze ans; et les assistants furent dans un ravissement extrême.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Jésus leur enjoignit expressément de n\'en parler à personne; et il dit qu\'on donnât à manger à l\'enfant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Jésus partit de là et se rendit dans sa patrie. Ses disciples l\'accompagnaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Quand le sabbat fut venu, il se mit à enseigner dans la synagogue; et plusieurs étaient étonnés en l\'entendant et disaient: D\'où cela lui vient-il? Quelle est cette sagesse qui lui a été donnée? De pareils miracles se font par ses mains!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'N\'est-ce pas le charpentier, le fils de Marie, un frère de Jacques, de Joses, de Jude et de Simon? Ses soeurs ne sont-elles pas ici avec nous? Et il était pour eux une pierre d\'achoppement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Mais Jésus leur dit: «Ce n\'est que dans son pays chez ses parents et dans sa maison qu\'un prophète n\'est pas honoré.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Et, sauf un petit nombre de malades qu\'il guérit en leur imposant les mains, il ne put faire là aucun miracle:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'il était surpris de leur incrédulité. Ensuite il fit une tournée dans les villages en enseignant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Il appela près de lui les Douze et se mit à les envoyer deux à deux, en leur donnant pouvoir sur les esprits impurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Il leur recommanda de ne rien prendre pour la route, si ce n\'est un bâton, de n\'emporter ni pain, ni sac, ni monnaie dans leur ceinture;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'mais d\'être chaussés de sandales et de ne pas mettre deux tuniques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Puis il ajouta: «Dans quelque maison que vous entriez, restez-y, jusqu\'à ce que vous partiez de cet endroit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'et, quel que soit le lieu on l\'on ne vous reçoive pas et on l\'on ne vous écoute pas, sortez-en, et secouez la poussière de vos pieds pour que cela serve de témoignage aux habitants.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Et les Douze étant partis, prêchèrent qu\'on se repentît;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'ils chassaient beaucoup de démons; ils oignaient d\'huile beaucoup de malades et les guérissaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Le roi Hérode, ayant entendu parler de Jésus, dont le nom était devenu célèbre, dit: «Jean-Baptiste est ressuscité c\'est pour cela que la puissance miraculeuse se déploie en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'D\'autres disaient: «C\'est Elie:» d\'autres: «C\'est un prophète comme l\'un des anciens prophètes;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'mais Hérode, entendant ces bruits, disait: «C\'est ce Jean que j\'ai fait décapiter, qui est ressuscité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'En effet, c\'était lui, Hérode, qui avait fait arrêter Jean et l\'avait fait charger de chaînes dans la prison, à cause d\'Hérodiade, femme de Philippe, son frère, parce qu\'il l\'avait épousée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'et que Jean lui avait dit: «Il ne t\'est pas permis d\'avoir pour femme la femme de ton frère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Hérodiade qui en voulait à Jean, désirait le faire mettre à mort; mais ne pouvait y parvenir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'parce qu\'Hérode craignait Jean, le connaissant pour un homme juste et saint; il le protégeait même, et faisait beaucoup de choses, après avoir pris ses conseils, et il les prenait volontiers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Enfin il se présenta une occasion favorable. Le jour anniversaire de sa naissance, Hérode donna un festin aux grands de sa cour, à ses officiers et aux principaux de la Galilée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'et la fille d\'Hérodiade étant entrée dans la salle, dansa et charma Hérode ainsi que les convives. Le roi dit à la jeune fille: «Demande-moi ce que tu voudras, et je te le donnerai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Et il ajouta avec serment: «Quoi que tu me demandes, je te le donnerai, fût-ce même la moitié de mon royaume.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Elle sortit, et dit à sa mère: «Que dois-je demander?» Sa mère lui dit: «La tête de Jean-Baptiste.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'La jeune fille rentrant aussitôt, s\'empressa d\'adresser au roi sa demande: «Je veux, dit-elle, que tu me donnes, à l\'heure même, dans un bassin, la tête de Jean-Baptiste.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Le roi devint tout triste; mais, à cause de ses serments et à cause des convives, il ne voulut pas la refuser,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'et il envoya immédiatement un de ses gardes, avec l\'ordre d\'apporter la tête de Jean. Le garde alla décapiter Jean dans la prison');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'et apporta sa tête dans un bassin; il la donna à la jeune fille, qui la donna à sa mère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Les disciples de Jean, ayant appris ce meurtre, vinrent prendre le corps de leur maître et le déposèrent dans un sépulcre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Les Apôtres s\'étant réunis auprès de Jésus, et lui ayant rapporté tout ce qu\'ils avaient fait et tout ce qu\'ils avaient enseigné,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Jésus leur dit: «Venez, vous seuls, à l\'écart, dans un lieu solitaire, et prenez un peu de repos.» Il y avait, en effet, beaucoup d\'allants et de venants, de sorte que les disciples n\'avaient pas même le temps de manger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Ils s\'en allèrent donc, dans une barque, en un lieu solitaire à l\'écart.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'On les vit partir, et bon nombre de gens devinèrent où ils allaient; ils y accoururent à pied de toutes les villes, et arrivèrent avant eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Lorsque Jésus sortit de la barque, il vit une grande foute, et fut ému de compassion envers eux, parce qu\'ils étaient comme des brebis qui n\'ont point de berger; et il se mit à les enseigner longuement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Comme l\'heure était déjà fort avancée, ses disciples s\'approchèrent de lui, et lui dirent: «Ce lieu est désert, et l\'heure est déjà fort avancée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'renvoie-les, afin qu\'ils aillent dans les campagnes et dans les villages d\'alentour s\'acheter de quoi manger.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Il leur répondit: «Donnez-leur, vous-mêmes, à manger.» Et ils lui dirent: «Que nous allions acheter pour deux cents deniers de pain, et que nous leur donnions à manger!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Jésus reprit: «Combien de pains avez-vous? Allez, voyez.» Et eux, s\'en étant assurés, dirent: «Cinq pains et deux poissons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Alors il leur commanda de faire asseoir tout le monde, par groupes, sur l\'herbe verte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'et ils s\'assirent par troupes de cent et de cinquante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Jésus prit les cinq pains et les deux poissons, et, levant les yeux au ciel, il prononça la bénédiction; puis il rompit les pains et les donna à ses disciples, pour qu\'ils les distribuassent. Il partagea aussi les deux poissons entre tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Tous mangèrent et furent rassasiés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'et l’on emporta douze corbeilles pleines de morceaux de pain et de ce qui restait des poissons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Le nombre de ceux qui mangèrent des pains, s\'élevait à cinq mille hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Aussitôt après, Jésus pressa ses disciples d\'entrer dans la barque et de le précéder vers l\'autre rive, du côté de Bethsaïde, pendant que lui-même renverrait la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Après avoir pris congé d\'elle, il s\'en alla sur la montagne pour prier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Quand la nuit fut venue, la barque était au milieu de la mer, et Jésus était seul à terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Ayant aperçu ses disciples qui avaient une traversée pénible, car le vent leur était contraire, il vint vers eux, à la quatrième veille de la nuit environ, en marchant sur la mer; il voulait les dépasser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mais eux, le voyant marcher sur la mer, crurent que c\'était un fantôme, et poussèrent des cris;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'car ils le voyaient tous, et ils étaient bouleversés. Alors il leur parla et leur dit: «Rassurez-vous, c\'est moi; n\'ayez point de peur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Puis il entra auprès d\'eux dans la barque, et le vent cessa. Et les disciples en furent stupéfaits et surpris au delà de toute idée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'car ils n\'avaient rien compris à l\'affaire des pains, parce que leur coeur était aveuglé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Lorsqu\'ils eurent achevé leur traversée, ils arrivèrent au pays de Génésareth, et abordèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'A peine eurent-ils débarqué, que les gens reconnaissant Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'coururent çà et là, dans tous les environs, et l\'on se mit à transporter les malades sur leurs lits, partout où l’on entendait dire qu\'il était.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'En quelque lieu qu\'il entrât, dans les villages, dans les villes ou dans les campagnes, on déposait les malades sur les places publiques, et on le priait de les laisser seulement toucher la houppe de son manteau; et tous ceux qui pouvaient toucher Jésus étaient guéris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Les pharisiens et quelques scribes venus de Jérusalem s\'assemblèrent près de Jésus:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'ils avaient vu quelques-uns de ses disciples prendre leurs repas avec des mains souillées, c’est-à-dire, qui n\'avaient pas été lavées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'En effet, les pharisiens et tous les juifs ne mangent pas, sans s\'être soigneusement lavé les mains, observant strictement en cela la tradition des anciens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Ils ne mangent point au retour du marché, sans s\'être plongés dans l’eau; et ils pratiquent encore beaucoup d\'autres observances traditionnelles: le lavage des coupes, des brocs, des ustensiles d\'airain et des lits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Les pharisiens donc et les scribes firent à Jésus cette question: «Pourquoi tes disciples ne se conforment-ils pas à la tradition des anciens, mais prennent-ils leurs repas avec des mains souillées?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Il leur répondit: «Ésaïe a bien prophétisé sur votre compte, hypocrites que vous êtes, ainsi qu\'il est écrit: «Ce peuple m\'honore des lèvres mais son coeur est fort éloigné de moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'C’est vainement qu\'il m\'honore en donnant des préceptes qui ne sont que des commandements d\'hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Vous abandonnez le commandement de Dieu, pour vous attacher à la tradition des hommes, au lavage des brocs et des coupes, et vous faites beaucoup d\'autres choses semblables et toutes pareilles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Et il ajouta: «Vous vous entendez merveilleusement à mettre à néant le commandement de Dieu pour garder votre tradition.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Par exemple. Moïse a dit: «Honore ton père et ta mère,» et: «Que celui qui maudit père ou mère soit mis et mort;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'mais vous, vous dites: «Si un homme dit à son père ou à sa mère, «ce dont je pourrais vous assister est Corban (c’est-à-dire, un don consacré),»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'eh bien! vous ne le laissez plus rien faire pour son père ni pour sa mère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'annulant ainsi le commandement de Dieu par la tradition que vous enseignez. Et vous faites beaucoup de choses semblables et toutes pareilles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Puis, ayant rappelé le peuple, il lui dit: «Écoutez-moi tous, et comprenez:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Rien de ce qui est hors de l\'homme et qui entre dans l\'homme, ne peut le souiller; mais ce qui sort de l\'homme, voilà ce qui le souille.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, '[Si quelqu’un a des oreilles pour entendre, qu’il entende!]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Lorsqu\'il fut rentré chez lui, et qu\'il se trouva loin de la foule, ses disciples lui demandèrent le sens de cette sentence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'et il leur dit: «Vous aussi, vous êtes donc sans intelligence? Vous ne comprenez pas que tout ce qui de dehors entre dans l\'homme ne peut le souiller,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'parce que cela n\'entre pas dans son coeur, mais dans son ventre, et s\'en va aux lieux qui purifient tous les aliments.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Et il ajouta: «Ce qui sort de l\'homme, voilà ce qui souille l\'homme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'car c\'est du dedans, du coeur des hommes, que sortent les mauvaises pensées, le libertinage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'les vols, les meurtres, les adultères, la rapacité, la malhonnêteté, la fourberie, le dérèglement, le regard envieux, la calomnie, l\'orgueil, la déraison:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'toutes ces mauvaises choses-là sortent de dedans, et souillent l\'homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Jésus, étant parti de là, se rendit aux confins de Tyr. Il entra dans une maison et aurait voulu qu\'on ne le sût point, mais il ne put rester ignoré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Une femme, dont la fille était possédée d\'un esprit impur, eut à peine entendu parler de lui, qu\'elle vint se jeter à ses pieds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Cette femme était grecque, syro-phénicienne d\'origine, et elle le pria de délivrer sa fille du démon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jésus lui dit: «Laisse d\'abord les enfants se rassasier; car il n\'est pas bien de prendre le pain des enfants pour le jeter aux petits chiens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Elle lui repartit: «Sans doute, Seigneur, puisque les petits chiens mangent, sous la table, les miettes des petits enfants.» —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, '«A cause de cette parole, lui dit Jésus, va, le démon est sorti de ta fille.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'A son retour chez elle, cette femme trouva l\'enfant couchée sur le lit, et le démon parti.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Ayant quitté les confins de Tyr, il revint par Sidon vers la mer de Galilée, en traversant le pays de la Décapole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'On lui amena un sourd-muet, et on le pria de lui imposer les mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Jésus, l\'ayant emmené loin de la foule, à l\'écart, lui mit les doigts dans les oreilles, et de la salive sur la langue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'puis, levant les yeux au ciel, il soupira, et lui dit: «Ephphata,» c’est-à-dire, ouvre-toi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Et les oreilles de cet homme s\'ouvrirent, sa langue se délia, et il parla distinctement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Jésus recommanda à ceux qui avaient vu cette guérison de n\'en parler à personne, mais plus il le leur recommandait, plus ils la publiaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Ils étaient frappés d\'étonnement au delà de toute idée, et disaient: «C\'est merveilleux, tout ce qu\'il a fait! Il fait entendre les sourds et parler les muets.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'En ces jours-là, Jésus, se trouvant avec une foule immense qui n\'avait pas de quoi manger, appela ses disciples et leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'J\'ai compassion de cette foule, car voilà déjà trois jours que ces gens restent près de moi, et ils n\'ont pas de quoi manger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Si je les renvoie chez eux à jeun, ils défailliront en route, car quelques-uns d\'entre eux viennent de loin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Ses disciples lui répondirent: «où pourrait-on trouver, ici, dans un désert, des pains pour nourrir ces gens?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Jésus leur demanda: «Combien de pains avez-vous?» — «Sept,» dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Alors il fit asseoir la foule par terre, puis il prit les sept pains, et, ayant rendu grâces, il les rompit, et les donna à ses disciples pour les distribuer et les disciples les distribuèrent à la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ils avaient encore quelques petits poissons, et Jésus, ayant prononcé la bénédiction, les fit aussi distribuer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Ils mangèrent et furent rassasiés, et l’on emporta sept corbeilles pleines des morceaux qui restaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Il y avait environ quatre mille personnes. Ensuite Jésus les renvoya.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Aussitôt après, il entra dans la barque avec ses disciples, et s\'en alla dans le territoire de Dalmanutha.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Les pharisiens vinrent et se mirent à discuter avec Jésus, lui demandant, pour le mettre à l\'épreuve, un signe qui vînt du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Et Jésus, ayant poussé un profond soupir en son coeur, dit: «Pourquoi cette génération réclame-t-elle un signe? En vérité, je vous le dis, non, il ne sera point accordé de signe à cette génération.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Là-dessus, il les quitta et se rembarqua pour passer à l\'autre bord.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Les disciples avaient oublié de prendre des pains; ils n\'en avaient qu\'un seul avec eux dans la barque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Et comme Jésus leur faisait des recommandations, disant: «Faites attention, gardez-vous du levain des pharisiens, ainsi que du levain d\'Hérode,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'ils raisonnaient ainsi entre eux: «C\'est que nous n\'avons pas de pains.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jésus s\'en étant aperçu, leur dit: «Quelle idée avez-vous? C\'est que vous n\'avez pas de pains! Vous ne saisissez pas encore, vous ne comprenez pas? Avez-vous l\'intelligence obtuse?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Puisque vous avez des yeux, ne voyez- vous pas, et, puisque vous avez des oreilles, n\'entendez-vous pas? N\'avez-vous point de mémoire?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Quand j\'ai rompu les cinq pains pour les cinq mille hommes, combien avez-vous emporté de corbeilles pleines de morceaux?» — «Douze,» lui dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '«Et quand j’ai rompu les sept pains pour les quatre mille hommes, combien avez-vous emporté de corbeilles pleines de morceaux?» - «Sept,» lui répondirent-ils. —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, '«Eh bien! leur dit-il, vous ne comprenez pas encore?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Et ils arrivèrent à Bethsaïde. On lui amena un aveugle, et on le pria de le toucher.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Jésus, prenant l\'aveugle par la main, l\'emmena hors du village; et, après lui avoir mis de la salive sur les yeux, il lui imposa les mains, et lui demanda s\'il voyait quelque chose.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'L\'aveugle, ayant ouvert les yeux, dit: «Je vois des hommes, car je les aperçois marcher comme si c\'étaient des arbres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Jésus lui mit une seconde fois les mains sur les yeux, et l\'aveugle, ayant regardé fixement, fut complètement guéri: il voyait tous les objets avec netteté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Jésus le renvoya dans sa maison, en lui disant: «Ne rentre pas dans le village, et n\'y parle à personne de ce qui est arrivé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Jésus s\'en alla avec ses disciples dans les villages de Césarée de Philippe, et, chemin faisant, il leur adressa cette question: «Qui dit-on que je suis?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Ils lui répondirent: «On dit que tu es Jean-Baptiste; d\'autres disent que tu es Elie, mais d\'autres prétendent que tu es quelqu\'un des prophètes.» —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, '«Et vous, leur demanda-t-il, qui dites-vous que je suis?» Pierre lui répondit: «Tu es le Messie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Jésus leur recommanda sévèrement de ne parler de lui à personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'et il commença à leur apprendre qu\'il fallait que le Fils de l\'homme souffrît beaucoup, qu\'il fût rejeté par les anciens, par les principaux sacrificateurs et par les scribes, qu\'il fût mis à mort, et qu\'il ressuscitât trois jours après:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'il s\'exprimait ouvertement. Pierre, le prenant à part, se mit à le reprendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mais Jésus, s\'étant retourné, et ayant regardé ses disciples, réprimanda Pierre, et lui dit: «Arrière de moi, Satan, car tes sentiments ne sont pas ceux de Dieu, mais ceux des hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Puis, ayant appelé la foule, ainsi que ses disciples, il leur dit: «Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, qu\'il se charge de sa croix, et qu\'il me suive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Car celui qui veut sauver sa vie, la perdra; mais celui qui perdra sa vie à cause de moi et de l\'évangile, la sauvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Que servira-t-il à l\'homme de gagner le monde entier, s\'il perd son âme?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Car que donnera un homme pour recouvrer son âme?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'En effet, si quelqu\'un a honte de moi et de mes paroles au milieu de cette génération adultère et pécheresse, le Fils de l\'homme aura aussi honte de lui, quand il viendra dans la gloire de son Père avec les saints anges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Et il ajouta: «En vérité je vous le dis, quelques-uns de ceux qui sont ici présents, ne goûteront point la mort, qu\'ils n\'aient vu le royaume de Dieu inauguré avec puissance.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Six jours après, Jésus, ayant pris avec lui Pierre, Jacques et Jean, les mena sur une haute montagne, seuls, à l\'écart, et il fut transfiguré devant eux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'ses vêtements devinrent éblouissants d\'une blancheur telle, qu\'il n\'est pas un foulon sur la terre qui puisse blanchir ainsi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Puis Elie leur apparut avec Moïse; ils s\'entretenaient avec Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Pierre, prenant la parole, dit à Jésus: «Rabbi, il est bon que nous soyons ici; dressons trois tentes, une pour toi, une pour Moïse, et une pour Élie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Il ne savait ce qu\'il disait: l\'effroi les avait saisis tous trois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Une nuée survint qui les enveloppa, et il sortit de la nuée une voix: «Celui-ci est mon fils bien-aimé; écoutez-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Soudain, ayant jeté les regards autour d\'eux, ils ne virent plus personne que Jésus, seul avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Comme ils descendaient de la montagne, Jésus leur recommanda de ne raconter à personne ce qu\'ils avaient vu, avant que le Fils de l\'homme fût ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Les disciples retinrent cette recommandation, tout en discutant entre eux pour savoir ce que signifiait ce mot «être ressuscité des morts;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'et ils adressèrent à Jésus cette question: «Pourquoi les scribes disent-ils qu\'Elie doit venir premièrement?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Il leur répondit: «Elie doit venir premièrement, et rétablir toutes choses! et d\'où vient qu\'il est écrit, que c\'est afin que le Fils de l\'homme souffre beaucoup, et qu\'il soit rejeté avec mépris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mais je vous dis qu\'Elie est venu, et qu\'ils lui ont fait tout ce qu\'ils ont voulu, selon qu\'il est écrit à son sujet.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Quand il arriva vers ses disciples, il vit une grande foule autour d\'eux, et des scribes qui disputaient avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Toute la foule fut surprise de le voir, et elle accourut pour le saluer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Il leur demanda: «De quoi disputez-vous avec eux?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Et un homme de la foule lui répondit: «Maître, je t\'ai amené mon fils qui est possédé d\'un esprit muet:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'en quelque lieu que cet esprit s\'empare de lui, il le jette par terre; l\'enfant écume, grince des dents, et dépérit. J\'ai prié tes disciples de chasser l\'esprit, et ils ne l\'ont pu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Jésus répondit, et leur dit: «Race incrédule, jusqu’à quand serai-je avec vous, jusqu’à quand vous supporterai-je?... Amenez-le moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Et on le lui amena. Aussitôt que l\'enfant vit Jésus, il fut jeté par l\'esprit dans des convulsions, il tomba par terre et se roulait en écumant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Jésus demanda au père: «Combien y a-t-il de temps que cela lui arrive?» — «Depuis son enfance, dit-il;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'et souvent l\'esprit l\'a jeté soit dans le feu, soit dans l\'eau, afin de le faire périr; mais si tu le peux, viens à notre secours par pitié pour nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jésus lui répliqua: «Si je le peux! Tout est possible envers celui qui croit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Aussitôt le père de l\'enfant s\'écria: «Je crois; viens au secours de mon incrédulité!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Jésus, voyant la foule accourir, tança l\'esprit impur, et lui dit: «Esprit muet et sourd, je te le commande, moi, sors de cet enfant, et n\'y rentre plus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Alors, ayant poussé un cri et causé de violentes convulsions, l\'esprit sortit, et l\'enfant devint comme un cadavre, au point que la plupart disaient: «Il est mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mais Jésus, le saisissant par la main, le releva, et il se tint debout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Jésus étant rentré chez lui, ses disciples lui demandèrent en particulier: «Pourquoi n\'avons-nous pu chasser cet esprit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Il leur dit: «Rien, excepté la prière, ne peut faire sortir cette espèce de démons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Etant partis de là, ils cheminèrent à travers la Galilée, et Jésus ne voulait pas qu\'on le sût,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'parce qu\'il enseignait ses disciples. Il leur disait: «Le Fils de l\'homme va être livré entre les mains des hommes, et ils le mettront à mort; mais, lorsqu\'il aura été mis à mort, trois jours après, il ressuscitera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mais eux ne comprenaient point cette parole, et ils craignaient de l\'interroger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Jésus rentra à Capernaoum. Quand il fut chez lui, il leur demanda: «De quoi vous entreteniez-vous en chemin?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mais ils gardèrent le silence, parce qu\'en chemin ils avaient débattu entre eux cette question: «Qui est le plus grand?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Jésus s\'étant assis, appela les Douze, et leur dit: «Si quelqu\'un veut être le premier, il sera le dernier de tous et le serviteur de tous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Puis, il prit un petit enfant, le plaça au milieu d\'eux, et, l\'ayant embrassé, il leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '«Celui qui reçoit un de ces enfants-là en mon nom, me reçoit; et celui qui me reçoit, reçoit non, pas moi, mais celui qui m\'a envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Jean, prenant la parole, lui dit: «Maître, nous avons vu un homme qui ne va pas avec nous, chasser les démons en ton nom, et nous l\'en avons empêché, parce qu\'il ne va pas avec nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Mais Jésus dit: «Ne l\'en empêchez pas, car il n\'est personne qui, après avoir fait un miracle en mon nom, puisse, aussitôt après, dire du mal de moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Qui n\'est pas contre nous est pour nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Car celui qui vous donnera un verre d\'eau pour le nom de Christ à qui vous êtes, je vous dis en vérité qu\'il ne perdra point sa récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Si quelqu\'un devait être une occasion de chute pour un seul des petits qui ont la foi, il vaudrait mieux pour lui, qu\'on lui mît une pierre de moulin autour du cou, et qu\'on le jetât dans la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Si ta main est pour toi une occasion de chute, coupe-la; il te vaut mieux entrer manchot dans la vie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'que d\'avoir deux mains, et d\'aller dans la Géhenne, dans le feu qui ne s\'éteint point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Si ton pied est pour toi une occasion de chute, coupe-le; il te vaut mieux entrer boiteux dans la vie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'que d\'avoir deux pieds, et d\'être jeté dans la Géhenne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Si ton oeil est pour toi une occasion de chute, arrache-le; il te vaut mieux entrer borgne dans le royaume de Dieu, que d\'avoir deux yeux, et d\'être jeté dans la Géhenne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, '«où le ver ne meurt point, et on le feu ne s\'éteint point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Car tout homme sera salé par le feu, et tout sacrifice sera salé avec du sel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'C\'est une bonne chose que le sel; mais s\'il devient insipide, avec quoi lui donnerez-vous de la saveur? Gardez bien le sel en vous, et soyez en paix les uns avec les autres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Jésus étant parti de là, se rendit aux confins de la Judée, de l\'autre côté du Jourdain. Des foules se joignirent de nouveau à lui, et Jésus, suivant sa coutume, se mit de nouveau à les enseigner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Des pharisiens vinrent vers lui, et lui demandèrent s\'il est permis à un mari de répudier sa femme: c\'était pour le mettre à l\'épreuve.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Jésus leur répondit: «Qu\'est-ce que Moïse vous a prescrit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, '— «Moïse, dirent-ils, nous a autorisés à dresser un acte de divorce et à répudier.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jésus reprit: «C\'est à cause de la dureté de votre coeur que Moïse vous a donné ce commandement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'mais au commencement de la création, Dieu les fit, l’un homme, l’autre femme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'pour cette raison. L’homme, quittera son père et sa mère pour s\'attacher à sa femme,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'et les deux seront une seule chair. Ainsi ils ne sont plus deux, mais ils sont une seule chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Que l\'homme donc ne sépare pas ce que Dieu a uni.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Rentrés au logis, les disciples l’interrogèrent encore sur ce sujet;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'et il leur dit: «Si un homme répudie sa femme et en épouse une autre, il se rend coupable d\'adultère à l’égard de la première;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'et si une femme se divorce d\'avec son mari et en épouse un autre, elle commet un adultère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'On lui amena de petits enfants, pour qu\'il les touchât. Les disciples reprenaient ceux qui les amenaient,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'mais Jésus, s\'en étant aperçu, en fut fâché, et leur dit: «Laissez venir vers moi ces petits enfants; ne les en empêchez pas, car le royaume de Dieu est à ceux qui leur ressemblent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'En vérité, je vous dis que si l’on ne reçoit pas le royaume de Dieu avec les dispositions d\'un petit enfant, l’on n\'y entre point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Puis il embrassa ces enfants, leur imposa les mains, et les bénit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Au moment où il sortait pour se mettre en route, un homme accourut, et, se jetant à ses genoux, lui adressa cette question: «Bon Maître, que dois-je faire pour hériter la vie éternelle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jésus lui dit: «Pourquoi m\'appelles-tu bon? Dieu seul est bon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu connais les commandements: «Ne commets point adultère; ne tue point; ne dérobe point; ne porte point de faux témoignage; ne fais tort à personne; honore ton père et mère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Cet homme répondit: «Maître, j\'ai gardé tous ces commandements dès ma jeunesse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jésus, l\'ayant regardé, l\'aima, et lui dit: «Il te manque une chose: va, vends tout ce que tu as, et le donne aux pauvres, et tu auras un trésor dans le ciel; puis viens, suis-moi en portant ta croix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mais lui, assombri par cette parole, s\'en alla tout triste, car il avait de grands biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Alors Jésus, jetant ses regards autour de lui, dit à ses disciples: «Qu\'il est difficile à ceux qui possèdent les richesses d\'entrer dans le royaume de Dieu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Ils furent stupéfaits de ces paroles. Alors Jésus reprit: «Mes enfants, qu\'il est difficile à ceux qui mettent leur confiance dans les richesses d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Il est plus aisé qu\'un chameau passe par le trou d\'une aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Les disciples encore plus étonnés, se disaient les uns aux autres: «Et qui peut être sauvé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jésus, arrêtant son regard sur eux, dit: «Cela est impossible aux hommes, mais non à Dieu; car toutes choses sont possibles à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pierre se mit à lui dire: «Pour nous, tu le vois, nous avons tout quitté pour te suivre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jésus répondit: «En vérité je vous le dis, personne ne quittera, pour moi et pour l\'évangile, maison, ou frères, ou soeurs, ou mère, ou père, ou enfants, ou terres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'qu\'il ne reçoive au centuple, dans le temps présent, des maisons, des frères, des soeurs, des mères, des enfants et des terres, au milieu même des persécutions, et, dans le siècle à venir, la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Bien des derniers seront les premiers, et bien des premiers seront les derniers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Ils étaient en route pour monter à Jérusalem: Jésus allait devant, et les disciples suivaient pleins de stupeur, quelques-uns même pleins d\'effroi. Jésus, prenant de nouveau les Douze près de lui, se mit à leur dire ce qui devait lui arriver:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '«Voici que nous montons à Jérusalem, et le Fils de l\'homme sera livré aux principaux sacrificateurs et aux scribes: ils le condamneront à mort et le livreront aux Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'qui le bafoueront, le flagelleront, cracheront sur lui et le mettront à mort; mais, trois jours après, il ressuscitera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Jacques et Jean, fils de Zébédée, s\'avancèrent vers lui, et lui dirent: «Maître, nous voudrions que tu fisses pour nous ce que nous allons te demander.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Jésus leur dit: «Que voulez-vous que je fasse pour vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, '— «Accorde-nous, lui dirent-ils, d\'être assis, l\'un à ta droite, l\'autre à ta gauche, quand tu seras dans ta gloire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jésus leur répondit: «Vous ne savez ce que vous demandez. Pouvez- vous boire le calice que je vais boire, et être baptisés du baptême dont je vais être baptisé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, '— «Nous le pouvons,» dirent-ils. Jésus leur répondit: «Oui, vous boirez le calice que je vais boire, et vous serez baptisés du baptême dont je vais être baptisé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'mais quant à être assis à ma droite ou à ma gauche, il ne m\'appartient pas de l\'accorder; cette distinction sera pour ceux à qui elle est réservée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Les dix autres disciples, qui avaient entendu cette demande, commencèrent à se fâcher contre Jacques et Jean.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Jésus les appela et leur dit: «Vous savez que les princes reconnus par les nations les maîtrisent, et que les grands les dominent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'il n\'en est point ainsi parmi vous: au contraire, celui qui veut être grand parmi vous sera votre serviteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'et celui qui veut être le premier, sera l\'esclave de tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Car le Fils de l\'homme est venu, non pour être servi, mais pour servir et donner sa vie pour la rançon de beaucoup.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Ils arrivèrent à Jéricho. Comme Jésus sortait de Jéricho, lui, ses disciples et une assez grande foule, le fils de Timée, Bar-Timée, mendiant aveugle, se trouvait assis sur le bord de la route.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Ayant entendu dire que c\'était Jésus de Nazareth qui passait, il se mit à crier: «Fils de David, Jésus, aie pitié de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Plusieurs le reprenaient pour le faire taire; mais il criait encore plus fort: «Fils de David, aie pitié de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jésus s\'arrêta, et dit: «Appelez-le.» On appela l\'aveugle, et on lui dit: «Courage! lève-toi, il t\'appelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Et lui, jetant son manteau, se leva d\'un bond, et vint vers Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Jésus, prenant la parole, lui dit: «Que veux-tu que je fasse pour toi?» L\'aveugle lui dit: «Rabbouni, que je recouvre la vue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, '— «Va, lui dit Jésus, ta foi t\'a guéri.» Aussitôt il recouvra la vue, et il suivit Jésus dans le chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Comme ils approchaient de Jérusalem et qu\'ils avaient atteint Bethphagé et Béthanie, vers la montagne des Oliviers, Jésus envoya deux de ses disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'en leur disant: «Allez à ce village qui est en face de vous, et vous trouverez, en y entrant, un ânon attaché, sur lequel jamais homme ne s\'est assis: détachez-le et amenez-le moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Si l\'on vous dit: «Pourquoi faites-vous cela?» dites: «Parce que le Seigneur en a besoin; et aussitôt on l\'enverra ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Ils allèrent et trouvèrent un ânon attaché à une porte, dehors, au contour du chemin, et ils le détachèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Quelques-uns de ceux qui étaient là, leur dirent: «Que faites-vous? vous détachez cet ânon?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Ils répondirent comme Jésus le leur avait dit, et on les laissa faire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Ils amenèrent l\'ânon à Jésus, jetèrent leurs manteaux sur l\'animal, et Jésus monta dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Une foule de gens étendirent leurs manteaux sur la route, d\'autres des rameaux qu\'ils avaient coupés dans les champs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Ceux qui allaient devant, et ceux qui suivaient, criaient: «Hosanna! Béni soit celui qui vient au nom du Seigneur!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, '«Béni soit le règne qui vient, le règne de David notre père! Hosanna dans les lieux très-hauts!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Jésus entra à Jérusalem, dans le temple, et, après avoir tout considéré, comme il était déjà tard, il s\'en alla à Béthanie avec les Douze.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Le lendemain, quand ils eurent quitté Béthanie, Jésus eut faim;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'et, apercevant de loin un figuier couvert de feuilles, il alla voir s\'il y trouverait quelque fruit. Il y monta, et n\'y trouva que des feuilles, car ce n\'était pas la saison des figues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Alors, prenant la parole, il dit au figuier: «Que jamais personne ne mange de ton fruit!» Et ses disciples l\'entendirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Ils arrivèrent à Jérusalem. Jésus, étant entré dans le temple, se mit à chasser ceux qui y vendaient et qui y achetaient; il renversa les tables des changeurs et les bancs des vendeurs de pigeons;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'et il ne souffrait pas qu\'on transportât aucun objet en traversant le temple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Il ajoutait cet enseignement: «N\'est-il pas écrit: «Ma maison sera appelle une maison de prière pour toutes les nations?» Mais vous, vous en avez fait une caverne de voleurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Les principaux sacrificateurs et les scribes l\'ayant entendu, cherchaient le moyen de le faire périr; car ils le craignaient, parce que tout le peuple était frappé de son enseignement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Quand le soir fut venu, Jésus sortit de la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Le lendemain matin, en passant, les disciples virent le figuier qui avait séché jusqu’à la racine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Pierre, se rappelant ce qui s\'était passé, dit à Jésus: «Rabbi, vois donc, le figuier que tu as maudit a séché.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Et Jésus leur répondit: «Ayez foi en Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'En vérité, je vous le dis, si quelqu\'un dit à cette montagne, «va te jeter à la mer,» et s\'il ne doute point en son coeur, mais qu\'il ait foi à l\'accomplissement de sa parole, cela se fera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'C\'est pourquoi je vous dis: Tout ce que vous demandez dans vos prières, ayez foi que vous l\'avez reçu, et vous le verrez s\'accomplir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Quand vous êtes debout, en prière, si vous avez quelque chose contre quelqu\'un, pardonnez, afin que votre Père qui est dans les cieux vous pardonne aussi vos offenses:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'si vous ne pardonnez pas, votre Père qui est dans les deux, ne vous pardonnera pas non plus vos offenses.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Ils arrivèrent de nouveau à Jérusalem. Pendant que Jésus allait et venait dans le temple, les principaux sacrificateurs, les scribes et les anciens se rendirent vers lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'et lui dirent: «De quel droit fais-tu ces choses, et qui t\'a donné le droit de les faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jésus leur répondit: «Je vous ferai aussi une question; répondez-moi, et je vous dirai de quel droit je fais ces choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Le baptême de Jean venait-il du ciel ou des hommes? Répondez-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Mais ils firent entre eux cette réflexion: Si nous disons «du ciel,» il dira: Pourquoi n\'y avez-vous pas cru?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Faut-il dire «des hommes?» — Ils craignaient le peuple, car tous croyaient réellement que Jean était un prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Ils répondirent à Jésus: «Nous ne savons.» Et Jésus leur dit: «Moi non plus, je ne vous dirai pas de quel droit je fais ces choses.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Il se mit alors à leur parler en paraboles. «Un homme planta une vigne, il l\'entoura d\'une haie, creusa un pressoir, bâtit une tour, puis il l\'afferma à des vignerons et quitta le pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Au temps des vendanges, il envoya un serviteur aux vignerons pour recevoir d\'eux une part de la récolte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'mais les vignerons l\'ayant pris, le battirent et le renvoyèrent les mains vides.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Le maître leur envoya encore un autre serviteur: ils le frappèrent à la tête et le maltraitèrent indignement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Il en envoya un troisième, qu\'ils tuèrent; et ils en maltraitèrent beaucoup d\'autres, battant les uns, tuant les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Le maître avait encore un fils unique, un fils bien-aimé, il le leur envoya le dernier, se disant: «Ils respecteront mon fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mais ces vignerons se dirent entre eux: «C\'est l\'héritier; venez, tuons-le, et l\'héritage sera à nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Là-dessus, ils le prirent, le tuèrent et le jetèrent hors de la vigne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Que fera donc le maître de la vigne? — Il viendra, fera périr ces vignerons, et donnera la vigne à d\'autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Vous n\'avez pas lu non plus ce passage de l\'Ecriture: «La pierre, que les constructeurs avaient mise au rebut, est devenue la pierre angulaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'C\'est par la volonté du Seigneur qu\'elle l’est devenue, et elle est une merveille à nos yeux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Les sénateurs cherchaient à l\'arrêter, mais la crainte du peuple les retint: ils avaient compris que c\'était à eux que s\'adressait cette parabole. Ils le quittèrent et s\'en allèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Ils envoyèrent vers lui des pharisiens et des hérodiens, pour lui faire une question insidieuse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Ceux-ci vinrent lui dire: «Maître, nous savons que tu es vrai, et que tu ne te soucies de qui que ce soit, car tu ne fais pas acception de personnes, mais tu enseignes en toute vérité la voie de Dieu. Est-il permis, ou non, de payer le tribut à César?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Devons-nous payer, oui ou non?» Mais Jésus connaissant leur hypocrisie, leur dit: «Pourquoi essayez-vous de me surprendre? Apportez-moi un denier, que je le voie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Ils en apportèrent un; et Jésus leur dit: «De qui sont cette effigie et cette légende?» — «De César,» lui dirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Jésus reprit: «Rendez à César ce qui est à César, et à Dieu ce qui est à Dieu.» Et il les étonna par sa réponse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Des sadducéens, gens qui prétendent qu\'il n\'y a point de résurrection, vinrent vers Jésus, et lui posèrent cette question:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '«Maître, Moïse nous a donné cette loi: «Si un frère meurt et qu\'il laisse une femme sans laisser d\'enfants, que son frère épouse la veuve et suscite lignée à son frère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Il y avait sept frères: le premier se maria, et mourut sans laisser de postérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Le second épousa la veuve, et mourut aussi sans postérité. Le troisième pareillement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Enfin aucun des sept frères ne laissa de postérité. Après eux tous, la femme mourut aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Duquel d\'entre eux sera-t-elle la femme dans la résurrection, lorsqu\'ils seront ressuscités, car tous les sept l\'ont épousée?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jésus leur répondit: «N\'est-ce pas, parce que vous ne connaissez ni les Écritures, ni même la puissance de Dieu, que vous êtes dans l\'erreur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Quand on ressuscitera, ni hommes, ni femmes ne se marieront, mais ils seront comme les anges qui sont dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Quant aux morts, nul doute qu\'ils ne ressuscitent. N\'avez-vous pas lu dans le livre de Moïse, dans le passage où il est parlé du buisson, comment Dieu s\'exprima, quand il dit à Moïse: «Je suis le Dieu d\'Abraham, le Dieu d’Isaac et le Dieu de Jacob?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Il n\'est pas Dieu des morts, mais Dieu des vivants. Vous êtes donc dans une grande erreur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Un scribe témoin de cette discussion, trouvant que Jésus leur avait bien répondu, s\'approcha, et lui demanda: «Quel est le premier de tous les commandements?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jésus répondit: «Le premier commandement, c\'est: «Ecoute Israël: le Seigneur notre Dieu et le seul Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'et tu aimeras le Seigneur ton Dieu de tout ton coeur, de toute ton âme, de toute ta pensée et de toute ta force.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Voici le second: «Tu aimeras ton prochain comme toi-même.» Il n\'y a pas d\'autre commandement plus grand que ceux-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Le scribe lui dit: «Maître, tu as vraiment bien parlé, quand tu as dit qu\'il est le «seul Seigneur,» et qu\'il n\'y en a point d\'autre que lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'et que «l\'aimer de tout son coeur, de toute sa pensée, de toute son âme et de toute sa force, et aimer son prochain comme soi-même,» c\'est plus que tous les holocaustes et tous les sacrifices.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Jésus, voyant qu\'il avait sagement répondu, lui dit: «Tu n\'es pas loin du royaume de Dieu.» Et personne n\'osait plus lui poser de questions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Jésus, continuant à enseigner dans le temple, ajouta: «Comment se fait-il que les scribes disent que le Messie est fils de David?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'David lui-même, animé du Saint-Esprit, a dit: «Le Seigneur dit à mon Seigneur: «Assieds-toi à ma droite jusqu\'à ce que j’aie fait de tes ennemis ton marchepied,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David lui-même l\'appelle «Seigneur,» et d\'où vient qu\'il est son fils?» Et la masse du peuple prenait plaisir à l\'entendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Il leur disait encore dans son enseignement: «Gardez-vous des scribes, qui aiment à se promener en robes, qui recherchent les salutations dans les places publiques,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'les premiers sièges dans les synagogues et les premières places dans les repas:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'ces gens qui dévorent les maisons des veuves, sous prétexte de longues prières, seront jugés d\'autant plus sévèrement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Jésus, s\'étant assis en face du trésor, observait la foule qui mettait de l\'argent dans le tronc. Plusieurs riches y mettaient beaucoup.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Il vint une pauvre veuve qui y mit deux pites, ce qui vaut un quart de sol.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Alors Jésus, ayant appelé ses disciples, leur dit: «Je vous assure que cette pauvre veuve a donné plus que tous ceux qui ont mis dans le tronc,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'car tous ont mis de leur superflu, tandis qu\'elle a donné de son nécessaire, tout ce qu\'elle possédait, tout ce qu\'elle avait pour vivre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Comme il sortait du temple, un de ses disciples lui dit: «Maître, vois donc, quelles pierres et quelles constructions!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Et Jésus lui dit: «Tu vois ces grandes constructions? Eh bien! il n\'y restera pierre sur pierre qui ne soit renversée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Comme il était assis sur la montagne des Oliviers, en face du temple, Pierre, Jacques, Jean et André lui demandèrent en particulier:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '«Dis-nous quand ces événements doivent avoir lieu, et quel sera le signe précurseur de leur accomplissement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jésus se mit à leur dire: «Prenez garde qu\'on ne vous séduise,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'car plusieurs viendront sous mon nom, disant: «C\'est moi qui suis le Messie;» et ils séduiront beaucoup de monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Quand vous entendrez parler de guerres et de bruits de guerre, ne vous alarmez pas; car il faut que cela arrive, mais ce ne sera pas encore la fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Une nation s\'élèvera, en effet, contre une nation, et un royaume contre un royaume; il y aura des tremblements de terre en divers lieux, il y aura des famines et des troubles. Ces calamités sont le commencement des douleurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Prenez garde à vous-mêmes; on vous livrera aux tribunaux et aux synagogues, vous serez battus, et l’on vous traduira devant les gouverneurs et devant les rois, à cause de mon nom, pour rendre témoignage devant eux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'il faut premièrement que l\'évangile soit prêché à toutes les nations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Quand on vous conduira pour vous livrer, ne vous inquiétez pas de ce que vous direz, ne vous préparez même pas, mais dites ce qui vous sera donné au moment même: ce n\'est pas vous qui parlez, c\'est le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Le frère livrera son frère à la mort, et le père, son enfant; les enfants s\'élèveront contre leurs pères et leurs mères, et les mettront à mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'et vous serez haïs de tous à cause de mon nom; mais celui qui persévérera jusqu’à la fin sera sauvé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Or, quand vous verrez l\'abomination cause de la désolation établie là où elle ne doit pas être (que celui qui lit y réfléchisse), alors, que ceux qui sont en Judée s\'enfuient dans les montagnes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'que celui qui est sur le toit, ne descende pas dans la maison, qu\'il n\'entre pas même prendre quoi que ce soit chez lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'et que celui qui est allé dans son champ, ne revienne pas en arrière pour prendre son manteau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Priez pour que cela n\'arrive pas en hiver;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'car il y aura dans ce temps une détresse telle, qu\'il n\'y en a point eu depuis le commencement du monde que Dieu a créé, jusqu’à nos jours, et qu\'il n\'y en aura jamais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Et si le Seigneur n\'avait abrégé ce temps, nul n\'échapperait; mais il l\'a abrégé à cause des élus qu\'il a choisis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, '«Si l\'on vous dit alors: «Le Messie est ici,» ou bien «le Messie est là,» ne le croyez point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'car il s\'élèvera de faux prophètes, qui feront des miracles et des prodiges pour séduire, s\'il était possible, les élus mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Pour vous, prenez garde; vous êtes prévenus de tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Mais en ce temps-là et après cette détresse, le soleil pâlira, la lune refusera sa lumière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'les étoiles tomberont du ciel et les puissances qui sont dans les cieux seront ébranlées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Alors on verra le Fils de l\'homme venir dans les nuées, revêtu d\'une grande puissance et de gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Alors il enverra les anges pour rassembler les élus, des quatre vents, d\'un bout du monde à l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Tirez instruction de la comparaison avec le figuier. Dès que sa branche devient tendre et que les feuilles poussent, on connaît que l\'été est proche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'de même, quand vous verrez ces événements se produire, sachez que le Fils de l\'homme est proche: il est à vos portes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'En vérité, je vous dis que cette génération ne passera point, que tous ces événements n\'arrivent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Quant au jour ou à l\'heure, nul ne les sait, pas même les anges qui sont dans le ciel, ni même le Fils, mais le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Prenez garde, veillez, car vous ne savez quand ce sera le moment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Il en est du Fils de l’homme comme d\'un homme, qui, en quittant sa maison pour aller en voyage, a laissé ses serviteurs maîtres, et qui, en assignant à chacun sa tâche, a enjoint au portier de veiller.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Veillez donc, car vous ne savez quand le maître de la maison doit arriver, si ce sera le soir, ou à minuit, ou au chant du coq, ou le matin;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'craignez qu\'en arrivant tout à coup, il ne vous trouve endormis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Ce que je vous dis, je le dis à tous: Veillez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'La Pâque et la fête des Pains sans levain devaient avoir lieu deux jours après. Les principaux sacrificateurs cherchaient le moyen d\'arrêter Jésus par ruse, pour le mettre à mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'car ils disaient: «Il ne faut pas que ce soit pendant la fête, de peur qu\'il n\'y ait du tumulte parmi le peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Comme Jésus était à Béthanie, dans la maison de Simon le lépreux, et qu\'il était à table, une femme entra avec un flacon d\'albâtre contenant une essence de nard pur de grand prix. Elle ouvrit le flacon, et lui versa le parfum sur la tête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Or il y avait là des gens qui en témoignaient entre eux leur mécontentement: «Pourquoi perdre ainsi ce parfum?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'On aurait pu le vendre plus de trois cents deniers, et les donner aux pauvres;» et ils se fâchaient contre elle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mais Jésus dit: «Laissez-la; pourquoi lui faites-vous de la peine? Elle a fait une bonne action à mon égard.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Vous aurez toujours des pauvres avec vous, et, quand vous voudrez, vous pourrez leur faire du bien; mais vous ne m\'aurez pas toujours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Elle a fait ce qu\'elle a pu; elle a embaumé d\'avance mon corps pour la sépulture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'En vérité, je vous dis que partout où l\'évangile sera prêché, dans le monde entier, ce qu\'elle a fait sera aussi raconté en mémoire d\'elle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Judas l\'iscariote, l\'un des Douze, alla trouver les principaux sacrificateurs pour leur livrer Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Cette ouverture les remplit de joie, et ils promirent de lui donner de l\'argent. Judas cherchait donc une occasion favorable pour le livrer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Le premier jour des Pains sans levain, où l’on immolait la pâque, les disciples de Jésus lui dirent: «où veux-tu que nous allions te préparer le repas de la Pâque?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Alors il envoya deux de ses disciples, et leur dit: «Allez à la ville; vous rencontrerez un homme portant une cruche d\'eau, suivez-le.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Et, en quelque lieu qu\'il entre, dites au maître de la maison: «Le maître te fait dire: «Ou est la salle qui m\'est réservée pour manger la pâque avec mes disciples?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Et lui-même vous montrera une grande salle haute, meublée et toute prête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Préparez-nous-y la pâque.» Ses disciples partirent; ils vinrent à la ville, trouvèrent les choses comme il le leur avait dit, et ils préparèrent la pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Jésus vint le soir avec les Douze.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Pendant qu\'ils étaient à table et qu\'ils mangeaient, Jésus dit: «En vérité, je vous dis que l\'un de vous me livrera, oui, celui qui mange avec moi!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'La tristesse les saisit, et ils se mirent à lui dire l\'un après l\'autre: «Est-ce moi? Est-ce moi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Il leur dit: «C\'est l\'un des Douze; oui, celui qui mange au même plat que moi!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Le Fils de l\'homme s\'en va selon ce qui est écrit de lui, mais malheur à l\'homme par qui le Fils de l\'homme est livré! Mieux vaudrait pour cet homme-là n\'être point né.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Pendant le repas, Jésus prit du pain, et, après avoir prononcé la bénédiction, il le rompit, et le leur donna en disant: «Prenez, ceci est mon corps.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Puis il prit une coupe, et, ayant rendu grâces, il la leur donna; et ils en burent tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Et il leur dit: «Ceci est mon sang, le sang de l\'alliance, qui sera répandu pour beaucoup de gens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'En vérité, je vous dis que je ne boirai plus du fruit de la vigne, jusqu\'au jour où j\'en boirai du nouveau dans le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Puis ils chantèrent les cantiques, et s\'en allèrent à la montagne des Oliviers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Jésus leur dit: «Je serai pour tous une occasion de chute, car il est écrit: «Je frapperai le berger, et les brebis seront dispersées.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mais, après que je serai ressuscité, je vous précéderai en Galilée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Pierre lui dit: «Quand tu serais pour tous une occasion de chute, tu ne le seras point pour moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jésus lui repartit: «En vérité, je te dis que toi, aujourd\'hui, cette nuit même, avant que le coq ait chanté deux fois, tu m\'auras renié trois fois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mais Pierre renchérissant, lui dit: «Quand je devrais mourir avec toi, non, je ne te renierai point.» Et tous protestèrent de même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Ils arrivèrent en un lieu nommé Gethsémané, et Jésus dit à ses disciples: «Asseyez-vous ici, jusqu’à ce que j\'aie prié.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Il prit avec lui Pierre, Jacques et Jean, et commença à être rempli d\'effroi et d\'angoisse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'et il leur dit: «Mon âme est saisie d\'une tristesse mortelle; restez ici et veillez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Puis, ayant fait quelques pas en avant, il se jeta à genoux sur la terre, et il priait que, s\'il était possible, cette heure passât loin de lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'et il disait: «Abba, Père, toutes choses te sont possibles, éloigne de moi ce calice; toutefois que ta volonté soit faite, et non la mienne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Il vint vers ses disciples, et, les trouvant endormis, il dit à Pierre: «Simon, tu dors! Tu n\'as pu veiller une heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Veillez et priez, de peur que vous ne tombiez en tentation: l\'esprit est plein d\'ardeur, mais la chair est faible.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Il s\'éloigna de nouveau, et pria en répétant la même parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Puis il revint et les trouva de nouveau endormis, car leurs yeux étaient appesantis, et ils ne savaient que lui répondre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Il vint pour la troisième fois vers eux, et leur dit: «C\'est trop dormir et vous reposer; assez! L\'heure est venue; le Fils de l\'homme va être livré entre les mains des pécheurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levez-vous, allons! voici, celui qui me livre est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Au même moment, comme il parlait encore, arriva Judas l\'iscariote, qui était l\'un des Douze, et avec lui une troupe armée d\'épées et de bâtons, qui avait été envoyée par les principaux sacrificateurs, par les scribes et par les anciens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Le traître était convenu avec eux d\'un signe; il leur avait dit: «Celui que je baiserai, c\'est lui; saisissez-le et l\'emmenez sûrement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Dès qu\'il fut arrivé, il s\'approcha de Jésus et lui dit: «Rabbi, Rabbi,» et il le baisa.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Les autres mirent la main sur Jésus, et l\'arrêtèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Un de ceux qui étaient présents, ayant tiré l\'épée, frappa le serviteur du souverain sacrificateur et lui emporta l\'oreille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jésus, prenant la parole, leur dit: «Vous êtes venus me prendre avec des épées et des bâtons, comme si vous poursuiviez un brigand.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Tous les jours, j\'étais assis au milieu de vous dans le temple, y enseignant, et vous ne m\'avez pas arrêté; mais il faut que les Écritures s\'accomplissent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Alors ses disciples l\'abandonnèrent et s\'enfuirent tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Un jeune homme le suivait, n\'ayant qu\'un drap sur le corps. Les jeunes gens le saisirent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'mais lui, ayant lâché le drap, leur échappa tout nu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Ils emmenèrent Jésus vers le souverain sacrificateur, chez qui tous les principaux sacrificateurs, les anciens et les scribes s\'assemblèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Pierre suivit Jésus de loin, jusque dans l\'intérieur de la cour du souverain sacrificateur, et, s\'étant assis avec les agents, il se chauffait vers le feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Les principaux sacrificateurs et tout le sanhédrin cherchaient quelque déposition contre Jésus, pour le mettre à mort, et ils n\'en trouvaient point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'car plusieurs déposaient faussement contre lui, mais les dépositions ne s\'accordaient pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Alors des gens se présentèrent qui portèrent contre lui un faux témoignage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'disant: «Nous l\'avons, nous-mêmes, entendu dire: «Je détruirai ce temple élevé par la main des hommes, et en trois jours j\'en bâtirai un autre, qui ne sera pas fait de main d\'homme;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'et même sur ce point, leurs témoignages ne concordaient pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Alors le souverain sacrificateur se leva, et, s\'étant avancé au milieu de l\'assemblée, il interrogea Jésus, disant: «Ne réponds-tu rien? Qu\'est-ce que ces gens déposent contre toi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mais Jésus garda le silence, et ne répondit rien. Le souverain sacrificateur l\'interrogea de nouveau, et lui dit: «Es-tu le Messie, le Fils du Dieu béni?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, '— «Je le suis, répondit Jésus; et vous verrez le Fils de l\'homme siéger à la droite du Tout-Puissant, et venir sur les nuées du ciel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Le souverain sacrificateur déchira ses tuniques, et dit: «Qu\'avons-nous encore besoin de témoins?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vous avez entendu le blasphème: que vous en semble?» Tous prononcèrent qu\'il méritait la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Quelques-uns se mirent à cracher sur lui, et, lui ayant bandé les yeux, ils lui donnaient des coups de poing, et lui disaient: «Devine.» Et les agents le reçurent en le souffletant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Pendant que Pierre était en bas, dans la cour, il vint une des servantes du souverain sacrificateur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'qui, voyant Pierre se chauffer, dit en l\'envisageant: «Toi aussi, tu étais avec le Nazaréen, ce Jésus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Il le nia, disant: «Je ne sais pas, je ne comprends pas ce que tu veux dire;» là-dessus, il s\'en alla, gagnant la cour extérieure, et un coq chanta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'La servante, le voyant qui s\'en allait, se mit de nouveau à dire à ceux qui étaient là: «Voilà un de ces gens-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Pierre le nia une seconde fois. Un instant après, encore, ceux qui étaient là dirent à Pierre: «Certainement tu es des leurs, car tu es Galiléen.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Mais il se mit à faire des imprécations et à dire avec serment: «Je ne connais pas l\'homme dont vous parlez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Alors, pour la seconde fois, un coq chanta, et Pierre se ressouvint de la parole que Jésus lui avait dite: «Avant que le coq ait chanté deux fois, tu m\'auras renié trois fois;» à cette pensée, il pleura.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Dès le matin, les principaux sacrificateurs, après avoir tenu conseil avec les anciens, les scribes et tout le sanhédrin, firent lier Jésus, l\'emmenèrent et le livrèrent à Pilate.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilate l\'interrogea: «C\'est toi, qui es le roi des Juifs?» — «Tu le dis,» lui répondit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Comme les principaux sacrificateurs le chargeaient de plusieurs crimes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilate l\'interrogea de nouveau, disant: «Tu ne réponds rien? Vois donc, de combien de crimes ils te chargent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mais Jésus ne fit plus aucune réponse, ce qui étonna Pilate.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'A chaque fête, il relâchait un prisonnier, celui que le peuple demandait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Or, on tenait en prison le nommé Barrabas, avec ses complices, pour un meurtre commis dans une émeute.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'La foule étant montée au prétoire, se mit à demander l’élargissement d’un prisonnier, ainsi qu\'il le leur accordait toujours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilate leur répondit: «Voulez-vous que je vous relâche le roi des Juif?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'car il comprenait que c\'était par envie que les principaux sacrificateurs l\'avaient livré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mais les principaux sacrificateurs agitèrent le peuple, afin que Pilate leur relâchât plutôt Barrabas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilate reprenant la parole, leur dit: «Que voulez-vous donc que je fasse de celui que vous appelez le roi des Juifs?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Ils crièrent de nouveau: «Crucifie-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, '— «Quel mal a-t-il fait?» leur dit Pilate. Ils crièrent encore plus fort: «Crucifie-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilate, voulant satisfaire le peuple, lui relâcha Barrabas, et, après avoir fait flageller Jésus, il le livra pour être crucifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Les soldats l\'emmènent dans l\'intérieur de la cour, c’est-à-dire, dans le prétoire, et appellent toute la cohorte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Ils l\'affublent d’un manteau de pourpre, et tressent une couronne d\'épines, dont ils ceignent sa tête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Puis ils se mettent à le saluer: «Salut, roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Et ils le frappent sur la tête avec un roseau, crachent sur lui, et fléchissent les genoux par manière d\'hommage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Quand ils l\'eurent bafoué, ils lui ôtèrent la pourpre et le revêtirent de ses propres vêtements. Après cela, ils l\'emmènent pour le crucifier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Ils mettent en réquisition, pour porter sa croix, un passant qui venait des champs, Simon de Cyrène, le père d\'Alexandre et de Rufus;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'et ils entraînent Jésus à la place de Golgotha, ce qui signifie: la place du Crâne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Ils lui présentent du vin aromatisé avec de la myrrhe, mais il n\'en prit pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Ils le crucifient, et se partagent ses vêtements en tirant au sort pour savoir qui aurait telle ou telle pièce:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'c\'était la troisième heure du jour quand on le crucifia.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'L\'inscription indiquant le sujet de sa condamnation, portait: «Le Roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Ils crucifient avec lui deux brigands, l\'un à sa droite, l\'autre à sa gauche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '[Et ainsi s\'accompli le passage de l\'Ecriture qui dit «Et il a été mis au nombre des malfaiteurs.»]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Les passants l\'insultaient en branlant la tête, et en disant: «Hé! toi qui détruis le temple, et qui le rebâtis en trois jours,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'sauve-toi toi-même en descendant de ta croix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Les principaux sacrificateurs aussi, avec les scribes, le raillaient entre eux, et disaient: «Il en a sauvé d\'autres, et il ne peut se sauver lui-même!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que le Messie, le roi d\'Israël descende maintenant de la croix, pour que nous voyions et que nous croyions» Les brigands qui étaient crucifiés avec lui, l\'insultaient également.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'A la sixième heure, des ténèbres se répandirent sur tout le pays jusqu’à la neuvième.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'A la neuvième heure, Jésus cria d\'une voix forte: «Éloï, Éloï, lema sabachtani,» ce qui signifie: mon Dieu, mon Dieu, pourquoi m\'as-tu abandonné?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Quelques-uns des assistants l\'ayant entendu, dirent: «Tenez, il appelle Élie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Il y en eut un qui courut tremper une éponge dans du vinaigre, et l\'ayant ajustée à une tige, il lui donna à boire, disant: «Laissez, voyons si Élie viendra l\'ôter de la croix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Mais Jésus, ayant poussé un grand cri, expira.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Le voile du temple se déchira en deux, depuis le haut jusqu\'en bas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Le centurion, qui était en face de Jésus, voyant qu\'il avait expiré en jetant un tel cri, dit: «Assurément, cet homme était Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Il y avait aussi des femmes qui regardaient de loin, entre autres Marie Madeleine, Marie, mère de Jacques le mineur et de Joses, et Salomé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'qui suivaient Jésus et l\'assistaient, lorsqu\'il était en Galilée, et plusieurs autres qui étaient montées avec lui à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Comme c\'était le jour de la préparation, c’est-à-dire, la veille du sabbat,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Joseph d\'Arimathée arriva sur le soir: c\'était un sénateur distingué par ses manières; il attendait, lui aussi, le royaume de Dieu. Il avait osé se rendre auprès de Pilate, pour lui demander le corps de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilate, surpris de ce que Jésus était déjà mort, fit venir le centurion et lui demanda s\'il y avait longtemps que Jésus était mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'et, sur le rapport du centurion, il accorda gratuitement le cadavre à Joseph.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Alors Joseph, ayant acheté un linceul, descendit Jésus de la croix, l\'enveloppa dans le linceul, le déposa dans un sépulcre taillé dans le roc, et roula une pierre à l\'entrée du sépulcre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Marie Madeleine et Marie, mère de Joses, observaient le lieu où l’on mettait le corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Quand le sabbat fut passé, Marie Madeleine, Marie, mère de Jacques, et Salomé achetèrent des aromates, afin d\'aller embaumer Jésus;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'et, le premier jour de la semaine, de très-grand matin, elles arrivèrent au sépulcre au moment où le soleil venait de se lever.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Elles se disaient entre elles: «Qui nous ôtera la pierre de l\'entrée du sépulcre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Et, ayant levé les yeux, elles aperçurent que la pierre était ôtée, car elle était extrêmement grosse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Étant entrées dans le sépulcre, elles virent un jeune homme assis à droite, vêtu d\'une robe blanche; et elles furent bouleversées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Il leur dit: «Ne vous bouleversez pas. Vous cherchez Jésus de Nazareth, qui a été crucifié; il est ressuscité; il n\'est point ici: voilà la place où on l\'avait mis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mais allez dire à ses disciples et à Pierre, qu\'il vous précède en Galilée: c\'est là que vous le verrez, comme il vous l\'a dit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Elles sortirent et s\'enfuirent du sépulcre. Le tremblement et l\'émotion les avaient saisies; et elles ne dirent rien à personne, parce qu\'elles étaient effrayées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, '[Or Jésus, étant ressuscité le matin du premier jour de la semaine, apparut d\'abord à Marie Madeleine, de laquelle il avait chassé sept démons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Elle alla en porter la nouvelle à ceux qui avaient été avec lui, et qui étaient dans le deuil et dans les larmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Quand ils entendirent que Jésus était vivant, et qu\'elle l’avait vu, ils ne la crurent point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Ensuite Jésus se montra en chemin, sous une autre forme que la sienne, à deux d\'entre eux. qui allaient à la campagne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Eux aussi vinrent l\'annoncer aux autres disciples, mais ils le les crurent pas davantage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Plus tard, il se montra aux Onze eux-mêmes, pendant qu\'ils étaient à table. Il leur reprocha leur incrédulité et leur obstination à ne pas croire ceux qui l’avaient vu ressuscité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'et il ajouta: «Allez par tout le monde, et prêchez l’évangile à toute créature.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Celui qui croira et qui sera baptisé, sera sauvé; mais celui qui ne croira pas sera condamné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Voici les miracles qui accompagneront ceux qui auront cru: en mon nom, ils chasseront les démons; ils parleront de nouvelles langues;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'ils prendront les serpents; s\'ils boivent quelque breuvage mortel, ils n\'en ressentiront aucun mal; ils guériront les malades en leur imposant les mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Après leur avoir ainsi parlé, le Seigneur fut enlevé au ciel et il s\'assit à la droite de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Pour eux, ils allèrent prêcher en tous lieux. Le Seigneur les assistait dans leur oeuvre, et confirmait sa Parole par les miracles qui l\'accompagnaient.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Plusieurs ayant entrepris d\'écrire l\'histoire des événements qui se sont accomplis parmi nous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'd\'après ce que nous ont enseigné ceux qui en ont été les témoins oculaires dès le commencement, et qui sont devenus les ministres de la Parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'j\'ai cru devoir aussi, après m\'être soigneusement enquis de tous les faits, dès leur origine, te les raconter dans leur ordre, excellent Théophile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'afin que tu reconnaisses la vérité des récits qui ont fait la matière de ton instruction.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Il y avait du temps d\'Hérode, roi de Judée, un sacrificateur nommé Zacharie; il appartenait à la classe d\'Abia, et sa femme, qui était une fille d\'Aaron, se nommait Elisabeth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Ils étaient tous deux justes devant Dieu, et observaient tous les commandements et ordonnances du Seigneur, de manière à être sans reproches.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Ils n\'avaient point d\'enfants, parce qu\'Élisabeth était stérile; et ils étaient l\'un et l\'autre avancés en âge.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Quand vint le tour de sa classe, et qu\'il dut officier devant Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'il fut désigné par le sort, selon les usages du sacerdoce, pour aller offrir les parfums dans le sanctuaire du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Pendant que tout le peuple était dehors en prières, à l\'heure qu\'on offre les parfums,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'un ange du Seigneur lui apparut debout, à droite de l\'autel des parfums.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Zacharie fut troublé à sa vue, et la frayeur s\'empara de lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'mais l\'ange lui dit: «Ne crains point, Zacharie, car ta prière a été exaucée: Elisabeth, ta femme, te donnera un fils, et tu le nommeras Jean;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'il sera pour toi un sujet de joie et d\'allégresse, et beaucoup se réjouiront de sa naissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Car il sera grand devant le Seigneur; il ne boira ni vin, ni liqueur enivrante, et il sera rempli du Saint-Esprit dès le sein de sa mère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'il convertira bien des fils d\'Israël au Seigneur leur Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'et lui-même marchera devant Dieu dans l\'esprit et la vertu d\'Élie, pour «ramener les coeurs des pères vers les enfants,» et les rebelles aux sentiments des justes, afin de préparer au Seigneur un peuple bien disposé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Zacharie dit à l\'ange: «A quoi reconnaîtrai-je la vérité de ce que tu m\'annonces? car je suis vieux, et ma femme est déjà avancée en âge.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'L\'ange lui répondit: «Je suis Gabriel, je me tiens devant Dieu; j\'ai été envoyé pour te parler, et pour t\'annoncer ces heureuses nouvelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Voici, tu seras muet, et tu ne pourras plus parler jusqu\'au jour où se réalisera cette promesse, parce que tu n\'as pas ajouté foi à mes paroles, qui s\'accompliront en leur temps.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Cependant le peuple attendait Zacharie, et s\'étonnait qu\'il demeurât aussi longtemps dans le sanctuaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Quand Zacharie sortit, il ne pouvait leur parler; et ils comprirent qu\'il avait eu une vision dans le sanctuaire, ce que lui-même confirmait par signes: et il resta muet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Lorsque les jours de son office furent accomplis, il s\'en retourna chez lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Quelque temps après, Elisabeth, sa femme, devint enceinte, et elle se tint cachée durant cinq mois, «parce que, disait-elle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'c\'est une grâce cachée que le Seigneur m\'a faite, quand il a daigné ôter l\'opprobre qui pesait sur moi aux yeux des hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Au sixième mois, Dieu envoya l\'ange Gabriel dans une ville de Galilée, appelée Nazareth,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'vers une vierge fiancée à un homme de la famille de David, nommé Joseph. Cette vierge se nommait Marie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'L\'ange lui dit en entrant: «Je te salue, toi qui es l\'objet d\'une grande grâce; le Seigneur est avec toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Cette parole la troubla; et elle se demandait ce que pouvait bien être cette salutation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'L\'ange lui dit: «Ne crains point, Marie, car tu as trouvé grâce devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Tu concevras en ton sein, et tu enfanteras un fils; et tu lui donneras le nom de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Il sera grand; on l\'appellera Fils du Très-Haut; le Seigneur Dieu lui donnera le trône de David, son père;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'il régnera éternellement sur la maison de Jacob, et son règne n\'aura point de fin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Mais Marie dit à l\'ange: «Comment cela se fera-t-il, puisque je ne connais point d\'homme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'L\'ange lui répondit: «Le Saint-Esprit viendra sur toi, et la puissance du Très-Haut te couvrira de son ombre; aussi l\'être saint qui naîtra de toi, sera-t-il appelé Fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Et voici, Elisabeth, ta parente, a, elle aussi, conçu un fils dans sa vieillesse, et celle qu\'on appelait stérile est dans son sixième mois:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'rien ne sera impossible à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Marie lui dit: «Je suis la servante du Seigneur; qu\'il me soit fait selon ta parole.» Et l\'ange la quitta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Dans ce même temps Marie partit, et s\'en alla en hâte au pays des montagnes, dans une ville de Juda;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'étant entrée dans la maison de Zacharie, elle salua Elisabeth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Dès qu\'Elisabeth eut entendu la salutation de Marie, son enfant tressaillit dans son sein, et elle fut remplie du Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Elle s\'écria à haute voix: «Tu es bénie entre les femmes, et le fruit que tu portes est béni.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Et d\'où me vient cet honneur, que la mère de mon Seigneur vienne me visiter?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Car, sitôt que la voix de ta salutation a frappé mon oreille, mon enfant a tressailli de joie dans mon sein.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Heureuse celle qui a cru à l\'accomplissement de ce que le Seigneur lui a fait annoncer!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Et Marie dit: «Mon âme glorifie le Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'et mon esprit est ravi de joie en Dieu, mon Sauveur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'parce qu\'il a jeté les yeux sur la bassesse de sa servante. «Car désormais toutes les générations me diront bienheureuse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'parce que le Tout-Puissant a fait en moi de grandes choses: son nom est saint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'et sa miséricorde détend d\'âge en âge sur ceux qui le craignent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Il a déployé la force de son bras; il a dissipé ceux qui s\'enorgueillissaient dans les pensées de leurs coeurs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'il a renversé les puissants de leurs trônes, et il a élevé les petits;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'il a comblé de biens les affamés, et il a renvoyé les riches les mains vides.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Il s\'est intéressé à Israël son serviteur, et, comme il l\'avait dit à nos pères, il s\'est souvenu de sa miséricorde');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'envers Abraham et sa postérité, pour toujours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marie demeura avec Elisabeth, environ trois mois, puis elle s\'en retourna dans sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Cependant Elisabeth, étant arrivée à son terme, mit au monde un fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Ses voisins et ses parents, ayant appris la grâce signalée que le Seigneur lui avait faite, l\'en félicitèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Le huitième jour, on vint circoncire l’enfant, et on lui donnait le nom de Zacharie, qui était le nom de son père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'lorsque sa mère prit la parole, et dit: «Non; il s\'appellera Jean.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Ils lui dirent: «Il n\'y a personne dans ta famille qui porte ce nom-là;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'et ils demandèrent par signes au père de l\'enfant, comment il voulait qu\'on le nommât.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Zacharie ayant demandé des tablettes, écrivit ces mots: «Son nom est Jean;» et ils en furent tous étonnés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Au même instant, sa bouche s\'ouvrit, sa langue se délia, il parlait, bénissant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'La crainte saisit tous les habitants des alentours, et, dans tout le pays des montagnes de la Judée, on parla de ces événements.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Tous ceux qui les apprirent, les serraient dans leur coeur en disant: «Que sera-donc cet enfant?» En effet, la main du Seigneur était avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Zacharie, son père, fut rempli du Saint-Esprit, et il prophétisa en ces termes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '«Béni soit le Seigneur, le Dieu d\'Israël, de ce qu\'il a visité et racheté son peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Il nous a suscité une Puissance libératrice dans la maison de David, son serviteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'selon qu\'il en avait parlé par la bouche de ses saints prophètes des temps anciens,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'une Puissance qui nous délivrera de nos ennemis, et des mains de tous ceux qui nous haïssent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Il a voulu faire miséricorde à nos pères, et il s\'est souvenu de sa sainte alliance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'selon la promesse qu\'il avait faite par serment à Abraham, notre père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'de nous donner, lorsque nous serions délivrés des mains de nos ennemis, de le servir sans crainte,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'en pratiquant sous son regard la sainteté et la justice tous les jours de notre vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, '«Et toi, petit enfant, tu seras appelé prophète du Très-Haut; car tu marcheras devant la face du Seigneur, pour préparer ses voies,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'afin qu\'il donne à son peuple la connaissance du salut par le pardon de ses péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Car notre Dieu, dans ses tendres compassions, a fait lever d\'en haut, sur nous, un soleil');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'qui doit éclairer ceux qui sont dans les ténèbres et dans l\'ombre de la mort, afin de diriger nos pas dans le chemin de la paix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Or, le petit enfant croissait, il se fortifiait en esprit; et il se tenait dans les déserts, jusqu\'au jour où il se fit connaître à Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'En ce temps-là parut un édit de César-Auguste, portant l\'ordre de faire le recensement des habitants de toute la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ce recensement, le premier qui eut lieu, se fit pendant que Quirinius était gouverneur de Syrie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Tous allaient se faire enregistrer, chacun dans sa ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Joseph aussi, qui était de la maison et de la famille de David, partit de la ville de Nazareth en Galilée, pour se rendre en Judée, dans la ville de David, appelée Bethléhem,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'afin de se faire enregistrer avec Marie, qui lui était fiancée, et qui était enceinte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Pendant qu\'ils étaient à Bethléhem, le moment de la délivrance de Marie arriva:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'elle mit au monde son fils premier-né, l\'emmaillota et le coucha dans une crèche, parce qu\'il ne se trouvait pas de place pour eux dans l\'hôtellerie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Il y avait, dans cette contrée, des bergers qui passaient la nuit en plein air, pour garder leurs troupeaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Tout à coup un ange du Seigneur leur apparut, et, la gloire du Seigneur les enveloppant de son éclat, ils furent saisis d\'une grande frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'L\'ange leur dit: «Ne craignez point, car je viens vous donner une heureuse nouvelle, qui causera une grande joie à tout le peuple:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'c\'est qu\'aujourd\'hui, dans la ville de David, il vous est né un Sauveur, qui est Messie, Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'et voici à quel signe vous le reconnaîtrez: vous trouverez un enfant emmailloté, couché dans une crèche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Soudain, il se joignit à l\'ange une troupe nombreuse de l\'armée céleste, qui louait Dieu et disait:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '«Gloire à Dieu dans les lieux très-hauts! Et paix sur la terre parmi les hommes de bonne volonté!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Lorsque les anges les eurent quittés pour remonter au ciel, les bergers se dirent les uns aux autres: «Allons jusqu’à Bethléhem voir ce qui est arrivé, et que le Seigneur nous a fait savoir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Ils s\'y rendirent en toute hâte, et trouvèrent Marie, Joseph, et le nouveau-né couché dans la crèche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Après l\'avoir vu, ils divulguèrent ce qui leur avait été dit touchant ce petit enfant,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'et tous ceux qui les entendirent, furent étonnés de ce que les bergers disaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Pour Marie, elle gardait toutes ces paroles et les repassait dans son coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Les bergers s\'en retournèrent, glorifiant et louant Dieu de tout ce qu\'ils avaient entendu et vu, conformément à ce qui leur avait été annoncé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Le huitième jour, on circoncit l\'enfant, et on le nomma Jésus, nom que l\'ange lui avait donné, avant qu\'il eût été conçu dans le sein de sa mère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Et quand, selon la loi de Moïse, le jour de leur purification fut arrivé, les parents le portèrent à Jérusalem, pour le présenter au Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'selon qu\'il est écrit dans la Loi: «Tout mâle premier-né sera consacré au Seigneur,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'ainsi que pour offrir en sacrifice «une paire de tourterelles ou deux jeunes pigeons,» comme le porte la loi du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Or, il y avait à Jérusalem un homme juste et pieux, nommé Syméon, qui vivait dans l\'attente de la consolation d\'Israël; et le Saint-Esprit reposait sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Il avait été averti par l\'Esprit Saint qu\'il ne mourrait point avant d\'avoir vu l\'Oint du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Syméon vint au temple par un mouvement de l\'Esprit, et quand les parents y apportèrent l\'enfant Jésus, pour accomplir à son égard les cérémonies d\'usage selon la Loi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'il reçut l\'enfant dans ses bras, bénit Dieu, et dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '«C\'est maintenant, Maître, que, selon ta parole, tu laisses ton serviteur s\'en aller en paix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'car mes yeux ont vu ton salut,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'ce salut qui est prêt à paraître devant tous les peuples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'comme une lumière destinée à éclairer les nations, et comme la gloire de ton peuple d\'Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Le père et la mère de l’enfant étaient dans l\'admiration des choses qu\'on disait de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Syméon les bénit, et il dit à Marie, sa mère: «Cet enfant sera cause de la chute et du relèvement de bien des gens en Israël, et il sera un prodige qui rencontrera de la contradiction,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'afin que les pensées de bien des coeurs soient dévoilées; pour toi, un glaive te traversera l\'âme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Il y avait aussi une prophétesse nommée Anne, fille de Phanuel, de la tribu d\'Asser, qui était fort avancée en âge. Après avoir vécu sept ans mariée depuis sa virginité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'elle était demeurée veuve, et avait atteint l\'âge de quatre-vingt-quatre ans, ne quittant pas le temple, où elle servait Dieu, jour et nuit, dans le jeûne et dans la prière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Étant survenue, elle aussi, en ce même instant, elle se mit à louer le Seigneur, et elle parlait de l\'enfant à tous ceux qui, à Jérusalem, attendaient la délivrance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Quand Joseph et Marie eurent achevé d\'accomplir toutes les prescriptions de la loi du Seigneur, ils s\'en retournèrent en Galilée, dans leur ville de Nazareth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Cependant l\'enfant croissait et se fortifiait, rempli de sagesse; et la grâce de Dieu se répandait sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Son père et sa mère allaient tous les ans à Jérusalem, à la fête de Pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Quand il eut douze ans, ils y montèrent selon la coutume; et lorsqu\'ils s\'en retournèrent après les jours de fête,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'l\'enfant Jésus resta à Jérusalem, sans que Joseph ni sa mère s\'en fussent aperçus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Ils firent une journée de chemin, le croyant dans la caravane, et le cherchèrent parmi leurs parents et leurs connaissances;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'et ne l\'ayant point trouvé, ils retournèrent à Jérusalem pour le chercher.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Au bout de trois jours, ils le trouvèrent dans le temple, assis au milieu des docteurs, les écoutant et leur adressant des questions;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'et tous ceux qui l\'entendaient étaient ravis de son intelligence et de ses réponses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Quand Joseph et Marie le virent, ils furent frappés d\'étonnement, et sa mère lui dit: «Mon enfant, pourquoi te conduire ainsi avec nous? Nous te cherchions, ton père et moi, étant fort en peine.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Il leur dit: «Pourquoi me cherchiez-vous? Ne saviez-vous pas que je dois être dans la maison de mon Père?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Et ils ne comprirent point ce qu\'il leur disait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Il descendit avec eux, allant à Nazareth. Il leur était soumis. Sa mère gardait soigneusement toutes ces choses dans son coeur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'et Jésus croissait en sagesse, en stature et en grâce, devant Dieu et devant les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'La quinzième année du règne de Tibère César, lorsque Ponce Pilate était gouverneur de Judée, qu\'Hérode était tétrarque de la Galilée, et Philippe, son frère, tétrarque de l\'Iturie et delà Trachonite, et que Lysanias était tétrarque de l\'Abilène,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'du temps du souverain sacrificateur Anne, et de Caïphe, la parole de Dieu fut adressée dans le désert à Jean, fils de Zacharie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Il vint dans toute la contrée qui avoisine le Jourdain, prêchant le baptême de la repentance pour le pardon des péchés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'ainsi qu\'il est écrit dans le livre des discours d\'Esaïe, le prophète: «C\'est une voix qui crie au désert: «Préparez le chemin du Seigneur, faites-lui des sentiers droits:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'toute vallée, sera comblée, toute montagne et toute colline seront abaissées; ce qui est tortu sera redressé, et les chemins raboteux seront aplanis:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'et toute chair verra le salut de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Jean disait donc aux foules qui venaient se faire baptiser par lui: «Race de vipères, qui vous a appris à fuir la colère à venir?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Produisez donc des fruits dignes de la repentance, et ne vous mettez pas à dire en vous-mêmes: «Nous avons pour père Abraham;» car je vous dis que de ces pierres, Dieu peut susciter des enfants à Abraham.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Déjà même la cognée est mise à la racine des arbres; tout arbre donc qui ne produit pas de bon fruit, va être coupé et jeté au feu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Et le peuple lui demanda: «Que faut-il donc faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Il leur répondit: «Que celui qui a deux tuniques partage avec celui qui n\'en a point; et que celui qui a de quoi manger fasse de même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Des publicains vinrent aussi se faire baptiser, et lui dirent: «Maître, que devons-nous faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Il leur dit: «N\'exigez rien au delà de ce qui vous est commandé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Des militaires l\'interrogèrent aussi: «Et nous, que devons-nous faire?» Il leur dit: «Ne commettez point d\'extorsions, et ne faites de chicanes à personne; contentez- vous de votre paie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Comme le peuple était dans l\'attente, et que chacun se demandait au dedans de soi, si Jean ne serait point le Messie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Jean, s\'adressant à tous, leur dit: «Pour moi, je vous baptise d\'eau; mais il vient, celui qui est plus puissant que moi, et je ne suis pas digne de délier la courroie de ses sandales: c\'est lui qui vous baptisera d\'esprit saint et de feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Il a son van à la main, et il nettoiera son aire; il amassera le blé dans son grenier, mais il brûlera la paille dans un feu qui ne s\'éteint point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Il annonçait donc la bonne nouvelle au peuple, tout en lui adressant beaucoup d\'autres exhortations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Mais Hérode, le tétrarque, qu\'il reprit au sujet d\'Hérodiade, femme de son frère, et de toutes les mauvaises actions que lui, Hérode, avait commises,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'ajouta à tous ses crimes celui de faire jeter Jean en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Comme tout le peuple se faisait baptiser, Jésus se fit aussi baptiser; et au moment où il priait, le ciel s\'ouvrit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'le Saint-Esprit descendit sur lui sous une forme corporelle, comme une colombe; et une voix sortit du ciel, disant: «Tu es mon Fils bien-aimé; c\'est en toi que j\'ai mis toute mon affection.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Jésus avait environ trente ans, quand il commença son ministère. Il était, à ce que l\'on croyait, fils de Joseph, fils d\'Héli,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'fils de Matthat, fils de Lévi, fils de Melchi, fils de Janné, fils de Joseph,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'fils de Mattathias, fils d\'Anios, fils de Nahum, fils d\'Hesli, fils de Naggé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'fils de Maath, fils de Mattathias, fils de Semeï, fils de Joseph, fils de Juda,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'fils de Johanna, fils de Rhésa, fils de Zorobabel, fils de Salathiel, fils de Néri,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'fils de Melchi, fils d\'Addi, fils de Cosam, fils d\'Elmodain, fils de Her,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'fils de José; fils d\'Eliézer, fils de Jorim, fils de Matthat, fils de Lévi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'fils de Syméon, fils de Juda, fils de Joseph, fils de Jônan, fils d\'Eliakim,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'fils de Méléa, fils de Maman, fils de Mattatha, fils de Nathan, fils de David,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'fils d\'Issaï, fils de Jobed, fils de Booz, fils de Salmon, fils de Naasson,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'fils d\'Aminadab, fils d\'Admin, fils d\'Ami, fils d\'Esron, fils de Phares, fils de Juda,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'fils de Jacob, fils d\'Isaac, fils d\'Abraham, fils de Tharé, fils de Nachor,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'fils de Seruch, fils de Ragan, fils de Phalez, fils d\'Héber, fils de Sala,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'fils de Caïnan, fils d\'Arpaxad, fils de Sem, fils de Noé, fils de Lamech,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'fils de Mathusalem, fils d\'Hénoch, fils de Jared, fils de Maleèl, fils de Caïnan,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'fils d\'Enos, fils de Seth, fils d\'Adam, fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jésus, rempli du Saint-Esprit, revint du Jourdain, et fut poussé par un mouvement de l\'Esprit au désert:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'il y fut tenté par le diable pendant quarante jours. Il ne mangea rien dans ces jours-là, et, quand ils furent passés, il eut faim.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Le diable lui dit: «Si tu es Fils de Dieu, commande à cette pierre de se changer en pain.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Jésus lui répondit: «Il est écrit que l\'homme ne vivra pas de pain seulement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Le diable l\'ayant emmené, lui fit voir en un instant tous les royaumes de la terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'et lui dit: «Je te donnerai toute cette puissance et la gloire de ces royaumes; car elles m\'ont été données, et je les donne à qui je veux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Si donc tu te prosternes devant moi, elles t\'appartiendront tout entières.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Jésus lui répondit: «Il est écrit: «Tu adoreras le Seigneur ton Dieu, et tu le serviras lui seul.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Le diable le mena à Jérusalem, le posa à l\'extrémité de l\'aile du temple, et lui dit: «Si tu es Fils de Dieu, jette toi d\'ici en bas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'car il est écrit qu\'il ordonnera à ses anges de te garder,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'et qu\'ils te porteront sur leurs bras, de peur que ton pied ne heurte contre une pierre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jésus lui répliqua qu\'il est dit: «Tu ne tenteras point le Seigneur ton Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Et le diable ayant épuisé toute espèce de tentation, s\'éloigna de lui jusqu’à nouvelle occasion.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Jésus, animé de la puissance de l\'Esprit, s\'en retourna en Galilée, et sa renommée se répandit dans tout le pays d\'alentour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Il enseignait dans les synagogues, et tout le monde le glorifiait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Il vint à Nazareth, où il avait été élevé, et, suivant sa coutume, il entra le jour du sabbat dans la synagogue, et se leva pour faire la lecture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'On lui remit le livre du prophète Ésaïe; et, l\'ayant ouvert, il trouva l\'endroit où il est écrit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'L\'Esprit du Seigneur est sur moi, parce qu\'il m\'a oint pour annoncer l\'évangile aux pauvres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'il m\'a envoyé pour annoncer la délivrance aux captifs, et aux aveugles le recouvrement de la vue; pour renvoyer en liberté les opprimés, et pour publier une année favorable du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Puis, il ferma le livre, le rendit au desservant, et s\'assit; et tout le monde dans la synagogue avait les yeux fixés sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Il se mit à leur dire: Aujourd\'hui est accomplie la parole de l\'Écriture, comme vous venez de l\'entendre de vos oreilles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Et tous témoignaient en sa faveur; ils étaient étonnés des paroles pleines de grâce qui sortaient de sa bouche, et ils disaient: «N\'est-ce pas là le fils de Joseph?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Alors il leur dit: «Sans doute, vous m\'alléguerez le proverbe: «Médecin, guéris-toi toi-même,» et vous me direz, fais également ici, dans ta patrie, tout ce que nous avons appris que tu as fait pour Capernaoum.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Mais il ajouta: «En vérité, je vous dis qu\'aucun prophète n\'est bien venu dans son pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Vraiment, je vous le dis, il y avait beaucoup de veuves en Israël au temps d\'Élie, quand le ciel fut fermé durant trois ans et demi, et qu\'il y eut une grande famine sur toute la terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'et pourtant Élie ne fut envoyé à aucune d\'elles, mais à une veuve de Sarepta, dans le pays de Sidon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Il y avait de même beaucoup de lépreux en Israël au temps du prophète Élysée, et pourtant aucun d\'eux ne fut guéri, mais Naaman le Syrien fut seul guéri.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Ces paroles remplirent de colère tous ceux qui étaient dans la synagogue;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'ils se levèrent, entraînèrent Jésus hors de la ville, et l\'emmenèrent jusqu\'à un escarpement de la montagne sur laquelle leur ville était bâtie, pour le précipiter en bas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'mais il passa au milieu d\'eux, et s\'en alla.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Il descendit à Capernaoum, ville de Galilée, et là il enseignait les habitants les jours de sabbat;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'et ils étaient frappés de son enseignement, parce que sa parole était pleine d\'autorité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Il y avait dans la synagogue un homme possédé d\'un esprit, d\'un démon impur; il poussa un grand cri, et dit');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '«Ah! Qu\'y a-t-il entre nous et toi, Jésus de Nazareth? Tu es venu nous faire périr; je te connais, tu es le Saint de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Jésus le tança: «Tais-toi, lui dit-il, et sors de cet homme.» Et le démon, ayant jeté cet homme par terre, au milieu de la synagogue, sortit de lui, sans lui avoir fait aucun mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Tous les assistants étaient dans la stupéfaction, et ils se disaient les uns aux autres: «Quelle parole est la sienne? Il commande avec autorité et puissance aux esprits impurs, et ils sortent!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Et il n\'était bruit que de Jésus dans tous les lieux d\'alentour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Étant sorti de la synagogue, il entra dans la maison de Simon. Or la belle-mère de Simon avait une grosse fièvre, et l\'on pria Jésus de la guérir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Il se pencha sur elle, tança la fièvre, et la fièvre la quitta. A l\'instant cette femme se leva et se mit à les servir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Quand le soleil fut couché, tous ceux qui avaient des malades atteints de divers maux, les lui amenèrent; et il les guérit en imposant les mains à chacun d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Des démons aussi sortaient de plusieurs malades, en criant: «Tu es le Fils de Dieu,» et Jésus les tançait pour leur imposer silence, parce qu\'ils savaient qu\'il était le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Quand le jour parut, il sortit et s\'en alla dans un lieu désert. Une foule de gens vinrent le chercher jusqu\'au lieu où il était, et ils le retenaient pour qu\'il ne s\'éloignât pas d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mais il leur dit: «Il faut que je porte aussi à d\'autres villes la bonne nouvelle du royaume de Dieu; car c\'est dans ce but que j\'ai été envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Et il prêchait dans les synagogues de la Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Un jour que Jésus, pressé par la foule, qui voulait entendre la parole de Dieu, était acculé vers le lac de Génésareth,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'il vit deux barques qui stationnaient près du rivage. Les pêcheurs, après en être descendus, avaient nettoyé leurs filets.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Il entra dans l\'une de ces barques, qui appartenait à Simon, et le pria de s\'éloigner un peu de terre; puis, s\'étant assis, il enseigna la foule de dessus la barque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Quand il eut cessé de parler, il dit à Simon: «Avancez en pleine eau, et jetez votre filet pour pêcher.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Simon lui répondit: «Maître, nous avons travaillé toute la nuit sans rien prendre; mais, sur ta parole, nous jetterons le filet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Et l\'ayant jeté, ils prirent une si grande quantité de poissons, que leur filet se rompait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Ils firent donc signe à leurs compagnons, qui étaient dans l\'autre barque, de venir les aider. Ils vinrent, et ils remplirent les deux barques au point qu\'elles enfonçaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'A cette vue, Simon-Pierre tomba aux genoux de Jésus, et lui dit: «Éloigne-toi de moi, Seigneur, car je suis un homme pécheur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Il était, en effet, stupéfié, aussi bien que tous ceux qui étaient avec lui, de la quantité de poissons qu\'ils avaient prise.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Il en était de même de Jacques et de Jean, fils de Zébédée, qui étaient associés de Simon. Alors Jésus dit à Simon: «Ne crains point, désormais tu seras pêcheur d\'hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Et eux, ayant ramené leurs barques à terre, quittèrent tout, et le suivirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Comme il était dans une des villes de la Galilée, un homme couvert de lèpre le vit, et, se prosternant la face contre terre, lui adressa cette prière: «Seigneur, si tu le veux, tu peux me rendre net.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Jésus avançant la main, le toucha, après lui avoir dit: «Je le veux, sois net.» Aussitôt la lèpre le quitta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Il lui recommanda de n\'en parler à personne: «Mais va, lui dit-il, montre-toi au sacrificateur, et présente pour ta guérison l\'offrande que Moïse a prescrite pour l\'attester au peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Sa renommée se répandait de plus en plus; et le peuple venait en foule pour l\'entendre et pour se faire guérir de ses maladies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Pour lui, il se retirait dans les déserts, et priait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Un jour qu\'il enseignait en présence de pharisiens et de docteurs de la Loi, venus de tous les villages de la Galilée, ainsi que de la Judée et de Jérusalem, et que la puissance du Seigneur se déployait dans la guérison des malades,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'arrivèrent des gens, qui portaient sur un lit un homme paralysé; ils cherchaient à le faire entrer, et à le placer sous les yeux de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Ne sachant par où pénétrer, à cause de la foule, ils montèrent sur le toit, et, en ayant enlevé les briques, ils descendirent le malade, avec son lit, au milieu de l\'assemblée, devant Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Celui-ci voyant leur foi, dit: «O homme, tes péchés te sont pardonnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Les scribes et les pharisiens commencèrent à dire en eux-mêmes: «Qui est cet homme qui profère des blasphèmes? Qui peut pardonner les péchés, que Dieu seul?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mais Jésus connaissant leurs pensées, prit la parole, et leur dit: «Quelles pensées avez-vous dans vos coeurs?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Lequel est le plus aisé de dire: Tes péchés te sont pardonnés, ou de dire: Lève-toi et marche?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Or, afin que vous sachiez que le Fils de l\'homme a sur la terre le pouvoir de pardonner les péchés: Je te le commande, dit-il au paralytique, lève-toi, prends ton lit et va-t\'en dans ta maison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'A l\'instant, le paralytique se leva en leur présence, prit ce qui lui servait de lit, et s\'en alla dans sa maison en glorifiant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Tous les assistants étaient dans la stupéfaction; ils glorifiaient Dieu, et, tout remplis de crainte, ils disaient: «Nous avons vu aujourd\'hui des choses étranges.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Après cela, Jésus étant sorti, remarqua un publicain nommé Lévi, qui était assis au bureau des péages, et il lui dit: «Suis-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Et lui, quittant tout, se leva et le suivit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Lévi lui donna un grand repas dans sa maison, et il y avait une troupe nombreuse de publicains et d\'autres gens, qui étaient à table avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Les pharisiens et les scribes du lieu s\'en plaignaient à ses disciples, disant: «Pourquoi mangez-vous et buvez-vous avec les publicains et les gens de mauvaise vie?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Jésus prit la parole, et leur dit: «Ce ne sont pas les bien portants qui ont besoin de médecin, mais ceux qui se portent mal:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'je ne suis pas venu appeler les justes à la repentance, mais les pécheurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Ils lui dirent: «Les disciples de Jean jeûnent fréquemment et font des prières, et ceux des pharisiens également, tandis que les tiens mangent et boivent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Il leur répondit: «Pouvez-vous faire jeûner les amis de l\'époux, pendant que l\'époux est avec eux?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Le temps de jeûner viendra: quand l\'époux leur sera ôté, alors ce sera le temps de jeûner.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Il ajouta une comparaison: «On ne prend pas une pièce à une étoffe neuve, pour la mettre à un vieux habit; autrement, non-seulement on déchire l\'étoffe neuve, mais encore le neuf n\'ira pas bien avec le vieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'On ne met pas non plus du vin nouveau dans de vieilles outres; autrement, le vin nouveau fait rompre les outres, et le vin se répand, et les outres sont perdues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Mais il faut mettre le vin nouveau dans des outres neuves.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'D\'ailleurs, quand on vient de boire du vin vieux, on ne veut pas du nouveau, car on dit: «Le vieux est bon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Le jour du second-premier sabbat, Jésus passant par des blés, ses disciples arrachaient des épis et les mangeaient, après les avoir froissés dans leurs mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Des pharisiens dirent: «Pourquoi faites-vous ce qui n\'est pas permis le jour du sabbat?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Et Jésus prenant la parole, leur dit: «N\'avez-vous pas lu ce que fit David, lorsqu\'il eut faim, lui et ceux qui étaient avec lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'comment il entra dans la maison de Dieu, prit les pains de proposition, en mangea, et en donna même à ceux qui l\'accompagnaient, quoiqu\'il ne soit permis qu\'aux sacrificateurs d\'en manger?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Et il ajouta: «Le Fils de l\'homme est maître même du sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Il lui arriva, un autre jour de sabbat, d\'entrer dans la synagogue, et d\'y enseigner. Il y avait là un homme dont la main droite était sèche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Les scribes et les pharisiens observaient Jésus, pour voir s\'il faisait des guérisons le jour du sabbat, afin d\'avoir sujet de l\'accuser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Jésus pénétrant leurs pensées, dit à l\'homme qui avait la main sèche: «Lève-toi, et tiens-toi là au milieu;» et lui, s\'étant levé, se tint debout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jésus leur dit: «Je vous demande s\'il est permis, le jour du sabbat, de faire bien ou de faire mal, de sauver la vie ou de l\'ôter?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Puis, ayant promené ses regards sur eux tous, il dit à cet homme: «Étends la main.» Il le fit, et sa main fut guérie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Les scribes et les pharisiens furent remplis de fureur; et ils conféraient ensemble pour savoir ce qu\'ils feraient à Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'En ce temps-là, Jésus se rendit à la montagne pour prier Dieu, et il passa toute la nuit en prière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Quand il fit jour, il appela ses disciples, et en choisit douze, auxquels il donna le nom d\'Apôtres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'savoir, Simon, qu\'il appela Pierre, et André son frère, Jacques, Jean, Philippe, Barthélemi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthieu, Thomas, Jacques fils d\'Alphée, Simon appelé le zélateur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Jude fils de Jacques, et Judas Iscariot, qui fut un traître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Il descendit avec eux et s\'arrêta sur un plateau, où se trouvaient une foule de ses disciples, et une multitude de gens qui étaient venus de toute là Judée, de Jérusalem et du littoral de Tyr et de Sidon, pour l\'entendre et pour être guéris de leurs maladies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Ceux qui étaient tourmentés par des esprits impurs étaient guéris;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'et toute la foule cherchait à le toucher, parce qu\'il sortait de sa personne une vertu qui les guérissait tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Alors, levant les yeux sur ses disciples, il dit: «Vous êtes bienheureux, vous qui êtes pauvres, parce que le royaume de Dieu est à vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Vous êtes bienheureux, vous qui avez faim maintenant, parce que vous serez rassasiés. Vous êtes bienheureux, vous qui pleurez maintenant, parce que vous rirez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Bienheureux serez-vous, quand on vous haïra, quand on vous chassera, qu\'on vous insultera et qu\'on rejettera votre nom comme un nom infâme, à cause du Fils de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Réjouissez-vous en ce jour-là et bondissez de joie, car votre récompense est grande dans le ciel: c\'est ainsi que leurs pères traitaient les prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mais, malheur à vous, riches, parce que vous avez déjà votre consolation!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Malheur à vous, rassasiés, parce que vous aurez faim! Malheur à vous, qui riez maintenant, parce que vous serez dans l\'affliction et que vous pleurerez!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Malheur à vous, lorsque tous les hommes diront du bien de vous, car c\'est ce que leurs pères faisaient à l\'égard des faux prophètes!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Mais je vous dis, à vous qui m\'écoutez, aimez vos ennemis; faites du bien à ceux qui vous haïssent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'bénissez ceux qui vous maudissent; priez pour ceux qui vous maltraitent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Si quelqu\'un te frappe sur une joue, présente-lui l\'autre, et si quelqu\'un t\'enlève ton manteau, laisse-lui prendre aussi ta tunique.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Donne à tout homme qui te demande, et ne réclame pas ton bien à celui qui te le prend.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Comme vous voulez que les hommes fassent pour vous, faites de même pour eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Si vous aimez ceux qui vous aiment, quel gré vous en doit-on savoir? Les pécheurs aussi aiment ceux qui les aiment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Si vous faites du bien à ceux qui vous en font, quel gré vous en doit-on savoir? Les pécheurs aussi en font autant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Si vous prêtez à ceux de qui vous espérez être remboursés, quel gré vous en doit-on savoir?» Des pécheurs aussi prêtent à des pécheurs, afin qu\'on leur rende la pareille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Mais aimez vos ennemis, faites du bien, et prêtez sans rien espérer: votre récompense sera grande; et vous serez fils du Très-Haut, car il est bon envers les ingrats et les méchants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Soyez donc miséricordieux, comme votre Père est miséricordieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Ne jugez point, et vous ne serez point jugés; ne condamnez point, et vous ne serez point condamnés; absolvez, et l\'on vous absoudra;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'donnez, et l’on vous donnera: on vous donnera dans votre robe une bonne mesure, serrée, secouée et débordante; car on se servira pour vous de la même mesure avec laquelle vous aurez mesuré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Il ajouta cette comparaison: «Un aveugle peut-il conduire un aveugle? Ne tomberont-ils pas tous deux dans une fosse?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Le disciple n\'est pas au-dessus de son maître: tout disciple sera traité comme son maître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Pourquoi vois-tu la paille qui est dans l\'oeil de ton frère, tandis que tu ne remarques pas la poutre qui est dans ton oeil?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Ou comment peux-tu dire à ton frère: «Frère, laisse-moi ôter la paille qui est dans ton oeil,» toi qui ne vois pas la poutre qui est dans le tien? Hypocrite, ôte premièrement la poutre de ton oeil, alors tu verras à ôter la paille qui est dans l\'oeil de ton frère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'car il n\'y a pas de bon arbre qui produise de mauvais fruits, comme il n\'y a pas de mauvais arbre qui produise de bons fruits:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'chaque arbre se reconnaît à son fruit. On ne cueille pas des figues sur des épines et l\'on ne vendange pas le raisin sur la ronce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'L\'homme de bien tire le bien du bon trésor de son coeur, et le méchant tire le mal de son mauvais trésor; car de l\'abondance du coeur la bouche parle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Pourquoi m\'appelez-vous: «Seigneur, Seigneur,» et ne faites-vous pas ce que je dis?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Je vous montrerai à qui ressemble tout homme qui vient à moi, qui écoute mes paroles et les met en pratique:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'il est semblable à un homme qui bâtit une maison, et qui, ayant creusé profondément, en a posé les fondements sur le roc: une inondation étant survenue, le fleuve est venu donner contre cette maison, et n\'a pu l\'ébranler, parce qu\'elle était bien bâtie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mais celui qui écoute et ne pratique pas, est semblable à un homme qui a bâti une maison sur la terre, sans creuser de fondements: le fleuve est venu donner contre cette maison, et aussitôt elle s\'est écroulée; et la ruine de cette maison a été grande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Lorsqu\'il eut achevé de parler au peuple qui l\'écoutait, il entra dans Capernaoum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Or un centurion avait un serviteur, auquel il tenait beaucoup, qui était malade et sur le point de mourir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Ayant entendu parler de Jésus, il lui députa quelques anciens des Juifs, pour le prier de venir guérir son serviteur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ceux-ci, étant arrivés vers Jésus, le sollicitaient instamment, disant: «Il mérite bien que tu lui accordes sa demande,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'car il aime notre nation, et c\'est lui qui nous a bâti la synagogue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jésus s\'achemina donc avec eux. Il n\'était plus qu\'à une petite distance de la maison, lorsque le centurion lui envoya dire par des amis: «Seigneur, ne te donne pas tant de peine, car je ne suis pas digne que tu entres sous mon toit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'C\'est pour cela que je n\'ai pas jugé devoir me rendre moi-même auprès de toi; mais dis un mot, et que mon serviteur soit guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'En effet, moi qui suis placé sous le commandement d\'autrui, j\'ai des soldats sous mes ordres, et je dis à celui-ci: «Va,» et il va; et à un autre: «Viens,» et il vient; et à mon esclave: «Fais cela,» et il le fait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'En entendant ces paroles, Jésus admira cet homme, et, se retournant, il dit à la foule qui le suivait: «Je vous déclare que je n\'ai pas trouvé une aussi grande foi même en Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'A leur retour dans la maison du centurion, les envoyés trouvèrent en santé le serviteur qui était malade.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Le lendemain, Jésus se rendit dans une ville appelée Nain; ses disciples, eu assez grand nombre, et une grande foule cheminaient avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Au moment où il arrivait près de la porte de la ville, on portait en terre un mort, fils unique d\'une veuve, et une foule considérable de gens de la ville accompagnaient cette femme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Le Seigneur, en la voyant, fut ému de compassion pour elle, et lui dit: «Ne pleure pas;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'puis, s\'étant approché, il toucha le cercueil, et les porteurs s\'arrêtèrent; alors il dit: «Jeune homme, je te le commande, lève-toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Et le mort se mit sur son séant, et commença à parler; et Jésus le rendit à sa mère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Un sentiment de crainte s\'empara d\'eux tous, et ils glorifiaient Dieu, disant: «Un grand prophète s\'est élevé parmi nous,» et «Dieu a visité son peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Ce propos sur Jésus courut dans la Judée tout entière et dans tout le pays d\'alentour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Jean ayant été informé de toutes ces choses par ses disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'en fit venir deux, et les envoya vers le Seigneur, pour lui dire: «Es-tu celui qui doit venir, ou devons-nous en attendre un autre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Quand ces hommes furent arrivés vers Jésus, ils dirent: «Jean-Baptiste nous a envoyés vers toi, pour te dire: «Es-tu celui qui doit venir, ou devons-nous en attendre un autre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'A ce moment même, Jésus venait de guérir plusieurs personnes de maladies, d\'infirmités et de mauvais esprits, et de rendre la vue à plusieurs aveugles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Il répondit aux envoyés: «Allez rapporter à Jean ce que vous avez vu et entendu: les aveugles voient, les boiteux marchent, les lépreux sont rendus nets, les sourds entendent, les morts ressuscitent, la bonne nouvelle est annoncée aux pauvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Heureux celui pour qui je ne serai pas une occasion de chute!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Quand les messagers de Jean furent partis, Jésus se mit à parler de Jean au peuple: «Qu\'êtes- vous allés contempler au désert? un roseau agité par le vent?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Mais encore, qu\'êtes-vous allés voir? un homme vêtu d\'habits somptueux? Vous savez que ceux qui portent des habits magnifiques et qui vivent dans le luxe, sont dans les palais des rois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mais, qu\'êtes-vous allés voir? un prophète? — Oui, vous dis-je, et plus qu\'un prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'C\'est celui dont il est écrit: «Voici, j’envoie mon messager devant ta face, pour préparer le chemin devant toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Car je vous dis, que parmi ceux qui sont nés de femme, il n\'y a point de plus grand prophète que Jean; toutefois le plus petit dans le royaume de Dieu est plus grand que lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Tout le peuple qui l\'a écouté, ainsi que les publicains, ont rendu justice à Dieu, en se faisant baptiser du baptême de Jean,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'au lieu que les pharisiens et les docteurs de la Loi ont fait échouer pour eux-mêmes le plan de Dieu, en ne se faisant pas baptiser par lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '«A qui donc comparerai-je les hommes de cette génération, et à qui ressemblent-ils?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Ils ressemblent aux enfants qui sont assis dans la place publique, et qui disent, en s\'apostrophant les uns les autres: «Nous vous avons joué de la flûte, et vous n\'avez pas dansé; nous vous avons chanté des complaintes, et vous n\'avez pas pleuré.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'En effet, Jean est venu ne mangeant point de pain, et ne buvant point de vin, et vous dites: «C\'est un possédé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Le Fils de l\'homme est venu mangeant et buvant, et vous dites: «C\'est un mangeur et un buveur, un ami des publicains et des pécheurs»:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'et pourtant la Sagesse a été justifiée par tous ses enfants.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Un pharisien invita Jésus à manger avec lui, et Jésus étant entré dans la maison du pharisien, prit place à table.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Alors une femme qui menait une vie déréglée dans la ville, apprenant que Jésus était à table dans la maison de ce pharisien, apporta un flacon d\'albâtre plein de parfum;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'et se tenant derrière lui, à ses pieds, tout en pleurs, elle se mit à mouiller ses pieds de ses larmes et à les essuyer avec les cheveux de sa tête; elle couvrait ses pieds de baisers et les oignait de parfum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'A cette vue, le pharisien qui l\'avait invité, se dit en lui-même: «Si cet homme était prophète, il saurait qui est la personne qui le touche, et quelle sorte de femme, c\'est une femme de mauvaise vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Jésus prit la parole, et lui dit: «Simon, j\'ai quelque chose à te dire.» — «Maître, parle,» dit-il. —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, '«Un créancier avait deux débiteurs, l\'un lui devait cinq cents deniers, l\'autre cinquante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Comme ils ne pouvaient payer, il les tint quitte tous les deux. Dis-moi lequel des deux l\'aimera le plus?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon répondit: «Je pense que c\'est celui auquel il a le plus remis.» Jésus lui dit: «Tu as bien jugé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Puis, se tournant vers la femme, il dit à Simon: «Tu vois cette femme? Je suis entré dans ta maison; tu ne m\'as point versé d\'eau sur les pieds, mais elle a mouillé mes pieds de ses larmes et les a essuyés avec ses cheveux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu ne m\'as point donné de baiser, mais depuis que je suis entré, elle n\'a cessé de me baiser les pieds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Tu n\'as pas oint ma tête d\'huile, mais elle a oint mes pieds de parfum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Aussi je te dis que ses nombreux péchés lui ont été pardonnés, car elle a beaucoup aimé; tandis que celui à qui l\'on pardonne peu, aime peu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Il dit à la femme: «Tes péchés te sont pardonnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Et les convives commencèrent à dire en eux-mêmes: «Qui est cet homme qui ose pardonner les péchés?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Mais Jésus dit à la femme: «Ta foi t\'a sauvée; va en paix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Ensuite Jésus alla de ville en ville et de village en village, prêchant et annonçant la bonne nouvelle du royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Il était accompagné des Douze et de quelques femmes qu\'il avait guéries des mauvais esprits et de leurs maladies; c’était Marie, appelée Madeleine, de laquelle étaient sortis sept démons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Jeanne, femme de Chouza, intendant d\'Hérode, Suzanne et plusieurs autres qui l\'assistaient de leurs biens, lui et ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Un jour que s\'était amassée une foule nombreuse, grossie de ceux qui de ville en ville venaient vers lui, il leur dit en parabole:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '«Un semeur sortit pour faire ses semailles; et, comme il semait, une partie de la semence tomba le long du chemin; elle fut foulée aux pieds, et les oiseaux du ciel la mangèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Une autre partie tomba sur le roc: elle poussa et sécha, parce qu\'elle manquait d\'humidité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Une autre partie tomba au milieu des épines; et les épines poussant avec la semence, l’étouffèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Enfin une autre partie tomba dans la bonne terre, elle poussa et produisit du fruit au centuple.» Puis il ajouta à haute voix: «Que celui qui a des oreilles pour entendre, entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Ses disciples lui ayant demandé ce que signifiait cette parabole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'il répondit: «Pour vous, il vous a été donné de connaître les mystères du royaume de Dieu; mais pour les autres, ce n\'est qu\'en paraboles, afin qu’en regardant, ils ne voient point, et qu\'en entendant, ils ne comprennent point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Voici donc le sens de cette parabole: La semence, c\'est la parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Ceux qui reçoivent la semence le long du chemin, sont ceux qui entendent la Parole; ensuite le diable vient, et il l\'enlève de leur coeur, de peur qu\'ils ne croient et ne soient sauvés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Ceux qui reçoivent la semence sur le roc, sont ceux qui reçoivent la Parole avec joie, dès qu\'ils l\'entendent, mais qui, n\'ayant pas de racines, ne croient que pour un temps, et font défection au moment de l\'épreuve.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Quant à la partie qui est tombée parmi les épines, ce sont ceux qui ont entendu la Parole, et qui, en cheminant, la laissent étouffer par les soucis, par les richesses et par les plaisirs de la vie, et ne donnent que des fruits avortés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Quant à la partie qui est tombée dans la bonne terre, ce sont ceux qui entendent la Parole avec un coeur honnête et bon, la conservent, et portent du fruit avec persévérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, '«Il n\'est personne, qui, après avoir allumé une lampe, la couvre d\'un vase, ou la mette sous un lit; mais on la met sur un pied, afin que ceux qui entrent voient clair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Car il n\'y a rien de caché qui ne se découvre, ni rien de secret qui ne finisse par être connu, et ne vienne au grand jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Prenez donc garde à la manière dont vous écoutez; car on donnera à celui qui a, mais pour celui qui n\'a pas, on lui ôtera même ce qu\'il croit avoir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Cependant la mère et les frères de Jésus étaient venus le trouver, et ne pouvaient arriver jusqu’à lui, à cause de la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'On l\'en informa en lui disant: «Ta mère et tes frères sont là dehors, qui désirent te voir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Il répondit: «Ma mère et mes frères sont ceux qui écoutent la parole de Dieu, et qui la mettent en pratique.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Un jour il entra dans une barque avec ses disciples, et leur dit: «Passons de l\'autre côté du lac;» et ils partirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Pendant qu\'ils naviguaient, Jésus s\'endormit, et un ouragan ayant fondu sur le lac, la barque se remplissait d\'eau; et ils étaient en péril.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Les disciples s\'approchèrent de Jésus et le réveillèrent en disant: «Maître, maître, nous périssons.» Jésus se leva, tança lèvent et les flots: ils s\'apaisèrent, et le calme se fit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Puis il dit à ses disciples: «où est votre foi?» Pour eux, saisis de frayeur et d\'étonnement, ils se disaient les uns aux autres: «Quel est donc cet homme, qu\'il commande aux vents et à l\'eau, et qu\'ils lui obéissent?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Puis ils abordèrent au pays des Gadaréniens, qui est vis-à-vis de la Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Quand Jésus fut descendu à terre, il rencontra un homme de la ville, qui depuis longtemps était possédé des démons: il ne portait point de vêtement, et demeurait non dans une maison, mais dans les sépulcres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Dès qu\'il vit Jésus, il poussa un cri, se jeta à ses pieds, et dit d\'une voix forte: «Qu\'y a-t-il entre toi et moi, Jésus, Fils du Dieu Très-Haut? Je t\'en prie, ne me tourmente pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Jésus, en effet, commandait à l\'esprit impur de sortir de cet homme; car depuis longtemps l’esprit l\'emportait avec lui: on avait beau le garder enchaîné et les fers aux pieds, il brisait ses liens et était entraîné par le démon dans les déserts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jésus lui demanda: «Quel est ton nom?» — «Légion,» répondit-il; en effet, plusieurs démons étaient entrés dans cet homme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'et il se mit à supplier Jésus de ne point commander à ces démons d\'aller dans l\'abîme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Or, il y avait là un grand troupeau de pourceaux qui paissaient sur la montagne, et les démons le supplièrent de leur permettre d\'aller dans ces pourceaux; et il le leur permit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Étant donc sortis de cet homme, ils entrèrent dans les pourceaux, et le troupeau se rua du haut du précipice dans le lac, et se noya.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'A cette vue, les gardeurs s\'enfuirent, et répandirent la nouvelle dans la ville et dans la campagne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Les gens sortirent pour voir ce qui était arrivé; ils vinrent vers Jésus et trouvèrent l\'homme de qui les démons étaient sortis, assis à ses pieds, vêtu et dans son bon sens; ce qui les remplit de frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Les témoins de ce fait leur rapportèrent aussi comment le démoniaque avait été guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Toute la population de la contrée voisine des Gadaréniens le pria de s\'éloigner de chez eux, parce qu\'ils étaient en proie à une grande frayeur: Jésus étant entré dans la barque, s\'en retourna.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'L\'homme de qui les démons étaient sortis, lui demanda de rester avec lui, mais Jésus le renvoya en lui disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '«Retourne dans ta maison, et raconte tout ce que Dieu a fait pour toi.» Il s\'en alla, et publia par toute la ville tout ce que Jésus avait fait pour lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'A son retour, Jésus fut accueilli par la foule; car ils étaient tous à l\'attendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Alors il vint un homme nommé Jaïrus, chef de la synagogue, qui, se jetant aux pieds de Jésus, le supplia de venir dans sa maison,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'parce qu\'il avait une fille unique, d\'environ douze ans, qui se mourait. Pendant que Jésus s\'y acheminait, la foule le serrait à l\'étouffer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Et une femme qui était atteinte d\'une hémorragie depuis douze ans, et qui avait dépensé tout son bien en médecins, sans qu\'aucun d\'eux eût pu la guérir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 's\'approcha par derrière, toucha la houppe de son manteau, et au même instant son hémorragie s\'arrêta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Et Jésus dit: «Qui est-ce qui m\'a touché?» Comme tous s\'en défendaient, Pierre et ceux qui étaient avec lui, dirent: «Maître, la foule t\'entoure et te presse, et tu demandes qui t\'a touché!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Mais Jésus répondit: «Quelqu\'un m\'a touché, car j\'ai senti une vertu sortir de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'La femme voyant qu\'elle n\'était pas restée inaperçue, vint toute tremblante se jeter aux pieds de Jésus, et déclara devant tout le monde, pour quelle cause elle l\'avait touché, et comment elle avait été guérie à l\'instant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Jésus lui dit: «Ma fille, ta foi t\'a guérie: va en paix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Il parlait encore, lorsqu\'on vint de chez Jaïrus dire à ce chef de la synagogue: «Ta fille est morte, ne fatigue pas le Maître.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Mais Jésus, qui avait entendu cette parole, lui dit: «Ne crains point, crois seulement, et elle sera guérie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Lorsqu\'il fut arrivé à la maison, il ne laissa entrer personne avec lui, si ce n\'est Pierre, Jean, Jacques, avec le père et la mère de l\'enfant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Comme tous pleuraient et se lamentaient, Jésus leur dit: «Ne pleurez pas; elle n\'est pas morte, mais elle dort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Et ils se moquèrent de lui, sachant qu\'elle était morte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mais lui, la saisissant par la main, dit en élevant la voix: «Enfant, lève-toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'La respiration lui revint, et elle se leva à l\'instant; et Jésus commanda qu\'on lui donnât à manger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Les parents de la jeune fille furent dans le ravissement, et Jésus leur recommanda de ne dire à personne ce qui venait de se passer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Jésus ayant assemblé les Douze, leur donna puissance et autorité pour chasser tous les démons et pour guérir toutes les maladies;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'puis il les envoya prêcher le royaume de Dieu et guérir les malades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Il leur dit: «Ne prenez rien pour la route, ni bâton, ni sac, ni pain, ni argent, ni deux tuniques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Dans quelque maison que vous entriez, restez-y, et que ce soit de là que vous partiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Quant à tous ceux qui ne vous recevront pas, sortez de leur ville, et secouez la poussière de vos pieds en témoignage contre eux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Les disciples étant partis, allèrent de village en village, annonçant la bonne nouvelle et faisant partout des guérisons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Cependant Hérode, le tétrarque entendit parler de tout ce qui se passait, et il ne savait que penser, parce que les uns disaient que Jean était ressuscité des morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'les autres, qu\'Elie était apparu; d\'autres enfin, qu\'un des anciens prophètes était ressuscité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Mais Hérode dit: «Quant à Jean, moi, je l\'ai fait décapiter; qui est donc cet homme, dont j\'entends dire des choses si extraordinaires?» Et il désirait le voir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Les apôtres, étant de retour, racontèrent à Jésus tout ce qu\'ils avaient fait; et Jésus les prenant avec lui, se retira à l\'écart, vers une ville nommée Bethsaïde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Mais les foules, en ayant eu connaissance, l\'y suivirent: Jésus les accueillit, leur parla du royaume de Dieu, et guérit tous ceux qui avaient besoin d\'être guéris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Comme le jour commençait à baisser, les Douze vinrent lui dire: «Renvoie cette foule de gens, afin qu\'ils aillent loger dans les villages d\'alentour et dans les campagnes, et qu\'ils trouvent de quoi manger, car ici nous sommes dans un lieu désert.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mais Jésus leur dit: «Donnez-leur, vous-mêmes, à manger.» Ils répondirent: «Nous n\'avons que cinq pains et deux poissons... à moins que nous n\'allions nous-mêmes acheter des vivres pour tout ce peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'En effet, il y avait environ cinq mille hommes. Jésus dit à ses disciples: «Faites-les asseoir par groupes de cinquante.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Ils exécutèrent cet ordre; ils les firent tous asseoir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Alors Jésus prit les cinq pains et les deux poissons, et, levant les yeux au ciel, il les bénit, les rompit, et les donna aux disciples pour les distribuer à la foule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Tous mangèrent et furent rassasiés; et l\'on emporta ce qu\'ils avaient eu de trop, douze corbeilles de morceaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Un jour que Jésus s\'était retiré dans un lieu solitaire, pour prier, ses disciples vinrent le rejoindre, et il leur adressa cette question: «Qui dit-on, dans le peuple, que je suis?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Ils lui répondirent: «On dit que tu es Jean-Baptiste; d\'autres disent que tu es Elie; d\'autres, qu\'un des anciens prophètes est ressuscité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, '— «Et vous, leur dit-il, qui dites-vous que je suis?» Pierre répondit: «Tu es l\'Oint de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Jésus leur recommanda sévèrement de ne le dire à personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'et il ajouta: «Il faut que le Fils de l\'homme souffre beaucoup, qu\'il soit rejeté par les anciens, les principaux sacrificateurs et les scribes, qu\'il soit mis à mort, et qu\'il ressuscite le troisième jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Puis s’adressant à tout le monde, il dit: «Si quelqu\'un veut venir après moi, qu\'il renonce à lui-même, qu\'il se charge chaque jour de sa croix, et qu\'il me suive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Car celui qui voudra sauver sa vie, la perdra; mais celui qui aura perdu sa vie à cause de moi, la sauvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'A quoi sert-il à un homme de gagner le monde entier, s\'il se perd ou se ruine lui-même?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'En effet, si quelqu\'un a honte de moi et de mes paroles, le Fils de l\'homme aura honte de lui, quand il viendra dans sa gloire, dans celle de son Père et dans celle des saints anges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Je vous le dis, certainement quelques-uns de ceux qui sont ici présents, ne goûteront point la mort, qu\'ils n\'aient vu le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Environ huit jours après ce discours, Jésus prit avec lui Pierre, Jean et Jacques, et monta sur la montagne pour prier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Pendant qu\'il priait, son visage parut tout autre et ses vêtements devinrent éblouissants de blancheur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Tout à coup parurent, entourés de gloire, deux hommes qui s\'entretenaient avec lui: c\'était Moïse et Élie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'ils parlaient de son départ qui devait s\'accomplir à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Pierre et ses compagnons étaient accablés de sommeil; mais s’étant tenus éveillés, ils virent sa gloire et les deux hommes qui étaient avec lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'et au moment où Moïse et Élie se séparaient de lui, Pierre dit à Jésus: «Maître, il est bon que nous soyons ici; dressons trois tentes, une pour toi, une pour Moïse, et une pour Elie»: il ne savait pas ce qu\'il disait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Comme il parlait ainsi, une nuée vint, qui les enveloppa, et en les voyant entrer dans la nuée, les disciples furent saisis de frayeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Il sortit de la nuée une voix qui dit: «Celui-ci est mon Fils élu; écoutez-le;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'et après que la voix se fut fait entendre, Jésus se trouva seul. Les disciples gardèrent le silence sur ce qui s’était passé, et ne rapportèrent pour lors à personne rien de ce qu\'ils avaient vu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Le lendemain, lorsqu\'ils furent descendus de la montagne, une foule considérable se porta à la rencontre de Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'et un homme s\'écria du milieu de la foule: «Maître, je t\'en prie, jette un regard sur mon fils, car je n\'ai que cet enfant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'un esprit le saisit, et soudain lui arrache des cris; puis il le jette dans des convulsions où il écume, et il le quitte à grand\'peine en le brisant encore.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'J\'ai prié tes disciples de le chasser, et ils ne l\'ont pu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jésus répondit: «Race incrédule et perverse, jusqu\'à quand serai-je avec vous, et vous supporterai-je?... Amène ici ton fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Au moment où l\'enfant s\'approchait, le démon le jeta par terre, dans des convulsions; mais Jésus tança l\'esprit impur, guérit l\'enfant, et le rendit à son père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Tous les assistants étaient frappés de la grandeur de Dieu. Tandis que tout le monde était dans l\'admiration de tout ce que Jésus faisait, il dit à ses disciples:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '«Pour vous, mettez-vous bien dans l\'esprit ce que je vais vous dire: c\'est que le Fils de l\'homme doit être livré entre les mains des hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mais les disciples ne comprenaient pas cette parole; elle était voilée pour eux, afin qu\'ils n\'en sentissent point la portée; et ils craignaient de l\'interroger là -dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Une pensée s\'éleva dans leur esprit: ils se demandaient lequel d\'entre eux serait le plus grand.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Jésus voyant la pensée de leur coeur, prit un petit enfant, le plaça auprès de lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'et leur dit: «Celui qui reçoit ce petit enfant en mon nom, me reçoit; et celui qui me reçoit, reçoit celui qui m\'a envoyé; car celui d\'entre vous tous qui est le plus petit, c\'est celui-là qui est grand.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Jean, prenant la parole, lui dit: «Maître, nous avons vu un homme qui chassait des démons en ton nom, et nous l\'en avons empêché, parce qu\'il ne va pas avec nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Jésus lui dit: «Ne l\'en empêchez point: celui qui n\'est pas contre vous est pour vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Quand le temps où Jésus devait être enlevé du monde fut venu, il prit la résolution de s\'acheminer à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Il se fit précéder par des messagers. Ceux-ci, s\'en étant allés, entrèrent dans une ville des Samaritains pour lui préparer un logement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'mais on ne le reçut point, parce qu\'il se rendait à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Ses disciples, Jacques et Jean, témoins de ce refus, dirent: «Seigneur, veux-tu qu\'à l\'exemple d\'Élie, nous commandions que le feu descende du ciel et consume ces gens-là?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mais Jésus s’étant retourné, les réprimanda, et leur dit: «Vous ne savez de quel esprit vous êtes animés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Et ils gagnèrent un autre village.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Comme ils s\'y rendaient, un homme lui dit en chemin: «Seigneur, je te suivrai partout où tu iras.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Et Jésus lui dit: «Les renards ont des tanières, et les oiseaux du ciel, des abris; mais le Fils de l\'homme n\'a pas un lieu pour reposer sa tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Il dit à un autre: «Suis-moi.» Celui-ci lui dit: «Seigneur, permets-moi d\'aller auparavant ensevelir mon père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mais il lui repartit: «Laisse les morts ensevelir leurs morts; pour toi, va annoncer le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Un autre lui dit aussi: «Je te suivrai, Seigneur, mais permets-moi d\'aller auparavant faire mes adieux à ma famille.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jésus lui dit: «Quiconque met la main à la charrue et regarde en arrière, n\'est pas propre au royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Après cela, Jésus désigna encore soixante-dix autres disciples, et les envoya devant lui, deux à deux, dans toutes les villes et dans tous les lieux, où lui-même devait aller.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Et il leur dit: «La moisson est grande, mais il y a peu d\'ouvriers; priez donc le maître de la moisson d\'envoyer des ouvriers dans sa moisson.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Allez, je vous envoie comme des agneaux au milieu des loups.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne prenez ni bourse, ni sac, ni sandales, et ne saluez personne en chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Dans quelque maison que vous entriez, dites d\'abord:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, '«Que la paix soit sur cette maison!» et s\'il se trouve là quelque enfant de paix, la paix que vous aurez souhaitée reposera sur lui; sinon, elle reviendra à vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Demeurez dans cette même maison, mangez et buvez ce qu\'on vous donnera; car l\'ouvrier mérite son salaire. Ne passez point d\'une maison dans une autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Dans quelque ville que vous entriez, si l\'on vous reçoit, mangez ce qu\'on vous servira;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'guérissez les malades qui s\'y trouveront, et dites aux habitants: «Le royaume de Dieu est proche de vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Dans quelque ville que vous entriez, si l’on ne vous reçoit pas, allez dans les rues, et dites:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '«Nous secouons de nos pieds, pour vous la rendre, même la poussière qui s\'y est attachée dans votre ville; pourtant, sachez-le bien, le royaume de Dieu est proche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Je vous déclare qu\'au dernier jour, Sodome sera traitée moins rigoureusement que cette ville-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Malheur à toi, Chorazin! Malheur à toi Bethsaïde! car si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu\'elles se seraient repenties sous le sac et la cendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Mais au jour du jugement Tyr et Sidon seront traitées moins rigoureusement que vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Et toi, Capernaoum, qui as été élevée jusqu\'au ciel, tu seras abaissée jusqu\'aux enfers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Qui vous écoute, m\'écoute; qui vous rejette, me rejette; et qui me rejette, rejette celui qui m\'a envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Les soixante et dix disciples revinrent pleins de joie, disant: «Seigneur, les démons mêmes se soumettent à nous en ton nom!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Il leur dit: «Je voyais Satan tomber du ciel comme un éclair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Je vous ai donné le pouvoir de fouler aux pieds les serpents et les scorpions, et toutes les forces de l\'ennemi, sans qu\'elles puissent aucunement vous nuire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'seulement ne vous réjouissez pas de ce que les esprits se soumettent à vous, mais réjouissez-vous de ce que vos noms sont écrits dans les cieux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'En ce moment même, Jésus tressaillit de joie en son esprit, et dit: «Je te loue, Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux enfants; oui, Père, je te loue de ce que tel a été ton bon plaisir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Et se tournant vers ses disciples, il dit: «Toutes choses m\'ont été enseignées par mon Père; et personne ne connaît ce qu\'est le Fils, que le Père, ni ce qu\'est le Père, que le Fils, et que celui à qui le Fils le veut bien révéler.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Puis se tournant vers ses disciples, il leur dit en particulier: «Heureux les yeux qui voient ce que vous voyez!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Car je vous dis que beaucoup de prophètes et de rois ont désiré de voir ce que vous voyez, et ne l\'ont pas vu; d\'entendre ce que vous entendez, et ne l\'ont pas entendu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Un docteur de la Loi, qui voulait mettre Jésus à l\'épreuve, se leva et lui dit: «Maître, que faut-il que je fasse pour obtenir la vie éternelle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Jésus lui répondit: «Que dit la Loi? Qu\'y lis-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Il repartit: «Tu aimeras le Seigneur ton Dieu de tout ton coeur, de toute ton âme, de toute ta force et de toute ta pensée; et ton prochain comme toi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Jésus lui dit: «Tu as bien répondu: fais cela, et tu vivras.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Cet homme voulant se justifier lui-même, dit à Jésus: «Et qui est mon prochain?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jésus reprit: «Un homme, qui descendait de Jérusalem à Jéricho, tomba au milieu des voleurs: ils le dépouillèrent, le chargèrent de coups, et s\'en allèrent, le laissant à demi mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Un sacrificateur, qui par hasard descendait par ce chemin, ayant vu ce malheureux, passa devant lui sans s\'arrêter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'De même, un lévite, étant arrivé dans cet endroit, s\'avança, et l\'ayant vu, passa devant lui sans s\'arrêter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mais un Samaritain, qui voyageait, étant venu dans ce lieu, et ayant vu cet homme, fut touché de compassion.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Il s\'approcha, banda ses blessures, après y avoir versé de l\'huile et du vin; puis, l\'ayant mis sur sa propre monture, il le mena dans une hôtellerie et prit soin de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Le lendemain matin, en partant, il tira de sa bourse deux deniers, les donna à l\'hôte, et dit: «Aie soin de lui, et, ce que tu dépenseras de plus, je te le rendrai à mon retour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Lequel des trois te semble avoir été le prochain de celui qui était tombé au milieu des voleurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Il dit: «C\'est celui qui a exercé la miséricorde envers lui.» Jésus lui dit: «Va, et fais de même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Pendant qu\'il était en route avec ses disciples, il entra dans un village; une femme, nommée Marthe, le reçut dans sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Elle avait une soeur, nommée Marie, qui, s\'étant assise aux pieds de Jésus, écoutait sa parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'tandis qu\'elle-même était distraite par les soins nombreux du ménage. Marthe s\'étant approchée, dit à Jésus: «Seigneur, ne vois-tu pas que ma soeur me laisse toute la tâche? Dis-lui donc de m\'aider.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Mais il lui répondit: «Marthe, Marthe, tu t\'inquiètes et tu t\'agites pour beaucoup de choses; une seule chose est nécessaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Marie a choisi la bonne part, qui ne lui sera point ôtée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Un jour, Jésus était en prière en un lieu. Lorsqu\'il eut fini de prier, un de ses disciples lui dit: «Seigneur, enseigne-nous à prier, comme Jean l\'a enseigné à ses disciples.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Il leur dit: «Quand vous priez, dites: «Père, que ton nom soit sanctifié; que ton règne vienne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Donne-nous chaque jour notre pain quotidien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Remets-nous nos péchés, car nous remettons aussi leurs dettes à tous ceux qui nous doivent; et ne nous induis point en tentation.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Et il ajouta: «Si quelqu\'un de vous avait un ami, et qu\'il l’allât trouver au milieu de la nuit pour lui dire: «Mon ami, prête-moi trois pains,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'car un de mes amis qui voyage est arrivé chez moi, et je n\'ai rien à lui offrir;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'et que cet ami lui répondît de l\'intérieur: «Ne m\'importune pas; ma porte est déjà fermée, et mes petits enfants sont au lit avec moi; je ne puis me lever pour te donner ces pains;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'eh bien! je vous dis qu\'alors même qu\'il ne se lèverait pas pour les lui donner, parce qu\'il est son ami, il se lèvera à cause de son importunité, et lui en donnera autant qu\'il en désire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Je vous dis aussi: Demandez, et l\'on vous donnera; cherchez, et vous trouverez; heurtez, et l\'on vous ouvrira;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'car quiconque demande, reçoit; qui cherche, trouve; et l\'on ouvre à qui heurte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Quel est parmi vous le père qui donne une pierre à son fils, quand il lui demande du pain? ou, s\'il demande du poisson, lui donnera-t-il un serpent au lieu d\'un poisson?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'ou, s\'il lui demande un oeuf, lui donnera-t-il un scorpion?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Si donc, tout méchants que vous êtes, vous savez donner de bonnes choses à vos enfants, combien plus le Père céleste donnera-t-il le Saint-Esprit à ceux qui le lui demandent!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Une autre fois, Jésus chassa un démon: c\'était un démon sourd-muet. Lorsque le démon fut sorti, le sourd-muet parla; et la foule était dans l\'admiration.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Toutefois il y eut des gens qui dirent: C\'est par Belzébuth, prince des démons, qu\'il chasse les démons;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'tandis que d\'autres, pour le mettre à l\'épreuve, lui demandaient un signe qui vînt du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mais Jésus, connaissant leurs pensées, leur dit: «Tout royaume en proie aux divisions se détruit, et il tombe maison après maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'S\'il est vrai que Satan soit en proie aux divisions, comment son royaume subsistera-t-il, puisque vous dites que c\'est par Belzébuth que je chasse les démons?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Et si, moi, je chasse les démons par Belzébuth, par qui vos fils les chassent-ils? C\'est pourquoi ils seront eux-mêmes vos juges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mais si je chasse les démons par le doigt de Dieu, le royaume de Dieu est donc venu vers vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quand l\'homme fort et bien armé garde l\'entrée de sa maison, ses biens sont en sûreté,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'mais qu\'un plus fort que lui vienne et le vainque, il lui enlève l\'armure qui faisait sa sécurité, et il partage ses dépouilles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Qui n\'est pas avec moi est contre moi, et qui n\'assemble pas avec moi, disperse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quand l\'esprit impur est sorti d\'un homme, il va par des lieux arides, pour chercher du repos; et, n\'en trouvant point, il se dit: «Je retournerai dans la maison d\'où je suis sorti.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Il vient et la trouve balayée et mise en ordre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Alors il s\'en va prendre sept autres esprits plus méchants que lui, puis ils y rentrent et s\'y établissent; et la dernière condition de cet homme est pire que la première.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Pendant qu\'il parlait ainsi, une femme, élevant la voix du milieu de la foule, lui dit: «Heureux le sein qui t\'a porté! Heureuses les mamelles qui t\'ont allaité!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, '«Ah! heureux plutôt, reprit Jésus, ceux qui écoutent la parole de Dieu, et qui la gardent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Comme la foule s\'amassait, il se mit à dire: «Cette génération est une génération mauvaise; elle réclame un signe; eh bien! il ne lui en sera point accordé d\'autre que le signe de Jonas:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'de même que Jonas fut un signe pour les Ninivites, ainsi le Fils de l\'homme sera un signe pour cette génération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'La reine du Midi se lèvera au jour du jugement avec les hommes de cette génération, et les condamnera; car elle vint du bout du monde pour entendre la sagesse de Salomon; et il y a ici plus que Salomon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Les hommes de Ninive se lèveront au jour du jugement avec cette génération, et la condamneront; car ils se convertirent à la prédication de Jonas; et il y a ici plus que Jonas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'On n\'allume pas une lampe pour la mettre dans une cave ou sous le boisseau; mais on la met sur son pied, afin que ceux qui entrent voient clair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'La lampe de ton corps, c\'est ton oeil. Quand ton oeil est bon, tout ton corps est éclairé; mais quand ton oeil est mauvais, ton corps est dans les ténèbres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'prends donc garde que la lumière qui est en toi, ne soit ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Si donc ton corps tout entier est éclairé, sans qu\'il y ait en toi aucune partie ténébreuse, il sera complètement éclairé, comme lorsque la lampe t\'éclaire de sa lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Quand il eut parlé, un pharisien le pria à dîner chez lui. Jésus entra et se mit à table.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Le pharisien voyant qu\'il ne s\'était point lavé avant le repas, en fut surpris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Mais le Seigneur lui dit: «Vous autres, pharisiens, vous nettoyez le dehors de la coupe et du plat, mais au dedans, vous êtes pleins de rapine et de malhonnêteté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Insensés, celui qui a fait le dehors, n\'a-t-il pas fait aussi le dedans?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Donnez-en plutôt le contenu en aumône, et alors toutes choses seront pures pour vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mais malheur à vous, pharisiens! parce que vous payez la dîme de la menthe, de la rue et de toute espèce de plantes potagères, et que vous négligez la justice et l\'amour de Dieu: il fallait faire ces choses-ci, sans toutefois omettre celles-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Malheur à vous, pharisiens! parce que vous aimez la première place dans les synagogues, et les salutations dans les places publiques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Malheur à vous! parce que vous êtes comme ces sépulcres qu\'on ne voit pas: on marche dessus sans le savoir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Un des docteurs de la Loi prit la parole et lui dit: «Maître, tu nous outrages aussi en parlant de la sorte.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Jésus lui dit: «Malheur à vous aussi, docteurs de la Loi! parce que vous chargez les hommes de fardeaux insupportables, et vous-mêmes vous n\'y touchez pas du bout du doigt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Malheur à vous! parce que vous bâtissez les tombeaux des prophètes que vos pères ont tués.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Vous servez donc de témoins, et vous applaudissez aux oeuvres de vos pères: eux, les ont tués, vous, vous bâtissez!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'C\'est pourquoi la sagesse de Dieu a dit: Je leur enverrai des prophètes et des apôtres; ils tueront les uns et chasseront les autres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'afin qu\'on redemande à cette génération le sang de tous les prophètes, qui a été versé depuis la création du monde,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'depuis le sang d\'Abel jusqu\'au sang de Zacharie, égorgé entre l\'autel et le sanctuaire; oui, je vous le dis, ce sang sera redemandé à cette génération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Malheur à vous, docteurs de la Loi! parce que vous avez enlevé la clef de la science: vous n\'êtes pas entrés, et vous avez arrêté ceux qui entraient.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Quand Jésus fut sorti de cette maison, les scribes et les pharisiens commencèrent à lui en vouloir violemment et à le faire parler sur plusieurs points');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'en lui adressant des questions insidieuses, pour surprendre quelque parole compromettante sortie de sa bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Cependant les gens s\'étant amassés par milliers, au point qu\'ils s\'écrasaient les uns les autres, Jésus se mit à dire à ses disciples: «Avant tout, gardez-vous du levain des pharisiens, qui est l\'hypocrisie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Il n\'y a rien de caché qui ne se découvre, ni rien de secret qui ne finisse par être connu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'aussi tout ce que vous aurez dit dans les ténèbres, sera redit en plein jour, et ce que vous aurez murmuré à l\'oreille dans les chambres, sera publié sur les toits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Je vous dis à vous qui êtes mes amis: Ne craignez pas ceux qui tuent le corps, et qui, après cela, ne peuvent rien faire de plus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Je vais vous dire qui vous devez craindre: Craignez celui qui, après avoir ôté la vie, a le pouvoir de jeter dans la Géhenne; oui, je vous le dis, c\'est lui que vous devez craindre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne vend-on pas cinq passereaux pour deux sous? et pourtant pas un seul n\'est oublié de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'les cheveux mêmes de votre tête sont tous comptés. Ne craignez point; vous valez mieux que beaucoup de passereaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Je vous le dis, quiconque me confessera devant les hommes, le Fils de l\'homme aussi le confessera devant les anges de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'mais celui qui m\'aura renié devant les hommes, sera renié devant les anges de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Et quiconque aura parlé contre le Fils de l\'homme, en obtiendra le pardon; mais il n\'y aura point de pardon pour celui qui aura blasphémé contre le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Quand on vous mènera dans les synagogues et devant les magistrats et les autorités, ne vous inquiétez pas de savoir comment vous vous défendrez, ni ce que vous répondrez ou direz,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'car le Saint-Esprit vous enseignera à l\'heure même ce qu\'il faudra dire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Quelqu\'un de la foule lui dit: «Maître, dis à mon frère de partager avec moi notre héritage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Mais Jésus lui dit: «homme, qui m\'a établi pour être votre juge, et pour faire vos partages?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Il dit à la foule: «Gardez-vous avec soin de toute avarice, car un homme a beau être dans l\'abondance, la vie ne dépend pas de ses biens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Il leur ajouta cette comparaison: «Il y avait un homme riche dont les terres avaient beaucoup rapporté,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'et il réfléchissait en lui-même, disant: «Que ferai-je? car je n\'ai pas de place pour serrer ma récolte.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Et il se dit: «Voici ce que je ferai: j\'abattrai mes greniers, j\'en bâtirai de plus grands, et j\'y serrerai tous mes produits et tous mes biens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'et je dirai à mon âme: «Mon âme, tu as de grands biens en réserve pour plusieurs années; repose-toi, mange, bois et jouis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mais Dieu lui dit: «Insensé, cette nuit même ton âme te sera redemandée; et ce que tu as mis en réserve, pour qui sera-t-il?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Il en est ainsi de l\'homme qui thésaurise pour lui-même, et qui n\'est pas riche pour Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Et il dit à ses disciples: «C\'est pourquoi je vous dis: Ne vous mettez point en souci, ni pour votre vie, de ce que vous mangerez; ni pour votre corps, de quoi vous vous vêtirez:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'la vie est plus que la nourriture, et le corps plus que le vêtement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Considérez les corbeaux: ils ne sèment ni ne moissonnent, ils n\'ont ni cellier ni grenier; et Dieu les nourrit. Combien ne valez-vous pas mieux que ces oiseaux!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'D\'ailleurs, qui de vous peut, par ses soucis, ajouter une coudée à sa taille?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Si donc les moindres choses sont au-dessus de votre pouvoir, pourquoi vous mettez-vous en souci des autres?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considérez que les lis ne filent ni ne tissent, cependant je vous dis que Salomon même, dans toute sa magnificence, n\'était point vêtu comme l\'un de ces lis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Si Dieu revêt de la sorte, dans les champs, l\'herbe qui est aujourd\'hui et qui demain sera jetée au four, combien plus vous revêtira-t-il, vous, ô gens de peu de foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Vous aussi, ne cherchez point ce que vous mangerez et ce que vous boirez, et ne soyez point inquiets;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'car ce sont les nations du monde qui recherchent toutes ces choses: votre Père sait que vous en avez besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Mais cherchez son royaume, et toutes ces choses vous seront données par-dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, '«Ne craignez point, petit troupeau, car il a plu à votre Père de vous donner le royaume.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendez vos biens et les donnez en aumônes. Faites-vous des bourses qui ne s\'usent point, un trésor inépuisable, dans les cieux, là où le voleur ne pénètre pas, où la gerce ne gâte pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'car là où est votre trésor, là aussi sera votre coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, '«Que vos reins soient ceints, et vos lampes allumées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Vous-mêmes, soyez semblables à des gens qui attendent le moment où leur maître doit revenir des noces, afin de lui ouvrir dès qu\'il arrivera, et qu\'il heurtera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Heureux les serviteurs que le maître, à son arrivée, trouvera veillant! En vérité, je vous dis qu\'il se ceindra, qu\'il les fera mettre à table, et viendra les servir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Qu\'il vienne à la seconde veille ou qu\'il vienne à la troisième, s\'il les trouve en cet état, heureux ces serviteurs-là!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Soyez certains que si le maître de la maison savait à quel moment le voleur doit venir, il veillerait et ne laisserait pas forcer sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Vous aussi, soyez prêts, parce que le Fils de l\'homme viendra à l\'heure que vous ne pensez pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Pierre dit: «Seigneur, est-ce à nous que tu adresses cette comparaison, ou l\'adresses-tu aussi à tout le monde?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Le Seigneur dit: «Quel est donc l\'économe fidèle et sensé que le maître placera à la tête de ses gens, pour donner à chacun sa portion au moment fixé?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Heureux le serviteur que son maître, à son arrivée, trouvera agissant de la sorte!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'En vérité, je vous dis qu\'il lui donnera l\'intendance de tous ses biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mais si ce serviteur dit en lui-même, «mon maître tarde à venir,» et qu\'il se mette à battre les serviteurs et les servantes, à manger, à boire et à s\'enivrer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'son maître viendra au jour où il ne s\'y attend pas, et à l\'heure qu\'il ne sait pas; il le coupera en deux, et lui assignera sa part avec les infidèles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Le serviteur qui aura connu la volonté de son maître, et qui n\'aura pas préparé et fait toutes choses, selon sa volonté, recevra un grand nombre de coups;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'tandis que celui qui ne l\'aura pas connue et qui aura fait des choses dignes de châtiment, recevra peu de coups. On exigera beaucoup de celui à qui l\'on aura beaucoup donné, et plus on aura confié à quelqu\'un, plus on lui redemandera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, '«Je suis venu apporter le feu sur la terre, et que désiré-je, sinon qu\'il soit déjà allumé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'D\'autre part, il y a un baptême dont je dois être baptisé, et combien il me tarde qu\'il soit accompli!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Croyez-vous que je sois venu mettre la paix sur la terre? — Non, vous dis-je, mais plutôt la division;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'car désormais, s\'il y a cinq personnes dans une même maison, elles seront divisées, trois contre deux et deux contre trois:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'on sera divisé, père contre fils et fils contre père, mère contre fille et fille contre mère, la belle-mère sera contre sa belle-fille et la belle-fille contre sa belle-mère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Jésus disait aussi à la foule: «Quand vous voyez la nuée s\'élever du couchant, vous dites aussitôt: «Il va pleuvoir;» et cela arrive ainsi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Et quand vous voyez souffler le vent du midi, vous dites: «Il fera chaud;» et cela arrive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hypocrites, vous savez bien juger de l\'aspect de la terre et du ciel, comment ne jugez-vous pas du temps actuel?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Pourquoi ne discernez-vous pas de vous-mêmes ce qui est juste?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Lorsque tu te rends avec ta partie adverse devant le magistrat, mets tout en oeuvre pour te libérer d\'avec elle en chemin, de peur qu\'elle ne te traîne devant le juge, que le juge ne te livre au sergent, et que le sergent ne te jette en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Je te le dis, tu n\'en sortiras pas que tu n\'aies payé jusqu’à la dernière pite.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'En ce moment même, il se trouva là quelques personnes qui apprirent à Jésus la nouvelle de ces Galiléens, dont Pilate avait mêlé le sang à celui de leurs sacrifices?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Et lui, prenant la parole, leur dit: «Croyez-vous que ces Galiléens fussent de plus grands pécheurs que les autres Galiléens, parce qu\'ils ont souffert de la sorte?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, '— Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous semblablement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou bien, croyez-vous que ces dix-huit personnes sur qui la tour est tombée, à Siloé, et qu\'elle a tuées, fussent plus coupables que toutes celles qui habitent Jérusalem?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, '— Non, vous dis-je; mais si vous ne vous repentez, vous périrez tous semblablement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Il ajouta cette comparaison: «Un homme avait un figuier planté dans sa vigne; il alla y chercher du fruit, et n\'en trouva point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Il dit au vigneron: «Voici trois ans que je viens chercher du fruit à ce figuier et que je n\'en trouve point: coupe-le. Pourquoi occupe-t-il la terre inutilement?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Le vigneron répondit: «Seigneur, laisse-le encore cette année. Je creuserai tout autour et j\'y mettrai du fumier;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'peut-être portera-t-il du fruit; sinon tu le couperas l\'an prochain.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Un jour de sabbat, Jésus enseignait dans une synagogue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'et il vint une femme, qui, depuis dix-huit ans, était possédée d\'un esprit qui la rendait faible: elle était toute voûtée, et ne pouvait absolument pas se redresser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Jésus la voyant, l\'appela, et lui dit: «Femme, tu es délivrée de ta faiblesse;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'et il lui imposa les mains: à l\'instant elle se redressa, et glorifia Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Mais le président de la synagogue, fâché de ce que Jésus avait fait cette guérison le jour du sabbat, prit la parole, et dit à la foule: «Il y a six jours pour travailler; venez-donc vous faire guérir en ces jours-là, et non pas le jour du sabbat.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Mais le Seigneur lui répondit: «Hypocrites, est-ce que chacun de vous, le jour du sabbat, ne délie pas de la crèche son boeuf ou son âne, pour le mener boire?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Et cette fille d\'Abraham, que Satan tient liée depuis dix-huit ans, il ne fallait donc pas la délivrer de cette chaîne le jour du sabbat!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Cette réponse couvrit de confusion tous ses adversaires, et le peuple se réjouissait de toutes les merveilles que Jésus faisait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Il ajouta donc: «A quoi ressemble le royaume de Dieu, et à quoi le comparerai-je?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Il est semblable à un grain de moutarde qu\'un homme a pris et a jeté dans son jardin: le grain a poussé, il est devenu un arbre, et les oiseaux du ciel se sont abrités dans ses branches.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Il dit encore: «A quoi comparerai-je le royaume de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Il est semblable à du levain qu\'une femme a pris et mis dans trois mesures de farine, jusqu’à ce que tout ait levé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Et Jésus traversait les villes et les villages, enseignant, et faisant route vers Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Quelqu\'un lui dit: «N\'y a-t-il que peu de personnes de sauvées?» Il répondit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '«Efforcez- vous d\'entrer par la porte étroite; car beaucoup, je vous le dis, chercheront à entrer, et ne le pourront pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Une fois que le maître de la maison se sera levé, et aura fermé la porte, si vous êtes dehors, et que vous commenciez à heurter, en disant: «Seigneur, Seigneur, ouvre-nous;» il vous dira: «Je ne sais d\'où vous êtes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Alors vous vous mettrez à dire: «Nous avons mangé et bu avec toi; c\'est dans nos places publiques que tu as enseigné;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'et il répondra: «Je vous le dis, je ne sais d\'où vous êtes; éloignez-vous de moi, vous tous, ouvriers d\'iniquité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'C\'est alors qu\'il y aura des pleurs et des grincements de dents, quand vous verrez Abraham, Isaac et Jacob, et tous les prophètes, dans le royaume de Dieu, et que vous serez jetés dehors.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Il viendra de l\'orient et de l\'occident, du nord et du midi, des gens qui seront à table dans le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Et voici, il y en a des derniers qui seront les premiers, et des premiers qui seront les derniers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Ce même jour, quelques pharisiens vinrent dire à Jésus: «Pars, éloigne-toi d\'ici, parce qu\'Hérode veut te faire mourir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Il leur dit: «Allez dire à ce renard: Voici, je chasse les démons et je fais des guérisons aujourd\'hui et demain; et après-demain j\'ai fini;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'seulement il faut qu\'aujourd\'hui et demain, et après-demain, je poursuive ma route, car il ne convient pas qu\'un prophète périsse hors de Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jérusalem, Jérusalem, toi qui tues les prophètes et qui lapides ceux qui te sont envoyés, combien de fois j\'ai voulu rassembler tes enfants comme une poule rassemble sa couvée sous ses ailes, et vous ne l\'avez pas voulu!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Voici, votre maison va vous être laissée, et je vous dis que vous ne me verrez plus, jusqu’à ce que le temps vienne, où vous direz: «Béni soit celui qui vient au nom du Seigneur!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Un jour de sabbat, Jésus entra dans la maison d\'un des principaux pharisiens pour y manger; et on l\'observait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Comme il se trouvait avoir devant lui un homme hydropique,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'il prit la parole, et s\'adressant aux docteurs de la Loi et aux pharisiens, il leur dit: «Est-il permis, oui ou non, de guérir au jour du sabbat?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Ils gardèrent le silence. Alors Jésus saisissant l\'hydropique, le guérit, et le renvoya.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Puis, prenant la parole, il dit: «Qui de vous, si son fils ou son boeuf vient à tomber dans un puits, ne l\'en retire aussitôt, le jour du sabbat?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Et ils ne surent que lui répondre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Ayant remarqué que les conviés choisissaient les premières places, il leur adressa cette comparaison:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '«Quand on t\'invitera à des noces, ne prends pas la première place, de peur qu\'il ne se trouve parmi les invités un homme plus considéré que toi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'et que celui qui vous aura invités, l\'un et l\'autre, ne te dise: «Cède-lui la place,» car alors tu auras la confusion d\'aller occuper la dernière place.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Mais, lorsqu\'on t\'invite, va te mettre à la dernière place, et, quand celui qui t\'a invité viendra, il te dira: «Cher ami, monte plus haut;» alors ce sera pour toi un honneur aux yeux des autres convives.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Car quiconque s\'élève, sera abaissé; et quiconque s\'abaisse, sera élevé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Il disait aussi à celui qui l\'avait invité: «Quand tu donnes à dîner ou à souper, n\'invite ni tes amis, ni tes frères, ni tes parents, ni tes voisins riches, de peur qu\'ils ne t\'invitent aussi a leur tour et ne te rendent la pareille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Mais, quand tu donnes un repas, invite les pauvres, les estropiés, les boiteux, les aveugles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'et tu seras heureux de ce qu\'ils ne peuvent te le rendre: cela te sera rendu à la résurrection des justes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Un des convives, qui avait entendu ces recommandations, lui dit: «Heureux celui qui sera a table dans le royaume de Dieu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Jésus lui dit: «Un homme donna un grand souper, et y convia beaucoup de monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'A l\'heure du souper, il envoya son serviteur dire aux invités: «Venez, car tout est prêt.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Et ils se mirent à s\'excuser tout d\'une voix. Le premier lui dit: «J\'ai acheté un champ, et je suis forcé de sortir pour le voir; je te prie de m\'excuser.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Un autre dit: «J\'ai acheté cinq paires de boeufs, et je vais les essayer; je te prie de m\'excuser.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Un autre dit: «Je viens de me marier, ainsi je n\'y puis aller.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Le serviteur étant de retour, rapporta ces refus à son maître. Alors le maître de la maison, irrité, dit à son serviteur: «Va vite dans les places et dans les rues de la ville, et amène ici les pauvres, les estropiés, les aveugles, les boiteux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Le serviteur de retour, dit: «Maître, tes ordres ont été exécutés, et il y a encore de la place.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Et le maître dit à son serviteur: «Va dans les chemins et le long des haies, et presse les gens d\'entrer, afin que ma maison soit pleine;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'car je vous déclare qu\'aucun de ceux qui avaient été conviés, ne goûtera de mon souper.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Comme une foule considérable cheminait avec Jésus, il se retourna, et lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '«Si quelqu\'un vient à moi, et ne hait pas son père, sa mère, sa femme, ses enfants, ses frères et ses soeurs, bien plus, s\'il ne hait pas sa propre vie, il ne peut être mon disciple;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'et quiconque ne porte pas sa croix et ne me suit pas, ne peut être mon disciple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Car quel est celui d\'entre vous, qui, voulant bâtir une tour, ne s\'asseye premièrement pour calculer la dépense, et pour voir s\'il a de quoi en venir à bout?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'de peur qu\'après avoir posé les fondements de l\'édifice, il ne puisse l\'achever, et que tous ceux qui le verront ne se mettent à se moquer de lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'et à dire: «Cet homme a commencé à bâtir, et il n\'a pu achever.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou bien, quel est le roi, qui, étant sur le point d\'aller livrer bataille à un autre roi, ne s\'asseye premièrement pour délibérer, et pour voir s\'il peut, avec dix mille hommes, marcher à la rencontre d\'un ennemi qui s\'avance contre lui avec vingt mille?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Autrement, pendant que celui-ci est encore éloigné, il lui envoie une ambassade pour négocier la paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'De même, quiconque d\'entre vous ne renonce pas à tout ce qu\'il possède, ne peut être mon disciple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'C\'est donc une bonne chose que le sel; mais si le sel aussi devient insipide, avec quoi lui donnera-t-on de la saveur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Il n\'est bon ni pour la terre ni pour le fumier: on le jette dehors. Que celui qui a des oreilles pour entendre, entende.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Tous les publicains et les gens de mauvaise vie se tenaient auprès de Jésus pour l\'entendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Les pharisiens et les scribes en murmuraient, disant: «Cet homme accueille les pécheurs et mange avec eux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Mais il leur adressa cette parabole:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '«Quel est l\'homme parmi vous qui, ayant cent brebis, s\'il en perd une, ne laisse les quatre-vingt-dix-neuf autres au désert, et n\'aille après celle qui est perdue, jusqu’à ce qu\'il l\'ait retrouvée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Puis, quand il l\'a retrouvée, il la met tout joyeux sur ses épaules,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'et en rentrant chez lui il appelle ses amis.et ses voisins, et leur dit: «Félicitez-moi de ce que j\'ai retrouvé ma brebis qui était perdue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Je vous dis qu\'il y aura de même plus de joie dans le ciel pour un seul pécheur qui se repent, que pour quatre-vingt-dix-neuf justes qui n\'ont pas besoin de se repentir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou bien, quelle est la femme qui, ayant dix drachmes, si elle vient à en perdre une, n\'allume une lampe, ne balaie sa maison, et ne cherche avec soin, jusqu’à ce qu\'elle l\'ait retrouvée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Puis, quand elle l\'a retrouvée, elle appelle ses amies et ses voisines, et leur dit: «Félicitez-moi de ce que j\'ai retrouvé la drachme que j\'avais perdue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'De même, je vous le dis, il y a de la joie devant les anges de Dieu pour un seul pécheur qui se repent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Il ajouta: «Un homme avait deux fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Le plus jeune dit à son père: «Mon père, donne-moi la part de patrimoine qui me revient;» et le père leur partagea son bien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Peu de jours après, le plus jeune ayant tout ramassé, partit pour un lointain pays, et y dissipa son avoir en vivant dans la débauche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Quand il eut tout dépensé, une grande famine survint dans le pays, et il commença d\'être dans le besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Il alla se mettre au service d\'un citoyen du pays, qui l\'envoya dans ses terres garder les pourceaux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'et il aurait bien voulu se rassasier des caroubes que mangeaient les pourceaux; mais personne ne lui en donnait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Alors, rentrant en lui-même, il se dit: «Combien d\'ouvriers de mon père ont plus de pain qu\'il ne leur en faut, et moi, je meurs ici de faim.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Je me lèverai, j\'irai vers mon père, et je lui dirai: «Mon père, j\'ai péché contre le ciel et contre toi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'je ne mérite plus d\'être appelé ton fils, traite-moi comme l\'un de tes ouvriers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Et il se leva, et alla vers son père. Lorsqu\'il était encore bien loin, son père le vit, et tout ému, il courut à lui, se jeta à son cou et le baisa tendrement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Son fils lui dit: «Mon père, j\'ai péché contre le ciel et contre toi, je ne mérite plus d\'être appelé ton fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Mais le père dit à ses serviteurs: «Apportez vite une robe, la plus belle, et l\'en revêtez; mettez-lui un anneau au doigt et des sandales aux pieds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Amenez le veau gras, qu\'on le tue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'et faisons un festin de réjouissance, parce que mon fils que voici était mort, et qu\'il est revenu à la vie; il était perdu, et il est retrouvé.» Et ils se mirent à se réjouir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Cependant le fils aîné, qui était aux champs, revint, et en approchant de la maison, il entendit de la musique et des danses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Il appela un des serviteurs, et lui demanda ce que c\'était.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Le serviteur lui dit: «Ton frère est arrivé, et ton père a fait tuer le veau gras, parce qu\'il a retrouvé son fils en bonne santé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Il en fut irrité et ne voulut point entrer. Son père sortit donc et le pria instamment de venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Il répondit à son père: «Il y a tant d\'années que je te sers, sans avoir contrevenu à tes ordres, et tu ne m\'as jamais donné, à moi, un chevreau pour me réjouir avec mes amis;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'et quand ton fils, qui a dévoré ton bien avec des femmes débauchées, arrive, tu tues pour lui le veau gras!» —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, '«Mon enfant, lui dit le père, tu es toujours avec moi, et tout ce que j\'ai est à toi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'mais il fallait bien s\'égayer et se réjouir, parce que ton frère était mort, et qu\'il est revenu à la vie; il était perdu, et il est retrouvé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Jésus dit aussi à ses disciples: «Un homme riche avait un économe qu\'on lui dénonça comme dilapidant ses biens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Il le fit venir, et lui dit: «Qu\'est-ce que j\'entends dire de toi? Rends-moi compte de ta gestion, car tu ne pourras plus gérer mes biens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'L\'économe dit en lui-même: «Que ferai-je, puisque mon maître m\'ôte la gestion de ses biens? — Bêcher? je n\'en ai pas la force. — Mendier? j\'en ai honte...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'je sais ce que je ferai, afin que, lorsque j\'aurai été renvoyé de mon emploi, il y ait des gens qui me reçoivent dans leurs maisons.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Et ayant fait venir les uns après les autres tous les débiteurs de son maître, il dit au premier: «Combien dois-tu à mon maître?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Celui-ci répondit: «Cent barils d\'huile.» — «Prends ton billet, lui dit-il, assieds-toi, et dépêche-toi d\'en faire un de cinquante.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Il dit ensuite à un autre: «Et toi, combien dois-tu?» Celui-ci répondit: «Cent mesures de blé.» — «Prends ton billet, lui dit-il, et fais-en un de quatre-vingts.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Et le maître loua le savoir-faire de cet économe infidèle; car les enfants de ce siècle sont bien plus habiles entre eux que ne le sont les enfants de lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Moi aussi je vous dis: Faites-vous des amis avec les richesses, source de malversations, afin que, lorsqu\'elles vous manqueront, ils vous reçoivent dans les tabernacles éternels.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, '«Celui qui est fidèle en peu, l\'est aussi en beaucoup; et celui qui malverse dans peu, malverse aussi dans beaucoup.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Si donc vous n\'avez pas été fidèles dans les richesses, source de malversations, qui vous confiera les véritables richesses?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Et si vous n\'avez pas été fidèles dans ce qui est à autrui, qui vous donnera ce qui est à vous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nul serviteur ne peut servir deux maîtres; car, ou il haïra l\'un et aimera l\'autre, ou il s\'attachera à l\'un et méprisera l\'autre: vous ne pouvez servir Dieu et Mammon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Les pharisiens aussi, qui étaient avares, écoutaient toutes ces choses et se moquaient de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Il leur dit: «Vous êtes de ces gens qui veulent se faire passer pour justes aux yeux des hommes; mais Dieu connaît vos coeurs; car ce qui est grand pour les hommes, est une abomination devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, '«La Loi et les Prophètes vont jusqu’à Jean; dès lors le royaume de Dieu est annoncé, et l\'on y entre de vive force.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Il est plus aisé que le ciel et la terre passent, qu\'il ne l\'est qu\'une seule lettre de la Loi reste inexécutée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Quiconque répudie sa femme et en épouse une autre, commet un adultère, et celui qui épouse une femme répudiée, commet un adultère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Il y avait un homme riche, qui était vêtu de pourpre et de fin lin, et qui faisait brillante chère tous les jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Un pauvre, nommé Lazare, avait été posé à sa porte: il était couvert d\'ulcères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'et aurait bien voulu se nourrir de ce qui tombait de la table du riche. Non-seulement on ne lui donnait rien, mais encore les chiens venaient lécher ses ulcères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Le pauvre vint à mourir, et il fut porté par les anges dans le sein d\'Abraham. Le riche mourut aussi, et fut enseveli.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Comme il était dans le séjour des morts, en proie aux tourments, il leva les yeux et vit de loin Abraham, et Lazare dans son sein;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'et il s\'écria: «Père Abraham, aie pitié de moi, et envoie Lazare, afin qu\'il trempe le bout de son doigt dans l\'eau pour me rafraîchir la langue, car je souffre cruellement dans ces flammes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Mais Abraham lui dit: «Mon enfant, souviens-toi que tu as reçu tes biens pendant ta vie, et que Lazare, au contraire, a eu ses maux; maintenant ici, il est consolé, et toi, tu souffres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'D\'ailleurs, entre vous et nous, s\'ouvre un grand abîme, afin que ceux qui veulent passer d\'ici vers vous ne le puissent point, et qu\'on ne traverse pas non plus de là vers nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Le riche dit: «Père, envoie-le donc, je t\'en prie, dans la maison de mon père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'où j\'ai cinq frères, afin qu\'il les avertisse, de peur qu\'ils ne viennent aussi dans ce lieu de tourments.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Abraham lui dit: «Ils ont Moïse et les Prophètes; qu\'ils les écoutent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, '— «Non, Père Abraham, dit-il; mais si quelqu\'un se rend de chez les morts vers eux, ils se repentiront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Mais Abraham lui dit: «S\'ils n\'écoutent pas Moïse et les Prophètes, ils ne se laisseront pas persuader, quand même quelqu\'un des morts ressusciterait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Il dit à ses disciples: «Il est impossible qu\'il n\'y ait pas de scandales; mais malheur à celui par qui ils arrivent!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Il vaudrait mieux pour lui, qu\'on lui mît au cou une pierre de moulin, et qu\'on le jetât dans la mer, que d\'être une occasion de chute pour un seul de ces petits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Prenez donc garde à vous-mêmes. Si ton frère t\'a offensé, reprends-le; et, s\'il se repent pardonne-lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'et quand il t\'offenserait sept fois en un jour, s\'il revient sept fois te dire «je me repens,» tu lui pardonneras.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Les apôtres dirent au Seigneur: «Augmente-nous la foi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Mais le Seigneur leur dit: «Si vous aviez de la foi gros comme un grain de moutarde, vous diriez à ce sycomore: «Déracine-toi, et va te planter dans la mer;» et il vous obéirait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, '«Qui de vous, ayant un serviteur occupé à labourer ou à paître ses troupeaux, lui dira, à son retour des champs: «Viens vite te mettre à table?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ne lui dira-t-il pas au contraire: «Prépare-moi à souper, et ceins-toi pour me servir, jusqu’à ce que j\'aie mangé et bu; après quoi, tu mangeras et boiras?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'A-t-il de l\'obligation à son serviteur, parce qu\'il a fait ce qui lui était commandé?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Je ne le pense pas. Vous de même, quand vous aurez fait tout ce qui vous est commandé, dites: «Nous sommes des serviteurs inutiles; nous n\'avons fait que ce que nous devions faire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'En se rendant à Jérusalem, il lui arriva de passer sur les confins de la Samarie et de la Galilée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'et, comme il entrait dans un village, il rencontra dix lépreux qui se tenaient à distance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'et qui lui crièrent: «Jésus, Maître, aie pitié de nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Jésus les ayant vus, leur dit: «Allez vous montrer aux sacrificateurs;» et, en y allant, ils furent nettoyés de leur lèpre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'L\'un d\'eux, se voyant guéri, revint sur ses pas, glorifiant Dieu à haute voix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'il se jeta aux pieds de Jésus, la face contre terre, et lui rendit grâces: c\'était un Samaritain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Alors Jésus dit: «Les dix n\'ont-ils pas tous été rendus nets? où sont les neuf autres?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'N\'y a-t-il que cet étranger qu\'on ait vu revenir donner gloire à Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Et il lui dit:» Lève-toi, va; ta foi t\'a guéri.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Les pharisiens lui ayant demandé quand le royaume de Dieu devait venir, il leur répondit: «Le royaume de Dieu ne vient pas d\'une manière qui frappe les regards,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'et l\'on ne dira pas: «il est ici,» ou «il est là;» car voici, le royaume de Dieu est au dedans de vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Il dit à ses disciples: «Le temps viendra où vous souhaiterez de voir un jour, un seul des jours du Fils de l\'homme, et vous ne le verrez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'On vous dira: «Il est là; il est ici;» n\'y allez pas, n\'y courez pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'car comme l\'éclair qui luit, brille d\'un bout du ciel à l\'autre, ainsi en sera-t-il du Fils de l\'homme en son jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mais il faut auparavant qu\'il souffre beaucoup, et qu\'il soit rejeté par cette génération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, '«Et ce qui se passa au temps de Noé, se passera de même au temps du Fils de l\'homme:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'on mangeait, on buvait, on prenait et l\'on donnait en mariage, jusqu\'au jour où Noé entra dans l\'arche; et le déluge vint qui les fit tous périr.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Et comme au temps de Loth, on mangeait, on buvait, on achetait, on vendait, on plantait, on bâtissait,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'mais le jour où Loth quitta Sodome, il tomba du ciel une pluie de feu et de soufre qui les fit tous périr,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'de même en sera-t-il le jour où le Fils de l\'homme paraîtra.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, '«En ce jour-là, que celui qui sera sur le toit ne descende pas prendre ses effets qui sont dans la maison; de même, que celui qui est aux champs, ne revienne pas en arrière:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'souvenez- vous de la femme de Loth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Celui qui cherchera à conserver sa vie, la perdra; et celui qui l\'aura perdue, la retrouvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Je vous le dis, en cette nuit-là, de deux personnes qui seront dans un même lit, l’une sera prise, l\'autre, laissée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'de deux femmes qui moudront ensemble, l\'une sera prise, l\'autre, laissée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '[de deux hommes qui seront aux champs; l’un sera pris, l’autre laissé].');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Alors ses disciples prenant la parole, lui dirent: «où sera-ce, Seigneur?» Il leur répondit: «Là où sera le cadavre, là aussi s\'assembleront les vautours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Il leur montra encore par une parabole, qu\'il faut toujours prier, sans se lasser jamais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Il leur dit: «Il y avait dans une ville un juge qui ne craignait point Dieu et qui ne respectait personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Il y avait aussi dans cette ville une veuve qui venait lui dire: «Fais-moi justice de ma partie adverse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Pendant longtemps il s\'y refusa; mais ensuite il dit en lui-même: «Encore que je ne craigne point Dieu et que je ne respecte personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'toutefois, parce que cette veuve m\'importune, je lui rendrai justice, afin qu\'elle ne vienne pas éternellement me rompre la tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Le Seigneur dit: «Entendez-vous ce que dit ce juge inique?...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Et Dieu ne rendrait pas justice à ses élus, qui crient à lui jour et nuit!... et il tarde à le faire!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Je vous dis qu\'il leur rendra prompte justice; seulement, quand le Fils de l\'homme viendra trouvera-t-il la foi sur la terre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Il ajouta cette parabole, en vue de certaines personnes qui se flattent d\'être justes, et qui méprisent les autres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '«Deux hommes montèrent au temple pour prier; l\'un était pharisien, l\'autre publicain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Le pharisien, la tête haute, priait ainsi en lui-même: «Dieu, je te rends grâce de ce que je ne suis pas comme le reste des hommes, qui sont ravisseurs, injustes, adultères, ni même comme ce publicain:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'je jeûne deux fois la semaine; je donne la dîme de tous mes revenus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Et le publicain, se tenant à distance, ne se permettait pas même de lever les yeux au ciel; mais il se frappait la poitrine, en disant: «Dieu, sois apaisé envers moi, qui suis un pécheur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Je vous déclare que celui-ci s\'en alla justifié dans sa maison, plutôt que celui-là; car quiconque s\'élève sera abaissé, et celui qui s\'abaisse sera élevé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Quelques personnes lui amenèrent aussi leurs petits enfants, afin qu\'il les touchât. Ses disciples l\'ayant vu, reprenaient ces gens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'mais Jésus appela les enfants, et dit: «Laissez venir vers moi ces petits enfants, et ne les en empêchez pas, car le royaume de Dieu est à ceux qui leur ressemblent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'En vérité, je vous dis que si l\'on ne reçoit pas le royaume de Dieu avec les dispositions d\'un petit enfant, l’on n\'y entre point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Alors un président de synagogue lui adressa cette question: «Bon Maître, que dois-je faire pour hériter la vie éternelle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jésus lui dit: «Pourquoi m\'appelles-tu bon? Dieu seul est bon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu connais les commandements: «Ne commets point adultère; ne tue point; ne dérobe point; ne porte point de faux témoignage; honore ton père et ta mère»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Cet homme répondit: «J\'ai gardé tous ces commandements dès ma jeunesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Jésus, entendant cette déclaration, lui dit: «Il te manque encore une chose: vends tout ce que tu as, distribue-le aux pauvres, et tu auras un trésor dans les cieux; puis viens, et suis-moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Cet homme ayant entendu ces paroles, devint tout triste, car il était très-riche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Jésus, voyant qu\'il était devenu fort triste, se mit à dire: «Qu\'il est difficile à ceux qui possèdent les richesses d\'entrer dans le royaume de Dieu!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Car il est plus aisé qu\'un chameau passe par un trou d\'aiguille, qu\'il ne l\'est à un riche d\'entrer dans le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Ceux qui l\'écoutaient dirent: «Et qui peut être sauvé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Jésus repartit: «Ce qui est impossible aux hommes est possible à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, '— «Pour nous, dit Pierre, tu le vois, nous avons quitté nos propres affaires pour te suivre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Jésus leur dit: «En vérité, je vous le dis, personne ne quittera maison, ou femme, ou frères, ou parents, ou enfants pour le royaume de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'qu\'il ne reçoive beaucoup plus dans le temps présent, et dans le siècle à venir, la vie éternelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Jésus prit les Douze près de lui, et leur dit: «Voici que nous montons à Jérusalem, et tout ce que les prophètes ont dit du Fils de l\'homme va s\'accomplir:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'on le livrera aux Gentils, on le bafouera, on l\'outragera, on crachera sur lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'et, après l\'avoir battu de verges, on le mettra à mort; et, le troisième jour, il ressuscitera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Mais ils n\'entendirent rien à tout cela: cette parole était complètement obscure pour eux, et ils ne comprenaient pas ce qu\'il leur disait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Comme il approchait de Jéricho, un aveugle qui était assis au bord de la route, pour mendier,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'entendit la foule passer, et demanda ce que c\'était.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'On lui dit: «C\'est Jésus de Nazareth qui passe;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'et il cria: «Jésus, fils de David, aie pitié de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Ceux qui marchaient en tête, le reprenaient pour lui imposer silence, mais il criait encore plus fort: «Fils de David, aie pitié de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jésus s\'étant arrêté, ordonna qu\'on le lui amenât, et quand l\'aveugle se fut approché, il lui demanda:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '«Que veux-tu que je fasse pour toi?» — «Seigneur, dit-il, que je recouvre la vue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Et Jésus lui dit: «Recouvre la vue, ta foi t\'a guéri.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'A l\'instant il recouvra la vue; et il suivit Jésus en glorifiant Dieu. Tout le peuple témoin de cette guérison, se mit à louer Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Jésus étant entré à Jéricho, traversa la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Et un homme riche, nommé Zachée, chef des publicains,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'cherchait à voir qui était Jésus, et il ne le pouvait à cause de la foule, car il était de petite taille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Il courut donc en avant, et monta sur un sycomore pour le voir, parce qu\'il devait passer par là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Lorsque Jésus fut arrivé à cet endroit, il leva les yeux, et l\'ayant aperçu, lui dit: «Zachée, hâte-toi de descendre, car il faut que je loge aujourd\'hui chez toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Zachée se hâta de descendre, et le reçut avec joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Voyant cela, tous murmuraient, et disaient: «Il est allé loger chez un homme pécheur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Cependant Zachée se présentant devant le Seigneur, lui dit: «Voici, Seigneur, je donne la moitié de mes biens aux pauvres, et si j\'ai fait tort à quelqu\'un en quoi que ce soit, je lui rends le quadruple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jésus lui dit: «Le salut est venu aujourd\'hui sur cette maison, parce que celui-ci est aussi un fils d\'Abraham;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'car le Fils de l\'homme est venu chercher et sauver ce qui était perdu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Comme on écoutait sa parole, il ajouta une parabole, parce qu\'il était près de Jérusalem, et qu\'on s\'imaginait que le royaume de Dieu allait paraître immédiatement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Il dit donc: «Un homme de haute naissance s\'en alla dans un pays lointain, pour être investi de la royauté, et revenir ensuite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Il appela dix de ses serviteurs, leur donna dix mines, et leur dit: «Faites- les valoir, jusqu’à ce que je revienne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Mais ses concitoyens, qui le haïssaient, envoyèrent une ambassade après lui, pour dire: «Nous ne voulons pas qu\'il règne sur nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Quand il fut de retour, après avoir été investi de la royauté, il lit appeler ses serviteurs à qui il avait remis son argent, afin de connaître ceux qui l\'avaient fait valoir, et ce qu\'ils avaient gagné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Le premier serviteur vint, et dit: «Seigneur, ta mine en a rapporté dix autres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Et le roi lui dit: «C\'est bien, bon serviteur, puisque tu as été fidèle dans une chose de minime valeur, reçois le gouvernement de dix villes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Le second vint, et dit: «Seigneur, ta mine en a produit cinq autres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Le roi lui dit de même: «Toi aussi, gouverne cinq villes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Le troisième vint et dit: «Seigneur, voici ta mine que j\'ai gardée soigneusement dans un linge,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'car je te craignais, parce que tu es un homme rigide: tu retires l\'argent que tu n\'as pas placé, et tu moissonnes ce que tu n\'as pas semé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Le roi lui dit: «Mauvais serviteur, je te jugerai, sur tes propres paroles. Tu savais que je suis un homme rigide, qui retire l’argent qu\'il n\'a pas placé, et qui moissonne ce qu\'il n\'a pas semé!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'pourquoi donc n\'as-tu pas mis mon argent dans une banque? et à mon retour, je l\'aurais retiré avec intérêt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Puis, il dit à ses gardes: «Otez-lui cette mine, et la donnez à celui qui en a dix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '— Ils lui dirent: «Seigneur, il en a déjà dix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '— «Je vous dis que l\'on donnera à tout homme qui a; quant à celui qui n\'a pas, on lui ôtera même ce qu\'il a...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Seulement, amenez ici mes ennemis, ces gens qui n\'ont pas voulu que je règne sur eux, et les égorgez en ma présence.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Ayant ainsi parlé, Jésus se mit en marche, en tête de la foule, pour monter à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Lorsqu\'il approcha de Bethphagé et de Béthanie, vers la montagne appelée Bois d\'oliviers, il envoya deux de ses disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'en disant: «Allez à ce village qui est en face; en y entrant vous trouverez un ânon attaché, sur lequel jamais homme ne s\'est assis: détachez-le, et amenez-le moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Si quelqu\'un vous demande pourquoi vous le détachez, vous lui direz: «Parce que le Seigneur en a besoin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Ceux qui étaient envoyés partirent, et trouvèrent les choses comme Jésus le leur avait dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Comme ils détachaient l\'ânon, les maîtres de l\'animal leur dirent: «Pourquoi détachez-vous cet ânon?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Ils dirent: «Le Seigneur en a besoin,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'et ils l\'amenèrent à Jésus. Puis ayant jeté leurs manteaux sur l\'ânon, ils y firent monter Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Pendant que Jésus cheminait, les gens étendaient leurs manteaux sur la route;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'mais lorsqu\'il approcha de Jérusalem, déjà à la descente de la montagne des Oliviers, toute la foule des disciples, transportée d\'allégresse, se mit à louer Dieu à haute voix de tous les miracles qu\'elle avait vus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Elle disait: «Béni soit le roi qui vient au nom du Seigneur!» «Paix dans le ciel, et gloire dans les lieux très-hauts!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Quelques pharisiens mêlés à la foule, dirent à Jésus: «Maître, reprends tes disciples.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Il répondit: «Je vous dis que s\'ils se taisent, les pierres crieront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Quand il fut proche de Jérusalem, à la vue de cette ville, il pleura sur elle, et dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '«Ah! si tu connaissais, toi aussi, du moins en ce jour qui t\'est donné, les choses qui appartiennent à ta paix! Hélas! elles sont cachées à tes yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Des jours de malheur fondront sur toi: tes ennemis t\'environneront de tranchées, ils t\'investiront, ils te serreront de toutes parts,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'ils te détruiront, toi et tes enfants qui sont dans ton sein, et ils ne te laisseront pierre sur pierre, parce que tu n\'as pas connu le temps où tu as été visitée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Ensuite, étant entré dans le temple, il se mit à chasser les vendeurs, en leur disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, '«Il est écrit: «Ma maison sera une maison de prière,» mais vous, vous en avez fait «une caverne de voleurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Jésus passait toutes ses journées à enseigner dans le temple. Les principaux sacrificateurs, les scribes, ainsi que les grands cherchaient à le faire périr;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'mais ils ne savaient comment s\'y prendre, car tout le peuple s\'attachait à lui pour l\'entendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Un de ces jours-là, comme Jésus enseignait le peuple dans le temple, et lui annonçait la bonne nouvelle, les sacrificateurs et les scribes accompagnés des anciens survinrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'et s\'adressèrent à lui, disant: «Dis-nous de quel droit tu fais ces choses, et qui t\'a donné ce droit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Jésus leur répondit: «Je vous ferai aussi une question;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'dites-moi: «Le baptême de Jean venait-il du ciel ou des hommes?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Mais ils firent entre eux cette réflexion: Si nous disons «du ciel,» il dira: Pourquoi n\'y avez-vous pas cru?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'et si nous disons «des hommes,» tout le peuple nous lapidera, car il est persuadé que Jean était un prophète!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Ils répondirent qu\'ils ne savaient d\'où il venait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Et Jésus leur dit: «Moi non plus, je ne vous dirai pas de quel droit je fais ces choses.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Il se mit à adresser au peuple cette parabole: «Un homme avait planté une vigne; il l\'afferma à des vignerons, et quitta le pays pour un temps assez long.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'A l\'époque des vendanges, il envoya un serviteur vers les vignerons pour qu\'ils lui donnent une part de la récolte; mais les vignerons le battirent, et le renvoyèrent les mains vides.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Il envoya un second serviteur; ils le battirent aussi, le maltraitèrent indignement, et le renvoyèrent les mains vides.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Il en envoya encore un troisième; ils le blessèrent aussi, et le chassèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Le maître de la vigne se dit: «Que faire? Je vais envoyer mon fils bien-aimé; peut-être qu\'en le voyant, ils le respecteront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mais, quand les vignerons le virent, ils se dirent entre eux: «C\'est l\'héritier; tuons-le, pour que l\'héritage soit à nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Là-dessus, ils le jetèrent hors de la vigne, et le tuèrent. Que leur fera donc le maître de la vigne?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Il viendra, fera périr ces vignerons, et donnera la vigne à d\'autres.» A ces mots, le peuple dit: «A Dieu ne plaise!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Mais Jésus jetant les yeux sur eux, dit: «Que signifie donc cette parole de l\'Ecriture: «La pierre que les constructeurs avaient mise au rebut, est devenue la pierre angulaire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Quiconque tombera sur cette pierre, s\'y brisera; et elle écrasera celui sur qui elle tombera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Les scribes et les principaux sacrificateurs désiraient se saisir de lui sur l\'heure, mais la crainte du peuple les retint: ils avaient compris que c\'était à eux que s\'adressait cette parabole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Ils ne perdirent pas Jésus de vue, et envoyèrent des personnes insidieuses, qui contrefaisaient les justes, afin de le surprendre dans ses paroles, et de le livrer aux magistrats et au pouvoir du gouverneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Elles lui posèrent cette question: «Maître, nous savons que tu parles et enseignes comme il faut, et que tu ne fais pas acception de personnes, mais que tu enseignes en toute vérité la voie de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nous est-il permis, ou non, de payer le tribut à César?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mais Jésus ayant démêlé leur fourberie, leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '«Montrez-moi un denier?... De qui porte-il l\'effigie et la légende?» Ils répondirent: «De César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, '— «Eh bien! leur dit-il, rendez à César ce qui est à César, et à Dieu ce qui est à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Ils ne purent lui arracher aucune parole compromettante devant le peuple, et, surpris de sa réponse, ils gardèrent le silence.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Quelques sadducéens, gens qui prétendent qu\'il n\'y a point de résurrection, vinrent vers Jésus, et lui posèrent cette question:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, '«Maître, Moïse nous a donné cette loi: «Si un frère marié meurt, et meurt sans enfants, que son frère épouse sa femme et suscite lignée à son frère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Il y avait donc sept frères: le premier s\'étant marié, mourut sans enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Le second, puis le troisième épousèrent la veuve.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Il en fut de même des sept; ils moururent tous, sans laisser d\'enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Ensuite, la femme mourut aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Duquel d\'entre eux sera-t-elle donc la femme dans la résurrection, car les sept frères l\'ont eue pour femme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Jésus leur dit: «Les enfants de ce siècle, hommes et femmes, se marient,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'mais ceux qui seront jugés dignes d\'avoir part au siècle à venir, et à la résurrection d\'entre les morts, ne se marieront point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'car ils ne peuvent même pas mourir, puisqu\'ils sont comme les anges, et qu\'ils sont fils de Dieu, étant fils de la résurrection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Que les morts ressuscitent, c\'est ce que Moïse même a indiqué dans le passage où il parle du buisson; lorsqu\'il appelle le Seigneur «le Dieu d\'Abraham, le Dieu d\'Isaac et le Dieu de Jacob;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Dieu n\'est pas Dieu des morts, mais Dieu des vivants, car ils sont tous vivants pour lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Quelques scribes, ayant pris la parole, dirent: «Maître, tu as bien parlé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'En effet, on n\'osait plus lui poser une seule question.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Jésus leur dit: «Comment dit-on que le Messie est fils de David,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'quand David dit, lui-même, dans le livre des Psaumes: «Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'jusqu’à ce que j’aie fait de tes ennemis ton marchepied?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Puis donc que David l\'appelle «Seigneur,» comment est-il son fils?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Il dit à ses disciples en présence de tout le peuple, qui l’écoutait:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '«Gardez-vous des scribes, qui aiment à se promener en robes, qui recherchent les salutations dans les places publiques, les premiers sièges dans les synagogues et les premières places dans les repas:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'ces gens qui dévorent les maisons des veuves, sous prétexte de longues prières, seront jugés d\'autant plus sévèrement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Jésus, ayant levé les yeux, vit les riches qui mettaient leurs offrandes dans le tronc.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Il vit aussi une femme, une veuve très pauvre, qui y mettait deux pites;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'et il dit: «Je vous assure que cette pauvre veuve a mis plus que personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'car tous les autres ont fait offrande à Dieu de leur superflu, tandis qu\'elle a donné de son nécessaire, tout ce qu\'elle avait pour vivre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Comme quelques personnes parlaient du temple, des pierres magnifiques et des offrandes qui l\'ornent, Jésus dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '«Le temps viendra où, de tout ce que vous regardez là, il ne restera pierre sur pierre qui ne soit renversée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Ses disciples lui demandèrent: «Maître, quand sera-ce donc, et quel sera le signe précurseur de cet événement?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Il dit: «Prenez garde de vous laisser séduire; car plusieurs viendront sous mon nom, disant: «C\'est moi qui suis le Messie, et le temps est proche.» Ne vous attachez pas à eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Quand vous entendrez parler de guerres et de troubles, ne vous alarmez pas; car il faut que cela arrive premièrement, mais la fin ne viendra pas de sitôt.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Alors il ajouta: «Une nation s\'élèvera contre une nation, et un royaume contre un royaume;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'il y aura de grands tremblements de terre, et çà et là des pestes et des famines; et il paraîtra dans le ciel d\'effrayants phénomènes et de grands signes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mais auparavant l’on se saisira de vous, et l’on vous persécutera: on vous traînera dans les synagogues et dans les prisons; on vous traduira devant les rois et les gouverneurs à cause de mon nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Cela vous arrivera pour que vous me rendiez témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Mettez-vous donc bien dans l\'esprit de ne point préparer de défense,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'car je vous donnerai une parole et une sagesse, à laquelle tous vos adversaires ne pourront ni répondre, ni résister.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Vous serez livrés même par vos pères et par vos mères, par vos frères, par vos parents et par vos amis; plusieurs d\'entre vous seront mis à mort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'et vous serez haïs de tout le monde à cause de mon nom;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'mais il ne se perdra pas un cheveu de votre tête:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'par votre persévérance vous conquerrez vos âmes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, '«Lorsque vous verrez que Jérusalem va être investie par les armées, sachez que sa ruine est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Alors que ceux qui sont en Judée s\'enfuient aux montagnes; que ceux qui demeurent dans la ville en sortent, et que ceux qui demeurent dans les campagnes n\'y entrent point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'parce que ce sont les temps où la justice va accomplir tout ce qui est écrit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ce temps-là! car une grande calamité fondra sur le pays, et un grand châtiment sera, infligé à ce peuple:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'les uns tomberont sous le tranchant de l\'épée, les autres seront emmenés en esclavage parmi toutes les nations, et Jérusalem sera foulée par les Gentils, jusqu’à ce que les temps des Gentils soient accomplis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Et il y aura des signes extraordinaires dans le soleil, dans la lune et dans les étoiles; et sur la terre, on verra l\'angoisse des nations troublées par le fracas de la mer et des flots,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'et celle des hommes mourant de frayeur dans l\'attente des événements qui menacent la terre; car les puissances des cieux seront ébranlées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Alors on verra le Fils de l\'homme venir dans une nuée, revêtu d\'une grande puissance et d\'une grande gloire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Quand ces phénomènes commenceront à arriver redressez-vous et levez la tête, parce que votre délivrance approche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Et il ajouta une parabole: «Voyez le figuier et tous les arbres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'dès qu\'ils ont commencé à pousser, vous connaissez de vous-mêmes, en les voyant, que déjà l\'été est proche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'de même, quand vous verrez ces événements se produire, sachez que le royaume de Dieu est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'En vérité, je vous dis que cette génération ne passera point, que tous ces événements n\'arrivent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Le ciel et la terre passeront, mais mes paroles ne passeront point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Prenez garde à vous-mêmes; craignez que vos coeurs ne viennent à s\'appesantir par les excès, par l\'ivresse et par les soucis de la vie, et que ce jour ne fonde sur vous à l’improviste;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'car il viendra, comme un filet, s\'abattre sur tous ceux qui habitent sur la face de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Mais veillez, priant en tout temps, afin d\'être jugés dignes d\'échapper à tous ces malheurs à venir, et de trouver place devant le Fils de l\'homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Jésus passait ses journées dans le temple, à enseigner, et il s\'en allait passer les nuits à la montagne appelée Bois d\'oliviers;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'et tout le peuple venait dès le matin vers lui, dans le temple, pour l\'entendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'La fête des pains sans levain, appelée la Pâque, était proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Les principaux sacrificateurs et les scribes cherchaient comment ils pourraient se défaire de Jésus, car ils craignaient le peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Or Satan entra dans Judas, surnommé Iscariot: cet homme, l\'un des Douze,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'alla trouver les principaux sacrificateurs et les officiers des gardes du temple pour conférer avec eux sur la manière de leur livrer Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Ceux-ci en furent remplis de joie; ils convinrent de lui donner de l\'argent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'et Judas s\'étant engagé, cherchait une occasion favorable pour le leur livrer, sans provoquer d\'attroupement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Cependant le jour des pains sans levain, où l’on devait immoler la pâque, étant arrivé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Jésus envoya Pierre et Jean, en disant: «Allez nous préparer la pâque, afin que nous la mangions.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Ils lui dirent: «où veux-tu que nous la préparions?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Il leur répondit: «En entrant dans la ville, vous rencontrerez un homme qui porte une cruche d\'eau; suivez-le dans la maison où il entrera,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'et vous direz au maître de la maison: «Le maître te fait dire: où est la salle où je dois manger la pâque avec mes disciples?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Et cet homme vous montrera une grande salle haute, meublée: préparez-y tout ce qu\'il faut.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Ils s\'en allèrent, trouvèrent les choses comme il le leur avait dit; et ils préparèrent la pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Quand l\'heure fut venue, Jésus se mit à table, et les apôtres avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Et il leur dit: «J\'ai vivement désiré de manger cette pâque avec vous, avant de souffrir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'car je vous dis que je n\'y prendrai plus part, jusqu’à ce que le moment soit venu dans le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Et, ayant pris une coupe, il rendit grâces, et dit: «Prenez cette coupe et la distribuez entre vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'car je vous dis que je ne boirai pas du fruit de la vigne, jusqu’à ce que le royaume de Dieu soit venu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Puis il prit du pain, et, ayant rendu grâces, il le rompit, et le leur donna en disant: «Ceci est mon corps, qui va être donné pour vous: faites ceci en mémoire de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Après avoir soupé, il leur donna de même la coupe, en disant: «Cette coupe est la nouvelle alliance en mon sang, qui va être versé pour vous...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Seulement voici, la main de celui qui me livre est avec moi à cette table!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Car le Fils de l\'homme s\'en va selon ce qui a été arrêté; mais malheur à l\'homme par qui il est livré!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Et les disciples se mirent à se demander les uns aux autres quel était bien celui d\'entre eux qui devait commettre ce crime.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Il s\'éleva aussi une querelle entre eux, pour savoir lequel paraissait être le plus grand.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Jésus leur dit: «Les rois des nations en sont Seigneurs, et les princes qui les gouvernent sont appelés Bienfaiteurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Qu\'il n\'en soit point ainsi entre vous; mais que le plus grand parmi vous soit comme le plus petit, et celui qui est à la tête comme celui qui sert.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Car quel est le plus grand, de celui qui est à table, ou de celui qui sert? N\'est-ce pas celui qui est à table?... et moi, cependant, je suis au milieu de vous comme celui qui sert.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Vous êtes demeurés avec moi dans mes épreuves,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'c\'est pourquoi je dispose du royaume en votre faveur, comme mon Père en a disposé en ma faveur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'afin que vous mangiez et buviez à ma table dans mon royaume, et que vous soyez assis sur des trônes, pour juger les douze tribus d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, '«Simon, Simon, Satan vous a réclamés, pour vous cribler comme on crible le froment;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'mais j\'ai prié pour toi, afin que ta foi ne défaille point; et toi, quand tu seras venu à résipiscence, affermis tes frères.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, '— «Seigneur, lui dit Pierre, je suis prêt à aller avec toi, et en prison et à la mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Jésus lui répondit: «Je te dis, Pierre, que le coq ne chantera pas aujourd\'hui, que tu n\'aies nié trois fois de me connaître.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Ensuite il dit à ses disciples: «Lorsque je vous ai envoyés sans bourse, sans sac ni sandales, avez-vous manqué de quelque chose?» — «Non, de rien,» répondirent-ils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Il leur dit donc: «Eh bien! maintenant, que celui qui a une bourse la prenne, et un sac également; et que celui qui n\'a point d\'épée vende son manteau pour en acheter une;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'car je vous dis, que cette parole des Écritures «et il a été mis an nombre des criminels,» doit encore s\'accomplir en ma personne: ce qui me concerne touche à sa fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Ils lui dirent: «Seigneur, il y a ici deux épées.» Il leur répondit: «Cela suffit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Puis il sortit, et s\'achemina, selon sa coutume, vers la montagne des Oliviers. Ses disciples aussi l\'accompagnèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Quand il fut arrivé au lieu où il se rendait, il leur dit: «Priez, de peur que vous ne tombiez en tentation;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'et il s\'éloigna d\'eux, à la distance d\'environ un jet de pierre, et s\'étant mis à genoux, il pria,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'disant: «Père, si tu voulais faire passer ce calice loin de moi! toutefois que ta volonté soit faite, et non la mienne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Un ange venu du ciel, lui apparut pour le fortifier,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'et, étant dans l\'agonie, Jésus priait avec plus d\'ardeur. Sa sueur était pareille à des caillots de sang, qui tombaient à terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Après avoir prié, il se leva, vint vers ses disciples, qu\'il trouva endormis de tristesse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'et leur dit: «Pourquoi donnez-vous? Levez-vous, et priez, de peur que vous ne tombiez en tentation.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Il parlait encore, lorsqu\'une troupe parut. Celui qu\'on appelait Judas, l\'un des Douze, marchait en tête; et il s\'approcha de Jésus pour le baiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jésus lui dit: «Judas, c\'est par un baiser que tu livres le Fils de l\'homme!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Ceux qui accompagnaient Jésus, voyant ce qui allait arriver, dirent: «Seigneur, si nous frappions de l\'épée?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'et l\'un d\'eux frappa le serviteur du souverain sacrificateur, et lui emporta l\'oreille droite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Mais Jésus prenant la parole, dit: «Arrêtez! attendez!...» et, ayant touché l\'oreille de cet homme, il le guérit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Il dit aux principaux sacrificateurs, aux officiers des gardes du temple et aux anciens qui étaient venus pour le saisir: «Vous êtes venus avec des épées et des bâtons, comme si vous poursuiviez un brigand.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'J\'étais pourtant tous les jours avec vous dans le temple, et vous ne m\'avez pas arrêté; mais c\'est ici votre heure et la puissance des ténèbres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Alors ils se saisirent de lui, l’emmenèrent, et le conduisirent dans le palais du souverain sacrificateur. Pierre suivait de loin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Les soldats allumèrent du feu au milieu de la cour, et s\'assirent. Pierre prit place parmi eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Une servante l\'apercevant assis près du feu, le regarda fixement, et dit: «Celui-ci était aussi avec lui;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'mais Pierre renia Jésus, en disant: «Femme, je ne le connais pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Un instant après, une autre personne le voyant, dit: «Toi aussi, tu es un de ces gens-là.» Pierre dit: «Non, je n\'en suis point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Il s\'était à peine écoulé une heure, qu\'une autre personne insista, disant: «Certainement cet homme était aussi avec lui, car il est Galiléen.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Pierre répondit: «Je ne sais ce que tu veux dire.» Au même instant, comme il parlait encore, un coq chanta:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'le Seigneur s\'étant retourné, regarda Pierre.- Alors Pierre se souvint de la parole que le Seigneur lui avait dite, «avant que le coq chante aujourd\'hui, tu me renieras trois fois;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'et, étant sorti du palais, il pleura amèrement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Ceux qui tenaient Jésus, le bafouaient, et le frappaient:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'ils lui avaient bandé les yeux et lui demandaient: «Devine qui t\'a frappé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Et ils lui disaient beaucoup d\'autres injures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Dès qu\'il fit jour, le corps des anciens du peuple s\'assembla avec les principaux sacrificateurs et les scribes, et ayant fait introduire Jésus dans leur Sanhédrin,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'ils lui dirent: «Si tu es le Messie, dis-le nous.» — «Si je vous le dis, leur répondit-il, vous ne le croirez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'et si je vous interroge, vous ne répondrez pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'mais désormais le Fils de l’homme sera assis à la droite du Dieu tout-puissant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Ils s\'écrièrent tous: «Tu es donc le Fils de Dieu?» Il leur répondit: «Vous le dites, je le suis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Alors ils dirent: «Qu’avons-nous encore besoin de témoignage? nous l\'avons entendu nous-mêmes de sa bouche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Ils se levèrent en masse, et conduisirent Jésus devant Pilate.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Ils se mirent à l\'accuser, disant: «Nous avons trouvé cet homme qui poussait notre nation à la révolte, et qui défendait de payer le tribut à César, se prétendant lui-même Messie, Roi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilate l\'interrogea, disant: «Tu es le roi des Juifs?» — «Tu le dis,» lui répondit Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilate dit aux principaux sacrificateurs et à la foule: «Je ne trouve rien de criminel en cet homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mais ils insistèrent, disant: «Il agite le peuple, en enseignant par toute la Judée, après avoir commencé par la Galilée, et être venu jusqu\'ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Pilate, entendant nommer la Galilée, demanda si cet homme était Galiléen;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'et ayant appris qu\'il était de la juridiction d\'Hérode, il le renvoya à Hérode, qui était aussi à Jérusalem en ces jours-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Hérode eut une grande joie de voir Jésus, car depuis longtemps il en avait le désir, parce qu\'il avait entendu parler de lui, et qu\'il espérait le voir faire quelque miracle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Il lui adressa un grand nombre de questions, mais Jésus ne lui répondit rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Or les principaux sacrificateurs et les scribes étaient là, qui l\'accusaient avec véhémence;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'mais Hérode avec sa garde le traita avec mépris: il le fit revêtir par dérision d\'un magnifique manteau, et le renvoya à Pilate.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Le jour même, Pilate et Hérode devinrent amis, d\'ennemis qu\'ils étaient auparavant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilate, ayant assemblé les principaux sacrificateurs, les sénateurs et le peuple, leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, '«Vous avez traduit devant moi cet homme, comme excitant le peuple à la révolte, et, après l\'avoir interrogé en votre présence, je ne l\'ai trouvé coupable d\'aucun des crimes dont vous l\'accusez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Hérode non plus, car je vous ai renvoyés à lui, et, vous le voyez, cet homme n\'a rien fait qui mérite la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Je le relâcherai donc, après l\'avoir fait châtier.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '[Or il était obligé à chaque fête de leur relâcher un prisonnier]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Mais ils crièrent tous à la fois: «Fais-le mourir! Relâche-nous Barabbas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Ce Barabbas avait été mis en prison pour une sédition qui avait eu lieu dans la ville, et pour un meurtre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilate, qui désirait relâcher Jésus, les harangua donc de nouveau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'mais ils répondirent par les cris de «crucifie-le! crucifie-le!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Il leur dit pour la troisième fois: «Quel mal a-t-il donc fait? Je n\'ai rien trouvé en lui qui mérite la mort; je le relâcherai donc, après l\'avoir fait châtier?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mais ils insistèrent, demandant à grands cris qu\'il fût crucifié, et leurs clameurs et celles des principaux sacrificateurs prévalurent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'et Pilate prononça que ce qu\'ils demandaient serait exécuté:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'il leur relâcha celui qui avait été mis en prison pour sédition et pour meurtre, et qu\'ils réclamaient; et il leur abandonna Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Comme ils l\'emmenaient au supplice, ils prirent un nommé Simon, de Cyrène, qui venait des champs, et ils le chargèrent de la croix, pour qu\'il la portât derrière Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Or, Jésus était suivi d\'une grande foule de peuple, et particulièrement de femmes qui se frappaient la poitrine et pleuraient sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Il se tourna vers elles, et leur dit: «Filles de Jérusalem, ne pleurez pas sur moi, mais pleurez sur vous-mêmes et sur vos enfants;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'car les temps viennent où l’on dira: «Heureuses les stériles! Heureux le sein qui n\'a point enfanté! Heureuses les mamelles qui n\'ont point nourri!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Alors on se mettra à dire aux montagnes: «Tombez sur nous;» et aux collines: «Couvrez-nous;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'car si l\'on fait ces choses au bois vert, que fera-t-on au bois sec?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Les soldats conduisaient en même temps deux malfaiteurs pour être mis à mort avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Quand ils furent arrivés au lieu appelé Calvaire, ils y crucifièrent Jésus, ainsi que les malfaiteurs, l\'un à sa droite, l\'autre à sa gauche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'et Jésus dit: «Père, pardonne-leur, car ils ne savent ce qu\'ils font.» Ils se partagèrent ses vêtements en les tirant au sort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Le peuple était là qui regardait. Les sénateurs se moquaient et disaient: «Il en a sauvé d\'autres, qu\'il se sauve lui-même, s\'il est le Messie, l\'élu de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Les soldats aussi, s\'approchant pour lui présenter du vinaigre, le raillaient,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'et disaient: «Si tu es le roi des Juifs, sauve-toi toi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Il y avait même une inscription au-dessus de sa tête, portant: «Celui-ci est le Roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'L\'un des malfaiteurs pendus à la croix, l\'injuriait, disant: «N\'es-tu pas le Messie? Sauve-toi toi-même, et nous avec toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mais l\'autre le reprenait: «N\'as-tu point de crainte de Dieu, toi qui subis le même jugement?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Pour nous, c\'est justice; car nous recevons la peine que nos crimes ont méritée; mais lui, il n\'a rien fait de mal.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Et il dit à Jésus: «Souviens-toi de moi, quand tu seras dans ton règne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Et Jésus répondit: «Je te dis en vérité, qu\'aujourd\'hui même tu seras avec moi dans le paradis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Il était déjà environ la sixième heure, quand des ténèbres se répandirent sur tout le pays jusqu’à la neuvième heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Le soleil pâlit; le voile du temple se déchira par le milieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'et Jésus s\'écria d\'une voix forte: «Père, je remets mon esprit entre tes mains.» En prononçant ces mots, il expira.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Le centurion, témoin de ces événements, donna gloire à Dieu, disant: «Assurément cet homme était juste;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'et les foules que ce spectacle avait attirées, voyant ce qui s\'était passé, s\'en retournaient toutes en se frappant la poitrine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Mais tous ceux qui connaissaient Jésus, et les femmes qui l\'avaient suivi de Galilée, se tenaient là, à l\'écart, regardant ce qui se passait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Il y avait un sénateur, nommé Joseph, homme droit et juste,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'qui ne s\'était associé ni au dessein, ni aux actes des autres sénateurs; il était originaire d\'Arimathée. ville des Juifs, et il attendait le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Il se rendit auprès de Pilate et lui demanda le corps de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Il le descendit de la croix, l\'enveloppa d\'un linceul, et le déposa dans un sépulcre taillé dans le roc, où personne n\'avait encore été mis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'C\'était le jour de la préparation, et le sabbat allait commencer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Les femmes qui étaient venues de la Galilée avec Jésus, ayant accompagné Joseph, virent le sépulcre et la manière dont le corps de Jésus y fut placé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'puis, s\'en étant retournées, elles préparèrent des aromates et des parfums.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Le jour du sabbat, elles se reposèrent, selon le commandement; mais, le premier jour de la semaine, à l\'aube, elles se rendirent au tombeau, portant les aromates qu\'elles avaient préparés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Elles trouvèrent qu\'on avait roulé la pierre loin du sépulcre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'et, étant entrées, elles ne trouvèrent point le corps du Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Elles ne savaient qu\'en penser, lorsque leur apparurent deux hommes vêtus d\'habits d\'une éclatante blancheur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Comme elles étaient saisies de frayeur, et qu\'elles baissaient la tête vers la terre, ils leur dirent: «Pourquoi cherchez-vous parmi les morts celui qui est vivant?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Il n\'est point ici, mais il est ressuscité. Rappelez- vous la manière dont il vous a parlé, quand, étant encore en Galilée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'il vous disait qu\'il fallait que le Fils de l\'homme fût livré entre les mains des pécheurs, qu\'il fût crucifié, et qu\'il ressuscitât le troisième jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Alors, elles se ressouvinrent des paroles de Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'et, à leur retour du sépulcre, elles rapportèrent toutes ces choses aux Onze et à tous les autres disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Celles qui leur firent ce rapport, étaient Marie Madeleine, Jeanne, Marie, mère de Jacques, et les autres femmes qui étaient avec elles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'mais les apôtres ne virent dans ce rapport que des rêveries et ne crurent point ces femmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, '[Toutefois Pierre se leva, courut au sépulcre, et, s\'étant baissé, il vit les bandes qui étaient à terre, toutes seules, et s\'en retourna chez lui, surpris de ce qui était arrivé.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Ce même jour, deux disciples allaient dans un village nommé Emmaüs, éloigné de Jérusalem de soixante stades;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'et ils s\'entretenaient de tous ces événements.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Pendant qu\'ils parlaient et discutaient, Jésus lui-même s\'approcha, et fit route avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mais ils avaient comme un bandeau sur les yeux, de sorte qu\'ils ne le reconnurent point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Il leur dit: «De quoi vous entretenez-vous chemin faisant?... et vous êtes tout tristes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'L\'un d\'eux, qui s\'appelait Cléopas, lui répondit: «Tu es bien le seul dans Jérusalem, qui ne sache pas ce qui s\'est passé ces derniers jours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, '— «Et quoi?» leur dit-il. Ils lui répondirent: «Ce qui est arrivé à Jésus de Nazareth, qui était un prophète puissant en oeuvres et en paroles, devant Dieu et devant tout le peuple:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'comment nos principaux sacrificateurs et nos sénateurs l\'ont livré pour être condamné à mort, et l\'ont crucifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Pour nous, nous espérions que ce serait lui qui délivrerait Israël; mais, après tout cela, voici le troisième jour, aujourd\'hui, que ces événements se sont passés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Il est vrai que des femmes qui sont avec nous, nous ont extraordinairement surpris: elles s\'étaient rendues au point du jour au sépulcre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'et, n\'ayant point trouvé son corps, elles sont venues dire que des anges leur sont apparus, et qu\'ils le disent vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Quelques-uns des nôtres sont allés au sépulcre, ils ont trouvé toutes choses comme les femmes l’avaient annoncé; mais lui, ils ne l’ont pas vu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Alors il leur dit: «Hommes dépourvus de sens, esprits lents à croire tout ce qu\'ont dit les prophètes!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ne fallait-il pas que le Messie passât par ces souffrances pour entrer dans sa gloire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Puis, commençant par Moïse, et poursuivant par tous les prophètes, il leur expliqua, dans toutes les Ecritures, ce qui le concernait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Cependant ils approchèrent du village où ils se rendaient, et comme l’étranger paraissait vouloir aller plus loin,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'ils le pressèrent de s\'arrêter, disant: «Reste avec nous; car voici le soir, et le jour a déjà baissé;»et il entra dans le village pour rester avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Quand il se mit à table avec eux, il prit le pain, et ayant prononcé la bénédiction, il le rompit, et le leur donna:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'alors leurs yeux se dessillèrent; ils le reconnurent; mais il disparut de devant leurs yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Ils se dirent l\'un à l\'autre: «Notre coeur n\'était-il pas tout brûlant au dedans de nous, lorsqu\'il nous parlait en chemin, et qu\'il nous expliquait les Écritures?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Et, se levant à l\'heure même, ils retournèrent à Jérusalem. Ils trouvèrent réunis les Onze et leurs compagnons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'qui leur dirent: «Le Seigneur est réellement ressuscité, et il est apparu à Simon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Ils racontèrent à leur tour, ce qui leur était arrivé en chemin, et comment ils l\'avaient reconnu au moment où il avait rompu le pain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Pendant qu\'ils s\'entretenaient ainsi, lui-même parut au milieu d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Frappés de stupeur et d\'effroi, ils crurent voir un esprit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'et Jésus leur dit: «Pourquoi êtes-vous troublés? Pourquoi vous faites-vous des idées folles?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Voyez mes mains et mes pieds: c\'est bien moi. Palpez-moi, et considérez qu\'un esprit n\'a ni chair ni os, comme vous voyez que j\'en ai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, '[Après avoir ainsi parlé, il leur montra ses mains et ses pieds.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Comme la joie les rendait encore incrédules, et qu\'ils ne revenaient pas de leur surprise, il leur dit: «Avez-vous ici quelque chose à manger?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Ils lui présentèrent un morceau de poisson rôti et un rayon de miel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Il les prit, et les mangea devant eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Puis il leur, dit: «C\'est là ce que je vous annonçais quand j\'étais encore avec vous; je vous disais qu\'il fallait que s\'accomplit tout ce qui est écrit de moi dans la Loi de Moïse, dans les Prophètes et dans les Psaumes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Alors il leur ouvrit l\'esprit, afin qu\'ils entendissent les Ecritures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Et il leur dit: «C\'est ainsi qu\'il est écrit que le Messie souffrirait, et qu\'il ressusciterait des morts le troisième jour,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'et qu\'on prêcherait en son nom la repentance et le pardon des péchés à toutes les nations, en commençant par Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vous êtes témoins de ces faits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Maintenant, je vais vous envoyer ce que mon Père vous a promis; pour vous, demeurez tranquillement dans la ville, jusqu\'à ce que vous soyez revêtus d\'une puissance qui vient d\'en haut.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Il les emmena hors de la ville, jusqu’à Béthanie; et, élevant les mains, il les bénit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Pendant qu\'il les bénissait, il se sépara d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Pour eux, ils s\'en retournèrent à Jérusalem, pleins d\'une grande joie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'et ils étaient continuellement dans le temple, louant et bénissant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Au commencement était la Parole; la Parole était avec Dieu, et la Parole était dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Elle était au commencement avec Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Toutes choses ont été faites par elle, et rien de ce qui a été fait, n\'a été fait sans elle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'En elle était la vie, et cette vie était la lumière des hommes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'la lumière brille dans les ténèbres, mais les ténèbres ne l\'ont point reçue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Un homme parut; il était envoyé de Dieu, son nom était Jean.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Il vint pour un témoignage, pour rendre témoignage à la Lumière, afin que tous crussent par lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'il n\'était pas la Lumière, mais il devait rendre témoignage à la Lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'La véritable Lumière, qui éclaire tout homme, était entrée dans le monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'elle était dans le monde, et le monde a été fait par elle, mais le monde ne l\'a point connue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Elle est venue chez les siens, et les siens ne l\'ont point reçue;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'mais à tous ceux qui l\'ont reçue, à tous ceux qui croient en son nom, elle a donné la prérogative d\'être enfants de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'enfants, qui ne sont pas nés du sang, ni de la volonté de la chair, ni de la volonté de l\'homme, mais qui sont nés de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Et la Parole a été faite chair; elle a habité au milieu de nous pleine de grâce et de vérité, et nous avons contemplé sa gloire, une gloire comme celle d\'un fils unique envoyé par son père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jean lui rend témoignage, quand il dit à haute voix: «Voici celui dont je disais: Celui qui vient après moi. a pris le pas devant moi, parce qu\'il est plus grand que moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'C\'est de sa plénitude que nous avons tous reçu grâce sur grâce;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'car la Loi a été donnée par Moïse; mais la Grâce et la Vérité sont venues par Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Personne n\'a jamais vu Dieu; le Fils unique, qui est dans le sein du Père, est celui qui l\'a révélé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Voici le témoignage que rendit Jean, lorsque les Juifs envoyèrent de Jérusalem des sacrificateurs et des lévites pour lui adresser cette question: «Qui es-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Il le déclara, et ne le nia point; il déclara qu\'il n\'était pas le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, '— «Quoi donc! Es-tu Élie?» lui demandèrent-ils; et il dit: «Je ne le suis point.» - «Es-tu le Prophète?» et il répondit: «Non.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Ils lui dirent donc: «Qui es-tu? afin que nous rendions réponse à ceux qui nous ont envoyés. Que dis-tu que tu es?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, '— «Moi, dit-il, je suis «une voix qui crie au désert: Redressez le chemin du Seigneur,» comme a dit le prophète Ésaïe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Ceux qu\'on avait envoyés étaient des pharisiens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Ils insistèrent, et lui dirent: «Pourquoi donc baptises-tu, si tu n\'es pas le Messie, ni même Elie ou le Prophète?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Jean leur répondit: «Pour moi, je baptise d\'eau, mais il y a au milieu de vous quelqu\'un que vous ne connaissez pas:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'c\'est celui qui vient après moi; je ne suis pas digne de délier la courroie de ses sandales.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ces choses se passèrent à Béthanie, au delà du Jourdain, où Jean baptisait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Le lendemain, Jean vit Jésus qui venait vers lui, et il dit: «Voici l\'agneau de Dieu qui ôte le péché du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'C\'est de lui que j\'ai dit: Il vient après moi un homme qui a pris le pas devant moi, parce qu\'il est plus grand que moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Je ne le connaissais pas; mais je suis venu baptiser d\'eau, afin qu\'il fût manifesté à Israël»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'et Jean avait rendu ce témoignage: «J\'ai vu l\'Esprit descendre du ciel comme une colombe, et demeurer sur lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Je ne le connaissais pas; mais celui-là même qui m\'a envoyé baptiser d\'eau m\'a dit: «Celui sur qui tu verras l\'Esprit descendre et demeurer, c\'est lui qui baptise d\'esprit saint.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Je l\'ai vu, et j\'ai rendu témoignage que c\'est lui qui est le Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Le lendemain, Jean se trouvait là de nouveau, avec deux de ses disciples;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'et, ayant considéré Jésus qui passait, il dit: «Voilà l\'agneau de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Ces deux disciples l\'ayant entendu parler de la sorte, suivirent Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jésus s\'étant retourné, et voyant qu\'ils le suivaient, leur dit. «Que cherchez- vous?» Ils lui dirent: «Rabbi,»(ce qui signifie Maître) «où demeures-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, '— «Venez, leur dit-il, et vous verrez. Ils allèrent, et ils virent où il demeurait, et ils restèrent auprès de lui ce jour-là. C\'était environ la dixième heure du jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'André, frère de Simon-Pierre, était l\'un des deux disciples qui avaient entendu la parole de Jean, et qui avaient suivi Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Il rencontra, le premier, son frère Simon, et il lui dit: «Nous avons trouvé le Messie» (ce qui signifie Christ);');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'et il le mena vers Jésus. Celui-ci, l\'ayant considéré, lui dit: «Tu es Simon, fils de Jona; on t\'appellera Céphas» (ce qui signifie Pierre).');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Le lendemain, Jésus résolut de partir pour la Galilée. Il rencontra Philippe, et lui dit: «Suis-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Philippe était de la ville de Bethsaïde, d\'où étaient aussi André et Pierre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippe rencontra Nathanaël, et lui dit: «Nous avons trouvé celui dont Moïse a parlé dans la Loi, et que les prophètes ont annoncé; c\'est Jésus, fils de Joseph, de Nazareth.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Nathanaël lui dit: «Peut-il sortir de Nazareth quelque chose de bon?» Philippe lui répondit: «Viens et vois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jésus voyant venir Nathanaël, dit en parlant de lui: «Voici un vrai Israélite, un homme sans détour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, '— «D\'où me connais-tu?» lui dit Nathanaël. Jésus lui répondit: «Avant que Philippe t\'appelât, je t\'ai vu sous le figuier.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, '— «Maître, lui repartit Nathanaël, tu es le Fils de Dieu, tu es le roi d\'Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jésus répondit et lui dit: «Parce que je t\'ai dit que je t\'ai vu sous le figuier, tu crois! Tu verras de plus grandes choses que celles-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Et il ajouta: «En vérité, en vérité, je vous le dis, vous verrez désormais le ciel ouvert, et les anges de Dieu monter et descendre sur le Fils de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Trois jours après, il se fit des noces à Cana en Galilée, et la mère de Jésus y était.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Jésus fut aussi convié aux noces avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Le vin ayant manqué, la mère de Jésus lui dit: «Ils n\'ont point de vin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jésus lui dit: «Femme, qu\'y a-t-il entre toi et moi? Mon heure n\'est pas encore venue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sa mère dit aux serviteurs: «Faites ce qu\'il vous dira.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Or, il y avait là six vases de pierre servant aux ablutions des Juifs, de la contenance de deux ou trois métrètes chacun.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jésus leur dit: «Remplissez d\'eau ces vases;» et ils les remplirent jusqu\'au bord.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, '«Puisez maintenant, leur dit-il, et portez-en au chef de table;» et ils en portèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Dès que le chef de table eut goûté de cette eau changée en vin (il ne savait pas d\'où venait ce vin, mais les serviteurs le savaient bien, eux qui avaient puisé l\'eau), il interpella l\'époux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'et lui dit: «Tout le monde sert d\'abord le bon vin, et, quand on a beaucoup bu, le moins bon; mais toi, tu as gardé le bon vin jusqu’à cette heure.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ce fut là le premier des miracles de Jésus, et il le fit à Cana en Galilée: il manifesta sa gloire, et ses disciples crurent en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Ensuite, il descendit à Capernaoum avec sa mère, ses frères et ses disciples, et ils n\'y demeurèrent que peu de jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'La Pâque des Juifs étant proche, Jésus monta à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Il trouva dans le temple des marchands de boeufs, de moutons et de pigeons, ainsi que les changeurs tout établis;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'et, ayant fait un petit fouet de cordes, il les chassa tous du temple, moutons et boeufs, il jeta par terre la monnaie des changeurs, renversa leurs banques,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'et il dit aux marchands de pigeons: «Otez cela d\'ici; ne faites pas de la maison de mon Père une maison de trafic»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Ses disciples se souvinrent qu\'il est écrit: «Le zèle de ta maison me dévore.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Les Juifs prenant la parole, lui dirent: «Par quel miracle nous prouves-tu que tu as le droit d\'agir de la sorte?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jésus leur répondit: «Détruisez ce temple, et, en trois jours, je le relèverai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Les Juifs repartirent: «On a mis quarante-six ans à bâtir ce temple, et toi, en trois jours, tu le relèveras!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Mais lui parlait du temple de son corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Quand donc il fut ressuscité des morts, ses disciples se souvinrent qu\'il avait dit cela, et ils ajoutèrent foi à l\'Écriture, et à la parole que Jésus avait prononcée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Pendant qu\'il était à Jérusalem, à la fête de Pâque, plusieurs crurent en son nom, en voyant les miracles qu\'il faisait;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'mais Jésus ne se fiait point à eux, parce qu\'il les connaissait tous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'et qu\'il n\'avait pas besoin qu\'on lui rendît témoignage d\'aucun homme: il connaissait lui-même ce qu\'il y a dans l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Il y avait, parmi les pharisiens, un homme qui s\'appelait Nicodème: c\'était un sénateur juif.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Il vint de nuit trouver Jésus, et lui dit: «Maître, nous savons que tu es un docteur venu de Dieu, car nul ne peut faire les miracles que tu fais, si Dieu n\'est avec lui...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jésus répondit et lui dit: «En vérité, en vérité, je te le dis, si l’on ne naît à nouveau, on ne peut voir le royaume de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodème lui dit: «Comment un homme qui est vieux, peut-il naître? peut-il rentrer dans le sein de sa mère et naître?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jésus répondit: «En vérité, en vérité, je te dis que si l’on ne naît, d\'eau et d\'esprit, on ne peut entrer dans le royaume de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'ce qui est né de la chair est chair, et ce qui est né de l\'esprit est esprit...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne t\'étonne point de ce que je t\'ai dit qu\'il vous faut naître à nouveau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Le vent souffle où il veut, et tu en entends le bruit; mais tu ne sais d\'où il vient ni où il va; ainsi en est-il de tout homme qui est né de l\'esprit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodème lui dit: «Comment cela peut-il se faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jésus lui répondit: «Tu es le docteur d\'Israël, et tu ne sais pas ces choses!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'En vérité, en vérité, je te dis que nous disons ce que nous savons, et que nous rendons témoignage de ce que nous avons vu; mais vous ne recevez pas notre témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Si, quand je vous parle des choses terrestres, vous ne croyez pas, comment croirez-vous quand je vous parlerai des choses célestes?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Nul n\'est monté au ciel, que celui qui est descendu du ciel, le Fils de l\'homme qui était dans le ciel;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'et, comme Moïse éleva le serpent dans le désert, il faut de même que le Fils de l’homme soit élevé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'afin que quiconque croit en lui ait la vie éternelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'En effet, Dieu a tant aimé le monde, qu\'il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu\'il ait la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Dieu n\'a pas envoyé son Fils dans le monde, pour juger le monde, mais afin que le monde soit sauvé par lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Celui qui croit en lui n\'est point jugé, mais celui qui ne croit pas en lui est déjà jugé, parce qu\'il n\'a pas cru au nom du Fils unique de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'et voici ce jugement: la lumière est venue dans le monde, mais les hommes ont mieux aimé les ténèbres que la lumière, parce que leurs oeuvres étaient mauvaises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Car tout homme qui fait le mal, hait la lumière, et il ne s\'approche point de la lumière, de peur que la méchanceté de ses oeuvres ne soit mise en évidence;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'mais celui qui pratique la vérité, s\'approche de la lumière, afin que ses oeuvres soient manifestées, parce qu\'elles sont faites en Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Après cela, Jésus se rendit dans les campagnes de la Judée avec ses disciples; il y séjourna avec eux, et il baptisait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Jean baptisait aussi à Énon, près de Salim, parce qu\'il y avait là beaucoup d\'eau; et l’on venait s\'y faire baptiser,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'car Jean n\'avait pas encore été mis en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Il s\'éleva donc une dispute entre les disciples de Jean et un Juif au sujet du baptême.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Les disciples vinrent vers Jean, et lui dirent: «Maître, celui qui était avec toi au delà du Jourdain, et à qui tu as rendu témoignage, le voilà qui baptise; et tout le monde va vers lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Jean répondit et dit: «Un homme ne peut rien recevoir, s\'il ne lui a été donné du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vous m\'êtes vous-mêmes témoins, que j\'ai dit: «Je ne suis pas le Messie, mais j\'ai été envoyé devant lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Celui qui a l\'épouse est l\'époux; mais l\'ami de l\'époux, qui se tient là et qui l\'écoute, est ravi de joie d\'entendre la voix de l\'époux: cette joie donc est la mienne, et elle est parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Il faut qu\'il croisse et que je diminue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Celui qui vient d\'en haut est au-dessus de tous. Celui qui vient de la terre est de la terre, et il parle comme étant de la terre; celui qui vient du ciel est au-dessus de tous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'et il rend témoignage de ce qu\'il a vu et entendu; mais nul ne reçoit son témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Celui qui reçoit son témoignage certifie que Dieu est vrai;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'car celui que Dieu a envoyé profère les paroles de Dieu, parce que Dieu ne lui donne pas son Esprit par mesure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Le Père aime le Fils et a remis toutes choses entre ses mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Celui qui croit au Fils a la vie éternelle; celui qui ne croit point au Fils ne verra point la vie, mais la colère de Dieu demeure sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Lorsque le Seigneur sut que les pharisiens avaient appris qu\'il faisait et baptisait plus de disciples que Jean');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(toutefois ce n\'était pas Jésus lui-même qui baptisait, mais c\'étaient ses disciples),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'il quitta la Judée et retourna en Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Or il fallait qu\'il passât par la Samarie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Il arriva donc à une ville de Samarie, nommée Sychar, située près du fond de terre que Jacob avait donné à son fils Joseph.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Là, se trouvait la fontaine de Jacob. Jésus, fatigué de la route, s\'assit tout simplement au bord de la fontaine. C\'était environ la sixième heure du jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Une femme samaritaine étant venue pour puiser de l\'eau, Jésus lui dit: «Donne-moi à boire;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'car ses disciples étaient allés à la ville pour acheter des vivres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Cette femme samaritaine lui dit donc: «Comment, toi qui es Juif, me demandes-tu à boire, à moi qui suis une femme samaritaine?» Les Juifs, en effet, ne frayent pas avec les Samaritains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jésus lui répondit: «Si tu connaissais la grâce que Dieu te fait, et qui est celui qui te dit, «donne-moi à boire,» tu lui aurais toi-même demandé à boire, et il t\'aurait donné de l\'eau vive.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, '— «Seigneur, lui dit cette femme, tu n\'as point de seau, et le puits est profond. D\'où aurais-tu donc cette eau vive?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Es-tu plus grand que notre père Jacob, qui nous a donné ce puits, et qui en a bu lui-même, aussi bien que ses fils et ses troupeaux?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jésus lui répondit: «Quiconque boit de cette eau aura encore soif;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'celui qui boira de l\'eau que je lui donnerai, n\'aura plus jamais soif; mais l\'eau que je lui donnerai, deviendra en lui une source d\'eau jaillissant en vie éternelle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Cette femme lui dit: «Seigneur, donne-moi de cette eau, afin que je n\'aie pas soif, et que je ne vienne pas ici pour puiser.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, '— «Va, lui dit Jésus, appelle ton mari, et viens ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, '— «Je n\'ai point de mari,» repartit cette femme. Jésus lui dit: «Tu as raison de dire, «je n\'ai point de mari,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'car tu as eu cinq maris, et celui que tu as maintenant, n\'est pas ton mari. Tu as dit vrai en cela.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, '— «Seigneur, lui dit cette femme, je vois que tu es prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nos pères ont adoré sur cette montagne, et vous dites, vous, que c\'est à Jérusalem qu\'est le lieu où l\'on doit adorer.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jésus lui dit: «Femme, crois-moi; l\'heure vient où vous n\'adorerez le Père ni sur cette montagne, ni à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vous adorez ce que vous ne connaissez pas; pour nous, nous adorons ce que nous connaissons, car le salut vient des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Mais l\'heure vient, et elle est déjà venue, où les vrais adorateurs adoreront le Père en esprit et en vérité: ce sont là les adorateurs que le Père demande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Dieu est esprit, et il faut que ceux qui l\'adorent, l\'adorent en esprit et en vérité»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Cette femme lui dit: «Je sais que le Messie va venir;» (celui qu\'on appelle Christ) «quand il sera venu, il nous enseignera toutes choses.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jésus lui dit: «Je le suis, moi qui te parle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Là-dessus, ses disciples arrivèrent, et ils s\'étonnèrent de ce qu\'il parlait avec une femme; cependant aucun d\'eux ne lui dit: «Que demandes-tu?» ou «Pourquoi parles-tu avec elle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Alors la femme laissant là sa cruche, s\'en alla à la ville et dit aux gens de l\'endroit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '«Venez voir un homme qui m\'a dit tout ce que j\'ai fait; ne serait-ce point le Messie?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Les gens sortirent de la ville et vinrent vers Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Cependant ses disciples le priaient de prendre quelque nourriture, disant: «Maître, mange.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Il leur dit: «J\'ai à prendre une nourriture que vous ne connaissez pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Ses disciples se disaient donc les uns aux autres: «Lui aurait-on apporté à manger?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jésus leur dit: «Ma nourriture à moi, c\'est de faire la volonté de celui qui m\'a envoyé, et d\'accomplir son oeuvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne dites-vous pas qu\'il y a encore quatre mois jusqu’à la moisson? Voici, je vous dis: Levez les yeux, et regardez les campagnes, elles sont blanches pour la moisson.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Déjà le moissonneur reçoit sa récompense, et serre la récolte pour la vie éternelle, afin que le semeur et le moissonneur se réjouissent ensemble;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'car c\'est bien ici que l’on peut dire: L\'un sème, un autre moissonne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Je vous ai envoyés moissonner là où vous n\'avez pas travaillé; d\'autres ont travaillé, et vous êtes entrés dans leurs travaux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Plusieurs des Samaritains de cette ville crurent en Jésus, pour avoir entendu cette femme les assurer qu\'il lui avait dit tout ce qu\'elle avait fait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Lors donc que les Samaritains furent venus vers lui, ils le prièrent de demeurer chez eux; et il y demeura deux jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Un bien plus grand nombre crurent, pour l\'avoir entendu lui-même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'et ils disaient à la femme: «Ce n\'est plus sur ton rapport que nous croyons, car nous l\'avons entendu nous-mêmes, et nous savons que c\'est lui qui est vraiment le Sauveur du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Après ces deux jours, Jésus partit de là, et s\'en alla en Galilée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'car il avait déclaré lui-même qu\'un prophète n\'est point honoré dans sa patrie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Quand il arriva en Galilée, les Galiléens l\'accueillirent, parce qu\'ils avaient vu tout ce qu\'il avait fait à Jérusalem, lors de la fête; car ils étaient aussi allés à la fête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Il vint donc de nouveau à Cana en Galilée, où il avait changé l\'eau en vin. Il y avait à Capernaoum un officier du roi, dont le fils était malade.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Cet homme, ayant appris que Jésus était revenu de Judée en Galilée, se rendit auprès de lui, et le pria de descendre à Capernaoum, pour guérir son fils qui était mourant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jésus lui dit: «Si vous ne voyez des miracles et des prodiges, vous ne croyez point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'L\'officier du roi lui dit: «Seigneur, viens avant que mon enfant meure.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, '— «Va, lui dit Jésus, ton fils vit.» Cet homme crut à la parole que Jésus lui avait dite, et partit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Il était déjà en route, lorsqu\'il rencontra ses serviteurs, qui lui donnèrent cette nouvelle: «Ton enfant vit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Il s\'informa de l\'heure à laquelle l\'enfant s\'était trouvé mieux; et ils lui dirent: «Hier, à la septième heure, la fièvre l\'a quitté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Le père reconnut que c\'était à cette heure-là que Jésus lui avait dit, «ton fils vit,» et il crut, lui et toute sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Ce fut là un second miracle que Jésus fit encore à son retour de Judée en Galilée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Après cela, il y eut une fête des Juifs, et Jésus monta à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Or il y a à Jérusalem, près de la porte des Brebis, une piscine appelée en hébreu Bethesda, qui a cinq portiques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Là étaient couchés par terre un grand nombre de malades, des aveugles, des boiteux, des gens ayant quelque membre sec. [qui attendaient le bouillonnement de l\'eau]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, '[Car un ange descendait, à certains moments, dans la piscine et agitait l\'eau. Le premier donc qui entrait dans l\'eau, après qu\'elle avait été agitée, était guéri de sa maladie, quelle qu\'elle fût.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Il y avait là un homme qui était malade depuis trente-huit ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Jésus le voyant couché, et reconnaissant qu\'il était malade depuis longtemps, lui dit: «Tu veux être guéri?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Le malade lui répondit: «Seigneur, je n\'ai personne pour me jeter dans la piscine quand l\'eau est agitée, et, pendant que j\'y vais, un autre descend avant moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jésus lui dit: «Lève-toi, prends ton lit et marche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Aussitôt cet homme fut guéri: il prit son lit et se mit à marcher. Or c\'était un jour de sabbat.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Les Juifs dirent donc à celui qui avait été guéri: «C\'est le sabbat, il ne t\'est pas permis de porter ton lit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Il leur répondit: «Celui qui m\'a guéri m\'a dit: «Prends ton lit, et marche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Ils lui demandèrent: «Qui est cet homme qui t\'a dit: Prends et marche?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Mais le malade l\'ignorait, car Jésus s\'était esquivé, grâce à la foule qui était en cet endroit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Plus tard, le trouvant dans le temple, Jésus lui dit: «Te voilà guéri, ne pèche plus, de peur qu\'il ne t\'arrive quelque chose de pis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Cet homme alla rapporter aux Juifs que c\'était Jésus qui l\'avait guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Aussi les Juifs persécutaient-ils Jésus, parce qu\'il faisait ces choses le jour du sabbat.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Mais Jésus leur répondit: «Mon Père agit continuellement, et moi aussi, j\'agis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'C\'est pourquoi les Juifs cherchaient encore plus à le faire mourir, non-seulement parce qu\'il violait le sabbat, mais encore parce qu\'il disait que Dieu était son propre Père, se faisant égal à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jésus prenant la parole, leur dit: «En vérité, en vérité, je vous dis que le Fils ne peut rien faire de lui-même, s\'il ne le voit faire au Père; car ce que le Père fait, le Fils aussi le fait pareillement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Le Père aime le Fils et lui montre tout ce qu\'il fait; et il lui montrera des oeuvres plus grandes que celles-là, afin que vous soyez dans l\'étonnement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Car, de même que le Père ressuscite les morts et donne la vie, de même le Fils donne la vie à qui il veut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Le Père même ne juge personne, mais il a remis au Fils le jugement tout entier, afin que tous honorent le Fils comme ils honorent le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Celui qui n\'honore point le Fils, n\'honore point le Père qui l\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'En vérité, en vérité, je vous le dis, celui qui écoute ma parole, et qui croit en celui qui m\'a envoyé, a la vie éternelle; et il n\'est point amené en jugement, mais il est passé de la mort à la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'En vérité, en vérité, je vous le dis, l\'heure vient, et elle est déjà venue, où les morts entendront la voix du Fils de Dieu, et ceux qui l\'auront entendue vivront;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'car, de même que le Père a la vie en lui-même, de même il a donné au Fils d\'avoir la vie en lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Il lui a même donné le pouvoir d\'exercer le jugement, parce qu\'il est un fils d\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne vous en étonnez point, car l\'heure vient, où tous ceux qui sont dans les sépulcres entendront sa voix, et en sortiront:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'ceux qui auront fait le bien ressusciteront pour la vie, ceux qui auront fait le mal ressusciteront pour la condamnation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Je ne puis rien faire de moi-même; je juge selon que j\'entends; et mon jugement est juste, parce que je ne cherche pas ma volonté, mais la volonté de celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Si c\'est moi qui rends témoignage de moi-même, mon témoignage n\'est pas vrai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Il y en a un autre qui rend témoignage de moi, et je sais que le témoignage qu\'il me rend est vrai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vous avez envoyé vers Jean, et il a rendu témoignage à la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Pour moi, je n\'emprunte pas le témoignage d\'un homme, mais ce que je vous en dis. c\'est afin que vous soyez sauvés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Jean était la lampe qui brûle et luit, mais vous n\'avez voulu vous réjouir qu\'un moment à sa lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Pour moi, j\'ai un témoignage qui est supérieur à celui de Jean, ce sont les oeuvres que mon Père m\'a donné d\'accomplir: ces oeuvres mêmes rendent témoignage de moi, elles attestent que mon Père m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Et le Père, qui m\'a envoyé, a rendu lui-même témoignage de moi: sa voix, vous ne l\'avez jamais entendue; sa face, vous ne l\'avez jamais vue;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'et sa parole... vous ne la gardez pas en vous, puisque vous ne croyez pas en celui qu\'il a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Vous sondez les Écritures, parce que vous pensez y trouver la vie éternelle, et ce sont elles qui rendent témoignage de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'mais vous ne voulez pas venir à moi pour avoir la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Je ne demande pas ma gloire aux hommes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mais je vous connais, je sais que vous n\'avez pas en vous l\'amour de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Je suis venu au nom de mon Père, et vous ne me recevez pas; si un autre vient en son propre nom, vous le recevrez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Comment pouvez-vous croire, vous qui tirez votre gloire les uns des autres et qui ne recherchez pas la gloire qui vient de Dieu seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne pensez pas que ce soit moi qui doive vous accuser devant le Père; votre accusateur, c\'est Moïse, en qui vous avez mis votre espérance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'car si vous croyiez Moïse, vous me croiriez, parce qu\'il a parlé de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'mais si vous n\'ajoutez pas foi à ses écrits, comment ajouteriez-vous foi à mes paroles?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Jésus s\'en alla ensuite de l\'autre côté de la mer de Tibériade en Galilée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'et une foule nombreuse le suivait, parce qu\'elle voyait les miracles qu\'il opérait sur les malades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jésus monta sur la montagne, et s\'y assit avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Or, la Pâque, la grande fête des Juifs, était proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Jésus donc ayant levé les yeux, et voyant qu\'une grande foule se dirigeait de son côté, dit à Philippe: «où nous faut-il acheter du pain, pour que ces gens aient à manger?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Il disait cela pour l\'éprouver; car, pour lui, il savait bien ce qu\'il voulait faire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippe lui répondit: «Deux cents deniers de pain ne suffiraient pas pour en donner un peu à chacun.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Un de ses disciples, André, frère de Simon-Pierre, lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '«Il y a ici un petit garçon qui a cinq pains d\'orge et deux poissons; mais qu\'est-ce que cela pour tant de monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jésus dit: «Faites asseoir ces gens.» Or il y avait une grande étendue d\'herbe en ce lieu. Les hommes s\'assirent donc: ils étaient au nombre d\'environ cinq mille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jésus prit les pains, et, ayant rendu grâces, il les distribua à ceux qui étaient assis; il leur donna de même des poissons, autant qu\'ils en voulurent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Lorsqu\'ils furent rassasiés, il dit à ses disciples: «Ramassez les morceaux qui restent, afin que rien ne se perde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Ils les ramassèrent, et remplirent douze corbeilles des morceaux qui restèrent des cinq pains d\'orge, après que l\'on eut mangé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ces gens ayant vu le miracle que Jésus avait fait, disaient: «C\'est vraiment le prophète qui doit venir dans le monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Alors Jésus ayant compris qu\'ils allaient venir l\'enlever pour le faire roi, se retira de nouveau dans la montagne, tout seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Quand le soir fut venu, ses disciples descendirent au bord de la mer;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'et, étant entrés dans la barque, ils traversèrent la mer dans la direction de Capernaoum. Il faisait déjà nuit, et Jésus ne les avait pas rejoints;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'et un gros vent s\'étant levé, la mer était agitée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Quand ils eurent fait de vingt-cinq à trente stades, ils virent Jésus marchant sur la mer, près de la barque, et ils eurent peur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mais Jésus leur dit: «C\'est moi, n\'ayez point de peur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Ils se disposèrent donc à le prendre dans la barque, et aussitôt la barque aborda au lieu où ils se rendaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'La foule qui était restée de l\'autre côté de la mer avait vu qu\'il n\'y avait là qu\'une seule barque, et que Jésus n\'y était point entré avec ses disciples, mais que ceux-ci étaient partis seuls.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Cependant il était arrivé de Tibériade d\'autres barques, près du lieu où ils avaient mangé le pain, après que le Seigneur eut rendu grâces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Le lendemain donc, lorsqu\'ils virent que Jésus n\'était pas là, non plus que ses disciples, ils entrèrent dans ces barques et se rendirent à Capernaoum pour chercher Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Et l\'ayant trouvé de l\'autre côté de la mer, ils lui dirent: «Maître, quand es-tu venu ici?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jésus leur répondit: «En vérité, en vérité, je vous le dis, vous me cherchez, non parce que vous avez vu des miracles, mais parce que vous avez mangé des pains, et que vous avez été rassasiés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Travaillez pour avoir, non l\'aliment qui périt, mais l\'aliment qui subsiste en vie éternelle, et que le Fils de l\'homme vous donnera, car c\'est lui que le Père, savoir Dieu, a marqué de son sceau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Ils lui dirent donc: «Que devons-nous faire, pour faire les oeuvres de Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jésus leur répondit: «L\'oeuvre que Dieu demande, c\'est que vous croyiez en celui qu\'il a envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, '— Quel miracle fais-tu donc, lui dirent-ils, que nous le voyions, et que nous croyions en toi? Que fais-tu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nos pères ont mangé la manne au désert, ainsi qu\'il est écrit: «Il leur donna à manger du pain du ciel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jésus leur répondit: «En vérité, en vérité, je vous le dis, Moïse ne vous a point donné «le pain du ciel;» c\'est mon Père qui vous donne le vrai pain du ciel,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'car le pain de Dieu, c\'est le pain qui descend du ciel et qui donne la vie au monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Ils lui dirent donc: «Seigneur, donne-nous toujours de ce pain-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jésus leur dit: «Je suis le pain de vie: celui qui vient à moi n\'aura jamais faim, et celui qui croit en moi n\'aura jamais soif;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'mais, je vous l\'ai dit, vous m\'avez vu, et vous ne croyez point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Tout ce que le Père me donne viendra à moi, et je ne repousserai point celui qui vient à moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'car je suis descendu du ciel pour faire, non ma volonté, mais la volonté de celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Or, la volonté de celui qui m\'a envoyé, c\'est que je ne perde aucun de ceux qu\'il m\'a donnés, mais que je les ressuscite au dernier jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Car c\'est ici la volonté de mon Père, que quiconque voit le Fils et croit en lui, ait la vie éternelle; et moi je le ressusciterai au dernier jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Les Juifs se mirent donc à murmurer contre lui, parce qu\'il avait dit: «Je suis le pain qui est descendu du ciel,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'et ils disaient: «N\'est-ce pas là Jésus, le fils de Joseph, dont nous connaissons le père et la mère? comment donc dit-il: «Je suis descendu du ciel?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jésus répondit et leur dit: «Ne murmurez point entre vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nul ne peut venir à moi, si le Père, qui m\'a envoyé, ne l\'attire; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Il est écrit dans les Prophètes: «Et ils seront tous enseignés de Dieu» quiconque a entendu le Père et a profité, vient à moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'ce n\'est pas que personne ait vu le Père, si ce n\'est celui qui vient de Dieu: celui-là a vu le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'En vérité, en vérité, je vous le dis, celui qui croit en moi a la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Je suis le pain de vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vos pères ont mangé la manne au désert, et ils sont morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'quant au pain qui descend du ciel, on en mange et l’on ne meurt point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Je suis le pain vivifiant qui est descendu du ciel: si quelqu\'un mange de ce pain, il vivra éternellement; et le pain que je donnerai, c\'est ma chair, que je donnerai pour la vie du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Là-dessus, les Juifs disputaient entre eux, disant: «Comment cet homme peut-il nous donner sa chair à manger?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jésus leur dit donc: «En vérité, en vérité, je vous le dis, si vous ne mangez la chair du Fils de l\'homme, et si vous ne buvez son sang, vous n\'avez point la vie en vous-mêmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'celui qui mange ma chair et qui boit mon sang a la vie éternelle; et moi, je le ressusciterai au dernier jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Car ma chair est vraiment une nourriture, et mon sang est vraiment un breuvage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Celui qui mange ma chair et qui boit mon sang demeure en moi, et moi en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Comme le Père, qui a la vie, m\'a envoyé, et que je vis par le Père, de même celui qui me mange, vivra par moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'C\'est là le pain qui est descendu du ciel: il n\'en est point comme de nos pères qui ont mangé et sont morts; celui qui mange de ce pain vivra éternellement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Jésus dit ces choses, enseignant en pleine synagogue à Capernaoum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Plusieurs de ses disciples, l\'ayant entendu, dirent: «Cette parole est dure, qui peut l\'écouter?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mais Jésus, sachant en lui-même que ses disciples murmuraient, leur dit: «Cela vous scandalise?...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'que sera-ce donc, si vous voyez le Fils de l’homme monter là où il était auparavant?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'C\'est l\'esprit qui vivifie; la chair ne sert de rien. Les paroles que je vous ai adressées sont esprit et vie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'mais il y en a parmi vous qui ne croient point.» En effet, Jésus savait dès l\'abord qui étaient ceux qui ne croyaient pas, et qui était celui qui le livrerait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Et il ajouta: «C\'est pour cela que je vous ai dit que nul ne peut venir à moi, s\'il ne lui a été donné du Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Dès lors plusieurs de ses disciples se retirèrent d\'auprès de lui et cessèrent de le suivre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jésus dit donc aux Douze: «Et vous, ne voulez-vous pas aussi vous en aller?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon-Pierre lui répondit: «Seigneur, à qui irions-nous? Tu as les paroles de la vie éternelle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'pour nous, nous avons cru et nous avons connu, que tu es le Saint de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jésus leur répondit: «N\'est-ce pas moi qui vous ai choisis, vous Douze?... et l\'un de vous est un démon!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Or il parlait de Judas, fils de Simon Iscariote, car c\'était lui, l\'un des Douze, qui devait le livrer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Après cela, Jésus se mit à parcourir la Galilée: il ne voulait pas séjourner en Judée, parce que les Juifs cherchaient à le faire mourir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Cependant la fête des Juifs, appelée fête des Tabernacles, était proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Ses frères lui dirent donc: «Quitte ce pays, et t\'en va en Judée, afin que tes disciples aussi voient les oeuvres que tu fais:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'car on n\'agit pas secrètement, quand on veut être connu du public. Si réellement tu fais ces choses, montre-toi au monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Car ses frères mêmes ne croyaient pas en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Jésus leur dit: «Le moment n\'est pas encore venu pour moi, tandis que pour vous tous les moments sont bons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Le monde ne peut vous haïr; mais, moi, il me hait, parce que je rends de lui ce témoignage que ses oeuvres sont mauvaises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Allez, vous, à la fête; pour moi, je n\'y vais pas, parce que le moment n\'est pas encore venu pour moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Leur ayant ainsi parlé, il resta en Galilée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'mais, lorsque ses frères furent partis, il alla aussi lui-même à la fête, non pas publiquement, mais comme en cachette.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Les Juifs donc le cherchaient à la fête, et disaient: «où est-il?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Et l\'on parlait beaucoup de lui dans la foule. Les uns disaient: «C\'est un homme de bien.» D\'autres disaient: «Non, il égare le peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Toutefois personne ne s\'exprimait librement sur son compte, par crainte des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'On était déjà au milieu de la fête, quand Jésus monta au temple; et il se mit à enseigner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Les Juifs, étonnés, disaient: «Comment cet homme connaît-il les saintes lettres, puisqu\'il n\'a point étudié?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jésus leur répondit: «Ma doctrine n\'est pas de moi; elle est de celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Si quelqu\'un veut faire la volonté de Dieu, il connaîtra si ma doctrine vient de Dieu, ou si je parle de mon chef.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Celui qui parle de son chef, cherche sa propre gloire; mais celui qui cherche la gloire de celui qui l\'a envoyé, est véridique, et il n\'y a rien de malhonnête en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Moïse ne vous a-t-il pas donné la Loi?... et pourtant nul de vous n\'observe la Loi. Pourquoi cherchez-vous à me faire mourir?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Le peuple répondit: «Tu es possédé d\'un démon; qui est-ce qui cherche à te faire mourir?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jésus répondit et leur dit: «J\'ai fait une seule oeuvre, et vous en êtes tous dans l\'étonnement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moïse vous a donné la circoncision (non qu\'elle vienne de Moïse; elle vient des patriarches) et vous circoncisez le jour du sabbat.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Si l’on circoncit un homme le jour du sabbat, pour que la loi de Moïse ne soit pas violée, pourquoi vous irritez-vous contre moi, de ce que j\'ai guéri un homme, dans tout son corps, un jour de sabbat?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne jugez pas sur l\'apparence, mais jugez avec justice.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Alors quelques personnes de Jérusalem dirent: «N\'est-ce pas celui qu\'on cherche à faire mourir?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'et le voilà qui parle librement, sans qu\'on lui dise rien. Les sénateurs auraient-ils reconnu qu\'il est le Messie?...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Mais nous savons d\'où est celui-ci, tandis que, quand le Messie viendra, personne ne saura d\'où il est.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jésus, qui enseignait dans le temple, dit donc à haute voix: «Vous me connaissez, et vous savez d\'où je suis!... et pourtant ce n\'est pas de moi-même que je suis venu, mais il y en a bien réellement un qui m\'a envoyé: vous ne le connaissez pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'moi je le connais, car je viens de lui, et c\'est lui-même qui m\'a envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Ils cherchèrent donc à le saisir; toutefois personne ne mit la main sur lui, parce que son heure n\'était pas encore venue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mais plusieurs hommes du peuple crurent en lui, et ils disaient: «Quand le Messie viendra, fera-t-il plus de miracles que n\'en a fait celui-ci?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Les pharisiens entendirent ce que le peuple disait tout bas de Jésus, et de concert avec les principaux sacrificateurs, ils envoyèrent des agents pour l\'arrêter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jésus dit donc: «Je suis encore avec vous pour un peu de temps, puis je m\'en vais vers celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vous me chercherez et vous ne me trouverez pas; et, là où je serai, vous ne pouvez venir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Sur quoi, les Juifs se dirent entre eux: «où doit-il aller, que nous ne le trouverons pas? Est-ce qu\'il doit aller chez ceux qui sont disséminés parmi les Grecs, et enseigner les Grecs?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Que signifie ce qu\'il vient de dire: «Vous me cherchera, et vous ne me trouverez pas; et, là où je serai, vous ne pouvez venir?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Le dernier et le plus grand jour de la fête, Jésus était là debout, et il dit à haute voix. «Si quelqu\'un a soif, qu\'il vienne à moi et qu\'il boive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Si quelqu\'un croit en moi, des fleuves d\'eau vive, comme dit l\'Ecriture, couleront de son sein.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Il disait cela de l\'Esprit que devaient recevoir ceux qui croient en lui; car l\'Esprit n\'était pas encore, parce que Jésus n\'avait pas encore été glorifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Là-dessus, des gens du peuple, qui avaient entendu ces paroles, disaient: «Assurément c\'est le Prophète.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'D\'autres disaient: «C\'est le Messie.» — «Non, disaient d\'autres, car le Messie doit-il venir de Galilée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'L\'Écriture ne dit-elle pas, que c\'est de la race de David et du village de Bethléhem, où était David, que le Messie doit venir?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Le peuple était donc divisé à cause de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Quelques-uns voulaient l\'arrêter, cependant personne ne mit la main sur lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Les agents vinrent donc vers les principaux sacrificateurs et les pharisiens, et ceux-ci leur dirent: «Pourquoi ne l\'avez-vous pas amené?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Les agents répondirent: «Jamais homme n\'a parlé comme cet homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Les pharisiens leur répliquèrent: «Vous aussi, vous êtes-vous laissé séduire?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Y a-t-il quelqu\'un des sénateurs ou des pharisiens qui ait cru en lui?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'mais cette populace, qui ne connaît point la Loi, est exécrable.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodème, l\'un d\'eux, le même qui était venu trouver Jésus, leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '«Est-ce que notre Loi condamne un homme avant de l\'avoir entendu, et d\'avoir pris connaissance de ce qu\'il a fait?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Ils lui répondirent: «Toi aussi, es-tu Galiléen? Examine, et tu verras qu\'il n\'est point sorti de prophète de la Galilée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '[Et chacun s\'en alla dans sa maison.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Pour Jésus, il se rendit à la montagne des Oliviers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Au point du jour, il revint dans le temple, et tout le peuple vint vers lui. Alors Jésus s\'assit, et se mit à les enseigner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Les scribes et les pharisiens lui amenèrent une femme qui avait été surprise en adultère, et l\'ayant placée au milieu de l\'assemblée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'ils dirent à Jésus: «Maître, cette femme a été prise en flagrant délit d\'adultère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'or, Moise nous a commandé, dans la Loi, de lapider ces sortes de femmes; toi donc, qu\'en dis-tu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Ils parlaient ainsi pour l\'éprouver, afin de pouvoir l\'accuser; mais Jésus s\'étant baissé, écrivait avec le doigt sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Comme persistaient à l\'interroger, il se releva, et leur dit: «Que celui de vous qui est sans péché, lui jette le premier la pierre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Et s\'étant baissé de nouveau, il se remit à écrire sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Eux, l\'ayant entendu, et se sentant repris par leur conscience, se retirèrent les uns après les autres, depuis les plus âgés jusqu\'aux derniers; et Jésus resta seul avec la femme qui était là au milieu de l\'assemblée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Alors Jésus s\'étant relevé, et ne voyant plus que la femme, lui dit: «Femme, où sont tes accusateurs? Est-ce que personne ne t\'a condamnée?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Elle lui répondit: «Personne, Seigneur. Et Jésus lui dit: «Je ne te condamne pas non plus; va, et ne pèche plus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jésus prenant de nouveau la parole, leur dit: «Je suis la lumière du monde; celui qui me suit ne marchera pas dans les ténèbres, mais il aura la lumière de la vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Les pharisiens lui dirent donc: «C\'est toi qui rends témoignage de toi-même, ton témoignage n\'est pas digne de foi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jésus leur répondit: Quoique ce soit moi, qui rends témoignage de moi-même, mon témoignage est digne de foi, parce que je sais d\'où je suis venu et où je vais; mais vous, vous ne savez ni d\'où je viens, ni où je vais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vous jugez selon la chair; pour moi, je ne juge personne;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'et pourtant quand il m\'arrive de juger, mon jugement est digne de foi, parce que je ne suis pas seul, mais que le Père qui m\'a envoyé est avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'D\'ailleurs, il est écrit dans votre Loi que le témoignage de deux personnes est digne de foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'eh bien il y a moi, qui témoigne de moi-même, et le Père, qui m\'a envoyé, rend aussi témoignage de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Ils lui disaient donc: «où est ton Père?» Jésus répondit: «Vous ne connaissez ni moi, ni mon Père; si vous me connaissiez, vous connaîtriez aussi mon Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Il prononça ces paroles dans la trésorerie, enseignant dans le temple; et personne ne mit la main sur lui, parce que son heure n\'était pas encore venue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Jésus leur dit encore: «Je m\'en vais; et vous me chercherez, et vous mourrez dans votre péché: vous ne pouvez venir où je vais.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Là-dessus, les Juifs disaient: «Est-ce qu\'il veut se tuer, qu\'il dit, «vous ne pouvez venir où je vais.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Jésus leur dit: «Vous êtes d\'ici-bas; pour moi, je suis d\'en haut; vous êtes de ce monde; moi, je ne suis pas de ce monde:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'c\'est pourquoi je vous ai dit que vous mourrez dans vos péchés; car si vous ne croyez pas ce que je suis, vous mourrez dans vos péchés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Ils lui disaient donc: «Qui es-tu, toi?» Jésus leur dit: «Je suis toujours ce que je vous dis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'J\'ai beaucoup de choses à dire de vous et à reprendre en vous; mais celui qui m\'a envoyé est la vérité même, et je ne dis au monde que ce que j\'ai appris de lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ils ne comprirent pas qu\'il leur parlait du Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jésus ajouta donc: «Lorsque vous aurez élevé le Fils de l\'homme, alors vous connaîtrez qui je suis; vous saurez que je ne fais rien de moi-même, mais que je parle comme le Père m\'a enseigné,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'et que celui qui m\'a envoyé, est avec moi: il ne m\'a point laissé seul, parce que je fais toujours ce qui lui est agréable.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Comme il disait ces choses, plusieurs crurent en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jésus dit donc à ces Juifs qui avaient cru en lui: «Si vous gardez ma parole, vous serez véritablement mes disciples:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'vous connaîtrez la vérité, et la vérité vous affranchira,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Ils lui répondirent: «Nous sommes la postérité d\'Abraham, et nous n\'avons jamais été esclaves de personne; pourquoi dis-tu: «Vous serez affranchis?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jésus leur repartit: «En vérité, en vérité, je vous le dis, quiconque s\'adonne au péché est esclave du péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Or l\'esclave ne demeure pas toujours dans la maison, c\'est le fils qui y demeure toujours;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'si donc le Fils vous affranchit, vous serez réellement libres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Je sais bien que vous êtes la postérité d\'Abraham; mais vous cherchez à me faire mourir, parce que ma parole ne pénètre point en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Pour moi, je dis ce que j\'ai vu chez mon Père, et vous, vous faites ce que vous avez appris de votre père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Ils lui répondirent: «Notre père, c\'est Abraham.» Jésus leur dit: «Si vous étiez enfants d\'Abraham, vous feriez les oeuvres d\'Abraham;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'mais voici, vous cherchez à me faire mourir, moi qui vous ai dit la vérité que j\'ai apprise de Dieu: Abraham n\'a point fait ainsi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vous faites, vous, les oeuvres de votre père.» Ils lui dirent: «Nous ne sommes pas des enfants illégitimes. Nous n\'avons qu\'un père, c\'est Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jésus leur dit: «Si Dieu était votre père, vous m\'aimeriez; car je suis issu de Dieu, et je viens à vous; je ne suis pas même venu de mon chef, mais c\'est lui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Pourquoi ne reconnaissez-vous pas mon langage? C\'est qu\'il vous est impossible d\'entendre ma parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Le père dont vous êtes issus, c\'est le diable, et vous avez la volonté d\'accomplir les désirs de votre père. Il a été homicide dès le commencement, et il ne demeure point dans la vérité, parce qu\'il n\'y a point de vérité en lui; quand il profère le mensonge, il parle de son propre fonds, car il est menteur, et le père du menteur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'et moi, parce que je vous dis la vérité, vous ne me croyez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Qui de vous peut me convaincre de péché? Si je dis la vérité, pourquoi ne me croyez-vous pas?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Celui qui est issu de Dieu, entend les paroles de Dieu; aussi ne les entendez-vous point, parce que vous n\'êtes point issus de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Les Juifs repartirent: «N\'avons-nous pas raison de dire tu es un Samaritain, et que tu es possédé d\'un démon?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jésus répondit: «Je ne suis point possédé d\'un démon, mais je rends honneur à mon Père, et vous, vous me déshonorez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Pour moi, je ne cherche point ma gloire: il y en a un qui la cherche et qui juge.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'En vérité, en vérité, je vous le dis, si quelqu\'un garde ma parole, il ne verra jamais la mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Les Juifs lui dirent: «Nous voyons bien maintenant que tu es possédé d\'un démon: Abraham est mort, les prophètes sont morts aussi, et tu dis, «si quelqu\'un garde ma parole, il ne goûtera jamais la mort!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Es-tu plus grand que notre père Abraham, qui est mort? Les prophètes aussi sont morts: qui donc prétends-tu être?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jésus répondit: «Si je me glorifie moi-même, ma gloire n\'est rien; c\'est mon Père qui me glorifie, lui, dont vous dites qu\'il est votre Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'et pourtant vous ne le connaissez pas. Moi, je le connais, et si je disais que je ne le connais pas, je serais comme vous, un menteur; mais je le connais, et je garde sa parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, votre père, s\'est réjoui de voir mon jour: il l\'a vu, et il en a eu de la joie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Les Juifs lui dirent donc: «Tu n\'as pas encore cinquante ans, et tu as vu Abraham!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jésus leur dit: «En vérité, en vérité, je vous le dis, avant qu\'Abraham fût, je suis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Là-dessus, ils prirent des pierres pour les lui jeter; mais Jésus se cacha, et sortit du temple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Comme il passait, il vit un homme aveugle de naissance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'et ses disciples lui demandèrent: «Maître, qui est-ce qui a péché, de cet homme, ou de ses parents, pour qu\'il soit né aveugle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jésus répondit: «Ce n\'est pas qu\'il ait péché, ni lui, ni ses parents, mais c\'est afin que les oeuvres de Dieu éclatent en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Il nous faut faire les oeuvres de celui qui m\'a envoyé, pendant qu\'il est jour; la nuit vient, où l\'on ne peut travailler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pendant que je suis dans le monde, je suis la lumière du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ayant ainsi parlé, il cracha à terre, fit de la boue avec sa salive, enduisit de cette boue les yeux de l\'aveugle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'et lui dit: «Va, lave-toi au réservoir de Siloé» (nom qui signifie Envoyé). Il s\'en alla donc, se lava, et revint clairvoyant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Ses voisins et ceux qui auparavant l\'avaient vu mendier, disaient: «N\'est-ce pas là celui qui était assis et qui mendiait?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Les uns disaient: «C\'est lui.» — «Non, disaient d\'autres, mais il lui ressemble.» Lui disait: «C\'est moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Sur quoi ils lui dirent: «Comment tes yeux ont-ils été ouverts?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Il répondit: «Un homme appelé Jésus a fait de la boue, il m\'en a enduit les yeux, et m\'a dit: «Va à Siloé, et te lave.» J\'y suis allé, et, m\'étant lavé, j\'ai recouvré la vue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Ils lui dirent: «où est cet homme?» — «Je ne sais pas,» répondit-il.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Ils menèrent vers les pharisiens celui qui naguère était aveugle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Or, c\'était un jour de sabbat que Jésus avait fait de la boue, et lui avait ouvert les yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Les pharisiens à leur tour, lui demandèrent aussi comment il avait recouvré la vue; et il leur dit: «Il m\'a mis de la boue sur les yeux; je me suis lavé, et je vois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Là-dessus, quelques-uns des pharisiens dirent: «Cet homme n\'est pas envoyé de Dieu, puisqu\'il n\'observe pas le sabbat.» Mais d\'autres disaient: «Comment un méchant pourrait-il faire de tels miracles?» Et ils étaient divisés entre eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Ils dirent donc de nouveau à l\'aveugle:» Et toi, que dis-tu de cet homme qui t\'a ouvert les yeux?» — «C\'est un prophète,» dit-il.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Les Juifs ne voulurent point croire que cet homme eût été aveugle et qu\'il eût recouvré la vue, jusqu’à ce qu\'ils eussent fait venir son père et sa mère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Et ils les interrogèrent: «Est-ce là, demandèrent-ils, votre fils, que vous dites être né aveugle? Comment donc voit-il à cette heure?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Les parents répondirent: «Nous savons que c\'est bien là notre fils, et qu\'il est né aveugle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'mais comment il se fait qu\'il voie maintenant, nous l\'ignorons; qui lui a ouvert les yeux, nous ne le savons pas. Interrogez-le, il a de l\'âge, il s\'expliquera lui-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ses parents dirent cela, parce qu\'ils craignaient les Juifs; car ceux-ci s\'étaient déjà concertés pour faire chasser de la synagogue quiconque reconnaîtrait Jésus pour le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'C\'est pour cela que ses parents dirent: «Il a de l\'âge, interrogez-le.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Les pharisiens tirent venir une seconde fois l\'homme qui avait été aveugle, et lui dirent: «Donne gloire à Dieu: nous savons que cet homme est un méchant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Il répondit: «Si c\'est un méchant, je l\'ignore; je ne sais qu\'une chose, c\'est que j\'étais aveugle et qu\'à cette heure je vois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Ils lui dirent: «Que t\'a-t-il fait? Comment t\'a-t-il ouvert les yeux?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, '— «Je vous l\'ai déjà dit, leur répliqua-t-il, et vous n\'avez pas écouté; pourquoi voulez-vous l\'entendre encore une fois? Est-ce que vous voulez devenir aussi ses disciples?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Ils l\'injurièrent et lui dirent: «C\'est toi qui es disciple de cet homme; pour nous, nous sommes disciples de Moïse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Nous savons que Dieu a parlé à Moïse; mais pour celui-ci, nous ne savons d\'où il est.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Cet homme répondit et leur dit: «C\'est une chose étrange que vous ne sachiez d\'où il est; et pourtant il m\'a ouvert les yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Nous savons que Dieu n\'exauce point les méchants; mais si quelqu\'un est pieux et fait sa volonté, c\'est celui-là qu\'il exauce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Jamais on n\'a entendu dire que quelqu\'un ait ouvert les yeux d\'un aveugle-né;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'si cet homme ne venait pas de Dieu, il ne pourrait rien faire de pareil.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Ils lui dirent: «Tu es né tout entier dans le péché, et tu te mêles de nous faire des leçons!» Et ils le chassèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jésus apprit qu\'on l\'avait chassé, et, l\'ayant rencontré, il lui dit: «Tu crois, toi, au Fils de Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Cet homme répondit: «Et qui est-il, Seigneur, afin que je croie en lui?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, '— «Tu le vois, lui dit Jésus, et c\'est lui-même qui te parle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, '— «Je crois, Seigneur,» dit-il alors, et il se prosterna devant lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Jésus ajouta: «Je suis venu dans ce monde pour un jugement, pour que ceux qui ne voient pas, voient, et que ceux qui voient deviennent aveugles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Les pharisiens qui étaient auprès de lui, entendirent cette parole, et lui dirent: «Et nous, sommes- nous aussi aveugles?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jésus leur dit: «Si vous étiez aveugles, vous seriez sans péché; mais puisque vous dites, «nous voyons,» votre péché subsiste.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '«En vérité, en vérité, je vous le dis, celui qui n\'entre pas par la porte dans la bergerie, mais qui l\'escalade par un autre endroit, est un voleur et un brigand;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'mais celui qui entre par la porte, est un berger des brebis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Le portier lui ouvre, et les brebis entendent sa voix; il appelle ses brebis par leur nom, et il les conduit dehors:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'dès qu\'il a fait sortir toutes les siennes, il va devant elles, et les brebis le suivent, parce qu\'elles connaissent sa voix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Elles ne suivront point un étranger, mais elles le fuiront, parce qu\'elles ne connaissent point la voix des étrangers.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jésus leur fit cette allégorie, mais ils ne comprirent pas de quoi il leur parlait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jésus reprit et leur dit: «En vérité, en vérité, je vous le dis, je suis la porte des brebis:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'tous ceux qui sont venus avant moi sont des voleurs et des brigands; mais les brebis ne les ont point écoutés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Je suis la porte: si quelqu\'un entre par moi, il sera sauvé; il entrera et il sortira, et il trouvera de la pâture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Le voleur ne vient que pour voler, pour égorger et pour détruire; moi, je suis venu pour que les brebis aient la vie, et qu\'elles l\'aient abondamment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Je suis le bon berger: le bon berger donne sa vie pour ses brebis;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'mais le mercenaire, qui n\'est pas berger, à qui les brebis n\'appartiennent pas en propre, ne voit pas plutôt venir le loup, qu\'il abandonne les brebis, et s\'enfuit: le loup les ravit, et disperse le troupeau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Le mercenaire s\'enfuit, parce qu\'il est mercenaire, et qu\'il n\'a nul souci des brebis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Je suis le bon berger: je connais mes brebis et mes brebis me connaissent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'comme le Père me connaît et que je connais le Père; et je donne ma vie pour mes brebis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'J\'ai encore d\'autres brebis, qui ne sont pas de cette bergerie; il faut aussi que je les conduise: elles entendront ma voix; et il y aura un seul troupeau, un seul berger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Mon Père m\'aime, parce que je donne ma vie, afin de la reprendre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'personne ne me l\'ôte, mais je la donne de moi-même; j\'ai le pouvoir de la donner, et j\'ai le pouvoir de la reprendre: tel est l\'ordre que j\'ai reçu de mon Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Ces paroles provoquèrent une nouvelle division parmi les Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Un grand nombre d\'entre eux disaient: «Il est possédé d\'un démon, il déraisonne: pourquoi l\'écoutez-vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'D\'autres disaient: «Ces paroles ne sont point celles d\'un possédé: est-ce qu\'un démon peut ouvrir les yeux des aveugles?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Or, on célébrait à Jérusalem la fête de la Dédicace: c\'était l\'hiver;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'et Jésus se promenait dans le temple, sous le portique de Salomon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Les Juifs l\'entourèrent donc, et lui dirent: «Jusques à quand nous tiendras-tu l\'esprit en suspens? Si tu es le Messie, dis-le nous franchement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jésus leur répondit: «Je vous l\'ai dit, et vous ne le croyez pas: les oeuvres que je fais au nom de mon Père, rendent témoignage de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'mais vous ne croyez point, parce que vous n\'êtes pus de mes brebis,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'comme je vous l\'ai dit. Mes brebis entendent ma voix; je les connais, et elles me suivent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'je leur donne la vie éternelle, et elles ne périront jamais, et nul ne les ravira de ma main.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mon Père, qui me les a données, est plus grand que tous; et personne ne peut les ravir de la main de mon Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Le Père et moi, nous ne faisons qu\'un.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Là-dessus, les Juifs ramassèrent de nouveau des pierres pour le lapider.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jésus leur dit: «J\'ai fait sous vos yeux plusieurs bonnes oeuvres, par la puissance de mon Père; pour laquelle me lapidez-vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Les Juifs lui répondirent: «Ce n\'est point pour une bonne oeuvre que nous te lapidons, mais pour un blasphème, et parce qu\'étant homme, tu te fais dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jésus leur repartit: «N\'est-il pas écrit dans votre Loi: «J\'ai dit: Vous êtes des dieux?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Si donc la Loi appelle «dieux» ceux à qui la parole de Dieu a été adressée, et si l\'Écriture ne peut être rejetée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'comment pouvez-vous dire à celui que le Père a consacré et qu\'il a envoyé dans le monde, «tu blasphèmes,» parce que j\'ai dit: «Je suis le Fils de Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Si je ne fais pas les oeuvres de mon Père, ne me croyez pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'mais si je les fais, quand même vous ne me croiriez pas, croyez-en mes oeuvres; reconnaissez et sachez que le Père est en moi, et que je suis dans le Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Alors les Juifs cherchèrent de nouveau à se saisir de lui; mais il s \'échappa de leurs mains,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'et s\'en retourna au delà du Jourdain, dans le lieu où Jean avait baptisé tout d\'abord, et il y demeura.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Bien des gens venaient vers lui, et disaient: «Jean n\'a point fait de miracles, mais tout ce qu\'il a dit de celui-ci est vrai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Et il y eu eut là beaucoup qui crurent en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Il y avait un homme malade, nommé Lazare, qui était de Béthanie, village de Marie et de Marthe, sa soeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Marie est celle qui oignit de parfum le Seigneur, et lui essuya les pieds avec ses cheveux; et c\'était son frère Lazare qui était malade.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Les soeurs donc envoyèrent dire à Jésus: «Seigneur, celui que tu aimes est malade.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Jésus, ayant entendu ces paroles, dit: «Cette maladie ne va point à la mort, mais elle est pour la gloire de Dieu, afin que le Fils de Dieu soit glorifié par elle.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Or Jésus aimait Marthe, et sa soeur, et Lazare.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Lorsqu\'il eut appris que Lazare était malade, il resta encore deux jours dans le lieu où il était;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'puis, ce temps écoulé, il dit à ses disciples: «Retournons eu Judée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Les disciples lui dirent: «Maître, il n\'y a que peu de temps que les Juifs cherchaient à te lapider, et tu retournes en Judée?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jésus répondit: «N\'y a-t-il pas douze heures au jour? Si l’on marche pendant le jour, on ne se heurte point, parce qu\'on voit la lumière de ce monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'mais si l’on marche pendant la nuit, on se heurte, parce qu\'on manque de lumière.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Il parla ainsi, et ajouta: «Lazare, notre ami, dort; mais je vais l\'éveiller.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, '«Les disciples lui dirent: «Seigneur, s\'il dort, il sera guéri;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'mais Jésus avait parlé de sa mort, et eux avaient cru qu\'il parlait du repos du sommeil.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Alors Jésus leur dit ouvertement: «Lazare est mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'et je me réjouis à cause de vous de ce que je n\'étais pas là, afin que vous croyiez; mais allons vers lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Sur quoi Thomas, qui est appelé Didyme, dit aux autres disciples: «Allons-y aussi, afin de mourir avec lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Jésus étant arrivé, trouva qu\'il y avait déjà quatre jours que Lazare était dans le sépulcre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'et, comme Béthanie n\'était éloigné de Jérusalem que de quinze stades environ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'beaucoup de Juifs étaient venus voir Marthe et Marie pour les consoler de la mort de leur frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Dès que Marthe eut appris que Jésus venait, elle alla au-devant de lui; pour Marie, elle était assise à la maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marthe dit donc à Jésus: «Seigneur, si tu eusses été ici, mon frère ne serait pas mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'mais, maintenant même, je sais que tout ce que tu demanderas à Dieu, Dieu te l\'accordera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jésus lui dit: «Ton frère ressuscitera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, '— «Je sais, reprit Marthe, qu\'il ressuscitera, lors de la résurrection, au dernier jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jésus lui repartit: «Je suis la résurrection et la vie: celui qui croit en moi, vivra, quand même il serait mort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'et quiconque vit et croit en moi, ne mourra point pour toujours. Crois-tu cela?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Elle lui dit: «Oui, Seigneur, je crois que tu es le Messie, le Fils de Dieu, celui qui devait venir dans le monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Ayant ainsi parlé, elle s\'en alla, et appela en secret Marie, sa soeur, disant: «Le maître est là, et il te demande.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Dès que Marie l\'eut entendue, elle se leva promptement et alla vers lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Or Jésus n\'était pas encore entré dans le village, mais il était à l\'endroit où Marthe l\'avait rencontré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Les Juifs qui étaient avec Marie, dans la maison, et qui la consolaient, la voyant se lever promptement et sortir, la suivirent, disant: «Elle va au sépulcre pour y pleurer.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Dès que Marie fut arrivée à l\'endroit où était Jésus, et qu\'elle le vit, elle tomba à ses pieds, et lui dit: «Seigneur, si tu eusses été ici, mon frère ne serait pas mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Lorsque Jésus la vit pleurer, elle et les Juifs qui l\'accompagnaient, il frémit intérieurement, et, se laissant aller à son émotion,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'il dit: «où l\'avez-vous mis?» Ils lui dirent: «Seigneur, viens et vois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jésus pleura.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Les Juifs disaient donc: «Voyez comme il l\'aimait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Toutefois quelques-uns d\'entre eux dirent: «Lui, qui a ouvert les yeux de l\'aveugle, ne pouvait-il pas faire aussi que celui-ci ne mourût pas?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jésus, frémissant de nouveau en lui-même, se rend au sépulcre: c\'était un caveau, et une pierre était posée dessus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jésus dit: «Otez la pierre.» La soeur du mort, Marthe, lui dit: «Seigneur, il a déjà de l\'odeur; car il y a quatre jours qu\'il est là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jésus lui repartit: «Ne t\'ai-je pas dit que si tu crois, tu terras la gloire de Dieu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Ils ôtèrent donc la pierre; alors Jésus, levant les yeux en haut, dit: «Père, je te rends grâce de ce que tu m\'as exaucé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Pour moi, je savais bien que tu m\'exauces toujours, mais je dis cela à cause de cette foule qui m\'entoure, afin qu\'elle croie que c\'est toi qui m\'as envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Ayant ainsi parlé, il cria d\'une voix forte: «Lazare, sors;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'et le mort sortit, les mains et les pieds liés de bandelettes, et le visage enveloppé d\'un suaire. Jésus leur dit: «Déliez-le, et le laissez aller.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Un grand nombre de Juifs, la plupart de ceux qui étaient venus visiter Marie et avaient vu ce miracle de Jésus, crurent en lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'quelques-uns d\'entre eux, cependant, allèrent trouver les pharisiens et leur rapportèrent ce que Jésus avait fait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Alors les principaux sacrificateurs et les pharisiens assemblèrent le Sanhédrin et dirent: «Que ferons-nous? car cet homme opère beaucoup de miracles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'si nous le laissons faire, tout le monde croira en lui, et les Romains viendront, et ils détruiront notre temple et notre nation.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'L\'un d\'eux, nommé Caïphe, souverain sacrificateur cette année-là, leur dit: «Vous n\'y entendez rien;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'vous ne réfléchissez pas qu\'il nous est avantageux qu\'un seul homme meure pour le peuple, et que toute la nation ne périsse pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Or, il ne dit pas cela de son propre mouvement, mais comme il était souverain sacrificateur cette année-là, il prophétisa que Jésus devait mourir pour la nation;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'mais non pas pour la nation seulement, car c\'était aussi afin de réunir en un seul corps les enfants de Dieu qui sont dispersés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Dès ce jour, ils délibérèrent de le faire mourir;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'c\'est pourquoi Jésus ne se montra plus en public parmi les Juifs, et s\'en alla dans les campagnes de la Judée, près du désert, à Ephraïm-la-Ville, où il séjourna avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Cependant la Pâque des Juifs était proche, et beaucoup de gens montèrent des campagnes de la Judée à Jérusalem, avant la Pâque, pour se purifier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Ils cherchaient Jésus, et, étant dans le temple, ils se disaient entre eux: «Qu\'en pensez-vous? Ne viendra-t-il pas à la fête?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Or les principaux sacrificateurs et les pharisiens avaient donné l\'ordre que si l\'on savait où il était, on eût à le déclarer, afin qu\'ils le fissent prendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Six jours avant la Pâque, Jésus se rendit à Béthanie, où était Lazare, le mort qu\'il avait ressuscité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Là, on lui donna à souper; Marthe servait, et Lazare était un de ceux qui étaient à table avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Marie ayant pris une livre d\'un parfum de nard pur très-précieux, en oignit les pieds de Jésus, et les essuya avec ses cheveux. Toute la maison fut remplie de l\'odeur de ce parfum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Alors l\'un de ses disciples, Judas l\'Iscariote, celui qui devait le livrer, dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '«Pourquoi n\'avoir pas vendu ce parfum trois cents deniers, et n\'en avoir pas donné l’argent aux pauvres?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Il disait cela, non qu\'il se souciât des pauvres, mais parce qu\'il était voleur, et qu\'il tenait la bourse et portait ce qu\'on y mettait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jésus lui dit donc: «Laisse-la en paix; elle a voulu garder ce parfum pour le jour de ma sépulture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Vous aurez toujours des pauvres avec vous, mais, moi, vous ne m\'aurez pas toujours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Une foule de Juifs surent donc que Jésus était à Béthanie, et ils y vinrent, non seulement à cause de Jésus, mais aussi pour voir Lazare, qu\'il avait ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Les principaux sacrificateurs délibérèrent de faire mourir aussi Lazare, parce qu\'à son occasion beaucoup de Juifs les quittaient et croyaient en Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Le lendemain, une multitude de gens qui étaient venus pour la fête, ayant appris que Jésus venait à Jérusalem,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'prirent des branches de palmier et allèrent au-devant de lui, en criant: «Hosanna! Béni soit celui qui vient au nom du Seigneur, le Roi d\'Israël.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Jésus, ayant trouvé un ânon, monta dessus, selon qu\'il est écrit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, '«Ne crains point, fille de Sion, voici ton roi qui vient, monté sur le petit d\'une ânesse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ses disciples ne comprirent pas ces choses tout d\'abord, mais quand Jésus eut été glorifié, ils se souvinrent qu\'elles étaient écrites pour lui, et qu\'ils les avaient accomplies à son égard.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'La foule donc qui était avec Jésus, rendait témoignage qu\'il avait fait sortir Lazare du sépulcre, et l\'avait ressuscité des morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'et c\'est aussi parce qu\'elle avait appris qu\'il avait fait ce miracle, que la multitude s\'était portée à sa rencontre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Sur quoi les pharisiens se dirent les uns aux autres: «Vous voyez bien que vous ne gagnez rien; voilà que tout le monde court après lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Or, dans le nombre des Grecs qui montent à Jérusalem, pour adorer, lors de la fête,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'il s\'en trouva là quelques-uns qui abordèrent Philippe de Bethsaïde en Galilée, et lui firent cette demande: «Seigneur, nous voudrions bien voir Jésus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Philippe alla le dire à André, puis André et Philippe le dirent à Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Jésus leur répondit: «L\'heure est venue où le Fils de l\'homme doit être glorifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'En vérité, en vérité, je vous le dis, si le grain de blé ne meurt, après qu\'il est tombé en terre, il demeure seul; mais s\'il meurt, il porte beaucoup de fruit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Celui qui aime sa vie, la perdra; mais celui qui hait sa vie en ce monde, la conservera pour la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Si quelqu\'un me sert, qu\'il me suive; et là où je suis, là aussi sera mon serviteur: si quelqu\'un me sert, mon Père l\'honorera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Maintenant mon âme est troublée... et que dirai-je?... Père, délivre-moi de cette heure... mais c\'est pour cette heure même que je suis venu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Père, glorifie ton nom.» Alors il vint une voix du ciel: «Je l\'ai glorifié, et je le glorifierai encore.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'La foule qui était là, et qui avait entendu, disait: «C\'est un tonnerre;» d\'autres disaient: «Un ange lui a parlé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Jésus dit: «Ce n\'est pas pour moi, que cette voix s\'est fait entendre; c\'est pour vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'C\'est maintenant que le jugement de ce monde a lieu; c\'est maintenant que le prince de ce monde va être expulsé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'quant à moi, dès que j\'aurai été élevé de la terre, j\'attirerai tous les hommes à moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, '(Il indiquait par là de quelle mort il devait mourir.)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'La foule lui répondit: «Nous avons appris par la Loi que le Messie doit demeurer éternellement, comment donc dis-tu que le Fils de l\'homme doit être élevé? Qui est ce Fils de l\'homme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Jésus leur dit donc:» La lumière n\'est plus au milieu de vous que pour un peu de temps; marchez, puisque vous avez la lumière, de peur que les ténèbres ne vous surprennent; celui qui marche dans les ténèbres ne sait où il va.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Puisque vous avez la lumière, croyez en la lumière, afin que vous soyez des enfants de lumière.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Ainsi parla Jésus, et, s\'en étant allé, il ne se montra plus à eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Quoiqu\'il eût fait tant de miracles en leur présence, ils ne croyaient point en lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'afin que s\'accomplît la parole qu\'Ésaïe le prophète a prononcée: «Seigneur, qui a cru à notre prédication, et à qui le bras du Seigneur a-t-il été révélé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Et ils ne pouvaient croire, parce qu\'Ésaïe a dit encore:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '«Il a aveuglé leurs yeux et endurci leur coeur, afin qu\'ils ne voient pas de leurs yeux, ne comprennent pas de leur coeur, et qu\'ils ne se convertissent pas: aussi ne les guérirai-je point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'C\'est là ce que dit Esaïe, lorsqu\'il vit la gloire du Seigneur et qu\'il parla de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Plusieurs, toutefois, même parmi les sénateurs, crurent en lui; mais, à cause des pharisiens, ils ne le confessaient point, de peur d\'être chassés de la synagogue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Ils aimèrent mieux la gloire des hommes que la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Cependant Jésus avait dit à haute voix: «Quiconque croit en moi, croit, non pas en moi, mais en celui qui m\'a envoyé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'et quiconque me voit, voit celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Je suis venu dans le monde comme une lumière, afin qu\'aucun de ceux qui croient en moi, ne demeure dans les ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Si quelqu\'un entend mes paroles et ne les garde pas, je ne le juge point, car je suis venu, non pour juger le monde, mais pour le sauver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Celui qui me rejette et repousse mes paroles a son juge: c\'est la parole que j\'ai prêchée, c\'est elle qui le jugera au dernier jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Car je n\'ai point parlé de mon chef, mais le Père, qui m\'a envoyé, m\'a lui-même commandé ce que je dois dire et ce dont je dois parler;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'et je sais que son commandement, c\'est la vie éternelle. En conséquence, les choses que j\'annonce, je les annonce comme le Père me les a dites.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Avant la fête de Pâque, Jésus, sachant que son heure était venue de quitter ce monde pour aller vers le Père, témoigna souverainement aux siens, qui sont dans le monde, l\'amour dont il les avait aimés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Dans un repas, le diable ayant déjà mis dans le coeur de Judas Iscariote, fils de Simon, le dessein de livrer son Maître,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jésus, qui savait que le Père avait remis toutes choses entre ses mains, qu\'il était venu de Dieu et qu\'il s\'en allait vers Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'se leva de table, posa son manteau, et, ayant pris un linge, il s\'en ceignit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'puis, ayant versé de l\'eau dans le bassin, il se mit à laver les pieds de ses disciples et à les essuyer avec le linge dont il était ceint.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Il vint donc à Simon Pierre, qui lui dit: «Toi, Seigneur, me laver les pieds!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jésus lui répondit: «Ce que je fais, tu ne le sais pas en ce moment, mais tu le sauras tout à l\'heure.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pierre lui dit: «Non, jamais tu ne me laveras les pieds.» Jésus lui répondit: «Si je ne te lave, tu n\'auras point de part avec moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simon Pierre lui dit: «Seigneur, non seulement les pieds, mais encore les mains et la tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jésus lui dit: «Celui qui s\'est baigné, n\'a besoin que de se laver les pieds, il est net dans toute sa personne; et vous êtes nets... mais non pas tous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Il savait en effet qui était celui qui allait le livrer, c\'est pourquoi il dit: «Vous n\'êtes pas tous nets.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Après qu\'il leur eut lavé les pieds, il reprit son manteau, et, s\'étant remis à table, il leur dit: «Comprenez-vous ce que je vous ai fait?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vous m\'appelez Maître et Seigneur; et vous avez raison, car je le suis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Si donc moi, le Seigneur et le Maître, je vous ai lavé les pieds, vous devez aussi vous laver les pieds les uns aux autres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'car je vous ai donné un exemple, afin que, comme je vous ai fait, vous fassiez aussi vous-mêmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'en vérité, en vérité, je vous le dis, le serviteur n\'est pas plus grand que son maître, ni l\'envoyé plus grand que celui qui l\'envoie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Si vous savez ces choses, vous êtes bienheureux, pourvu que vous les pratiquiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Je ne dis pas cela de vous tous; je connais ceux que j\'ai choisis, mais il faut que cette parole de l\'Ecriture soit accomplie: «Celui qui mange le pain avec moi, a levé le pied contre moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Je vous le dis dès à présent, avant que la chose arrive, afin que, lorsqu\'elle sera arrivée, vous reconnaissiez qui je suis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'En vérité, en vérité, je vous le dis, quiconque reçoit celui que j\'envoie, me reçoit, et quiconque me reçoit, reçoit celui qui m\'a envoyé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Ayant ainsi parlé, Jésus fut ému profondément, et il dit ouvertement: «En vérité, en vérité, je vous dis que l\'un de vous me livrera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Ses disciples se regardaient les uns les autres, ne sachant de qui il voulait parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Or l\'un d\'eux était couché sur le sein de Jésus: c\'était celui que Jésus aimait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Pierre lui fit donc signe, pour lui dire: «De qui parle-t-il?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Le disciple se penchant sur le sein de Jésus, lui dit: «Seigneur, qui est-ce?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jésus lui répondit: «C\'est celui à qui je donnerai le morceau de pain que je vais tremper.» Alors ayant trempé le morceau, il le donna à Judas Iscariote, fils de Simon;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'et aussitôt que Judas l\'eut pris, Satan entra en lui. Jésus lui dit: «Fais au plus tôt ce que tu as à faire;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'mais aucun de ceux qui étaient à table ne comprit pourquoi il lui disait cela:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'quelques-uns pensaient que, comme Judas avait la bourse, Jésus voulait lui dire: «Achète ce qu\'il nous faut pour la fête,» ou qu\'il lui commandait de donner quelque chose aux pauvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Judas, ayant pris le morceau de pain, sortit aussitôt. Il était nuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Lorsqu\'il fut sorti, Jésus dit: «Maintenant le Fils de l\'homme a été glorifié, et Dieu a été glorifié en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Puisque Dieu a été glorifié en lui, Dieu aussi le glorifiera en lui-même, et il le glorifiera bientôt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Mes chers enfants, je ne suis plus avec vous que pour un peu de temps; vous me chercherez; et comme j\'ai dit aux Juifs qu\'ils ne pouvaient venir où je vais, je vous le dis aussi à cette heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Je vous donne un commandement nouveau, c\'est de vous aimer les uns les autres comme je vous ai aimés; vous aussi, aimez-vous les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'C\'est à ceci que tous connaîtront que vous êtes mes disciples, si vous avez de l\'amour les uns pour les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Pierre lui dit: «Seigneur, où vas-tu?» Jésus lui répondit: «Là où je vais, tu ne peux me suivre maintenant; plus tard, tu me suivras.» —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, '«Seigneur, lui dit Pierre, pourquoi ne puis-je te suivre à cette heure? Je donnerai ma vie pour toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jésus lui répondit: «Tu donneras ta vie pour moi? En vérité, en vérité, je te le dis, le coq ne chantera pas, que tu ne m\'aies renié trois fois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Que votre coeur ne se trouble point. Confiez-vous en Dieu; confiez-vous aussi en moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Il y a beaucoup de demeures dans la maison de mon Père; si cela n\'était pas, je vous l\'aurais dit: je vais vous y préparer une place.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Dès que je serai allé, et que je vous aurai préparé une place, je reviendrai, et je vous prendrai auprès de moi, afin que là où je suis, vous y soyez aussi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'et là où je vais, vous en savez le chemin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Thomas lui dit: «Seigneur, nous ne savons où tu vas, comment donc en saurions-nous le chemin?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jésus lui dit: «Je suis le chemin, la vérité et la vie; nul ne vient au Père que par moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Si vous me connaissiez, vous connaîtriez aussi mon Père... et dès à présent vous le connaissez, et vous l\'avez vu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Philippe lui dit: «Seigneur, montre-nous le Père, et cela nous suffit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jésus lui dit: «Il y a si longtemps que je suis avec vous, et tu ne m\'as pas connu, Philippe! Celui qui m\'a vu, a vu le Père; comment donc peux-tu dire: Montre-nous le Père?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne crois-tu pas que je suis dans le Père, et que le Père est en moi? Les paroles que je vous dis, je ne les dis pas de mon chef: le Père qui demeure en moi fait lui-même les oeuvres que je fais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Croyez-moi, croyez que je suis dans le Père, et que le Père est en moi; si non croyez-le à cause de ces oeuvres mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, '«En vérité, en vérité, je vous le dis, celui qui croit en moi fera aussi les oeuvres que je fais; et il en fera de plus grandes encore, parce que je m\'en vais vers le Père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'et que tout ce que vous demanderez en mon nom, je le ferai, afin que le Père soit glorifié dans le Fils:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'si vous demandez quelque chose en mon nom, je le ferai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Si vous m\'aimez, gardez mes commandements;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'quant à moi, je prierai le Père, et il vous donnera un autre Directeur, afin qu\'il soit éternellement avec vous:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'c\'est l\'Esprit de vérité, que le monde ne peut recevoir, parce qu\'il ne le voit point et qu\'il ne le connaît point; mais vous, vous le connaissez, parce qu\'il demeure auprès de vous; et il sera en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Je ne vous laisserai point orphelins; je viendrai vers vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Encore un peu de temps, et le monde ne me verra plus; mais vous, vous me verrez; parce que je vis, vous aussi vous vivrez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'En ce jour-là, vous connaîtrez que je suis en mon Père, et que vous êtes en moi, et que je suis en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Celui qui retient mes commandements et qui les garde, c\'est celui-là qui m\'aime: celui qui m\'aime sera aimé de mon Père; et moi, je l\'aimerai, et je me ferai connaître à lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas, non pas l’Iscariote, lui dit: «Seigneur, et d\'où vient que tu te feras connaître à nous, mais non pas au monde?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jésus répondit et lui dit: «Si quelqu\'un m\'aime, il gardera ma parole: mon Père l\'aimera, et nous viendrons vers lui, et nous ferons notre demeure chez lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Celui qui ne m\'aime pas, ne garde pas mes paroles; et la parole que vous entendez n\'est pas de moi, mais elle est de mon Père, qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Je vous dis ces choses, pendant que je demeure auprès de vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'mais le Directeur, le Saint-Esprit, que mon Père enverra en mon nom, vous enseignera toutes choses, et vous fera ressouvenir de tout ce que je vous ai dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Je vous laisse la paix; je vous donne ma paix; je ne la donne pas comme le monde la donne. Que votre coeur ne se trouble point, qu\'il ne s\'intimide point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Vous avez entendu que je vous ai dit, «je m\'en vais, et je reviens vers vous;» si vous m\'aimiez, vous vous réjouiriez de ce que je vais vers le Père, car mon Père est plus grand que moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Je vous dis maintenant ces choses, avant qu\'elles arrivent, afin que, lorsqu\'elles seront arrivées, vous croyiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Je ne m\'entretiendrai plus guère avec vous, car le prince du monde vient; et il n\'a rien en moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mais afin que le monde sache que j\'aime le Père, et que j\'agis selon que le Père m\'a commandé, levez-vous, partons d\'ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '«Je suis le vrai cep, et mon Père est le vigneron:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'tout sarment qui est en moi et qui ne porte pas de fruit, il le retranche; et tout sarment qui porte du fruit, il le nettoie, afin qu\'il en porte davantage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Pour vous, vous êtes déjà nets, à cause de la parole que je vous ai annoncée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Demeurez en moi, et je demeurerai en vous. Comme le sarment ne peut de lui-même porter du fruit, s\'il ne demeure attaché au cep, ainsi vous ne le pouvez non plus, si vous ne demeurez en moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Je suis le cep, et vous êtes les sarments: celui qui demeure en moi, et en qui je demeure, porte beaucoup de fruit, car hors de moi, vous ne pouvez rien faire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Si quelqu\'un ne demeure pas en moi, on le jette dehors, comme le sarment, et il sèche; puis on ramasse ces sarments, on les jette au feu, et ils brûlent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Si vous demeurez en moi, et que mes paroles demeurent en vous, demandez ce que vous voudrez, et cela vous sera accordé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'C\'est en ceci que mon Père sera glorifié, si vous portez beaucoup de fruit; et vous serez mes disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Comme le Père m\'a aimé, je vous ai aussi aimés: demeurez dans mon amour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Si vous gardez mes commandements, vous demeurerez dans mon amour, comme j\'ai gardé moi-même les commandements de mon Père, et je demeure dans son amour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Je vous dis ces choses, afin que ma joie soit en vous, et que votre joie soit parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'C\'est ici mon commandement, que vous vous aimiez les uns les autres, comme je vous ai aimés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Il n\'y a pas de plus grand amour, que de donner sa vie pour ses amis;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'vous êtes mes amis, si vous faites ce que je vous commande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Je ne vous appelle plus serviteurs, parce que le serviteur ne sait pas ce que fait son maître; mais je vous appelle «amis,» parce que je vous ai fait connaître tout ce que j\'ai appris de mon Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ce n\'est pas vous qui m\'avez choisi; c\'est moi qui vous ai choisis, et qui vous ai établis, afin que vous alliez dans le monde, que vous portiez du fruit, un fruit qui demeure, et que le Père vous accorde ce que vous lui demanderez en mon nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Je vous donne ces instructions, afin que vous vous aimiez les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Si le monde vous hait, sachez qu\'il m\'a haï avant vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Si vous étiez du monde, le monde aimerait ce qui serait à lui; parce que vous n\'êtes pas du monde, et que je vous ai choisis du milieu du monde, c\'est pour cela que le monde vous hait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Rappelez-vous la parole que je vous ai dite: «Le serviteur n\'est pas plus grand que son maître;» s\'ils m\'ont persécuté» ils vous persécuteront aussi; s\'ils ont gardé ma parole, ils garderont aussi la vôtre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'mais ils vous feront toutes ces choses à cause de mon nom, parce qu\'ils ne connaissent point celui qui m\'a envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Si je n\'étais pas venu, et que je ne leur eusse point parlé, ils seraient sans péché, mais maintenant leur péché est sans excuse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Celui qui me hait, hait aussi mon Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Si je n\'avais pas fait au milieu d\'eux des oeuvres qu\'aucun autre n\'a faites, ils seraient sans péché; mais maintenant ils les ont vues; et ils ont haï et moi et mon Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Mais il fallait que s\'accomplît la parole qui est écrite dans leur Loi: «Ils m\'ont haï sans sujets.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Quand le Directeur que je vous enverrai de la part du Père, l\'Esprit de vérité qui provient du Père, sera venu, c\'est lui qui rendra témoignage de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'vous aussi, vous me rendrez témoignage, parce que vous avez été dès le commencement avec moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '«Je vous ai parlé de ces choses, afin que vous ne vous laissiez point scandaliser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Ils vous excluront de leurs synagogues; l\'heure même vient, où quiconque vous fera mourir, croira servir Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'et ils agiront de la sorte, parce qu\'ils n\'auront connu ni le Père, ni moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Je vous le dis, afin que, lorsque l\'heure sera venue, il vous souvienne que je vous en ai parlé. Je ne vous en ai pas parlé dès le commencement, parce que j\'étais avec vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Maintenant que je m\'en vais vers celui qui m\'a envoyé, aucun de vous ne me demande: «où vas-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'mais, parce que je vous ai dit ces choses, la tristesse a rempli votre coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Cependant moi, je vous dis la vérité: il vous est bon que je m\'en aille, car si je ne m\'en vais pas, le Directeur ne viendra point vers vous, tandis que, si je m\'en vais, je vous l\'enverrai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Et quand il sera venu, il convaincra le monde au sujet du péché, de la justice et du jugement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'au sujet du péché, parce que le monde ne croit pas en moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'de la justice, parce que je m\'en vais vers le Père, et que vous ne me verrez plus;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'du jugement, parce que le prince de ce monde est jugé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'J\'ai encore beaucoup de choses à vous dire, mais elles sont présentement au-dessus de votre portée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Quand l\'Esprit de vérité sera venu, il vous guidera dans toute la vérité; car il ne parlera pas de son chef, mais il dira tout ce qu\'il aura entendu, et il vous annoncera ce qui doit arriver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Il me glorifiera, parce qu\'il prendra de ce qui est à moi, et vous l\'annoncera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tout ce que le Père a, est à moi; c\'est pourquoi je dis qu\'il prendra de ce qui est à moi, et qu\'il vous l\'annoncera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Encore un peu de temps, et vous ne me verrez plus; puis un peu de temps encore, et vous me verrez, parce que je vais vers le Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Alors quelques-uns de ses disciples se dirent les uns aux autres: «Qu\'est-ce qu\'il nous dit: «Encore un peu de temps et vous ne me verrez plus; puis un peu de temps encore, et vous me verrez;» et «parce que je m\'en vais vers le Père?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Ils disaient donc: «Que veut-il dire avec ce «un peu de temps?» Nous ne savons ce qu\'il veut dire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jésus comprit qu\'ils voulaient l\'interroger, et il leur dit: «Vous discutez entre vous sur ce que j\'ai dit, «encore un peu de temps, et vous ne me verrez plus; puis un peu de temps encore, et vous me verrez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'En vérité, en vérité je vous dis que vous pleurerez et que vous vous lamenterez, tandis que le monde se réjouira; vous serez affligés, mais votre affliction se changera en joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Quand la femme enfante, elle est dans la douleur, parce que son heure est venue; mais quand elle a donné le jour à l\'enfant, elle ne se souvient plus de sa souffrance, dans la joie qu\'elle éprouve de ce qu\'un homme est venu au monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Vous donc aussi, vous êtes maintenant dans l\'affliction, mais je vous reverrai, et votre coeur sera réjoui, et nul ne vous ravira votre joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'En ce jour-là, vous ne m\'interrogerez plus sur rien: en vérité, en vérité, je vous dis que ce que vous demanderez au Père en mon nom, il vous le donnera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Jusqu\'à présent vous n\'avez rien demandé en mon nom; demandez et vous recevrez, afin que votre joie soit parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Je vous ai dit ces choses en me servant de figures; l\'heure vient où je ne vous parlerai plus par figures, mais où je vous parlerai ouvertement du Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'En ce jour-là, vous demanderez en mon nom, et je ne vous dis pas que je prierai le Père pour vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'car le Père lui-même vous aime, parce que vous m\'avez aimé, et que vous avez cru que je suis venu de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Je suis venu du Père, et je suis venu dans le monde; maintenant je quitte le monde, et je vais vers le Père.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Ses disciples lui dirent: «Voici, c\'est maintenant que tu parles ouvertement et sans figures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Maintenant nous voyons bien que tu sais toutes choses et que tu n\'as pas besoin que l\'on t\'interroge; c\'est pourquoi nous croyons que tu es venu de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jésus leur répondit: «Vous croyez à présent...');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Voici l\'heure vient, et elle est déjà venue, où vous allez être dispersés, chacun de vous s\'enfuira chez soi, et vous me laisserez seul; pourtant je ne suis pas seul, parce que le Père est avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Je vous ai dit ces choses, afin que vous ayez la paix en moi: vous aurez des tribulations dans le monde, mais prenez courage, j\'ai vaincu le monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Ainsi parla Jésus, puis il leva les yeux au ciel, et dit: «Père, l\'heure est venue, glorifie ton Fils, afin que ton Fils te glorifie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'selon que tu lui as donné autorité sur toute chair, afin qu\'à tous ceux que tu lui as donnés, il donne la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Or c\'est ici la vie éternelle, qu\'ils te connaissent, toi, pour le seul vrai Dieu, et pour Messie, Jésus que tu as envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Pour moi, je t\'ai glorifié sur la terre, j\'ai achevé l\'oeuvre que tu m\'as donné à faire:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'maintenant, toi, Père, glorifie-moi auprès de ta personne, en me rendant la gloire que je possédais auprès de toi, avant que le monde fût.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'J\'ai fait connaître ton nom aux hommes que tu as tirés du monde, pour me les donner; ils étaient à toi, tu me les a donnés, et ils ont gardé ta parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Ils ont reconnu maintenant que tout ce que tu m\'as donné, vient de toi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'car les paroles que tu m\'as données, je les leur ai données, et ils les ont reçues: ils ont vraiment connu que je viens de ta part, et ils ont cru que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Moi, je prie pour eux: je ne prie pas pour le monde, mais je prie pour ceux que tu m\'as donnés, parce qu\'ils sont à toi');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, '(tout ce qui est à moi est à toi, et tout ce qui est à toi est à moi)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'et que je suis glorifié en eux. Je ne suis plus dans le monde; pour eux, ils sont dans le monde, mais moi, je vais vers toi. Père saint, garde-les fidèles à ton nom, que tu m\'as chargé de manifester, afin qu\'ils ne fassent qu\'un, comme nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Lorsque j\'étais avec eux, je les gardais fidèles à ton nom: j\'ai gardés ceux que tu m\'as donnés, et aucun d\'eux ne s\'est perdu, hormis le fils de perdition, afin que l\'Ecriture fût accomplie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Maintenant je vais vers toi, et je t\'adresse cette prière, pendant que je suis dans le monde, afin qu\'ils possèdent complètement ma joie au dedans d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Je leur ai donné ta parole, et le monde les a haïs, parce qu\'ils ne sont pas du monde, comme moi-même je ne suis pas du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Je ne te demande pas de les ôter du monde, mais de les préserver du mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Ils ne sont pas du monde, comme moi-même je ne suis pas du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Sanctifie-les par ta vérité: ta parole est vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Comme tu m\'as envoyé dans le monde, je les ai aussi envoyés dans le monde,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'et je me sanctifie moi-même pour eux, afin que eux aussi soient vraiment sanctifiés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ce n\'est pas pour eux seulement que je prie, mais je prie encore pour ceux qui, par leur parole, vont croire en moi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'pour que tous ne fassent qu\'un, comme toi, mon Père, tu es en moi et moi en toi - pour qu\'eux aussi ne fassent qu\'un en nous, afin que le monde croie que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Et je leur ai donné la gloire que tu m\'as donnée, afin qu\'ils ne fassent qu\'un, comme nous ne faisons qu\'un,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'moi en eux et toi en moi - afin qu\'ils soient parfaits dans l\'unité, et que le monde connaisse que c\'est toi qui m\'as envoyé, et que tu les as aimés comme tu m\'as aimé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Père, ma volonté est que là où je suis, ceux que tu m\'as donnés y soient aussi avec moi, afin qu\'ils voient ma gloire, la gloire que tu m\'as donnée, parce que tu m\'as aimé avant la création du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Père juste, le monde ne t\'a point connu; mais, moi, je t\'ai connu, et ceux-ci ont connu que c\'est toi qui m\'as envoyé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Je leur ai fait connaître ton nom, et je le leur ferai connaître, afin que l\'amour dont tu m\'as aimé soit en eux, et que je sois moi-même en eux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Ayant ainsi parlé, Jésus, accompagné de ses disciples, passa au delà du torrent de Cédron, où se trouvait un jardin dans lequel il entra avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Judas, qui le livrait, connaissait aussi ce lieu-là, parce que Jésus y était souvent allé avec ses disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas donc, à la tête de la cohorte et des agents des principaux sacrificateurs et des pharisiens, y vint avec des lanternes, des flambeaux et des armes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Alors Jésus, qui savait tout ce qui devait lui arriver, sortit et leur dit: «Qui cherchez- vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ils lui répondirent: «Jésus de Nazareth.» Jésus leur dit: «C\'est moi.» Or Judas, qui le livrait, était là avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Lorsque Jésus leur eut dit, «c\'est moi,» ils reculèrent et tombèrent par terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Il leur demanda une seconde fois: «Qui cherchez-vous?» Ils répondirent: «Jésus de Nazareth.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jésus reprit: «Je vous ai dit que c\'est moi. Si donc c\'est moi que vous cherchez, laissez aller ceux-ci.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Il parla ainsi, afin que s\'accomplît cette parole qu\'il avait dite: «Je n\'ai perdu aucun de ceux que tu m\'as donnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Pierre, qui avait une épée, la tira, en frappa le serviteur du souverain sacrificateur, et lui coupa l\'oreille droite: ce serviteur s\'appelait Malchus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jésus dit à Pierre: «Remets ton épée dans le fourreau: ne boirai-je pas le calice que mon Père m\'a donné à boire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Alors la cohorte, le tribun et les agents des Juifs se saisirent de Jésus, le lièrent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'et l\'emmenèrent d\'abord chez Anne: c\'était le beau-père de Caïphe qui était souverain sacrificateur cette année-là,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'et Caïphe était celui qui avait donné aux Juifs ce conseil: «Il est avantageux qu\'un seul homme périsse pour le peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Cependant Simon Pierre et l\'autre disciple suivaient Jésus. Ce disciple était connu du souverain sacrificateur, et il entra en même temps que Jésus dans la cour du souverain sacrificateur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'tandis que Pierre était resté à la porte, en dehors. L\'autre disciple, qui était connu du souverain sacrificateur, sortit donc, parla à la portière, et fit entrer Pierre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Alors cette servante dit à Pierre: «N\'es-tu pas, toi aussi, des disciples de cet homme?» Il dit: «Je n\'en suis point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Les serviteurs et les agents se tenaient autour d\'un brasier qu\'ils avaient allumé, parce qu\'il faisait froid, et ils se chauffaient. Pierre était aussi là, et se chauffait avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Le souverain sacrificateur interrogea Jésus sur ses disciples et sur sa doctrine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jésus lui répondit: «J\'ai parlé ouvertement à tout le monde; j\'ai toujours enseigné en pleine synagogue et dans le temple, où tous les Juifs s\'assemblent, et je n\'ai rien dit en secret.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Pourquoi m\'interroges-tu? Demande à ceux qui m\'ont entendu ce que je leur ai dit: ils savent ce que j\'ai dit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Comme il prononçait ces mots, un des agents, qui se trouvait-là, donna un soufflet à Jésus, en disant: «C\'est ainsi que tu réponds au souverain sacrificateur?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jésus lui répondit: «Si j\'ai mal parlé, fais voir ce que j\'ai dit de mal; mais si j\'ai bien parlé, pourquoi me frappes-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Anne l\'avait envoyé lié à Caïphe, le souverain sacrificateur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Cependant Simon Pierre était debout qui se chauffait. On lui dit donc: «N\'es-tu pas, toi aussi, de ses disciples?» Il le nia, et dit: «Je n\'en suis point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Un des serviteurs du souverain sacrificateur, parent de celui à qui Pierre avait coupé l\'oreille, lui dit: «Ne t\'ai-je pas vu avec lui dans le jardin?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pierre le nia encore une fois, et aussitôt un coq chanta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Les sénateurs menèrent donc Jésus de chez Caïphe au prétoire. C\'était de grand matin. Ils n\'entrèrent point dans le prétoire de peur de se souiller et de ne pouvoir manger la pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilate se rendit donc vers eux, et leur dit: «De quoi accusez-vous cet homme?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Ils lui répondirent: «Si ce n\'était pas un malfaiteur, nous ne te l\'aurions pas livré.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Alors Pilate leur dit: «Prenez-le vous-mêmes, et le jugez selon votre loi.» Mais les Juifs lui répondirent: «Nous n\'avons pas le droit de mettre à mort personne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Cela arriva, afin que s\'accomplît la parole que Jésus avait prononcée, quand il avait indiqué de quelle mort il devait mourir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilate étant rentré dans le prétoire, fit venir Jésus et lui dit: «C\'est toi qui es le roi des Juifs?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jésus répondit: «Dis-tu cela de toi-même, ou d\'autres te l\'ont-ils dit de moi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, '— «Suis-je Juif, moi?» lui répliqua Pilate. «La nation et les principaux sacrificateurs t\'ont livré à moi: qu\'as-tu fait?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jésus répondit: «Mon royaume n\'est pas de ce monde. Si mon royaume était de ce monde, mes gens auraient combattu pour que je ne fusse pas livré aux Juifs, mais mon royaume n\'est pas d\'ici-bas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilate lui dit: «Ainsi tu es roi?» — «Tu le dis, répondit Jésus, je suis roi; je suis né, et je suis venu dans le monde pour rendre témoignage à la vérité. Quiconque est pour la vérité, écoute ma voix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilate lui dit: «Qu\'est-ce que la vérité?» En disant ces mots, il se rendit de nouveau vers les Juifs, et leur dit: «Pour moi, je ne trouve aucun crime en lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'mais il est d\'usage que je vous relâche un prisonnier à Pâque, voulez-vous donc que je vous relâche le roi des Juifs?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Alors tous crièrent de nouveau: «Non pas lui, mais Barrabas.» Or Barrabas était un brigand.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Alors Pilate fit prendre Jésus et le lit battre de verges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Et les soldats, ayant tressé une couronne d\'épines, la lui mirent sur la tête; ils le revêtirent aussi d\'un manteau de pourpre, puis, s\'approchant de lui, ils lui disaient:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, '«Salut, roi des Juifs,» et ils lui donnaient des soufflets.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilate sortit encore une fois du prétoire, et dit aux Juifs: «Voici, je vous l\'amène, afin que vous sachiez que je ne trouve aucun crime en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jésus sortit donc, portant la couronne d\'épines et le manteau de pourpre, et Pilate leur dit: «Voilà l\'homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Dès que les principaux sacrificateurs et leurs agents le virent, ils se mirent à crier: «Crucifie! crucifie-le!» Pilate leur dit: «Prenez-le vous-mêmes, et le crucifiez; car, pour moi, je ne trouve aucun crime en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Les Juifs lui répondirent: «Nous avons une loi, et, d\'après notre loi, il doit mourir, parce qu\'il s\'est fait Fils de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Quand Pilate eut entendu cette parole, il fut encore plus effrayé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'et, étant rentré dans le prétoire, il dit à Jésus: «D\'où es-tu?» Mais Jésus ne lui fit aucune réponse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Alors Pilate lui dit: «Tu ne me parles pas? Ne sais-tu pas que j\'ai le pouvoir de te crucifier, et que j\'ai le pouvoir de te relâcher?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jésus lui répondit: «Tu n\'aurais aucun pouvoir sur moi, s\'il ne t\'était donné d\'en haut; c\'est pourquoi celui qui me livre entre tes mains est plus coupable que toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Dès ce moment Pilate cherchait à le délivrer; mais les Juifs criaient: «Si tu le relâches, tu n\'es pas ami de César. Quiconque se fait roi, se déclare contre César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Pilate ayant entendu ces paroles, fit conduire Jésus hors du prétoire, et s\'assit sur son tribunal, au lieu appelé le Pavé, en hébreu Gabbatha.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'C\'était la préparation de la Pâque, et environ la sixième heure du jour. Et Pilate dit aux Juifs: «Voilà votre roi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Mais ils se mirent à crier: «A mort! à mort! crucifie-le!» Pilate leur dit: «Crucifierai-je votre roi?» Les principaux sacrificateurs répondirent: «Nous n\'avons d\'autre roi que César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Alors il le leur livra pour être crucifié. Ils prirent donc Jésus et l’emmenèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Jésus portant sa croix, s\'achemina hors de la ville, au lieu nommé la Place du Crâne, en hébreu Golgotha:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'là ils le crucifièrent, et deux autres avec lui, l\'un d\'un côté, l\'autre de l\'autre, et Jésus au milieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilate fit faire aussi, et placer au haut île la croix, un écriteau portant ces mots: Jésus de Nazareth, Roi des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Un grand nombre de Juifs lurent cet écriteau, parce que le lieu où Jésus avait été crucifia était près de la ville, et que l\'inscription était en hébreu, en latin et en grec.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Les principaux sacrificateurs des Juifs dirent à Pilate: «Ne mets pas: Roi des Juifs; mets qu\'il a dit: «Je suis roi des Juifs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilate répondit: «Ce qui est écrit, est écrit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Après avoir crucifié Jésus, les soldats prirent ses vêtements, et en firent quatre parts, une pour chaque soldat. Ils prirent aussi la tunique, et, comme elle était sans couture, d\'un seul tissu depuis le haut jusqu\'en bas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'ils se dirent entre eux: «Ne la déchirons pas, mais tirons au sort à qui l\'aura.» Ainsi firent les soldats; afin que s\'accomplît l\'Écriture, qui dit: «Ils se sont partagé mes habits, et ils ont tiré au sort mon vêtement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Près de la croix, se tenaient la mère de Jésus et la soeur de sa mère, Marie femme de Clopas et Marie Madeleine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Jésus, ayant vu sa mère, et à côté d\'elle le disciple qu\'il aimait, dit à sa mère: «Femme, voilà ton fils;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'puis, il dit au disciple: «Voilà ta mère;» et, dès ce moment, ce disciple la prit chez lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Après cela, Jésus, sachant que tout était déjà consomment, afin que l\'Écriture fût accomplie: «J\'ai soif.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Or il y avait là un vase plein de vinaigre, et les soldats, ayant mis au bout d\'une tige d\'hysope une éponge imbibée de vinaigre, l\'approchèrent de sa bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Quand Jésus eut pris ce vinaigre, il dit: «Tout est consommé;» et, ayant penché la tête, il rendit l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Comme les Juifs craignaient que les corps ne restassent sur la croix pendant le sabbat, car c\'était la préparation, et ce jour de sabbat était très-solennel, ils demandèrent à Pilate qu\'on leur rompît les jambes, et qu\'on les ôtât.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Les soldats vinrent donc, et rompirent les jambes au premier brigand, puis à l\'autre qui avait été crucifié avec lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'ensuite, étant venus à Jésus, et le voyant déjà mort, ils ne lui rompirent pas les jambes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'mais l\'un des soldats lui perça le côté avec sa lance, et aussitôt il en sortit du sang et de l\'eau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Celui qui l\'a vu, en rend témoignage, et son témoignage est digne de foi; et il sait qu\'il dit vrai, afin que vous croyiez aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'En effet, ces choses arrivèrent, afin que l\'Écriture fût accomplie: «Aucun de ses os ne sera brisé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Et un autre passage de l’Écriture dit encore: «Ils regarderont à celui qu’ils ont percé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Après cela, Joseph d\'Arimathée, qui était disciple de Jésus, mais en secret, par crainte des Juifs, demanda à Pilate l\'autorisation de prendre le corps de Jésus, et Pilate la lui accorda. Il vint donc et prit le corps de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Nicodème, le même qui, la première fois, était venu de nuit vers Jésus, vint aussi, apportant environ cent livres d\'un mélange de myrrhe et d’aloès.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Ils prirent donc le corps de Jésus, et le lièrent de bandes en le couvrant d\'aromates, selon la manière d\'ensevelir usitée chez les Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Or, il y avait là, au lieu où Jésus avait été crucifié, un jardin, et dans ce jardin, un sépulcre tout neuf, où personne n\'avait encore été mis:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'c\'est là qu\'ils déposèrent le corps de Jésus, parce que la préparation des Juifs arrivait, et que ce sépulcre était proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Le premier jour de la semaine, Marie Madeleine se rendit au sépulcre, de grand matin, lorsqu\'il faisait encore obscur: elle vit que la pierre en était ôtée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Elle courut donc trouver Simon Pierre, ainsi que l\'autre disciple que Jésus aimait, et leur dit: «On a enlevé du sépulcre le Seigneur, et nous ne savons où on l’a mis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Pierre sortit donc, ainsi que l\'autre disciple, et ils se rendirent au sépulcre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Ils couraient tous deux; mais l\'autre disciple courut plus vite que Pierre, et arriva le premier au sépulcre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'et s\'étant baissé, il vit les bandes qui étaient à terre; cependant, il n\'entra point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Simon Pierre, qui le suivait, arriva à son tour; il entra dans le sépulcre, et vit les bandes qui étaient à terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'et le suaire, dont on avait couvert la tête de Jésus, non point avec les bandes, mais roulé à part dans un coin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Alors cet autre disciple qui était arrivé le premier au sépulcre, y entra aussi: il vit, et il crut;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'car ces disciples ne savaient pas encore que, d\'après l\'Écriture, le Messie devait ressusciter des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Là-dessus, ils s\'en retournèrent chez eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Cependant Marie se tenait près du sépulcre, en dehors, et pleurait. Tout en pleurant, elle se baissa pour regarder dans le sépulcre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'et elle vit deux anges, vêtus de blanc, assis au lieu où avait reposé le corps de Jésus, l\'un à la tête, l\'autre aux pieds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Et ces anges lui dirent: «Femme, pourquoi pleures-tu?» Elle leur répondit: «C\'est qu\'on a enlevé mon Seigneur, et je ne sais où on l’a mis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'En disant ces mots, elle se retourna et vit Jésus qui était là; mais elle ne savait pas que c\'était Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jésus lui dit: «Femme, pourquoi pleures-tu? Qui cherches-tu?» Marie, croyant que c\'était le jardinier, lui dit: «Seigneur, si c\'est toi qui l\'as emporté, dis-moi où tu l\'as mis, et j\'irai le prendre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jésus lui dit: «Marie!» Elle se retourna, et lui dit en hébreu: «Rabboni!» c’est-à-dire, Maître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jésus lui dit: «Ne me touche pas, car je ne suis pas encore monté vers le Père; mais va trouver mes frères, et dis-leur que je monte vers mon Père et votre Père, vers mon Dieu et votre Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marie Madeleine alla annoncer aux disciples qu\'elle avait vu le Seigneur, et qu\'il lui avait dit ces choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Dans la soirée de ce même jour, qui était le premier de la semaine, les portes du lieu où étaient les disciples étant fermées par crainte des Juifs, Jésus vint, et, se présentant au milieu d\'eux, il leur dit: «La paix soit avec vous!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Ayant ainsi parlé, il leur montra ses mains et son côté. Les disciples furent remplis de joie en voyant le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jésus leur dit une seconde fois: «La paix soit avec vous! Comme le Père m\'a envoyé, moi aussi je vous envoie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Après ces paroles, il souffla sur eux, et leur dit: «Recevez le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Ceux à qui vous pardonnerez leurs péchés, ces péchés leur seront pardonnés; ceux à qui vous retiendrez leurs péchés, ces péchés leur seront retenus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Thomas, l\'un des Douze, celui qu\'on appelle Didyme, n\'était pas avec eux, lorsque Jésus vint.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Les autres disciples lui dirent donc: «Nous avons vu le Seigneur.» Mais Thomas leur dit: «Si je ne vois dans ses mains la marque des clous, si je ne mets mon doigt à la place où étaient les clous, et si je ne mets ma main dans son côté, je ne le croirai point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Huit jours après, les disciples se trouvaient de nouveau dans la maison, et Thomas était avec eux. Jésus vint, quoique les, portes fussent fermées, et, se présentant au milieu d\'eux, leur dit: «La paix soit avec vous!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Il dit ensuite à Thomas: «Approche ici ton doigt, et regarde mes mains; approche aussi ta main et la mets dans mon côté; et ne sois pas incrédule, mais crois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas répondit et lui dit: «Mon Seigneur et mon Dieu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jésus lui dit: «Parce que tu m\'as vu, tu as cru: heureux ceux qui croiront sans avoir vu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Jésus a fait, en présence de ses disciples, beaucoup d\'autres miracles qui ne sont pas consignés dans ce livre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'mais ceux-ci ont été rapportés, afin que vous croyiez que Jésus est le Messie, le Fils de Dieu, et qu\'en croyant vous ayez la vie en son nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Après cela, Jésus se montra encore à ses disciples, au bord de la mer de Tibériade, et voici comment il se montra:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simon Pierre, Thomas appelé Didynie, Nathanaël de Cana en Galilée, les fils de Zébédée et deux autres de ses disciples se trouvaient ensemble.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simon Pierre leur dit: «Je vais pêcher.» Ils lui dirent: «Nous y allons aussi avec toi.» Ils sortirent donc et entrèrent dans une barque; mais ils ne prirent rien cette nuit-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Le matin étant venu, Jésus se trouva sur le rivage; cependant les disciples ne savaient pas que c\'était Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jésus leur dit: «Enfants, n\'avez-vous rien à manger?» Ils lui répondirent: «Non.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Il leur dit: «Jetez le filet à droite de la barque, et vous trouverez du poisson.» Ils le jetèrent, et ils ne pouvaient plus le tirer à cause de la grande quantité de poissons qu\'il contenait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Alors le disciple que Jésus aimait dit à Pierre: «C\'est le Seigneur.» Dès que Simon Pierre eut entendu que c\'était le Seigneur, il mit son sarrau et se ceignit, car il était nu, et il se jeta dans l\'eau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Les autres disciples vinrent avec la barque, tirant le filet plein de poissons, car ils n\'étaient éloignés de la terre que d\'environ deux cents coudées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Lorsqu\'ils furent descendus à terre, ils virent sur le sol des charbons allumés, du poisson dessus, et du pain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Jésus leur dit: «Apportez de ces poissons que vous venez de prendre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Pierre entra dans la barque, et tira sur la grève le filet qui était plein de cent cinquante-trois gros poissons; et, quoiqu\'il y en eût tant, le filet ne se rompit point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Jésus leur dit: «Venez et déjeunez.» Mais aucun des disciples n\'osa lui demander: «Qui es-tu?» parce qu\'ils savaient bien que c\'était le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jésus s\'approcha, prit du pain, leur en donna, et du poisson également.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'C\'était la troisième fois déjà que Jésus se montrait à ses disciples depuis qu\'il était ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Après qu\'ils eurent déjeuné, Jésus dit à Simon Pierre: «Simon, fils de Jona, m\'aimes-tu plus que ne font ceux-ci?» Pierre lui répondit: «Oui, Seigneur, tu sais que je t\'aime.» Jésus lui dit: «Pais mes agneaux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Il lui demanda pour la seconde fois: «Simon, fils de Jona, m\'aimes-tu?» Pierre lui répondit: «Oui, Seigneur, tu sais que je t\'aime.» Jésus lui dit: «Pais mes brebis.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Il lui demanda pour la troisième fois: «Simon, fils de Jona, m\'aimes-tu?» Pierre fut affligé de ce qu\'il lui demandait pour la troisième fois, «m\'aimes-tu?» et il lui répondit: «Seigneur, tu sais toutes choses, tu sais bien que je t\'aime.» Jésus lui dit: «Pais mes chères brebis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'En vérité, en vérité, je te le dis, quand tu étais jeune, tu te ceignais toi-même, et tu allais où tu voulais; quand tu seras vieux, tu étendras les bras, et un autre te ceindra, et t\'entraînera là où tu ne voudras pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Or il dit cela pour indiquer de quelle mort Pierre devait glorifier Dieu. Puis il ajouta: «Suis-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pierre s\'étant retourné, vit venir derrière eux le disciple que Jésus aimait, celui qui, pendant le souper, s\'était penché sur le sein de Jésus, et lui avait dit: «Seigneur, qui est celui qui te livre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Pierre donc le voyant, dit à Jésus: «Et celui-ci, Seigneur, que deviendra-t-il?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jésus lui dit: «Si je veux qu\'il demeure jusqu’à ce que je vienne, que t\'importe? Pour toi, suis-moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Le bruit se répandit donc parmi les frères, que ce disciple ne mourrait pas. Pourtant Jésus ne lui avait pas dit qu\'il ne mourrait pas, mais il avait dit: «Si je veux qu\'il demeure jusqu’à ce que je vienne, que t\'importe?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'C\'est ce même disciple qui atteste ces faits, et qui les a écrits; et nous savons que son témoignage est véritable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Jésus a fait encore beaucoup d\'autres choses: si on les rapportait en détail, je ne pense pas que le monde même pût contenir les livres qu\'on en écrirait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Théophile, j\'ai raconté dans mon premier livre tout ce que Jésus a fait et enseigné dès le commencement');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'jusqu\'au jour où il fut enlevé de ce monde, après avoir, par le Saint-Esprit, donné ses ordres à ceux qu\'il avait choisis pour apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Il s\'était aussi montré à eux, après qu\'il eut souffert, et leur avait donné plusieurs preuves de sa résurrection, pendant quarante jours qu\'il leur apparut et les entretint de ce qui a trait au royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Un jour qu\'il se trouvait avec eux, il leur recommanda de ne pas s\'éloigner de Jérusalem, mais d\'y attendre l\'accomplissement de la promesse du Père, «dont je vous ai parlé, leur dit-il,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'car Jean a baptisé d\'eau, mais vous, vous serez baptisés d\'esprit saint dans peu de jours.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Eux donc, s\'étant rapprochés, lui demandèrent: «Seigneur, est-ce en ce temps que tu dois rétablir le royaume pour Israël?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Il leur dit: «Il ne vous appartient pas de connaître les temps ni les moments que Dieu a déterminés de sa propre autorité, mais quand le Saint-Esprit sera venu sur vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'vous serez revêtus de force, et vous serez mes témoins à Jérusalem, dans toute la Judée, dans la Samarie et jusqu\'au bout du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'En disant ces mots, il fut élevé en leur présence, et une nuée le déroba à leurs yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Comme leurs regards restaient fixés vers le ciel, pendant qu\'il s\'en allait, deux hommes vêtus de blanc se présentèrent à eux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'et leur dirent: «Galiléens, pourquoi vous arrêtez-vous à regarder au ciel? Ce Jésus qui a été enlevé d\'avec vous au ciel, en viendra de la même manière que vous l\'y avez vu monter.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Alors ils revinrent de la montagne appelée Bois d\'oliviers, à Jérusalem, qui n\'en est éloignée que de la distance d\'un sabbat.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'De retour à la ville, ils montèrent dans la chambre haute où se tenaient d\'ordinaire Pierre, Jean, Jacques, André, Philippe et Thomas, Barthélemi et Matthieu, Jacques, fils d\'Alphée, et Simon le zélateur, et Jude, fils de Jacques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ils étaient tous constamment en prière, tous ensemble, avec quelques femmes, notamment Marie, mère de Jésus, et avec les frères de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'En ces jours-là, Pierre se leva au milieu des disciples (la réunion était nombreuse, d\'environ cent vingt personnes) et il leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '«Frères, il fallait que s\'accomplît la parole que le Saint-Esprit a jadis prononcée par la bouche de David, au sujet de Judas, le guide de ceux qui ont arrêté Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'car il était compté parmi nous, et il avait part à notre ministère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(Ce misérable, après avoir acheté un fonds de terre avec le salaire de son crime, est tombé la tête la première; il s\'est ouvert le ventre et toutes ses entrailles sont sorties.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Ce fait est si connu de tous les habitants de Jérusalem, que ce terrain a été appelé dans leur langue Akeldama, c’est-à-dire, la Place du Sang.)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, '«En effet, il est écrit dans le livre des Psaumes: «Que sa demeure soit déserte, que celui qui l\'habite, ne l\'occupe pas,» et «qu’un autre prenne sa charge.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'En conséquence, il faut que l\'un de ceux qui nous ont accompagnés pendant tout le temps que le Seigneur Jésus a vécu avec nous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'depuis le baptême de Jean jusqu\'au jour où il nous a été enlevé, se joigne à nous comme témoin de sa résurrection.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Il s\'en présenta deux: Joseph appelé Barsabas, surnommé Juste, et Matthias.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Alors les disciples firent cette prière: «Seigneur, toi qui connais les coeurs de tous, montre-nous lequel de ces deux tu as choisi');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'pour occuper, dans ce ministère de l\'apostolat, la place que Judas a laissée, pour aller en son lieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Puis on tira au sort: le sort tomba sur Matthias, et l\'on vota son adjonction aux onze Apôtres.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Le jour de la Pentecôte, ils étaient tous ensemble en un même lieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'lorsque tout à coup il se fit du ciel un bruit semblable à celui d\'un violent coup de vent: ce bruit remplit toute la maison où ils étaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'En même temps ils virent comme des langues de feu, qui se divisèrent et se posèrent sur chacun d\'eux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'ils furent tous remplis du Saint-Esprit, et se mirent à parler des langues étrangères, selon que l\'Esprit leur donnait de s\'exprimer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Or il y avait en séjour à Jérusalem, des Juifs, hommes pieux de toutes les nations qui sont sous le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'A ce bruit, ils accoururent en foule, et chacun fut confondu de les entendre parler sa propre langue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Surpris et tout étonnés, ils disaient: «Eh! ces gens qui parlent ne sont-ils pas tous Galiléens?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Comment se fait-il que chacun de nous les entende parler la langue de son pays?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Nous tous, Parthes, Mèdes, Élamites, habitants de la Mésopotamie, de la Judée et de la Cappadoce, du Pont et de l\'Asie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'de la Phrygie et de la Pamphylie, de l\'Egypte et des districts de la Libye voisine de Cyrène, et Romains, Juifs et prosélytes en passage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Crétois et Arabes, nous les entendons célébrer en nos langues les merveilles que Dieu a faites.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Ils étaient tous surpris, et, ne sachant que penser, ils se disaient les uns aux autres: «Qu\'est-ce que cela pourrait bien être?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Toutefois d\'autres se moquaient, et disaient: «Ils sont pleins de vin doux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Pierre se présentant avec les Onze, éleva la voix, et leur adressa ces mots: «Juifs, et vous tous qui êtes en séjour à Jérusalem, retenez bien ceci, et prêtez l\'oreille à mes paroles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Ces gens ne sont point ivres, comme vous le supposez, car c\'est la troisième heure du jour;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'mais vous voyez l\'accomplissement de ce qui a été dit par le prophète Joël:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '«Dans les derniers temps, dit Dieu, je répandrai mon Esprit sur toute chair: vos fils et vos filles prophétiseront; vos jeunes gens auront des visions, et vos vieillards auront des songes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Ce sera, du moins, sur mes serviteurs et sur mes servantes qu’à cette époque-là je répandrai mon Esprit; et ils prophétiseront.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Je ferai paraître des prodiges en haut dans le ciel, et des miracles en bas sur la terre, du sang, du feu et une épaisse fumée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Le soleil sera changé en ténèbres, et la lune, en sang, avant que vienne la grande et éclatante journée du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Alors quiconque invoquera le nom du Seigneur, sera sauvé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, '«Israélites, écoutez ce que je vais vous dire: Un homme a été marqué de Dieu, en vue de vous, par les miracles, les prodiges et les signes que Dieu a opérés par lui, au milieu de vous, comme vous le savez vous-mêmes: c\'est Jésus de Nazareth.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Cet homme, qui a été livré selon le plan déterminé et la prescience de Dieu, vous l\'avez mis à mort par la main des impies, en le clouant au bois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Eh bien! Dieu l’a ressuscité en le délivrant des étreintes de la mort, attendu qu\'il n\'était pas possible qu\'elle le tînt en sa puissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'En effet, David dit de lui: «J\'avais continuellement le Seigneur devant les yeux, car il est à ma droite, pour que je ne sois pas ébranlé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Aussi mon coeur a-t\'il été dans la joie et ma langue dans l’allégresse; bien plus, ma chair reposera avec espérance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'parce que tu n\'abandonneras pas mon âme dans le séjour des morts, tu ne permettras pas même que ton Saint voie la corruption.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu m\'as fait connaître les sentiers de la vie; tu me rempliras de joie par ta présence.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Frères, qu\'il me soit permis de vous dire en toute franchise, que, pour le patriarche David, il est mort, il a été enseveli, et son tombeau existe encore aujourd\'hui chez nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Comme il était prophète et qu\'il savait que Dieu lui avait promis avec serment d\'asseoir sur son trône quelqu\'un de ses descendants,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'il prévit la résurrection du Messie, et dit «qu\'il ne serait point abandonné dans le séjour des morts, et que sa chair ne verrait pas la corruption.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Eh bien! ce Messie, c\'est ce Jésus que Dieu a ressuscité, comme nous en sommes tous témoins:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'il a été élevé à la droite de Dieu, et ayant reçu du Père le Saint-Esprit qu\'il avait promis, il l\'a répandu. C\'est ce que vous voyez et entendez;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'car David n\'est point monté au ciel, mais il dit lui-même: «Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'jusqu’à ce que j’aie fait de tes ennemis ton marche-pied.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Que toute la maison d\'Israël tienne donc pour certain, que Dieu a fait Seigneur et Messie, ce Jésus que vous avez crucifié.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Le coeur brisé par ce discours, ils dirent à Pierre et aux autres apôtres: «Frères, que ferons-nous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Pierre leur dit: «Repentez-vous, et que chacun de vous soit baptisé au nom de Jésus-Christ, pour obtenir le pardon de ses péchés; et vous recevrez le don du Saint-Esprit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'car la promesse est pour vous, pour vos enfants, et pour tous ceux qui sont au loin, en aussi grand nombre que le Seigneur notre Dieu les appellera.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Il les pressa encore par beaucoup d\'autres paroles, et les exhorta en disant: «Retirez-vous de cette génération perverse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Ceux qui agréèrent sa parole, reçurent le baptême, et environ trois mille personnes furent admises en ce jour-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Ils étaient assidus à l’instruction des apôtres et aux réunions communes, à la fraction du pain et aux prières.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'La crainte était dans toutes les âmes; et il se faisait un grand nombre de prodiges et de miracles par les apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Tous les croyants se réunissaient entre eux, et avaient tout en commun:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'ils vendaient leurs propriétés et leurs biens, et en partageaient le produit entre tous, selon que quelqu\'un d\'entre eux en avait besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Chaque jour, ils se trouvaient régulièrement, tous ensemble dans le temple, et, rompant le pain à la maison, ils prenaient leur nourriture avec joie et simplicité de coeur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'louant Dieu et trouvant faveur auprès de tout le peuple. Le Seigneur ajoutait chaque jour à l\'église ceux qui étaient sauvés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Pierre et Jean montaient ensemble au temple, à l\'heure de la prière: c\'était la neuvième heure du jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Il y avait à la porte du temple, appelée la Belle Porte, un homme boiteux de naissance qui s\'y faisait transporter et poser chaque jour, pour demander l\'aumône à ceux qui entraient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Cet homme voyant Pierre et Jean qui allaient entrer dans le temple, leur demanda l\'aumône.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Pierre ayant fixé les yeux sur lui, ainsi que Jean, dit: «Regarde-nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Il les regarda attentivement, s\'attendant à recevoir d\'eux quelque chose.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Mais Pierre lui dit: «Je n\'ai ni argent, ni or; mais ce que j\'ai, je te le donne: au nom de Jésus-Christ de Nazareth, lève-toi et marche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Et l\'ayant pris par la main droite, il le fit lever. A l\'instant, les plantes et les chevilles de ses pieds furent affermies;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'il se leva d\'un saut, se tint debout, et marcha; puis il entra avec eux dans le temple, marchant, sautant, et louant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Tout le peuple le vit marcher et louer Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Ils reconnurent que c\'était lui qui était assis à la Belle Porte du temple pour demander l\'aumône, et ils furent remplis de surprise et d\'étonnement de ce qui lui était arrivé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Comme cet homme ne quittait pas Pierre et Jean, tout le peuple accourut vers eux au portique appelé Portique de Salomon: la foule était en stupéfaction.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'A cette vue, Pierre dit au peuple: «Israélites, pourquoi cet homme est-il pour vous un sujet d\'étonnement? pourquoi tenez-vous les yeux fixés sur nous, comme si c\'était par notre propre puissance ou par notre piété que nous l\'eussions fait marcher?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Le Dieu d\'Abraham, d\'Isaac et de Jacob, le Dieu de nos pères a glorifié son serviteur Jésus, que vous avez livré et renié devant Pilate, qui penchait pour qu\'on le relâchât;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'mais vous, vous avez renié le Saint et le Juste, et vous avez sollicité la grâce d\'un meurtrier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Vous avez fait mourir l\'auteur de la vie, que Dieu a ressuscité des morts, comme nous en sommes témoins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'C\'est par la foi en son nom que ce nom a affermi l\'homme que vous voyez et que vous connaissez, et c\'est la foi, dont nous lui sommes redevables, qui a donné à cet impotent cette complète guérison, en présence de vous tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Je sais bien, frères, que vous avez agi par ignorance, aussi bien que vos magistrats;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'mais Dieu a accompli de la sorte ce qu\'il avait annoncé par la bouche de tous ses prophètes, que son Oint devait souffrir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Repentez-vous donc, et vous convertissez, pour que vos péchés soient effacés, afin que les temps de rafraîchissement viennent de la part du Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'et qu\'il envoie celui dont il a disposé pour vous, Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'que le ciel doit recevoir jusqu’à l\'époque de la restauration universelle, dont Dieu a parlé de toute ancienneté par la bouche de ses saints prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Moïse a dit: «Le Seigneur votre Dieu vous suscitera d\'entre vos frères un prophète comme moi; vous l’écouterez dans tout ce qu’il vous dira.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Quiconque n\'écoutera pas ce prophète sera retranché du milieu du peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Puis, depuis Samuel et successivement, tous les prophètes qui ont parlé, ont aussi annoncé ces temps-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vous êtes, vous, les fils des prophètes et de l’alliance que Dieu a traitée avec nos pères, en disant à Abraham: «Toutes les familles de la terre seront bénies en ta postérité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'C\'est à vous, tout d\'abord, que Dieu; après avoir suscité son Serviteur, l\'a envoyé pour vous bénir, et détourner chacun de vous de ses iniquités.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Comme Pierre et Jean haranguaient la foule, survinrent les sacrificateurs, le commandant du temple et les sadducéens,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'fatigués de ce qu\'ils enseignaient le peuple et annonçaient, en la personne de Jésus, la résurrection des morts:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'ils les arrêtèrent et les mirent en prison jusqu\'au lendemain, car c\'était déjà le soir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Toutefois un grand nombre de ceux qui avaient entendu ce discours, crurent, en sorte que le nombre des hommes s\'éleva à environ cinq mille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Le lendemain, les magistrats des Juifs, soit anciens, soit scribes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'et notamment Anne souverain sacrificateur, Caïphe, Jean, Alexandre, et tous ceux qui étaient de la famille des souverains sacrificateurs, s\'assemblèrent à Jérusalem,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'et ayant fait comparaître les apôtres devant eux, ils leur demandèrent: «Par quelle puissance, ou au nom de qui avez-vous fait cela?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Alors Pierre, rempli de l\'Esprit saint, leur dit: «Magistrats du peuple, et Anciens d\'Israël,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'puisqu\'on nous interroge aujourd\'hui à l\'occasion d\'un bienfait accordé à un infirme, et qu\'on nous demande par quoi cet homme a été guéri,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'sachez bien, vous tous, et que tout le peuple d\'Israël le sache aussi, que c\'est par le nom de Jésus-Christ de Nazareth, que vous avez crucifié, mais que Dieu a ressuscité des morts: c\'est par lui que cet homme se présente devant vous, guéri.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Jésus est «la pierre que vous, constructeurs, vous avez mise au rebut, mais qui est devenue la pierre angulaire;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'et il n’y a point de salut en aucun autre, car il n\'y a sous le ciel, parmi les hommes, aucun autre nom qui ait été donné, par lequel nous devions être sauvés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Les sénateurs furent étonnés de voir l\'assurance de Pierre et de Jean, d\'autant qu\'ils s\'aperçurent que c\'étaient des hommes du peuple sans instruction. Ils les reconnurent pour avoir été avec Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'et, comme ils voyaient là, avec eux, l\'homme qui avait été guéri, ils n\'avaient rien à répondre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Après les avoir fait sortir du sanhédrin, ils discutèrent entre eux, disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, '«Que ferons-nous à ces hommes? Qu\'ils aient fait un miracle insigne, c\'est ce que tous les habitants de Jérusalem peuvent voir, et nous ne pouvons le nier;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'mais afin que cela ne se divulgue pas davantage, défendons-leur avec menaces de parler désormais à qui que ce soit en ce nom-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Et les ayant rappelés, ils leur interdirent absolument de parler et d\'enseigner au nom de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mais Pierre et Jean leur répondirent: «Jugez, s\'il est juste devant Dieu, de vous écouter, plutôt que Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Pour nous, nous ne pouvons pas ne pas dire ce que nous avons vu et entendu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Ils les renvoyèrent avec de nouvelles menaces, ne sachant comment les punir, à cause du peuple, parce que tout le monde glorifiait Dieu de ce qui était arrivé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'En effet, l\'homme qui avait été miraculeusement guéri, avait plus de quarante ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Dès qu\'on les eut relâchés, ils se rendirent auprès des leurs, et rapportèrent tout ce que les souverains sacrificateurs et les anciens leur avaient dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Après les avoir entendus, les frères élevèrent tous ensemble la voix vers Dieu, et dirent: «Souverain Maître, tu es le Dieu qui a fait le ciel, la terre, la mer et tout ce qu\'ils renferment,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'c\'est toi qui as dit par la bouche de David ton serviteur: Pourquoi les nations ont-elles frémi de colère, et les peuples ont-ils formé de vains projets?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Les rois de la terre se sont insurgés, et les magistrats se sont ligués contre le Seigneur et contre son Oint.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'En effet, Hérode et Ponce-Pilate se sont véritablement ligués, dans cette ville-ci, avec les nations et avec les peuples d\'Israël contre ton serviteur Jésus, ton Oint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'pour faire tout ce que ta main et ton conseil avaient arrêté;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'eh bien! maintenant vois leurs menaces, et donne à tes serviteurs d\'annoncer ta parole avec pleine assurance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'en étendant ta main, pour qu\'il s\'opère des guérisons, et qu\'il se fasse des miracles et des prodiges, par le nom de ton saint serviteur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'A peine eurent-ils prié, que le lieu où ils étaient réunis trembla: ils furent tous remplis du Saint-Esprit, et ils annoncèrent la parole de Dieu avec assurance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'La multitude des croyants n\'était qu\'un coeur et qu\'une âme. Personne ne disait que ce qu\'il possédait était à lui en propre, mais tout était commun entre eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Les apôtres rendaient témoignage avec beaucoup de force de la résurrection du Seigneur Jésus, et une grande grâce était répandue sur eux tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'car nul parmi eux n\'était dans le besoin. Tous ceux qui se trouvaient possesseurs de terres ou de maisons, les vendaient, en apportaient le prix,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'et le déposaient aux pieds des apôtres. Et l\'on donnait à chacun selon le besoin qu\'il en avait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Joses, surnommé par les apôtres Barnabas, c’est-à-dire, fils d\'exhortation, lévite originaire de Chypre, possédait un champ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'il le vendit, en apporta l\'argent, et le déposa aux pieds des apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Un homme nommé Ananias, avec Saphira sa femme, vendit une propriété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'et ayant, de concert avec elle, détourné quelque chose du prix, il en apporta une partie, et la déposa aux pieds des apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Mais Pierre lui dit: «Ananias, pourquoi Satan a-t-il rempli ton coeur, que tu mentes au Saint-Esprit, et que tu aies détourné quelque chose du prix de ce fonds?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'S\'il demeurait sans être vendu, ne restait-il pas ta propriété? Et, après l\'avoir vendu, n\'étais-tu pas le maître de disposer du prix? Comment as-tu bien pu concevoir un pareil dessein? Tu as menti, non aux hommes, mais à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'En entendant ces paroles, Ananias tomba, et expira. Tous les auditeurs furent saisis d\'une grande crainte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Les plus jeunes s\'étant levés l\'arrangèrent et l\'emportèrent pour l\'enterrer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Environ trois heures après, sa femme entra, sans rien savoir de ce qui s\'était passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Pierre lui adressa la parole: «Dis-moi si vous avez vendu le fonds tant?» Elle dit: «Oui, tant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Pierre lui dit: «Comment avez-vous bien pu vous entendre pour tenter l\'Esprit du Seigneur? Voici, les pieds de ceux qui ont enterré ton mari sont à la porte... et ils t\'emporteront»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Au même instant, elle tomba à ses pieds, et expira. Les jeunes gens, en entrant, la trouvèrent morte, ils l\'emportèrent et l\'enterrèrent auprès de son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Cet événement répandit une grande crainte dans toute l\'assemblée, et parmi tous ceux qui en entendirent parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Les apôtres faisaient beaucoup de miracles et de prodiges parmi le peuple, et les disciples étaient tous ensemble dans le portique de Salomon;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'aucune autre personne n\'osait se joindre à eux, mais le peuple les exaltait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Des croyants toujours plus nombreux, des multitudes d\'hommes et de femmes, s\'attachaient au Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'en sorte qu\'on apportait les malades dans les rues et qu\'on les plaçait sur de petits lits et sur des couchettes, afin que, lorsque Pierre passerait, son ombre au moins couvrit quelqu\'un d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'On venait aussi en foule des villes d\'alentour à Jérusalem; on y apportait des malades et des gens tourmentés par des esprits impurs, et tous étaient guéris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Le souverain sacrificateur et tous ses adhérents, qui forment le parti des sadducéens, étaient pleins de haine contre les apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'Ils les firent arrêter et les jetèrent dans une prison publique;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'mais un ange du Seigneur ouvrit pendant la nuit les portes de la prison, les fit sortir, et leur dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '«Allez, tenez-vous dans le temple, et enseignez au peuple toute la parole de vie:»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'ce qu\'ayant entendu, ils entrèrent vers le point du jour dans le temple, et se mirent à enseigner. Cependant le souverain sacrificateur et ses adhérents s\'étant réunis, convoquèrent le sanhédrin et tout le collège des anciens des fils d\'Israël, et ils envoyèrent à la prison pour qu\'on amenât les apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Les agents s\'y étant rendus, ne les y trouvèrent point, et revinrent faire leur rapport,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'disant: «Nous avons trouvé la prison très-bien fermée et les sentinelles aux portes, mais, après avoir ouvert, nous n\'avons trouvé personne dedans.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Cette nouvelle jeta le souverain sacrificateur, le commandant du temple et les principaux sacrificateurs dans la perplexité au sujet des prisonniers: ils ne savaient ce que ce pouvait être.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Cependant on vint leur dire: «Voici, les hommes que vous aviez mis en prison, sont dans le temple, et ils enseignent le peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Alors le commandant partit avec ses agents, et les amena, mais sans employer la force, pour ne pas être lapidés, car ils craignaient le peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Après les avoir amenés ils les introduisirent dans le sanhédrin, et le souverain sacrificateur les interrogea, disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, '«Nous vous avons formellement défendu d\'enseigner en ce nom-là, et voici, vous avez rempli Jérusalem de votre enseignement, et vous voulez faire retomber sur nous le sang de cet homme.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Pierre et les autres apôtres répondirent: «On doit obéir à Dieu plutôt qu\'aux hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Le Dieu de nos pères a ressuscité Jésus, que vous avez tué en le pendant au bois;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'il l’a élevé à sa droite, en qualité de Chef et Sauveur, pour donner à Israël la repentance et le pardon des péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Nous sommes nous-mêmes ses témoins, les témoins de ce que nous avançons, et le Saint-Esprit que Dieu a donné à ceux qui lui obéissent, en est témoin avec nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Exaspérés de ce qu\'ils venaient d\'entendre, les sénateurs étaient d\'avis de les faire mourir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'quand un pharisien, nommé Gamaliel, docteur de la Loi fort considéré de tout le peuple, ordonna de faire sortir un instant ces gens,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'puis il dit: «Israélites, prenez bien garde à ce que vous allez faire à ces hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Il n\'y a pas longtemps que parut Theudas; il se donnait pour un grand personnage, et environ quatre cents hommes se rallièrent à lui: il a été mis à mort, et tous ceux qui l\'avaient suivi ont été défaits et réduits à rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Plus tard, à l\'époque du dénombrement, s\'éleva Judas le Galiléen qui entraîna du monde après lui: il a péri aussi, et tous ceux qui l\'avaient suivi ont été dispersés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Maintenant, je vous le dis, ne vous commettez pas avec ces gens et laissez-les tranquilles. Si cette idée, ou cette oeuvre vient des hommes, elle se détruira;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'mais si elle vient de Dieu, vous ne pourrez détruire ces gens. Prenez garde que vous ne vous trouviez aussi avoir fait la guerre à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Ils se rangèrent à son avis. Ayant rappelé les apôtres, ils leur défendirent, après les avoir fait battre de verges, de parler au nom de Jésus, et ils les relâchèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Pour eux, ils se retirèrent joyeux de devant le sanhédrin, parce qu\'ils avaient été jugés dignes de souffrir des opprobres pour ce nom;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'et ils ne cessèrent chaque jour, dans le temple et à la maison, d\'enseigner et d\'annoncer que Jésus est le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'En ce temps-là, le nombre des disciples s\'étant accru, les hellénistes élevèrent des plaintes contre les hébreux, parce que leurs veuves étaient négligées dans l\'assistance journalière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Les Douze ayant convoqué la multitude des disciples, dirent: «Il ne convient pas que nous abandonnions la prédication de la parole de Dieu pour servir aux tables;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'cherchez donc parmi vous, frères, sept hommes de bon renom, pleins d\'esprit et de sagesse, que nous préposerons à cet emploi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'tandis que nous continuerons de vaquer à la prière et au ministère de la Parole.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Cette proposition plut à toute l\'assemblée, et l\'on élut Etienne, homme plein de foi et d\'Esprit saint, Philippe, Prochore, Nicanor, Timon, Parménas, et Nicolas, prosélyte d\'Antioche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'on les présenta aux apôtres, qui, après avoir prié, leur imposèrent les mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'La parole de Dieu se répandait de plus en plus, et le nombre des disciples s\'augmentait considérablement à Jérusalem: une multitude de sacrificateurs embrassaient la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Etienne, plein de grâce et de force, faisait des prodiges et de grands miracles parmi le peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Quelques Juifs de la synagogue dite des Affranchis, de celle des Cyrénéens et de celle des Alexandrins, ainsi que des Juifs venus de Cilicie et d\'Asie étant entrés en dispute avec lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'ne purent résister à la sagesse et à l\'esprit avec lesquels il parlait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Alors ils subornèrent des gens qui dirent: «Nous l\'avons entendu tenir des propos blasphématoires contre Moïse et contre Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Ils ameutèrent le peuple, ainsi que les anciens et les scribes, puis, se jetant sur lui, ils l\'entraînèrent et l\'emmenèrent au sanhédrin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Ils produisirent de faux témoins qui dirent: «Cet homme ne cesse de tenir des propos contre le lieu saint et contre la Loi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'nous l’avons entendu dire que Jésus, ce Nazaréen, détruira ce lieu, et changera les institutions que Moïse nous a données.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Et comme tous les membres du sanhédrin avaient les yeux fixés sur lui, son vidage leur parut comme celui d\'un ange.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Le souverain sacrificateur lui demanda si ce dont on l\'accusait était véritable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Etienne répondit: «Mes frères et mes pères, écoutez: Le Dieu de gloire apparut à notre père Abraham, lorsqu\'il était en Mésopotamie, avant qu\'il s\'établit à Charran, et lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, '«Quitte ton pays et ta famille, et rends-toi dans le pays que je t\'indiquerai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Alors Abraham sortit du pays des Chaldéens, et s\'établit à Charran. De là, après la mort de son père, Dieu le fit émigrer dans le pays que vous habitez maintenant;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'il ne lui donna point de propriété dans ce pays, pas même un pouce de terre, mais il lui promit, à une époque où le patriarche n\'avait point d\'enfants, de le lui donner en possession, à lui, et à sa postérité après lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Dieu parla ainsi: «Sa postérité habitera en terre étrangère; on la réduira en servitude et on la maltraitera pendant quatre cents ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Mais moi, dit Dieu, je jugerai la nation à laquelle ses descendant auront été assujettis; après cela, ils quitteront ce pays, et me rendront leur culte dans ce lieu-ci;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'puis il donna à Abraham l\'alliance de la circoncision. C\'est dans ces circonstances qu\'Abraham eut Isaac, qu\'il circoncit le huitième jour; Isaac eut Jacob; Jacob, les douze patriarches.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Les patriarches, jaloux de Joseph, le vendirent pour l\'Egypte; mais Dieu était avec lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'il le tira de toutes ses peines, et lui donna de plaire par sa sagesse à Pharaon, roi d\'Egypte, de sorte que ce prince le mit à la tête du royaume et de toute sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Or il survint une famine dans tout le pays d\'Egypte et dans celui de Canaan; la détresse était grande, et nos pères ne trouvaient pas de nourriture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Jacob ayant appris qu\'il y avait des vivres en Egypte, y envoya nos pères une première fois;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'puis, au second voyage, Joseph fut reconnu par ses frères, et Pharaon sut quelle était l\'origine de Joseph.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Joseph envoya chercher Jacob son père et toute sa famille, qui se montait à soixante et quinze personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Jacob descendit en Egypte, où il mourut, ainsi que nos pères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'et leurs corps furent transportés à Sichem, et déposés dans le sépulcre qu\'Abraham avait acheté à prix d\'argent des fils d\'Hémor, père de Sichem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, '«A mesure que s\'approchait le temps où devait s\'accomplir la promesse que Dieu avait faite à Abraham, le peuple s\'accroissait et se multipliait en Egypte,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'jusqu’à l\'époque où s\'éleva un autre roi, qui ne savait rien de Joseph.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ce prince, usant d\'artifice contre notre race, maltraita nos pères et les contraignit d\'exposer leurs nouveau-nés, afin qu\'ils ne vécussent pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'C\'est en ce temps que naquit Moïse, qui était d\'une divine beauté. Il fut nourri trois mois dans la maison de son père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'mais, ayant été exposé, la fille de Pharaon le recueillit, et l\'éleva pour en faire son fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Moïse fut instruit de toute la science des Égyptiens; il était puissant en paroles et en oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Quand il eut atteint l\'âge de quarante ans, il eut l\'idée de visiter ses frères, les fils d\'Israël,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'et, en ayant vu un qu\'on maltraitait, il prit sa défense, et vengea l\'opprimé en frappant l\'Égyptien:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'il pensait que ses frères comprendraient que Dieu se servait de lui pour les délivrer, mais ils ne le comprirent point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Le lendemain, il s\'approcha de deux d\'entre eux qui se battaient, et les engagea à faire la paix, en disant: «Hommes, vous êtes frères, pourquoi vous maltraitez-vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Mais celui qui maltraitait son compatriote le repoussa, en disant: «Qui t’a établi chef et juge sur nous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Veux-tu me tuer, comme tu as tué hier l’Egyptien?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Cette parole fut cause que Moïse s\'enfuit, et alla habiter dans le pays de Madian, où il eut deux fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, '«Quarante ans s\'étaient écoulés, lorsqu\'un ange lui apparut au désert du mont Sinaï, dans la flamme d\'un buisson ardent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Comme Moïse s\'étonnait de ce phénomène, et s\'approchait pour le considérer, la voix du Seigneur se fit entendre:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '«Je suis le Dieu de tes pères, le Dieu d\'Abraham, d’Isaac et de Jacob.» Et Moïse tremblant n\'osait regarder.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Le Seigneur lui dit: «Ote tes souliers de tes pieds, car le lieu que tu foules est une terre sainte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'J\'ai vu de mes yeux l’oppression de mon peuple en Egypte: j’ai entendu ses gémissements, et je suis descendu pour le délivrer. Viens donc, que je t\'envoie en Egypte.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ce Moïse qu\'ils avaient renié en disant: «Qui t’a établi chef et juge?» c\'est lui que Dieu a envoyé pour chef et libérateur, avec l\'assistance de l\'ange qui lui était apparu dans le buisson;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'c\'est lui qui les a délivrés, en faisant des prodiges et des miracles sur la terre d\'Egypte, sur la mer Rouge et au désert, pendant quarante ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'C\'est ce Moïse qui a dit aux fils d\'Israël: «Dieu vous suscitera d\'entre vos frères un prophète comme moi;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'c\'est lui, qui, lors de l\'assemblée au désert, servit d\'intermédiaire entre l\'ange, qui lui parlait sur le mont Sinaï, et nos pères, en recevant les vivants oracles, pour nous les transmettre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Nos pères, loin de vouloir lui obéir, le repoussèrent et tournèrent leur coeur vers l\'Egypte,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'en disant à Aaron: «Fais-nous des dieux qui marchent devant nous; car pour ce Moïse qui nous a fait sortir du pays d\'Egypte, nous ne savons ce qui lui est arrivé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Ils fabriquèrent alors un veau, puis ils offrirent un sacrifice à l\'idole, et se réjouirent de l\'oeuvre de leurs mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Dieu, de son côté, se détourna d\'eux, et les livra au culte de l\'armée du ciel, ainsi qu\'il est écrit au livre des Prophètes: «M\'avez-vous offert des victimes et des sacrifices pendant quarante ans au désert, ô maison d\'Israël?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, '— Vous avez porté le tabernacle de Moloch et l\'astre du Dieu Rephan, ces idoles que vous avez fabriquées pour les adorer: aussi vous transporterai-je au delà de Babylone.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Le tabernacle du témoignage était pour nos ancêtres au désert, comme l\'avait enjoint celui qui dit à Moïse de le construire sur le modèle qu\'il avait vu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'C\'est ce tabernacle que nos pères reçurent à leur tour, et qu\'ils apportèrent sous la conduite de Josué, lorsqu\'ils firent la conquête du pays sur les nations que Dieu chassa de devant eux, et il subsista jusqu\'au temps de David.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Ce prince, qui avait trouvé grâce devant Dieu, demanda d\'élever un tabernacle au Dieu de Jacob;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'néanmoins ce fut Salomon qui lui bâtit un temple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Mais le Très-Haut n\'habite point dans des constructions de main d\'homme, comme le prophète le dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '«Le ciel est mon trône, la terre, mon marchepied. Quelle maison me bâtirez-vous, dit le Seigneur, et quel sera le lieu de mon repos?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'N’est-ce pas ma main qui a fait toutes ces choses?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, '«Hommes de col roide et incirconcis de coeur et d\'oreilles, vous vous opposez toujours au Saint-Esprit, oui vous, comme vos pères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Lequel des prophètes vos pères n\'ont-ils pas persécuté? Ils ont même tué ceux qui ont annoncé la venue du Juste, et vous, aujourd\'hui, vous l\'avez trahi et vous avez été ses meurtriers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Vous qui avez reçu la Loi sur les ordres des anges, et qui ne l\'avez point gardée...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Ces paroles transportèrent leur coeur de rage; ils grincèrent des dents contre lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mais Etienne, animé de l\'Esprit saint, tourna les yeux au ciel; il vit la gloire de Dieu, et Jésus debout à sa droite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'et il dit: «Voici, je vois les cieux ouverts, et le Fils de l\'homme debout à la droite de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Alors les Juifs, poussant de grands cris, se bouchèrent les oreilles; et ils se jetèrent tous ensemble sur lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'l\'entraînèrent hors de la ville, et le lapidèrent. Les témoins avaient posé leurs manteaux aux pieds d\'un jeune homme nommé Saul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Pendant qu\'ils lapidaient Etienne, celui-ci priait, et disait: «Seigneur Jésus, reçois mon esprit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Et s\'étant mis à genoux, il s\'écria à haute voix: «Seigneur, ne leur impute point ce péché;» et, en disant ces mots, il s\'endormit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saul applaudissait à ce meurtre. Le même jour, une violente persécution éclata sur l\'église de Jérusalem; tous les fidèles, excepté les apôtres, se dispersèrent dans les campagnes de la Judée et de la Samarie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Toutefois des hommes religieux enterrèrent Etienne en faisant de grandes lamentations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saul désolait l\'église; il pénétrait dans les maisons, en arrachait les hommes et les femmes, et les faisait jeter en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Ceux donc qui étaient dispersés, s\'en allèrent de lieu en lieu annonçant la Parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Philippe entre autres, s\'étant rendu dans une ville de Samarie, y prêcha le Messie, et les foules s\'attachèrent toutes à ce qu\'il leur disait, quand elles apprirent et virent les miracles qu\'il faisait;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'car les esprits impurs sortaient de plusieurs possédés, en poussant de grands cris. Beaucoup de paralytiques et de boiteux furent aussi guéris;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'et ce fut une grande joie dans cette ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Il s\'y trouvait déjà un homme nommé Simon, qui exerçait la magie et qui émerveillait le peuple de Samarie. Il se donnait pour un grand personnage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'et tous, petits et grands, s\'étaient attachés à lui, et disaient: «C\'est la Puissance de Dieu, celle qu\'on appelle la Grande Puissance.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Ils s\'étaient donc attachés à lui, parce que, pendant assez longtemps, il les avait charmés par sa magie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Mais, quand ils eurent cru Philippe, qui leur annonçait ce qui a trait au royaume de Dieu et à la personne de Jésus-Christ, hommes et femmes se firent baptiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Simon même crut aussi, et, après s\'être fait baptiser, il ne quittait plus Philippe, et il s\'extasiait à la vue des miracles et des prodiges qui s\'opéraient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Les apôtres, qui étaient à Jérusalem, ayant appris que la Samarie avait accueilli la parole de Dieu, y envoyèrent Pierre et Jean.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Ceux-ci, s\'y étant rendus, prièrent pour que les Samaritains reçussent le Saint-Esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'car il n\'était encore descendu sur aucun d\'eux; ils se trouvaient seulement baptisés au nom du Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Alors les deux apôtres leur imposèrent les mains, et ils reçurent le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Lorsque Simon vit que le Saint-Esprit était donné par l\'imposition des mains des apôtres, il leur offrit de l\'argent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'en disant: «Donnez-moi aussi ce pouvoir, que celui à qui j\'imposerai les mains reçoive le Saint-Esprit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Pierre lui dit: «Que ton argent périsse avec toi, puisque tu as cru acquérir le don de Dieu avec de l\'argent!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Tu n\'as aucune espèce de part à cette faveur, car ton coeur n\'est pas droit devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Repens-toi donc de ta méchanceté, et prie le Seigneur de vouloir bien te pardonner la pensée de ton coeur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'car je m\'aperçois que tu es dans un fiel bien amer et dans les liens de la méchanceté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Simon repartit: «Priez vous-mêmes le Seigneur pour moi, afin qu\'il ne m’arrive rien de ce que vous dites.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Pour eux, après avoir rendu témoignage, et prêché la parole du Seigneur, ils reprirent la route de Jérusalem et annoncerait l\'évangile dans plusieurs villages des Samaritains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Un ange du Seigneur adressa la parole à Philippe, et lui dit: «Lève-toi, et va au midi, sur la route qui descend de Jérusalem à Gaza.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, '(Cette ville est déserte.) Il se leva et se mit en marche. Et voici, il y avait sur cette route un Éthiopien, eunuque puissant de Candace, reine d\'Ethiopie, surintendant de tous ses trésors, qui était venu à Jérusalem pour adorer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Il s\'en retournait, et assis sur son char, il lisait le prophète Ésaïe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'L\'Esprit dit à Philippe: «Avance, et ne quitte pas ce char.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Philippe, étant accouru, entendit ce seigneur qui lisait le prophète Esaïe, et il lui dit: «Comprends-tu ce que tu lis?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Il lui répondit: «Eh! comment le pourrais-je, si l\'on ne me guide?» Et il invita Philippe à monter s\'asseoir avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Or, voici la teneur du passage qu\'il lisait: «Il a été mené comme une brebis à la boucherie, et, comme un agneau muet devant celui qui le tond, il n\'ouvre pas la bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'C\'est dans l’humiliation que son jugement est consommé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Quant aux hommes de sa génération, qui les dépeindra? car on lui a ôté la vie de dessus la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'L\'eunuque ayant pris la parole, dit à Philippe: «Je t\'en prie, de qui le prophète parle-t-il ainsi? Est-ce de lui-même, ou de quelque autre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Philippe ouvrant la bouche, lui annonça Jésus en commençant par ce passage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'En poursuivant leur route, ils rencontrèrent de l\'eau; l\'eunuque dit: «Voici de l\'eau; qu\'est-ce qui empêche que je ne sois baptisé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '[Philipppe lui dit: «Si tu crois de tout ton coeur cela est possible.» Il répondit: «Je crois que Jésus-Christ est le Fils de Dieu.»]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Et il fit arrêter le char; puis Philippe et l\'eunuque descendirent tous deux dans l\'eau, et Philippe le baptisa.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Quand ils furent sortis de l\'eau. l\'Esprit du Seigneur enleva Philippe: l\'eunuque ne le vit plus, car, pendant qu\'il continuait sa route, plein de joie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippe se trouva à Azote, d\'où il alla jusqu’à Césarée, en évangélisant toutes les villes par où il passait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Cependant Saul, ne respirant que mort et menaces contre les disciples du Seigneur, alla trouver le souverain sacrificateur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'et lui demanda des lettres pour les synagogues de Damas, afin que, s\'il trouvait des gens de cette croyance, il les amenât, hommes et femmes, enchaînés à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Comme il était en chemin et qu\'il approchait de Damas, tout à coup une lumière, qui venait du ciel, l\'enveloppa de sa clarté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Et, étant tombé par terre, il entendit une voix qui lui dit: «Saul, Saul, pourquoi me persécutes-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Il dit: «Qui es-tu, Seigneur?» Le Seigneur répondit: «Je suis Jésus, que tu persécutes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'mais lève-toi, entre dans la ville, et l’on te dira ce que tu dois faire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Les hommes qui faisaient route avec lui s\'étaient arrêtés, muets; ils entendaient la voix, mais ils ne voyaient personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Cependant Saul se releva, et, quoiqu\'il eût les yeux ouverts, il ne voyait rien:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'c\'est en le conduisant par la main qu\'on le mena à Damas. Il resta trois jours sans voir; et il ne mangeait ni ne buvait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Or il y avait à Damas un disciple nommé Ananias; et le Seigneur lui dit dans une vision: «Ananias!» Il répondit: «Me voici, Seigneur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Le Seigneur lui dit: «Lève-toi, va dans la rue qu\'on appelle la Rue Droite, et demande, dans la maison de Judas, après un nommé Saul de Tarse; car voici, il est en prière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'et il a vu un homme nommé Ananias, qui entrait, et lui imposait les mains pour lui rendre la vue.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias répondit: «Seigneur, j\'ai entendu dire à plusieurs personnes, combien de maux cet homme a faits à tes saints dans Jérusalem;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'et, ici, il est muni de pouvoirs de la part des principaux sacrificateurs, pour emprisonner tous ceux qui invoquent ton nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Mais le Seigneur lui dit: «Va, car cet homme est un instrument que j\'ai choisi, pour porter mon nom devant les Gentils, devant les rois et devant les fils d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Je lui montrerai tout ce qu\'il faut qu\'il souffre pour mon nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Ananias donc s\'en alla et vint dans cette maison; puis, ayant imposé les mains à Saul, il dit: «Saul, mon frère, le Seigneur Jésus qui t\'est apparu sur la route par laquelle tu venais, m\'a envoyé, afin que tu recouvres la vue, et que tu sois rempli du Saint-Esprit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Aussitôt, il tomba des yeux de Saul comme des écailles, et il recouvra la vue. Il se leva et fut baptisé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'puis, ayant pris de la nourriture, il retrouva des forces. Dès qu\'il eut passé quelques jours avec les disciples de Damas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'il prêcha dans les synagogues que Jésus est le Fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Tous ceux qui l\'entendaient étaient surpris, et disaient: «N\'est-ce pas lui qui, à Jérusalem, persécutait ceux qui invoquent ce nom, et n\'était-il pas venu ici dans le dessein de les emmener, prisonniers, aux principaux sacrificateurs?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Cependant Saul se fortifiait de plus en plus, et il confondait les Juifs qui demeuraient à Damas, leur démontrant que Jésus est le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Au bout de quelque temps, les Juifs complotèrent de le faire périr;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'mais Saul eut connaissance de leur trame. Ils gardaient aussi les portes, jour et nuit, pour le tuer;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'mais ses disciples le prirent et le firent évader de nuit par le rempart, en le descendant dans une corbeille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Arrivé à Jérusalem, il tâchait de se lier avec les disciples, mais tous le craignaient, ne croyant pas qu\'il fût disciple de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabas, l\'ayant pris avec lui, le conduisit auprès des apôtres, et leur raconta comment Saul avait vu le Seigneur sur la route, lui avait parlé, et comment, à Damas, il avait prêché hardiment au nom de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Dès lors Saul allait et venait avec eux à Jérusalem, et il ne craignait pas de parler au nom du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Il abordait les hellénistes et disputait avec eux; mais ceux-ci cherchaient à lui ôter la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Les frères, en ayant eu connaissance, l\'emmenèrent à Césarée, et le firent partir pour Tarse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'L\'Église jouissait donc de la paix dans toute la Judée, la Galilée et la Samarie, s\'édifiant et marchant dans la crainte du Seigneur, et elle s\'accroissait par les exhortations qu\'inspirait le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Pierre qui faisait une tournée générale, vint aussi chez les saints qui demeuraient à Lydde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Il y trouva un homme nommé Énée, qui gardait le lit depuis huit ans: il était paralysé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Pierre lui dit: «Énée, Jésus, le Messie, te guérit. Lève-toi, et fais toi-même ton lit;» et aussitôt il se leva.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Tous les habitants de Lydde et du Saron le virent, et ils se convertirent au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Il y avait à Joppé, parmi les disciples, une femme nommée Tabitha, en grec Dorcas: elle était riche en bonnes oeuvres, notamment en aumônes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Elle tomba malade en ce temps-là, et mourut. Après l\'avoir lavée, on la déposa dans une chambre haute.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Comme Lydde est près de Joppé, les disciples, ayant appris que Pierre s\'y trouvait, lui dépêchèrent deux hommes, pour le prier de venir jusque chez eux, sans tarder.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Pierre se leva, et partit avec les messagers. Dès qu\'il fut arrivé, on le fit monter à la chambre haute. Toutes les veuves vinrent à lui en pleurant, et en lui montrant toutes les tuniques et tous les vêtements que faisait Dorcas pendant qu\'elle était avec elles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Pierre fit sortir tout le monde, se mit à genoux et pria; puis, s\'étant tourné vers le corps, il dit: «Tabitha, lève-toi.» Elle ouvrit les yeux, et, ayant vu Pierre, elle se mit sur son séant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Il lui donna la main, et la fit lever; puis, ayant appelé les saints et les veuves, il la leur présenta vivante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Ce miracle fut connu dans toute la ville de Joppé; et beaucoup crurent au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Pierre demeura quelque temps à Joppé, chez un corroyeur nommé Simon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Il y avait à Césarée un homme du nom de Corneille, centurion de la cohorte appelée cohorte italienne:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'c\'était un homme pieux et craignant Dieu, lui et toute sa maison. Il faisait beaucoup d\'aumônes au peuple, et priait Dieu sans cesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Un jour, vers la neuvième heure, il vit clairement dans une vision, un ange de Dieu, qui entra vers lui, et lui dit: «Corneille!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Il le regarda fixement, et, plein d\'effroi, répondit: «Qu\'est-ce, Seigneur?» Et l\'ange lui dit: «Tes aumônes et tes prières sont montées devant Dieu; et il s\'en est souvenu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Et maintenant envoie chercher à Joppé un certain Simon, surnommé Pierre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'il loge chez un corroyeur nommé Simon, qui a sa maison près de la mer.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Dis que l\'ange qui lui parlait fut parti, Corneille appela deux de ses domestiques et un soldat pieux, d\'entre ceux qui étaient attachés à sa personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'et, après leur avoir tout raconté, il les envoya à Joppé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Le lendemain, comme les messagers étaient en route, et qu\'ils approchaient de la ville, Pierre monta sur le toit, vers la sixième heure du jour, pour prier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Il avait faim, et il désirait manger; et, pendant qu\'on préparait son repas, il tomba en extase:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'il vit le ciel ouvert, et un objet semblable à une grande nappe, lequel descendait, attaché par les quatre coins, et s\'abaissait sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Là, se trouvaient tous les quadrupèdes et les reptiles de la terre, et les oiseaux du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'En même temps une voix lui dit: «Lève-toi, Pierre, tue, et mange.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Mais Pierre dit: «Je n\'ai garde, Seigneur, car je n\'ai jamais rien mangé de souillé ni d\'impur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Et une voix lui parla pour la seconde fois: «Ce que Dieu a déclaré pur, toi, ne le tiens pas pour souillé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Cela arriva par trois fois, et aussitôt l\'objet fut retiré dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Pierre hésitait en lui-même sur le sens de la vision qu\'il avait eue, quand les hommes envoyés par Corneille, s\'étant informés de la maison de Simon, se présentèrent à la porte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'et, après avoir appelé, ils demandèrent si c\'était là que logeait Simon surnommé Pierre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Comme Pierre était plongé dans ses réflexions sur la vision, l\'Esprit lui dit: «Voici des gens qui te demandent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'lève-toi donc, descends et va avec eux, sans hésiter, car c\'est moi qui te les ai envoyés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Il descendit, et dit à ces hommes: «Voici, je suis celui que vous demandez: quel motif vous amène?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Ils lui dirent: «Le centurion Corneille, homme juste et craignant Dieu, à qui toute la nation des Juifs rend un bon témoignage été averti par un saint ange de te faire venir chez lui et d\'entendre tes instructions.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Pierre les pria donc d\'entrer, et les logea. Le lendemain, s\'étant levé, il partit avec eux, accompagné de quelques frères de Joppé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'et le jour suivant ils entrèrent à Césarée. Corneille les attendait; il avait convoqué ses parents et ses amis intimes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Quand Pierre entra, Corneille alla au-devant de loi, et se jeta à ses pieds pour l\'adorer»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Mais Pierre le releva en disant: «Lève-toi, je ne suis moi-même qu\'un homme;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'et tout en causant avec lui, il entra, et trouva une nombreuse réunion.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Il leur dit: «Vous savez à quel point il est interdit à un Juif de se lier avec un étranger, ou de lui rendre visite; eh bien! Dieu m\'a appris, à moi, à ne traiter aucun homme de souillé ni d\'impur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Aussi n\'ai-je fait aucune difficulté de venir, dès que vous m\'avez envoyé chercher; je vous prie donc de me dire pour quelle raison vous m\'avez fait venir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Et Corneille dit: «Il y a, à cette heure même, quatre jours que je jeûnais, et, à la neuvième heure, au moment où je priais dans ma maison, un homme vêtu d\'une robe éclatante m’apparut,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'et me dit: «Corneille, ta prière a été exaucée, et Dieu s\'est souvenu de tes aumônes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Envoie donc à Joppé, et fais appeler Simon surnommé Pierre; il loge dans la maison du corroyeur Simon, près de la mer, il viendra te parler.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'J\'ai donc envoyé immédiatement vers toi, et tu as bien fait de venir. Maintenant nous voici tous en présence de Dieu, pour entendre tout ce que le Seigneur t\'a commandé de nous dire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Pierre ouvrit la bouche, et dit: «En vérité, je comprends que Dieu ne fait pas acception de personnes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'mais qu\'en toute nation celui qui le craint et pratique la justice lui est agréable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Telle est la parole qu\'il a adressée aux fils d\'Israël, en annonçant la bonne nouvelle de la paix par Jésus-Christ. Il est le Seigneur de tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, '«Vous savez ce qui s\'est passé dans toute la Judée, et qui a commencé par la Galilée, après le baptême que Jean a prêché:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'comment Dieu a oint d\'esprit saint et de force Jésus de Nazareth, qui allait de lieu en lieu faisant du bien et guérissant tous ceux qui étaient tyrannisés par le diable, parce que Dieu était avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Pour nous, nous sommes témoins de tout ce qu\'il fait dans les campagnes de la Judée et à Jérusalem, lui, à qui les Juifs ont même ôté la vie en le pendant au bois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Mais Dieu l’a ressuscité le troisième jour, et lui a donné de se faire voir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'non à tout le peuple, mais à des témoins, à ceux que Dieu avait précédemment choisis, à nous, qui avons mangé et bu avec lui, après qu\'il a été ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Et Jésus nous a commandé de prêcher au peuple, et d\'attester que c\'est lui que Dieu a désigné pour juge des vivants et des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'C\'est de lui que tous les prophètes rendent le témoignage, que quiconque croit en lui, reçoit par son nom le pardon de ses péchés...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Pierre parlait encore, lorsque le Saint-Esprit descendit sur tous ceux qui écoutaient sa parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Tous les fidèles de la circoncision qui avaient accompagné Pierre, furent surpris de ce que le don du Saint-Esprit était aussi répandu sur les Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'car ils les entendaient parler des langues et glorifier Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Alors Pierre dit: «Peut-on refuser l\'eau du baptême à ces hommes qui ont reçu le Saint-Esprit aussi bien que nous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Et il ordonna de les baptiser au nom du Seigneur. Après cela, on le pria de rester quelques jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Cependant les apôtres et les frères qui étaient en Judée, apprirent que les Gentils avaient aussi reçu la parole de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'et lorsque Pierre monta à Jérusalem, les fidèles de la circoncision eurent une contestation avec lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'disant: «Tu es entré chez des incirconcis, et tu as mangé avec eux!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Pierre se mit à leur exposer de point en point ce qui s\'était passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '«J\'étais, dit-il, en prière dans la ville de Joppé, et j\'eus, en extase, une vision: je vis descendre un objet semblable à une grande nappe qui descendait du ciel, tenue par les quatre coins, et qui s\'abaissa jusqu’à moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Ayant arrêté mes regards sur cette nappe, je la considérai, et j\'y vis les quadrupèdes de la terre, les bêtes sauvages, les reptiles et les oiseaux du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'J\'entendis aussi une voix qui me dit: «Lève-toi, Pierre, tue, et mange.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Et je dis: «Je n\'ai garde, Seigneur, car jamais ce qui est souillé ou impur n\'est entré dans ma bouche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Mais une voix parlant une seconde fois du ciel, répondit: «Ce que Dieu a déclaré pur, toi, ne le tiens pas pour souillé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Cela arriva par trois fois, puis tout fut retiré dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, '«Au même instant, trois hommes se présentèrent à la maison où nous étions: on les avait envoyés de Césarée vers moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'L\'Esprit me dit d\'aller avec eux sans hésiter. Les six frères que voici, vinrent aussi avec moi, et nous entrâmes dans la maison de Corneille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Il nous raconta comment il avait vu dans sa maison un ange apparaître, et lui dire: «Envoie à Joppé, et fais venir Simon surnommé Pierre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'qui te dira des choses par lesquelles tu seras sauvé, toi et toute ta maison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Lorsque j\'eus commencé à parler, le Saint-Esprit descendit sur eux, ainsi qu\'il est descendu sur nous au commencement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'et je me ressouvins de ce mot du Seigneur: «Jean a baptisé d\'eau, mais vous, vous serez baptisés d\'esprit saint.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Si donc Dieu leur a fait le même don qu\'à nous, lorsque nous avons cru au Seigneur Jésus-Christ, qui étais-je, moi, pour m’opposer à Dieu? Le pouvais-je?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Quand ils eurent entendu ce récit, ils s\'apaisèrent et glorifièrent Dieu en disant: «Dieu a donc donné aussi aux Gentils la repentance pour avoir la vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Ceux qui avaient été dispersés par la persécution survenue à l\'occasion d\'Etienne, allèrent jusqu\'en Phénicie, dans l\'île de Chypre et à Antioche, n\'annonçant la Parole à personne, sinon aux Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Toutefois il y eut parmi eux quelques Cypriotes et quelques Cyrénéens, qui, étant venus à Antioche, s\'adressèrent aux Grecs, et leur annoncèrent le Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Et la main du Seigneur était avec eux, de sorte qu\'un grand nombre de personnes crurent et se convertirent au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'La nouvelle en étant venue aux oreilles de l\'église de Jérusalem, on chargea Barnabas de se rendre jusqu’à Antioche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Lorsqu\'il fut arrivé, et qu\'il eut vu la grâce que Dieu avait accordée à ceux d’Antioche, il s\'en réjouit et les exhorta tous à demeurer attachés au Seigneur, comme du reste ils se le proposaient en leur coeur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'car c\'était un homme de bien, plein d\'esprit saint et de foi. Et une foule assez considérable se joignit au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Barnabas alla ensuite à Tarse, pour chercher Saul, et, l\'ayant trouvé, il l\'amena à Antioche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Ils passèrent ensemble une année entière dans cette église, et instruisirent beaucoup de monde. Ce fut à Antioche que, pour la première fois, les disciples furent appelés chrétiens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'A la même époque, des prophètes descendirent de Jérusalem à Antioche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'L\'un d\'eux, nommé Agabus, s\'étant levé, présagea par l\'Esprit, qu\'il y aurait une grande famine sur toute la terre: elle eut effectivement lieu sous Claude.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Les disciples décidèrent d\'envoyer, chacun selon ses moyens, un secours aux frères qui habitaient la Judée:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'ce qu\'ils firent. On envoya ce secours aux anciens par l\'entremise de Barnabas et de Saul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Vers ce temps-là, le roi Hérode fit arrêter quelques-uns des membres de l\'église, pour les maltraiter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Il fit mourir par le glaive Jacques, le frère de Jean,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'et voyant que cela était agréable aux Juifs, il fit encore prendre Pierre. On était aux jours des pains sans levain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'L\'ayant aussi arrêté, il le fit mettre en prison, et le confia à la garde de quatre escouades de quatre soldats chacune, dans l\'intention de le faire exécuter devant le peuple, après Pâque.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Pierre était donc gardé dans la prison, et l\'église ne cessait de prier Dieu pour lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'La nuit même qui précéda le jour où Hérode devait le faire exécuter, Pierre, lié de deux chaînes, dormait entre deux soldats, pendant que des sentinelles faisaient la garde devant les portes de la prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Tout à coup un ange du Seigneur apparut, et une lumière resplendit dans le cachot. L\'ange poussant Pierre par le côté, l\'éveilla, et lui dit: «Lève-toi promptement;» et les chaînes tombèrent de ses mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'L\'ange lui dit: «Ceins-toi, et chausse tes sandales.» Pierre obéit. L\'ange ajouta: «Mets ton manteau, et suis-moi;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'et Pierre sortit du cachot et le suivit, sans savoir que ce que faisait l’ange fût réel: il croyait avoir une vision.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Lorsqu\'ils eurent passé la première garde et la seconde, ils arrivèrent à la porte de fer qui donne sur la ville; elle s\'ouvrit d\'elle-même devant eux, et, étant sortis, ils s\'engagèrent dans une rue. Aussitôt l\'ange le quitta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Pierre étant revenu à lui-même, se dit: «Je vois maintenant que le Seigneur a réellement envoyé son ange, et m\'a délivré de la main d\'Hérode et de tout ce qu\'attendait le peuple juif;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'puis, après un moment de réflexion, il se rendit à la maison de Marie, mère de Jean surnommé Marc, où un assez grand nombre de personnes s\'étaient réunies et priaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Il heurta à la porte d\'entrée; une servante nommée Rhode, vint répondre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'et, ayant reconnu la voix de Pierre, dans sa joie, elle ne lui ouvrit point, mais courut annoncer que Pierre était à la porte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Ils lui dirent: «Tu es folle.» Mais elle soutenait que c\'était vrai; et eux disaient: «C\'est son ange.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Cependant Pierre continuait à heurter. Ils ouvrirent, et, en le voyant, ils furent tout surpris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Alors, ayant fait signe de la main de faire silence, il leur raconta comment le Seigneur l\'avait tiré de la prison, et ajouta: «Faites-le savoir à Jacques et aux frères;» puis il sortit, et s\'en alla dans un autre lieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Quand il fit jour, les soldats furent dans une grande agitation, pour savoir ce que Pierre était devenu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Hérode, ayant fait des perquisitions, et n\'ayant pu le trouver, procéda à l\'interrogatoire des gardes, et les fit conduire au supplice. Puis il descendit de Judée à Césarée, où il s\'arrêta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Il était en hostilité avec les Tyriens et les Sidoniens. Ceux-ci se rendirent ensemble auprès de lui, et, ayant gagné Blaste, chambellan du roi, ils lui demandèrent la paix, parce que leur pays tirait sa subsistance de celui du roi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Le jour même de l’audience, Hérode, revêtu de ses habits royaux et assis dans sa tribune, les haranguait,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'et le peuple s\'écria: «Voix d\'un dieu, et non d\'un homme!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Soudain, un ange du Seigneur le frappa, parce qu\'il n\'avait pas donné gloire à Dieu; et il expira rongé des vers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Cependant la parole de Dieu faisait des progrès, et le nombre des croyants se multipliait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Après avoir rempli leur mission, Barnabas et Saul quittèrent Jérusalem et s\'en retournèrent, emmenant avec eux Jean surnommé Marc.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Il y avait dans l\'église d\'Antioche des prophètes et des docteurs, Barnabas, Syméon dit Niger, Lucius de Cyrène, ainsi que Manahem, qui avait été élevé avec Hérode le Tétrarque, et Saul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Pendant qu\'ils rendaient leur culte au Seigneur et qu\'ils jeûnaient, le Saint-Esprit dit: «Mettez-moi à part Barnabas et Saul pour l\'oeuvre à laquelle je les ai appelés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Alors, après qu\'ils eurent jeûné et prié, ils leur imposèrent les mains, et les laissèrent aller.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Pour eux, envoyés par le Saint-Esprit, ils descendirent à Séleucie, et de là ils firent voile pour l\'île de Chypre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Arrivés à Salamine, ils annoncèrent la parole de Dieu dans les synagogues des Juifs: Jean les accompagnait en qualité d\'aide.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Après avoir parcouru toute l\'île jusqu’à Paphos, ils trouvèrent un certain personnage, magicien, faux prophète juif, nommé Bar-jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'qui vivait auprès du proconsul Sergius Paulus, homme de sens. Le proconsul, ayant fait appeler Barnabas et Saul, témoigna le désir d\'entendre la parole de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'mais Elymas, le mage (car c\'est ce que signifie ce nom) leur faisait opposition et cherchait à détourner le proconsul de la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saul, qui s\'appelle aussi Paul, rempli du Saint-Esprit, l\'ayant regardé fixement, lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, '«Homme plein de toute sorte de ruse et de toute sorte de fourberie, fils du diable, ennemi de toute justice, ne cesseras-tu pas de pervertir les voies du Seigneur, qui sont droites?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Mais voici, la main du Seigneur va s\'appesantir sur toi, et tu seras aveugle, privé pour un temps de la vue du soleil.» Soudain, l\'obscurité et les ténèbres tombèrent sur lui, et, allant de droite et de gauche, il cherchait quelqu\'un pour le conduire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Alors le proconsul, témoin de cet événement, embrassa la foi: il était frappé de la doctrine du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Paul et ses compagnons s\'embarquèrent à Paphos et vinrent à Perge en Pamphylie. Jean les quitta et s\'en retourna à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Pour eux, étant partis de Perge, ils se rendirent à Antioche en Pisidie, et, étant entrés dans la synagogue le jour du sabbat, ils y prirent place.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Après la lecture de la Loi et des Prophètes, les chefs de la synagogue leur firent dire: «Frères, si vous avez quelques mots d\'exhortation à adresser au peuple, parlez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Paul se leva, et, ayant fait signe de la main, il dit: «Israélites, et vous qui craignez Dieu, écoutez:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Le Dieu de ce peuple choisit autrefois nos pères, et éleva bien haut ce peuple pendant son séjour au pays d\'Egypte; puis, il l\'en tira par la puissance de son bras,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'et durant quarante ans environ, il en prit soin au désert.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Après avoir détruit sept nations dans le pays de Canaan, il le mit en possession de leur territoire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Ensuite, durant quatre cent cinquante ans environ, il leur donna des juges jusqu’à Samuel le prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Ils demandèrent alors un roi, et Dieu leur donna Saul, fils de Kis, de la tribu de Benjamin, qui régna quarante ans;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'puis, l\'ayant retiré, il leur suscita pour roi David, à qui il a rendu témoignage, disant: «J\'ai trouvé David fils d\'Issai, homme selon mon coeur, qui exécutera toutes mes volontés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'C\'est de la postérité de ce prince que Dieu, selon sa promesse, a donné à Israël un Sauveur, savoir Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Immédiatement avant sa venue, Jean avait prêché le baptême de la repentance à tout le peuple d\'Israël,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'et, arrivé au terme de sa course, il disait: «Qui pensez-vous que je sois? Je ne suis pas le Messie. Mais voici, il vient après moi, celui dont je ne suis pas digne de délier les sandales.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Mes frères, c\'est à vous, descendants d\'Abraham, et à ceux d\'entre vous qui craignent Dieu, que cette parole de salut est envoyée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Pour les habitants de Jérusalem et leurs magistrats, ils n\'ont point reconnu Jésus, et, en le jugeant, ils ont accompli la voix des prophètes, qui se lisent tous les sabbats.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Quoiqu\'ils n\'aient trouvé en lui aucun crime qui méritât la mort, ils ont demandé à Pilate de le faire mourir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Mais, quand ils eurent accompli tout ce qui est écrit à son sujet, on l\'ôta delà croix, et on le plaça dans un sépulcre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'et Dieu l\'a ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Il est apparu, pendant plusieurs jours de suite, à ceux qui étaient montés avec lui de Galilée a Jérusalem, eux qui lui servent maintenant de témoins auprès du peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Et nous, nous vous annonçons que cette promesse faite à nos pères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Dieu l’a accomplie pour nous, leurs enfants, en ressuscitant Jésus, ainsi qu\'il est écrit au Psaume premier: «Tu es mon Fils; c\'est moi qui j’ai engendré aujourd\'hui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Que Dieu l’ait ressuscité des morts, pour qu\'il ne retournât plus à la corruption, c\'est ce qu\'il a dit en ces termes: «Je vous donnerai les choses saintes promises à David, lesquelles sont certaines.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'C\'est ce qu\'il dit encore dans un autre Psaume: «Tu ne laisseras pas ton Saint voir la corruption; »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'en effet, tandis que David, après avoir, pour sa propre génération, servi les desseins de Dieu, s\'est endormi, a été recueilli avec ses pères et a vu la corruption,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'celui que Dieu a ressuscité, n\'a pas vu la corruption.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Sachez donc, mes frères, que c\'est par ce Jésus que le pardon des péchés vous est annoncé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'et que tout homme qui Croit, trouve en lui la justification de tout ce dont vous ne pouviez être justifiés par la loi de Moïse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Prenez donc garde qu\'il ne vous arrive ce qui est dit dans les Prophètes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '«Contempteurs, voyez!... soyez étonnés et disparaissez; car je vais faire une oeuvre en votre temps, une oeuvre que vous ne croiriez point, quand on vous la raconterait.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'A leur sortie, on les pria de parler sur le même sujet au sabbat suivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Quand l\'assemblée se sépara, plusieurs Juifs et plusieurs prosélytes pieux accompagnèrent Paul et Barnabas, qui, en s\'entretenant avec eux, leur persuadèrent de demeurer attachés à la grâce de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Le sabbat suivant, presque toute la ville se rassembla pour entendre la parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'La vue de cette foule remplit les Juifs d\'une violente haine; ils contredisaient ce que Paul avançait, ajoutant aux contradictions les injures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paul et Barnabas leur dirent tout ouvertement: «C\'est bien à vous qu\'il fallait d\'abord annoncer la parole de Dieu; mais, puisque vous la repoussez, et que, vous-mêmes, vous ne vous jugez pas dignes de la vie éternelle, eh bien! nous nous tournons vers les Gentils;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'car c\'est ainsi que le Seigneur nous l’a ordonné: «Je t\'ai établi pour servir de lumière aux Gentils, pour porter le salut jusqu\'au bout de la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Les Gentils, qui les entendaient, étaient dans la joie, et glorifiaient la parole du Seigneur. Et tous ceux qui étaient disposés pour la vie éternelle, crurent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'La parole du Seigneur se propageait par tout le pays.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Mais les Juifs ayant excité les grandes dames dévotes et les principaux de la ville, provoquèrent une persécution contre Paul et Barnabas, et les firent chasser de leur territoire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Les apôtres, ayant secoué contre eux la poussière de leurs pieds, se rendirent à Icône.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Toutefois les disciples étaient remplis de joie et d\'esprit saint.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'A Icône, ils entrèrent ensemble dans la synagogue des Juifs, et ils parlèrent de telle manière qu\'une grande multitude de Juifs et de Grecs crurent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'mais les Juifs incrédules excitèrent et animèrent les esprits des Gentils contre les frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Après un assez long séjour, pendant lequel ils parlèrent hardiment, en s\'appuyant sur le Seigneur, qui rendait témoignage à la prédication de sa grâce par les prodiges et les miracles qu\'il leur donnait de faire,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'la population de la ville se divisa: les uns étaient pour les Juifs, les autres, pour les apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Mais, dès que l\'animosité des Gentils et des Juifs, ainsi que de leurs chefs, alla jusqu’à les insulter et à leur jeter des pierres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'alors, tout bien considéré, ils se réfugièrent dans les villes de Lycaonie, à Lystres, à Derbe et dans les environs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'et ils y annoncèrent l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Il y avait à Lystres un homme impotent des pieds, perclus de naissance, qui n\'avait jamais marché:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'il était assis, et il écoutait parler Paul. L\'apôtre, ayant fixé ses regards sur lui, et voyant qu\'il avait foi de manière à être guéri,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'lui dit à voix haute: «Lève-toi sur tes pieds, tout droit.» Il se leva d\'un saut, et il marcha.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'A la vue de ce miracle, que Paul venait de faire, le peuple éleva la voix, disant en lycaonien: «Les dieux, ayant pris une forme humaine, sont descendus vers nous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Et ils appelaient Barnabas, Jupiter, et Paul, Mercure, parce que c\'était lui qui portait la parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Le prêtre de Jupiter, dont le temple est à l\'entrée de la ville, amena devant leur porte des taureaux, apporta des bandelettes, et se disposait, ainsi que la foule, à leur offrir un sacrifice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Les apôtres Barnabas et Paul, l\'ayant appris, déchirèrent leurs vêtements, et se précipitèrent vers la foule, en s\'écriant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, '«hommes, pourquoi faites-vous ces choses? Nous sommes des hommes comme vous; nous vous annonçons qu\'il faut quitter ces vaines divinités, pour vous tourner vers le Dieu vivant, qui a fait le ciel, la terre, la mer et tout ce qu\'ils renferment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'C\'est lui qui, dans les âges passés, a laissé toutes les nations suivre leurs voies;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'néanmoins il ne s\'est point laissé sans témoignage, faisant du bien, vous dispensant du ciel les pluies et les saisons fertiles, nous donnant la nourriture en abondance et remplissant nos coeurs de joie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Malgré ces paroles, ils ne parvinrent qu\'avec peine à empêcher le peuple de leur sacrifier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Cependant il survint d\'Antioche et d\'Icône des Juifs, qui gagnèrent le peuple; ils lapidèrent Paul, et, croyant qu\'il était mort, ils le traînèrent hors de la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Mais les disciples l\'ayant entouré, il se releva et rentra dans la ville. Le lendemain, il s\'en alla à Derbe avec Barnabas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Après avoir évangélisé cette ville, et y avoir fait un assez grand nombre de disciples, ils retournèrent à Lystres, à Icône et à Antioche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Ils fortifiaient le courage des disciples, les exhortaient à demeurer dans la foi, ajoutant que c\'est par beaucoup d\'afflictions que nous devons entrer dans le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Ils élurent des anciens dans chaque église, et, après avoir jeûné et prié. ils les recommandèrent au Seigneur, en qui ils avaient cru.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Puis ils traversèrent la Pisidie et vinrent en Pamphylie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Après avoir annoncé la Parole à Perge, ils descendirent à Attalie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'de là, ils firent voile pour Antioche, d\'où ils étaient partis, après avoir été remis à la grâce de Dieu, pour l\'oeuvre qu\'ils venaient d\'accomplir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Quand ils furent arrivés, ils convoquèrent l\'église et rapportèrent tout ce que Dieu avait fait avec eux, notamment qu\'il avait ouvert aux Gentils la porte de la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Ils séjournèrent longtemps avec les disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Quelques disciples, venus de Judée, se mirent à enseigner les frères, disant: «Si vous ne vous faites circoncire suivant l\'institution de Moïse, vous ne pouvez être sauvés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Mais un dissentiment et une dispute assez vive s\'étant élevés entre Paul et Barnabas d\'un côté, et ces gens de l’autre, on décida que Paul, Barnabas et quelques autres d\'entre eux monteraient à Jérusalem vers les apôtres et les anciens, pour conférer sur cette question.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'En conséquence, après avoir été accompagnés par l\'église, ils traversèrent la Phénicie et la Samarie, où ils causèrent une grande joie à tous les frères en leur racontant la conversion des Gentils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Arrivés à Jérusalem, ils furent reçus par l\'église, les apôtres et les anciens, et ils rapportèrent tout ce que Dieu avait fait par leur moyen.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Mais quelques-uns du parti des pharisiens, qui avaient embrassé la foi, se levèrent en disant: «Il faut les circoncire et leur enjoindre d\'observer la loi de Moïse.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Les apôtres et les anciens s\'assemblèrent pour examiner la question.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Une longue discussion s\'étant engagée, Pierre se leva et leur dit: «Frères, vous savez que, dès longtemps déjà, Dieu m\'a choisi parmi vous pour faire entendre aux Gentils, par ma bouche, la parole de l\'évangile, afin qu\'ils croient:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'or Dieu, qui connaît les coeurs, a témoigné en leur faveur, en leur donnant le Saint-Esprit aussi bien qu\'à nous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'il n\'a point fait de différence entre eux et nous, ayant purifié leurs coeurs par la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Pourquoi donc tentez-vous Dieu maintenant, en mettant sur le cou des disciples un joug, que ni nos pères ni nous n\'avons pu porter?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Nous croyons, au contraire, que c\'est par la grâce du Seigneur Jésus que nous sommes sauvés, comme eux le croient aussi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Toute l\'assemblée garda le silence, et elle écouta Barnabas et Paul, qui racontèrent tous les miracles et les prodiges que Dieu avait faits par leur ministère au milieu des Gentils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Quand ils eurent cessé de parler, Jacques prit la parole, et dit: «Frères, écoutez-moi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Syméon a raconté comment Dieu a commencé de mettre à exécution son dessein de tirer du milieu des Gentils un peuple qui portât son nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Les déclarations des prophètes concordent avec ce fait, selon qu\'il est écrit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '«Après cela je reviendrai, et je réédifierai la maison de David, qui est tombée; je réédifierai ses ruines, et je la relèverai,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'afin que le reste des hommes cherche le Seigneur, ainsi que toutes les nations auxquelles on donne mon nom, dit le Seigneur qui exécuté ces choses,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'lesquelles sont connues de toute antiquité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'En conséquence j\'estime qu\'il ne faut point inquiéter les Gentils qui se convertissent à Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'mais leur écrire de s\'abstenir des souillures des idoles, du libertinage, des animaux étouffés et du sang.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Car, pour Moïse, depuis nombre de générations, il y a dans chaque ville des gens qui le prêchent, puisqu\'on le lit chaque sabbat dans les synagogues.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Alors les apôtres et les anciens avec toute l\'église arrêtèrent de choisir parmi eux quelques personnes qu\'on enverrait à Antioche avec Paul et Barnabas. Ils choisirent Jude dit Barsabas et Silas, personnages éminents parmi les frères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'et les chargèrent de la lettre que voici: «Les Apôtres, les Anciens et les frères, aux frères d\'entre les Gentils qui sont à Antioche, en Syrie et en Cilicie, salut!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, '— Ayant appris que quelques-uns des nôtres sont venus, sans notre aveu, vous troubler par des discours qui ont bouleversé vos âmes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'nous avons arrêté, en assemblée générale, de choisir des représentants et de vous les envoyer avec nos bien-aimés Barnabas et Paul,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'ces hommes qui ont exposé leur vie pour le nom de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Nous vous avons donc député Jude et Silas, qui vous diront de bouche ce que nous vous écrivons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'c\'est qu\'il a semblé bon au Saint-Esprit et à nous, de ne vous point imposer de nouvelles charges, excepté ceci, qui est indispensable,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'savoir, de vous abstenir de ce qui est sacrifié aux idoles, du sang, des animaux étouffés et du libertinage; toutes choses dont vous vous trouverez bien de vous garder. Adieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Les députés ayant pris congé de l’église, allèrent à Antioche, et remirent la lettre à la multitude assemblée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'On en fit lecture, et tous furent heureux de l\'invitation qu\'elle renfermait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Jude et Silas, qui étaient eux-mêmes prophètes, exhortèrent les frères et les affermirent par un long discours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Après avoir passé quelque temps avec eux, ils revinrent, avec les voeux des frères, vers ceux qui les avaient envoyés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '[Pour Silas, il trouva bon de rester à Antioche.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paul et Barnabas séjournèrent à Antioche, enseignant et annonçant, avec plusieurs autres, la parole du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Mais, au bout de quelque temps, Paul dit à Barnabas: «Retournons visiter les frères dans les différentes villes où nous avons annoncé la parole du Seigneur, pour voir dans quel état ils se trouvent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas fut d\'avis de prendre aussi Jean dit Marc;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'mais Paul estimait qu\'il n\'était pas juste de prendre avec eux un homme qui les avait abandonnés en Pamphylie, et qui ne les avait pas accompagnés dans leur oeuvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Il en résulta de l\'irritation, au point qu\'ils se séparèrent l\'un de l\'autre, et que Barnabas, prenant Marc avec lui, fit voile pour l\'Ile de Chypre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paul, ayant fait choix de Silas, partit, après avoir été remis à la grâce du Seigneur par les frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Il parcourut la Syrie et la Cilicie, affermissant les églises, et arriva à Derbe et à Lystres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Il y fit rencontre d\'un disciple nommé Timothée, qui était fils d\'une Juive fidèle, mais d\'un père grec,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'et qui jouissait d\'un bon renom parmi les frères de Lystres et d\'Icône.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paul voulut remmener avec lui; il le prit et le circoncit à cause des Juifs qui étaient en ces lieux-là, car tous savaient que son père était grec.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Dans les villes où ils passaient, ils enseignaient aux frères à garder les arrêtés pris par les apôtres et par les anciens de Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Les églises s\'affermissaient donc dans la foi, et croissaient en nombre de jour en jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Ils parcoururent la Phrygie et le pays de Galatie, après avoir été empêchés par le Saint-Esprit d\'annoncer la Parole dans l’Asie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Arrivés près de la Mysie, ils essayèrent d\'entrer en Bithynie, mais l\'Esprit de Jésus ne le leur permit pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Alors, ayant traversé rapidement la Mysie, ils descendirent à Troas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Là, Paul eut une vision dans la nuit: il vit un Macédonien debout, qui l\'appelait, et lui disait: «Passe en Macédoine pour nous secourir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Aussitôt après cette vision, nous cherchâmes à passer en Macédoine, concluant que le Seigneur nous appelait à y porter l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Étant donc partis de Troas, nous fîmes voile droit vers la Samothrace, et le lendemain nous débarquâmes à Néapolis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'De là, nous allâmes à Philippes, colonie romaine, qui est la première ville du district de Macédoine. Nous nous arrêtâmes quelques jours dans cette ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Le jour du sabbat, nous nous rendîmes hors de la porte, vers une rivière, où se trouvait, selon la coutume, un lieu de prière, et nous étant assis, nous nous entretînmes avec les femmes qui s\'y étaient assemblées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'L\'une d\'elles écouta: c\'était une marchande de pourpre, nommée Lydie, de la ville de Thyatire, femme craignant Dieu. Le Seigneur lui ouvrit le coeur pour qu\'elle fût attentive aux choses que Paul disait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Lorsqu\'elle eut été baptisée, ainsi que sa famille, elle nous adressa cette invitation: «Puisque vous avez jugé que j\'ai foi au Seigneur, venez demeurer chez moi.» Et elle nous y contraignit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Un jour que nous nous acheminions vers le lieu de prière, nous rencontrâmes une servante qui avait un esprit Python, et qui, en devinant, procurait un grand profit à ses maîtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Elle se mit à nous suivre, Paul et nous, en criant: «Ces hommes-là sont des serviteurs du Dieu Très-Haut, ils nous annoncent la voie du salut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Elle fit cela plusieurs jours de suite, et Paul en étant fatigué, se retourna, et dit à l\'esprit: «Je te commande, au nom de Jésus, de sortir de cette fille;» et il sortit à l\'heure même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Les maîtres de la servante, voyant que leur espérance de gain s\'était évanouie, se saisirent de Paul et de Silas, et les traînèrent à la place publique vers les magistrats.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Ils les amenèrent devant les préteurs, et dirent: «Ces hommes troublent notre ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Ce sont des Juifs; ils prêchent des pratiques qu\'il ne nous est pas permis à nous, Romains, d\'adopter ni de suivre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'La foule se souleva aussi contre eux, et les préteurs, leur ayant arraché leurs vêtements, ordonnèrent qu\'ils fussent battus de verges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Lorsqu\'on les eut chargés de coups, ils les firent jeter en prison en commandant au geôlier de les garder sûrement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'D\'après cet ordre, le geôlier les mit dans le cachot intérieur, et fixa leurs pieds dans les ceps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Vers le milieu de la nuit, Paul et Silas, s\'étant mis en prière, chantaient des hymnes à Dieu; et les détenus les entendaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Tout à coup il se fit un si grand tremblement de terre, que les fondements de la prison en furent ébranlés; au même instant, toutes les portes s\'ouvrirent, et les fers de tous les prisonniers tombèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Le geôlier, s\'étant réveillé, et voyant les portes de la prison ouvertes, crut que les détenus s\'étaient enfuis; il tira une épée et allait se tuer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'lorsque Paul lui cria d\'une voix forte: «Ne te fais point de mal mous sommes tous ici.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Alors, ayant demandé de la lumière, il s\'élança dans le cachot, et, tout tremblant, se jeta aux pieds de Paul et de Silas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'puis, les ayant fait sortir, il leur dit: «Seigneurs, que faut-il que je fasse pour être sauvé?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Ils lui répondirent: «Crois au Seigneur Jésus, et tu seras sauvé, toi et ta famille;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'et ils lui annoncèrent la parole du Seigneur, ainsi qu\'à tous ceux qui étaient dans sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'A cette même heure de la nuit, le geôlier les prit avec lui, lava leurs plaies, et, immédiatement après, il fut baptisé, lui et tous les siens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Après les avoir fait monter dans son logement, il leur servit à manger, heureux qu\'il était d\'avoir cru en Dieu avec toute sa fa- mille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Quand le jour fut venu, les préteurs envoyèrent dire par les licteurs: «Relâche ces gens-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Et le geôlier annonça cette nouvelle à Paul: «Les préteurs, dit-il, ont envoyé l\'ordre de vous relâcher; maintenant donc sortez, et allez en paix.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Mais Paul dit aux licteurs: «Quoi! après nous avoir publiquement battus de verges, sans jugement, nous qui sommes romains, ils nous ont jetés en prison, et maintenant ils nous font sortir secrètement! Non pas; mais qu\'ils viennent eux-mêmes nous mettre en liberté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Les licteurs rapportèrent ces paroles aux préteurs, qui furent effrayés en apprenant que ces hommes étaient romains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Ils vinrent leur parler, et, en les élargissant, ils les prièrent de quitter la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Au sortir de la prison, les apôtres entrèrent chez Lydie, et, après avoir vu et encouragé les frères, ils partirent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Ils firent route par Amphipolis, par Apollonie, et arrivèrent à Thessalonique, où se trouvait la synagogue des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Paul y entra selon sa coutume, et discuta avec eux pendant trois sabbats de suite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Il expliquait et enseignait par les Écritures, que le Messie avait dû souffrir et ressusciter des morts, ajoutant: «Ce Messie, c\'est Jésus, que je vous annonce.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Quelques Juifs furent persuadés, et passèrent du côté de Paul et de Silas, comme aussi une grande multitude de Grecs craignant Dieu, et un assez grand nombre des premières dames de la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Mais les Juifs ayant recruté quelques mauvais sujets des rues, firent un attroupement et du tumulte dans la ville; puis, s\'étant portés vers la maison de Jason, ils cherchèrent les apôtres pour les mener devant le peuple:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'ne les ayant pas trouvés, ils traînèrent Jason et quelques frères devant les autorités de la ville, criant: «Ces gens qui ont bouleversé le monde, les voilà maintenant ici.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Jason les a reçus, et tous, ils agissent contre les édits de César, disant qu\'il y a un autre roi, Jésus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Ils jetèrent le trouble dans la population et chez les magistrats qui entendirent ces accusations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ce ne fut qu\'après avoir reçu satisfaction de Jason et des autres, qu\'ils les laissèrent aller.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Les frères se hâtèrent de faire partir, dans la nuit, Paul et Silas pour Bérée. Quand ils y furent arrivés, ils se rendirent à la synagogue des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ceux-ci montrèrent des sentiments plus élevés que ceux de Thessalonique; ils accueillirent la Parole avec beaucoup d\'empressement, examinant chaque jour les Écritures, pour voir si ce qu\'on leur enseignait était exact.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Un grand nombre d\'entre eux crurent, et spécialement beaucoup de femmes grecques de qualité, et un assez grand nombre d\'hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Mais aussitôt que les Juifs de Thessalonique surent que Paul annonçait également la parole de Dieu à Bérée, ils vinrent y agiter aussi la population.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Alors les frères firent immédiatement partir Paul, pour qu\'il gagnât la mer, mais Silas et Timothée restèrent à Bérée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ceux qui s\'étaient chargés de Paul, le conduisirent jusqu’à Athènes; ils en partirent avec ordre de dire à Silas et à Timothée de le rejoindre au plus tôt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Pendant que Paul les attendait à Athènes, son coeur était froissé intérieurement de voir cette ville toute pleine d\'idoles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Il discutait donc dans la synagogue avec les Juifs et avec les hommes craignant Dieu, et tous les jours dans la place avec les premiers venus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Quelques philosophes épicuriens et des stoïciens conférèrent avec lui: quelques-uns disaient: «Que veut bien dire ce discoureur?» et d\'autres: «Il paraît que c\'est un prédicateur de divinités étrangères;» parce que Paul leur annonçait Jésus et la résurrection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Alors ils le prirent, et le menèrent à la place de l\'Aréopage, disant: «Pourrions-nous savoir quelle est cette nouvelle doctrine que tu prêches?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Car tu nous fais entendre des choses étranges: nous désirerions donc savoir ce que cela peut être.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Or tous les Athéniens et les étrangers qui demeuraient à Athènes, ne passaient leur temps qu\'à dire ou à écouter des nouvelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paul, debout au milieu de l\'Aréopage, leur dit: «Athéniens, je me suis aperçu que vous êtes, à tous égards, plus dévots que les autres peuples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'car, ayant examiné en passant les objets de votre culte, j\'ai trouvé même un autel sur lequel il est écrit: «A un Dieu inconnu.» Eh bien! ce que vous révérez sans le connaître, c\'est ce que je vous annonce,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'le Dieu qui a fait le monde et tout ce qu\'il renferme. Lui, qui est le Maître du ciel et de la terre, n\'habite pas dans des sanctuaires faits de main d\'homme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'il n\'est point servi non plus par des mains humaines, comme s\'il avait besoin de quelque chose, lui qui donne à tous la vie, la respiration, et toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Il a fait habiter tout le genre humain, qui est issu d\'un seul et même sang, sur toute la surface de la terre, ayant déterminé la durée précise des nations, ainsi que les limites de leur habitation,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'afin qu\'elles le cherchent, et le trouvent comme à tâtons. Et certes, il n\'est pas loin de chacun de nous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'car c\'est en lui que nous avons la vie, le mouvement et l\'être; et, comme l\'ont dit quelques-uns de vos poètes, «nous sommes aussi de sa race.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Puis donc que nous sommes de la race de Dieu, nous ne devons pas croire que la Divinité soit semblable à une sculpture d\'or, d\'argent ou de pierre, fruit de l\'art et de la pensée de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Dieu, passant donc sur ces temps d\'ignorance, fait savoir actuellement en tous lieux, à tous les hommes, qu\'ils aient à se repentir;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'parce qu\'il a arrêté un jour, où il doit juger la terre avec justice, par l\'homme qu\'il a désigné, en foi de quoi il l\'a ressuscité des morts...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Lorsqu\'ils entendirent parler de résurrection des morts, les uns se moquèrent, les autres dirent: «Nous t\'entendrons là -dessus une autre fois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'C\'est ainsi que Paul se retira du milieu d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Toutefois quelque personnes s\'étant attachées à lui, embrassèrent la foi, savoir Denis l\'aréopagite, une femme nommée Damaris, et d\'autres avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Ensuite Paul partit d\'Athènes et se rendit à Corinthe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Il y trouva un Juif nommé Aquilas, originaire du Pont, fraîchement arrivé d\'Italie avec Priscille, sa femme, parce que Claude avait enjoint à tous les Juifs de quitter Rome. Paul alla les voir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'et, comme il était du même métier, il demeura chez eux et y travailla: ils étaient faiseurs de tentes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Tous les jours de sabbat, il discourait dans la synagogue, et persuadait Juifs et Grecs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Quand Silas et Timothée arrivèrent de Macédoine, Paul était tout entier à la Parole, ne cessant d\'enseigner aux Juifs, que Jésus était le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mais comme ils s\'opposaient et se portaient à des injures, il secoua ses vêtements, et leur dit: «Que votre sang retombe sur votre tête! pour moi, j\'en suis net; désormais j\'irai vers les Gentils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Puis il sortit de ce lieu et se retira chez un nommé Justus, homme craignant Dieu, dont la maison était contiguë à la synagogue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Crispus, président de la synagogue, crut au Seigneur avec toute sa famille. Un grand nombre aussi de Corinthiens embrassèrent la foi en entendant Paul, et se firent baptiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Le Seigneur dit à Paul, la nuit, dans une vision: «Ne crains point, mais parle; ne garde point le silence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'car je suis avec toi, et personne ne t\'attaquera de manière à te maltraiter. J\'ai un grand peuple dans cette ville.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Et Paul résida un an et demi à Corinthe, y enseignant la parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Un jour, les Juifs se jetèrent tous ensemble sur lui, et le menèrent devant le tribunal de Gallion qui était alors proconsul d\'Achaïe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, '«Cet homme, dirent-ils, persuade aux gens d\'adorer Dieu d\'une manière contraire à la Loi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Comme Paul se disposait à parler, Gallion dit aux Juifs: «S\'il s\'agissait de quelque délit ou de quelque acte frauduleux, je vous entendrais patiemment, comme de raison;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'mais puisqu\'il s\'agit de disputes sur une parole, sur des noms propres, et sur votre Loi, vous y aviserez vous-mêmes: je ne veux pas être juge de ces choses-là.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Et il les fit sortir du tribunal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Alors tous ayant saisi Sosthènes, président de la synagogue, le battirent devant le tribunal, sans que Gallion s\'en mît en peine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Après être demeuré assez longtemps encore à Corinthe, Paul fit ses adieux aux frères, et s\'embarqua pour la Syrie avec Priscille et Aquilas; il se fit auparavant raser la tête à Cenchrées à cause d’un voeu qu\'il avait fait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Ils arrivèrent à Éphèse, et Paul y laissa ses compagnons. Pour lui, étant entré dans la synagogue, il s\'entretint avec les Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Ceux-ci le prièrent de prolonger son séjour parmi eux, mais il n\'y consentit point,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'et leur fit ses adieux en disant: «Il faut absolument que je célèbre la fête prochaine à Jérusalem, mais je reviendrai vers vous, s\'il plaît à Dieu;» et il partit d\'Éphèse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Etant débarqué à Césarée, il monta à Jérusalem, et, après avoir salué l\'église, il se rendit à Antioche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Lorsqu\'il y eut passé quelque temps, il partit et parcourut successivement la Galatie et la Phrygie, affermissant tous les disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Or un Juif nommé Apollos, originaire d\'Alexandrie, homme éloquent et très versé dans les Écritures, était venu à Éphèse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Il était instruit de la voie du Seigneur, et, dans la ferveur de son âme, il expliquait et enseignait avec exactitude ce qui se rapporte à Jésus, quoiqu\'il n\'eût connaissance que du baptême de Jean.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Il se mit à parler hardiment dans la synagogue: Aquilas et Priscille l\'ayant entendu, le prirent avec eux, et lui exposèrent plus exactement la voie de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Comme il voulait aller en Achaïe, les frères écrivirent aux disciples pour les engager à le recevoir. Quand il y fut arrivé, il fut d\'un grand secours, par ses talents, à ceux qui avaient embrassé la foi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'car il réfutait vigoureusement les Juifs, en public, démontrant par les Écritures que Jésus est le Messie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Pendant qu’Apollos était à Corinthe. Paul, après avoir parcouru les hautes provinces de l’Asie, arriva à Éphèse. Il y trouva quelques disciples,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'et leur dit: «Avez-vous reçu le Saint-Esprit, quand vous avez cru?» Ils lui répondirent: «Mais nous n\'avons pas même entendu dire qu\'il y ait un Saint-Esprit?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, '- «Quel baptême, leur dit-il, avez-vous donc reçu?» Ils répondirent: «Le baptême de Jean.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Alors Paul leur dit: «Jean a baptisé du baptême de la repentance en disant au peuple que c\'était afin qu\'ils eussent foi en celui qui venait après lui, c\'est-à-dire, on Jésus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Là-dessus, ils se firent baptiser au nom du Seigneur Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'et Paul leur ayant imposé les mains, le Saint-Esprit vint sur eux: ils parlaient des langues et prophétisaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Ils étaient en tout environ douze.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Paul entra dans la synagogue; il y parla hardiment, et pendant trois mois il s\'efforça par ses discours de convaincre les Juifs de ce qui concerne le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Mais, comme quelques-uns s\'endurcissaient et se refusaient à croire, décriant devant la multitude la voie du Seigneur, il se sépara d\'eux, prit à part les disciples et se mit à enseigner chaque jour dans l\'école d\'un nommé Tyrannus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Cela dura deux ans, de sorte que tous ceux qui habitaient l\'Asie, tant Juifs que Grecs, entendirent la parole du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Et Dieu faisait des miracles prodigieux par les mains de Paul,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'au point que l\'on appliquait sur les malades les mouchoirs et les tabliers qui avaient touché son corps, et les maladies étaient guéries, et les esprits malins étaient chassés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Quelques-uns aussi des exorcistes juifs qui courent les pays, essayèrent de prononcer le nom du Seigneur Jésus sur ceux qui avaient des esprits malins, en disant: «Je vous conjure par Jésus que Paul prêche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, '(C\'étaient sept fils de Scévas, grand sacrificateur juif, qui faisaient cela).');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Mais l\'esprit malin répondit: «Je connais Jésus, et je sais qui est Paul; mais vous, qui êtes-vous?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Et l\'homme en qui se trouvait l\'esprit malin, sauta sur eux, se rendit maître de tous deux, et les maltraita si fort qu\'ils s\'enfuirent de cette maison, nus et blessés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Ce fait étant venu à la connaissance des Juifs et des Grecs qui habitaient Éphèse, ils furent tous saisis de crainte, et le nom du Seigneur Jésus fut glorifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Plusieurs de ceux qui avaient cru, venaient confesser et déclarer ce qu\'ils avaient fait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Un grand nombre de ceux qui exerçaient les sciences occultes, apportèrent leurs livres et les brûlèrent devant tout le monde; ils en calculèrent le prix et trouvèrent qu\'il s\'élevait à cinquante mille drachmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'telle était la force avec laquelle la parole du Seigneur s\'étendait et se montrait puissante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Après cela, Paul résolut d\'aller à Jérusalem en passant par la Macédoine et par l\'Achaïe, et il se dit: «Lorsque j\'aurai été là, il faut aussi que je voie Rome.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Il envoya en Macédoine deux de ses aides, Timothée et Éraste; lui-même resta encore quelque temps en Asie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Il s\'éleva, à cette époque, un grand tumulte au sujet de la voie du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Un orfèvre nommé Démétrius, qui faisait de petits temples de Diane en argent, et qui donnait beaucoup d\'ouvrage aux artistes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'les rassembla, ainsi que les ouvriers qui travaillaient à ce genre d\'objets, et leur dit: «hommes, vous savez que cette industrie fait notre aisance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'et vous voyez et vous entendez dire, que, non seulement à Ephèse, mais encore dans presque toute l\'Asie, ce Paul a fait changer beaucoup de monde, en persuadant par ses discours, que les dieux faits de main d\'homme ne sont pas des dieux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'de sorte que nous courons le risque, non seulement que notre partie ne tombe, mais encore que le temple de la grande déesse Diane ne soit complètement discrédité, et qu\'on ne dépouille de sa majesté celle que toute l\'Asie, que le monde entier adore.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Ces paroles les ayant enflammés de colère, ils se mirent à crier: «Grande est la Diane des Éphésiens!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Et la ville fut remplie de confusion. Ils se portèrent tous ensemble au théâtre, entraînant avec eux Caïus et Aristarque, Macédoniens qui avaient accompagné Paul dans son voyage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Paul voulait se rendre vers le peuple, mais ses disciples ne le lui permirent pas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'et même quelques-uns des Asiarques, qui étaient de ses amis, envoyèrent vers lui pour le prier de ne pas se présenter au théâtre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Les uns donc criaient d\'une manière, les autres d\'une autre, car l\'assemblée était tumultueuse, et la plupart ne savaient pas pourquoi ils s\'étaient réunis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Cependant on vit sortir de la foule Alexandre, qui était poussé en avant par les Juifs. Il fit signe de la main qu\'il voulait parler au peuple;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'mais, lorsqu\'ils eurent reconnu qu\'il était Juif, ils poussèrent tous une clameur, et, durant près de deux heures, ils crièrent: «Grande est la Diane des Éphésiens!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Le chancelier ayant apaisé la foule, dit: «Éphésiens, quel homme au monde ignore que la ville d\'Éphèse est la gardienne du temple de la grande Diane et de sa statue tombée du ciel?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Puis donc que cela est incontestable, vous devez vous calmer et ne rien faire inconsidérément;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'car ces hommes que vous avez amenés ici, ne sont ni sacrilèges, ni blasphémateurs de notre déesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Si Démétrius et les artistes qui l\'accompagnent, ont quelque plainte à faire contre quelqu\'un, il y a des assises et des proconsuls, qu\'ils s\'y adressent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'et si vous avez à débattre d\'autres affaires, cela se videra dans l\'assemblée légale,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'car nous risquons d\'être accusés de sédition pour le rassemblement d\'aujourd\'hui, parce qu\'il n\'y a pas de motif qui puisse justifier cet attroupement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Là-dessus, il congédia l\'assemblée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Lorsque le tumulte eut cessé, Paul, ayant réuni les disciples et les ayant embrassés, partit pour aller en Macédoine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Il parcourut cette province en adressant aux disciples de nombreuses exhortations, et se rendit en Grèce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Après un séjour de trois mois, il se disposait à s\'embarquer pour la Syrie, mais, les Juifs lui ayant dressé des embûches, il prit le parti de s\'en retourner par la Macédoine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Sopater, fils de Pyrrhus, de Bérée, raccompagna jusqu\'en Asie, avec Aristarque et Secundus de Thessalonique, Caïus de Derbe et Timothée, Tychique et Trophime d\'Asie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'ceux-ci ayant pris les devants, nous attendirent à Troas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Pour nous, nous partîmes de Philippes après les jours des pains sans levain, et au bout de cinq jours de navigation, nous les rejoignîmes à Troas, et nous y demeurâmes sept jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Le premier jour de la semaine, comme nous étions assemblés pour rompre le pain, Paul, qui devait partir le lendemain, s\'entretint avec les disciples, et prolongea son discours jusqu’à minuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Il y avait beaucoup de lampes dans la salle haute où nous étions assemblés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Un jeune homme nommé Eutyche, qui était assis sur la fenêtre, succomba à un profond sommeil, parce que Paul parlait fort longtemps, et, entraîné par le sommeil, il tomba du troisième étage en bas: on le releva mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Mais Paul, étant descendu, s\'étendit sur lui, et, après l\'avoir tenu embrassé, il dit: «Cessez vos cris, car la vie est en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Puis étant remonté, il rompit le pain, mangea et conversa assez longtemps, jusqu’à l\'aube; et il partit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Quant au jeune homme, on l\'amena vivant, ce qui fut une immense consolation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Pour nous, ayant pris les devants par mer, nous fîmes voile vers Assos, où nous devions reprendre Paul, car c\'est ainsi qu\'il l\'avait ordonné: il devait, lui, aller à pied.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Lorsqu\'il nous eut rejoints à Assos, nous le prîmes avec nous, et nous gagnâmes Mytilène.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Nous partîmes de là, et nous arrivâmes le jour suivant en face de Chio, le troisième jour nous touchâmes Samos, puis, après avoir relâché à Trogylle, nous abordâmes le lendemain à Milet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Paul avait jugé bon de dépasser Éphèse, pour ne pas perdre de temps en Asie, car il se hâtait, afin d\'arriver, s\'il était possible, le jour de la Pentecôte à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Cependant il envoya de Milet à Éphèse, pour mander les anciens de l\'église.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Lorsqu\'ils furent venus vers lui, il leur dit: «Vous savez comment, depuis le premier jour que j\'ai mis le pied en Asie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'je me suis toujours comporté avec vous, servant le Seigneur en toute humilité, au milieu des larmes et des épreuves, auxquelles m\'ont exposé les embûches des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Vous savez que je vous ai annoncé l’évangile, et que je vous ai instruits en public et en particulier, sans vous rien cacher de ce qui pouvait vous être avantageux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'je n\'ai pas cessé d\'enseigner aux Juifs et aux Grecs la repentance envers Dieu, et la foi en notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Maintenant, je m\'en vais à Jérusalem, m\'y sentant obligé intérieurement, sans que je sache ce qui doit m\'y arriver;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'seulement, de ville en ville, le Saint-Esprit ne cesse de m\'assurer que des chaînes et des malheurs m\'attendent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Mais je n\'en tiens aucun compte, et je n\'attache pour moi-même aucun prix à la vie, pourvu que je fournisse ma carrière, et que j\'accomplisse le ministère que j\'ai reçu du Seigneur Jésus, d\'enseigner la bonne nouvelle de la grâce de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Pour moi, je sais que vous ne verrez plus mon visage, vous tous parmi lesquels je suis venu prêcher le royaume;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'en conséquence je proteste aujourd\'hui devant vous que je suis net du sang de tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'car je vous ai annoncé tout le conseil de Dieu, sans vous en rien cacher.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Prenez donc garde à vous-mêmes, et à tout le troupeau sur lequel le Saint-Esprit vous a établis évêques, pour paître l\'église que le Seigneur s\'est acquise par son propre sang.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Je sais qu\'après mon départ, il s\'introduira parmi vous des loups terribles, qui n\'épargneront point le troupeau,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'et qu\'il s\'élèvera dans votre propre sein des hommes professant des doctrines perverses, pour s\'attirer des disciples.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Veillez donc, vous souvenant que durant trois années, je n\'ai cessé, ni jour ni nuit, d\'avertir avec larmes chacun de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Et maintenant, je vous recommande à Dieu et à la parole de sa grâce, à celui qui peut édifier et vous donner une part avec tous les sanctifiés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Je n\'ai désiré ni l\'argent, ni l\'or, ni les vêtements de personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Vous savez vous-mêmes que ces mains ont pourvu à mes besoins et à ceux de mes compagnons;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'je vous ai montré de toutes manières que c\'est en travaillant ainsi, que l\'on doit accueillir les faibles, et se souvenir des paroles du Seigneur, qui a dit lui-même: «Il y a plus de bonheur à donner qu\'à recevoir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Après avoir ainsi parlé, il se mit à genoux, et pria avec eux tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Ils fondirent tous en larmes, et, se jetant au cou de Paul,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'ils l\'embrassaient, navrés surtout de ce qu\'il leur avait dit qu\'ils ne verraient plus son visage. Puis ils l\'accompagnèrent jusqu\'au vaisseau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Après nous être séparés d\'eux avec beaucoup de peine, nous levâmes l\'ancre, et nous vînmes droit à Cos, le lendemain à Rhodes, et de là à Patare.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Et ayant trouvé un navire qui mettait à la voile pour la Phénicie, nous montâmes dessus, et nous partîmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Quand nous fûmes en vue de Chypre, nous laissâmes l\'île à gauche, et, nous dirigeant vers la Syrie, nous abordâmes à Tyr: c\'est là que le vaisseau devait poser sa cargaison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Ayant découvert des disciples dans cette ville, nous y demeurâmes sept jours; eux, mus par l\'Esprit, déconseillèrent à Paul de monter à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Quand ces jours furent écoulés, nous nous remîmes en route; tous les frères nous accompagnèrent jusqu\'en dehors de la ville, avec leurs femmes et leurs enfants; nous nous mîmes à genoux sur le rivage, pour prier,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'et nous nous séparâmes: nous montâmes sur le navire, et ils retournèrent chez eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Pour nous, achevant notre navigation, nous allâmes de Tyr à Ptolemaïs; nous y saluâmes les frères et passâmes un jour avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Le lendemain nous partîmes, et nous vînmes à Césarée; et, étant entrés dans la maison de Philippe l’évangéliste, qui était l\'un des sept diacres, nous demeurâmes chez lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Il avait quatre filles vierges, qui prophétisaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Nous y étions depuis plusieurs jours, lorsqu’arriva un prophète de Judée, nommé Agabus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Étant venu nous voir, il prit la ceinture de Paul, s\'en lia les mains et les pieds, et dit: «Voici ce que dit le Saint-Esprit: «C\'est ainsi que les Juifs de Jérusalem lieront l\'homme à qui appartient cette ceinture; et ils le livreront entre les mains des Gentils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'A ces paroles, les gens de l\'endroit se joignirent à nous pour prier Paul de ne point monter à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Mais Paul répondit: «Que faites-vous en pleurant ainsi, et en m\'attendrissant le coeur? Je suis tout prêt, quant à moi, non seulement à être enchaîné, mais encore à mourir à Jérusalem pour le nom du Seigneur Jésus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'N\'ayant pu le dissuader, nous ne le pressâmes pas davantage, et nous dîmes: «Que la volonté du Seigneur se fasse!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Quelques jours après, nous fîmes nos préparatifs, et nous montâmes à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Quelques disciples de Césarée vinrent aussi avec nous, et nous menèrent chez un nommé Mnason, de Chypre, ancien disciple, chez qui nous devions loger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Arrivés à Jérusalem, nous fûmes reçus avec joie par les frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Le lendemain, Paul se rendit avec nous chez Jacques: tous les anciens s\'y assemblèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Après les avoir embrassés, Paul leur raconta en détail ce que Dieu avait fait, par son ministère, au milieu des Gentils;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'et eux glorifiaient Dieu en l\'entendant. Ensuite ils dirent à Paul: «Tu vois, frère, combien il y a de myriades de gens qui ont cru, parmi les Juifs, et qu\'ils sont tous pleins de zèle pour la Loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Or on a été instruit que tu enseignes à tous les Juifs qui sont parmi les Gentils, d\'abandonner Moïse, leur disant de ne pas circoncire leurs enfants, et même de ne pas vivre selon nos institutions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Que faire donc? On se rassemblera en foule bien certainement, car on saura que tu es venu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Fais donc ce que nous allons te dire: Nous avons quatre hommes qui ont fait un voeu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'prends-les avec toi, purifie-toi avec eux, et fais les frais des sacrifices pour eux, afin qu\'ils se rasent la tête; de cette manière tous connaîtront que les rapports qu\'on a faits sur ton compte sont sans valeur, et que tu vis en gardant toi-même la Loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Quant aux Gentils convertis à la foi, nous leur avons envoyé une députation, après avoir décidé qu\'ils n\'ont rien de pareil à observer, mais qu\'ils doivent seulement s\'abstenir de ce qui est sacrifié aux idoles, du sang, des animaux étouffés et du libertinage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Alors Paul prit ces hommes, et, s\'étant purifié, il entra le lendemain avec eux dans le temple, pour déclarer que les jours de la purification étaient expirés, et il y vint jusqu’à ce que le sacrifice eût été présenté pour chacun d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Mais, sur la fin des sept jours de la fête, les Juifs d\'Asie l\'ayant vu dans le temple, ameutèrent toute la foule et se saisirent de lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'en criant: «Israélites, au secours! Voilà l\'homme qui s\'en va prêchant partout et à tous contre le peuple, contre la Loi et contre ce lieu. Bien plus, il a introduit des Grecs dans le temple, et a profané ce saint lieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Ils avaient vu peu auparavant Trophime d\'Éphèse avec Paul dans la ville, et ils croyaient qu\'il l\'avait fait entrer dans le temple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Toute la ville fut en émoi, et le peuple accourut en foule. S\'étant saisis de Paul, ils le traînèrent hors du temple, et les portes en furent fermées aussitôt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Pendant qu\'ils cherchaient à le tuer, la nouvelle que tout Jérusalem était en confusion, arriva au tribun de la cohorte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Il prit au même instant des soldats et des centurions, et fondit sur ces furieux, qui, voyant le tribun et les soldats, cessèrent de frapper Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Alors le tribun s\'étant approché, se saisit de lui, et le fit lier de deux chaînes; puis il demanda qui il était, et ce qu\'il avait fait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Mais, dans cette foule, les uns criaient une chose, les autres, une autre, de sorte que ne pouvant rien savoir de certain, à cause du tumulte, il commanda qu\'on l\'emmenât dans la caserne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Lorsque Paul fut sur les degrés, il fallut que les soldats le portassent, à cause de la violence de la multitude,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'car le peuple les suivait en foule, en criant: «A mort!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Au moment d\'entrer dans la caserne, Paul dit au tribun: «Me serait-il permis de te dire quelque chose?» Le tribun lui dit: «Tu sais le grec?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Tu n\'es donc pas cet Égyptien qui s\'est révolté, il y a quelques jours, et qui a emmené au désert ces quatre mille brigands?» —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, '«Moi, lui dit Paul, je suis Juif, de Tarse, citoyen d\'une ville de Cilicie qui n\'est pas sans renom. Je te prie, permets-moi de parler au peuple?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Le tribun l\'y ayant autorisé, Paul, debout sur les degrés, fit signe de la main au peuple. Un profond silence s\'étant établi, il leur adressa la parole en langue hébraïque, et dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '«Mes frères et mes pères, écoutez ce que j\'ai à vous dire présentement pour ma défense.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Quand ils entendirent qu\'il s\'adressait à eux en hébreu, ils redoublèrent de tranquillité, et Paul dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '«Je suis Juif, né à Tarse en Cilicie, mais j\'ai été élevé ici, dans cette ville, et j\'y ai été instruit aux pieds de Gamaliel dans l\'observance stricte de la Loi de nos pères, ayant pour Dieu le même zèle que vous avez tous aujourd\'hui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'C\'est moi qui ai persécuté à mort cette secte, enchaînant et mettant en prison hommes et femmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Le souverain sacrificateur m\'en est témoin, ainsi que tout le collège des anciens, de qui j\'ai même reçu des lettres pour les frères, lorsque je suis allé à Damas, afin d\'amener enchaînés à Jérusalem ceux de cette secte qui s\'y trouvaient, et de les faire punir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Mais, comme j\'étais en chemin, et que j\'approchais de Damas, tout à coup, vers midi, une vive lumière qui venait du ciel, m\'enveloppa de sa clarté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Je tombai sur le sol, et j\'entendis une voix qui me disait: «Saul, Saul, pourquoi me persécutes-tu?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Je répondis: «Qui es-tu, Seigneur?» Et le Seigneur me dit: «Je suis Jésus de Nazareth que tu persécutes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Ceux qui étaient avec moi virent bien la lumière, et furent saisis d\'effroi; mais ils n\'entendirent point la voix de celui qui me parlait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Alors je dis; «Que dois-je faire, Seigneur?» Le Seigneur me répondit: «Lève-toi, va-t\'en à Damas, et là on t\'instruira de tout ce que tu dois faire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Comme je n\'y voyais pas, par l\'effet de l\'éclat de cette lumière, ceux qui étaient avec moi me conduisirent par la main à Damas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Cependant un homme pieux selon la Loi, nommé Ananias, de qui tous les Juifs domiciliés à Damas rendaient un bon témoignage, vint me trouver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Il se présenta et me dit: «Saul, mon frère, recouvre la vue.» A l\'instant même je vis, et je le regardai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Il ajouta: «Le Dieu de nos pères a disposé de toi, pour que tu connusses sa volonté, que tu visses le Juste, et que tu entendisses le son de sa voix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'parce que tu lui serviras de témoin, devant tous les hommes, des choses que tu as vues et entendues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Que tardes-tu? Lève-toi, fais-toi baptiser et laver de tes péchés en invoquant son nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Un jour que j\'étais revenu à Jérusalem, il m\'arriva, comme je priais dans le temple, de tomber en extase:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'je vis Jésus qui me dit: «Hâte-toi, sors promptement de Jérusalem, parce qu\'on n\'y recevra pas le témoignage que tu rendras de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Et je dis: «Seigneur, ils savent bien que c\'est moi qui faisais emprisonner et battre dans les synagogues ceux qui croyaient en toi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'et que, lorsqu\'on répandait le sang d\'Etienne, ton témoin, j\'étais là, y assistant en personne, j\'applaudissais aussi, et je gardais les manteaux de ceux qui le tuaient.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Et il me dit: «Va, car je t\'enverrai bien loin chez les Gentils...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Ils l\'écoutèrent jusqu’à ce mot; mais alors ils élevèrent la voix, disant: «A mort le malfaiteur! Il n\'est pas digne de vivre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Ils vociféraient, ils lançaient leurs vêtements et faisaient voler la poussière en l\'air.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Le tribun donna l\'ordre d\'emmener Paul dans la caserne, et de lui donner la question par le fouet, afin de savoir pour quelle cause on poussait de tels cris contre lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Quand on l\'eut attaché au pilier pour le flageller, Paul dit au centurion qui se trouvait là: «Vous est-il permis de battre de verges un citoyen romain, et sans jugement encore? »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'A ces mots, le centurion alla faire rapport au tribun, disant: «Que vas-tu faire? Cet homme est citoyen romain.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Le tribun vint, et dit à Paul: «Dis-moi, tu es citoyen romain?» — «Oui,» dit-il.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Le tribun reprit: «Moi, j\'ai donné une forte somme d\'argent pour ce droit de cité.» — «Et moi, dit Paul, je l\'ai par ma naissance.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Là-dessus, ceux qui devaient lui donner la question s\'éloignèrent de lui; et le tribun eut peur, quand il sut que Paul était citoyen romain, parce qu\'il l\'avait fait attacher.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Le lendemain, voulant savoir positivement de quoi les Juifs l\'accusaient, il lui ôta ses chaînes, et, ayant fait assembler les principaux sacrificateurs et tout le sanhédrin, il amena Paul et le fit comparaître devant eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paul, les regards fixés sur le sanhédrin, dit: «Frères, c\'est en toute bonne conscience que je me suis conduit devant Dieu jusqu’à ce jour...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Le souverain sacrificateur Ananias ordonna aux huissiers qui étaient près de lui, de le frapper à la bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Alors Paul lui dit: «Dieu te frappera, muraille blanchie! Tu sièges pour me juger selon la loi, et, au mépris de la loi, tu ordonnes qu\'on me frappe!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Mais les huissiers lui dirent: «Tu insultes le souverain sacrificateur de Dieu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paul dit: «Je ne savais pas, mes frères, qu\'il était souverain sacrificateur, car il est écrit: «Tu ne proféreras point d\'injures contre un chef de ton peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Paul, sachant qu\'une partie du sénat se composait de sadducéens, et l\'autre, de pharisiens, s\'écria en plein sanhédrin: «Mes frères, je suis pharisien, fils de pharisiens, c\'est à cause de l\'espérance et de la résurrection des morts que je suis mis en jugement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Dès qu\'il eut prononcé ces paroles, un dissentiment éclata entre les pharisiens et les sadducéens, et l\'assemblée se divisa;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'car les sadducéens prétendent qu\'il n\'y a pas de résurrection, ni même d\'ange et d\'esprit, tandis que les pharisiens professent l\'une et l\'autre doctrine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Une grande clameur se fit entendre; des scribes du parti des pharisiens s\'étant levés, dirent dans l\'ardeur de la lutte: «Nous ne trouvons aucun mal en cet homme; si un esprit lui a parlé, ou un ange, qu\'est-ce à dire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Comme la discorde éclatait, le tribun, craignant que Paul ne fût mis en pièces par eux, donna l\'ordre de faire venir la troupe pour l\'enlever du milieu d\'eux, et le ramener dans la caserne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'La nuit suivante, le Seigneur se présenta à Paul, et lui dit: «Prends courage; comme tu m\'as rendu témoignage à Jérusalem, il faut de même que tu me rendes témoignage à Rome.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Quand le jour fut venu, les Juifs ourdirent un complot, et jurèrent, avec des imprécations contre eux-mêmes, de ne manger ni boire qu\'ils n\'eussent tué Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Ils étaient plus de quarante qui avaient fait cette conjuration.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ils allèrent trouver les principaux sacrificateurs et les anciens, et leur dirent: «Nous avons juré, avec des imprécations contre nous-mêmes, de ne rien manger que nous n\'ayons tué Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Vous donc, maintenant, adressez-vous avec le sanhédrin au tribun, pour qu\'il vous l\'amène, comme si vous vouliez examiner plus soigneusement son affaire; et nous, nous sommes prêts à le tuer, avant qu\'il approche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Le fils de la soeur de Paul, ayant entendu parler de ce guet-apens, se rendit à la caserne, y entra, et en informa Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Celui-ci appela un des centurions, et lui dit: «Mène ce jeune homme au tribun, car il a quelque chose à lui communiquer.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Le centurion prit donc le jeune homme avec lui, le mena auprès du tribun, et lui dit: «Le prisonnier Paul m\'ayant appelé, m\'a prié de t\'amener ce jeune homme, parce qu\'il a quelque chose à te dire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Le tribun ayant pris le jeune homme par la main et l\'ayant tiré à part, lui demanda: «Qu\'as-tu à me communiquer?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, '— «Les Juifs, dit-il, sont convenus de te prier d\'amener demain Paul au sanhédrin, sous prétexte de te le faire examiner plus soigneusement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Garde-toi d\'y consentir, car c\'est un guet-apens: plus de quarante d\'entre eux ont juré, avec des imprécations contre eux-mêmes, de ne manger ni boire qu\'ils ne l\'aient tué; maintenant ils sont prêts, et n\'attendent que ton consentement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Le tribun renvoya le jeune homme en lui recommandant de ne dire à personne qu\'il lui eût fait ce rapport;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'et, ayant appelé deux de ses centurions, il leur dit: «Tenez prêts, dès la troisième heure de la nuit, deux cents soldats avec soixante et cavaliers et deux cents lanciers pour aller jusqu’à Césarée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Il leur dit aussi de se pourvoir de montures pour Paul, afin de le mener sain et sauf au gouverneur Félix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'il écrivit en même temps une lettre, dont voici la teneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '« Claude Lysias au très excellent gouverneur Félix, salut!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, '— Les Juifs s\'étaient saisis de cet homme et allaient le tuer, quand j\'arrivai avec de la troupe et le leur arrachai, ayant appris qu\'il était citoyen romain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Comme je désirais savoir de quel crime ils l\'accusaient, je le menai dans leur sénat,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'et je trouvai qu\'il s\'agissait de controverses relatives à leur Loi, mais qu\'il n\'y avait point de grief qui méritât la mort ou la prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Ayant reçu l\'avis qu\'on devait lui dresser des embûches, je te l\'ai immédiatement envoyé, et j\'ai ordonné à ses accusateurs de porter leur plainte devant toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Conformément à l\'ordre qu\'ils avaient reçu, les soldats prirent Paul et le conduisirent pendant la nuit à Antipatris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Le lendemain, ils laissèrent les cavaliers cheminer avec Paul, et revinrent à la caserne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Les cavaliers entrèrent à Césarée et remirent la lettre au gouverneur; ils lui présentèrent aussi Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Après avoir lu la lettre, le gouverneur demanda de quelle province était Paul, et, ayant appris qu\'il était de Cilicie, il lui dit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, '«Je t\'entendrai quand tes accusateurs seront venus;» et il commanda qu\'on le gardât dans le prétoire d\'Hérode.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Cinq jours après, arriva le souverain sacrificateur Ananias avec les anciens et un avocat nommé Tertulle. Ils portèrent plainte au gouverneur contre Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Celui-ci ayant été appelé, Tertulle se mit à l\'accuser en ces termes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, '«Très excellent Félix, nous reconnaissons en toute rencontre et en tout lieu, avec une entière gratitude, que c\'est à toi et aux bonnes mesures que ta sollicitude t\'a dictées pour cette nation, que nous devons la paix profonde dont nous jouissons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Mais je ne veux pas t\'arrêter plus longtemps, et je te prie de nous prêter, dans ta clémence, quelques moments d\'attention.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Le fait est qu\'ayant trouvé cet homme, nous l\'avons arrêté, parce que c\'est une peste, un homme qui va semant la discorde parmi tous les Juifs répandus dans l\'empire, un chef de la secte des Nazaréens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'il a même tenté de profaner le temple. [Nous voulions le juger selon notre loi;]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, '[mais le tribun Lysias, étant survenu, l’a violemment arraché de nos mains,]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, '[en donnant l’ordre à ses accusateurs de se rendre vers toi.] Tu pourras toi-même, en l\'interrogeant, t’assurer par ses propres aveux, de tout ce que nous avançons à sa charge»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Les Juifs se joignirent à cette accusation, prétendant que c\'était l’exacte vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Mais Paul, à qui le gouverneur fit signe de parler, répondit: «C\'est avec confiance que je prends la parole pour me justifier, sachant que depuis plusieurs années tu gouvernes cette nation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Tu peux rassurer, qu\'il n\'y a pas plus de douze jours que je suis monté à Jérusalem pour adorer;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'et l’on ne m\'a vu parler à personne dans le temple, ni ameuter la foule, soit dans les synagogues, soit dans la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Ils ne peuvent pas trouver ce dont ils m\'accusent maintenant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Je te confesse que je sers le Dieu de mes pères selon la voie qu\'ils appellent une secte, en croyant néanmoins toutes les choses qui sont écrites dans la Loi et dans les Prophètes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'en ayant cette espérance en Dieu, comme ils l\'ont eux-mêmes, qu\'il y aura une résurrection tant des justes que des injustes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'dans cette conviction, je m\'efforce aussi moi-même d\'avoir constamment une conscience irréprochable devant Dieu et devant les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Après plusieurs années d’absence, je suis venu faire des aumônes à ma nation, et présenter des offrandes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'C\'est dans ces circonstances que des Juifs venus d\'Asie m\'ont trouvé, purifié, dans le temple, sans attroupement et sans tumulte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'C\'était à eux de paraître en ta présence et de m\'accuser, s\'ils ont quelque plainte à porter contre moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'ou bien, que ceux-ci disent de quel crime ils m\'ont trouvé coupable, lorsque j\'ai paru devant le sanhédrin,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'à moins qu\'ils ne me fassent un crime de cette seule parole, que j\'ai prononcée lors de ma comparution devant eux: «C\'est à cause de la résurrection des morts que vous me mettez aujourd\'hui en jugement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Mais Félix, qui connaissait assez bien ce qui se rapporte à cette croyance, les remit à un autre jour, disant: «Quand le tribun. Lysias sera venu, j\'examinerai à fond votre affaire.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Puis il commanda au centurion de tenir Paul en prison, d\'avoir des égards pour lui, et de n\'empêcher aucun des siens de lui rendre des services.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Quelques jours après, Félix étant venu avec Drusille sa femme, qui était Juive, fit chercher Paul et l\'entendit sur la foi en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Mais, comme Paul parlait de justice, de tempérance et de jugement à venir, Félix, effrayé, lui dit: «Pour le moment, va-t\'en; à la première occasion, je te rappellerai.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Il espérait en même temps que Paul lui donnerait de l\'argent: aussi le faisait-il venir assez fréquemment pour s\'entretenir avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Deux ans s\'étant écoulés, Félix eut pour successeur Porcius Festus, et, dans son désir de se rendre agréable aux Juifs, il laissa Paul en prison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Trois jours après son arrivée dans son gouvernement, Festus monta de Césarée à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Les grands sacrificateurs et les principaux d\'entre les Juifs lui portèrent plainte contre Paul,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'et sollicitèrent de lui la faveur qu\'il le fît transférer à Jérusalem: ils avaient l\'intention de le faire périr en route de guet-apens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus répondit que Paul était bien gardé à Césarée, et que lui-même devait bientôt repartir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '«Que ceux de vous, dit-il, qui sont fondés de pouvoir, descendent avec moi, et, si cet homme a commis quelque crime, qu\'ils l\'accusent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Après s\'être arrêté chez eux huit ou dix jours au plus, il descendit à Césarée, et le lendemain, ayant pris place sur son tribunal, il fit amener Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Quand celui-ci fut présent, les Juifs venus de Jérusalem l\'entourèrent, en portant contre lui plusieurs accusations graves qu\'ils ne pouvaient prouver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paul se défendait en disant qu\'il n\'avait rien fait, ni contre la loi des Juifs, ni contre le temple, ni contre César.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festus, qui voulait se faire bien venir des Juifs, répondit à Paul: «Veux-tu monter à Jérusalem, et y être jugé, en ma présence, sur ces différents chefs d\'accusation?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Mais Paul dit: «Je suis devant le tribunal de César; c\'est là que je dois être jugé. Je n\'ai fait aucun tort aux Juifs, comme tu le vois bien toi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Si je suis coupable, et que j\'aie commis quelque attentat qui mérite la mort, je ne refuse pas de mourir; mais si leurs accusations sont sans fondement, personne n\'a le droit de me livrer à eux: j\'en appelle à César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Alors Festus, après en avoir conféré avec son conseil, répondit: «Tu en as appelé à César; tu iras à César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Quelques jours après, le roi Agrippa et Bérénice arrivèrent à Césarée pour saluer Festus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Comme ils y passaient plusieurs jours, Festus exposa au roi l\'affaire de Paul, en disant: «Il y a ici un homme que Félix a laissé prisonnier,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'et contre lequel les principaux sacrificateurs et les anciens des Juifs m\'ont porté plainte, lorsque j\'étais à Jérusalem, demandant sa punition.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Je leur ai répondu que ce n’est pas la coutume des Romains de livrer un homme avant de l\'avoir confronté avec ses accusateurs, et de lui avoir donné les moyens de se justifier du crime dont on l\'accuse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Ils sont donc venus ici, et, sans différer, j\'ai pris place le lendemain sur mon tribunal, et j\'ai fait amener cet homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Ses accusateurs, ayant comparu, ne lui reprochèrent aucun des crimes dont je m\'attendais à le voir accusé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'ils l\'attaquèrent sur des controverses ayant trait à leur propre religion, et à un certain Jésus, mort, que Paul affirme être vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Comme j\'étais fort embarrassé pour faire une enquête sur ces matières, je lui demandai s\'il voulait aller à Jérusalem et y être jugé sur ces différents chefs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'mais Paul en ayant appelé, pour que sa cause fût réservée au jugement, de sa Majesté, j\'ai commandé qu\'on le gardât jusqu’à ce que je l\'envoyai à César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agrippa dit à Festus: «Je voudrais bien aussi entendre cet homme.» - «Demain, répondit Festus, tu l\'entendras»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Le lendemain donc, Agrippa et Bérénice vinrent en grande pompe, et, quand ils furent entrés dans la salle d\'audience, accompagnés des tribuns et des principaux de la ville, Paul fut amené par l\'ordre de Festus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Alors Festus dit: «Roi Agrippa, et vous tous qui êtes ici présents avec nous, vous voyez l\'homme au sujet duquel les Juifs sont venus en foule me parler, soit à Jérusalem, soit ici, me demandant à grands cris de ne plus le laisser vivre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Pour moi, ayant compris qu\'il n\'avait rien fait qui méritât la mort, et toi-même en ayant appelé à sa Majesté, j\'ai résolu de le lui envoyer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Comme je ne sais trop qu\'écrire de positif à l\'empereur sur le compte de cet homme, je l\'ai fait comparaître devant vous, et principalement devant toi, roi Agrippa, afin qu\'ensuite de ton interrogatoire, je puisse en écrire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'car il me semble déraisonnable d\'envoyer un prisonnier, sans indiquer en même temps les charges qui pèsent sur lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa dit à Paul: «Tu as la parole pour ta défense.» Alors Paul, ayant fait un geste de la main, se justifia en ces termes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '«Roi Agrippa, je m\'estime heureux d\'avoir aujourd\'hui à me disculper devant toi de toutes les choses dont les Juifs m\'accusent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'parce que tu connais parfaitement toutes leurs institutions et toutes leurs controverses. Je te prie donc de m’écouter avec patience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, '«Quant à la vie que j\'ai menée dès mon jeune âge, tous les Juifs la connaissent, puisqu\'elle s\'est passée, dès le commencement de ma jeunesse, au sein de ma nation, à Jérusalem.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Ils me connaissent de longue date; ils surent, s\'ils veulent en témoigner, que j\'ai vécu en pharisien, selon les principes de la secte la plus rigide de notre religion:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'maintenant, me voici mis en jugement, pour avoir espéré en la promesse que Dieu a faite à nos pères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'cette promesse, dont nos douze tribus espèrent voir l\'’accomplissement en servant Dieu sans relâche, jour et nuit; eh bien! ô roi, c\'est pour cette espérance que des Juifs m\'accusent!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Pourquoi juge-ton incroyable chez vous que Dieu ressuscite les morts?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Pour en revenir à moi, j\'avais cru qu\'il fallait s\'opposer fortement au nom de Jésus de Nazareth,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'et c\'est ce que j\'ai fait à Jérusalem: j\'ai fait enfermer dans les prisons bien des saints; j\'en avais reçu le pouvoir des principaux sacrificateurs; et, lorsqu\'on les mettait à mort, j\'y donnais mon suffrage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'J\'allais dans toutes les synagogues et je sévissais souvent contre eux pour les forcer de blasphémer; dans mon extrême fureur, je les poursuivais jusque dans les villes étrangères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, '«C\'est dans ces dispositions que je me rendais à Damas avec des pleins pouvoirs et une procuration que m\'avaient donnée les principaux sacrificateurs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'lorsque je vis, ô roi, en plein midi, sur la route, une lumière venant des cieux, plus éclatante que le soleil, qui m\'enveloppa de sa clarté, moi et ceux qui m\'accompagnaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Nous tombâmes tous par terre. J\'entendis une voix qui s\'adressait à moi, et me disait en hébreu: «Saul, Saul, pourquoi me persécutes-tu? Il t\'est dur de regimber contre l\'aiguillon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Je dis: «Qui es-tu, Seigneur?» Le Seigneur répondit: «Je suis Jésus que tu persécutes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'mais relève-toi et te tiens sur tes pieds, car je t\'ai apparu précisément pour faire de toi un serviteur et un témoin, tant des choses que tu as vues que de celles pour lesquelles je t\'apparaîtrai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Je t\'ai choisi du milieu du peuple et des Gentils chez lesquels je t\'envoie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'pour leur ouvrir les yeux, en sorte qu\'ils passent des ténèbres à la lumière et de la puissance de Satan à Dieu, et qu\'ils reçoivent par la foi en moi le pardon des péchés, et une part avec ceux qui ont été sanctifiés:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'en conséquence, ô roi Agrippa, je ne résistai point à la vision céleste;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'mais m\'adressant d\'abord à ceux qui étaient à Damas et à Jérusalem, puis à ceux qui étaient dans tout le pays de Judée et aux Gentils, je leur prêchai de se repentir et de se convertir à Dieu, en faisant des oeuvres dignes de la repentance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, '«Telles sont les causes pour lesquelles les Juifs se sont saisis de moi dans le temple, et ont tâché de me tuer de leurs propres mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'C\'est donc grâce à un secours venu de Dieu, que j\'ai subsisté jusqu’à ce jour, instruisant petits et grands, ne disant autre chose que ce que les prophètes et Moïse même ont prédit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'savoir que le Messie devait souffrir, et qu\'étant les prémices de la résurrection des morts, il devait annoncer la lumière au peuple et aux Gentils...»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Comme il parlait ainsi pour sa défense, Festus dit à haute voix: «Tu es fou, Paul, ton grand savoir tourne à la folie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, '«Très excellent Festus, dit Paul, je ne suis point fou, et les paroles que je prononce sont les paroles de la vérité et du bon sens;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'car le roi, à qui je parle en toute liberté, est instruit de ces faits; je suis persuadé qu\'il n\'en ignore aucun, car ils ne se sont point passés en un coin obscur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Roi Agrippa, crois-tu aux prophètes?... Je sais que tu y crois.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa dit à Paul: «C\'est bien vite me persuader d\'être chrétien.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paul repartit: «Ah! plût à Dieu que, vite ou longuement, non seulement toi, mais encore tous ceux qui m\'écoutent aujourd\'hui, vous fussiez tels que je suis... à la réserve de ces chaînes!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Le roi et le gouverneur, puis Bérénice et tous ceux qui étaient assis avec eux se levèrent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'et, s\'étant retirés, ils se disaient entre eux: «Il n\'y a rien dans la conduite de cet homme qui mérite la mort ou la prison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Et Agrippa dit à Festus: «Cet homme aurait pu être relâché, s\'il n\'en eût appelé à César.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Quand il eut été décidé que nous irions par mer en Italie, on remit Paul et d\'autres prisonniers à un centurion nommé Julius, de la cohorte Augusta.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Nous montâmes sur un vaisseau d\'Adramytte qui devait longer les côtes de l\'Asie, et nous levâmes l\'ancre, ayant avec nous Aristarque, Macédonien de Thessalonique.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Le lendemain, nous touchâmes à Sidon. Julius traita Paul avec beaucoup de bonté, et lui permit d\'aller vers ses amis jouir de leurs bons soins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Etant partis de là, nous rangeâmes la côte de Chypre, parce que les vents étaient contraires;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'et, après avoir traversé la mer qui baigne la Cilicie et la Pamphylie, nous abordâmes à Myra, ville de Lycie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Là, ayant trouvé un bâtiment d\'Alexandrie qui faisait voile pour l\'Italie, le centurion nous y fit monter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Après plusieurs jours d\'une lente navigation, nous arrivâmes à grand\'peine à la hauteur de Cnide. Le vent ne nous ayant pas permis d\'en approcher, nous rangeâmes la côte de Crête, vers Salmone,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'et, en côtoyant l\'île avec peine, nous arrivâmes à un endroit nommé Beaux-Ports; près de là se trouvait la ville de Lasée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Comme il s\'était écoulé bien du temps et que la navigation était déjà dangereuse, car l’époque même du Jeûne était déjà passée, Paul fit des représentations à l’équipage, disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, '«hommes, je vois que la navigation ne peut se faire sans exposer au danger et à de graves dommages, non seulement la cargaison et le bâtiment, mais encore nos personnes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Mais le centurion ajouta plus de foi à Paris du pilote et de l\'affréteur qu\'aux paroles de Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'D\'ailleurs, comme le port n\'était pas bon pour un hivernage, la plupart furent d\'avis de quitter ces lieux pour tâcher de gagner Phénice, port de Crête qui regarde le sud-ouest et le nord-ouest, afin d\'y passer l\'hiver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Un léger vent du sud s\'étant levé, ils se crurent à même de réaliser leur projet, levèrent l\'ancre et serrèrent de plus près la côte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mais bientôt un vent impétueux, qu\'on appelle Euroclydon, se déchaîna sur l\'île:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'comme le navire était entraîné, de sorte qu\'il ne pouvait tenir contre le vent, nous voguâmes en nous y abandonnant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Ayant passé rapidement au-dessous d\'une petite île nommée Clauda, nous parvînmes, non sans peine, à nous rendre maîtres de la chaloupe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Après l\'avoir hissée, on se servit des engins de secours; on entoura le navire par-dessous avec des câbles, et, dans la crainte d\'aller donner contre la Syrte, on abattit la voilure: c\'est ainsi que nous voguions au gré du vent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Comme nous étions violemment battus par la tempête, on jeta, le lendemain, la cargaison à la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Le jour suivant, nous précipitâmes de nos propres mains le mobilier du bâtiment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Pendant plusieurs jours, ni le soleil ni les étoiles ne se montrèrent: une violente tempête se déchaîna, et nous perdîmes alors toute espérance de salut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Comme il y avait longtemps que personne n\'avait mangé, Paul se leva au milieu de l\'équipage, et dit: «Vous auriez dû m\'écouter, hommes, ne point partir de Crête, et vous vous seriez épargné ces fureurs de la mer et cette perte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Maintenant je vous invite à prendre courage; aucun de vous ne perdra la vie, le navire seul périra;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'car un ange du Dieu à qui j\'appartiens et que je sers, m\'est apparu cette nuit même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'et m\'a dit: «Sois sans crainte, Paul; il faut que tu comparaisses devant César, et voici, Dieu t\'a donné tous ceux qui naviguent avec toi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'En conséquence, ô hommes, ayez bon courage, car j\'ai cette foi en Dieu, que les choses se passeront comme elles m\'ont été dites:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'nous devons échouer sur quelque île.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Quand vint la quatorzième nuit, nous étions ballottés sur l\'Adriatique, lorsque, vers le milieu de la nuit, les matelots soupçonnèrent qu\'on approchait de quelque terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Ayant jeté la sonde, ils trouvèrent vingt brasses; à quelque distance de là, ils la jetèrent de nouveau, et trouvèrent quinze brasses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Craignant alors de donner contre des récifs, ils jetèrent quatre ancres de la poupe, et appelèrent de leurs voeux la venue du jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Comme les matelots cherchaient à s\'enfuir du vaisseau, et mettaient la chaloupe à la mer, sous prétexte d\'aller jeter des ancres du côté de la proue,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Paul dit au centurion et aux soldats: «Si ces hommes ne restent pas sur le bâtiment, c\'en est fait de vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Alors les soldats coupèrent les cordes de la chaloupe et la laissèrent tomber.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'En attendant le jour, Paul invita tout le monde à prendre de la nourriture, disant: «C\'est aujourd\'hui le quatorzième jour que vous passez dans l\'attente et que vous n\'avez rien pris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Je vous engage donc à manger; c\'est nécessaire à votre salut, car aucun de vous ne perdra un cheveu de sa tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Ayant ainsi parlé, il prit du pain, et, ayant rendu grâces à Dieu en présence de tous, il le rompit, et se mit à manger.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Tous les autres reprenant courage, mangèrent aussi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'nous étions en tout, sur le bâtiment, deux cent soixante et seize personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Lorsqu\'on eut mangé suffisamment, on allégea le navire en jetant les provisions à la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Quand le jour fut venu, ils ne reconnurent pas quelle terre c\'était, mais ils aperçurent une baie ayant une plage, et ils résolurent d\'y pousser le navire, s\'ils le pouvaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Ils coupèrent les amarres des ancres, en laissant celles-ci à la mer; en même temps ils relâchèrent les cordes qui attachaient les gouvernails, et mettant au vent la voile de perroquet, ils se dirigèrent vers la plage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'mais ayant touché une langue de terre, ils y firent échouer le vaisseau, et, tandis que la proue, ensablée, restait immobile, la poupe était fracassée par la violence des vagues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Les soldats formèrent le projet de tuer les prisonniers, de peur que quelqu\'un d\'eux ne s\'échappât à la nage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'mais le centurion, qui voulait sauver Paul, les empêcha d\'exécuter leur dessein; il ordonna que ceux qui savaient nager se jetassent les premiers à l\'eau, pour gagner le rivage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'et que le reste, les uns sur des planches, les autres sur quelque fragment du navire, en fit autant: c\'est ainsi qu\'ils réussirent tous à se sauver à terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Une fois arrivés sains et saufs, nous reconnûmes que l\'île s\'appelait Malte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Les barbares nous traitèrent avec une bonté peu commune; car ils nous accueillirent tous auprès d\'un grand feu qu\'ils avaient allumé, à cause du froid et de la pluie qui était survenue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Paul ayant ramassé une brassée de broussailles, la mit au feu; mais la chaleur en fit sortir une vipère, qui s\'attacha à sa main.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Quand les barbares virent cette bête qui pendait à sa main, ils se dirent entre eux: «Bien certainement cet homme est un meurtrier: à peine réchappé de la mer, il est saisi par la Justice divine, qui ne permet pas qu\'il vive.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Mais Paul, ayant secoué la bête dans le feu, ne ressentit aucun mal,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'tandis que ces gens s\'attendaient à ce qu\'il allait enfler, ou tomber mort tout d\'un coup. Après avoir longtemps attendu, voyant qu\'il ne lui arrivait rien de fâcheux, ils changèrent de sentiment et dirent que c\'était un dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Il y avait près de cet endroit-là, des terres appartenant au premier personnage de l\'Ile, nommé Publius: il nous recueillit et nous donna une cordiale hospitalité durant trois jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Le père de Publius étant retenu au lit par des accès de fièvre et par la dysenterie, Paul alla le voir, et, après avoir prié en lui imposant les mains, il le guérit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Là-dessus, tous les autres habitants de l’île qui étaient malades, vinrent et furent guéris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Ils nous rendirent toute sorte d\'honneurs, et lorsque nous nous remîmes en mer, ils nous fournirent ce dont nous avions besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Au bout de trois mois, nous partîmes sur un vaisseau d\'Alexandrie, qui avait passé l\'hiver dans l\'île, et qui portait pour enseigne les Dioscures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Nous touchâmes à Syracuse, et nous y restâmes trois jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De là, en suivant le contour, nous vînmes à Rheggio, et le lendemain, le vent du sud s\'étant levé, nous arrivâmes en deux jours à Pouzzoles:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'nous y trouvâmes des frères, qui nous invitèrent à passer sept jours avec eux; ensuite nous partîmes pour Rome.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Les frères de cette ville ayant entendu parler de nous, vinrent à notre rencontre jusqu\'au forum d\'Appius et aux Trois-Tavernes. Paul, en les voyant, bénit Dieu, et prit courage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Quand nous fûmes arrivés à Rome, on autorisa Paul à demeurer seul avec un soldat qui le gardait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Trois jours après, Paul convoqua les principaux d\'entre les Juifs. Quand ils furent réunis, il leur dit: «Mes frères, quoique je n\'eusse rien fait contre le peuple, ni contre les institutions de nos pères, j\'ai été mis en prison, et transféré de Jérusalem à Césarée, pour être livré aux Romains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Après m\'avoir interrogé, ils voulaient me relâcher, parce qu\'ils ne trouvaient en moi rien qui méritât la mort,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'mais les Juifs s\'y étant opposés, j\'ai été forcé d\'en appeler à César, sans avoir aucunement le dessein d\'accuser ma nation:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'tel est le motif qui m\'a fait désirer vous voir et vous parler; car c\'est à cause de l\'espérance d\'Israël que je porte cette chaîne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Ils lui dirent: «Pour nous, nous n\'avons reçu de Judée aucune lettre à ton sujet, et aucun des frères qui en sont revenus, n’a fait de rapport, ni rien dit de défavorable sur ton compte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Mais nous voudrions bien entendre de ta bouche ce que tu penses, car, pour ce qui est de cette secte, nous savons qu\'on s\'y oppose partout.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Ayant pris jour avec lui, ils vinrent en plus grand nombre le trouver dans son logis: Paul, depuis le matin jusqu\'au soir, leur exposa, dans son instruction, ce qui a trait au royaume de Dieu, cherchant à les persuader par la Loi de Moïse et par les Prophètes, de ce qui regarde Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Les uns furent convaincus par ce qu\'il disait, mais les autres ne crurent point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Comme ils étaient en désaccord entre eux, et qu\'ils se retiraient, Paul ajouta un seul mot: «Le Saint-Esprit a bien parlé, quand il a dit à nos pères par le prophète Ésaïe:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, '«Va vers ce peuple, et dis lui: Vous entendrez de vos oreilles, et vous ne comprendrez pas; vous regarderez de vos yeux, et vous ne verrez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'En effet, ce peuple s\'est épaissi l\'intelligence, il est dur d\'oreille, et il a fermé les yeux, de peur de voir de ses yeux, d\'entendre de ses oreilles, de comprendre avec son intelligence et de se convertir: aussi ne le guérirai-je point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Sachez donc que ce salut de Dieu a été envoyé aux Gentils; pour eux, ils l\'écouteront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '[Quand il eut dit ces mots, les Juifs se retirèrent en disputant vivement entre eux.]');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Paul demeura deux ans entiers dans un appartement qu\'il avait loué, et il recevait tous ceux qui venaient le voir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Il prêchait le royaume de Dieu, et enseignait ce qui regarde le Seigneur Jésus-Christ avec toute liberté et sans aucun empêchement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paul, serviteur de Jésus-Christ, élu apôtre, choisi pour annoncer l\'évangile de Dieu');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '— évangile que Dieu avait déjà promis par ses prophètes, dans les saintes Écritures,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'et qui concerne son Fils (celui qui est issu de la postérité de David, pour la chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'et qui, pour l\'esprit de sainteté, a été désigné Fils de Dieu d\'une manière puissante, par sa résurrection d\'entre les morts) Jésus-Christ, notre Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'par qui nous avons reçu la grâce de l\'apostolat, pour amener en son nom à l\'obéissance de la foi tous les Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'du nombre desquels vous êtes aussi, vous les élus de Jésus-Christ —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'à tous les bien-aimés de Dieu, les élus saints qui sont à Rome: que la grâce et la paix vous soient données par Dieu notre Père et par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'D\'abord, je rends grâces pour vous tous à mon Dieu, par Jésus-Christ, de ce que votre foi est citée dans le monde entier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Dieu, que je sers de toute mon âme, en annonçant l\'évangile de son Fils, m\'est témoin que je ne cesse de faire mention de vous dans mes prières,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'demandant toujours, si enfin j\'aurai bientôt, par sa volonté, le bonheur de me rendre auprès de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'J\'ai un grand désir de vous voir, afin de vous faire part de quelque don spirituel pour vous affermir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'c’est-à-dire, pour me fortifier avec vous par la foi qui nous est commune, à vous et à moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Je ne veux pas vous laisser ignorer, mes frères, que j\'ai souvent formé le projet d\'aller vers vous — mais j\'en ai été empêché jusqu\'ici — afin de produire aussi quelque fruit parmi vous, comme j\'en ai produit chez les autres nations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Je me dois aux Grecs et aux barbares, aux savants et aux ignorants:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'de là mon empressement à vous annoncer aussi l\'évangile, à vous qui êtes à Rome.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Car je n\'ai point honte de l\'évangile; c\'est la puissance de Dieu pour le salut de tout homme qui croit, du Juif d\'abord, puis du Grec');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'parce que la justice qui vient de Dieu par la foi, y est révélée, pour amener à la foi, selon qu\'il est écrit: «Le juste vivra par la foi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'En effet, la colère de Dieu se révèle du ciel contre toute impiété et toute méchanceté des hommes, qui dans leur méchanceté étouffent la vérité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'attendu que ce qu\'on peut connaître de Dieu est manifeste en eux: Dieu le leur a manifesté;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'car les perfections invisibles de Dieu, sa puissance éternelle et sa divinité, se voient comme à l\'oeil, depuis la création du monde, quand on considère ses ouvrages. Ces hommes sont donc inexcusables,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'parce que, ayant conscience de Dieu, ils ne l\'ont ni glorifié, ni béni comme Dieu, mais ont déraisonné dans leurs raisonnements, et leur coeur dépourvu d\'intelligence s\'est enveloppé de ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Se disant sages, ils sont devenus fous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'et ils ont changé la gloire du Dieu immortel en une image semblable à celle de l\'homme mortel, des oiseaux, des quadrupèdes et des reptiles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Aussi Dieu les a-t-il livrés, au milieu des convoitises de leur coeur, à l\'impureté, de sorte qu\'ils déshonorent, eux-mêmes, leurs propres corps;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'eux qui ont changé la vérité de Dieu en mensonge, et ont adoré et servi la créature au lieu du Créateur, qui est béni éternellement. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Aussi Dieu les a-t-il livrés à des passions honteuses: leurs femmes ont changé l\'usage naturel en celui qui est contre nature;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'de même aussi les hommes, laissant l\'usage naturel de la femme, ont, dans leurs désirs, brûlé les uns pour les autres, commettant hommes avec hommes des choses infâmes, et ont reçu en leurs personnes le juste salaire de leur égarement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Comme ils n\'ont pas eu la sagesse de retenir la vraie connaissance de Dieu, Dieu les a livrés à leur mauvais esprit, de sorte qu\'ils font des choses immorales:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'ils sont remplis de toute espèce de vices, de malhonnêteté, de cupidité, de méchanceté; ils sont pleins d\'envie, de meurtre, de dispute, de tromperie, de malignité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'ils sont calomniateurs, détracteurs, impies, insolents, arrogants, vantards, fourbes, enfants rebelles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'sans intelligence, déloyaux, durs, sans pitié;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'et, quoiqu\'ils sachent bien que Dieu a porté une sentence de mort contre ceux qui font de telles choses, non seulement ils les commettent, mais encore ils applaudissent à ceux qui les font.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Ainsi, qui que tu sois, ô homme, toi qui juges, tu es inexcusable; car en jugeant autrui, tu te condamnes toi-même, puisque tu fais les mêmes choses, toi qui juges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Nous savons que le jugement de Dieu contre ceux qui commettent de telles choses est conforme à la vérité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'or, penses-tu, ô homme, toi qui juges ceux qui commettent de telles choses, et qui les fais toi-même, que tu échapperas au jugement de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Méprises-tu les richesses de sa bonté, de sa patience et de sa longanimité, ne reconnaissant pas que la bonté de Dieu t\'invite à la repentance?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Par ton endurcissement et par l\'impénitence de ton coeur, tu t\'amasses un trésor de colère pour le jour de la colère et de la manifestation du juste jugement de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'qui rendra à chacun selon ses oeuvres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'à ceux qui, par leur persévérance dans les bonnes oeuvres, recherchent la gloire, l\'honneur et l\'immortalité, il donnera la vie éternelle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'mais les disputeurs de parti pris, qui sont rebelles à la vérité, et obéissent à l\'injustice, éprouveront sa colère et son courroux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'La détresse et le désespoir tomberont sur toute âme d\'homme qui fait le mal, sur le Juif d\'abord, puis sur le Grec;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'mais la gloire, l\'honneur, la paix seront pour quiconque fait le bien, pour le Juif d\'abord, puis pour le Grec;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'car il n\'y a point d\'acception de personnes devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Tous ceux qui auront péché sans loi, périront aussi sans loi, et tous ceux qui auront péché avec une loi, seront jugés avec cette loi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'car ce ne sont pas ceux qui écoutent une loi, qui sont justes devant Dieu, mais ce sont ceux qui la mettent en pratique, qui seront tenus pour justes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, '(Car, lorsque les Gentils, qui n\'ont pas de loi, font naturellement ce que la Loi commande, n\'ayant pas de loi, ils s\'en tiennent lieu à eux-mêmes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'ils montrent que l\'oeuvre commandée par la Loi est écrite dans leur coeur; au dedans d\'eux, leur conscience le témoigne, et, entre eux, les raisonnements qui condamnent ou même qui absolvent.)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Cela paraîtra au jour où, selon mon évangile, Dieu jugera par Jésus-Christ les actions secrètes des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Or toi, qui te donnes le nom de Juif, qui te reposes sur la Loi, qui es fier de ton Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'qui connais sa volonté et qui sais discerner ce qui s\'en écarte, instruit que tu es par la Loi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'et qui te crois le guide des aveugles, la lumière de ceux qui sont dans les ténèbres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'le docteur des ignorants, le maître des enfants, bien que tu n\'aies que l\'ombre de la science et de la vérité qui se trouvent dans la Loi');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, '— toi donc, qui enseignes les autres, tu ne t\'enseignes pas toi-même! Tu prêches de ne pas dérober, et tu dérobes!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Tu dis de ne pas commettre adultère, et tu commets adultère! Tu as horreur des idoles, et tu t\'en appropries les dépouilles!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Toi qui te vantes d\'avoir une loi, tu déshonores Dieu en la transgressant,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, '«car le nom de Dieu est blasphémé à cause de toi parmi les Gentils,» comme dit l\'Écriture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'La circoncision est utile assurément, si tu pratiques la Loi; mais si tu transgresses la Loi, ta circoncision n\'est plus qu\'une incirconcision.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Si donc l’incirconcis garde les ordonnances de la Loi, son incirconcision ne sera-t-elle pas tenue pour circoncision?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Et l\'incirconcis de naissance qui accomplit la Loi, ne te condamne-t-il pas, toi, transgresseur de la Loi avec ta lettre et ta circoncision?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'On n\'est pas juif par l\'extérieur, et la vraie circoncision n\'est pas celle qui est extérieure, en la chair;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'mais on est juif par l\'intérieur, et la vraie circoncision est la circoncision du coeur, dans l\'esprit, et non selon la lettre de la Loi: ce juif-là tire sa louange, non des hommes, mais de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Quel est donc l’avantage du juif, ou quelle est l\'utilité de la circoncision?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, '— Cet avantage est grand à tous égards: d\'abord, parce que les oracles de Dieu leur ont été confiés?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Car, qu\'est-ce à dire? Si quelques-uns n\'ont pas cru, leur incrédulité annulera-t-elle la fidélité de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, '— Loin de nous cette pensée! mais plutôt que Dieu soit reconnu pour vrai — et tout homme pour menteur — «de sorte, comme il est écrit, que tu sois reconnu juste dans tes paroles, et que tu triomphes, quand on te juge.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mais si notre incrédulité fait éclater la justice de Dieu, que dirons-nous? Dieu n\'est-il pas injuste en nous punissant? (Je parle comme font les hommes.) —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Non, certes; autrement, comment Dieu jugerait-il le monde?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Car, dirait-on, si la véracité de Dieu a été rehaussée, à sa gloire, par mon mensonge, pourquoi, moi aussi, suis-je encore jugé comme pécheur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'et même (comme quelques personnes, qui nous calomnient, nous accusent de le dire) ne ferons-nous pas le mal, pour qu\'il en arrive du bien? — La condamnation de ces gens est juste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Quoi donc? Avons-nous quelque supériorité? — Non, aucune; car nous avons prouvé que tous, tant Juifs que Grecs, sont sous l\'empire du péché,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'ainsi qu\'il est écrit: «Il n\'y a point de juste, pas même un seul;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'il n\'y a point d\'homme qui ait de l’intelligence; il n\'y en a point qui cherche Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Tous se sont dévoyés, ils se sont tous ensemble corrompus. Il n\'y en a point qui fasse le bien, pas même un seul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Leur gosier est un sépulcre béant, leur langue est trompeuse; le venin de l\'aspic est sur leurs lèvres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'leur bouche est pleine de malédiction et d\'amertume.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Ils ont pied léger pour répandre le sang;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'la désolation et la misère sont dans leurs voies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Ils ne connaissent point le chemin de la paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Ils n\'ont point la crainte de Dieu devant les yeux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Or nous savons que tout ce que la loi dit, elle l\'adresse à ceux qui sont sous la loi, afin que toute bouche soit fermée, et que le monde entier soit sous le coup de la justice de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'attendu que nul ne sera justifié devant lui par les oeuvres de la loi, car la loi ne fait que donner la connaissance du péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mais voici, la justice qui vient de Dieu a été manifestée indépendamment de toute loi (la Loi et les Prophètes lui rendent témoignage),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'la justice, dis-je, qui vient de Dieu par la foi en Jésus-Christ, pour tous et sur tous ceux qui ont la foi, indistinctement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'car tous ont péché et sont privés de la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Puisque nous sommes justifiés gratuitement, par la grâce de Dieu, au moyen du pardon qui est en Jésus-Christ');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, '— qui devait être, d\'après le conseil de Dieu, une victime propitiatoire, par la foi en son sang, pour faire voir la justice qui vient de Lui, parce qu\'il avait passé aux hommes leurs péchés commis précédemment, au temps de sa patience,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'pour faire voir, dis-je, à cette époque-ci, la justice qui vient de Lui, en sorte qu\'il est tout ensemble juste et justifiant celui qui a la foi —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'y a-t-il donc là sujet de se glorifier? Toute glorification est exclue. Par quel principe? celui des oeuvres? — Non, mais par le principe de la foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'car nous estimons que l\'homme est justifié par la foi, indépendamment des oeuvres de la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Dieu est-il seulement le Dieu des Juifs? N\'est-il pas aussi le Dieu des Gentils? — Oui, il est aussi le Dieu des Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'puisqu\'il y a un seul Dieu, qui justifiera par la foi le circoncis et l\'incirconcis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Annulons-nous donc la Loi par la foi?— Loin de là; nous la confirmons au contraire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Que dirons-nous donc qu\'Abraham, notre père, a obtenu par la chair?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'car si Abraham a été justifié par les oeuvres, il a sujet de se glorifier. Eh bien! il n\'en a pas sujet devant Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'car que dit l\'Écriture? — «Abraham eut foi en Dieu, et cela lui fut imputé à justice.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Or, on ne considère pas comme une grâce la récompense gagnée par le travail, on la tient pour un dû;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'tandis que pour l\'homme qui ne la gagne pas par son travail, mais qui a foi en celui qui justifie le pécheur, «sa foi lui est imputée à justice.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'C\'est ainsi que David célèbre le bonheur de l\'homme à qui Dieu impute la justice indépendamment des oeuvres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '«Heureux ceux dont les fautes ont été pardonnées, et dont les péchés ont été couverts!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Heureux l\'homme à qui le Seigneur n\'impute pas son péché!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ce bonheur est-il pour le circoncis seulement, ou s\'applique-t-il aussi à l\'incirconcis? nous disons, en effet, «que la foi fut imputée à justice à Abraham.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Comment donc lui fut-elle imputée? Était-ce en l\'état de circoncision, ou en l\'état d\'incirconcision? — Ce n\'était pas en l\'état de circoncision; c\'était en celui d\'incirconcision;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'puis, il reçut le signe de la circoncision, comme sceau de la justice que lui avait procurée sa foi, lorsqu\'il était incirconcis. Il est ainsi le père de tous ceux qui ont la foi avec l\'incirconcision, pour que la justice leur soit aussi imputée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'et le père des circoncis, de ceux du moins qui ne s\'en tiennent pas à la circoncision seulement, mais qui marchent aussi sur les traces de la foi, qu\'avait notre père Abraham, lorsqu\'il était incirconcis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'En effet, ce n\'est point par une loi que la promesse d\'hériter le monde a été faite à Abraham et à sa postérité, mais c\'est par la justice que procure la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Car, si ceux qui s\'en tiennent à la loi, sont héritiers, la foi devient inutile, et la promesse de Dieu, sans effet;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'parce que la loi produit la colère, mais où il n\'y a pas de loi, il n\'y a pas non plus de transgression.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Aussi est-ce par la foi qu\'on est héritier, afin que ce soit par grâce; de sorte que la promesse est assurée à toute la postérité d\'Abraham, non seulement à celle qui relève de la Loi, mais encore à celle qui relève de la foi d\'Abraham. Il est notre père à tous, ainsi qu\'il est écrit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '«Je t’ai fait père d\'un grand nombre de nations,» et cela devant Dieu, en qui il eut foi, — Dieu, qui donne la vie aux morts, et qui nomme les choses qui ne sont pas, comme si elles étaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Espérant contre toute espérance, il eut foi: c\'est ainsi qu\'il devint le père de beaucoup de nations, selon cette parole: «Telle sera ta postérité.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Comme il n\'était point faible en la foi, il ne considéra point que son corps était déjà éteint (il était presque centenaire), ni que Sarah était vieille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Il n\'eut ni hésitation ni défiance à l\'égard de la promesse de Dieu; mais, puisant sa force dans sa foi, il donna gloire à Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'pleinement convaincu que, ce qu\'il a promis, il est puissant aussi pour l\'exécuter:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'c\'est pour cette raison que «sa foi lui fut imputée à justice.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Or ce n\'est pas pour lui seul qu\'il est écrit «qu\'elle lui fut imputée,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'mais c\'est aussi pour nous, à qui elle doit être imputée, pour nous qui avons foi en Celui qui a ressuscité des morts Jésus, notre Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'lequel a été livré pour nos fautes, et est ressuscité pour notre justification.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Étant donc justifiés par la foi, nous avons la paix avec Dieu par notre Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'à qui nous devons, soit d\'avoir eu accès par la foi à cette grâce que nous possédons, soit de nous glorifier dans l\'espérance de la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Bien plus, nous nous glorifions même dans les afflictions, sachant que l\'affliction produit la constance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, '— la constance, une vertu éprouvée, — la vertu éprouvée, l\'espérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Et cette espérance n\'est point trompeuse, parce que le sentiment de l\'amour de Dieu pour nous est répandu dans nos coeurs par l’Esprit-Saint qui nous a été donné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'En effet, lorsque nous étions encore faibles, même alors Christ est mort, au temps voulu, pour des pécheurs:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'c\'est difficilement qu\'on mourra pour un juste, car il se peut encore qu\'on ait le courage de mourir pour un homme de bien;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'mais Dieu a fait éclater son amour pour nous, en ce que, lorsque nous étions encore pécheurs, Christ est mort pour nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Maintenant donc que nous sommes justifiés par son sang, à plus forte raison serons-nous sauvés par lui de la colère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Car si, d\'ennemis que nous étions, nous nous sommes réconciliés avec Dieu par la mort de son Fils, à combien plus forte raison, étant réconciliés, serons-nous sauvés par sa vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Bien plus, nous nous glorifions en Dieu, par notre Seigneur Jésus-Christ, par qui maintenant nous avons obtenu la réconciliation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'En conséquence, de même que par un seul homme le Péché est entré dans le monde, et par le Péché, la mort; et qu\'ainsi la mort a passé sur tous les hommes, parce que tous ont péché;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '— car, jusqu’à la Loi, le péché était dans le monde; or, le péché n\'est pas porté en compte, s\'il n\'y a pas de loi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'mais la mort a régné d\'Adam à Moïse, même sur ceux qui n\'avaient pas péché par une transgression semblable à celle d\'Adam, qui est une figure de ce qui devait arriver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mais il n\'en est pas de la faute comme du bienfait; car si, par la faute d\'un seul, la plupart sont morts, à bien plus forte raison la grâce de Dieu et le don que nous devons au seul homme Jésus-Christ, se sont-ils répandus sur un plus grand nombre de personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Il y a encore cette différence entre ce qui arrive par un seul homme qui a péché, et le bienfait; c\'est que le jugement entraîne condamnation pour une seule faute commise, tandis que la sentence de grâce amène l\'absolution de beaucoup de fautes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'En effet, si, par la faute d\'un seul, la mort a régné par ce seul homme, à bien plus forte raison ceux qui acceptent l\'immense grâce de Dieu et le don de la justice, règneront-ils en la vie par le seul Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Ainsi donc, comme par la faute d\'un seul, la condamnation s\'est étendue sur tous les hommes, ainsi le bienfait d\'un seul s\'étendra sur tous les hommes en sentence de vie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'car, comme par la désobéissance d\'un seul homme, la plupart ont été rendus pécheurs, ainsi par l\'obéissance d\'un seul homme la plupart seront rendus justes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Or la loi est intervenue, afin que la faute abondât, mais là où le péché a abondé, la grâce a plus que surabondé;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'afin que, de la même manière que le Péché a régné en donnant la mort, ainsi la Grâce règne, par la justice, en amenant à la vie éternelle par Jésus-Christ, notre Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Que dirons-nous donc? Dirons-nous: Persistons dans le péché, afin que la grâce abonde?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, '— Dieu nous en garde! Nous qui sommes morts au péché, comment vivrions-nous encore dans le péché?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ignorez-vous, que nous tous qui avons été baptisés en Jésus-Christ, c\'est en sa mort que nous avons été baptisés?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Nous avons donc été ensevelis avec lui par notre baptême en sa mort, afin que, de même que Jésus-Christ est ressuscité des morts par la gloire du Père, nous aussi, de même, nous ressuscitions et marchions en nouveauté de vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'S\'il est vrai, en effet, qu\'unis à lui, nous ayons reproduit l\'image de sa mort, nous reproduirons aussi l\'image de sa résurrection;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'comprenant que le vieil homme, en nous, a été crucifié avec lui, afin que le corps du péché soit anéanti, de sorte que nous ne soyons plus les esclaves du péché:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'car celui qui est mort au péché, est exempt de péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Or, si nous sommes morts avec Christ, nous avons la conviction que nous vivrons aussi avec lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'sachant que Christ ressuscité des morts ne meurt plus, la mort n\'ayant plus d\'empire sur lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'car la mort dont il est mort, c\'est la mort, une fois pour toutes, au péché, et la vie dont il vit, c\'est la vie pour Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'vous aussi, de même, considérez-vous comme morts au péché, et comme vivant pour Dieu, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Que le Péché ne règne donc point dans votre corps mortel, de sorte que vous obéissiez à ses passions;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'et n\'abandonnez pas vos membres au Péché, comme des instruments de perversité. Mais donnez-vous, vous-mêmes, à Dieu, comme étant vivants, de morts que vous étiez; et consacrez-lui vos membres comme des instruments de justice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Car le Péché n\'aura plus d\'empire sur vous, attendu que vous n\'êtes pas sous la loi, mais sous la grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Quoi donc? Pécherons-nous, parce que nous sommes, non sous la loi, mais sous la grâce?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, '— Dieu nous en garde! Ne savez-vous pas que vous êtes les esclaves de celui à qui vous vous êtes donnés comme esclaves, et à qui vous obéissez? Eh bien! ou vous êtes les esclaves du Péché, ce qui conduit à la mort, ou vous êtes les esclaves de l\'obéissance à Dieu, ce qui conduit à la justice:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'mais, grâces soient rendues â Dieu, de ce que, après avoir été les esclaves du Péché, vous vous êtes soumis de coeur au modèle de doctrine qui vous a été enseigné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Or, ayant été affranchis du Péché, vous êtes devenus les esclaves de la justice');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, '— humainement parlant, à cause de la faiblesse de votre chair. Eh bien! comme vous faisiez de vos membres les esclaves de l\'impureté et du dérèglement, ce qui n\'aboutissait qu\'à la vie déréglée; de même, faites-en maintenant les esclaves de la justice, pour devenir saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Car, lorsque vous étiez les esclaves du Péché, vous étiez libres à l\'égard de la justice: aussi, quels fruits portiez-vous alors?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, '— Des fruits dont vous avez honte maintenant, car la fin de ces choses, c\'est la mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'mais aujourd\'hui que vous êtes affranchis du Péché et que vous êtes devenus les esclaves de Dieu, vous portez votre fruit de manière à être saints, et vous avez pour fin la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Car le salaire du péché, c\'est la mort; mais la grâce de Dieu, c\'est la vie éternelle en Jésus-Christ, notre Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Vous n\'ignorez pas, mes frères, (car je m\'adresse à des gens qui connaissent la loi) que l\'homme est sous l\'empire de la loi, aussi longtemps qu\'il vit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'La femme mariée, par exemple, est liée par la loi à son mari, tant qu\'il est vivant; mais si son mari meurt, elle est dégagée de la loi qui la liait à son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Ainsi donc, on l\'appellera adultère, si, du vivant de son mari, elle se donne à un autre homme; mais, si son mari meurt, elle est affranchie de la loi, en sorte qu\'elle n\'est point adultère, si elle se donne à un autre mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Vous, de même, mes frères, on vous a fait mourir à la loi au moyen de la personne de Christ, pour que vous vous donniez à un autre, à celui qui est ressuscité des morts; afin que nous portions des fruits pour Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'En effet, lorsque nous vivions selon la chair, les passions, qui engendrent les péchés, éveillées par la loi, déployaient leur puissance dans nos membres, de sorte que nous portions des fruits pour la mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'mais maintenant, nous avons été dégagés de la loi, étant morts à la loi, sous l\'autorité de laquelle nous étions tenus, de sorte que nous servons Dieu dans un esprit nouveau, et non suivant une lettre surannée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Que dirons-nous donc? La loi est-elle péché? — Non, sans doute; mais je n\'aurais certainement pas connu le péché, si une loi ne me l\'avait fait connaître: par exemple, je n\'aurais pas connu la convoitise, si la loi n\'avait dit: «Tu ne convoiteras point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Puis, le Péché en ayant pris occasion, a fait naître en moi, par le commandement, toutes sortes de convoitises; car sans loi, le Péché est mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Pour moi, autrefois étant sans loi, je vivais; mais le commandement étant venu, le Péché a pris vie, et moi, je suis mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'de sorte qu\'il s\'est trouvé que le commandement même qui devait me donner la vie, m\'a donné la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Le Péché, en effet, ayant saisi l\'occasion, m\'a séduit par le commandement, et m\'a donné la mort par ce commandement même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Ainsi la loi est bien sainte, et le commandement saint, juste et bon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Une chose bonne m\'aurait donc donné la mort? — Non, sans doute; mais c\'est le Péché qui m\'a donné la mort, afin de se montrer péché, en me donnant la mort par le moyen d\'une chose bonne, afin même de se développer à l\'excès par le moyen du commandement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'En effet, nous savons que la loi est spirituelle, mais c\'est moi qui suis charnel, vendu au Péché;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'car je ne sais ce que je fais: je ne fais pas ce que je veux, et je fais ce que je hais;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'or, si je fais ce que je ne veux pas, je reconnais que la loi est bonne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Ce n\'est donc plus moi qui le fais, mais c\'est le Péché qui habite en moi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'en effet, je sais que le bien n\'habite pas en moi, c’est-à-dire, en ma chair, car vouloir le bien est en mon pouvoir, mais l\'exécuter, non;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'puisque je ne fais pas le bien que je veux, mais que je fais le mal que je ne veux pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Or, si je fais ce que je ne veux pas, ce n\'est plus moi qui le fais, mais c\'est le Péché qui habite en moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Je trouve donc cette loi en moi, c\'est que, lorsque je veux faire le bien, le mal est là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'En effet, je prends plaisir à la loi de Dieu, selon l\'homme intérieur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'mais je vois dans mes membres une autre loi qui lutte contre la loi de ma raison, et fait de moi le captif de la loi du Péché, laquelle est dans mes membres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Malheureux que je suis! qui me délivrera du corps qui cause cette mort?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, '— Ah! grâces soient rendues à Dieu, par Jésus-Christ, notre Seigneur! Ainsi donc, moi-même, par l\'intérieur, je suis esclave de la loi de Dieu; mais par la chair, je suis esclave de la loi du Péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Il n\'y a donc maintenant aucune condamnation pour ceux qui sont en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'En effet, la loi de l\'esprit, qui donne la vie en Jésus-Christ, m\'a affranchi de la loi du Péché et de la mort; car ce qui était impossible à la loi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'parce que la chair la rendait impuissante, Dieu l\'a fait: en envoyant, à cause du péché, son propre Fils, dans une chair semblable à la chair de péché, il a prononcé la sentence de mort du Péché dans la chair même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'afin que la justice ordonnée par la loi soit réalisée en nous, qui marchons, non selon la chair, mais selon l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'En effet, ceux qui vivent selon la chair, s\'affectionnent aux choses de la chair, tandis que ceux qui vivent selon l\'esprit, s\'affectionnent aux choses de l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Or les affections de la chair, c\'est la mort, tandis que les affections de l\'esprit, c\'est la vie et la paix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'attendu que les affections de la chair sont inimitié contre Dieu, car elles ne sont pas soumises à Dieu, elles ne peuvent même pas se soumettre à Lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Ceux qui vivent selon la chair ne peuvent plaire à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Pour vous, vous ne vivez pas selon la chair, mais vous vivez selon l\'esprit, si toutefois l\'Esprit de Dieu habite en vous. Si quelqu\'un n\'a pas l\'Esprit de Christ, il ne lui appartient pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'mais si Christ est en vous, le corps est mort à cause du péché, et l\'esprit est vie à cause de la justice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Et si l\'Esprit de Celui qui a ressuscité Jésus d\'entre les morts habite en vous, Celui qui a ressuscité Christ d\'entre les morts, donnera aussi la vie à vos corps mortels, parce que son Esprit habite en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Ainsi donc, mes frères, nous ne sommes point redevables à la chair, pour vivre selon la chair;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'car si vous vivez selon la chair, vous mourrez, mais si, par l\'esprit, vous faites mourir les actions auxquelles la chair sollicite, vous vivrez;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'car tous ceux qui sont conduits par l\'Esprit de Dieu, sont fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'En effet, vous n\'avez pas reçu un esprit d\'esclavage, pour être encore dans la crainte, mais vous avez reçu un esprit filial, par lequel nous crions: «Abba! Père!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Cet esprit même témoigne à notre esprit que nous sommes enfants de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, '— Et, si nous sommes enfants, nous sommes aussi héritiers, héritiers de Dieu et cohéritiers de Christ, si toutefois nous souffrons avec lui, afin d\'être aussi glorifiés avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'J\'estime que les souffrances du temps présent ne sont rien au prix de la gloire qui nous doit advenir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Car la Création dans l\'attente, attend l\'apparition des fils de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'en effet, la Création a été assujettie à la vanité — non de son gré, mais par la volonté de Celui qui l\'y a soumise —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'avec l\'espérance qu\'elle aussi, la Création, sera affranchie de l\'esclavage de la corruption, pour avoir part à la liberté de la gloire des enfants de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Car nous savons que toute la Création gémit et souffre jusqu’à présent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'et non seulement elle, mais nous-mêmes aussi, quoique nous ayons les prémices de l\'Esprit, nous-mêmes aussi, nous gémissons intérieurement, attendant d\'être adoptés, délivrés de notre corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'En effet, c\'est en espérance que nous sommes sauvés; or, quand on voit ce qu\'on espère, ce n\'est pas espérance; car espère-t-on encore ce qu\'on voit?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'mais, si nous espérons ce que nous ne voyons pas, nous l\'attendons avec patience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'L\'Esprit aussi vient pareillement en aide à notre faiblesse: lorsque nous ne savons que demander, ni comment demander, l\'Esprit intercède par de muets soupirs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'et Celui qui sonde les coeurs, connaît quels sont les désirs de l\'Esprit, il sait qu\'il intercède, selon Dieu, pour des saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Nous savons, d\'ailleurs, que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui ont été appelés conformément à son plan,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'savoir que ceux qu\'il a prédestinés et désignés d\'avance pour être semblables à l\'image de son Fils, en sorte qu\'il soit l\'aîné d\'un grand nombre de frères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'que ceux, dis-je, qu\'il a désignés d\'avance, il les a aussi appelés, — que ceux qu\'il a appelés, il les a aussi justifiés, — que ceux qu\'il a justifiés, il les a aussi glorifiés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Que dirons-nous donc à ce propos? Si Dieu est pour nous, qui sera contre nous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Lui qui n\'a pas épargné son propre Fils, mais qui l\'a livré à la mort pour nous tous, comment ne nous accordera-t-il pas aussi toutes choses avec lui?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, '— Qui accusera les élus de Dieu? Dieu les justifie!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, '— Qui les condamnera? Christ est mort! Bien mieux, il est ressuscité, il est à la droite de Dieu, il intercède pour nous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, '— Qui nous arrachera à l\'amour de Christ? sera-ce l\'affliction, la détresse, la persécution, la faim, le dénûment, le péril, l\'épée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'car, «à cause de toi, comme dit l\'Ecriture, on nous met à mort tout le jour, on nous tient pour des brebis de boucherie?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Mais, dans toutes ces calamités, nous sommes plus que vainqueurs par celui qui nous a aimés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'car je suis assuré que ni la mort, ni la vie, ni anges, ni archanges, ni choses présentes, ni choses à venir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ni puissances, ni hauteurs, ni abîmes, ni rien au monde, ne pourra nous séparer de l\'amour que Dieu nous a témoigné en Jésus-Christ, notre Seigneur!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Je dis la vérité, en Christ, je ne mens point; ma conscience que le Saint-Esprit anime m\'en rend le témoignage:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'j\'ai un grand chagrin et une douleur incessante au coeur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'car je souhaiterais d\'être moi-même anathème, loin de Christ, pour mes frères, mes parents selon la chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'qui sont Israélites, à qui appartiennent l\'adoption, la gloire, les alliances, la Loi, le culte et les promesses;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'à qui appartiennent les patriarches, et desquels est issu le Messie, du moins pour la chair. Que celui qui gouverne toutes choses, Dieu, en soit béni éternellement! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Toutefois, en m\'exprimant ainsi, je n\'entends point que la promesse de Dieu ait failli. En effet, tous ceux qui sont issus d\'Israël ne sont pas pour cela Israël;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'et même, pour être la postérité d\'Abraham, ils ne sont pas tous enfants d\'Abraham, mais il est écrit: «C\'est la postérité d\'Isaac qui sera dite ta postérité; »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'c’est-à-dire, que ce ne sont pas les enfants de la chair qui sont enfants de Dieu, mais que ce sont les enfants de la promesse qui sont considérés comme la postérité d’Abraham;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'car voici les termes de la promesse: «Je viendrai en cette même saison, et Sarah aura un fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Ce n\'est pas tout: il en fut de même pour Rébecca, qui conçut d\'un seul homme, Isaac notre père;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'car — quoique les enfants ne fussent pas encore nés, et qu\'ils n\'eussent fait ni bien ni mal — afin que le plan de Dieu, lequel procède par choix, subsistât, non en vertu des oeuvres, mais par la volonté de Celui qui appelle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'il fut dit à Rébecca: «L’ainé sera assujetti au plus jeune,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'selon qu\'il est écrit: «J\'ai aimé Jacob et j’ai haï Ésaü.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que dirons-nous donc? Y a-t-il de l\'injustice en Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, '— Loin de nous cette pensée! car il dit à Moïse: «Je ferai miséricorde à qui il me plaira de faire miséricorde, et j’aurai compassion de qui il me plaira d\'avoir compassion.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Ainsi donc, cela ne dépend ni de celui qui veut, ni même de celui qui court, mais de Dieu qui fait miséricorde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'car l\'Écriture dit à Pharaon: «Je t’ai suscité tout exprès, pour faire voir en toi ma puissance, et pour que mon nom soit publié dans toute la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Ainsi donc, il fait miséricorde à qui il veut, et il endurcit qui il veut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Tu me diras: De quoi donc se plaint-il encore? car qui s\'oppose à sa volonté?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, '— Ah! bien plutôt, ô homme, qui es-tu, toi qui contestes avec Dieu? Le vase d\'argile dira-t-il à celui qui l\'a fabriqué: «Pourquoi m\'as-tu fait ainsi?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Le potier n\'a-t-il pas le droit de faire de la même masse d\'argile des vases pour des usages honorables, et d\'autres pour des usages vils?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Or, si Dieu, tout en voulant montrer sa colère et faire connaître sa puissance, a supporté avec une grande longanimité des vases, objets de sa colère, faits pour la ruine,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'et, afin de faire connaître les richesses de sa gloire envers des vases, objets de sa miséricorde, qu\'il a réservés d\'avance pour la gloire,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'nous a aussi appelés, non seulement d\'entre les Juifs, mais aussi d\'entre les Gentils, n\'en a-t-il pas le droit?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'C\'est ainsi qu\'il dit dans Osée: «Celui qui n’est pas mon peuple, je l\'appellerai mon peuple, et celle qui n\'est pas bien-aimée, je l’appellerai bien-aimée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'et il arrivera que, dans le lieu où on leur aura dit, «vous n\'êtes point mon peuple,» là même on les appellera fils du Dieu vivant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'D\'autre part, Ésaïe s\'écrie au sujet d\'Israël: «Quand le nombre des fils d\'Israël serait comme le sable de la mer, un faible reste seulement sera sauvé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'En effet, ce qu\'il dit, il le réalise pleinement et rapidement dans sa justice, car le Seigneur va exécuter, et exécuter rapidement sa parole sur la terre,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'et, comme Esaïe l\'avait déjà dit: «Si le Seigneur des armées ne nous avait laissé une semence, nous aurions été comme Sodome, et nous aurions ressemblé à Gomorrhe.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que dirons-nous donc? — Nous dirons que les Gentils, qui ne cherchaient pas la justice, ont obtenu la justice, la justice qui vient de la foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'tandis qu\'Israël, qui cherchait un principe de justice, n\'est point parvenu à le trouver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Et pourquoi? — Parce qu\'il l\'a cherché, non par la foi, mais vainement par les oeuvres. En effet, il est allé se heurter contre la pierre d\'achoppement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'selon qu\'il est écrit: «Voici, je pose en Sion une pierre d\'achoppement et un rocher qui fait trébucher, mais celui qui met en lui sa confiance, ne sera point confus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Mes frères, le voeu de mon coeur et ma prière à Dieu pour eux, c\'est qu\'ils soient sauvés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'car je leur rends le témoignage qu\'ils ont du zèle pour Dieu, mais c\'est un zèle mal éclairé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'En méconnaissant la justice qui vient de Dieu, et en cherchant à établir leur propre justice, ils ne se sont pas soumis à la justice qui vient de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'car Christ est la fin de la loi, en vue même de la justice, pour tout homme qui a la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'En effet, Moïse caractérise comme suit la justice qui vient de la loi: «Celui qui observera ces commandements, obtiendra la vie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'tandis que la Justice qui vient de la foi s\'exprime ainsi: «Ne dis pas en ton coeur, «qui montera au ciel?» (c\'est en faire descendre Christ)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, '«ni qui descendra dans l’abîme?» (c\'est faire monter Christ de chez les morts).');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mais que dit-elle? - «Ce qu\'elle dit est près de toi, dans ta bouche, dans ton coeur,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'c\'est la parole de la foi que nous prêchons; elle dit que si ta bouche confesse Jésus pour Seigneur, et que tu croies en ton coeur que Dieu l’a ressuscité des morts, tu seras sauvé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'En effet, la foi de coeur conduit à la justice, et la confession débouche, au salut;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'car l\'Écriture dit: «Quiconque a foi en lui, ne sera point confus,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Il n\'y a pas de distinction entre Juifs et Grecs, parce que ce même Christ est le Seigneur de tous les hommes, étant riche pour tous ceux qui l\'invoquent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'car «quiconque invoquera le nom du Seigneur sera sauvé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Comment donc invoquera-t-on celui en qui l\'on n\'a pas encore cru? Et comment croira-t-on en celui dont on n\'a pas entendu parler? Et comment en entendra-t-on parler, si quelqu\'un ne prêche?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Et comment prêchera-t-on, si quelqu\'un n\'est envoyé, selon qu\'il est écrit: «Qu\'ils sont beaux les pieds de ceux qui annoncent la paix, de ceux qui annoncent les bonnes nouvelles?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, '— Mais tous ne l\'ont pas écoutée, la bonne nouvelle, car Ésaïe dit: «Seigneur, qui a ajouté foi à notre prédication?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Ainsi donc, la foi vient de ce qu\'on entend, et l\'on entend par l\'ordre de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mais je demande: «N\'auraient-ils pas entendu prêcher?» - Ah! bien au contraire; «la voix des messagers a retenti par toute la terre, et leurs paroles sont parvenues jusqu\'aux extrémités du monde.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Je demande encore: «Israël n\'aurait-il pas eu connaissance de l’ordre de Dieu?» — Moïse, le premier, a dit: «Je vous rendrai jaloux d\'une nation qui n\'en est pas une; je provoquerai votre colère contre une nation sans intelligence;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'et Esaïe va même jusqu’à dire: «Je me suis laissé trouver par ceux qui ne me cherchaient point; je me suis fait connaître à ceux qui ne me demandaient point;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'tandis qu\'il dit en parlant d\'Israël: «J\'ai tout le jour tendu les bras à un peuple rebelle et récalcitrant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Je dis donc: «Dieu a-t-il rejeté son peuple?» — Non, sans doute: moi, par exemple, je suis bien Israélite, de la postérité d\'Abraham, de la tribu de Benjamin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Non, Dieu n\'a point rejeté son peuple, le peuple qu\'il avait prédestiné pour être sien. Ne savez-vous pas ce que dit l\'Ecriture dans le passage où il est parlé d\'Élie? comment ce prophète porte plainte à Dieu contre Israël:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '«Seigneur, ils ont tué tes prophètes, ils ont renversé tes autels; je suis resté seul, et ils en veulent à ma vie?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mais que lui répond la voix divine? — «Je me suis réservé sept mille hommes, qui n\'ont pas fléchi le genou devant Bahal.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Eh bien! de même dans la circonstance actuelle, un reste subsiste par un choix de grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Or, si c\'est par grâce, ce n\'est plus par les oeuvres; autrement, la grâce n\'est plus grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Qu\'est-il donc arrivé? — Ce qu\'Israël recherche, il ne l\'a point obtenu; toutefois l\'élite l\'a obtenu, tandis que tous les autres se sont aveuglés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'ainsi qu\'il est écrit: «Dieu leur a donné jusqu’à ce jour un esprit d\'étourdissement, des yeux pour ne point voir, et des oreilles pour ne point entendre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'David dit aussi: «Que leur table leur soit un piège, un lac, un trébuchet, et une juste punition;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'que leurs yeux s\'obscurcissent de sorte qu\'ils ne voient point: tiens leur dos constamment courbé.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Je dis donc: «Ont-ils bronché, afin de tomber?» — Non, sans doute: mais, par leur faute, le salut a été pour les Gentils, de manière à exciter la jalousie d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Or, si leur faute a été la richesse du monde, et leur échec, la richesse des Gentils, que ne sera pas leur conversion en masse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'En effet, je vous le dis, à vous Gentils: moi-même, en tant qu\'apôtre des Gentils, je m\'efforce de rendre mon ministère glorieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'afin, s\'il est possible, d\'exciter la jalousie de ceux de mon sang, et d\'en sauver quelques-uns;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'car si leur rejet a été la réconciliation du monde, que sera leur réhabilitation, sinon la vie surgissant du sein des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Or, si les prémices de la pâte sont saintes, la masse l\'est aussi; si la racine est sainte, les branches le sont également.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Toutefois, si quelques-unes des branches ont été retranchées, tandis que toi, qui n\'es qu\'un sauvageon, tu as été enté sur l\'olivier, de sorte que tu participes à sa racine et à sa graisse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'garde-toi de traiter ces branches avec hauteur; si tu le fais, sache que ce n\'est pas toi qui portes la racine, mais que c\'est la racine qui te porte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu diras donc: «Ces branches ont été retranchées, afin que je fusse enté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, '— D\'accord: c\'est pour leur incrédulité qu\'elles ont été retranchées, et, toi, tu es là, pour ta foi. Ne t\'enorgueillis pas, mais crains:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'si Dieu n\'a pas épargné les branches naturelles, crains qu\'il ne t\'épargne pas non plus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Considère donc la bonté et la sévérité de Dieu, sa sévérité envers ceux qui sont tombés, et sa bonté envers toi, pourvu que tu te maintiennes dans sa bonté; autrement, tu seras aussi retranché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Eux aussi, s\'ils ne persistent pas dans leur incrédulité, ils seront entés, car Dieu est puissant pour les enter de nouveau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'et si toi, qui as été coupé sur un olivier de nature sauvage, tu as été enté, malgré ta nature, sur un olivier franc, combien plus eux, qui, de nature, sont francs, seront-ils entés sur leur propre olivier?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'En effet, je ne veux pas, mes frères, que vous ignoriez ce mystère-ci, afin que vous n\'ayez pas une haute opinion de vous-mêmes: c\'est que l\'aveuglement qui s\'est emparé d\'une partie d\'Israël, durera jusqu’à ce que la masse des Gentils soit entrée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'et alors tout Israël sera sauvé, selon qu\'il est écrit: «Le libérateur viendra de Sion, il éloignera de Jacob ses impiétés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Et voici l\'alliance que je leur octroierai: j’ôterai leurs péchés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'En ce qui concerne l\'évangile, ils sont ennemis, à cause de vous; mais en ce qui concerne leur élection, ils sont aimés, à cause de leurs pères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'car les faveurs et l\'appel de Dieu sont choses dont Dieu ne se repent pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'De même que vous avez jadis désobéi à Dieu, et que maintenant vous avez obtenu miséricorde par le fait de leur désobéissance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'de même, ils ont maintenant désobéi, afin que, par le fait de la miséricorde dont vous êtes les objets, ils obtiennent aussi miséricorde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'car Dieu a enveloppé tous les hommes dans la désobéissance, afin de faire à tous miséricorde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O profondeur de la richesse, de la sagesse et de la science de Dieu! Que ses jugements sont mystérieux et ses voies impénétrables!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, '«Car, qui a connu la pensée du Seigneur, ou qui a tenu conseil avec lui?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'ou bien, «qui lui a rien donné le premier, qu\'il doive recevoir quelque chose en retour?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Toutes choses viennent de lui; elles sont par lui et pour lui: à lui soit la gloire aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Je vous invite donc, mes frères, par les compassions de Dieu, à offrir vos personnes en sacrifice vivant, saint, agréable à Dieu: c\'est là le culte spirituel que vous lui devez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Ne vous modelez pas sur le siècle présent, mais qu\'il se fasse en vous une métamorphose par le renouvellement de l\'esprit, en sorte que vous appréciiez ce qu\'est la volonté de Dieu, combien elle est bonne, agréable et parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Je dis à chacun de vous, en vertu de la grâce qui m\'a été donnée, de ne pas avoir une opinion trop avantageuse de soi-même, mais de s\'appliquer à avoir des sentiments modestes, chacun selon la mesure de foi que Dieu lui a départie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Car, de même que dans un seul corps nous avons plusieurs membres, et que tous les membres n\'ont pas la même fonction;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'de même, nous qui sommes plusieurs, nous ne faisons qu\'un seul corps en Christ, et nous sommes tous membres les uns des autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Mais nous avons des dons différents suivant la grâce qui nous a été donnée: nous avons suivant l\'analogie de la foi, soit la prophétie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'soit le ministère dans le diaconat; nous avons aussi le docteur qui se livre à l\'enseignement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'et celui qui exhorte, qui s\'adonne à l\'exhortation. Que celui qui donne, le fasse avec générosité; que celui qui préside, y mette du soin; que celui qui prend pitié, secoure avec joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que votre charité soit sans hypocrisie. Haïssez le mal; attachez-vous fortement au bien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Quant à l\'amour fraternel, soyez pleins d\'affection les uns pour les autres; quant à l\'honneur, prévenez-vous les uns les autres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'quant au zèle, ne soyez pas nonchalants. Soyez fervents d\'esprit; servez le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Que l\'espérance vous rende joyeux; soyez patients dans l\'affliction, persévérants dans la prière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Subvenez aux besoins des saints; exercez l\'hospitalité avec empressement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Bénissez ceux qui vous persécutent: bénissez, et ne maudissez pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Réjouissez-vous avec ceux qui sont dans la joie; pleurez avec ceux qui pleurent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Soyez en bonne intelligence les uns avec les autres. N\'aspirez pas aux choses élevées, mais laissez-vous gagner par ce qui est humble. N\'ayez pas une haute opinion de vous-mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Ne rendez à personne le mal pour le mal. Ayez soin de faire ce qui est bien aux yeux de tous les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'S\'il est possible, et autant qu\'il dépend de vous, vivez en paix avec tout le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne vous vengez point vous-mêmes, mes bien-aimés, mais laissez agir la colère de Dieu; car il est écrit: «A moi la vengeance; à moi de rétribuer,» dit le Seigneur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Si ton ennemi a faim, donne-lui à manger; s\'il a soif, donne-lui à boire; car en agissant de la sorte tu amasseras des charbons de feu sur sa tête.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne te laisse point vaincre par le mal, mais surmonte le mal par le bien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toute personne soit soumise aux puissances régnantes, car il n\'y a point de puissance qui ne vienne de Dieu, et celles qui existent sont instituées par lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'ainsi celui qui s\'oppose à l\'autorité, s\'élève contre l\'ordre que Dieu a établi. Ceux qui s\'opposent à l\'autorité, s\'attireront une peine,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'parce que les magistrats sont redoutables, non à ceux qui font le bien, mais à ceux, qui font le mal. Veux-tu ne pas craindre l\'autorité, fais le bien, et tu auras son approbation;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'car le magistrat est le ministre de Dieu pour faire régner le bien. Mais si tu fais le mal, crains; car il ne porte pas l\'épée en vain, il est le ministre de Dieu, pour tirer vengeance de celui qui fait le mal, et le punir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'En conséquence il faut être soumis, non seulement dans la crainte de la punition, mais encore par motif de conscience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'C\'est aussi pour cette raison que vous payez les impôts, car les magistrats sont les fonctionnaires de Dieu en s\'acquittant de cet office avec persévérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Rendez à tous ce que vous leur devez: l\'impôt, à qui vous devez l\'impôt; le cens, à qui vous devez le cens; la crainte, à qui vous devez la crainte; l\'honneur, à qui vous devez l\'honneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'N\'ayez de dettes envers personne, excepté la dette de l\'amour mutuel, car celui qui aime le prochain, a accompli la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'En effet, les commandements: «Tu ne commettras point adultère, tu ne tueras point, tu ne déroberas point, tu ne convoiteras point,» et tout autre commandement qu\'on pourrait citer, se résument dans cette parole: «Tu aimeras ton prochain comme toi-même,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'L\'amour ne fait point de mal au prochain; l\'amour est donc l\'accomplissement de la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Cela importe d\'autant plus, que vous connaissez l\'époque où nous sommes: vous savez que l\'heure est venue de nous réveiller enfin du sommeil, car le salut est maintenant plus proche de nous que lorsque nous avons embrassé la foi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'la nuit est avancée, le jour approche. Dépouillons-nous donc des oeuvres des ténèbres, et revêtons les armes de la lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Marchons avec bienséance, comme on marche en plein jour. Fuyez les excès de la table et du vin, la débauche et les désordres, les querelles et les haines;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'revêtez-vous, au contraire, du Seigneur Jésus-Christ, et ne prenez pas soin de la chair, de manière à en éveiller les désirs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Quant à celui qui est faible en la foi, accueillez-le, sans vous mettre à juger ses pensées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'L\'un croit qu\'on peut manger de tout, tandis que le faible se nourrit de légumes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Que celui qui mange de tout, ne méprise pas celui qui ne mange pas de tout; et que celui qui ne mange pas de tout, ne juge pas celui qui mange de tout, puisque Dieu l\'a accueilli.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Qui es-tu, toi qui juges le serviteur d\'autrui? S\'il se tient debout, ou s\'il tombe, c\'est l\'affaire de son maître; mais il se tiendra debout, car le Seigneur a la puissance de le soutenir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'L\'un juge un jour plus saint qu\'un autre, l\'autre les juge tous pareils; que chacun soit bien convaincu en son esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Celui qui s\'attache à tel ou à tel jour, le fait pour le Seigneur; et celui qui mange de tout, le fait pour le Seigneur, car il rend à Dieu des actions de grâces; celui qui ne mange pas de tout, s\'abstient pour le Seigneur, et il rend aussi à Dieu des actions de grâces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'En effet, nul de nous ne vit pour soi-même, et nul ne meurt pour soi-même;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'car, soit que nous vivions, nous vivons pour le Seigneur, soit que nous mourions, nous mourons pour le Seigneur; soit donc que nous vivions, soit que nous mourions, nous appartenons au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'C\'est dans ce but que Christ est mort et a vécu, afin que, soit morts, soit vivants, nous l’ayons pour Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Toi donc, pourquoi juges-tu ton frère? Toi aussi, pourquoi méprises-tu ton frère? puisque nous comparaîtrons tous devant le tribunal de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'car il est écrit: «Aussi vrai que je vis, dit le Seigneur, tout genou fléchira devant moi, et toute langue célébrera les louanges de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Ainsi donc chacun de nous rendra compte à Dieu pour soi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Cessons donc de nous juger les uns les autres, et prenons plutôt la résolution de ne rien faire qui soit à notre frère une pierre d\'achoppement, ni une occasion de chute.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Je sais, et j\'ai, dans le Seigneur Jésus, la ferme conviction que rien n\'est impur en soi; néanmoins, si quelqu\'un estime qu\'une chose est impure, elle est impure pour lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Si, pour un aliment, tu fais de la peine à ton frère, tu ne te conduis plus avec amour: n\'entraîne pas à la perdition, par ton aliment, un homme pour lequel Christ est mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Ne faites donc pas calomnier l\'avantage dont vous jouissez;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'car le royaume de Dieu ne consiste ni dans le manger, ni dans le boire, il consiste dans la justice, dans la paix et dans la joie par le Saint-Esprit:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'celui qui sert Christ de cette manière est agréable à Dieu, et estimé des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Ainsi donc, recherchons ce qui contribue à la paix, et à l\'édification mutuelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'N\'allez pas, pour un aliment, détruire l\'oeuvre de Dieu. Toutes choses sont pures, il est vrai, mais il est mal à un homme de manger en devenant une cause d\'achoppement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'ce qui est bien, c\'est de ne point manger de viande, de ne point boire de vin, de ne rien faire qui soit à ton frère une occasion d\'achoppement, de chute ou de faiblesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Toi, tu as une conviction; garde ta conviction pour toi, devant Dieu: heureux celui qui ne se condamne point lui-même dans le parti qu\'il prend!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Quant à celui qui a des doutes, s\'il mange, il est condamné, parce qu\'il n\'a pas agi par conviction. Tout ce qu\'on ne fait pas par conviction, est péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Or nous devons, nous qui sommes forts, supporter les infirmités des faibles, et ne pas nous complaire en nous-mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que chacun de nous cherche à complaire au prochain, en vue du bien qui en résulte pour l\'édification:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Christ n\'a point cherché sa propre satisfaction, mais, comme il est écrit, «les outrages de ceux qui t’outragent sont tombés sur moi»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Car tout ce qui a été précédemment écrit, l\'a été pour notre instruction, afin que par la patience, ainsi que par la consolation que donnent les Écritures, nous possédions l\'espérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Que le Dieu de patience et de consolation vous donne d\'être en bonne intelligence entre vous, comme Jésus-Christ le veut;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'afin que tous ensemble, d\'une même voix, vous glorifiiez Dieu, le Père de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'En conséquence, accueillez-vous les uns les autres, comme Christ vous a accueillis pour la gloire de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'j\'affirme en effet, que Christ a été ministre des circoncis, pour montrer la véracité de Dieu en réalisant les promesses faites à leurs pères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'quant aux Gentils, ils glorifient Dieu pour sa miséricorde, ainsi qu\'il est écrit: «C\'est pourquoi je te louerai parmi les Gentils, et je célébrerai ton nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'L\'Ecriture dit encore: «Gentils, réjouissez-vous avec son peuple;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'et ailleurs: «Gentils, louez tous le Seigneur; que tous les peuples célèbrent ses louanges.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Esaïe dit aussi: «Il paraîtra le rejeton d\'Issaï, celui qui s\'élèvera pour gouverner les Gentils: ils mettront leur espoir en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Que le Dieu de l\'espérance vous fasse trouver dans votre foi toute sorte de joie et de paix, pour que vous soyez pleins d\'espérance, par la puissance de l’Esprit-Saint!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Moi aussi, mes frères, je suis persuadé, en ce qui vous concerne, que pour vous, vous êtes pleins de bonté, remplis d\'une parfaite connaissance, en état de vous avertir les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Si, dans quelques endroits, je vous ai écrit un peu librement, c\'est plutôt pour raviver vos souvenirs, — à cause de la grâce que Dieu m\'a faite');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'd\'être ministre de Jésus-Christ pour les Gentils, — en m’acquittant du divin service de l\'évangile de Dieu, afin que les Gentils soient une oblation agréable, étant sanctifiée par le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Je puis donc me glorifier en Jésus-Christ pour les affaires religieuses,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'car je n\'oserais dire chose au monde, que Christ n\'ait faite par mon ministère pour la conversion des Gentils, en parole et en action,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'par la puissance des miracles et des prodiges, par celle de l\'esprit; si bien que depuis Jérusalem et tout autour, jusqu\'en Illyrie, j\'ai porté partout l\'évangile de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'me faisant toutefois un point d\'honneur de prêcher l\'Évangile, non pas là où le nom de Christ a été annoncé, pour ne pas bâtir sur le fondement d\'autrui, mais dans d\'autres pays,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'selon qu\'il est écrit: «Ceux à qui ou ne l\'avait pas annoncé, le verront, et ceux qui n\'en avaient pais entendu parler, le connaîtront.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'C\'est ce qui d\'ordinaire m\'a empêché de me rendre chez vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'mais à présent, n\'ayant plus à faire dans ces contrées-ci, et ayant depuis plusieurs années le désir d\'aller vers vous, j\'espère vous voir en passant, quand je me rendrai en Espagne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'et y être accompagné par vous, après que j\'aurai d\'abord satisfait, en partie du moins, le désir que j\'ai de vous voir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Pour le moment, je vais à Jérusalem porter secours aux saints;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'car la Macédoine et l\'Achaïe ont bien voulu s\'imposer quelque contribution pour les saints de Jérusalem qui sont dans la pauvreté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Elles l\'ont bien voulu; du reste, elles le leur devaient, car si les Gentils ont eu part à leurs biens spirituels, ils doivent aussi les assister de leurs biens matériels.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Après m\'être acquitté de cette mission, et leur avoir officiellement déclaré ce fruit de la reconnaissance, je gagnerai l\'Espagne en passant chez vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'et je sais qu\'en me rendant auprès de vous, j\'y viendrai avec une pleine bénédiction de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Je vous prie, mes frères, par notre Seigneur Jésus-Christ, et par l\'amour que mon âme ressent, de me soutenir dans mes luttes, en priant Dieu pour moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'afin que j\'échappe aux incrédules de Judée, et que l\'assistance que je porte à Jérusalem soit agréable aux saints,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'en sorte que, s\'il plaît à Dieu, je me rende chez vous dans la joie, et que je goûte quelque repos avec vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Que le Dieu de paix soit avec vous tous! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Je vous recommande Phébé, notre soeur, qui est diaconesse de l\'église de Cenchrées,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'afin que vous la receviez, en notre Seigneur, d\'une manière digne des saints, et que vous l\'assistiez dans toute affaire, où elle pourrait avoir besoin de vous; car elle a été elle-même la protectrice de bien des frères, et la mienne en particulier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Saluez Prisca et Aquilas, mes compagnons d\'oeuvre en Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'qui ont exposé leur tête pour me sauver la vie: ce n\'est pas moi seul qui leur rends grâces, mais ce sont aussi toutes les églises des Gentils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Saluez aussi rassemblée qui se réunit dans leur maison. Saluez mon cher Épénète, qui a été les prémices de l\'Asie, pour Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Saluez Marie, qui a beaucoup travaillé pour vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Saluez Andronicus et Junias, mes parents et mes compagnons de captivité, qui sont avantageusement connus des apôtres, et qui se sont attachés à Christ, même avant moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Saluez Amplias qui m\'est cher dans le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Saluez Urbain notre compagnon d’oeuvre en Christ, ainsi que mon cher Stachys.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Saluez Apelle qui a fait ses preuves, en Christ. Saluez les gens de la maison d\'Aristobule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Saluez Hérodion, mon parent. Saluez ceux de la maison de Narcisse qui sont au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Saluez Tryphène et Tryphose, car elles ont travaillé pour le Seigneur. Saluez notre chère Perside; elle a beaucoup travaillé pour le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Saluez Rufus, l\'élu dans le Seigneur, et sa mère, que je regarde comme la mienne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Saluez Asyncritus, Phlégon, Hermès, Patrobas, Hermasetles frères qui sont avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Saluez Philologue et Julie, Nérée et sa soeur, ainsi qu\'Olympas et tous les saints qui sont avec eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Saluez-vous les uns les autres par un saint baiser. Toutes les églises de Christ vous saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Je vous invite, mes frères, à bien avoir l\'oeil sur ceux qui causent les dissensions et les chutes par leur opposition à l’enseignement que vous avez reçu. Eloignez-vous d\'eux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'car de telles gens ne servent point Christ, notre Seigneur, mais ils sont les serviteurs de leur ventre, et avec leurs bonnes paroles et leur langage flatteur, ils trompent les coeurs des innocents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Je vous y invite, car votre soumission est parvenue aux oreilles de tout le monde; je me réjouis donc à votre sujet, mais je désire que vous soyez habiles pour le bien, tout en étant innocents pour le mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Le Dieu de paix écrasera promptement Satan sous vos pieds. Que la grâce de notre Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timothée, le compagnon de mes travaux, vous salue; Lucius, Jason et Sosipatros, mes parents, vous saluent aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Je vous salue dans le Seigneur, moi Tertius, qui écris cette lettre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaïus mon hôte et celui de toute l\'église, vous salue. Éraste, le trésorier de la ville, et notre frère Quartus, vous saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'A Celui qui peut vous affermir dans mon évangile et dans la prédication qui se fait de Jésus-Christ — conformément à la révélation du mystère celé durant de longs siècles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mais révélé maintenant, ainsi que par les écrits des Prophètes, sur l\'ordre du Dieu éternel, pour amener à l\'obéissance de la foi toutes les nations —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'à Dieu, seul sage, soit la gloire aux siècles des siècles, par Jésus-Christ! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paul, élu apôtre de Jésus-Christ par la volonté de Dieu, et Sosthènes notre frère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'aux fidèles sanctifiés en Jésus-Christ, les élus saints de l’église de Dieu qui est à Corinthe, et à tous ceux qui, en tout lieu, invoquent le nom de Jésus-Christ, leur Seigneur et le nôtre:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'que la grâce et la paix vous soient donnée par Dieu notre Père, et par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Je ne cesse de bénir mon Dieu de la grâce qu\'il vous a faite en Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'il vous a comblés en lui de toutes sortes de richesses, richesses de parole et richesses de science,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'par la manière dont le témoignage de Christ a été solidement établi parmi vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'de sorte que vous ne manquez d\'aucun don, en attendant la venue de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Il vous affermira jusqu\'à la fin, pour que vous soyez sans reproche au jour de notre Seigneur Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Dieu, qui vous a appelés à la communion de son Fils Jésus-Christ, notre Seigneur, est fidèle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Je vous conjure, mes frères, au nom de notre Seigneur Jésus-Christ, d\'avoir tous un même langage. Qu\'il n\'y ait point de divisions parmi vous, mais soyez bien unis dans un même esprit et dans une même pensée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'car, mes frères, j\'ai appris par les gens de Chloé, qu\'il y a des disputes parmi vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'J\'entends par là que chacun dit: «Moi, je suis à Paul; — moi, à Apollos; — moi, à Céphas; — moi, à Christ.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Est-ce que Christ est divisé? Est-ce que Paul a été crucifié pour vous? Est-ce au nom de Paul que vous avez été baptisés?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Je bénis Dieu de ce que je n\'ai baptisé aucun d\'entre vous, si ce n\'est Crispus et Caïus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'pour que l\'on ne puisse pas dire que vous avez été baptisés en mon nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'J\'ai encore baptisé la famille de Stephanas; du reste, personne d\'autre, que je sache.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Christ ne m\'a pas envoyé pour baptiser, mais pour prêcher l\'évangile, et pour le prêcher sans la sagesse, ni l\'art de la parole, afin de ne pas ôter sa puissance à la croix de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'La prédication de la croix est, en effet, une folie pour ceux qui périssent; pour ceux qui sont sauvés, pour nous, elle est la puissance de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'car il est écrit: «Je perdrai la sagesse des sages, et j\'anéantirai la science des savants.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'où est le sage? où est le scribe? où est le dialecticien de ce siècle? Dieu n\'a-t-il pas fait voir que la sagesse du monde est folie?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Car le monde, avec sa sagesse, n\'ayant pas su connaître Dieu dans la sagesse de ses autres, il a plu à Dieu de sauver les croyants par la folie de la prédication.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Les Juifs demandent des miracles; les Grecs recherchent la sagesse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'pour nous, nous prêchons Christ crucifié, qui est scandale aux Juifs, folie aux Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'mais qui, pour les élus, soit juifs, soit grecs, est Christ, puissance de Dieu et sagesse de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'car la folie de Dieu est plus sage que les hommes, et la faiblesse de Dieu, plus forte que les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Vous voyez bien, mes frères, que parmi vous, élus, il n\'y a pas beaucoup de sages selon la chair, pas beaucoup de puissants, pas beaucoup de nobles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Dieu a choisi les choses folles du monde, pour confondre les sages; il a choisi les choses faibles du monde, pour confondre les fortes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'il a choisi celles qui sont de basse extraction dans ce monde, les méprisées, ce qui est néant, pour anéantir ce qui est,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'afin que personne ne se glorifie en sa présence.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'C\'est à lui que vous devez d\'être en Jésus-Christ, qui a été fait sagesse pour nous par la volonté de Dieu, ainsi que justice, sanctification et délivrance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'afin, comme il est écrit, que «celui qui se glorifie, se glorifie dans le Seigneur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Moi-même, mes frères, quand je suis venu chez vous, je ne suis pas venu vous annoncer le témoignage de Dieu avec le prestige de la parole et de la sagesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Je n\'ai pas jugé que je dusse savoir autre chose parmi vous que Jésus-Christ, et Jésus-Christ crucifié;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'et, personnellement, j\'ai été, dans mes rapports avec vous, faible, craintif et tout tremblant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Ma parole et ma prédication n\'ont pas consisté en discours éloquents dictés par la sagesse, mais en une démonstration d\'esprit et de puissance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'afin que votre foi reposât, non sur la sagesse des hommes, mais sur la puissance de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Pourtant, c\'est bien la sagesse que nous enseignons parmi les parfaits; une sagesse qui n\'est pas celle de ce monde, ni des princes de ce monde, dont le règne va finir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'mais la sagesse mystérieuse de Dieu, ces plans cachés que Dieu, de toute éternité, avait arrêtés pour notre gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Nul des princes de ce monde ne l\'a connue, car s\'ils l\'avaient connue, ils n\'auraient pas crucifié le Seigneur de gloire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'mais ce sont, comme il est écrit «des choses que l’oeil n\'a point vues, que l’oreille n\'a point entendues, et qui ne sont point montées à l’esprit de l’homme - des choses que Dieu a préparées pour ceux qui l\'aiment.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Dieu nous les a révélées par son Esprit, car l\'Esprit sonde tout, même les profondeurs de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Qui est-ce qui connaît ce qui est en l\'homme, si ce n\'est son esprit, qui est en lui? De même, nul n\'a connu ce qui est en Dieu, que l\'Esprit de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Pour nous, nous avons reçu, non l\'esprit du monde, mais l\'Esprit qui vient de Dieu, afin que nous connaissions les grâces que Dieu nous a faites;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'et nous en parlons, non avec des paroles qu\'enseigne la sagesse humaine, mais avec celles que l\'Esprit suggère, en exprimant les choses spirituelles dans un langage spirituel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'L\'homme qui ne vit que de la vie animale, n\'accueille pas les choses de l\'Esprit de Dieu: elles sont pour lui une folie; et il ne peut les comprendre, parce qu\'elles demandent à être jugées spirituellement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'L\'homme spirituel, au contraire, juge de tout, et lui-même n\'est jugé par personne;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'car «qui a connu la pensée du Seigneur, pour pouvoir l’instruire?» Pour nous, nous possédons la pensée de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Moi-même, mes frères, je n\'ai pu vous parler comme à des hommes spirituels, mais j\'ai dû vous parler comme à des hommes charnels, comme à de petits enfants en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Je vous ai donné du lait, non de la nourriture solide: vous n\'étiez pas assez forts. Vous ne l\'êtes pas même à présent, puisque vous êtes encore charnels.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Quand il y a parmi vous de la jalousie et des disputes, n\'êtes-vous pas charnels, et ne vous conduisez-vous pas d\'une manière tout humaine?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Quand vous dites, l\'un, «moi, je suis à Paul,» — l\'autre, «moi, je suis à Apollos,» n\'êtes-vous pas des hommes charnels?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Qu\'est donc Apollos, et qu\'est Paul? Ce sont des ministres par le moyen desquels vous avez cru, selon ce qui a été donné à chacun d\'eux par le Seigneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'j\'ai planté, Apollos a arrosé, mais c\'est Dieu qui a donné l\'accroissement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Ainsi celui qui plante n\'est rien, non plus que celui qui arrose; Dieu, qui donne l\'accroissement, est tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Celui qui plante et celui qui arrose sont tout un, et ils recevront leur récompense, chacun selon son travail propre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Nous sommes ouvriers avec Dieu: vous êtes le champ que Dieu cultive, la maison qu\'il édifie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Par la grâce de Dieu, qui m\'a été donnée, j\'ai posé le fondement comme un sage architecte; un autre bâtit dessus: seulement, que chacun prenne bien garde comment il bâtit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Personne, en effet, ne peut poser un autre fondement que celui qui est déjà placé; ce fondement, c\'est Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Que l\'on bâtisse sur ce fondement avec de l\'or, de l\'argent, des pierres précieuses, du bois, du foin, de la paille, l\'ouvrage de chacun sera mis en lumière;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'la grande journée le fera voir, parce qu\'elle va apparaître flamboyante, et le feu même montrera quel est l\'ouvrage de chacun.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Si l\'ouvrage de quelqu\'un subsiste, il en recevra la récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Celui dont l\'ouvrage aura été consumé, perdra sa récompense; pour lui, toutefois, il sera sauvé, mais ce sera comme au travers du feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne savez-vous pas que vous êtes le temple de Dieu, et que l\'Esprit de Dieu habite en vous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Si quelqu\'un détruit le temple de Dieu, Dieu le détruira; car le temple de Dieu est saint, ce que vous êtes vous-mêmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que personne ne s\'abuse: si quelqu\'un parmi vous pense être sage, parce qu\'il a la sagesse de ce monde, qu\'il devienne fou, afin d\'être sage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'car la sagesse de ce monde est folie aux yeux de Dieu. N\'est-il pas écrit: «Il prend les sages dans leurs finesses,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'et encore: «Le Seigneur connaît les pensées des sages; il sait qu\'elles sont vaines?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Que personne donc ne mette sa gloire dans les hommes; car tout est à vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'soit Paul, soit Apollos, soit Céphas, soit le monde, soit la vie, soit la mort, soit les choses présentes, soit les choses à venir:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'tout est à vous; mais vous, vous êtes à Christ, et Christ est à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Qu\'ainsi l\'on nous tienne pour des ministres de Christ et des dispensateurs des mystères de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'En cette matière, du reste, ce qu\'on demande à des dispensateurs, c\'est d\'être trouvés fidèles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Pour moi, il m\'importe fort peu d\'être jugé par vous ou par un tribunal humain; je ne me juge pas moi-même;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'car, quoique ma conscience ne me reproche rien, cela ne veut pas dire que je sois tenu pour juste: mon juge, c\'est le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'En conséquence, ne portez pas de jugement avant le temps; attendez que le Seigneur vienne: il illuminera aussi ce qui est caché dans les ténèbres, et mettra en plein jour les desseins des coeurs. Alors chacun recevra de Dieu la louange qu\'il mérite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Ce que je viens de dire d\'Apollos et de moi, n\'est qu\'une forme que j\'ai prise à cause de vous, pour que vous appreniez en nos personnes, la maxime, «pas au delà de ce qui est écrit,» afin que nul de vous ne mette son orgueil en l\'un, pour s\'élever contre l\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Car, qui est-ce qui te distingue, toi? Qu\'as-tu que tu ne l\'aies reçu? et si tu l\'as reçu, pourquoi te glorifies-tu, comme si tu ne l\'avais pas reçu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Déjà vous êtes rassasiés, déjà vous êtes riches, vous régnez sans nous! Eh! plût à Dieu que vous régnassiez, afin que nous aussi, nous régnassions avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Car il semble que Dieu nous ait assigné, à nous apôtres, la dernière place, comme à des condamnés à mort, nous donnant en spectacle au monde, aux anges et aux hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nous sommes fous à cause de Christ; mais vous, vous êtes sages en Christ; nous sommes faibles, vous êtes forts; vous êtes considérés, nous sommes méprisés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'A cette heure encore, nous avons faim, nous avons soif, nous sommes nus, nous sommes battus de coups, nous n\'avons ni feu ni lieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'et nous nous fatiguons à travailler de nos propres mains. On nous insulte, nous bénissons; on nous persécute, nous supportons;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'on nous dit des injures, nous donnons de bonnes paroles; nous sommes jusqu’à présent comme les balayures du monde, le rebut des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Je n\'écris pas cela pour vous faire honte; mais je vous avertis comme mes enfants bien-aimés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Quand vous auriez dix mille maîtres en Christ, néanmoins vous n\'avez pas plusieurs pères: c\'est moi qui vous ai engendrés en Jésus-Christ par l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Je vous en conjure donc, soyez mes imitateurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'C\'est pour cela que je vous ai envoyé Timothée, qui est mon enfant chéri et fidèle, dans le Seigneur; il vous rappellera quelles sont mes voies en Christ, d\'après la manière dont j\'enseigne partout, dans toutes les églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Quelques-uns se sont enflés, comme si je ne devais pas aller chez vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'mais j\'irai bientôt chez vous, s\'il plaît au Seigneur, et je prendrai connaissance, non des paroles de ceux qui se sont enflés, mais de ce qu\'ils savent faire:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'le royaume de Dieu consiste, non en paroles, mais en oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Que voulez-vous? que j\'aille chez vous avec la verge, ou bien avec amour et dans un esprit de douceur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'On entend dire généralement, qu\'il y a de l’impudicité parmi vous, et une telle impudicité qu\'elle ne se rencontre pas même chez les Gentils; c\'est au point que l\'un de vous vit avec la femme de son père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Et vous vous êtes enflés! et vous n\'avez pas plutôt pleuré, afin d\'ôter du milieu de vous celui qui a commis cette action!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Pour moi, absent de corps, mais présent d\'esprit, j\'ai déjà jugé, comme si j\'étais là, celui qui a commis cette énormité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'j’ai décidé au nom de notre Seigneur Jésus, après nous être assemblés, vous et mon esprit, assisté de la puissance de notre Seigneur Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'de livrer un tel homme à Satan pour la destruction de la chair, afin que l\'âme soit sauvée au jour du Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Il ne vous sied point de vous glorifier. Ne savez-vous pas qu\'un peu de levain fait lever toute la pâte?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Purifiez-vous du vieux levain, afin que vous soyez une pâte nouvelle, comme aussi vous êtes sans levain, puisque notre Pâque a été immolée, nous voulons dire Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Ainsi, célébrons la fête, non avec du vieux levain, ni avec un levain de méchanceté et de perversité, mais avec les pains sans levain de la pureté et de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Je vous ai écrit dans ma lettre, «de n\'avoir aucune relation avec les libertins;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'non pas absolument avec tous les libertins de ce monde, ni avec les hommes cupides et rapaces, ni avec les idolâtres; autrement, il faudrait sortir de ce monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'J\'ai simplement voulu vous dire de n\'avoir aucune relation avec un homme qui porte le nom de frère, si c\'est un libertin, ou un avare, ou un idolâtre, ou un homme outrageux, ou un ivrogne, ou un homme rapace; vous ne devez pas même manger avec un tel homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Qu\'ai-je affaire de juger aussi les gens du dehors? N\'est-ce pas vous qui jugez ceux du dedans?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Ceux du dehors, c\'est Dieu qui les juge. Otez le pervers du milieu de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quand l\'un de vous a un différend avec son frère, ose-t-il bien l\'appeler en jugement devant les méchants, et non devant les saints?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ne savez-vous pas que les saints jugeront le monde? Et, si vous devez juger le monde, êtes-vous indignes de prononcer des jugements bien moins importants?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne savez-vous pas que nous jugerons les anges? et nous ne jugerions pas des affaires d\'intérêt?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Quand donc vous avez des procès pour affaires d\'intérêt, vous prenez pour juges des gens qui sont méprisés de l\'église!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Je le dis à votre honte. Ainsi, il n\'y a pas parmi vous un seul homme sage qui puisse servir d\'arbitre entre ses frères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'mais un frère est en procès avec un frère, et cela devant des infidèles!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'En général, c\'est un défaut chez vous que d\'avoir des procès les uns avec les autres. Pourquoi ne vous laissez-vous pas plutôt faire tort? Pourquoi ne vous laissez-vous pas plutôt spolier?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mais c\'est vous-mêmes, qui êtes injustes, spoliateurs, et cela envers des frères!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ne savez-vous pas que les injustes n\'hériteront point le royaume de Dieu? Ne vous y trompez pas: ni les libertins, ni les idolâtres, ni les adultères, ni les efféminés, ni les infâmes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'ni les voleurs, ni les avares, ni les ivrognes, ni les outrageux, ni les rapaces n\'hériteront le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Voilà pourtant ce que vous étiez, du moins quelques-uns de vous; mais vous avez été lavés; mais vous avez été sanctifiés; mais vous avez été justifiés au nom du Seigneur Jésus, et par l\'Esprit de notre Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Tout m\'est permis, mais tout n\'est pas utile; tout m\'est permis, mais je ne me laisserai dominer par rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Les aliments sont pour l\'estomac, et l\'estomac est pour les aliments: et Dieu détruira et ceux-ci, et celui-là. Mais le corps n\'est pas pour le libertinage; il est pour le Seigneur, et le Seigneur, pour le corps:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'et Dieu, qui a ressuscité le Seigneur, nous ressuscitera aussi par sa puissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne savez-vous pas que vos corps sont les membres de Christ? Je prendrai donc les membres de Christ pour en faire les membres d\'une prostituée? Loin de moi une telle pensée!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ne savez-vous pas que celui qui s\'unit à une prostituée, fait un seul et même corps avec elle? car il est dit: «les deux seront une seule chair.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Celui qui s\'unit au Seigneur, est un seul et même esprit avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fuyez le libertinage. Quelque autre péché qu\'un homme commette, ce péché est hors du corps, tandis que le libertin pèche contre son propre corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ne savez-vous pas que votre corps est le temple du Saint-Esprit, qui est en vous et qui vous vient de Dieu? que vous ne vous appartenez point à vous-mêmes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'car vous avez été achetés à grand prix? Glorifiez Dieu dans votre corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Quant aux points sur lesquels vous m\'avez écrit, je vous dirai qu\'il est bon pour l’homme de ne point approcher d\'une femme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'néanmoins, pour éviter le libertinage, que chaque homme ait sa femme, que chaque femme ait son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Que le mari rende à sa femme ce qu\'il lui doit, et que la femme en use de même envers son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'La femme n\'est point la maîtresse de son corps, c\'est le mari qui en est le maître; de même, le mari n\'est point le maître du sien, c\'est la femme qui en est la maîtresse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne vous privez ni l\'un ni l\'autre de ce que vous vous devez, à moins que ce ne soit d\'un commun accord et pour un temps, afin de vaquer à la prière; puis remettez-vous ensemble, de peur que Satan ne prenne sujet de votre incontinence pour vous tenter:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'c\'est un conseil, non un ordre que je vous donne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Je voudrais que tous les hommes fussent comme moi; mais chacun reçoit de Dieu son don particulier, l\'un d\'une manière, l\'autre d\'une autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Je dis à ceux qui ne sont pas mariés et aux veuves, qu\'il leur est bon de demeurer en cet état, comme j\'y demeure moi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Toutefois, s\'ils ne peuvent garder la continence, qu\'ils se marient: il vaut mieux se marier que de brûler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Quant aux personnes mariées, j\'ordonne, non pas moi, mais le Seigneur, qu\'une femme ne se sépare point de son mari');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(dans le cas où elle s\'en trouverait séparée, qu\'elle demeure sans se marier, ou qu\'elle se réconcilie avec son mari) et qu\'un mari ne répudie point sa femme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Pour ce qui s\'agit des autres, ce n\'est pas le Seigneur, c\'est moi qui leur dis: Si un frère a une femme qui n\'ait pas la foi, et que cette femme consente à habiter avec lui, qu\'il ne la répudie point;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'si une femme a un mari qui n\'ait pas la foi, et que ce mari consente à habiter avec elle, qu\'elle ne répudie point son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Le mari qui n\'a pas la foi, est sanctifié dans la personne de sa femme, et la femme qui n\'a pas la foi, est sanctifiée dans la personne du frère, autrement vos enfants seraient impurs, au lieu qu\'ils sont saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Si le conjoint qui n\'a pas la foi, se sépare, eh bien! qu\'il se sépare; en pareil cas, le frère ou la soeur ne sont pas liés: c\'est pour que nous vivions en paix que Dieu nous a appelés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Que sais-tu, femme, si tu sauveras ton mari? Que sais-tu, mari, si tu sauveras ta femme?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'En tout cas, que chacun conforme sa conduite à la position que le Seigneur lui a assignée et dans laquelle il se trouvait quand Dieu l\'a appelé. C\'est la règle que j\'établis dans toutes les Eglises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Quelqu\'un a-t-il été appelé étant circoncis, qu\'il demeure circoncis. Quelqu\'un a-t-il été appelé étant incirconcis, qu\'il ne se fasse pas circoncire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'La circoncision n\'est rien; l\'incirconcision n\'est rien: ce qui est tout, c\'est de garder les commandements de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Que chacun reste dans l\'état où il était quand il a été appelé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Tu as été appelé étant esclave, ne t\'en mets point en peine, mais alors même que tu peux recouvrer ta liberté, mets plutôt à profit ton état de servitude;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'car celui qui a été appelé au Seigneur étant esclave, est un affranchi du Seigneur; de même, l’homme libre qui a été appelé, est un esclave de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vous avez été achetés à grand prix: ne vous rendez pas esclaves des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Mes frères, que chacun demeure devant Dieu dans l’état où il était, quand il a été appelé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Pour ce qui est des vierges, je n\'ai pas d\'ordre à leur donner delà part du Seigneur; mais je leur donne un avis, comme ayant reçu du Seigneur la grâce d\'être fidèle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Je crois que cet état est bon à cause de la calamité qui est imminente, oui, je crois qu\'il est bon à l\'homme d\'être ainsi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'T\'es-tu engagé à une femme, ne cherche point à te dégager; es-tu libre, ne cherche point de femme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Si pourtant tu te maries, tu ne pèches point; si une vierge se marie, elle ne pèche point; mais ces personnes auront des afflictions dans la chair, et je voudrais vous les épargner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Je vous assure, mes frères, que le temps s\'est fait court; du reste, je le dis, afin que ceux qui ont des femmes, soient comme s\'ils n\'en avaient pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'ceux qui pleurent, comme s\'ils ne pleuraient pas; ceux qui se réjouissent, comme s\'ils ne se réjouissaient pas; ceux qui achètent, comme s\'ils ne possédaient pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'et ceux qui usent du monde, comme s\'ils n\'en usaient point du tout; car l\'état de ce monde va passer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Je voudrais que vous fussiez libres de soucis mondains: l\'homme non marié se soucie des affaires du Seigneur, il cherche à plaire au Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'l\'homme marié se soucie des affaires du monde, il cherche à plaire à sa femme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'La femme et la vierge ont aussi des intérêts différents: celle qui n\'est pas mariée se soucie des affaires du Seigneur, afin d\'être sainte de corps et d\'âme; tandis que celle qui est mariée se soucie des affaires du monde, cherchant à plaire à son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'C\'est dans votre intérêt que je parle ainsi, non dans l\'intention de mettre le grappin sur vous; je voudrais vous retenir honnêtement et sans tiraillements auprès du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Si quelqu\'un estime qu\'il manquerait aux convenances envers sa fille, si elle passait la fleur de l\'âge sans se marier, et qu\'il est de son devoir de la marier, qu\'il fasse comme il l\'entend: il ne pèche point, qu\'il la marie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mais celui qui, sans y être forcé, étant maître de faire ce qu\'il veut, prend en son coeur la ferme résolution de garder sa fille, celui-là fait bien:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'ainsi, celui qui marie sa fille fait bien; mais celui qui ne la marie pas, fait mieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'La femme est liée à son mari aussi longtemps qu\'il est vivant; si son mari meurt, elle est libre d\'épouser qui elle voudra; seulement, que ce soit dans le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Cependant elle sera plus heureuse, si elle reste comme elle est: c\'est mon avis, et je crois avoir, moi aussi, l\'Esprit de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Quant aux viandes sacrifiées aux idoles, nous savons que nous sommes tous éclairés là-dessus; mais la science enfle, au lieu que la charité édifie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Si quelqu\'un s\'en croit pour sa science, il n\'a encore rien connu comme on le doit connaître;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'mais, si quelqu\'un aime Dieu, cet homme-là est connu de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Pour ce qui est donc de manger des viandes sacrifiées aux idoles, nous savons bien qu\'il n\'existe pas réellement d\'idole dans le monde, qu\'il n\'y a qu\'un seul Dieu et qu\'il n\'y en a point d\'autre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Bien qu\'il y ait, soit dans le ciel, soit sur la terre, des êtres qu\'on appelle dieux, comme effectivement il existe plusieurs dieux et plusieurs seigneurs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'néanmoins, il n\'y a pour nous qu\'un seul Dieu, le Père, de qui viennent toutes choses, et nous sommes pour lui, — et qu\'un seul Seigneur, Jésus-Christ, par qui sont toutes choses, et nous sommes par lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Malheureusement, tous n\'ont pas cette connaissance. Quelques-uns, par l\'idée qu\'ils se font encore de l\'idole, mangent de la viande comme chose sacrifiée à une idole réelle, et leur conscience, qui est faible, en est souillée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Un aliment ne saurait nous rapprocher ni nous éloigner de Dieu: qu\'on en mange ou qu\'on n\'en mange pas, on n\'en a ni plus ni moins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mais prenez garde que cette liberté dont vous jouissez, ne soit une pierre d\'achoppement pour les faibles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Si l\'on te voit, toi qui es un homme éclairé, assis à table dans le temple d\'une idole, la conscience du faible ne sera-t-elle pas édifiée, au point de lui faire manger des viandes sacrifiées aux idoles?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Oui, il court à sa perte par ta science, le faible, ce frère pour lequel Christ est mort!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'C\'est ainsi qu\'en manquant à des frères, et en violentant leur conscience, qui est faible, vous manquez à Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Pour moi, si un aliment est une occasion de chute pour mon frère, je me passerai éternellement de viande, plutôt que d\'être pour lui une occasion de chute.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ne suis-je pas libre? Ne suis-je pas apôtre? N\'ai-je pas vu Jésus, notre Seigneur? N\'êtes-vous pas mon ouvrage dans le Seigneur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Si, pour d\'autres, je ne suis pas apôtre, au moins le suis-je pour vous; car vous êtes le sceau de mon apostolat dans le Seigneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'voilà ma réponse à mes détracteurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'N\'avons-nous pas le droit de manger et de boire à nos frais?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'N\'avons-nous pas le droit de mener avec nous une soeur en qualité de femme, comme font les autres apôtres, et les frères du Seigneur, et Céphas?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Barnabas et moi, sommes-nous les seuls qui n\'ayons pas le droit de ne point travailler?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Qui jamais a porté les armes à ses propres frais? Plante-t-on une vigne pour n\'en pas manger le fruit? Fait-on paître un troupeau, sans se nourrir de son lait?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Ce que je dis là, n\'est-il que dans les usages humains? La Loi ne le dit-elle pas aussi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'N\'est-il pas écrit dans la loi de Moïse: «Tu n\'emmuselleras pas le boeuf qui foule le grain?» Est-ce que Dieu se met en peine des boeufs?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Ne le dit-il pas bien certainement à cause de nous? Certainement, c\'est pour nous qu\'il a été écrit que le laboureur doit labourer avec espoir, et que celui qui foule le grain, doit le fouler dans l\'espérance d\'y avoir part.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Si nous avons semé pour vous les biens spirituels, est-ce beaucoup de recueillir vos biens temporels?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Si d\'autres jouissent de ce droit sur vous, ne l’avons-nous pas à plus forte raison? Eh bien! nous n\'avons point usé de ce droit: nous nous résignons à tout pour ne créer aucun obstacle à l\'évangile de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne savez-vous pas que ceux qui font le service sacré vivent du temple? que ceux qui sont occupés à l\'autel, ont part à l\'autel?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'De même, le Seigneur a prescrit à ceux qui annoncent l’évangile, de vivre de l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Pour moi, je n\'ai profité d\'aucun de ces avantages. Je n\'écris point cela dans le but d\'obtenir rien de semblable; mieux me vaudrait mourir que de me laisser enlever ce sujet de gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Car si j\'annonce l\'évangile, je n\'ai point là de sujet de gloire; c\'est une nécessité qui m\'est imposée: malheur à moi si je n\'annonce pas l\'évangile!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Si je le fais de bon coeur, j\'en ai la récompense; si je le fais à regret, la charge ne m\'en est pas moins confiée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Quelle est donc ma récompense? C\'est, en annonçant l\'évangile, de l\'annoncer gratuitement, sans user aucunement du droit que l\'évangile me donne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Étant libre de tous, je me suis fait esclave de tous, pour gagner un plus grand nombre:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'j\'ai été avec les Juifs, comme un juif, afin de gagner les Juifs; avec ceux qui sont sous la loi, comme si j\'eusse été sous la loi, quoique, personnellement, je ne sois pas sous la loi, afin de gagner ceux qui sont sous la loi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'avec ceux qui sont sans loi, comme si j\'avais été sans loi, — quoique je ne sois point sans la loi de Dieu, étant sous la loi de Christ, — pour gagner ceux qui sont sans loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'J\'ai été faible avec les faibles, afin de gagner les faibles; je me suis fait tout à tous, afin, de toutes les manières, d\'en sauver quelques-uns.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Je fais tout à cause de l\'évangile, afin d\'y avoir part moi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne savez-vous pas que dans les courses du stade, tous courent, mais qu\'un seul remporte le prix? Courez de même, afin de remporter le prix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Tous ceux qui combattent dans les jeux, observent une tempérance parfaite: eux, pour remporter une couronne périssable; nous, pour une couronne impérissable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Eh bien! moi, je cours de même, et ce n\'est pas à l\'aventure; je frappe de même, et ce n\'est pas en l\'air;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'mais je frappe mon corps et je le traite en esclave, de peur qu\'après avoir prêché aux autres, je ne sois moi-même rejeté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Mes frères, je ne veux pas que vous ignoriez que nos pères ont tous été sous la nuée, qu\'ils ont tous passé au travers de la mer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'qu\'ils ont tous été baptisés en Moïse dans la nuée et dans la mer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'qu\'ils ont tous mangé le même aliment spirituel,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'et qu\'ils ont tous bu le même breuvage spirituel; car ils buvaient à un rocher spirituel qui les suivait, et ce rocher était Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Néanmoins, la plupart d\'entre eux ne furent point agréables à Dieu, puisque leurs corps jonchèrent le sol au désert.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Ces faits se sont passés pour nous servir d\'exemples, afin que nous ne désirions pas de mauvaises choses, comme eux en désirèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Ne soyons donc pas idolâtres, comme quelques-uns d\'entre eux, ainsi qu\'il est écrit: «Le peuple s\'assit pour manger et pour boire; puis il se leva pour se divertir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ne nous livrons pas au libertinage, comme quelques-uns d\'entre eux s\'y livrèrent, de sorte qu\'il en tomba vingt-trois mille en un seul jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ne tentons point Christ, comme quelques-uns d\'entre eux qui périrent victimes des serpents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ne murmurez pas non plus, comme quelques-uns d\'entre eux qui périrent sous les coups de l\'exterminateur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Ces châtiments leur arrivèrent pour servir d\'exemples, et ils ont été consignés par écrit pour notre instruction, à nous, qui touchons à la fin des temps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Ainsi, que celui qui croit être debout, prenne garde de tomber.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Vous n\'avez pas été exposés à des tentations surhumaines, et Dieu, qui est fidèle, ne permettra pas que vous soyez tentés au delà de vos forces; mais, avec la tentation, il vous donnera l\'issue, pour que vous puissiez supporter la tentation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'C\'est pourquoi, mes bien-aimés, fuyez l\'idolâtrie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Je vous parle comme à des personnes raisonnables; jugez vous-mêmes de ce que je dis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'La coupe de bénédiction que nous bénissons, n\'est-elle pas une communion avec le sang de Christ? Le pain que nous rompons, n\'est-il pas une communion avec le corps de Christ?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Puisqu\'il y a un seul pain, nous formons, tout nombreux que nous sommes, un seul corps, car nous participons tous à un seul et même pain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Considérez Israël selon la chair: ceux qui mangent des victimes n\'ont-ils pas communication avec l\'autel?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Qu\'est-ce donc que je veux dire? Que la viande sacrifiée à l\'idole soit quelque chose? Que l\'idole soit quelque chose? — Non;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'mais je dis que ce qu\'ils immolent, ils le sacrifient à des démons, non à un dieu véritable; et je ne veux pas que vous ayez communication avec les démons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vous ne pouvez boire à la coupe du Seigneur et à la coupe des démons; vous ne pouvez prendre part à la table du Seigneur et à la table des démons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Voulons-nous «provoquer la jalousie du Seigneur?» Sommes-nous plus forts que lui?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Tout est permis, mais tout n\'est pas utile; tout est permis, mais tout n\'édifie pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Que personne ne cherche son propre avantage, mais qu\'il cherche celui d\'autrui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Mangez de tout ce qui se vend à la boucherie, sans vous enquérir de rien, à cause de la conscience;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'car «la terre est au Seigneur avec tout ce qu\'elle contient.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Si un infidèle vous invite, et que vous vouliez vous rendre à son invitation, mangez de tout ce qu\'on vous servira, sans vous enquérir de rien, à cause de la conscience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mais si quelqu\'un vous dit: «Ceci a été offert en sacrifice,» n\'en mangez pas à cause de celui qui vous a donné ce renseignement, et à cause de la conscience,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'non pas de la vôtre, bien entendu, mais de celle d\'autrui; car pourquoi ma liberté serait-elle jugée par une conscience étrangère?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Si je mange d\'un aliment avec actions de grâces, pourquoi serais-je diffamé pour une chose dont je rends grâces?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Soit donc que vous mangiez, soit que vous buviez, soit que vous fassiez quelque autre chose, faites tout pour la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Ne soyez en scandale ni aux Juifs, ni aux Grecs, ni à l\'église de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'C\'est ainsi que moi-même je m\'efforce de plaire à tous, sous tous les rapports, cherchant, non mon avantage, mais celui des autres, afin qu\'ils soient sauvés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Soyez mes imitateurs, comme je le suis moi-même de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Je vous loue de ce que vous vous souvenez de moi à tous égards, et de ce que vous retenez mes instructions telles que je vous les ai données.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Je désire cependant que vous sachiez que le chef de tout homme, c\'est Christ; que le chef de la femme, c\'est l\'homme, et que le chef de Christ, c\'est Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Tout homme qui prie ou qui prophétise, la tête couverte, déshonore son chef.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Toute femme qui prie ou qui prophétise, la tête découverte. déshonore son chef; car elle, et la femme rasée, c\'est exactement de même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Si une femme ne se voile pas la tête, qu\'elle se fasse donc couper les cheveux; mais s\'il est honteux à une femme d\'avoir les cheveux coupés ou la tête rasée, qu\'elle se voile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'L\'homme ne doit pas avoir la tête couverte, parce qu\'il est l\'image et la gloire de Dieu; mais la femme est la gloire de l\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'En effet, l\'homme n\'a pas été tiré de la femme; c\'est la femme qui a été tirée de l\'homme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'et l\'homme n\'a pas été créé pour la femme; c\'est la femme qui a été créée pour l\'homme:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'voilà pourquoi la femme doit avoir sur la tête une marque de dépendance, à cause des anges.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Néanmoins la femme ne va point sans l\'homme, ni l\'homme sans la femme, dans le Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'car, si la femme a été tirée de l\'homme, l\'homme aussi naît de la femme, et tout vient de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Je vous en fais juges vous-mêmes: est-il bienséant qu\'une femme prie Dieu sans être voilée?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'La nature même ne vous enseigne-t-elle pas que c\'est une honte à un homme de porter de longs cheveux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'tandis que c\'est une gloire pour la femme qu\'une longue chevelure, parce que la chevelure lui a été donnée en guise de voile?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Si quelqu\'un se plaît à contester, qu\'il sache que telle n\'est pas notre habitude, non plus que celle des églises de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Tout en vous recommandant ce point, je n\'ai garde de vous louer de ce que vous vous réunissez, non pour devenir meilleurs, mais pour devenir pires.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'D\'abord, j\'apprends que, lorsque vous vous réunissez en assemblée, il y a des divisions parmi vous, et je le crois en partie:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'il faut bien qu\'il y ait parmi vous des dissensions, afin qu\'on voie nettement quels sont les bons parmi vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Lors donc que vous vous réunissez, il n\'est pas possible de prendre le repas du Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'car, à table, chacun prend son souper particulier avant que tous soient là, en sorte que l\'un a faim, tandis que l\'autre est ivre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Vous manque-t-il donc des maisons pour manger et boire? Méprisez-vous l\'église de Dieu, et voulez-vous faire un affront à ceux qui n\'ont pas? Que vous dirai-je? Vous louerai-je? — Non, je ne vous loue point en cela.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Car, pour moi, j\'ai appris du Seigneur ce que je vous ai enseigné: c\'est que le Seigneur Jésus, dans la nuit où il fut livré, prit un pain,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'et, après avoir rendu grâces, il le rompit, et dit: « Ceci est mon corps qui est pour vous; faites ceci en mémoire de moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'De même, après avoir soupé, il prit la coupe, et dit: «Cette coupe est la nouvelle alliance en mon sang; faites ceci en mémoire de moi, toutes les fois que vous boirez.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Car toutes les fois que vous mangez ce pain, et que vous buvez cette coupe, vous annoncez la mort du Seigneur, jusqu’à ce qu\'il vienne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Ainsi, celui qui mangera le pain et boira la coupe du Seigneur indignement, sera coupable envers le corps et le sang du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Que chacun s\'éprouve soi-même, et qu\'ainsi il mange du pain et boive de la coupe:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'celui qui mange et boit, sans discerner le corps du Seigneur, mange et boit sa propre condamnation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Voilà pourquoi il y a chez vous beaucoup de gens débiles, malades, et pourquoi un assez grand nombre de personnes sont mortes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Si nous nous jugions bien nous-mêmes, nous ne serions pas jugés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'mais le Seigneur nous juge et nous châtie, pour que nous ne soyons pas condamnés avec le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'En conséquence, mes frères, quand vous vous réunissez pour prendre le repas, attendez-vous les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Si quelqu\'un a faim, qu\'il mange chez lui, afin que vous ne vous réunissiez pas pour votre condamnation. Quant aux autres détails, je les réglerai, dès que je serai arrivé chez vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Pour ce qui est des dons spirituels, je ne veux pas, mes frères, que vous soyez dans l\'ignorance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vous savez que, lorsque vous étiez païens, vous vous laissiez entraîner vers les idoles muettes, comme vous vous y trouviez poussés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Apprenez donc qu\'aucun homme qui parle par l\'Esprit de Dieu, ne dit «Maudit Jésus!» et que nul ne peut dire «Seigneur Jésus!» que par le Saint-Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Cependant il y a diversité de dons, mais le même Esprit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'il y a aussi diversité de ministères, mais le même Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'il y a aussi diversité de pouvoirs, mais c\'est le même Dieu qui les produit tous en tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Toutefois la manifestation de l\'Esprit par chacun, lui est donnée en vue de l\'utilité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'En effet, à l\'un est donnée, par le moyen de l\'Esprit, la parole de sagesse; à un autre, la parole de science, par le même Esprit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'à un autre, la foi, grâce au même Esprit; à un autre, le don des guérisons, grâce à ce seul et unique Esprit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'à un autre, la puissance de faire des miracles; à un autre, la prophétie; à un autre, le discernement des esprits; à un autre, le don de parler les diverses sortes de langues; à un autre, l\'interprétation des langues;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'mais c\'est le seul et même Esprit qui produit tous ces dons, les distribuant à chacun en particulier, comme il lui plaît.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'De la même manière que le corps forme un seul tout, et a plusieurs membres — que, d\'autre part, les membres du corps, malgré leur pluralité, ne forment qu\'un seul corps, ainsi en est-il de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'C\'est, en effet, dans un seul et même Esprit, que nous avons tous été baptisés, pour former un seul corps, soit Juifs, soit Grecs, soit esclaves, soit libres, et nous avons tous été abreuvés d\'un seul et même Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Le corps se compose, non d\'un seul membre, mais de plusieurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Si le pied disait: «Parce que je ne suis pas main, je ne suis pas du corps;» en serait-il moins du corps pour cela?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Si l\'oreille disait: «Parce que je ne suis pas oeil, je ne suis pas du corps;» en serait-elle moins du corps pour cela?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Si tout le corps était oeil, où serait l\'ouïe? S\'il était tout entier ouïe, où serait l\'odorat?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mais voici, Dieu a placé chacun des membres dans le corps, comme il a voulu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Si tous les membres étaient un seul et même membre, où serait le corps?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Il y a donc plusieurs membres, mais il n\'y a qu\'un corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'L\'oeil ne peut pas dire à la main, «je n\'ai pas besoin de toi;» ni la tête, à son tour, dire aux pieds, «je n\'ai pas besoin de vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Bien au contraire, les membres qui sont faibles sont nécessaires,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'et ceux que nous tenons pour les moins honorables du corps, sont ceux que nous entourons de plus d\'honneur; de sorte que les moins honnêtes sont les plus honorés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'au lieu que ceux qui sont honnêtes n\'ont pas besoin d\'autant d\'honneur. Dieu a composé le corps de telle sorte qu\'il a accordé plus d\'honneur à ce qui en manquait,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'afin qu\'il n\'y ait pas de division dans le corps, mais que les membres soient également soucieux les uns des autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Si un membre souffre, tous les autres souffrent avec lui; si un membre est honoré, tous les membres s\'en réjouissent avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Vous êtes le corps de Christ, et chacun, pour sa part, est un de ses membres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Dieu a établi dans l\'Église, premièrement des apôtres, secondement des prophètes, troisièmement des docteurs; il a établi ensuite ceux qui ont le don des miracles, puis ceux qui ont le don de guérir, de secourir, de gouverner, de parler les diverses sortes de langues.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Tous sont-ils apôtres? tous sont-ils prophètes? tous sont-ils docteurs? tous ont-ils le don des miracles?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'tous ont-ils le don de guérir? tous parlent-ils des langues? tous interprètent-ils?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Aspirez aux dons supérieurs. Bien plus, je vais vous montrer une voie infiniment excellente.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Quand je parlerais les langues des hommes et des anges, si je n\'ai pas la charité, je ne suis qu\'un airain sonnant, ou une cymbale retentissante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Quand j\'aurais le don de prophétie, quand je connaîtrais tous les mystères et que je posséderais toute science, quand j\'aurais toute la foi possible, jusqu’à transporter les montagnes, si je n\'ai pas la charité, je ne suis rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Quand je distribuerais tous mes biens pour la nourriture des pauvres, quand je livrerais mon corps pour être brûlé, si je n\'ai pas la charité, cela ne me sert de rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'La charité est patiente, elle est pleine de bonté; la charité n\'est point envieuse; la charité ne se vante point, elle ne s\'enfle point,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'elle ne fait rien d\'inconvenant, elle n\'est point égoïste, elle ne s\'irrite point, elle ne soupçonne pas le mal,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'elle ne se réjouit point de la méchanceté, elle se réjouit, au contraire, de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Elle se résigne à tout, elle croit tout, elle espère tout, elle supporte tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'La charité ne passera jamais. Les prophéties prendront fin, les langues cesseront, la science aura son terme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'car c\'est partiellement que nous connaissons et partiellement que nous prophétisons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'mais quand ce qui est parfait viendra, ce qui est partiel prendra fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Quand j\'étais enfant, je parlais comme un enfant, je pensais comme un enfant, je raisonnais comme un enfant; mais, quand j\'ai été homme, je me suis défait de ce qui tenait de l\'enfant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Maintenant, nous voyons comme dans un miroir, en devinant; alors, nous verrons face à face; maintenant, je connais d\'une manière partielle; alors je connaîtrai comme j\'ai été connu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Mais voici, ces trois choses demeurent, la foi, l\'espérance, la charité; mais la plus grande d\'entre elles, c\'est la charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Recherchez la charité, tout en aspirant aux dons spirituels, et surtout au don de prophétie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Celui qui parle une langue ne parle pas aux hommes, mais à Dieu, car personne ne le comprend. C\'est en son coeur qu\'il profère des mystères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'au lieu que celui qui prophétise parle aux hommes: il édifie, il exhorte, il console.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Celui qui parle une langue, n\'édifie que lui-même; celui qui prophétise, édifie une assemblée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Je veux bien que vous parliez tous des langues, mais encore plus que vous prophétisiez. Celui qui prophétise est supérieur à celui qui parle des langues, à moins que ce dernier n\'interprète ce qu\'il dit, pour que l\'assemblée en reçoive de l\'édification.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Mais à quoi donc vous serais-je utile, mes frères, si je venais vous parler des langues et que je ne m\'exprimasse pas comme l’on s\'exprime dans la révélation, dans la science, dans la prophétie ou dans l\'exhortation?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Bien que les instruments inanimés, soit flûte, soit lyre, rendent un son, cependant s\'ils ne rendent pas des sons distincts, comment comprendra-t-on ce qui est joué avec la flûte ou sur la lyre?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Si la trompette rend un son confus, qui est-ce qui se préparera au combat?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Vous, de même, si vous ne faites pas entendre avec la langue une parole distincte, comment saura-t-on ce que vous dites? Vous ne ferez que parler en l\'air.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Il y a, on le dit du moins, tant de langues différentes dans le monde, et pourtant il n\'en est aucune qui ne soit un idiome;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'si donc je ne connais pas la valeur de cet idiome, je serai un barbare pour celui qui parle, et celui qui parle sera, à mon sens, un barbare: il en est de même de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Puisque vous êtes si ambitieux de dons spirituels, que ce soit pour l\'édification de l\'église que vous cherchiez à en être riches.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'En conséquence, que celui qui parle une langue, prie; mais qu\'il interprète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Car si je prie en langue, mon coeur prie, mais mon intelligence ne produit aucun fruit d\'édification.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Que faire donc? Je prierai avec le coeur, mais je prierai aussi avec l\'intelligence; je psalmodierai avec le coeur, mais je psalmodierai aussi avec l\'intelligence;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'autrement, si tu ne rends des actions de grâces qu\'avec le coeur, comment celui qui occupe la place de l\'homme du peuple, répondra-t-il Amen! à ton action de grâces, puisqu\'il ne sait pas ce que tu dis?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Pour toi, il est vrai, tu rends d\'excellentes actions de grâces, mais l\'homme du peuple n\'en est point édifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Je bénis Dieu, de ce que je parle des langues plus que vous tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'mais j\'aimerais mieux prononcer dans une assemblée cinq paroles avec mon intelligence, afin d\'instruire aussi les autres, que dix mille en langue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Mes frères, ne soyez pas des enfants pour la raison, mais pour la malice, restez en bas âge; pour la raison, soyez des hommes faits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Il est écrit dans la Loi: «C\'est par des gens de langue étrangère et avec lèvres d\'étrangers que je parlerai à ce peuple; et, même de cette manière, ils ne m\'écouteront pas, dit le Seigneur; »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'd\'où suit, que les langues sont un signe qui est adressé, non aux croyants, mais à ceux qui ne croient pas; la prophétie, au contraire, est, non pour ceux qui ne croient pas, mais pour le croyants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Supposez donc l\'église tout entière réunie en un même lieu, et tous parlant des langues, puis, qu\'il entre des hommes du peuple ou des gens qui ne croient pas; ne diront-ils pas que vous êtes des fous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Si tous, au contraire, prophétisent, et qu\'il entre quelque homme qui ne croit pas ou quelque homme du peuple: il est confondu par tous, jugé par tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'les choses cachées au fond de son coeur sont mises au jour, et, frappé de ce qu\'il entend, il tombe la face contre terre, adore Dieu, et reconnaît que Dieu est véritablement au milieu de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Que faire donc, mes frères? Toutes les fois que vous vous assemblez, chacun de vous a son psaume, sa leçon, son exercice de langues, sa révélation ou son interprétation: eh bien! que tout se fasse pour l\'édification.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Parle-t-on une langue, que deux ou tout au plus trois parlent, à tour de rôle, et qu\'un seul interprète;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'mais, s\'il n\'y a point d\'interprète, qu\'ils se taisent dans l\'assemblée: qu\'ils parlent pour eux seuls et pour Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Qu\'il n\'y ait que deux ou trois prophètes qui parlent, et que les autres jugent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Si, pendant que l\'un parle, un autre assis a une révélation, que le premier se taise.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'En effet, vous pouvez tous prophétiser, les uns après les autres, afin que tous soient instruits et que tous soient exhortés:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'les esprits des prophètes sont soumis aux prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Dieu n\'est pas un Dieu de désordre, mais un Dieu de paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Que vos femmes se taisent dans les assemblées, comme cela a lieu dans toutes les églises des saints: il ne leur est pas permis d\'y prendre la parole; elles doivent être soumises comme la Loi le dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Si elles veulent s\'instruire sur quelque point, qu\'elles interrogent leurs maris, à la maison: il est malséant à une femme de parler dans une assemblée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Est-ce de chez vous que la parole de Dieu est partie? N\'est-elle parvenue qu\'à vous seuls?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Si quelqu\'un croit être prophète ou un homme spirituel, qu\'il reconnaisse que ce que je vous écris est bien du Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 's\'il le veut ignorer, qu\'il l\'ignore.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'En résumé, mes frères, aspirez à prophétiser, n\'empêchez pas qu\'on parle des langues;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'mais que tout se fasse avec bienséance et avec ordre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Je vous rappelle, mes frères, l\'évangile que je vous ai annoncé, que vous avez reçu, et auquel vous êtes fermement attachés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Il fera votre salut, si vous le retenez dans les termes où je vous l\'ai annoncé; autrement, vous auriez cru en vain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Je vous ai annoncé principalement, comme je l\'ai appris moi- même, que Christ est mort pour nos péchés, conformément aux Écritures;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'qu\'il a été enseveli, et qu\'il est ressuscité le troisième jour, conformément aux Écritures;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'qu\'il est apparu à Céphas, puis aux Douze;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'qu\'après cela, il est apparu, en une rencontre, à plus de cinq cents frères, dont la plupart sont encore vivants aujourd\'hui, et quelques-uns sont morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'qu\'ensuite il est apparu à Jacques, puis à tous les apôtres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'qu\'enfin, après eux tous, il m\'est apparu à moi, comme à l\'avorton;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'car je suis le moindre des apôtres, moi qui ne suis pas digne d\'être appelé apôtre, parce que j\'ai persécuté l\'Église de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'C\'est par la grâce de Dieu que je suis ce que je suis, et la grâce qu\'il m\'a faite n\'a pas été vaine: j\'ai travaillé plus qu\'eux tous, non pas moi pourtant, mais la grâce de Dieu avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Ainsi donc eux et moi, voilà ce que nous prêchons, et c\'est ce que vous avez cru.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Si l\'on prêche que Christ est ressuscité des morts, comment quelques-uns parmi vous disent-ils qu\'il n\'y a point de résurrection des morts?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'S\'il n\'y a point de résurrection des morts, Christ non plus n\'est pas ressuscité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'et si Christ n\'est pas ressuscité, notre prédication est vaine; votre foi aussi est vaine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Il se trouve même que nous sommes de faux témoins à l\'égard de Dieu, puisque nous avons témoigné contre lui, qu\'il a ressuscité Christ; au lieu qu\'il ne l\'a point ressuscité, s\'il est vrai que les morts ne ressuscitent pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Si les morts ne ressuscitent pas, Christ non plus n\'est pas ressuscité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'et si Christ n\'est pas ressuscité, votre foi est vaine; vous êtes encore dans vos péchés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'ceux aussi qui sont morts en Christ, sont perdus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Si nous n\'avons d\'espérance en Christ que dans cette vie seulement, nous sommes les plus malheureux de tous les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mais voici, Christ est ressuscité: il est les prémices de ceux qui sont morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'En effet, puisque la mort est venue par un homme, c\'est par un homme aussi qu\'est venue la résurrection des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'De même que tous meurent en Adam; de même, tous revivront en Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'mais chacun en son rang: les prémices, c\'est Christ, ensuite viendront ceux qui appartiennent à Christ, lors de son avènement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'puis, ce sera la fin, quand il remettra la royauté à Dieu, son Père, après avoir renversé toute principauté, toute autorité et puissance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'car il doit exercer la royauté «jusqu\'à ce qu\'il ait mis tous ses ennemis sous ses pieds.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Le dernier ennemi qui sera détruit, c\'est la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'En effet, Dieu a tout mis sous ses pieds; toutefois, quand il est dit que «tout» lui a été soumis, il est évident qu\'il faut excepter celui qui lui a soumis toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Lorsque toutes choses lui auront été soumises, alors le Fils lui-même sera aussi soumis à Celui qui lui a soumis toutes choses, afin que Dieu soit tout en tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Autrement, que feraient ceux qui se font baptiser pour les morts? Si absolument les morts ne ressuscitent pas, pourquoi se font-ils aussi baptiser pour eux?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Et nous-même, pourquoi sommes-nous à toute heure en péril?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Je suis tous les jours exposé à la mort, aussi vrai, mes frères, que vous êtes ma gloire en Jésus-Christ, notre Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Si c\'est dans des vues humaines que j\'ai combattu contre les bêtes à Éphèse, quel avantage m\'en revient-il? Si les morts ne ressuscitent pas, «mangeons et buvons, car demain nous mourrons. »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne vous laissez point abuser: «les mauvaises compagnies corrompent les bonnes moeurs. »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Revenez à la raison, comme il faut, et ne péchez point; car il y a parmi vous des gens qui ne connaissent pas Dieu: je le dis à votre honte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mais dira quelqu\'un: « Comment les morts ressuscitent-ils? Avec quel corps viennent-ils? »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, '— Insensé que tu es, ce que tu sèmes ne reprend pas vie, s\'il ne meurt auparavant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Quant à ce que tu sèmes, tu ne sèmes pas le corps qui sera un jour, mais un simple grain, de blé, peut-être, ou de quelque autre semence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'puis Dieu lui donne un corps, comme il lui plaît, et à chaque semence le corps qui lui est propre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Toute chair n\'est pas la même chair: autre est la chair des hommes, autre la chair des bêtes, autre la chair des oiseaux, autre la chair des poissons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Il y a aussi des corps célestes et des corps terrestres; mais l\'éclat des corps célestes est d\'une nature différente de celui des corps terrestres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'autre est l\'éclat du soleil, autre l\'éclat de la lune, autre l\'éclat des étoiles; une étoile même diffère en éclat d\'une autre étoile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Il en est de même pour la résurrection des morts: le corps est semé corruptible, il ressuscite incorruptible;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'il est semé méprisable, il ressuscite glorieux; il est semé infirme, il ressuscite plein de force;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'il est semé corps animal, il ressuscite corps spirituel. S\'il y a un corps animal, il y a aussi un corps spirituel;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'c\'est en ce sens qu\'il est écrit: « Le premier homme, Adam, a été doué d\'une âme vivante;» le dernier Adam l\'a été d\'un esprit vivifiant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Mais ce qui est spirituel, n\'est pas le premier, c\'est ce qui est animal; ensuite vient ce qui est spirituel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Le premier homme étant tiré de la terre, est de terre; le second homme vient du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Tel est celui qui est de terre, tels sont aussi ceux qui sont de terre; tel est le céleste, tels sont aussi les célestes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Et, de même que nous avons porté l\'image de celui qui est de terre, nous porterons aussi l\'image de celui qui est céleste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Ce que j\'affirme, mes frères, c\'est que la chair et le sang ne peuvent hériter le royaume de Dieu, et que la corruption n\'héritera pas l\'incorruptibilité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Voici un mystère que je vous révèle: nous ne mourrons pas tous, mais nous serons tous changés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'en un instant, en un clin d\'oeil, au son de la dernière trompette; car la trompette sonnera, et les morts ressusciteront incorruptibles, et nous, nous serons changés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Car il faut que ce corps corruptible revête l\'incorruptibilité, et que ce corps mortel revête l\'immortalité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Lorsque ce corps corruptible aura revêtu l\'incorruptibilité, et que ce corps mortel aura revêtu l\'immortalité, alors se réalisera la parole qui est écrite: « La mort a été engloutie pour que nous soyons vainqueurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'O mort, où est ton aiguillon? O mort, où est ta victoire? »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'L\'aiguillon de la mort, c\'est le péché, et la puissance du péché, c\'est la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mais grâces soient rendues à Dieu, qui nous donne la victoire par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Ainsi, mes frères bien-aimés, soyez fermes, inébranlables, vous distinguant toujours dans l\'oeuvre du Seigneur, sachant que votre travail n\'est pas vain dans le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Quant à la collecte pour les saints, suivez, vous aussi, les prescriptions que j\'ai données aux églises de Galatie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Que, le premier jour de la semaine, chacun de vous mette à part chez soi et amasse ce qu\'il peut épargner, afin qu\'on n\'attende pas que je sois venu, pour recueillir les dons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Quand je serai arrivé, j\'enverrai avec des lettres les personnes que vous aurez choisies, porter votre aumône à Jérusalem;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'et, si la chose mérite que j\'y aille moi-même, elles feront le voyage avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'J\'irai vous voir quand j\'aurai passé par la Macédoine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Je ne veux que la traverser, mais je m\'arrêterai peut-être chez vous, ou même j\'y passerai l\'hiver, afin que ce soit vous qui me reconduisiez à ma destination.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Je ne veux pas, cette fois, vous voir seulement en passant; j\'espère séjourner quelque temps chez vous, si le Seigneur le permet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Je resterai cependant à Éphèse jusqu\'à la Pentecôte,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'parce qu\'une grande porte m\'est ouverte pour agir puissamment, et que les adversaires sont nombreux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Dans le cas où Timothée viendrait chez vous, veillez à ce qu\'il soit sans appréhension dans ses rapports avec vous, car il travaille à l\'oeuvre du Seigneur tout comme moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Que personne ne le méprise, mais reconduisez-le en paix,. afin qu\'il vienne me trouver; car je l\'attends avec nos frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Quant à notre frère Apollos, je l\'ai fortement engagé à aller chez vous avec nos frères. Il ne veut absolument pas s\'y rendre maintenant; il ira dès qu\'il pourra.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Veillez, soyez fermes dans la foi, soyez hommes, soyez forts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Que tout ce que vous faites, se fasse avec charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Une recommandation encore, mes frères. Vous savez que la famille de Stephanas est les prémices de l\'Achaïe, et qu\'elle s\'est dévouée au service des saints;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'eh bien! ayez, vous aussi, de la déférence pour des personnes de ce caractère, ainsi que pour tous ceux qui partagent leurs travaux et qui se donnent de la peine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Je suis heureux de la visite de Stéphanas, de Fortunatus et d\'Achaïque: ils ont personnellement suppléé à votre absence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'car ils ont tranquillisé mon esprit et le vôtre. Appréciez de telles personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Les églises d\'Asie vous saluent. Aquilas et Prisca vous envoient mille salutations dans le Seigneur, ainsi que l\'Église qui se réunit dans leur maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Tous les frères vous saluent. Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Je vous salue de ma propre main, moi Paul.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Si quelqu\'un n\'aime pas le Seigneur, qu\'il soit maudit! Maranatha.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que la grâce du Seigneur Jésus soit avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Mon amour est avec vous tous, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paul, Apôtre de Jésus-Christ par la volonté de Dieu, et Timothée notre frère, à l\'église de Dieu qui est à Corinthe, et à tous les saints qui sont dans toute l\'Achaïe:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'que la grâce et la paix vous soient données par Dieu notre Père et par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, le Père des miséricordes et le Dieu de toute consolation,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'qui nous console dans toutes nos afflictions, afin que, par la consolation que nous recevons nous-même de lui, nous puissions consoler les autres, dans quelque affliction qu\'ils se trouvent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Si les souffrances de Christ débordent sur nous, la consolation aussi déborde par Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Ainsi, soit que nous soyons affligés, c\'est pour votre consolation et pour votre salut; soit que nous soyons consolés, c\'est encore pour votre consolation, afin que vous supportiez avec patience les mêmes afflictions que nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'D\'ailleurs l\'espérance que nous avons pour vous est une espérance solide, parce que nous savons que, si vous avez part aux souffrances, vous aurez aussi part à la consolation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'En effet, mes frères, nous ne vous laisserons pas ignorer qu\'une persécution s\'est élevée contre nous en Asie, et que nous en avons été excessivement accablé, au delà de nos forces, au point que nous avons désespéré même de notre vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Nous en avions fait au dedans de nous le sacrifice, pour ne pas mettre notre confiance en nous, mais en Dieu, qui ressuscite les morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'C\'est lui qui nous a délivré de ce danger mortel, qui nous en délivre, et nous avons l\'espérance qu\'il nous en délivrera encore à l’avenir;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'surtout si vous nous assistez de vos prières, afin que, plusieurs personnes contribuant à nous obtenir ce bienfait, plusieurs aussi en rendent grâces pour nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Ce qui fait notre gloire, c\'est le témoignage que nous rend notre conscience, de nous être conduit dans le monde, et plus particulièrement envers vous, avec la sainteté et la loyauté que Dieu demande, non par une sagesse charnelle, mais par la grâce de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'En vous écrivant, nous n\'avons pas d\'autre pensée que ce que vous lisez, et que vous connaissez bien. J\'espère que vous reconnaîtrez jusqu’à la fin,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'comme une partie déjà d\'entre vous l\'ont reconnu, que nous sommes votre gloire, comme vous serez la nôtre au jour du Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Dans cette persuasion, je m\'étais proposé d\'aller tout d\'abord chez vous, afin de vous faire un double plaisir:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'j\'aurais passé par chez vous pour aller en Macédoine, puis je serais revenu de Macédoine chez vous, et vous m\'auriez fait reconduire en Judée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Est-ce donc qu\'en prenant cette résolution, j\'aurais agi avec légèreté? Est-ce que les projets que je fais, je les fais selon la chair, pour avoir à ma disposition le oui et le non? —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Aussi vrai que Dieu est fidèle, notre parole, la parole que nous vous avons adressée n\'est pas oui et non.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Le Fils de Dieu, Jésus-Christ, que nous avons prêché parmi vous, Silvain, Timothée et moi, n\'a point été oui et non; il n\'y a eu que oui en lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'car toutes les promesses de Dieu sont oui en Jésus, c\'est pourquoi aussi elles sont «Amen!» par lui, à la gloire de Dieu par nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Celui qui nous affermit, ainsi que vous, en Christ, et qui nous a oints, c\'est Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Il nous a aussi marqués de son sceau, et, pour arrhes, il nous a donné son Esprit dans nos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Je prends Dieu à témoin sur mon âme, que c\'est pour vous épargner que je ne suis point encore allé à Corinthe:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'non que nous prétendions dominer sur votre foi, mais nous tâchons de contribuer à votre joie; car vous êtes fermes en la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'J\'ai pris pour moi-même la résolution de ne pas retourner chez vous pour y causer de la tristesse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'car si je vous afflige, de qui attendrai-je de la joie, puisque j\'aurai affligé moi-même ceux qui devaient m\'en donner?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Je vous ai écrit comme je l\'ai fait, afin qu\'en me rendant chez vous je ne sois pas affligé par ceux qui doivent me donner de la joie: je suis persuadé que vous faites tous votre joie de la mienne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'C\'est, en effet, le coeur navré et serré, les larmes aux yeux, que je vous ai écrit, non dans le dessein de vous affliger, mais afin de vous faire connaître l\'amour extrême que j\'ai pour vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Si quelqu\'un a été une cause de tristesse, ce n\'est pas moi personnellement qu\'il a affligé, mais vous tous, du moins en partie, pour ne rien exagérer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'C\'est assez pour cet homme du blâme que lui a infligé la majorité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Au lieu d\'aggraver la peine, vous devez plutôt lui faire grâce et le consoler, dans la crainte que le malheureux ne succombe à une trop grande affliction.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Je vous invite, en conséquence, à rendre à son égard une sentence de charité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'car, en vous écrivant, mon but était aussi de connaître, à l\'épreuve, si vous êtes obéissants en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'A qui vous pardonnez, je pardonne aussi; car, pour moi, la grâce que j\'accorde, si tant est que j\'en accorde quelqu\'une, je l\'accorde à cause de vous, en présence de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'pour que nous ne soyons pas les dupes de Satan, dont nous n\'ignorons pas les desseins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Au reste, m\'étant rendu à Troas pour l\'évangile de Christ, quoiqu\'une porte m\'y fût ouverte dans le Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'je n\'eus point l\'esprit en repos, parce que je n\'y trouvai pas Tite, mon frère, c\'est pourquoi, ayant fait mes adieux aux frères, je partis pour la Macédoine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Grâces soient rendues à Dieu de ce qu\'il nous fait toujours triompher en Christ et répand en tout lieu, par notre ministère, le parfum de sa connaissance!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Nous sommes, pour Dieu, l\'encens de Christ parmi ceux qui sont sauvés et parmi ceux qui se perdent:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'aux uns, une odeur de mort, qui donne la Mort; aux autres, un parfum de vie, qui donne la Vie. Mais qui est capable d\'un tel ministère?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Pour nous, nous en sommes capable, car nous ne frelatons pas la parole de Dieu, comme plusieurs le font, mais c\'est pure, mais c\'est telle qu\'elle vient de Dieu que nous la prêchons devant Dieu, en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Recommençons-nous à nous recommander nous-même. Aurions-nous par hasard besoin, comme certaines gens, de lettres de recommandation pour vous, ou de votre part?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vous êtes, vous-mêmes, notre lettre de recommandation, une lettre écrite dans notre coeur, connue et lue de tout le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Il est manifeste que vous êtes une lettre de Christ, tracée par nous, ses ministres, écrite, non avec de l\'encre, mais avec l\'Esprit du Dieu vivant; non sur des tables de pierre, mais sur des tables de chair, sur vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Cette haute assurance, nous l\'avons par Christ en Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'non que nous soyons capables de rien concevoir par nous-même, comme si nous le tirions de notre propre fonds, mais c\'est de Dieu que nous vient notre capacité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'C\'est lui également qui nous a rendu capables d\'être ministres d\'une nouvelle alliance, non d\'une lettre, mais de l\'esprit; car la lettre tue, mais l\'esprit vivifie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Si le ministère de mort, gravé en lettres sur des tables de pierre, a été entouré d\'assez de gloire pour que les fils d\'Israël ne pussent fixer leurs regards sur la face de Moïse, à cause de l’éclat passager de son visage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'comment le ministère de l\'esprit ne sera-t-il pas revêtu d\'une gloire supérieure?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Si le ministère de la condamnation est glorieux, le ministère de la justification le surpasse de beaucoup en gloire:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'sous ce rapport, la gloire dont le premier a été entouré est totalement éclipsée par la gloire infinie du second;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'car, si ce qui se passe n\'a pas été sans éclat, ce qui demeure est bien autrement glorieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ayant donc une telle espérance, nous parlons et nous agissons avec une grande liberté:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'nous ne faisons pas comme Moïse qui se mettait un voile sur le visage, pour que les fils d\'Israël ne vissent pas la fin de ce qui était passager.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Malheureusement leur intelligence s\'est aveuglée; car, jusqu’à ce jour, ce même voile demeure, lorsqu\'ils lisent l\'Ancien Testament. Il ne leur est point dévoilé que l\'alliance a pris fin en la personne de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'mais aujourd\'hui encore, un voile est étendu sur leurs coeurs:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'quand leurs coeurs se tourneront vers le Seigneur, le voile tombera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Or le Seigneur est l\'esprit; et là où est l\'esprit du Seigneur, là est la liberté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Quant à nous tous, qui, le visage découvert, contemplons en un miroir la gloire du Seigneur, nous sommes transformés en son image, avançant de gloire en gloire, comme on doit l’attendre de l\'esprit du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'C\'est pourquoi, étant revêtus de ce ministère par la miséricorde qui nous a été faite, nous ne nous laissons point décourager.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Nous rejetons loin de nous les manoeuvres secrètes et honteuses, n\'agissant point avec fourberie, n\'altérant point non plus la parole de Dieu. Nous nous rendons recommandables à toute conscience d\'homme, devant Dieu, par la franche révélation de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Si, malgré cela, notre évangile est encore voilé, il n\'est voilé qu\'à ceux qui se perdent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'à ces incrédules dont le Dieu de ce siècle a aveuglé l\'esprit, afin qu\'ils ne soient point illuminés des splendeurs de l\'évangile, on brille la gloire de Christ, qui est l\'image de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Ce n\'est pas nous, c\'est Jésus-Christ que nous prêchons comme Seigneur; quant à nous, nous donnons nous-mêmes pour vos serviteurs, à cause de Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'parce que le Dieu qui a dit, «que la lumière jaillisse des ténèbres,» a fait luire sa lumière dans nos coeurs, pour que nous fassions briller la connaissance de sa gloire, laquelle resplendit en la personne de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Nous portons ce trésor dans des vases de terre, afin que la force extraordinaire qui est en nous, paraisse, non venir de nous, mais appartenir à Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'nous sommes pressés de toute manière, mais non pas réduits à la dernière extrémité; nous sommes perplexes, mais non pas désespérés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'nous sommes persécutés, mais non pas abandonnés; abattus, mais non perdus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Nous portons toujours dans notre corps la mort de Jésus, afin que la vie de Jésus se montre aussi dans notre corps;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'car nous qui vivons, nous sommes toujours livrés à la mort à cause de Jésus, afin que la vie de Jésus se manifeste aussi dans notre chair mortelle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'de sorte que la mort agit en nous, tandis que la vie agit en vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Or comme nous avons l\'esprit de foi qui a dicté cette parole, «j\'ai cru, c\'est pourquoi j’ai parlé,» nous aussi, «nous croyons, c\'est pourquoi nous parlons,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'étant persuadés que Celui qui a ressuscité le Seigneur Jésus, nous ressuscitera aussi avec lui, et nous fera paraître avec vous en sa présence;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'car tout cela est pour vous, afin que la grâce, en s\'étendant à un plus grand nombre, provoque de plus nombreuses actions de grâces à la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'C\'est pourquoi, nous ne nous laissons point décourager; au contraire, alors même que notre homme extérieur se détruit, notre homme intérieur se renouvelle de jour en jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Nos légères et passagères afflictions nous procurent une gloire infinie et éternelle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'attendu que nous regardons non aux choses visibles, mais aux choses invisibles; car les choses visibles ne sont que pour un temps, au lieu que les invisibles sont éternelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Nous savons, en effet, que, si cette tente où nous logeons sur la terre, est détruite, nous avons dans les cieux un édifice qui vient de Dieu, un domicile éternel, qui n\'est pas fait de main d\'homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Nous soupirons même dans cette tente, désireux que nous sommes d\'être revêtus de notre domicile céleste;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'si toutefois il se trouve que nous soyons effectivement revêtus, non pas nus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'En effet, nous qui sommes dans cette tente, nous soupirons, l\'âme oppressée, parce que nous ne voulons pas être dépouillés; nous désirons, au contraire, d\'être revêtus, afin que ce qu\'il y a de mortel en nous, soit absorbé par la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Et celui qui nous a formés pour cet avenir, c\'est Dieu; il nous a donné pour arrhes son Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Nous sommes donc toujours plein de courage. Cependant, comme nous savons qu\'en habitant dans ce corps, nous habitons loin du Seigneur');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(car c\'est par la foi que nous marchons, non par la vue),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'nous préférons, quoique nous soyons pleins de courage, déloger de ce corps et habiter près du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'C\'est pour ce motif que toute notre ambition est de lui être agréables, soit que nous demeurions dans ce corps, soit que nous en délogions;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'car ce que nous sommes tous doit être mis en plein jour devant le tribunal de Christ, afin que chacun reçoive selon le bien ou le mal qu\'il aura fait, étant dans son corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Etant donc pénétrés de la crainte du Seigneur, nous cherchons à convaincre les hommes que tels sont nos sentiments; quant à Dieu, il connaît le fond de notre coeur, et nous espérons que dans votre conscience, vous le connaissez aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Nous ne venons point nous recommander encore nous-même auprès de vous, mais vous fournir l\'occasion et les moyens de vous glorifier de nous, afin que vous puissiez répondre à ceux qui se glorifient de ce qui n\'est que grimace, et non sentiment du coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Car, si nous sommes hors de sens, c\'est pour Dieu; si nous sommes dans notre sens, c\'est pour vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'car l\'amour de Christ nous possède, persuadés comme nous le sommes, que si un seul est mort pour tous, tous donc sont morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'et qu\'il est mort pour tous, afin que ceux qui vivent, ne vivent plus pour eux-mêmes, mais pour celui qui est mort et qui est ressuscité pour eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Aussi, pour nous, ne connaissons-nous désormais personne selon la chair: quand même nous avons connu Christ selon la chair, maintenant nous ne le connaissons plus de cette manière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Si quelqu\'un est en Christ, il est une nouvelle créature: les choses anciennes sont passées, toutes choses sont devenues nouvelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Et tout cela vient de Dieu, qui nous a réconciliés avec lui par Jésus-Christ, et qui nous a confié le ministère de la réconciliation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Dieu, en effet, réconciliait le monde avec lui en Christ, en n\'imputant point aux hommes leurs péchés, et c\'est lui qui a mis en nous la parole de la réconciliation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'C\'est donc pour Christ que nous remplissons les fonctions d\'ambassadeur, comme si Dieu exhortait par nous. Nous vous en prions pour Christ: Réconciliez-vous avec Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Celui qui n\'a pas connu le péché, il l\'a traité pour nous comme pécheur, afin que nous possédions en sa personne, la justice qui vient de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Puisque nous faisons l\'oeuvre avec Dieu, nous vous exhortons à ne pas recevoir la grâce de Dieu en vain,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'car il dit: «Je t’ai exaucé au temps favorable; je t\'ai porté secours au jour du salut.» Voici, c\'est aujourd\'hui «le temps particulièrement favorable;» voici, c\'est aujourd\'hui «le jour du salut.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Nous faisons cette oeuvre, en ne donnant aucun sujet de scandale en quoi que ce soit, afin que notre ministère ne soit l\'objet d\'aucun blâme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Nous nous rendons recommandables sous tous les rapports, comme le doivent des ministres de Dieu, par une grande patience dans les afflictions, dans les nécessités, dans les extrêmes misères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'sous les coups, dans les prisons, dans les troubles, dans les travaux, dans les veilles, dans les jeûnes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'par la pureté, par la science, par la longanimité, par la bonté, par un esprit saint, par une charité sincère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'par la parole de vérité, par la puissance de Dieu; maniant de la droite et de la gauche les armes de la justice,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'tirant parti de la gloire et de l\'ignominie, de la bonne et de la mauvaise réputation; tenus pour imposteurs, bien que véridiques;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'pour inconnus, quoique bien connus; pour mourants, et voilà que nous vivons; pour châtiés, et pourtant nous ne sommes pas mis à mort;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'pour tristes, nous qui sommes toujours joyeux; pour pauvres, nous qui en enrichissons bon nombre; pour n\'ayant rien, nous qui avons tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Notre bouche s\'est ouverte pour vous, ô Corinthiens, notre coeur s\'est élargi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'vous n\'êtes point à l\'étroit au dedans de nous, tandis que nous sommes à l\'étroit dans votre affection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Rendez-nous la pareille; je vous parle comme à mes enfants; vous aussi, élargissez vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne vous unissez point aux infidèles, car quelle parenté ya-t-il entre la justice et l\'iniquité? ou, qu\'a de commun la lumière avec les ténèbres?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Quel accord y a-t-il entre Christ et Bélial? ou, quel rapport y a-t-il entre le fidèle et l\'infidèle?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Quelle compatibilité y a-t-il entre le temple de Dieu et les idoles? car nous sommes le temple du Dieu vivant, comme Dieu l’a dit: «J\'habiterai et je marcherai au milieu d\'eux; je serai leur Dieu et ils seront mon peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'C\'est pourquoi, sortez du milieu d\'eux et séparez-vous d\'eux, dit le Seigneur. Ne touchez point à ce qui est impur, et moi je vous adopterai:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'je serai pour vous un père, et vous serez pour moi des fils et des filles, dit le Seigneur tout-puissant. »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Puis donc que nous avons de telles promesses, purifions-nous, mes bien-aimés, de toute souillure de la chair et de l\'esprit, en achevant l\'oeuvre de notre sanctification dans la crainte de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Donnez-nous une place dans vos coeurs. Nous n\'avons fait tort à personne, nous n\'avons ruiné personne, nous n\'avons dupé personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Je ne dis pas cela pour vous condamner, puisque je viens de vous dire que vous êtes dans notre coeur, à la vie et à la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Je m\'épanche avec vous; je suis tout fier de vous; je suis rempli de consolation; je suis inondé de joie au milieu de toutes mes afflictions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Lorsque nous fûmes arrivé en Macédoine, notre chair n\'eut aucun repos; nous étions affligés de toute manière: au dehors, des combats; au dedans, des appréhensions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mais Dieu qui console ceux qui sont abattus, nous a consolés par l\'arrivée de Tite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'et non seulement par son arrivée, mais encore par la consolation qu\'il avait lui-même éprouvée à votre sujet: il nous a dit vos regrets, votre désolation, votre dévouement pour moi, ce qui a redoublé ma joie en l\'entendant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Quand même je vous ai attristés par ma lettre, je ne m\'en repens point: j\'en ai eu, il est vrai, du regret (je vois, en effet, que cette lettre vous a affligés, momentanément pourtant),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'mais à présent je suis heureux, non de ce que vous avez été attristés, mais de ce que cette tristesse vous a portés à la repentance; car vous avez été attristés selon Dieu, afin de n\'éprouver aucun dommage de notre part.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'La tristesse selon Dieu produit une repentance qui conduit à un salut qu\'on ne regrette point, au lieu que la tristesse du monde produit la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Voyez ce que c\'est que d\'avoir été attristés selon Dieu, ce que cela a produit pour vous: quel empressement! Que dis-je? quelle justification! quelle indignation! quelle crainte! quel regret! quel dévouement! quelle punition! Vous avez bien fait voir que vous étiez, vous-mêmes, innocents dans cette affaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Aussi bien je vous ai écrit, non à cause de l\'offenseur, ni même à cause de l\'offense, mais afin que votre dévouement pour nous éclatât au milieu de vous, devant Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'c\'est ce qui nous a consolé. A cette consolation, s\'est ajoutée une joie infiniment plus vive, celle que nous a causée la joie de Tite, dont vous avez tous tranquillisé l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Si je me suis un peu glorifié de vous auprès de lui, je n\'ai point eu à en rougir; mais comme nous vous avons toujours parlé avec vérité, aussi ce que nous avons dit devant Tite, en nous glorifiant de vous, s\'est trouvé véritable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Et son affection pour vous redouble, quand il se rappelle la docilité que vous lui avez tous montrée, et la crainte, le tremblement avec lequel vous l\'avez reçu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Je suis heureux de ce que, sous tous les rapports, je puis compter sur vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Nous vous informons, mes frères, de la grâce que Dieu a faite aux fidèles des églises de la Macédoine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Malgré la grande épreuve de la persécution, leur joie a été immense, et leur profonde pauvreté s\'est magnifiquement montrée par la richesse de leur libéralité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Ils ont donné selon leur pouvoir, je l\'atteste, et même au delà de leur pouvoir, d\'une manière toute spontanée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'nous ayant demandé fort instamment la faveur de prendre part à l\'assistance destinée aux saints;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'et, dépassant nos espérances, ils se sont donnés eux-mêmes au Seigneur d\'abord, puis à nous, par la volonté de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Nous avons donc prié Tite d\'aller chez vous achever, de la manière qu\'il l\'avait déjà commencée, cette oeuvre de bienfaisance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Comme vous excellez à tous égards, en foi, en éloquence, en science, en zèle pour tout ce qui est bien, et en affection pour nous, distinguez-vous aussi dans cette oeuvre de bienfaisance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ce n\'est pas un ordre que je vous donne, mais je profite de l\'empressement des autres, pour mettre aussi à l\'épreuve la sincérité de votre charité:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'vous connaissez la grâce de notre Seigneur Jésus-Christ, lui qui, étant riche, s\'est fait pauvre à cause de vous, afin de vous faire riches par sa pauvreté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'C\'est donc un avis que j\'exprime ici; vous n\'avez pas besoin d\'autre chose, vous qui les premiers, non seulement avez commencé à agir, mais encore en avez eu l\'intention dès l\'an passé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Eh bien! achevez maintenant votre oeuvre; comme il y a chez vous le bon vouloir de l\'intention, qu\'il y ait aussi l\'exécution selon vos moyens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Quand la bonne volonté existe, elle est agréable, pourvu qu\'on donne à raison de ce qu\'on peut, non à raison de ce qu\'on ne peut pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Il ne s\'agit pas de donner de l\'aisance aux autres en vous écrasant, vous: c\'est une affaire d\'égalité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'dans la circonstance présente votre superflu suppléera à leur disette, afin que leur superflu supplée aussi à la vôtre, de sorte qu\'il y ait égalité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'selon qu\'il est écrit: «Celui qui avait beaucoup recueilli, n\'avait pas trop, et celui qui avait peu recueilli, n\'avait pas trop peu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Grâces soient rendues à Dieu de ce qu\'il a mis au coeur de Tite le même zèle que nous avons pour vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Il a accueilli notre prière, et, dans son empressement, il part de son plein gré pour aller auprès de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Nous lui avons adjoint le frère dont toutes les églises font l\'éloge pour sa prédication de l\'évangile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'et qui, de plus, a été appelé par les suffrages des églises à porter avec nous l\'aumône que nous recueillons à la gloire du Seigneur même, et en preuve de notre bonne volonté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Nous prenons cette mesure, pour qu\'on ne nous adresse pas de reproches à propos de l\'importante somme que nous recueillons;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'car notre esprit se préoccupe de ce qui est bien, non seulement devant Dieu, mais encore aux yeux des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Nous avons envoyé avec eux notre frère, dont nous avons souvent éprouvé le zèle en mainte affaire, et que sa grande confiance en vous rend aujourd\'hui plus empressé encore.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Nous vous les recommandons, soit Tite, qui est mon collègue et mon aide au milieu de vous, soit nos frères, qui sont les délégués des églises, la gloire de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'En leur donnant des preuves de votre affection, et du juste orgueil que nous avons témoigné à votre sujet, vous le faites à la face des églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Quant à l\'assistance destinée aux saints, il est superflu de vous écrire à ce sujet:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'je sais votre bonne volonté, et je m\'en fais gloire pour vous auprès des Macédoniens, en annonçant que l\'Achaïe est toute prête dès l\'an passé. Votre zèle a été un stimulant pour la plupart.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Toutefois, je vous ai envoyé nos frères, afin que la bonne opinion que nous avons exprimée à votre égard, ne soit pas illusoire sur ce point, et que vous soyez prêts, ainsi que je l\'ai affirmé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Songez un peu: si des Macédoniens arrivaient avec moi, et qu\'ils vous trouvassent non préparés, quelle honte pour moi, pour ne pas dire pour vous, qu\'une telle assurance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'J\'ai donc cru devoir prier nos frères de nous devancer auprès de vous et de s\'arranger pour que ce bienfait, que vous avez promis, soit prêt, de manière que ce soit réellement un bienfait, non une lésinerie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Écoutez bien: Celui qui sème chichement, récoltera chichement; celui qui sème abondamment, récoltera abondamment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Que chacun donne comme il a décidé en son coeur de donner, sans regret, sans contrainte: «Dieu aime celui qui donne gaiement»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Il est puissant pour vous combler de toutes sortes de grâces, afin qu\'ayant toujours, en toutes choses, tout en suffisance, vous abondiez en toutes sortes de bonnes oeuvres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'selon qu\'il est écrit: «Il a fait des largesses, il a donné aux pauvres: sa justice demeure éternellement.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Celui qui fournit la semence au semeur, et le pain pour la nourriture, vous fournira la semence, il vous la multipliera, et il fera croître les fruits de votre justice;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'si bien qu\'enrichis de toute manière pour toute espèce de libéralité, nous contribuions à faire bénir Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'En effet, l\'assistance que vous procurez, non seulement pourvoit abondamment aux besoins des saints, mais elle est aussi une riche source d\'actions de grâces envers Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Instruits par l\'expérience de ce secours, les saints glorifient Dieu de l\'obéissance que vous montrez dans la profession de l\'évangile de Christ, et de la libéralité dont vous usez envers eux, et envers tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Ils prient pour vous et vous chérissent à cause de la grâce infinie que Dieu fait reposer sur vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Grâces soient rendues à Dieu pour son don ineffable!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Au reste, moi Paul, je vous invite par la douceur et la clémence de Christ — oui, moi qui «ai l’air d\'un lâche quand je suis au milieu de vous, mais qui suis hardi avec vous, quand je suis absent!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'je vous prie de ne pas m\'obliger, quand je serai présent, d\'oser avec l\'assurance dont je compte m\'armer contre certaines gens qui se figurent que nous marchons selon la chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Quoique nous marchions en la chair, nous ne combattons point selon la chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Les armes avec lesquelles nous combattons ne sont pas chamelles; elles sont puissantes, par la grâce de Dieu, pour renverser les forteresses:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'nous renversons les raisonnements et tout boulevard élevé contre la connaissance de Dieu; nous faisons prisonnière toute intelligence, pour l\'amener à l\'obéissance de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'et nous sommes tout prêt à sévir contre toute désobéissance, lorsque, de votre côté, l\'obéissance sera complète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Ah! vous regardez à «l\'air!» — Si quelqu\'un se persuade «qu\'il est à Christ,» qu\'il se mette bien dans l\'esprit, à son tour, sans qu\'on ait besoin de le lui dire, que s\'il appartient à Christ, nous aussi, nous lui appartenons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Si même je me faisais un peu plus gloire du pouvoir que le Seigneur m\'a donné, à moi, pour votre édification, non pour votre destruction, je me garderais bien d\'en rougir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'pour n\'avoir pas l\'air de chercher à vous intimider par mes lettres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'On dit en effet: «Ses lettres sont pleines d\'autorité et de force, mais, quand on le voit, c\'est un homme flasque, et sa parole n\'impose pas.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Que celui qui tient ce langage, se dise bien, que tel nous sommes en paroles dans nos lettres, étant absent, tel nous sommes en actions, quand nous sommes présents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Nous n\'avons pas la hardiesse de nous confondre ni de nous comparer avec certaines gens qui se recommandent eux-mêmes; mais, ces gens-là, en se mesurant à leur propre mesure, et en se comparant eux-mêmes à eux-mêmes, sont absurdes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Pour nous, nous ne nous glorifions pas outre mesure; mais, sans passer la ligne que Dieu a assignée pour mesure à notre activité, nous nous glorifierons d\'être parvenus jusqu’à vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Ce n\'est point une prétention exorbitante de notre part, comme si nous n\'étions pas parvenus jusqu’à vous, car c\'est bien jusqu’à vous, que nous sommes arrivés les premiers avec l\'évangile de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Nous ne nous glorifions point outre mesure, puisque nous ne nous glorifions pas des travaux d\'autrui; et nous gardons l\'espérance que, lorsque votre foi se sera développée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'nous agrandirons considérablement notre champ d\'action parmi vous, en suivant toujours notre ligne, de manière à porter l\'évangile dans les pays qui sont au delà du vôtre, sans entrer dans la circonscription d\'autrui pour nous glorifier de travaux déjà faits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Toutefois, «que celui qui se glorifie, se glorifie dans le Seigneur;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'car ce n\'est pas celui qui se recommande lui-même, qui est un homme éprouvé, c\'est celui que le Seigneur recommande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Plût à Dieu que vous supportiez un peu de déraison de ma part! Mais, oui, vous me supportez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'J\'ai conçu pour vous une sainte jalousie. Je vous ai fiancés à un seul époux, comme une vierge pure, pour vous présenter à Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'mais je crains bien que, comme Eve fut séduite par l\'astuce du serpent, vos esprits n\'aient été viciés, et n\'aient perdu leur candeur pour Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Ah! si l\'on venait vous prêcher réellement un Jésus que nous n\'eussions pas prêché, ou si vous receviez réellement un esprit que vous n\'eussiez pas reçu, ou un évangile que vous n\'eussiez pas embrassé, vous auriez raison de vous laisser faire; mais il n\'en est rien,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'car j\'estime que je n\'ai été inférieur en rien à ces éminents apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Si je suis étranger à l\'art de la parole, je ne le suis pas à la science: nous l\'avons bien fait voir sous tous les rapports, en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ou bien, ai-je commis un péché, parce qu\'en m\'abaissant moi-même pour vous élever, je vous ai annoncé gratuitement l\'évangile de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'J\'ai dépouillé d\'autres églises en recevant d\'elles une paie pour pouvoir vous servir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'et pendant que j\'étais chez vous et que je me trouvais dans le besoin, je n\'ai été à charge à personne. Des frères venus de Macédoine pourvurent à ce qui me manquait: sous tous les rapports, je me suis gardé de vous être à charge, et je m\'en garderai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Aussi vrai que la vérité de Christ est en moi, je vous proteste que cette gloire-là ne me sera pas enlevée dans les contrées de l’Achaïe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Et pourquoi? Parce que je ne vous aime pas? Ah! Dieu le sait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mais je le fais, et je le ferai, pour ôter ce prétexte à ceux qui cherchent un prétexte, afin que l\'on connaisse ce désintéressement dont ils se vantent, comme on connaît le nôtre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Ces gens-là sont de faux apôtres, des ouvriers astucieux qui se déguisent en apôtres de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'et il ne faut pas s\'en étonner: Satan se déguise bien en ange de lumière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Ce n\'est pas merveille donc, si ses ministres se déguisent en ministres de justice. Leur fin sera digne de leurs oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Je le répète: qu\'on ne croie pas que j\'aie perdu la raison, tout au moins, acceptez-moi comme si je l\'avais perdue, afin que je me glorifie aussi un peu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Ce que je vais dire, je ne le dis pas selon le Seigneur, mais comme si j\'étais en état de déraison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Puisque tant de gens se glorifient selon la chair, moi aussi je me glorifierai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Vous supportez volontiers les insensés, vous, si raisonnables;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'vous supportez bien qu\'on vous traite comme des esclaves, qu\'on vous dévore, qu\'on vous pille, qu\'on vous traite avec hauteur, qu\'on vous manque en face.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Ah! pour nous (je le dis à notre honte), nous avons été faible! Pourtant, qu\'on ose se vanter de quoi que ce soit (je parle en insensé), moi aussi, je l\'ose. Ils sont Hébreux; moi aussi, je le suis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Ils sont Israélites; moi aussi, je le suis. Ils sont de la postérité d\'Abraham; moi aussi, j\'en suis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Ils sont ministres de Christ (ah! je vais parler comme un homme qui ne se possède pas), je le suis plus qu\'eux: je le suis plus par les travaux, infiniment plus par les coups, excessivement plus par les emprisonnements: souvent j\'ai vu la mort de près.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'J\'ai reçu des Juifs, par cinq fois, quarante coups de fouet moins un;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'j\'ai été battu de verges trois fois; j\'ai été lapidé une fois; j\'ai fait naufrage trois fois; j\'ai passé un jour et une nuit dans l\'abîme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Souvent, dans mes voyages, j\'ai été en danger sur les fleuves, en danger des voleurs, en danger de la part de ceux de ma nation, en danger de la part des Gentils, en danger dans les villes, en danger dans les déserts, en danger sur mer, en danger parmi les faux frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'J\'ai enduré les labeurs et les peines, les veilles fréquemment, la faim et la soif, les jeûnes fréquemment, le froid et la nudité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Sans parler de tant d\'autres choses, j\'ai tout un courant d\'affaires qui m\'assiègent chaque jour, le souci de toutes les églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Qui est faible, que je n\'en souffre? Qui trébuche, que je n\'en aie la fièvre?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'S\'il faut se glorifier, je me glorifierai de ma faiblesse!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Dieu, qui est le Père de notre Seigneur Jésus-Christ, et qui est béni éternellement, m\'est témoin que je ne mens point:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'à Damas, le gouverneur du roi Aretas faisait garder la ville pour m\'arrêter;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'mais on me descendit par une fenêtre dans une corbeille, le long de la muraille; et j\'échappai ainsi de ses mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Il faut se glorifier... cela ne m\'est pas bon, car j\'en viendrai aux visions et aux révélations du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Je connais un homme en Christ, qui, il y a quatorze ans, fut ravi jusqu\'au troisième ciel (si ce fut avec son corps ou sans corps, je ne sais; Dieu le sait),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'et je sais que cet homme-là (si ce fut avec son corps ou sans son corps, je ne sais; Dieu le sait)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'fut enlevé dans le paradis, et qu\'il entendit des mystères qu\'il n\'est pas permis à un homme de révéler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Je me glorifierai pour cet homme-là, mais pour ce qui est de ma personne, je ne me ferai gloire que de mes faiblesses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Ce n\'est pas que si je voulais me glorifier, je fusse un insensé, car je dirais la vérité; mais je m\'en abstiens dans la crainte qu\'on ne se fasse de moi une idée supérieure à celle que produit ma vue ou ma parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'D\'ailleurs, pour que je ne vienne pas à m\'enorgueillir de la sublimité de ces révélations, il m\'a été donné une écharde pour la chair, un ange de Satan pour me frapper.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Trois fois, j\'ai prié le Seigneur de m\'en délivrer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'et il m\'a dit: «Ma grâce te suffit, car c\'est dans la faiblesse que ma force se déploie tout entière.» Je préfère donc bien volontiers me glorifier de mes faiblesses, afin que la force de Christ vienne reposer sur moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'C\'est pourquoi je me complais dans les faiblesses, dans les outrages, dans les nécessités, dans les persécutions, dans les extrêmes misères; je les endure pour Christ; car lorsque je suis faible, c\'est alors que je suis fort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'J\'ai été déraisonnable; c\'est vous qui m\'y avez contraint. C\'était à vous de parler avantageusement de moi, car je n\'ai été inférieur en quoi que ce soit à ces éminents apôtres, encore que je ne sois rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Les preuves de mon apostolat ont éclaté au milieu dé vous par une patience à toute épreuve, par des signes, des prodiges et des miracles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'En quoi avez-vous été moins bien traités que les autres églises, si ce n\'est que ma personne ne vous a point été à charge? Pardonnez-moi ce tort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Voici, je suis tout prêt à aller chez vous pour la troisième fois, et je ne vous serai point à charge, car ce que je recherche, ce ne sont pas vos biens, c\'est vous-mêmes. Ce n\'est pas aux enfants à thésauriser pour leurs parents, mais aux parents pour leurs enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Quant à moi, je dépenserai bien volontiers, et je me dépenserai moi-même tout entier pour vos âmes, dussé-je, en vous aimant toujours plus, être toujours moins aimé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, '— Eh bien! soit; «je ne vous ai pas été personnellement à charge; mais, en vrai fourbe, je vous ai attrapés par ruse!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Est-ce que par aucun de ceux que je vous ai adressés, j\'ai rien tiré de vous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'J\'ai invité Tite à se rendre chez vous, et je l\'ai fait accompagner par le frère que mus savez: est-ce que Tite a rien tiré de vous? N\'avons-nous pas marché dans le même esprit, sur les mêmes traces?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Depuis longtemps vous croyez que nous nous justifions devant vous. Détrompez vous; c\'est devant Dieu que nous parlons, en Christ, et toutes nos paroles, mes bien-aimés, sont pour votre édification.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Ah! je crains bien qu\'à mon arrivée je ne vous trouve pas tels que je voudrais vous voir, et que vous ne me trouviez aussi tel que vous ne voudriez pas que je sois. Je crains de trouver des querelles, de la jalousie, des emportements, des disputes, des médisances, des calomnies, de l\'orgueil, des troubles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Est-ce que, lorsque je vous verrai, mon Dieu m\'humiliera encore une fois par rapport à vous? est-ce que j\'aurai à pleurer sur plusieurs pécheurs qui ne se seront pas repentis de l\'impureté, du libertinage et des désordres auxquels ils se sont livrés?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Je vais me rendre chez vous pour la troisième fois. «Toute affaire sera décidée sur la déclaration de deux ou trois témoins. »');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Je vous l\'ai déjà dit, et je vous en préviens; comme je le fis lors de mon second séjour, étant présent, je le fais encore aujourd\'hui que je suis absent, je déclare à ceux qui ont péché auparavant et à tous les autres pécheurs, que, si je retourne chez vous, je ne les ménagerai pas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'puisqu\'il vous plaît de faire l\'épreuve de Christ, qui parle en moi: lui qui, loin d\'être faible à votre égard, a la force de sévir au milieu de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Il a, en effet, été crucifié à cause de sa faiblesse, mais il est plein de vie par la puissance de Dieu; nous aussi, si nous sommes faible en lui, nous serons plein de vie avec lui, grâce à la puissance de Dieu, pour sévir contre vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Examinez-vous vous-mêmes, pour voir si vous êtes dans la foi: éprouvez-vous vous-mêmes; ne reconnaissez-vous pas vous-mêmes que Jésus-Christ est en vous? à moins peut-être que vous ne puissiez soutenir cette épreuve.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Quant à nous, j\'espère bien que vous connaîtrez que nous ne craignons pas l\'épreuve.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Cependant nous prions Dieu que vous ne fassiez rien de mal, désireux que nous sommes, non de paraître, nous-même, un homme qui soutient l\'épreuve, mais de vous voir faire le bien, dussions-nous passer pour faillir nous-même à l\'épreuve;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'car nous n\'avons point de puissance contre la vérité, nous n\'en avons que pour la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'C\'est un bonheur pour nous, quand nous sommes faibles et que vous êtes forts; et même, nous ne demandons à Dieu autre chose que votre perfectionnement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'c\'est pour cette raison que je vous écris ces lignes, pendant que je suis loin de vous, afin qu\'arrivé chez vous, je n\'aie pas à user de sévérité selon le pouvoir que le Seigneur m\'a donné pour édifier, non pour détruire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Au reste, mes frères, soyez dans la joie; perfectionnez-vous; consolez-vous; soyez en bonne intelligence; vivez en paix; et le Dieu d\'amour et de paix sera avec vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saluez-vous les uns les autres par un saint baiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Tous les saints vous saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Que la grâce du Seigneur Jésus-Christ, l\'amour de Dieu et la communication du Saint-Esprit soient avec vous tous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paul, Apôtre (non par la grâce des hommes, ni par l\'intermédiaire d\'un homme, mais par l\'intermédiaire de Jésus-Christ et par la grâce de Dieu le Père, qui a ressuscité Jésus d\'entre les morts),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'ainsi que tous les frères qui sont avec moi, aux églises de Galatie:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'que la grâce et la paix vous soient données par Dieu notre Père et par notre Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'qui s\'est donné lui-même pour nos péchés, afin de nous arracher à la corruption du siècle présent, conformément à la volonté de Dieu notre Père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'à qui appartient la gloire aux siècles des siècles. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Je suis surpris que si vite vous vous laissiez détourner de Celui qui vous a appelés à la grâce de Christ, pour passer à un autre évangile;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'non qu\'il y ait un autre évangile, mais il y a certaines gens qui vous troublent, et qui veulent renverser l\'évangile de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mais, quand nous-même, quand un ange venu du ciel vous annoncerait un autre évangile que celui que nous avons annoncé, qu\'il soit anathème!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Nous l\'avons déjà dit, et nous vous le répétons à cette heure: si quelqu\'un vous annonce un autre évangile que celui que vous avez reçu, qu\'il soit anathème!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Est-ce la faveur des hommes que je me concilie en ce moment, ou celle de Dieu? Est-ce aux hommes que je cherche à plaire? Si je plaisais encore aux hommes, je ne serais pas serviteur de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Je vous le déclare, mes frères: l\'évangile que j\'ai prêché n\'a rien qui soit de l\'homme,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'car ce n\'est pas d\'un homme que je le tiens ni que je l\'ai appris; je l\'ai appris par une révélation de Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Vous avez entendu parler de ma conduite quand j\'étais dans le judaïsme; vous savez que je persécutais à outrance et ravageais l\'Église de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'et que je surpassais par mes progrès dans le judaïsme bon nombre de ceux de mon âge et de ma race, à cause de mon zèle excessif pour les traditions de mes pères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mais, quand Celui qui m\'a choisi dès le sein de ma mère et qui m\'a appelé par sa grâce,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'daigna me révéler son Fils, afin que je l\'annonçasse parmi les Gentils, sur le champ, sans consulter ni la chair ni le sang,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'sans même aller à Jérusalem vers ceux qui étaient apôtres avant moi, je me rendis en Arabie, puis je retournai à Damas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Ensuite, trois ans après, je montai à Jérusalem pour faire connaissance avec Céphas, et je restai quinze jours avec lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'mais je ne vis aucun des autres apôtres, si ce n’est Jacques, le frère du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Je déclare devant Dieu que je ne mens point dans tout ce que je vous dis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'J\'allai ensuite dans les parages de la Syrie et de la Cilicie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'mais mon visage était inconnu aux églises de Christ qui sont en Judée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Seulement, elles avaient entendu dire que celui qui les persécutait autrefois, prêchait maintenant la foi, qu\'il s\'efforçait alors de détruire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'et elles glorifiaient Dieu à mon sujet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Ensuite, après un intervalle de quatorze ans, je montai de nouveau à Jérusalem avec Barnabas; je pris aussi Tite avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Je m\'y rendis sur une révélation, et je leur exposai l\'évangile que je prêche parmi les Gentils. Je l\'exposai en particulier aux personnages les plus considérés, de peur de courir ou d\'avoir couru en vain;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'mais on n\'exigea pas même de Tite, qui m\'accompagnait et qui était Grec, qu\'il se fît circoncire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'J\'y montai à cause des faux frères intrus qui s\'étaient glissés parmi nous, pour espionner, afin de nous asservir, la liberté que nous avons en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Loin de nous soumettre à eux, nous ne leur cédâmes pas même un instant, afin que la vérité de l\'évangile vous demeurât acquise.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Quant à ceux qu\'on tient en si haute estime (ce qu\'ils ont été autrefois, ne m\'importe pas; Dieu ne fait pas acception de personnes), eh bien! ces hommes si considérés n\'ajoutèrent rien à mon exposition.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Au contraire, voyant que l’évangélisation des incirconcis m\'a été confiée, comme à Pierre, celle des circoncis');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(car celui qui a fait de Pierre l\'apôtre des circoncis, a aussi fait de moi l\'apôtre des Gentils)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'et reconnaissant la grâce qui m\'a été accordée, Jacques, Céphas et Jean, qui sont regardés comme des colonnes, nous donnèrent, à Barnabas et à moi, la main d\'association, afin que nous allassions, nous, vers les Gentils, et eux vers les circoncis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Ils nous prièrent seulement de nous souvenir des pauvres; ce que j\'ai eu soin de faire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Quand Céphas vint à Antioche, je lui résistai en face, parce que sa conduite était fort remarquée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Avant l\'arrivée de certaines personnes qui venaient d\'auprès de Jacques, il mangeait avec les Gentils, mais, quand elles furent arrivées, il se retira et s\'isola par crainte des partisans de la circoncision.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Les autres Juifs usèrent de dissimulation comme lui, si bien que Barnabas lui-même se laissa entraîner par leur hypocrisie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Quand je vis qu\'ils ne marchaient pas droit, selon la vérité de l\'évangile, je dis à Céphas devant tous: «Si, tout Juif que tu es, tu vis à la manière des Gentils, et non à la manière des Juifs, pourquoi forces-tu les Gentils à judaïser?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Pour nous, nous sommes Juifs de naissance; nous ne sommes pas du nombre de ces pécheurs de Gentils;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'néanmoins, sachant que l\'homme est justifié, non par les oeuvres de la loi, mais par la foi en Jésus-Christ, nous avons cru en Jésus-Christ, pour être justifiés par la foi en Christ, et non par les oeuvres de la loi; parce que nul ne sera justifié par les oeuvres de la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Or si, en cherchant à être justifiés en Christ, nous étions, nous aussi, trouvés pécheurs, Christ serait donc un ministre de péché. Loin de nous une telle pensée!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'En effet, si je réédifie les choses que j\'ai démolies, je me constitue moi-même transgresseur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'car c\'est par la loi, que moi, je suis mort à la loi, afin de vivre par la grâce de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'J\'ai été crucifié avec Christ, et je vis... mais ce n\'est plus moi qui vis, c\'est Christ qui vit en moi. La vie, dont je vis maintenant en la chair, est une vie en la foi au Fils de Dieu qui m\'a aimé, et s\'est donné lui-même pour moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Je n\'annule pas la grâce de Dieu; car si la justice s\'obtient par la loi, Christ est donc mort pour rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Galates insensés, qui vous a fascinés, vous, aux yeux de qui Jésus a été peint, comme s\'il eût été crucifié au milieu de vous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Je vous ferai une seule question: Est-ce par les oeuvres de la loi que vous avez reçu l\'Esprit, ou par la prédication de la foi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Êtes-vous si dépourvus de sens, qu\'après avoir commencé par l\'esprit, vous finissiez maintenant par la chair?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Avez-vous fait de si grandes expériences en vain? si du moins c\'est en vain!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Celui qui vous dispense l\'Esprit et qui opère des miracles en vous, le fait-il donc par les oeuvres de la loi ou par la prédication de la foi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Comme «Abraham eut foi en Dieu, et cela lui fut imputé à justice,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'reconnaissez donc que ceux-là sont fils d\'Abraham, qui ont la foi pour principe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'L\'Écriture prévoyant que Dieu justifierait les Gentils par la foi, donna d\'avance à Abraham cette bonne nouvelle: «Toutes les nations de la terre seront bénies en toi;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'de sorte que ceux qui s\'en tiennent à la foi, sont bénis avec Abraham, l\'homme de foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'En effet, tous ceux qui s\'appuient sur les oeuvres de la loi, sont sous la malédiction, car il est écrit: «Maudit est quiconque n\'observe pas tous les commandements qui sont écrits dans le livre de la Loi, de manière à les pratiquer.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Que nul ne soit juste devant Dieu par la loi, c\'est évident, puisque «le juste vivra par la foi;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'or la loi ne relève pas de la foi, mais son principe est: «Celui qui observera ces commandements obtiendra ainsi la vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christ nous a libérés de la malédiction de la loi, s\'étant fait malédiction pour nous (puisqu\'il est écrit: «Maudit est quiconque est pendu au bois,»)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'afin que «la bénédiction» annoncée à Abraham se réalisât pour «les nations» en Jésus-Christ, et que nous reçussions par la foi l\'Esprit qui a été promis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Mes frères (je parle d\'après les usages humains), quand un contrat est passé en bonne forme, personne, quoique l\'engagement soit pris par un homme, ne peut l\'annuler, ni y rien ajouter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Or c\'est «à Abraham et à sa postérité» que Dieu a fait les promesses, il ne dit pas «et à tes postérités,» comme s\'il s\'agissait de plusieurs, mais il dit «et à ta postérité,» parce qu\'il ne s\'agit que d\'une seule, savoir Christ');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, '— eh bien! j\'affirme que la Loi, qui est venue quatre cents ans après, ne peut casser un engagement antérieur que Dieu a pris en bonne forme, et annuler la promesse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'car si l\'héritage s\'obtient par la loi, il ne vient plus d\'une promesse: mais c\'est bien par une promesse que Dieu a accordé cette faveur à Abraham.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Pourquoi donc la Loi a-t-elle été donnée? — Elle a été ajoutée à la promesse, pour faire apparaître les transgressions, jusqu’à ce que vînt «la postérité» à qui la promesse a été faite: les anges l\'ont donnée par l\'entremise d\'un médiateur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'or un médiateur n\'est pas médiateur d\'une seule personne, et Dieu est une seule personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'La Loi va-t-elle donc contre les promesses de Dieu? — Non, sans doute. Il est vrai que, si une loi capable de donner la vie, eût été donnée, la justice s\'obtiendrait par la loi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'mais loin de là, l\'Écriture a enfermé tous les hommes sous le péché, afin que la promesse advînt, par la foi en Jésus-Christ, à ceux qui ont la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Avant que vînt la foi, nous étions sous les verrous de la loi, enfermés en vue de l\'apparition future de la foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'de sorte que la loi a servi d\'instituteur pour nous mener à Christ, afin que nous fussions justifiés par la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Mais, la foi étant venue, nous ne sommes plus sous un instituteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'car vous êtes tous fils de Dieu par la foi en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Vous tous, en effet, qui avez été baptisés en Christ, vous avez revêtu Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Il n\'y a ici ni Juif ni Grec, ni esclave ni homme libre, ni homme ni femme, car tous vous ne formez qu\'une seule personne en Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'et, si vous faites corps avec Christ, vous êtes donc «postérité» d\'Abraham, héritiers, selon la promesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Or j\'affirme qu\'aussi longtemps que l\'héritier est enfant, il ne diffère en rien d\'un esclave, quoiqu\'il soit le maître de tout:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'mais il est soumis à des tuteurs et à des curateurs jusqu\'au temps marqué par le père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Nous, de même, quand nous étions enfants, nous étions esclaves des grossières instructions du monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'mais, quand le temps est venu, Dieu a envoyé son Fils, né d\'une femme, né sous la loi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'pour affranchir ceux qui sont sous la loi, afin de faire de nous des fils adoptifs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'et, parce que vous êtes fils, Dieu a envoyé dans vos coeurs l\'esprit de son Fils, lequel crie: «Abba! Père!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Ainsi tu n\'es pas esclave, tu es fils; si tu es fils, tu es aussi héritier par la grâce de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mais, tandis qu\'alors, ne connaissant pas Dieu, vous serviez des êtres qui, de leur nature, ne sont pas des dieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'maintenant que vous connaissez Dieu, bien mieux! que vous êtes connus de Dieu, comment retournez-vous à ces faibles et pauvres rudiments, auxquels vous voulez recommencer à vous assujettir?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vous observez les jours, les mois, les saisons, les années!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Je crains bien que toute la peine que je me suis donnée pour vous, ne soit perdue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Soyez comme moi, mes frères, je vous en prie, car moi aussi, j\'ai été comme vous. Vous ne m\'avez fait aucun tort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Vous savez bien que c\'est à cause d\'une infirmité de la chair, que je vous évangélisai la première fois;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'et vous ne m\'avez ni méprisé ni repoussé, malgré l\'épreuve où vous mettait ma chair; vous m\'avez reçu comme un ange de Dieu, comme Jésus-Christ lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Qu\'est-ce donc qui vous rendait si heureux? car je vous rends témoignage que, si c\'eût été possible, vous vous seriez arraché les yeux pour me les donner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Ainsi, j\'ai été votre ennemi en vous enseignant la vérité!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Ces gens se prennent d\'une vive affection pour vous, mais ce n\'est pas d\'une manière honorable; ils veulent vous isoler, afin que vous vous preniez d\'une vive affection pour eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Il est beau d\'être l\'objet d\'une vive affection, quand c\'est dans le bien, toujours et non pas seulement quand je suis près de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Mes chers enfants, pour qui je ressens de nouveau les douleurs de l\'enfantement, jusqu’à ce que Christ soit formé en vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'que je voudrais être près de vous à cette heure, et changer de langage, car je suis dans une grande perplexité à votre sujet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dites-moi, vous qui voulez être sous la loi, n\'entendez-vous point la Loi?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'car il est écrit qu\'Abraham eut deux fils, l\'un de la servante, l\'autre de la femme libre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Mais le fils de la servante est né selon la chair, tandis que le fils de la femme libre est né en vertu de la promesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Tout cela a un sens allégorique. Ces femmes sont deux alliances: l\'une du mont Sinaï, enfantant pour sa servitude, c\'est Agar');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, '(car l\'Agar, c\'est le mont Sinaï en Arabie), elle correspond à la Jérusalem actuelle, qui, en effet, est esclave avec ses enfants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mais la Jérusalem d\'en haut est libre, c\'est notre mère;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'car il est écrit: «Réjouis-toi, stérile, toi qui n’a pas enfanté; éclate en cris d\'allégresse, toi qui n\'as pas connu les douleurs de l’enfantement; car les enfants de la femme délaissée sont plus nombreux que ceux de la femme qui a son mari.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Pour vous, mes frères, vous êtes enfants de la promesse, à la manière d\'Isaac;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'mais, comme alors celui qui était né selon la chair persécutait celui qui était né selon l\'esprit, ainsi en est-il encore maintenant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Mais que dit l\'Écriture? — «Chassez l’esclave et son fils, car le fils de l’esclave n\'héritera pas avec le fils de la femme libre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'C\'est pourquoi, mes frères, nous ne sommes pas enfants d\'une esclave, mais nous sommes enfants de la femme libre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'en vertu de la liberté, pour laquelle Christ nous a affranchis. Tenez donc ferme, et ne vous laissez pas mettre sous le joug de la servitude.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'C\'est moi, Paul, qui vous le dis: si vous vous faites circoncire, Christ ne vous servira de rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Je déclare encore une fois à tout homme qui se fait circoncire, qu\'il est tenu d\'observer la Loi tout entière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vous avez complètement rompu avec Christ, vous qui voulez être justifiés par la loi; vous êtes déchus de la grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Pour nous, c\'est de l\'esprit, par la foi que nous attendons l\'espérance de la justice;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'car en Jésus-Christ, ce qui importe, ce n\'est ni la circoncision ni l\'incirconcision, c\'est la foi agissante par la charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vous couriez bien; qui vous arrêtés, et vous a détournés d\'obéir à la vérité?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Ce conseil-là ne vient pas de Celui qui vous a appelés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Un peu de levain fait lever toute la pâte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'J\'ai, dans le Seigneur, cette confiance en vous que vous ne penserez pas autrement. Quant à celui qui met le trouble parmi vous, il en portera la peine, quel qu\'il soit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Pour moi, mes frères, si je prêche encore la circoncision, pourquoi suis-je encore persécuté? le scandale de la croix a donc été levé!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Que ne se font-ils mutiler, ces gens qui vous troublent!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Mes frères, vous avez été appelés à la liberté; seulement, que votre liberté ne serve pas d\'excitation à la chair, mais asservissez-vous, par la charité, les uns aux autres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'car toute la loi se résume dans une seule parole: «Tu aimeras ton prochain comme toi-même.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Si vous vous mordez et vous dévorez les uns les autres, prenez garde que vous ne soyez détruits les uns par les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Je vous le dis, marchez par l\'esprit, et n\'accomplissez pas les désirs de la chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'La chair, en effet, a des désirs contraires à ceux de l\'esprit, et l\'esprit en a de contraires à ceux de la chair; ils se contrecarrent, afin que vous ne réalisiez pas ce dont vous auriez le vouloir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Si vous êtes conduits par l\'esprit, vous n\'êtes point sous la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Or les oeuvres de la chair sont évidentes, c\'est le libertinage, l\'impureté, le désordre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'l\'idolâtrie, la magie, les inimitiés, les querelles, les jalousies, les emportements, les disputes, les divisions, les partis,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'l\'envie, les meurtres, les excès de vin et de table et autres choses semblables. Je vous préviens, comme je vous en ai déjà prévenus, que tous ceux qui commettent de telles choses, n\'hériteront pas le royaume de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Le fruit de l\'esprit, au contraire, c\'est l\'amour, la joie, la paix, la patience, la mansuétude, la bonté, la bonne foi, la douceur, la tempérance:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'contre de telles choses, il n\'y a pas de loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Ceux qui appartiennent à Christ ont crucifié la chair avec ses passions et ses désirs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Si nous vivons par l\'esprit, marchons aussi par l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne nous laissons point aller à la vaine gloire, nous provoquant les uns les autres, et nous portant mutuellement envie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Mes frères, alors même qu\'un homme serait surpris en quel que faute, vous qui êtes spirituels, redressez-le avec un esprit de douceur, prenant garde à vous-mêmes, pour que vous ne tombiez pas en tentation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Portez les fardeaux les uns des autres, et vous accomplirez ainsi la loi de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'car si quelqu\'un croit être quelque chose, quoiqu\'il ne soit rien, il se fait illusion à lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Que chacun examine ses propres oeuvres, et alors il aura matière à se glorifier en se comparant à soi-même seulement, et non en se comparant à autrui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'car chacun a son propre fardeau à porter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Que celui à qui l’on enseigne la Parole, fasse part de tous ses biens à celui qui l\'enseigne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne vous abusez pas; on ne se moque pas de Dieu: ce qu\'on aura semé, on le recueillera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Celui qui sème pour sa propre chair, recueillera de la chair, la corruption; celui qui sème pour l\'esprit, recueillera de l\'esprit, la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Ne nous lassons point de bien faire, car nous recueillerons en son temps, si nous ne nous relâchons pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Ainsi donc, puisque nous en avons l\'occasion, faisons envers tous ce qui est bien, mais surtout envers nos frères en la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Voyez avec quelles grosses lettres je vous écris de ma propre main.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Ceux qui vous forcent à vous faire circoncire, ce sont tous ces gens qui veulent se donner bonne apparence en la chair, dans le seul but de n\'être pas persécutés pour la croix de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'car quoiqu\'ils se soient fait circoncire, eux-mêmes n\'observent pas la Loi; ils veulent que vous soyez circoncis, afin de se glorifier dans votre chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Pour moi, Dieu me garde de me glorifier, si ce n\'est dans la croix de notre Seigneur Jésus-Christ, par lequel le monde est crucifié pour moi, comme je le suis pour le monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'car la circoncision n\'est rien, l\'incirconcision n\'est rien; ce qui est tout, c\'est d\'être une nouvelle créature.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Paix et miséricorde sur tous ceux qui marcheront d\'après cette règle, et sur l\'Israël de Dieu!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Qu\'à l\'avenir, personne ne me fasse de la peine, car je porte sur mon corps les stigmates de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit, mes frères! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paul, Apôtre de Jésus-Christ par la volonté de Dieu, aux saints qui sont [à Éphèse] et aux fidèles en Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'que la grâce et la paix vous soient données par Dieu, notre Père, et par notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, de ce qu\'il nous a comblés en Christ de toutes sortes de bénédictions spirituelles dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'C\'est en Christ qu\'il nous a élus avant la fondation du monde, pour être saints et parfaits devant Lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'après nous avoir, dans son amour, désignés d\'avance pour ses fils adoptifs par Jésus-Christ, d\'après le bon plaisir de sa volonté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, '— à la louange de la grâce magnifique qu\'il nous a faite en son Bien-aimé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'C\'est en lui que nous avons la délivrance par son sang, le pardon de nos fautes, selon les richesses de sa grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Il l\'a abondamment répandue sur nous, cette grâce, et avec elle toute espèce de sagesse et d\'intelligence,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'nous révélant le mystère de sa volonté, conformément au dessein, que, dans sa bienveillance, il avait formé en lui-même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'et qu\'il devait réaliser, quand les temps seraient venus, à savoir de réunir toutes choses en Christ, celles qui sont dans les cieux et celles qui sont sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'C\'est aussi en lui que nous avons été faits héritiers, ayant été désignés d\'avance pour cet héritage, d\'après le dessein de Celui qui opère toutes choses selon le plan voulu de Lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'pour que nous servions à la louange de sa gloire, nous qui d\'avance avons espéré en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'C\'est en lui que vous-mêmes, après avoir entendu la parole de vérité, la bonne nouvelle de votre salut — c\'est en lui, dis-je, qu\'en suite de votre foi, vous avez été marqués du sceau du Saint-Esprit, qui avait été promis,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'et qui est le gage de notre héritage en attendant la délivrance de ceux qu\'il s\'est acquis, à la louange de sa gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'C\'est pourquoi, ayant entendu parler de votre foi au Seigneur Jésus et de votre charité pour tous les saints,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'je ne cesse, moi aussi, de rendre grâces pour vous en faisant mention de vous dans mes prières,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'afin que le Dieu de notre Seigneur Jésus-Christ, le Père de gloire, vous donne dans sa connaissance, un esprit de sagesse et de révélation;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'et qu\'il illumine les yeux de votre coeur, pour que vous sachiez quelle est l\'espérance à laquelle il vous a appelés, quelles sont les richesses de la gloire de son héritage au milieu des saints,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'et quelle est, envers nous qui croyons, l\'infinie grandeur de sa puissance, à la juger par l\'efficacité puissante de sa force.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Il l\'a déployée en Christ, lorsqu\'il l’a ressuscité des morts, et qu\'il l\'a fait asseoir à sa droite, dans les cieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'bien au-dessus de toute principauté, de toute autorité, de toute puissance, de toute dignité et de tout nom qui se peut nommer, non-seulement dans ce temps-ci, mais encore dans le siècle à venir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'et lorsqu\'il a mis toutes choses sous ses pieds et l’a donné pour chef suprême à l\'Eglise,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'qui est son corps, l\'oeuvre parfaite de celui qui rend tout parfait en tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Et vous, vous étiez morts par vos fautes et par les péchés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'auxquels vous vous livriez autrefois, suivant le train de ce monde, suivant le prince de la puissance de l’air, de l\'esprit qui agit maintenant dans les hommes rebelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Nous tous aussi, nous étions autrefois de ce nombre, quand nous vivions dans nos passions charnelles, obéissant aux volontés de notre chair et aux caprices de notre esprit; et nous étions naturellement des enfants de colère comme les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Mais Dieu, qui est riche en miséricorde, à cause du grand amour dont il nous a aimés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'et alors que nous étions morts par nos fautes, nous a rappelés à la vie avec Christ (c\'est par grâce que vous êtes sauvés),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'il nous a ressuscités avec lui, il nous a fait asseoir avec lui dans les cieux, en Jésus-Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'afin de faire voir dans les temps qui vont venir, les richesses infinies de sa grâce, par la bonté dont nous sommes les objets en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'C\'est par grâce, en effet, que vous êtes sauvés, par le moyen de la foi; et cela ne vient pas de vous, c\'est le don de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'cela ne vient pas des oeuvres, afin que nul ne se glorifie');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, '— car nous sommes son ouvrage, ayant été créés en Jésus-Christ, pour faire de bonnes oeuvres, et Dieu a commencé par nous y rendre propres, afin que nous les pratiquions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'C\'est pourquoi, souvenez-vous, qu\'autrefois, vous, Gentils par la chair, traités d\'incirconcis par les soi-disant circoncis, qui ne le sont qu\'en la chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'souvenez-vous que vous étiez, en ce temps-là, sans Christ, étrangers à la bourgeoisie d\'Israël, en dehors des alliances résultant de la promesse, sans espérance et sans Dieu dans le monde;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'mais aujourd\'hui, en Christ, vous qui étiez autrefois éloignés, vous êtes rapprochés par le sang de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Car c\'est lui qui est notre paix, lui qui des deux peuples n\'en a fait qu\'un: il a abattu le mur de séparation, l\'inimitié entre eux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'abrogeant par sa chair la loi des ordonnances impératives; il a voulu par là refondre ces deux hommes en lui, pour en faire un seul homme nouveau, en établissant la paix,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'et réconcilier l\'un et l\'autre avec Dieu, par sa croix, de manière à ce qu\'ils forment un seul et même corps, en détruisant en sa personne l\'inimitié entre eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Et il est venu annoncer la paix à vous, qui étiez éloignés, et la paix à ceux qui étaient proches;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'car c\'est par lui que nous avons, les uns et les autres, accès auprès de Dieu dans un seul et même esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Ainsi donc vous n\'êtes plus des étrangers ni des passagers, mais vous êtes concitoyens des saints et gens de la maison de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Vous avez été édifiés sur le fondement des apôtres et des prophètes, la pierre angulaire étant Jésus-Christ lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'C\'est en lui que tout l\'édifice, harmoniquement ordonné, s\'élève pour être un temple saint, dans le Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'c\'est en lui que, vous aussi, vous êtes édifiés, pour former par l\'Esprit une maison où Dieu habite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'C\'est dans ce but que je vous écris, moi Paul, le prisonnier de Jésus-Christ pour vous, Gentils;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'si du moins vous avez entendu parler de la grâce, que, dans ses dispensations, Dieu m\'a accordée en vue de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'C\'est par une révélation que j\'ai été initié au mystère dont j\'ai dit quelques mots ci-dessus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'et vous pouvez apercevoir en les lisant, l\'intelligence que j\'en ai.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Il n\'a pas été révélé en d\'autres âges à l\'humanité, comme il l\'a été en ces derniers temps, par l\'Esprit, aux saints apôtres de Christ et à ses prophètes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'à qui il a été dévoilé que les Gentils sont avec les Juifs membres du même corps, cohéritiers et coparticipants de la même promesse, en Jésus-Christ, par l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'J\'ai été fait ministre de cet évangile par la faveur que la grâce de Dieu m\'a accordée, et par l’efficacité de sa puissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'C\'est à moi, le moindre des saints, qu\'a été faite cette faveur d\'annoncer à tous les Gentils les richesses insondables de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'et de les éclairer tous sur l\'économie du mystère, qui avait été caché de tout temps en Dieu, le créateur de toutes choses,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'afin qu\'à la vue de l\'Église, les principautés et les puissances dans les cieux connaissent aujourd\'hui la sagesse infiniment variée de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'selon le dessein éternel qu\'il a réalisé en Jésus-Christ, notre Seigneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'à qui nous devons la liberté de nous approcher de Dieu en toute assurance, par la foi que nous avons en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'C\'est pourquoi je vous prie de ne pas vous laisser décourager par les afflictions que j\'endure pour vous: elles sont votre gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'C\'est dans ce but que je fléchis les genoux devant le Père,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'de qui vient à tout ce qui s\'appelle «famille,» aux cieux et sur la terre, ce nom même de «famille.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Qu\'il veuille, selon les richesses de sa gloire, vous donner d\'être puissamment fortifiés par son Esprit, pour le développement de l\'homme intérieur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'en sorte que Christ habite en vos coeurs par la foi, afin qu\'étant enracinés et fondés dans l\'amour de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'vous soyez en état de comprendre avec tous les saints quelle en est la largeur et la longueur, la profondeur et la hauteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'et de connaître l\'amour de Christ, qui surpasse toute idée, afin que vous soyez parfaits en aspirant à toute la perfection de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'A Celui qui peut, par la puissance qui se déploie en nous, faire infiniment au delà de tout ce que nous demandons et pensons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'à Lui soit la gloire dans l\'Église et en Jésus-Christ, dans tous les âges, aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Je vous prie donc instamment, moi qui suis prisonnier dans le Seigneur, de vous conduire d\'une manière digne de la vocation qui vous a été adressée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'et cela, en toute humilité et en toute douceur, avec longanimité, vous supportant les uns les autres avec charité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'vous efforçant de conserver l\'unité de l\'esprit par le lien de la paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Il y a un seul corps et un seul Esprit, comme il y a une seule espérance, à laquelle vous avez été appelés par la vocation qui vous a été adressée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Il y a un seul Seigneur, une seule foi, un seul baptême,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'un seul Dieu et Père de tous, maître de tous, agissant et demeurant en tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Mais la grâce a été donnée à chacun de nous, selon la mesure de la libéralité de Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'aussi est-il dit: «Étant monté en haut, il a emmené prisonniers bien des captifs, et il a fait des largesses aux hommes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Or, que veut dire cette expression «il est monté,» sinon qu\'il était descendu ici-bas, sur la terre?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Celui qui est descendu est celui-là même qui est monté au plus haut, de tous les cieux, afin de rendre toutes choses parfaites:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'lui-même a donné les uns comme apôtres, les autres comme prophètes, d\'autres comme évangélistes, d\'autres comme pasteurs et docteurs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'pour le perfectionnement des saints, en vue de l\'oeuvre du ministère et de l\'édification du corps de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'jusqu’à ce que nous soyons tous parvenus à l\'unité de la foi et de la connaissance du Fils de Dieu, à l\'état d\'hommes faits, à la hauteur de la perfection de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Il a voulu que nous ne soyons plus des enfants, des gens flottants et emportés à tout vent de doctrine par la tromperie des hommes, par une adresse assortie aux manoeuvres de l\'erreur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'mais que, professant la vérité avec charité, nous croissions à tous égards en intimité avec lui, qui est le chef, le Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'C\'est de lui que tout le corps bien ordonné et bien lié par toutes les jointures dont ce corps est pourvu, tire son développement par le jeu harmonique de chacune des parties, et réalise par la charité son édification propre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Je dis donc et je déclare, dans le Seigneur, que vous ne devez plus marcher comme les Gentils, qui se laissent aller à la vanité de leurs pensées:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'leur esprit est obscurci de ténèbres, ils sont étrangers à la vie de Dieu, à cause de l\'ignorance où ils sont, et de l\'endurcissement de leur coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Ayant perdu tout sentiment moral, ils se sont abandonnés aux désordres, au point de commettre toute espèce d\'impuretés, en y joignant la cupidité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mais, pour vous, ce n\'est point ainsi que vous avez appris à connaître Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'si du moins vous avez entendu parler de lui, et si vous avez été instruits, à son école, de la vérité telle qu\'elle est en Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'On vous a enseigné que vous devez, comme le réclame votre conduite passée, vous défaire du vieil homme corrompu par les passions trompeuses,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'et vous renouveler par l\'Esprit dans vos pensées,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'de sorte que vous revêtiez l\'homme nouveau, qui est créé à l\'image de Dieu dans une justice et une sainteté que produit la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'En conséquence, que chacun de vous renonçant au mensonge, «parle avec vérité à son prochain;» car nous sommes membres les uns des autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, '«Êtes-vous en colère, ne péchez point; que le soleil ne se couche point sur votre colère.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Ne donnez pas non plus prise au diable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Que celui qui dérobait, ne dérobe plus, mais que plutôt il s\'occupe en travaillant de ses mains à quelque chose de bon, afin d\'avoir de quoi donner à celui qui est dans le besoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Qu\'aucune mauvaise parole ne sorte de votre bouche, mais si, dans l\'occasion, l\'un de vous a quelque parole propre à édifier, qu\'il la dise, afin qu\'elle fasse du bien à ceux qui l\'entendent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'n\'attristez pas le Saint-Esprit de Dieu, du sceau duquel vous avez été marqués pour le jour de la délivrance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Que toute aigreur, toute violence, toute colère, toute criaillerie, toute injure soient bannies du milieu de vous, et toute méchanceté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Soyez bons, pleins de tendresse les uns pour les autres, vous pardonnant réciproquement, comme Dieu vous a pardonné en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Soyez donc des imitateurs de Dieu, comme des enfants bien-aimés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'et marchez dans la charité, à l\'exemple de Christ, qui nous a aimés et qui s\'est donné lui-même à Dieu pour nous, en oblation et en sacrifice comme un suave parfum.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Que le libertinage et toute impureté, que l\'avarice ne soient pas même nommés parmi vous, comme il convient à des saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Qu\'on n\'entende point de paroles déshonnêtes ou extravagantes, ni de plaisanteries grossières, toutes choses malséantes; qu\'on entende plutôt des actions de grâces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Car retenez bien ceci, que d\'ailleurs vous savez, c\'est qu\'aucun libertin, aucun impur, ni aucun avare (car l\'avarice est une idolâtrie) n\'a part au royaume de Christ et de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Que nul ne vous abuse par de vains discours: c\'est bien à cause de ces vices que la colère de Dieu tombe sur les hommes rebelles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'ne soyez donc pas leurs complices.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Vous étiez autrefois ténèbres, à présent vous êtes lumière dans le Seigneur; conduisez-vous donc en enfants de lumière');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(car le fruit de la lumière consiste en toute sorte de bonté, de justice et de vérité)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'examinant ce qui est agréable au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Ne prenez aucune part aux oeuvres infructueuses des ténèbres; bien mieux, réprouvez-les;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'car il est honteux même de dire ce qu\'ils font en secret.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Toutes ces choses, quand elles sont réprouvées, sont mises en plein jour par la lumière, et tout ce qui est mis en plein jour est lumière;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'c\'est pour cela qu\'il est dit: «Réveille-toi, toi qui dors, et relève-toi d\'entre les morts, et le Christ fera briller sur toi sa lumière.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Prenez donc garde de vous conduire avec circonspection, non en insensés, mais comme des hommes sages,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'mettant l\'occasion à profit, car les jours sont mauvais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Ne soyez point déraisonnables, mais comprenez bien quelle est la volonté du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Ne vous laissez point aller aux excès de vin: il n\'y a là que dissolution; mais soyez parfaits en esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Entretenez-vous par des psaumes, par des hymnes et par des cantiques spirituels, chantant et psalmodiant au Seigneur, du fond de vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Rendez toujours grâces pour toutes choses à Dieu, notre Père, au nom de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Soumettez-vous les uns aux autres dans la crainte de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Femmes, soyez soumises à vos maris, comme au Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'car le mari est le chef de la femme, comme Christ est le chef de l\'Église. Christ est, il est vrai, le sauveur de l’Église, qui est son corps; mais n\'importe,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'de même que l\'Église est soumise à Christ, de même les femmes doivent être soumises à leurs maris en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Maris, aimez vos femmes comme Christ a aimé son Église, et s\'est livré lui-même à la mort pour elle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'afin de la sanctifier par la Parole, après l\'avoir purifiée par l\'ablution d\'eau,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'pour en faire lui-même, pour lui-même, l\'Église glorieuse, sans tache, ni ride, ni rien de semblable, mais sainte et parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'C\'est ainsi que les maris doivent aimer leurs femmes comme leurs propres corps: celui qui aime sa femme, s\'aime lui-même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'car jamais personne n\'a haï sa propre chair, mais il l\'entretient et la soigne, comme Christ en use avec son Église;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'car nous sommes les membres de son corps,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'formés «de sa chair et de ses os; c\'est pourquoi l’homme quittera son père et sa mère pour s\'attacher à sa femme, et les deux seront une seule chair.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ce mystère est grand, je le dis par rapport à Christ et à l\'Église.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Quoi qu\'il en soit, que chacun de vous aussi aime sa femme comme soi-même, et que la femme craigne son mari.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Enfants, obéissez à vos parents selon le Seigneur, car cela est juste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Honore ton père et ta mère; c\'est le premier commandement qui soit accompagné d\'une promesse:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '«afin que tu sois heureux et que tu vives longtemps sur la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Et vous, pères, n\'exaspérez pas vos enfants, mais élevez-les en les corrigeant et les avertissant selon le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Esclaves, obéissez à ceux qui sont vos maîtres selon la chair, avec crainte et tremblement, dans la droiture de votre coeur, comme à Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'non pas seulement quand ils ont l\'oeil sur vous, comme si vous ne cherchiez qu\'à plaire aux hommes, mais comme des serviteurs de Christ, qui font de bon coeur la volonté de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Servez-les avec affection, comme si vous serviez le Seigneur, et non des hommes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'certains que ce que chacun aura fait de bien, le Seigneur le lui rendra, qu\'il soit esclave ou qu\'il soit libre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Et vous, maîtres, agissez de même à leur égard; interdisez-vous la menace, sachant que leur maître et le vôtre est dans les cieux, et qu\'il ne fait pas acception de personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Du reste, cherchez des forces dans le Seigneur et dans sa vertu puissante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Revêtez-vous de l\'armure que Dieu nous donne, pour être en état de tenir contre les manoeuvres du diable,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'parce que ce n\'est pas seulement contre la chair et le sang que nous avons à lutter, mais contre les principautés et les autorités, contre les puissances de ce monde de ténèbres, contre les mauvais esprits qui sont dans l\'air;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'c\'est pourquoi saisissez toutes les armes de Dieu, afin de pouvoir résister dans le jour mauvais, et de demeurer debout, après avoir vaincu toutes les oppositions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Soyez donc fermes, ayant ceint vos reins de vérité, ayant revêtu la cuirasse de la justice');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'et chaussé vos pieds de l\'agilité que donne l\'évangile de paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Par-dessus tout, prenez le bouclier de la foi, avec lequel vous pourrez éteindre les traits enflammés du malin;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'puis, armez-vous du casque du salut et de l\'épée de l\'esprit, qui est la parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Adressez à Dieu toutes sortes de voeux et de supplications, en toute circonstance, et de coeur. Veillez dans ce but avec une persévérance continuelle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'priant pour tous les saints et pour moi, en particulier, afin qu\'il me soit donné d\'ouvrir la bouche et de faire connaître hardiment le mystère de l\'évangile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'pour le quel je fais les fonctions d\'ambassadeur, lié d\'une chaîne, afin, dis je, que je l\'annonce hardiment, comme j\'en dois parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Tychique, mon cher frère et mon fidèle serviteur dans le Seigneur, vous donnera de mes nouvelles, afin que vous sachiez, vous aussi, tout ce qui me concerne et ce que je fais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Je vous l\'envoie tout exprès pour que vous connaissiez l\'état de nos affaires, et qu\'il console vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Que la paix soit donnée aux frères, ainsi que la charité unie à la foi, par Dieu, notre Père, et par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que la grâce soit avec tous ceux qui aiment notre Seigneur Jésus-Christ d\'un amour inaltérable!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paul et Timothée, serviteurs de Jésus-Christ, à tous les saints en Jésus-Christ, qui sont à Philippes, ainsi qu\'aux évêques et aux diacres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'que la grâce et la paix vous soient données par Dieu, notre Père, et par notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Je ne cesse, dans toutes mes prières pour vous tous, de rendre grâces à mon Dieu de tous les bons souvenirs que j\'ai conservés de vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'lui adressant avec joie ma prière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'à cause de votre intérêt unanime pour l’avancement de l\'évangile, depuis le premier jour jusqu’à présent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Je m\'assure que Celui qui a commencé en vous une oeuvre excellente, en poursuivra l\'achèvement jusqu\'au jour de Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'C\'est une justice que je vous dois, de penser ainsi de vous tous, parce que je vous porte dans mon coeur, vous tous, qui, soit dans ma captivité, soit dans la défense et la confirmation de l\'évangile, prenez un si vif intérêt à la grâce qui m\'est accordée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Dieu m\'est témoin que je vous chéris tous avec la tendresse de Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'ce que je lui demande, c\'est que votre amour abonde de plus en plus en connaissance et en parfait jugement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'afin que, par une juste appréciation de ce qui vaut le mieux, vous soyez purs et parfaits pour le jour de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'possédant pleinement, par Jésus-Christ, le fruit de justice, à la gloire et à la louange de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Je désire que vous sachiez, mes frères, que ma position a même contribué aux progrès de l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'C\'est une chose bien connue dans tout le prétoire et partout ailleurs, que c\'est pour Christ que je suis dans les chaînes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'en sorte que la plupart des frères rassurés, grâce au Seigneur, par mes liens, osent d\'autant mieux annoncer la Parole, sans crainte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Quelques-uns, il est vrai, prêchent Christ par envie et dans un esprit de dispute; mais il y en a d\'autres qui le font avec des sentiments de bienveillance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'ils sont mus par l\'affection, sachant que je suis chargé de la défense de l\'évangile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'tandis que ceux-là, poussés par un esprit de rivalité, annoncent Christ avec des intentions qui ne sont pas pures: ils pensent me faire éprouver quelque vexation dans ma captivité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Mais qu\'importe? De quelque manière qu\'on le fasse, avec des arrière-pensées ou avec sincérité, Christ est annoncé, et je m\'en réjouis; bien plus, je m\'en réjouirai,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'car je sais que par vos prières et par le secours de l\'Esprit de Jésus-Christ, cela tournera à mon salut:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'j\'ai la ferme espérance que je n\'aurai à rougir de rien, mais que, maintenant comme toujours, Christ sera franchement glorifié en ma personne, soit par ma vie, soit par ma mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Car Christ est ma vie, et la mort m\'est un gain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Toutefois, si je dois vivre en ce corps, c\'est à cause de l\'oeuvre que j\'ai à faire; aussi ne sais-je ce que je dois souhaiter.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Je me sens pressé des deux côtés: j\'ai le désir de partir et d\'être avec Christ, car c\'est bien préférable;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'd\'autre part, il est plus nécessaire que je demeure dans ce corps, à cause de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Persuadé de cette nécessité, je sais que je demeurerai dans ce monde, et que j\'y demeurerai avec vous tous, pour l\'avancement et la joie de votre foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'afin que, par mon retour auprès de vous, vous ayez sujet de vous glorifier de plus en plus de moi, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Seulement, conduisez-vous d\'une manière digne de l\'évangile de Christ, afin que, soit que je vienne vous voir, soit que je sois absent, j\'apprenne que vous demeurez fermes dans un même esprit, et que vous combattez d\'un même coeur pour la foi de l\'évangile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'sans vous laisser aucunement intimider par les adversaires. Cette fermeté est un signe évident de ruine pour eux, et, pour vous, de salut: et cela vous vient de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'parce qu\'il vous a fait, à vous, la grâce, non-seulement d\'avoir foi en Christ, mais encore de souffrir pour lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'en soutenant le même combat que vous m\'avez vu soutenir, et que, comme vous le savez, je soutiens encore aujourd\'hui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Si donc il y a quelque consolation en Christ, s\'il y a quelque soulagement dans la charité, s\'il y a quelque communion d\'esprit, s\'il y a quelque tendresse et quelque compassion,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'rendez ma joie parfaite: soyez en bonne intelligence, ayant un même amour, une même âme, une seule et même pensée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Ne vous laissez pas aller à des sentiments de rivalité ou de vaine gloire; mais que l\'humilité vous fasse considérer les autres comme étant au-dessus de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Que nul n\'ait en vue ses propres intérêts, mais que chacun ait aussi égard à ceux des autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Soyez animés des mêmes sentiments dont Jésus-Christ a été animé:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'quoiqu\'il fût en forme de Dieu, loin de s\'en prévaloir pour s\'égaler à Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'il s\'est anéanti lui-même en prenant la forme de serviteur, en devenant semblable aux hommes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'et, ayant paru comme un simple homme, il s\'est abaissé lui même, se rendant obéissant jusqu’à la mort, jusqu’à la mort de la croix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'C\'est pourquoi Dieu l\'a souverainement élevé, et lui a donné le nom qui est au-dessus de tout nom,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'afin qu\'au nom de Jésus, tout genou fléchisse dans le ciel, sur la terre et sous la terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'et que toute langue confesse que Jésus-Christ est le Seigneur, à la gloire de Dieu son Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Ainsi, mes bien-aimés, comme vous avez toujours été obéissants, travaillez à votre salut avec crainte et tremblement, non seulement comme vous faisiez quand j\'étais avec vous, mais bien plus encore maintenant que je suis absent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'car c\'est Dieu qui produit en nous le vouloir et le faire, parce que c\'est son bon plaisir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Faites toutes choses sans murmures ni arrière-pensées,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'afin que vous soyez irréprochables et purs, des enfants de Dieu parfaits, au milieu d\'une génération perverse et corrompue, parmi laquelle vous brillez comme des luminaires dans le monde,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'en tenant haut la parole de vie: et je serai fier, lors de la journée de Christ, de n\'avoir ni couru ni travaillé en vain.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Et même si je dois servir de libation en offrant à Dieu le sacrifice de votre foi, j\'en suis heureux, et je m\'en réjouis avec vous tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'vous aussi soyez-en heureux, et réjouissez-vous-en avec moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'J\'espère que, grâce au Seigneur Jésus, je vous enverrai bientôt Timothée, afin de me sentir, moi-même, plein de courage, en recevant de vos nouvelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Je n\'ai personne qui partage comme lui mes sentiments, et qui puisse s\'intéresser véritablement à ce qui vous concerne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'car tous ont en vue leurs propres intérêts, et non ceux de Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Vous connaissez la solidité de son caractère, vous savez qu\'il s\'est dévoué avec moi, comme un enfant sous son père, au service de l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'J\'espère donc vous l\'envoyer aussitôt que j\'aurai vu clair dans mes affaires,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'et j\'ai la conviction que, grâce au Seigneur, je le suivrai moi-même de près.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'En attendant, j\'ai cru qu\'il était nécessaire de vous envoyer Epaphrodite, mon frère, le compagnon de mes travaux et de mes combats, que vous avez député pour subvenir à mes besoins;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'd\'ailleurs, il soupirait après vous tous, et il était tourmenté de ce que vous aviez su sa maladie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Il a été, en effet, tout près de la mort, mais Dieu a eu pitié de lui, et non pas seulement de lui, mais aussi de moi, afin que je n\'eusse pas tristesse sur tristesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Je me suis donc empressé de vous l\'envoyer, afin que la joie vous revînt en le voyant, et que, moi-même, je fusse moins triste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Accueillez-le donc, dans le Seigneur, avec une joie entière, et honorez de telles personnes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'car c\'est pour l’oeuvre qu\'il a failli mourir, en exposant sa vie pour accomplir ce que vous ne pouviez faire vous-mêmes, dans le service que vous me rendiez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Au reste, mes frères, réjouissez-vous dans le Seigneur. Pour moi, je ne crains point de vous redire toujours les mêmes choses, et pour vous, cela vous est bon:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'prenez garde aux chiens; prenez garde aux mauvais ouvriers; prenez garde à la fausse circoncision;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'car c\'est nous qui sommes la vraie circoncision, nous qui servons Dieu avec l\'esprit de Dieu, qui nous glorifions dans Jésus-Christ, et qui ne mettons pas notre confiance en la chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'quoique j\'aie, quant à moi, tout sujet de mettre aussi ma confiance en la chair. Si quelqu\'un croit pouvoir se confier en la chair, je le puis à plus juste titre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'moi qui suis un circoncis du huitième jour, de la race d\'Israël, de la tribu de Benjamin, hébreu fils d\'hébreux; pour la Loi, pharisien;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'pour le zèle, persécuteur de l\'Église; pour la justice de la Loi, sans reproche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mais ces qualités, qui étaient pour moi des gains, je les ai tenues pour un préjudice, à cause de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'et je les tiens certainement toutes pour un préjudice, à cause de l\'excellence de la connaissance de Jésus-Christ, mon Seigneur. J\'ai fait abandon de toutes ces choses pour lui; je les regarde toutes comme de la balayure, afin de gagner Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'et d\'être trouvé en lui, ayant, non ma propre justice, cette justice qui vient de la loi, mais celle qui s\'obtient par la foi en Christ, la justice qui vient de Dieu par la foi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'en sorte que je le connaisse, lui, et la puissance de sa résurrection, et la communion de ses souffrances, en reproduisant sa mort en ma personne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'pour tâcher de parvenir à la bienheureuse résurrection des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ce n\'est pas que j\'aie déjà saisi le prix, ou que je sois déjà arrivé à la perfection; mais je le poursuis, tachant de le saisir, parce que j\'ai été saisi moi-même par Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Pour moi, mes frères, je n\'estime pas de l\'avoir saisi, mais voici ce que je fais: je laisse ce qui est derrière moi, et me portant vers ce qui est devant moi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'je cours vers le but, pour remporter le prix auquel Dieu m\'a appelé d\'en haut, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Que ce soit là notre sentiment, à nous tous qui sommes parfaits, et si, sur quelque point, vous pensez différemment, eh bien! Dieu vous éclairera;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'seulement, au point où nous sommes arrivés, marchons comme nous l\'avons fait jusqu\'ici.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Soyez mes imitateurs, mes frères, et ayez les yeux sur ceux qui se conduisent comme nous, vu que nous vous servons de modèle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Il y en a plusieurs, que je vous ai souvent signalés, et qu\'aujourd\'hui encore je vous signale, les larmes aux yeux, comme les ennemis de la croix de Christ par la conduite qu\'ils mènent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'La fin de ces gens-là, c\'est la perdition; eux qui font leur Dieu de leur ventre, et mettent leur gloire dans ce qui fait leur honte, n\'ayant de goût que pour les choses terrestres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Pour nous, notre patrie est dans les cieux, d\'où nous attendons aussi, comme Sauveur, le Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'qui transformera notre corps vil, en le rendant semblable à son corps glorieux, par le pouvoir qu\'il a de s\'assujettir toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Ainsi, mes chers et bien-aimés frères, vous qui êtes ma joie et ma couronne, demeurez de cette manière fermes dans le Seigneur, mes bien-aimés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'J\'invite Évodie ainsi que Syntyche à être en bonne intelligence, dans le Seigneur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'oui, je te prie aussi, digne Syzygos de t\'intéresser à elles, car elles ont combattu avec moi pour l\'évangile, ainsi qu\'avec Clément et mes autres compagnons d\'oeuvre, dont les noms sont écrits dans le livre de vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Réjouissez-vous toujours dans le Seigneur; je vous le répète, réjouissez-vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Que votre douceur se fasse connaître à tout le monde: le Seigneur est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Ne vous inquiétez de rien, mais en toute circonstance, faites connaître vos besoins à Dieu par des prières et des demandes accompagnées d\'actions de grâces;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'et la paix de Dieu, qui surpasse toute intelligence, gardera vos coeurs et vos pensées, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Au reste, mes frères, que toutes les choses qui sont véritables, toutes celles qui sont respectables, toutes celles qui sont justes, toutes celles qui sont pures, toutes celles qui sont aimables, toutes celles qui sont bienséantes, tout ce qui est vertueux et digne de louange, soit l\'objet de vos pensées;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'en un mot, ce que vous avez appris et embrassé, ce que vous m\'avez entendu dire et vu faire moi-même, pratiquez-le; et le Dieu de paix sera avec vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'J\'ai ressenti une grande joie, dans le Seigneur, de ce que votre intérêt pour moi a enfin porté de nouveaux fruits; vous y songiez bien, mais l\'occasion vous manquait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ce n\'est pas le besoin qui me fait parler ainsi, car j\'ai appris à être content dans toutes les positions où je me trouve:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'je sais vivre à l\'étroit et je sais vivre dans l\'aisance; en tout et partout j\'ai appris à être rassasié et à avoir faim, à être dans l\'abondance et à être dans la disette;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'je puis tout par Celui qui me fortifie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Vous avez bien fait, néanmoins, de prendre part à ma détresse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'd\'ailleurs, vous savez bien aussi, vous, Philippiens, qu\'au commencement de la prédication de l\'évangile, quand je quittai la Macédoine, aucune église ne m\'ouvrit un compte de Doit et Avoir; vous seuls le fîtes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'car, déjà à Thessalonique, puis par deux fois, vous m\'avez envoyé de quoi subvenir à mes besoins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ce n\'est pas que je recherche les présents, mais je recherche le fruit qui vous en doit revenir et qui va s\'augmentant à votre compte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'J\'ai tout reçu et je suis dans l\'abondance; j\'ai été comblé en recevant d\'Épaphrodite vos dons, parfum suave, sacrifice que Dieu accepte et qui lui est agréable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mon Dieu pourvoira à tous vos besoins, suivant sa richesse, avec gloire, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'A Dieu, notre Père, soit la gloire aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saluez tous les saints en Jésus-Christ. Tous les frères qui sont avec moi, vous saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Tous les saints vous saluent, et principalement ceux qui sont de la maison de César.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Que la grâce du Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paul, Apôtre de Jésus-Christ par la volonté de Dieu, et Timothée, notre frère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'aux saints qui sont à Colosses, nos fidèles frères en Christ: que la grâce et la paix vous soient données par Dieu, notre Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Nous ne cessons de rendre grâces à Dieu, le Père de notre Seigneur Jésus-Christ, dans les prières que nous lui adressons pour vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'depuis que nous avons entendu parler de votre foi en Jésus-Christ et de votre charité pour tous les saints,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'à cause de l\'espérance qui vous est réservée dans les cieux, et dont on vous a déjà entretenus, quand on vous a annoncé la vérité évangélique.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'L\'évangile est au milieu de vous, comme il est dans le monde entier, où il porte des fruits et fait des progrès, ainsi que cela a eu lieu parmi vous, depuis le jour où vous avez entendu et connu la grâce de Dieu telle qu\'elle est véritablement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'telle aussi que vous l\'avez apprise de notre bien-aimé collègue Epaphras, qui est pour vous un fidèle ministre de Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'C\'est lui qui nous a informé de la charité toute spirituelle qui vous anime.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'C\'est pourquoi, du jour où nous l\'avons su, nous n\'avons cessé de prier pour vous, et de demander que vous ayez la pleine connaissance de la volonté de Dieu, avec toute sagesse et toute intelligence spirituelle,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'en sorte que vous vous conduisiez d\'une manière digne du Seigneur, pour lui plaire en toutes choses. Que Dieu vous donne de porter toutes sortes de bons fruits, de croître dans sa connaissance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'et d\'être fortifiés de toute manière par sa glorieuse puissance, pour tout supporter et endurer avec joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Soyez pleins de reconnaissance pour le Père, qui nous a rendus capables de partager le sort des saints dans la lumière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'en nous arrachant à la puissance des ténèbres pour nous transporter dans le royaume du Fils de son amour,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'en qui nous avons la délivrance, le pardon des péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'C\'est ce Fils qui est l\'image du Dieu invisible, le premier-né de toute la création,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'car c\'est en lui que toutes les choses ont été créées, celles qui sont dans les cieux et celles qui sont sur la terre, les choses visibles et les choses invisibles, les majestés, les seigneuries, les principautés, les puissances: tout a été créé par lui et pour lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Il est avant toutes choses et toutes choses subsistent en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Il est la tête du corps de l\'Église, lui qui est les prémices de la résurrection, le premier-né d\'entre les morts, afin qu\'il soit le premier en tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Car Dieu s\'est plu à faire habiter en lui toute la perfection,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'et à réconcilier avec soi, par lui, toutes choses, soit celles qui sont sur la terre, soit celles qui sont dans les cieux, en faisant la paix par le sang de sa croix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Vous aussi, qui étiez autrefois étrangers et ennemis par vos sentiments et par vos mauvaises oeuvres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Christ vous a maintenant réconciliés par la mort qu\'il a soufferte en sa chair, de manière à vous faire paraître devant lui, saints, sans tache et sans reproche;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'si du moins vous demeurez fondés et inébranlables dans la foi, sans vous écarter de l\'espérance proclamée par l\'évangile que vous avez entendu, qui a été prêché à toute créature sous ciel, et dont, moi Paul, je suis devenu ministre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Je suis heureux maintenant des souffrances que j\'endure pour vous, et j\'achève en ma chair ce qui manque aux souffrances de Christ pour son corps, qui est l\'Église.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'J\'en ai été fait ministre par la dispensation de Dieu, qui m\'a donné, en vue de vous, la tâche de répandre partout sa parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, '— ce mystère caché de toute éternité et avant tous les âges, mais révélé aujourd\'hui aux saints,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'à qui Dieu a voulu faire connaître quelle est la richesse de ce glorieux mystère parmi les Gentils: cette richesse, c\'est Christ au milieu de vous, c\'est l\'espérance de la gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'C\'est lui que nous annonçons, avertissant et instruisant tout homme en toute sagesse, afin de rendre tout homme parfait en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'C\'est aussi dans ce dessein que je travaille, en luttant avec l\'énergie qu\'il déploie puissamment en moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Car je veux que vous sachiez combien est grand le combat que je soutiens pour vous, pour ceux de Laodicée, et pour tous ceux qui ne me connaissent pas de visage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'afin que vos coeurs soient réconfortés, et qu\'étant unis par la charité, vous soyez enrichis d\'une pleine conviction de l\'intelligence et d\'une juste connaissance du mystère du Dieu de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'où se trouvent renfermés tous les trésors de la sagesse et de la science.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Je vous dis cela, afin que personne ne vous induise en erreur par des raisons spécieuses;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'car si je suis absent de corps, je suis néanmoins avec vous en esprit, heureux de voir l\'ordre qui règne chez vous, et la solidité de votre foi en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Ainsi donc, comme vous avez reçu le Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'attachez-vous aussi à lui dans toute votre conduite, étant enracinés en lui, et vous édifiant sur ce fondement, étant affermis par la foi, telle qu\'elle vous a été enseignée, et y faisant toujours de nouveaux progrès, avec reconnaissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Prenez garde que personne ne fasse de vous sa proie par la philosophie, vaine illusion qui appartient aux enseignements des hommes, aux grossières instructions du monde, et non à Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'car c\'est en lui qu\'habite toute la perfection de la Divinité, corporellement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'et en lui, vous êtes parfaits: lui, qui est le chef de toute principauté et de toute puissance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'lui en qui vous avez été circoncis d\'une circoncision qui n\'est pas de main d\'homme, par le dépouillement des influences charnelles du corps, par la circoncision de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'lorsque vous avez été ensevelis avec lui dans le baptême où vous êtes aussi ressuscités avec lui par la foi en la puissance de Dieu, qui l\'a ressuscité des morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Lorsque nous étions morts dans nos fautes et dans l\'incirconcision de notre chair, Dieu nous a rappelés avec Christ à la vie, en nous faisant grâce pour toutes nos fautes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Il a biffé l\'acte, dont les clauses nous étaient contraires, et l\'a supprimé en le clouant à la croix;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'il a dépouillé les principautés et les puissances du mal, et les a données en spectacle au monde, en les menant en triomphe par la croix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Que personne donc ne vous juge à l\'égard du manger et du boire, ou au sujet d\'une fête, d\'une nouvelle lune ou d\'un sabbat:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'ce n\'est là que l\'ombre des choses à venir, tandis que la réalité se trouve en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Que nul ne vous fasse perdre le prix, en vous poussant, sous couleur d\'humilité, à rendre un culte aux anges. Ces gens follement enflés par leurs idées charnelles, s\'embarquent dans des rêveries,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'et ne s\'attachent pas au chef, de qui, tout le corps bien constitué et bien lié au moyen des jointures et des ligaments, tire son développement par la croissance que Dieu donne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Si vous êtes morts avec Christ aux grossières instructions du monde, pourquoi, comme si vous viviez de la vie du monde, vous laissez-vous dicter ces arrêts:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '«Ne prends pas! ne goûte pas! ne touche pas!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'ce sont des choses qui, toutes, corrompent par l\'usage qu\'on en fait» — Ces défenses ne sont que des commandements et des enseignements d\'hommes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'elles ont, il est vrai, un renom de sagesse par le fait d\'un culte volontaire, d\'un sentiment d\'humilité, et d\'une rigueur exercée à l\'égard du corps, mais elles sont sans valeur aucune, parce qu\'elles ne servent qu\'à la satisfaction de la chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Si vous êtes ressuscités avec Christ, cherchez les choses qui sont en haut, où Christ est assis à la droite de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'attachez-vous aux choses d\'en haut, et non à celles qui sont sur la terre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'car vous êtes morts, et votre vie est cachée avec Christ en Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Lorsque Christ, qui est notre vie, paraîtra, vous aussi, vous paraîtrez avec lui dans la gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Faites donc mourir vos membres, ces membres qui sont de la terre, le libertinage, l\'impureté, la passion, les mauvais désirs et l’avarice, car elle est une idolâtrie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'C\'est là ce qui attire la colère de Dieu sur les hommes rebelles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'parmi lesquels vous marchiez autrefois, quand vous viviez dans ces désordres:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'mais aujourd\'hui, rejetez toutes ces souillures, la colère, l\'emportement, la méchanceté; que les injures et les paroles déshonnêtes soient bannies de votre bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'N\'usez point de mensonge les uns envers les autres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'puisque vous avez dépouillé le vieil homme avec ses oeuvres, et revêtu l\'homme nouveau, qui se renouvelle par la connaissance conformément à l\'image de Celui qui l\'a créé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'et cela, dans une sphère où il n\'y a ni Grec ni Juif, ni circoncis ni incirconcis, ni barbare ni Scythe, ni esclave ni homme libre, mais où Christ est tout en tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Revêtez-vous donc, comme des élus de Dieu saints et bien-aimés, d\'une tendresse compatissante, de bonté, d\'humilité, de douceur, de longanimité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'vous supportant les uns les autres, et, si l\'un a sujet de se plaindre de l\'autre, vous pardonnant réciproquement: comme le Seigneur vous a pardonné, pardonnez- vous aussi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Surtout, revêtez-vous de charité, c\'est le lien de la perfection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Que la paix de Christ, à laquelle vous avez été appelés pour ne former qu\'un seul et même corps, règne dans vos coeurs. Soyez reconnaissants.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que la parole de Christ habite richement en vous, de sorte que vous vous instruisiez et que vous vous avertissiez les uns les autres en toute sagesse, et que vous chantiez à Dieu des psaumes, des hymnes, des cantiques spirituels, du fond de vos coeurs, avec reconnaissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Que tout ce que vous faites, paroles ou actes, que tout se fasse au nom du Seigneur Jésus en rendant grâces par lui à Dieu, notre Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Femmes, soyez soumises à vos maris comme cela se doit, selon le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maris, aimez vos femmes, et ne vous aigrissez point contre elles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Enfants, obéissez en tout à vos pères et à vos mères, car c\'est une chose agréable au Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pères, n\'irritez pas vos enfants, afin qu\'ils ne se découragent pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Esclaves, obéissez en tout à ceux qui sont vos maîtres selon la chair, non pas seulement lorsqu\'ils ont l\'oeil sur vous, comme gens cherchant à plaire aux hommes, mais avec droiture de coeur, comme gens craignant le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Quoi que vous fassiez, acquittez-vous-en de bon coeur, comme pour le Seigneur, non pour les hommes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'sachant que vous recevrez du Seigneur l\'héritage pour récompense. Vous êtes au service de Christ, le Seigneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'celui qui commet l\'injustice, recevra la rétribution du tort qu\'il aura fait, et il n\'y aura pas acception de personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Maîtres, rendez à vos serviteurs ce qui est juste et équitable, sachant que vous avez aussi un maître dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Persévérez dans la prière, vous y appliquant avec vigilance et actions de grâces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Priez en même temps pour nous, afin que Dieu nous ouvre une porte pour parler, en sorte que j\'annonce le mystère de Christ, pour lequel je suis aussi dans les chaînes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'et que je le fasse connaître comme je dois en parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Conduisez-vous avec sagesse à l\'égard de ceux du dehors, en mettant l\'occasion à profit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Que votre parole soit toujours aimable, assaisonnée de sel, en sorte que vous sachiez comment vous devez répondre à chacun.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tychique, mon cher frère, mon fidèle serviteur et collègue dans le Seigneur, vous donnera de mes nouvelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Je vous l\'envoie tout exprès pour que vous connaissiez l\'état de nos affaires, et qu\'il console vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Je lui ai adjoint Onésime, mon cher et fidèle frère, qui est de votre pays: ils vous informeront de tout ce qui se passe ici.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarque, mon compagnon de captivité, vous salue, ainsi que Marc, cousin de Barnabas, au sujet duquel vous avez reçu des ordres. S\'il vient chez vous, accueillez-le.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Jésus aussi, appelé Justus, vous salue. Ce sont des circoncis, et les seuls d\'entre les circoncis qui travaillent avec moi à l\'avancement du royaume de Dieu: ils ont été ma consolation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epaphras, votre compatriote, vous salue: c\'est un serviteur de Christ; il combat toujours pour vous par ses prières, afin qu\'étant parfaits et bien convaincus, vous demeuriez fermes dans tout ce que Dieu veut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Je lui rends le témoignage qu\'il se donne bien de la peine pour vous, ainsi que pour ceux de Laodicée et d\'Hierapolis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Luc, le médecin, qui nous est cher, vous salue, ainsi que Démas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Saluez les frères qui sont à Laodicée, et Nymphas, et l\'assemblée qui se réunit dans sa maison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Lorsque vous aurez lu ma lettre, faites qu\'on la lise aussi dans l\'église des Laodicéens, et que vous pareillement, vous lisiez celle qui viendra de Laodicée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Dites à Archippe: «Considère bien le ministère que tu as reçu, dans le Seigneur, afin de le bien remplir.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Je vous salue de ma propre main, moi Paul. Souvenez-vous de mes liens. Que la grâce soit avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paul, Silvain et Timothée à l\'Eglise des Thessaloniciens, qui est en Dieu, le Père, et en Jésus-Christ, le Seigneur: que la grâce et la paix vous soient données!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nous ne cessons de rendre grâces à Dieu pour vous tous, en faisant mention de vous dans nos prières,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'nous rappelant sans cesse l\'oeuvre de votre foi, le labeur de votre charité et la fermeté de votre espérance en notre Seigneur Jésus-Christ, devant Dieu, notre Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Nous savons, frères bien-aimés de Dieu, votre élection:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'notre évangile, en effet, ne vous a pas été annoncé avec des paroles seulement, mais avec puissance, avec l’Esprit-Saint et avec une conviction profonde; vous savez du reste quels nous avons été parmi vous, à cause de vous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, '— vous-mêmes, vous avez été nos imitateurs et ceux du Seigneur, en accueillant la Parole au milieu de grandes afflictions, avec la joie que donne le Saint-Esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'si bien que vous avez été des modèles pour tous ceux qui croient dans la Macédoine et dans l\'Achaïe.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Car non seulement la parole du Seigneur a retenti de chez vous dans la Macédoine et dans l\'Achaïe, mais le bruit de votre foi en Dieu s\'est répandu en tout lieu, en sorte que nous n\'avons pas besoin d\'en parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Les gens eux-mêmes racontent ce qu\'a été notre venue chez vous, comment vous vous êtes convertis à Dieu, en abandonnant les idoles pour servir le Dieu vivant et vrai,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'et pour attendre des cieux son Fils qu\'il a ressuscité des morts, Jésus, qui nous délivre de la colère qui va venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Vous savez bien, vous-mêmes, mes frères, que notre venue chez vous n\'a pas été vaine;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'mais qu\'au sortir de Philippes, où nous avions souffert et avions été maltraités, vous ne l\'ignorez pas, nous ne laissâmes pas, nous confiant en notre Dieu, de vous annoncer hardiment son évangile malgré de grandes luttes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Car notre prédication n\'a point sa source dans une erreur, ni dans un sentiment impur; elle ne cache non plus aucune fraude;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'mais comme Dieu nous a trouvés dignes de nous confier l\'évangile, nous parlons aussi, non pour plaire aux hommes, mais pour plaire à Dieu, qui voit le fond de nos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Jamais, en effet, nous n\'avons usé de paroles flatteuses, comme vous le savez; ni de motifs intéressés, Dieu en est témoin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Nous n\'avons pas davantage recherché la gloire des hommes, qu\'elle vienne de vous ou d\'autres; quoique nous puissions prétendre à quelque autorité en notre qualité d\'apôtres de Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'nous nous sommes montrés, au contraire, pleins d\'affabilité au milieu de vous. Comme une nourrice prend soin de ses propres enfants,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'de même, dans notre tendresse pour vous, nous aurions voulu vous donner, non seulement l\'évangile de Dieu, mais encore nos propres vies, tant vous nous étiez chers.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Vous vous rappelez nos peines et nos labeurs, quand, travaillant jour et nuit pour n\'être à charge à aucun de vous, nous vous prêchâmes l\'évangile de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vous êtes témoins, et Dieu l\'est aussi, combien la conduite que nous avons tenue envers vous qui croyez, a été sainte, juste et irréprochable;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'comment, ainsi que vous le savez, nous vous exhortions, nous vous encouragions, et nous conjurions chacun de vous — comme un père, ses enfants');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, '— de vous comporter d\'une manière digne de Dieu, qui vous appelle à son royaume et à sa gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Et voilà pourquoi nous ne cessons, nous aussi, de rendre grâces à Dieu, de ce qu\'en recevant de nous la parole du message divin, vous l\'avez accueillie, non comme une parole d\'homme, mais, ainsi qu\'elle l\'est véritablement, comme la parole de Dieu. Cette parole aussi déploie sa puissance en vous qui croyez;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'car vous êtes devenus, mes frères, les imitateurs des églises de Dieu qui sont en Judée, et qui croient en Jésus-Christ, puisque, vous aussi, vous avez éprouvé de la part de vos propres compatriotes les mêmes traitements qu\'elles ont essuyés de la part des Juifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Ces mêmes Juifs ont fait mourir le Seigneur Jésus et les prophètes; ils nous ont persécutés; ils ne plaisent point à Dieu et sont les ennemis du genre humain');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'en nous empêchant de parler aux Gentils et de les sauver, en sorte qu\'ils mettent incessamment le comble à leurs péchés; mais la colère de Dieu va finalement les atteindre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Pour nous, mes frères, séparés un instant de vous, de corps et non de coeur, nous n\'avons fait que plus d\'efforts pour réaliser le vif désir que nous avions de vous aller voir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'puisque, par deux fois, nous avons voulu (du moins, moi, Paul) nous rendre auprès de vous; mais Satan nous en a empêché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Car, qui est notre espérance, notre joie et notre couronne de gloire? Ne le serez-vous pas, vous aussi, devant notre Seigneur Jésus, à son avènement?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, '— Oui, vous êtes notre gloire et notre joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Aussi, n\'y tenant plus, nous prîmes le parti de demeurer seul à Athènes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'et nous envoyâmes notre frère Timothée, qui est ouvrier avec Dieu dans la propagation l\'évangile de Christ, pour vous affermir et vous encourager dans votre foi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'afin que nul de vous ne se laissât ébranler au milieu de ces persécutions, qui, vous le savez vous-mêmes, sont notre partage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'car, lorsque nous étions avec vous, nous vous disions déjà que nous serions persécutés, comme cela est arrivé, et comme vous le savez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'C\'est pour ce motif, que, moi aussi, n\'y tenant plus, j\'envoyai reconnaître l\'état de votre foi; j\'appréhendais que le tentateur ne vous eût tentés, et que notre travail ne fût devenu inutile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mais Timothée, qui vient d\'arriver ici d\'auprès de vous, nous a donné de bonnes nouvelles de votre foi et de votre charité; il a ajouté que vous gardez toujours un bon souvenir de nous, désirant nous voir, comme nous désirons nous-même vous voir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Aussi, au milieu de toutes nos afflictions et de toutes nos calamités, avons-nous été consolé à votre sujet, mes frères, en apprenant votre foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Nous vivons maintenant, puisque vous demeurez fermes dans le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Nous ne pouvons assez rendre grâces à Dieu à votre sujet, pour toute la joie que vous nous faites ressentir devant lui,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'nous qui le prions jour et nuit, avec une ardeur extrême, de nous permettre d\'aller vous voir et d\'achever ce qui manque à votre foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Puisse-t-il, lui, notre Dieu et notre Père, puisse notre Seigneur Jésus aplanir notre route pour aller vers vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Puisse le Seigneur vous faire croître et abonder en charité les uns pour les autres et pour tous les hommes, comme nous-mêmes nous en sommes remplis pour vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'afin d\'affermir vos coeurs de manière à ce qu\'ils soient d\'une sainteté parfaite devant Dieu notre Père, au jour où notre Seigneur Jésus viendra avec tous ses saints!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Au reste, mes frères, nous vous prions et nous vous conjurons au nom du Seigneur Jésus, de marcher de mieux en mieux, comme vous l\'avez appris de nous et comme vous le faites aussi, dans la route qu\'il faut suivre pour plaire à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Vous savez bien quels commandements nous vous avons donnés de la part du Seigneur Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'car ce que Dieu veut, c\'est que vous vous conserviez purs: que vous vous absteniez du libertinage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'que chacun de vous sache posséder son corps dans la pureté et dans l\'honnêteté,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'et non en le livrant aux emportements de la passion, comme les Gentils qui ne connaissent point Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'il veut que nul ne trompe ni ne dupe son frère en affaires, attendu que le Seigneur fait justice de tous ces péchés, comme nous vous l\'avons déjà dit et déclaré;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'car Dieu nous a appelés, non à l\'impureté, mais à la sainteté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Celui donc qui rejette ces commandements, rejette, non un homme, mais Dieu, qui même a donné son Esprit, qui est saint, pour qu\'il se répande sur vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Quant à l\'amour fraternel, nous n\'avons pas besoin de vous en écrire, car Dieu vous a appris à vous aimer les uns les autres,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'et vraiment vous le faites à l\'égard de tous les frères qui sont dans la Macédoine entière. Nous vous invitons, mes frères, à vous acquitter toujours davantage de ce devoir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'à mettre votre honneur à vivre paisiblement, à vous occuper de vos propres affaires, et à travailler de vos mains, ainsi que nous vous l\'avons commandé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'afin que vous vous conduisiez honnêtement à l\'égard de ceux du dehors, et que vous n\'ayez besoin de rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nous ne voulons pas, mes frères, que vous soyez dans l\'ignorance au sujet de ceux qui sont morts, afin que vous ne vous affligiez pas comme les autres, qui n\'ont point d\'espérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Si nous croyons que Jésus est mort et ressuscité, de même nous devons croire que Dieu ramènera avec Jésus-Christ et par lui, ceux qui sont morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Nous vous affirmons par la parole du Seigneur, que nous qui vivons et qui sommes laissés pour l’avènement du Seigneur, nous ne devancerons point ceux qui sont morts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Le Seigneur lui-même, au signal donné, à la voix d\'un archange et au son de la trompette de Dieu, descendra du ciel; alors ceux qui sont morts en Christ ressusciteront d\'abord;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'puis nous, les vivants, ceux qui auront été laissés, nous serons enlevés tous ensemble avec eux sur les nuées pour aller au-devant du Seigneur, dans les airs; et ainsi nous serons toujours avec le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Consolez-vous donc les uns les autres dans ces pensées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Quant au temps et au moment, vous n\'avez pas besoin, mes frères, qu\'on vous en écrive.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Vous savez bien vous-mêmes, que le jour du Seigneur viendra comme un voleur dans la nuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Quand les gens diront, «paix et sûreté!» alors une ruine subite fondra sur eux, comme les douleurs saisissent une femme enceinte, et ils n\'échapperont point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mais vous, mes frères, vous n\'êtes pas dans les ténèbres pour que ce jour vous surprenne, comme nous surprend un voleur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'vous êtes tous enfants de la lumière et enfants du jour; nous ne sommes pas de la nuit ni des ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Ne dormons donc point comme les autres, mais veillons et soyons sobres;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'car ceux qui dorment, dorment la nuit, et ceux qui s\'enivrent, s\'enivrent la nuit;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'mais nous, qui sommes du jour, soyons sobres, ayant revêtu la cuirasse de la foi et de la charité, et ayant pris pour casque l\'espérance du salut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Car Dieu ne nous a pas destinés à être les objets de la colère, mais à posséder le salut par notre Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'qui est mort pour nous, afin que, soit que nous veillions, soit que nous dormions, nous vivions en même temps avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Aussi consolez-vous les uns les autres, et édifiez-vous mutuellement, comme vous le faites.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Nous vous prions, mes frères, d\'avoir de la considération pour ceux qui travaillent parmi vous, qui vous gouvernent dans le Seigneur, et qui vous avertissent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Ayez pour eux une affection extrême à cause de leur emploi. Vivez en paix entre vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Nous vous invitons, mes frères, à avertir ceux qui vivent dans le désordre, à relever les découragés, à soutenir les faibles, à être patients envers tous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Prenez garde que nul ne rende le mal pour le mal, mais recherchez toujours le bien entre vous et à l\'égard de tout le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Soyez toujours joyeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Priez sans cesse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'rendez grâces en toutes choses: c\'est là ce que Dieu demande de vous, en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'N\'éteignez pas l\'Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Ne méprisez pas les prophéties,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'mais examinez toutes choses, et retenez ce qui est bon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Abstenez-vous de toute espèce de mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Que le Dieu de paix, lui-même, vous sanctifie tout entiers, et que tout ce qui est en vous, l\'esprit, l\'âme et le corps, soit conservé irrépréhensible pour l\'avènement de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Celui qui vous a appelés est fidèle, et il le fera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Mes frères, priez pour nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Saluez tous les frères par un saint baiser.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Je vous en conjure au nom du Seigneur, que cette lettre soit lue à tous les frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paul, Silvain et Timothée à l\'Église des Thessaloniciens, qui est en Dieu, notre Père, et en Jésus-Christ, notre Seigneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'la grâce et la paix vous soient données par Dieu, le Père, et par le Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Nous devons rendre à Dieu de continuelles actions de grâces à votre sujet, mes frères, comme cela est juste; parce que votre foi s\'augmente singulièrement, et que votre charité les uns pour les autres s\'accroît de plus en plus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Nous-mêmes, nous nous glorifions de vous auprès des églises de Dieu, à cause de la constance et de la fidélité, que vous faites paraître au milieu de toutes les persécutions et de toutes les afflictions que vous endurez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'C\'est là une preuve du juste jugement de Dieu, qui vous reconnaîtra dignes de son royaume, pour lequel vous souffrez.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Il est de sa justice de rendre l\'affliction à ceux qui vous affligent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'et de vous donner, à vous qui êtes affligés, du repos avec nous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'lorsque le Seigneur Jésus, entouré d\'une flamme de feu, viendra du ciel avec les anges ministres de sa puissance, pour faire justice de ceux qui ne connaissent pas Dieu et de ceux qui n\'obéissent pas à l\'évangile de notre Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Ils seront punis de la perdition éternelle, privés de la présence du Seigneur et de la gloire dont sa force nous revêtira,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'le jour où il viendra, pour être glorifié dans ses saints et admiré dans tous ceux qui ont cru, — car il a été cru, le témoignage qui a été rendu devant vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Dans cette attente, nous prions constamment pour vous, afin que notre Dieu vous trouve dignes de la vocation qui vous a été adressée, et qu\'il rende parfaitement accomplies toutes vos bonnes dispositions, ainsi que l\'oeuvre de votre foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'de sorte que notre Seigneur Jésus soit glorifié en vous et vous en lui, par la grâce de notre Dieu et de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Quant à ce qui concerne l\'avènement de notre Seigneur Jésus-Christ et notre réunion à lui, nous vous prions, mes frères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'de ne pas vous laisser facilement troubler, et encore moins alarmer, par quelque esprit, par quelque parole ou quelque lettre à nous attribuées, comme si le jour du Seigneur était sur le point d\'arriver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Que personne ne vous égare d\'aucune manière, car ce jour ne viendra pas avant que l\'apostasie n\'ait eu lieu et qu\'on n\'ait vu paraître l\'homme de péché, le fils de la perdition,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'l\'adversaire qui s\'élève contre tout ce qui est appelé Dieu ou adoré, jusqu’à s\'installer dans le sanctuaire de Dieu en se proclamant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ne vous souvenez-vous pas que je vous disais ces choses, lorsque j\'étais encore avec vous?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Et maintenant vous savez ce qui empêche l\'adversaire de paraître avant son temps,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'car le mystère de l\'impiété déploie déjà son action; seulement, il faut attendre pour qu\'il relate, que celui qui lui fait obstacle à cette heure soit écarté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Alors paraîtra l\'impie, que le Seigneur Jésus détruira par le souffle de sa bouche et anéantira par l\'éclat de son avènement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Cet impie paraîtra avec une puissance satanique, faisant toutes sortes de miracles, de signes et de prodiges menteurs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'et déployant toute la séduction dont la méchanceté est capable, pour le malheur des hommes perdus, parce qu\'ils n\'ont pas ouvert leur coeur à l\'amour de la vérité qui les eût sauvés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'C\'est pour ce motif que Dieu leur envoie une puissance d\'égarement, qui les fera croire au mensonge,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'afin que tous ceux qui n\'auront pas cru à la vérité, mais qui auront pris plaisir à la méchanceté, tombent sous son jugement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Pour nous, nous devons rendre à Dieu de continuelles actions de grâces à votre sujet, frères bien-aimés du Seigneur, de ce que Dieu vous a choisis dès le commencement, pour vous sauver par la sanctification de l\'esprit et par la foi à la vérité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'en vous y appelant par notre évangile, afin que vous possédiez la gloire de notre Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Ainsi donc, mes frères, demeurez fermes, et retenez bien les instructions que nous vous avons données, soit de vive voix, soit dans notre précédente lettre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Que notre Seigneur Jésus-Christ lui-même, que Dieu, notre Père, qui nous a aimés et nous a donné par sa grâce une consolation éternelle et une bonne espérance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'console vos coeurs et vous affermisse en toute bonne oeuvre et en toute bonne parole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Au reste, mes frères, priez pour nous, afin que la parole du Seigneur ait un libre cours, qu\'elle soit partout glorifiée comme elle l\'est chez vous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'et que nous soyons délivrés des hommes absurdes et méchants, car il n\'est pas donné à tous d\'avoir la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Mais le Seigneur est fidèle; il vous affermira et vous gardera du mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Le Seigneur nous donne cette confiance en vous, que vous faites et que vous ferez toujours ce que nous prescrivons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Que le Seigneur forme vos coeurs à l\'amour pour Dieu et à la patience de Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Nous vous recommandons, mes frères, au nom de notre Seigneur Jésus-Christ, de vous éloigner de tout frère qui vit dans le désordre et ne se conforme pas aux instructions qu\'il a reçues de nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Vous savez vous-mêmes ce que vous devez faire pour nous imiter, car nous n\'avons pas vécu dans le désordre parmi vous:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'nous n\'avons mangé gratuitement le pain de personne, mais nous avons travaillé laborieusement et péniblement, jour et nuit, pour n\'être à charge à aucun de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Ce n\'est pas que nous n\'en eussions le droit, mais nous avons voulu vous servir d\'exemple, pour que vous nous imitiez,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'car lorsque nous étions avec vous, nous vous disions expressément: «Si quelqu\'un ne veut pas travailler, qu\'il ne mange pas non plus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Nous entendons dire qu\'il y en a quelques-uns parmi vous qui vivent dans le désordre, qui ne travaillent point, mais qui s\'occupent de choses tout à fait inutiles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'nous invitons ces sortes de personnes, et nous les engageons, en notre Seigneur Jésus-Christ, a manger un pain qui soit le leur, en travaillant paisiblement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Pour vous, mes frères, ne vous lassez pas de bien faire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'et si quelqu\'un ne se conforme pas à l\'invitation que nous lui adressons dans cette lettre, notez cet homme, ne le fréquentez pas, afin qu\'il ait honte de sa conduite;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'ne le regardez pourtant pas comme un ennemi, mais avertissez-le comme un frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Que le Seigneur de paix, lui-même, vous donne la paix, toujours, de toute manière! Que le Seigneur soit avec vous tous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Je vous salue de ma propre main, moi Paul. C\'est là ma signature dans toutes mes lettres; c\'est ainsi que j\'écris.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que la grâce de notre Seigneur Jésus-Christ soit avec vous tous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paul, Apôtre de Jésus-Christ par l\'ordre de Dieu, notre Sauveur, et de Jésus-Christ, notre espérance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'à Timothée mon véritable enfant en la foi: que la grâce, la miséricorde et la paix te soient données par Dieu, notre Père, et par Jésus-Christ, notre Seigneur!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Je te renouvelle l\'invitation que je te fis en partant pour la Macédoine, de rester à Éphèse, afin d\'enjoindre à certaines personnes de ne pas enseigner de fausses doctrines,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'et de ne pas s\'attacher à des fables et à des généalogies sans fin, qui sont une source de disputes, plutôt qu\'elles n\'avancent le règne de Dieu, qui repose sur la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Le but du Commandement, c\'est la charité qui vient d\'un coeur pur, d\'une bonne conscience et d\'une foi sincère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Quelques-uns, ayant perdu ces choses de vue, sont tombés dans le bavardage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'tout en ayant la prétention d\'être des docteurs de la loi, quoiqu\'ils ne comprennent ni ce qu\'ils disent, ni ce qu\'ils certifient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Nous savons que la loi est bonne, pourvu qu\'on en fasse un usage légitime,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'et qu\'on retienne bien qu\'elle n\'est pas faite pour le juste, mais pour les hommes sans frein ni règle, pour les impies et les pécheurs, pour les scélérats et les profanes, pour les parricides, pour les meurtriers,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'pour les libertins, pour les infâmes, pour les voleurs d\'hommes, pour les menteurs, pour les parjures et pour quiconque enfreint la discipline morale.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Ainsi l\'enseigne l\'évangile, où resplendit la gloire du Dieu souverainement heureux. Cet évangile m\'a été confié,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'et je rends grâce à Jésus-Christ, notre Seigneur, qui m\'a fortifié, de ce qu\'il m\'a jugé fidèle, en m\'appelant au ministère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'quoique je fusse auparavant un blasphémateur, un persécuteur, un homme violent. Mais j\'ai obtenu miséricorde, parce que j\'agissais par ignorance dans mon incrédulité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'et la grâce de notre Seigneur a surabondé avec la foi en Jésus-Christ et l\'amour pour lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'C\'est une vérité certaine et digne de toute créance, que Jésus-Christ est venu dans le monde pour sauver les pécheurs, dont je suis le premier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mais j\'ai obtenu miséricorde, précisément afin que Jésus-Christ fît voir en moi, le premier, sa longanimité tout entière, et que je servisse d\'exemple à ceux qui, à l\'avenir, mettront leur confiance en lui pour avoir la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Au Roi des siècles, immortel, invisible, seul Dieu, soient honneur et gloire aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ce que je te recommande, Timothée, mon enfant, c\'est que, suivant les prédictions qu\'on a faites autrefois à ton sujet, tu combattes le bon combat, et que tu les réalises');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'en gardant la foi et une bonne conscience. C\'est pour avoir renoncé à cette bonne conscience, que quelques-uns ont fait naufrage par rapport à la foi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'de ce nombre sont Hyménée et Alexandre, que j\'ai livrés à Satan, afin qu\'ils apprennent à ne point blasphémer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Je recommande donc, avant toutes choses, qu\'on fasse des requêtes, des prières, des supplications, des actions de grâces pour tous les hommes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'pour les rois et pour tous ceux qui sont élevés en dignité, afin que nous passions une vie paisible et tranquille en toute piété et en toute honnêteté:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'cela est bon et agréable à Dieu, notre Sauveur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'qui veut que tous les hommes soient sauvés, et parviennent à la connaissance de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Car il n\'y a qu\'un seul Dieu; il n\'y a aussi qu\'un seul médiateur entre Dieu et les hommes, savoir un homme, Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'qui s\'est donné lui-même en rançon pour tous, fait attesté en son temps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'C\'est afin d\'en témoigner que j\'ai été établi prédicateur, apôtre (je dis la vérité, je ne mens point) et docteur des Gentils pour ce qui a trait à la foi et à la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Je veux donc que les hommes prient en tout lieu, levant au ciel des mains pures, et n\'ayant ni colère, ni arrière-pensée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Je veux pareillement, que les femmes soient vêtues d\'une manière convenable, avec pudeur et modestie; qu\'elles se parent, non de tresses et de bijoux, de perles ou d\'habits somptueux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'mais de bonnes oeuvres, comme il sied à des femmes qui font profession de piété.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Que la femme écoute l\'instruction en silence, avec une parfaite soumission.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Je ne permets pas à la femme d\'enseigner, ni même de prendre aucune autorité sur l\'homme, mais je veux qu\'elle se tienne dans le silence;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'car Adam a été formé le premier, Eve ensuite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'et ce n\'est pas Adam qui a été séduit, mais la femme s\'étant laissé séduire, s\'est rendue coupable de transgression.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Néanmoins, la femme sera sauvée en devenant mère, pourvu qu\'elle demeure dans la foi, dans la charité et dans la sainteté unies à la modestie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'C\'est une vérité certaine, que si quelqu\'un aspire à la charge d\'évêque, il désire un emploi honorable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Il faut donc que l\'évêque soit irréprochable, mari d\'une seule femme, sobre, mesuré, convenable, hospitalier, capable d\'enseigner,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'point buveur, point emporté, mais doux, pacifique, désintéressé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Il faut qu\'il gouverne bien sa propre maison, qu\'il maintienne ses enfants dans l\'obéissance et dans un parfait respect:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'si l\'on ne sait pas gouverner sa propre maison, comment pourra-t-on prendre soin de l\'Église de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Qu\'il ne soit point nouvellement converti, de peur que venant à s\'enfler d\'orgueil, il n\'encoure le jugement du diable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Il faut aussi qu\'il jouisse de la considération de ceux du dehors, de peur qu\'il ne tombe dans l\'opprobre et dans les pièges du diable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'De même, que les diacres soient des hommes graves, point doubles, point adonnés au vin, point portés à un gain sordide;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'qu\'ils possèdent le mystère de la foi avec une conscience pure,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Qu\'on les éprouve d\'abord, puis, s\'il ne s\'élève aucune plainte, qu\'on les admette comme diacres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Leurs femmes, pareillement, doivent être des personnes graves, point médisantes, sobres, fidèles en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Que les diacres soient maris d\'une seule femme, qu\'ils gouvernent bien leurs enfants et leurs propres maisons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'car ceux qui s\'acquittent bien de l\'office de diacre, s\'acquièrent un rang honorable et une grande assurance dans la foi en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Je te donne ces instructions, quoique j\'espère te rejoindre assez promptement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'afin que, si je tarde, tu saches comment on doit se conduire dans la maison de Dieu, qui est l\'Église du Dieu vivant, la colonne et l\'appui de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Et, de l\'aveu de tous, il est grand le mystère de la piété: celui qui s\'est manifesté en chair a été justifié par l\'Esprit, vu des anges, prêché parmi les Gentils, cru dans le monde, reçu dans la gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Mais l\'Esprit dit expressément, que, dans les derniers temps, quelques-uns abandonneront la foi pour s\'attacher à des esprits séducteurs, et à des doctrines de démons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'y étant entraînés par l\'hypocrisie d\'imposteurs marqués de flétrissure dans leur propre conscience,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'qui proscrivent le mariage et l\'usage d\'aliments que Dieu a créés pour que les fidèles, qui, eux aussi, ont connu la vérité, en usent avec actions de grâces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Car tout ce que Dieu a créé est bon, et rien ne doit être rejeté, pourvu qu\'on le prenne avec actions de grâces:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'c\'est sanctifié par la parole de Dieu et par la prière.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Si tu représentes ces choses aux frères, tu seras un bon ministre de Jésus-Christ, nourri des leçons de la foi et de la bonne doctrine, que tu as fidèlement suivie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Repousse les fables profanes, ces contes de vieille femme. Exerce-toi à la piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'car l\'exercice corporel est utile à peu de choses, au lieu que la piété est utile à tout, puisqu\'elle a la promesse de la vie présente et de la vie à venir:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'c\'est là une parole certaine et digne de toute créance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'car nous ne nous donnons tant de peine, et nous ne sommes en butte aux outrages, que parce que nous avons mis notre espérance dans le Dieu vivant, qui est le Sauveur de tous les hommes, surtout des fidèles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Prescris ces choses et enseigne-les.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Que personne ne méprise ta jeunesse, mais sois le modèle des fidèles en parole, en conduite, en charité, en foi, en pureté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'En attendant que je vienne, attache-toi à lire les Écritures, à exhorter, à enseigner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne néglige pas le don qui est en toi, qui t\'a été conféré, et qui a été accompagné d\'une honorable prédiction, lorsque le collège des anciens t\'a imposé les mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Occupe-toi de ces choses; donne-t\'y tout entier, afin que tout le monde voie les progrès que tu fais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Veille sur toi-même et sur ton enseignement. Persévère dans ces occupations, car, en agissant de la sorte, tu te sauveras toi-même, et ceux qui t\'écoutent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Ne réprimande pas le vieillard, mais exhorte-le comme un père, les jeunes gens comme des frères,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'les femmes âgées comme des mères, les jeunes comme des soeurs, avec une pureté parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honore les veuves qui sont réellement veuves.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Si une veuve a des enfants ou des petits-enfants, qu\'ils apprennent d\'abord à montrer leur piété envers leur propre famille et à payer leurs parents de retour, car c\'est une chose agréable à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Pour la veuve qui est réellement veuve et seule dans le monde, elle a mis son espérance en Dieu, et elle persévère jour et nuit dans la prière et l\'oraison;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'mais pour celle qui vit dans les plaisirs, elle est morte, quoique vivante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Rappelle-le-leur, afin qu\'elles soient sans reproche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Si quelqu\'un n\'a pas soin des siens, et surtout des membres de sa famille, il a renié la foi, et il est pire qu\'un infidèle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Que celle qui sera mise sur le rôle des veuves n\'ait pas moins de soixante ans; qu\'elle n\'ait eu qu\'un mari;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'qu\'elle soit connue pour ses bonnes oeuvres: pour avoir élevé des enfants, exercé l\'hospitalité, lavé les pieds des saints, secouru les malheureux, prêté son concours à toute bonne oeuvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Quant aux jeunes veuves, refuse-les; car, lorsque leurs désirs les détachent de Christ, elles veulent se remarier,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'sans se laisser arrêter par le reproche de manquer à leur premier engagement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'En même temps, étant inoccupées, elles vont s\'instruire en courant les maisons, et elles sont non seulement inoccupées, mais encore causeuses et curieuses, parlant de choses dont on ne doit point parler.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Je veux donc que les jeunes veuves se marient, qu\'elles aient des enfants, gouvernent leur ménage, et ne donnent pas prise à l\'adversaire pour gloser,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'car il y en a déjà quelques-unes qui se sont détournées pour suivre Satan.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Si quelque fidèle, homme ou femme, a des veuves dans sa famille, qu\'il les assiste, et que l\'Église n\'en soit point chargée, afin qu\'elle puisse secourir celles qui sont réellement veuves.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Que les anciens qui gouvernent bien, reçoivent un double honneur, surtout ceux qui s\'occupent de la prédication et de l\'enseignement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'car l\'Écriture dit: «Tu n’emmuselleras pas le boeuf qui foule le grain,» et l\'ouvrier mérite son salaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Ne reçois point d\'accusation contre un ancien, si ce n\'est sur la déposition de deux ou trois témoins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Reprends devant tout le monde ceux qui manquent à leurs devoirs, afin que les autres aussi aient de la crainte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Je te conjure devant Dieu, devant Jésus-Christ et les anges élus, d\'observer ces directions sans rien faire par prévention ni par faveur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'N\'impose les mains à personne avec précipitation, et ne te rends point complice des péchés d\'autrui; conserve-toi pur, toi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne continue pas à ne boire que de l\'eau, mais prends un peu de vin, à cause de ton estomac et de tes fréquentes indispositions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Les péchés de certains hommes sont manifestes, et les font juger tout de suite; mais chez d\'autres, ils ne se voient que plus tard.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'De même, les bonnes actions sont manifestes, et celles qui ne le sont pas d\'abord, ne peuvent demeurer cachées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Que tous ceux qui sont sous le joug de l\'esclavage, tiennent leur maîtres pour dignes de tout respect, de peur qu\'on ne blasphème le nom de Dieu et la doctrine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Que ceux qui ont des fidèles pour maîtres, ne les méprisent point sous prétexte que ce sont des frères; au contraire, qu\'ils les servent d\'autant mieux que ceux qui reçoivent leurs services sont des fidèles et des bien-aimés. Enseigne, ces choses et exhorte à les pratiquer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Si quelqu\'un enseigne de fausses doctrines, et n\'adhère pas aux leçons morales de notre Seigneur Jésus-Christ, ni à la doctrine qui a pour objet la piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'c\'est un orgueilleux qui ne sait rien: il a la maladie des discussions et des disputes, lesquelles n\'engendrent qu\'envie, querelles, propos injurieux, soupçons injustes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'et des animosités sans fin avec des hommes viciés d\'esprit et dévoyés, qui croient que la piété est un moyen de lucre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Pourtant, c\'est un grand gain que la piété jointe au contentement d\'esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'car nous n\'avons rien apporté dans ce monde, et il est clair que nous n\'en pourrons rien emporter;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'si nous avons de quoi nous nourrir et nous couvrir, nous devons être contents.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Ceux qui veulent être riches, tombent dans la tentation, dans le piège et dans une foule de désirs insensés et pernicieux, qui plongent les hommes dans la ruine et la perdition,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'car l\'amour de l\'argent est la racine de tous les maux. Quelques-uns en étant possédés, se sont détournés de la foi, et se sont créés bien des tourments.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Pour toi, homme de Dieu, fuis ces désirs; recherche la justice, la piété, la foi, la charité, la patience, la douceur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Combats le bon combat de la foi; saisis la vie éternelle à laquelle tu as été appelé, et pour laquelle tu as fait ta belle profession en présence d\'un grand nombre de témoins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Je t\'adjure devant Dieu qui donne à tout la vie, et devant Jésus-Christ, qui fit sa belle déclaration devant Ponce-Pilate,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'de garder le Commandement, en demeurant sans tache et sans reproche jusqu’à l\'avènement de notre Seigneur Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'qui paraîtra au temps voulu par le Bienheureux et seul Puissant, par le Roi des rois et le Seigneur des seigneurs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'qui seul possède l\'immortalité, qui habite une lumière inaccessible, que nul homme n\'a vu ni ne peut voir, à qui appartiennent l\'honneur et la puissance éternelle. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Recommande aux riches de ce monde de ne se point enorgueillir et de ne point mettre leur espérance dans les richesses incertaines, mais de la placer en Dieu, qui nous fournit toutes choses en abondance, pour que nous sachions en jouir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Recommande-leur de faire du bien, d\'être riches en bonnes oeuvres, donnants, généreux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'de sorte qu\'ils s\'amassent pour l\'avenir un trésor placé sur un fondement solide, afin de saisir la vie véritable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timothée, conserve le dépôt qui t\'a été confié, évitant les bavardages profanes et les controverses d\'une science faussement ainsi nommée:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'c\'est pour en avoir fait profession que quelques-uns se sont éloignés de la foi. Que la grâce soit avec toi!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paul Apôtre de Jésus-Christ par la volonté de Dieu, pour annoncer la promesse de la vie qui est en Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'à Timothée mon enfant bien-aimé: que la grâce, la miséricorde et la paix te soient données par Dieu, notre Père, et par Jésus-Christ, notre Seigneur!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Je rends grâces à Dieu, qu\'ont servi mes ancêtres, et que je sers avec une conscience pure, de la manière dont tu es toujours présent à ma pensée dans mes prières, le jour et la nuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Je me rappelle les larmes que tu as versées à ton départ, et j\'ai besoin de te voir, afin d\'être rempli de joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Je me souviens aussi de la foi sincère qui t\'animait: elle habita d\'abord dans Loïs, ton aïeule, et dans Eunice. ta mère, et j\'ai la conviction qu\'elle habite aussi en toi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'C\'est une raison pour moi de te rappeler d\'attiser le feu de la grâce que tu as reçue de Dieu, lorsque je t\'imposai les mains,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'car Dieu ne nous a pas donné un esprit de timidité, mais un esprit de force, d\'amour et de sagesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'N\'aie donc point honte du témoignage que tu dois rendre de notre Seigneur, ni de moi qui suis son prisonnier; mais sache souffrir avec moi pour l’Evangile par la puissance que Dieu donne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'C\'est lui qui nous a sauvés, et nous a adressé un saint appel, non en vertu de nos oeuvres, mais ensuite d\'un dessein qui lui est propre, et d\'une grâce qui nous a été faite de toute éternité en Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'quoiqu\'elle n\'ait été manifestée que maintenant, par la venue de notre Sauveur Jésus-Christ, qui a aboli la mort, et a mis en lumière la vie et l\'immortalité par l\'évangile.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'C\'est pour cet évangile que j\'ai été établi prédicateur, apôtre et docteur des Gentils,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'et c\'est ce qui m\'a attiré tous les maux que j\'endure. Mais je n\'en ai point honte, car je sais en qui j\'ai cru, et j\'ai la conviction qu\'il a la puissance de garder mon dépôt pour le grand jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Conserve, dans la foi et dans la charité qui est en Jésus-Christ, le modèle des leçons morales que tu tiens de moi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'garde ce précieux dépôt par l\'Esprit-Saint qui habite en nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sais que tous ceux qui sont en Asie m\'ont abandonné, entre autres Phygelles et Hermogènes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Que le Seigneur étende sa miséricorde sur la famille d\'Onésiphore, car il m\'a souvent réconforté, et il n\'a point eu honte de la chaîne que je porte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'au contraire, dès son arrivée à Rome, il m\'a cherché soigneusement, et il m\'a trouvé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Que le Seigneur lui donne de trouver miséricorde auprès du Seigneur dans le grand jour. D\'ailleurs tu sais mieux que personne tous les services qu\'il m\'a rendus à Éphèse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Toi donc, mon enfant, fortifie-toi dans la grâce qui est en Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'et quant aux enseignements que tu as reçus de moi en présence d\'un grand nombre de témoins, confie-les à des hommes sûrs, qui soient capables à leur tour d\'en instruire d’autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Sache aussi souffrir, comme un bon soldat de Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Celui qui s\'en va en guerre ne s\'embarrasse pas dans les affaires de la vie, s\'il veut plaire à celui qui l\'a enrôlé,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'et quand on combat dans les jeux, l\'on n\'est point couronné si l\'on n\'a pas combattu selon les lois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'C\'est le laboureur qui prend de la peine, qui doit le premier avoir sa part des fruits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Fais attention à ce que je te dis, car le Seigneur te donnera l\'intelligence en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Souviens-toi que Jésus-Christ, issu de la famille de David, est ressuscité d\'entre les morts, selon mon évangile,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'pour lequel je souffre jusqu’à être enchaîné comme un malfaiteur. Mais la parole de Dieu n\'est point enchaînée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'c\'est pourquoi j\'endure tout à cause des élus, afin qu\'ils obtiennent, eux aussi, le salut qui est en Jésus-Christ, avec la gloire éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'C\'est une chose certaine, que si nous mourons avec lui, nous vivrons aussi avec lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'si nous endurons, nous régnerons aussi avec lui; si nous le renions, lui aussi, nous reniera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Si nous manquons à notre parole, il demeure fidèle à la sienne, car il ne peut, se renier lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Voilà ce que tu dois rappeler, en conjurant devant Dieu qu\'on bannisse les disputes: elles ne servent à rien et sont la ruine de ceux qui les entendent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Efforce-toi de te montrer dans le service de Dieu, un homme éprouvé, un ouvrier consciencieux, qui enseigne purement la parole de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Évite les bavardages profanes, car ceux qui s’y livreront feront des progrès toujours plus grands dans l\'impiété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'et leur parole rongera comme la gangrène. Tels sont, entre autres, Hyménée et Philète,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'qui se sont éloignés de la vérité en soutenant que la résurrection a déjà eu lieu, et qui détruisent la foi de quelques personnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Néanmoins, le solide fondement que Dieu a posé demeure ferme, marqué de ce sceau: «Le Seigneur connaît ceux qui lui appartiennent,» et: «Qu\'il se détourne du mal, quiconque a le nom du Seigneur à la bouche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Dans une grande maison, il n\'y a pas seulement des vases d\'or et d\'argent, il y en a aussi de bois et de terre: les uns servent à un usage noble, les autres à un usage vil.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Si donc l\'on se conserve pur de ces bavardages, on sera un vase servant à un usage noble, sanctifié, fort utile au maître de la maison, propre à toute bonne oeuvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fuis les passions de la jeunesse, et recherche la justice, la foi, la charité et la paix avec ceux qui invoquent le Seigneur d\'un coeur pur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Repousse les questions folles et sottes: tu sais qu\'elles engendrent des disputes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Il ne faut pas que le serviteur du Seigneur se dispute; il doit être, au contraire, affable à tout le monde, capable d\'enseigner, endurant;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'il doit instruire avec douceur ceux qui sont d\'un avis opposé, dans l\'espérance que Dieu leur donnera peut-être de changer de sentiments pour arriver à la connaissance de la vérité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'et qu\'en revenant à la raison, ils se dégageront des lacs du diable, qui les tient captifs pour qu\'ils fassent sa volonté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Sache que dans les derniers temps, il y aura des circonstances difficiles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'car les hommes seront égoïstes, intéressés, vantards, arrogants, diffamateurs, rebelles à leurs parents, ingrats, impies,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'durs, implacables, calomniateurs, intempérants, cruels, ennemis des gens de bien,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traîtres, emportés, enflés d\'orgueil, amis des plaisirs plutôt que de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'ayant les dehors de la piété, mais ayant renié ce qui en fait le nerf. Eloigne-toi aussi de ces hommes-là;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'car c\'est parmi eux que se rencontrent ces gens qui s\'insinuent dans les maisons et s\'emparent de l\'esprit de femmelettes chargées de péchés, travaillées de passions de plus d\'un genre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'apprenant toujours sans pouvoir jamais parvenir à la connaissance de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Et comme Jannès et Jambrès s\'opposèrent à Moïse, eux aussi, gens viciés d\'esprit et sans valeur au point de vue de la foi, ils s\'opposent à la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Mais ils ne feront pas de plus grands progrès, car leur folie frappera les yeux de tout le monde, comme il est arrivé de la folie de ces imposteurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Pour toi, tu m\'as suivi dans mon enseignement, dans ma conduite, dans mes projets, dans ma foi, dans ma patience, dans ma charité, dans ma constance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'dans mes persécutions et dans mes souffrances. A quelles souffrances n\'ai-je pas été exposé à Antioche, à Icône, à Lystres? Quelles persécutions n\'ai-je pas supportées? Et le Seigneur m\'a constamment délivré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Tous ceux qui veulent vivre pieusement en Jésus-Christ, seront aussi persécutés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Quant aux méchants et aux imposteurs, ils tomberont toujours plus bas, égarant et égarés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Pour toi, persévère dans les choses que tu as apprises, et dont tu as été convaincu, sachant de qui tu les tiens,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'et considérant que dès ton enfance, tu as eu la connaissance des saintes lettres, qui peuvent te rendre sage à salut par la foi en Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toute Écriture inspirée de Dieu, est utile aussi pour instruire, pour reprendre, pour corriger, pour former à la justice,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'afin que l\'homme de Dieu soit accompli et propre à toute bonne oeuvre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Je t\'en conjure devant Dieu et devant Jésus-Christ, qui doit juger les vivants et les morts, et au nom de son avènement et de son règne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'prêche la Parole, insiste en temps et hors de temps, reprends, censure, exhorte, en instruisant avec une patience parfaite;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'car il viendra un temps où les hommes ne souffriront pas l\'instruction morale, mais cédant à leurs passions, ils s\'entoureront de docteurs qui chatouillent agréablement leurs oreilles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'et ils se détourneront de la vérité pour se tourner du côté des fables.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Mais toi, conserve ton bon sens en toutes choses, sache souffrir, fais l\'oeuvre d\'un évangéliste. remplis tous les devoirs de ton ministère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Pour moi, je vais être immolé et le moment de mon départ est imminent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'J\'ai combattu le bon combat, j\'ai achevé la course, j\'ai gardé la foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'il ne me reste plus qu\'à recevoir la couronne de justice qui m\'est réservée: le Seigneur me la donnera en ce jour-là, lui, le juste juge, et non seulement à moi, mais aussi à tous ceux qui auront aimé son avènement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Tâche de venir promptement vers moi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'car Démas m\'a abandonné par amour pour le siècle présent, il est parti pour Thessalonique; Crescens est allé en Galatie, Tite en Dalmatie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Luc est seul avec moi. Prends Marc, et l\'amène avec toi, car il m\'est d\'un grand secours pour le ministère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Pour Tychique, je l\'ai envoyé à Éphèse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Apporte, en venant, le sac de voyage que j\'ai laissé chez Carpus à Troas, ainsi que les livres, surtout les parchemins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre, le chaudronnier, m\'a fait bien du mal: le Seigneur lui rendra selon ses oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Toi aussi, tiens-toi en garde contre lui, car il a fait une vive opposition à ce que nous lui avons dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Personne ne m\'a soutenu de sa présence dans ma première plaidoirie; tous m\'ont abandonné. Que cela ne leur soit point imputé!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mais le Seigneur m\'a assisté et m\'a fortifié, afin que j\'annonçasse complètement l\'Évangile et que tous les Gentils l\'entendissent; et j\'ai été délivré de la gueule du lion.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Le Seigneur me délivrera de toute méchante action, et me sauvera en m\'appelant dans son royaume céleste. A lui soit la gloire aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Salue Prisca et Aquilas, et la famille d\'Onésiphore.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Éraste est resté à Corinthe; quant à Trophime, je l\'ai laissé malade à Milet.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Tâche de venir avant l\'hiver. Eubule te salue, ainsi que Prudens, Linus, Claudia et tous les frères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Que le Seigneur Jésus-Christ soit avec ton esprit! Que la grâce soit avec vous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paul, serviteur de Dieu et Apôtre de Jésus-Christ — pour annoncer la foi des élus de Dieu et faire connaître la vérité qui a pour objet la piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'afin d’amener à l\'espérance de la vie éternelle promise de tout temps par le Dieu qui ne trompe point,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'et qui, au moment convenable, a révélé sa parole par la prédication qui m\'a été confiée par l\'ordre de Dieu, notre Sauveur —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'à Tite, mon véritable enfant en la foi qui nous est commune: que la grâce et la paix te soient données par Dieu, notre Père, et par Jésus-Christ, notre Sauveur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Je t\'ai laissé en Crète précisément afin que tu achèves de tout organiser, et que tu établisses des anciens dans chaque ville, comme je te l\'ai prescrit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'S\'il y a quelque homme d\'une réputation intacte, mari d\'une seule femme, ayant des enfants qui aient la foi et qui ne soient accusés ni de dissolution ni d\'insubordination, choisis-le pour ancien:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'car il faut que l\'évêque soit irréprochable comme étant un économe de Dieu. Il ne doit être ni arrogant, ni colère, ni buveur, ni violent, ni porté à un gain sordide,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'mais il doit être hospitalier, ami des gens de bien, mesuré, juste, pieux, tempérant,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'attaché à la vraie Parole, telle qu\'on la lui a enseignée, afin qu\'il soit en état, et d\'exhorter par l\'instruction morale, et de confondre les contradicteurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Il y a, en effet, surtout parmi les circoncis, bien des gens insubordonnés, bavards et séducteurs, à qui il faut fermer la bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Ils bouleversent des familles entières, en enseignant pour un vil intérêt des choses inconvenantes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Un de leurs compatriotes, leur propre prophète, a dit: «Les Crétois sont toujours menteurs; ce sont de méchantes bêtes, des ventres paresseux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Ce jugement est vrai: aussi reprends-les vertement, afin qu\'ils aient une foi morale,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'et qu\'ils ne s\'attachent pas à des fables judaïques, ni à des commandements d\'hommes dévoyés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Tout est pur pour ceux qui sont purs; mais pour ceux qui sont souillés et infidèles, rien n\'est pur: leur esprit est souillé ainsi que leur conscience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Ils font profession de connaître Dieu, mais ils le renient par leurs oeuvres: ils sont abominables, rebelles et incapables de rien de bon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Pour toi, parle comme le demande l\'instruction morale.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Dis aux vieillards d\'être sobres, graves, mesurés, moraux dans la foi, dans la charité, dans la patience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Dis pareillement aux femmes âgées d\'avoir un extérieur vénérable, de n\'être ni médisantes ni adonnées à la boisson,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'd\'être de sages conseillères, afin d\'apprendre aux jeunes femmes à aimer leurs maris et leurs enfants,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'à être sages, chastes, occupées à leur ménage, bonnes, soumises à leurs maris, pour qu\'on ne parle point mal de la parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Exhorte de même les jeunes hommes à être sages,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'te montrant toi-même, à tous égards, un modèle de vertus. Apporte dans ton enseignement de la pureté, de la dignité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'une parole morale, irréprochable, afin que l\'adversaire soit dans la confusion, en n\'ayant rien de mauvais à dire sur notre compte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Exhorte les serviteurs à être soumis à leurs maîtres, à leur complaire en toutes choses, en ne les contredisant point,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'en ne détournant rien, mais en faisant preuve d\'une fidélité parfaite, afin de faire honneur en toutes choses à la doctrine de Dieu, notre Sauveur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Car elle a paru, la grâce de Dieu, source de salut pour tous les hommes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'elle fait notre éducation, pour que, renonçant à l\'impiété et aux passions mondaines, nous vivions dans le siècle présent avec sagesse, avec justice et avec piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'en attendant la réalisation de notre bienheureuse espérance, et l\'apparition de la gloire du grand Dieu et de notre Sauveur Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'il s\'est, en effet, donné lui-même pour nous, afin de nous délivrer de toute iniquité, et de se faire, en nous purifiant, un peuple qui lui appartienne, et qui soit zélé pour les bonnes oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Dis ces choses, exhorte et reprends avec une pleine autorité. Que personne ne te méprise.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Rappelle aux fidèles d\'être soumis aux magistrats, aux autorités, de leur obéir, d\'être toujours prêts à faire le bien,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'de ne dire du mal de personne, d\'être pacifiques, indulgents, en un mot, de se montrer d\'une douceur parfaite envers tous les hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Nous aussi, nous étions autrefois insensés, rebelles, égarés, asservis à des passions et à des voluptés de tout genre, passant notre vie dans la méchanceté et dans l\'envie, des gens détestables, nous haïssant les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mais, lorsque la bonté de Dieu, notre Sauveur, et son amour envers les hommes ont paru,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'il nous a sauvés, non en vertu des oeuvres de justice que nous aurions faites nous-mêmes, mais par sa propre miséricorde, par une ablution de nouvelle naissance et de renouvellement opéré par l’Esprit-Saint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'qu\'il a richement répandu sur nous par Jésus-Christ notre Sauveur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'il a voulu qu\'étant justifiés par sa grâce, nous soyons héritiers, en espérance, de la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Cette parole est certaine et je veux que tu la certifies, afin que ceux qui ont cru en Dieu s\'appliquent à pratiquer les bonnes oeuvres: voilà ce qui est bon et utile aux hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Quant aux questions folles, aux généalogies, aux querelles et aux disputes sur la Loi, évite-les; elles sont inutiles et vaines.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Repousse l\'hérétique, après lui avoir adressé un premier et un second avertissement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'sachant qu\'un tel homme est perverti, et qu\'il pèche en ayant lui-même le sentiment de sa condamnation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Lorsque je t\'aurai envoyé Artémas ou Tychique, hâte-toi de venir me rejoindre à Nicopolis, car j\'ai résolu d\'y passer l\'hiver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Aie soin de pourvoir au voyage de Zénas le jurisconsulte et d\'Apollos, afin que rien ne leur manque;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'il faut que les nôtres aussi apprennent à pratiquer les bonnes oeuvres, de manière à subvenir aux besoins urgents, sous peine d\'être des gens stériles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Tous ceux qui sont avec moi te saluent. Salue ceux qui nous aiment en la foi. Que la grâce soit avec vous tous!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paul, prisonnier de Jésus-Christ, et son frère Timothée, — à notre cher Philémon, le compagnon de nos travaux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'à notre soeur Apphia; à Archippe notre compagnon d\'armes, ainsi qu\'à l\'Église qui se réunit dans ta maison:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'que la grâce et la paix vous soient données par Dieu, notre Père, et par notre Seigneur Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Je ne cesse de rendre grâces à mon Dieu, en faisant mention de toi dans mes prières,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'depuis que j\'entends parler de ta charité pour tous les saints et de ta foi au Seigneur Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Je lui demande, que l\'union que la foi établit entre nous, soit efficace pour te faire reconnaître tout bien qui est en nous en vue de Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Nous avons, en effet, ressenti bien de la joie et bien de la consolation à la pensée de ta charité, car, frère, elle a tranquillisé le coeur des saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'C\'est pourquoi, bien que j\'aie en Christ toute liberté pour te rappeler ton devoir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'je préfère, par amour, t\'adresser une prière. Tel que je suis, moi, Paul, vieillard, et, qui plus est, actuellement prisonnier de Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'je t\'adresse une prière pour l\'enfant que j\'ai engendré dans ma captivité, pour Onésime (Utile),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'qui autrefois t\'était inutile, mais qui maintenant t\'est fort utile, ainsi qu\'à moi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Je te le renvoie, et toi, accueille-le, cet objet de ma tendresse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'J\'aurais voulu le retenir auprès de moi, afin qu\'à ta considération il me servît dans la captivité que je souffre pour l’évangile;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'toutefois, je n\'ai rien voulu faire sans ton avis, afin que ce bienfait de ta part ne paraisse pas forcé, mais qu\'il soit volontaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Peut-être aussi Onésime n\'a-t-il été séparé de toi momentanément, qu\'afin que tu le recouvres pour l\'éternité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'non plus comme un esclave, mais comme étant fort au-dessus d\'un esclave, comme un frère bien-aimé, tout particulièrement aimé de moi, et combien plus de toi, à qui il doit être cher, et en lui-même, et dans le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'S\'il est donc vrai que tu me tiennes pour un ami, accueille-le comme tu m\'accueillerais moi-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'S\'il t\'a fait quelque tort ou s\'il te doit quelque chose, passe-le-moi en compte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Moi, Paul, je te l\'écris de ma main, je te rembourserai... pour ne pas dire que tu es mon débiteur, et même de ta propre personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Oui, frère, fais-moi ce plaisir, dans le Seigneur; tranquillise mon coeur en Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Je t\'écris, en comptant sur ton obéissance, sûr même que tu feras au delà de ce que je demande.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Prépare-moi en même temps un logement, car j\'espère que, grâce à vos prières, je vous serai rendu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Épaphras, mon compagnon de captivité, te salue en Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'ainsi que Marc, Aristarque, Démas et Luc, les compagnons de mes travaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Que la grâce de notre Seigneur Jésus-Christ soit avec votre esprit!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Après avoir parlé autrefois à nos pères en divers temps et en diverses manières par les prophètes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Dieu nous a parlé dans ces derniers temps par son Fils, qu\'il a établi héritier de toutes choses, et par lequel aussi il a fait le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Ce Fils, qui est le reflet de sa gloire, l\'image empreinte de sa personne, et qui soutient toutes choses par sa parole puissante, après avoir fait la purification des péchés, s\'est assis à la droite de la majesté divine, dans les cieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Il est d\'autant supérieur aux anges, que le nom dont il a hérité est plus éminent que le leur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Auquel des anges, en effet, Dieu a-t-il jamais dit: «Tu es mon Fils, je t’ai engendré aujourd\'hui?» et encore: «Je serai son Père, et il sera mon Fils?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Et, quand il introduira de nouveau le Premier-né dans le monde, il doit dire: «Que tous les anges de Dieu l’adorent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'De plus, tandis qu\'il dit des anges: «Celui qui a fait de ses anges des vents, et de ses serviteurs une flamme de feu;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'il dit du Fils: «Ton trône, ô Dieu, subsiste d\'éternité en éternité,» et: «Le sceptre de ta royauté est un sceptre de droiture;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'tu as aimé la justice et haï l’iniquité. C\'est pourquoi, ô dieu, ton Dieu t’a oint, plus que tes pairs, d\'une huile d\'allégresse;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'et: «C\'est toi, Seigneur, qui, au commencement, as fondé la terre, et les cieux sont l’ouvrage de tes mains.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ils périront, mais tu demeures; ils vieilliront tous comme un vêtement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'tu les enrouleras comme un manteau, et ils seront changés; mais toi, tu es toujours le même, et tes années ne finiront point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Auquel des anges a-t-il jamais dit: «Assieds-toi à ma droite, jusqu’à ce que j\'aie fait de tes ennemis ton marchepied?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Ne sont-ils pas tous des esprits servants employés au service de Dieu, et envoyés pour ceux qui doivent hériter du salut?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'C\'est une raison pour nous de faire d\'autant plus attention aux choses que nous avons entendues, de peur que nous ne venions à les perdre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Si la parole annoncée par les anges a été si sûre et si certaine, que toute transgression et toute désobéissance a reçu sa juste rémunération,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'comment échapperons-nous, si nous négligeons un si grand salut, qui, après avoir été annoncé d\'abord par le Seigneur, nous est parvenu d\'une manière sûre et certaine par ceux qui ont entendu sa voix,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Dieu appuyant leur témoignage par des signes, des prodiges, des miracles divers, et par l\'Esprit-Saint qu\'il dispense à son gré?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'En effet, ce n\'est pas aux anges que Dieu a soumis le monde à venir dont nous parlons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Or l\'on a fait quelque part cette déclaration: «Qu\'est-ce que l\'homme, que tu te souviennes de lui, ou le Fils de l\'homme, que tu en prennes soin?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu l\'as abaissé pour un peu de temps au-dessous des anges, tu l\'as couronné de gloire et d\'honneur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'tu as mis toutes choses sous ses pieds.» En effet, en lui soumettant «toutes choses, Dieu n\'a rien laissé qui ne lui soit soumis; mais, nous ne voyons pas encore maintenant que toutes choses lui soient soumises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Toutefois «celui qui a été abaissé pour un peu de temps au-dessous des anges,» Jésus, nous le voyons «couronné de gloire et d\'honneur,» à cause de la mort qu\'il a soufferte afin que, par la grâce de Dieu, il goûtât la mort pour tout homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Puisque Celui pour qui et par qui sont toutes choses, voulait conduire un grand nombre de fils à la gloire, il était convenable qu\'il élevât par des souffrances au plus haut degré de perfection et de gloire l’auteur de leur salut;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'car celui qui sanctifie, aussi bien que ceux qui sont sanctifiés, sont tous issus d\'un même Père. C\'est pour ce motif que Jésus n\'a point honte de les appeler «frères,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'quand il dit: «J\'annoncerai ton nom à mes frères, je te célébrerai en pleine assemblée;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'et encore: «Pour moi, je mettrai ma confiance en Lui;» et encore: «Me voici, moi et les enfants que tu m\'as donnés.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Puis donc que ces «enfants» ont tous en partage le sang et la chair, lui aussi y a participé également, afin d\'anéantir par la mort même, la puissance de celui qui a l\'empire de la mort, c’est-à-dire, du diable,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'et de délivrer ainsi tous ceux que la crainte de la mort tenait dans la servitude pendant toute leur vie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'car ce n\'est point aux anges assurément qu\'il vient en aide, mais à la postérité d\'Abraham.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Voilà pourquoi il devait être rendu semblable à tous égards à ses frères, pour qu\'il pût être compatissant, et, dans leurs rapports avec Dieu, un souverain sacrificateur digne de confiance, pour faire l\'expiation pour les péchés du peuple:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'c\'est parce qu\'il a souffert en ayant été lui-même tenté, qu\'il peut secourir ceux qui sont tentés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'En conséquence, frères saints, vous qui avez répondu à l\'appel céleste, considérez bien celui qui est apôtre et souverain sacrificateur de la foi que nous professons,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Jésus, qui est fidèle à Celui qui l\'a fait, comme Moïse lui a été «fidèle dans toute Sa maison.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Il a été jugé digne d\'une gloire d\'autant supérieure à celle de Moïse, que celui qui construit une maison est plus honorable que la maison même');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, '(car toute maison est construite par quelqu\'un; quand bien même c\'est Dieu qui a tout construit).');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Et tandis que Moïse «a été fidèle dans toute la maison de Dieu» en qualité de serviteur chargé de communiquer ce qui devait être dit à cette maison,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Christ est fidèle comme Fils, à la tête de sa propre maison: et sa maison, c\'est nous, pourvu que nous retenions jusqu’à la fin la ferme confiance et l\'espérance, qui font notre gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'C\'est pourquoi — selon ce que dit le Saint-Esprit: «Aujourd’hui, si vous entendez Ma voix,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'n\'endurcissez point vos coeurs, comme il arriva au jour de la révolte et de la tentation au désert,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'où vos pères me tentèrent par manière d’épreuve; et ils virent de mes oeuvres pendant quarante ans!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Aussi mon courroux s’alluma-t-il contre cette génération, et je dis: «Leur coeur s\'égare toujours; ils n\'ont point connu mes voies,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'de sorte que je fis serment, dans ma colère, qu\'ils n\'entreraient pas dans mon repos;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, '— c\'est pourquoi prenez garde, mes frères, qu\'il n\'y ait peut-être chez quelqu\'un de vous un mauvais coeur incrédule, qui lui fasse abandonner le Dieu vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Exhortez-vous chaque jour les uns les autres, aussi longtemps que l\'on peut dire «aujourd\'hui,» afin qu\'aucun de vous «ne s\'endurcisse,» séduit par le péché;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'car nous avons part aux bienfaits de Christ, pourvu que nous retenions fermement jusqu’à la fin notre conviction première,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'pendant qu\'on peut dire encore: «Aujourd\'hui, si vous entendez la voix de Dieu, n\'endurcissez point vos coeurs, comme il arriva au jour de la révolte.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Qui sont, en effet, ceux qui, après «avoir entendu la voix de Dieu,» se sont révoltés? Mais, ne sont-ce pas tous ceux qui sont sortis d\'Egypte sous la conduite de Moïse?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, '— Et contre qui fut-il courroucé pendant quarante ans? N\'est-ce pas contre ceux qui avaient péché, et dont les membres jonchèrent le désert?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, '— Et à qui «fit-il serment qu\'ils n\'entreraient pas dans son repos,» sinon à ceux qui avaient été incrédules?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Nous voyons, en effet, qu\'ils ne purent y rester à cause de leur incrédulité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Craignons donc, puisque la promesse «d\'entrer dans son repos,» n\'est pas retirée, que quelqu\'un de vous ne paraisse l\'avoir négligée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Car cette bonne nouvelle nous a été annoncée aussi bien qu\'à eux; mais la parole qu\'ils entendirent ne leur servit de rien, parce qu\'ils ne se l\'approprièrent pas par la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Pour nous qui avons cru, nous entrons dans «le repos» dont il a parlé, quand il a dit: «De sorte que je fis serment dans ma colère, qu\'ils n\'entreraient pas dans mon repos;» parole qu\'il a prononcée bien que ses oeuvres eussent été achevées dès la création du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'En effet, au sujet du septième jour, il s\'exprime ainsi quelque part: «Dieu se reposa le septième jour de toutes ses oeuvres,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'et dans le passage ci-dessus, il dit de nouveau: «Je fais serment qu\'ils n\'entreront pas dans mon repos.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Puis donc qu\'il est encore donné à quelques-uns d\'y entrer, et que les premiers, à qui cette nouvelle a été annoncée, n\'y sont pas entrés à cause de leur incrédulité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Dieu détermine de nouveau dans David un jour qu\'il appelle «aujourd\'hui,» en disant si longtemps après, comme on l\'a vu plus haut: «Aujourd\'hui si vous entendez ma voix, n’endurcissez pas vos coeurs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Si Josué leur eût donné «le repos,» Dieu ne parlerait pas après cela d\'un autre jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Il reste donc un jour de repos pour le peuple de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'car celui qui entre dans «le repos de Dieu,» se repose de ses oeuvres, comme Dieu s\'est reposé des siennes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Empressons-nous donc d\'entrer dans ce repos-là, afin qu\'aucun ne tombe en donnant le même exemple d\'incrédulité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Car la parole de Dieu est vivante, puissante, plus acérée qu\'aucune épée à deux tranchants; elle pénètre jusqu’à la suture de l\'âme et de l\'esprit, jusque dans les jointures et dans les moelles; elle juge les sentiments et les pensées du coeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Nulle créature n\'est cachée à Dieu, tout est à nu et à découvert aux yeux de celui à qui nous avons affaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Puis donc que nous avons en Jésus, le Fils de Dieu, un grand souverain sacrificateur qui a pénétré au haut des cieux, demeurons fermes dans la profession de notre foi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'car nous n\'avons pas un souverain sacrificateur qui ne puisse pas compatir à nos faiblesses; au contraire, puisqu\'il a été tenté comme nous en toutes choses, et n\'a point commis de péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Approchons-nous donc avec assurance du trône de la grâce, afin d\'obtenir miséricorde et de trouver grâce en un temps où il est possible encore d\'être secouru.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'En effet, tout souverain sacrificateur pris du milieu des hommes, est établi en faveur des hommes en vue de leurs rapports avec Dieu, afin d\'offrir des oblations et des sacrifices pour les péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Il peut être indulgent envers ceux qui pèchent par ignorance et par erreur, puisqu\'il est lui-même plein de faiblesse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'et c\'est à cause de cette faiblesse même, qu\'il doit offrir pour sa propre personne, comme pour le peuple, des sacrifices pour les péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'D\'ailleurs on ne s\'arroge point cette dignité, mais on y est appelé de Dieu, comme le fut Aaron.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'De même, Christ ne s\'est point arrogé la gloire d\'être souverain sacrificateur, mais il la tient de celui qui lui a dit: «Tu es mon Fils, je t\'ai engendré aujourd\'hui,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'comme il lui dit encore dans un autre endroit: «Tu es sacrificateur éternellement, selon l\'ordre de Melchisédec.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'C\'est lui qui, aux jours de sa chair, ayant présenté des prières et des supplications, accompagnées de grands cris et de larmes, à Celui qui pouvait le sauver de la mort, et ayant été exaucé pour sa piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'a appris, tout Fils qu\'il est, l\'obéissance par les choses qu\'il a souffertes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'et qui, exalté, est devenu l\'auteur du salut éternel pour tous ceux qui lui obéissent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Dieu, l\'ayant proclamé «souverain sacrificateur selon l’ordre de Melchisédec.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Nous avons à ce sujet, bien des choses à vous dire, et des choses difficiles à expliquer, parce que vous êtes devenus lents à comprendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Vous, qui depuis longtemps devriez être maîtres, vous avez encore besoin qu\'on vous enseigne les premiers éléments des révélations de Dieu; vous en êtes à avoir besoin de lait, plutôt que d\'une nourriture solide.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Quiconque en est encore au lait, ne connaît pas l\'enseignement parfait: c\'est un enfant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'La nourriture solide est pour les hommes faits, pour ceux dont la pratique a exercé les facultés à discerner ce qui est bon et ce qui est mauvais.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'C\'est pourquoi, laissant l\'enseignement élémentaire du Christ, élevons-nous à l\'enseignement parfait, sans poser de nouveau les principes fondamentaux du renoncement aux oeuvres mortes et de la foi en Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'la doctrine du baptême, de l\'imposition des mains, de la résurrection des morts et du jugement éternel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'C\'est ce que nous allons faire, si Dieu le permet,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'car il est impossible que ceux qui ont été une fois éclairés, qui ont goûté le don céleste, qui ont eu part au Saint-Esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'qui ont savouré la bonne parole de Dieu et les puissances du monde nouveau,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'puis sont tombés, soient ramenés à la repentance par un second renouvellement, puis qu\'ils crucifient de nouveau, pour leur malheur, le Fils de Dieu, et l\'exposent à l\'ignominie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Lorsqu\'une terre abreuvée par des pluies fréquentes, produit des plantes utiles à ceux pour qui on la cultive, elle a part à la bénédiction de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'mais, si elle ne donne que des épines et des chardons, c\'est une mauvaise terre, près d\'être maudite, et l\'on finit par y mettre le feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Cependant, mes bien-aimés frères, quoique nous nous exprimions de la sorte, nous sommes convaincus, pour ce qui vous concerne, que des destinées meilleures, auxquelles s\'attache le salut, vous attendent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Dieu est trop juste pour oublier votre travail et l\'amour pour son nom, dont vous avez fait preuve par les services que vous avez rendus et que vous rendez encore aux saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Nous désirons, toutefois, que chacun de vous montre le même zèle à conserver son espérance pleine et entière jusqu’à la fin,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'en sorte que vous ne vous relâchiez point, mais que vous imitiez ceux qui, par une foi persévérante, sont devenus héritiers des promesses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Lorsque Dieu fit la promesse à Abraham, ne pouvant jurer par quelqu\'un de plus grand que lui, il jura par lui-même,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'en disant: «Je fais serment que je te comblerai de bénédictions et que je multiplierai énormément ta postérité:»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'c\'est ainsi qu\'Abraham, ayant persévéré dans la foi, vit se réaliser pour lui la promesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Les hommes, en effet, jurent par celui qui est plus grand qu’eux, et le serment est une assurance qui met fin à toutes leurs contestations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Eh bien! Dieu voulant montrer expressément aux héritiers de la promesse, l’immutabilité de ses desseins, fit intervenir le serment,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'afin que, par deux actes immuables, dans lesquels il est impossible que Dieu nous trompe, nous nous sentions puissamment encouragés, nous qui avons cherché notre refuge en lui, à tenir ferme à l\'espérance qui nous est offerte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Et nous la gardons comme une ancre de l\'âme, sûre et solide, cette espérance qui pénètre jusqu\'au delà du voile, dans le sanctuaire');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'où Jésus est entré pour nous comme précurseur, ayant été fait «souverain sacrificateur pour l’éternité, selon l’ordre de Melchisédec.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'En effet, ce Melchisédec, roi de Salem, sacrificateur du Dieu Très-Haut, qui alla au-devant d\'Abraham, lorsqu\'il revenait de la défaite des rois, — qui le bénit');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'et reçut d\'Abraham la dîme de tout le butin, — qui est d\'abord roi de justice, d\'après l\'interprétation de son nom, puis roi de Salem, c’est-à-dire, roi de paix,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, '— qui est sans père, sans mère, sans aïeux, sans commencement de jours ni fin de vie, — qui est enfin tout à fait semblable au Fils de Dieu, ce Melchisédec, dis-je, demeure sacrificateur à perpétuité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Considérez combien est grand ce personnage, à qui le patriarche même, Abraham, donna une dîme prise sur le meilleur du butin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Ceux des fils de Lévi, qui reçoivent la sacrificature, ont l\'ordre, d\'après la Loi, de lever la dîme sur le peuple, c’est-à-dire, sur leurs frères, quoique ceux-ci soient issus d\'Abraham;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'et un homme qui n\'appartenait point à leur famille, a levé la dîme sur Abraham! et il a béni celui qui avait les promesses!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Or, c\'est sans contredit l\'inférieur qui est béni par le supérieur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'De plus, ici, ce sont des hommes mortels qui perçoivent les dîmes; là, c\'est un personnage dont il est attesté qu\'il est éternellement vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Et Lévi même, qui perçoit la dîme, la lui a, pour ainsi dire, payée en la personne d\'Abraham,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'car il était encore dans les reins de son père, lorsque Melchisédec alla au-devant de ce patriarche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Si donc la perfection avait pu être réalisée par le moyen du sacerdoce lévitique (car le peuple a reçu une législation qui repose sur ce sacerdoce), qu\'était-il encore besoin qu\'il parût un autre sacrificateur «selon l’ordre de Melchisédec,» et non selon l\'ordre d\'Aaron?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Une fois le sacerdoce changé, la Loi l\'est aussi nécessairement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Le sacerdoce est effectivement changé, car celui à qui s\'appliquent ces paroles, appartient à une tribu dont aucun membre n\'a été attaché au service de l\'autel:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'il est notoire que notre Seigneur est sorti de la tribu de Juda, à laquelle Moïse n\'a point attribué le sacerdoce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Ce changement est plus évident encore, quand on voit apparaître un autre sacrificateur qui, de même que Melchisédec,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'est institué, non selon la règle d\'une ordonnance charnelle, mais en vertu d\'une vie qui ne finit point,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'car voici le témoignage qui lui est rendu: «Tu es sacrificateur pour l’éternité, selon l\'ordre de Melchisédec.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Il y a bien abrogation d\'une ordonnance antérieure, à cause de son impuissance et de son inutilité');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(car la Loi n\'a rien amené à la perfection), et introduction, d\'autre part, d\'une meilleure espérance qui nous rapproche de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Et Jésus est le garant d\'une alliance d\'autant supérieure à la première,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'que son sacerdoce n\'a pas été institué sans l\'intervention du serment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Tandis que les Lévites ont été établis sacrificateurs sans serment, Jésus l\'a été avec serment par celui qui lui a dit: «Le Seigneur l\'a juré, et il ne s\'en repentira point: tu es sacrificateur éternellement, selon l’ordre de Melchisédec.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'De plus, ils forment, eux, une succession de sacrificateurs, parce que la mort les empêche de l\'être toujours;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'mais lui, parce qu\'il subsiste «éternellement,» il possède le sacerdoce qui ne se transmet point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'C\'est pour cela aussi qu\'il peut sauver parfaitement ceux qui vont à Dieu par lui, étant toujours vivant pour intercéder en leur faveur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'C\'était bien là le souverain sacrificateur qu\'il nous fallait: saint, innocent, sans tache, hors du contact des pécheurs et élevé au-dessus des cieux;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'qui ne fût pas obligé, comme les souverains sacrificateurs, d\'offrir chaque jour des victimes, d\'abord pour ses propres péchés, puis pour ceux du peuple; car ceci, il l\'a fait une fois pour toutes en s\'offrant lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'La Loi, en effet, institue souverains sacrificateurs des hommes sujets à la faiblesse; mais la parole du serment intervenue après la Loi institue souverain sacrificateur un Fils qui est parvenu pour jamais à la perfection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Un point capital dans notre sujet, c\'est que nous avons un souverain sacrificateur tel, qu\'il s\'est assis à la droite du trône de la Majesté divine dans les cieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'en qualité de ministre du Lieu très-saint et du véritable tabernacle qui a été dressé par le Seigneur, non par un homme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Tout souverain sacrificateur étant établi pour offrir des oblations et des sacrifices, il était nécessaire que lui aussi eût quelque chose à offrir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'S\'il était sur la terre, il ne serait pas même sacrificateur, puisqu\'il s\'y trouve tout un personnel chargé d\'offrir les oblations selon la Loi,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'et de faire le service de ce qui n\'est qu\'une pâle copie du sanctuaire céleste, ainsi que Moïse en fut averti, lorsqu\'il dut exécuter le tabernacle: «Aie soin, lui dit le Seigneur, de faire tout d\'après le modèle qui t\'a été montré sur la montagne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mais notre souverain sacrificateur a obtenu un office d\'autant plus éminent, qu\'il est le médiateur d\'une alliance supérieure à la première, et fondée sur de meilleures promesses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'En effet, si cette première alliance eût été sans défaut, il n\'aurait pas été question de la remplacer par une seconde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Car c\'est bien un blâme que Dieu prononce, quand il dit au peuple: «Voici, les temps viennent, où je traiterai une alliance nouvelle avec la maison à Israël et avec la maison de Juda;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'non pas une alliance comme celle que je fis avec leurs pères au jour où je les pris par la main pour les faire sortir du pays d\'Egypte. Puisqu\'ils ne sont pas demeurés fidèles à mon alliance, moi non plus, je ne me suis pas soucié d\'eux, dit le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Voici l’alliance que je ferai avec la maison d\'Israël, quand les temps seront venus, dit le Seigneur: Je mettrai mes lois dans leur esprit, et je les graverai dans leur coeur; et je serai leur Dieu, et ils seront mon peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Nul n\'enseignera son concitoyen, et nul n\'enseignera son frère, disant: «Connais le Seigneur;» car tous me connaîtront, depuis le plus petit jusqu\'au plus grand d\'entre eux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'parce que je leur pardonnerai leurs fautes, et que je ne me souviendrai plus de leurs péchés ni de leurs iniquités.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'En appelant cette alliance «une alliance nouvelle,» Dieu a frappé la première de vétusté; or ce qui est vieux et suranné touche à sa fin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'La première alliance possède bien aussi des ordonnances pour le culte et un sanctuaire, le sanctuaire terrestre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'On a, en effet, construit un tabernacle, dont la partie antérieure renferme le candélabre, la table et les pains de proposition, et qu\'on appelle le Lieu saint.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Puis, derrière le second voile, se trouve la partie du tabernacle appelée le Lieu très-saint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'renfermant l\'autel d\'or pour les parfums et l\'arche de l\'alliance toute recouverte d\'or. Dans l\'arche se trouvent une urne d\'or contenant la manne, la verge d\'Aaron, qui avait bourgeonné, et les tables de l\'alliance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'elle-même est surmontée des chérubins de la Gloire, qui ombragent le propitiatoire. Mais ce n\'est pas le moment de parler de tout cela en détail.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Ces choses étant ainsi disposées, les sacrificateurs entrent en tout temps dans la partie antérieure du tabernacle, lorsqu\'ils célèbrent le culte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'le souverain sacrificateur seul, et une seule fois par année, entre dans la seconde partie, non sans y porter du sang, qu\'il offre pour sa propre personne et pour les ignorances du peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Le Saint-Esprit fait voir par là, que le chemin du Lieu très-saint n\'est pas ouvert, tant que la partie antérieure du tabernacle subsiste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Elle est une figure symbolique relative au temps présent: elle signifie que les oblations et les sacrifices offerts sont incapables d\'amener celui qui rend ce culte à la perfection réclamée par la conscience.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Ce ne sont là, avec les prescriptions relatives aux aliments, aux boissons et aux diverses ablutions, que des institutions pour la chair imposées jusqu\'à une époque de réformation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mais Christ ayant paru en qualité de souverain sacrificateur des biens à venir, a passé par ce tabernacle plus grand et plus parfait, qui n\'est pas construit de main d\'homme, c’est-à-dire, qui n\'appartient pas à la création d’ici-bas,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'et est entré une fois pour toutes dans le Lieu très-saint, non avec le sang des boucs et des taureaux, mais avec son propre sang, nous ayant acquis un pardon éternel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Car si le sang des boucs et des taureaux et la cendre d\'une vache, dont on asperge ceux qui sont souillés, sanctifie de manière à donner la pureté de la chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'combien plus le sang de Christ qui, doué d\'un esprit éternel, s\'est offert lui-même à Dieu, sans tache, purifiera-t-il notre conscience des oeuvres mortes, pour que nous servions le Dieu vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Voilà pourquoi il est le médiateur d\'un nouveau testament, afin que, par le fait d\'une mort pour le pardon des transgressions commises sous le premier testament, ceux qui ont été appelés reçoivent l\'héritage éternel qui a été promis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'En effet, là où il y a un testament, il est nécessaire de constater la mort du testateur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'un testament n\'étant valable qu\'en cas de mort, puisqu\'il n\'est jamais en vigueur, lorsque le testateur est en vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'C\'est par le même principe que le premier testament a été également inauguré avec du sang.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Quand Moïse eut exposé à tout le peuple tous les commandements, selon la teneur de la Loi, il prit le sang des taureaux et des boucs, avec de l\'eau, de la laine rouge et de l’hysope, et en aspergea le livre même et tout le peuple,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'en disant: «Ceci est le sang de l’alliance que Dieu a ordonné de traiter avec vous.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Puis, il fit pareillement une aspersion de sang sur le tabernacle et sur tous les ustensiles du culte:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'et en général, c\'est avec du sang que, d\'après la Loi, tout est purifié, et sans effusion de sang, il n\'y a point de pardon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Il était donc nécessaire, puisque la copie du Lieu très-saint qui est dans les cieux, est purifiée par ces sacrifices, que le modèle céleste lui-même le fût par des sacrifices supérieurs à ceux-là;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'car ce n\'est pas dans un Lieu très-saint fait de main d\'homme, en imitation du véritable Lieu très-saint, que Christ est entré, mais il est entré dans le ciel même, afin de comparaître maintenant pour nous devant la face de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Il n\'y est pas entré non plus pour s\'offrir plusieurs fois lui-même en sacrifice, comme le souverain sacrificateur, qui entre chaque année dans le Lieu très-saint avec un sang qui n\'est pas le sien;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'autrement, il aurait dû souffrir plusieurs fois depuis la création du monde; mais il s\'est montré une seule fois, dans ces derniers temps, pour anéantir le péché par son sacrifice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Et comme il est arrêté que les hommes meurent une seule fois, après quoi suit un jugement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'de même, Christ, après s\'être offert une seule fois en sacrifice, pour ôter les péchés de beaucoup, apparaîtra une seconde fois, non pour ôter le péché, mais pour donner le salut à ceux qui attendent sa venue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'En effet, la Loi n\'ayant que l\'ombre des biens à venir, et pas même l\'image des choses, ne peut jamais par ces sacrifices renouvelés chaque année et perpétuellement, amener à la perfection ceux qui s\'approchent de l’autel;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'autrement, n\'aurait-on pas cessé de les offrir, par la raison que les adorateurs, une fois purifiés, n\'auraient plus senti leur conscience chargée de péché?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mais par ces sacrifices, on rappelle tous les ans le souvenir des péchés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'car il est impossible que le sang des taureaux et des boucs ôte les péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Cette impossibilité fait dire à Christ entrant dans le monde: «Tu n\'as voulu ni sacrifice ni offrande, mais tu m\'as fait un corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Tu n\'as désiré ni holocaustes ni oblations pour le péché;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'alors j’ai dit: Voici, je viens (car il est question de moi dans le livre) je viens, ô Dieu, pour faire ta volonté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, '— Après avoir commencé par dire: «Tu n\'as point voulu, tu n’as point désiré de sacrifices, ni d \'offrandes, ni d\'holocaustes, ni d\'oblations pour le péché,» (toutes choses qu\'on offre conformément à la Loi),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'il ajoute: «Voici, je viens pour faire ta volonté.» Il supprime le premier point, pour établir le second;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'et c\'est par l\'exécution de cette volonté que nous avons été sanctifiés, nous qui sommes sanctifiés une fois pour toutes par l’oblation du corps de Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'De plus, tandis que tout sacrificateur se tient chaque jour debout pour officier, et offre plusieurs fois les mêmes victimes, qui ne peuvent jamais ôter les péchés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'lui, au contraire, après avoir offert un seul sacrifice pour les péchés, «s\'est assis» pour toujours «à la droite de Dieu,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'attendant désormais que «ses ennemis aient été mis comme un marchepied sous ses pieds;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'car, par une oblation unique, il a amené pour toujours à la perfection ceux qui ont été sanctifiés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'D\'ailleurs, l\'Esprit-Saint nous l\'atteste, puisque, après avoir dit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '«voici l\'alliance que je ferai avec eux, quand les temps seront venus,» le Seigneur ajoute: «Je mettrai mes lois dans leur coeur, je les graverai dans leur esprit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'et je ne me souviendrai plus de leurs péchés ni de leurs iniquités.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Or, là où il y a pardon des péchés et des iniquités, il n\'est plus question d\'oblation pour le péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Puis donc, mes frères, que le sang de Christ nous ouvre un libre accès au Lieu très-saint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'par la voie récente et vivante que Christ a inaugurée pour nous à travers le voile, c’est-à-dire, à travers sa chair,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'et puisque nous avons un souverain sacrificateur à la tête de la maison de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'approchons-nous de Dieu avec un coeur sincère, dans la plénitude de la foi, ayant le coeur purifié des souillures d\'une mauvaise conscience, et le corps lavé d\'une eau pure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Gardons inébranlablement la profession de notre espérance, car celui qui a fait les promesses est fidèle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Ayons l\'oeil les uns sur les autres pour nous exciter à la charité et aux bonnes oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'N\'abandonnons point nos assemblées, comme quelques-uns ont coutume de le faire, mais exhortons-nous les uns les autres, et cela d\'autant plus que vous voyez s\'approcher le grand jour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Si nous péchons volontairement, après avoir reçu la connaissance de la vérité, il ne reste plus de sacrifice pour les péchés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'il n\'y a plus à attendre qu\'un redoutable jugement et l\'ardeur d\'un feu qui doit dévorer les rebelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Si quelqu\'un a violé la loi de Moïse, il meurt sans miséricorde sur le témoignage de deux ou trois personnes:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'quel pire châtiment croyez-vous que méritera celui qui aura foulé aux pieds le Fils de Dieu, qui aura tenu pour impur le sang de l\'alliance, par lequel il avait été sanctifié, et qui aura outragé l\'Esprit de grâce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Car nous connaissons celui qui a dit: «A moi la vengeance! C\'est moi qui rétribuerai!» et encore: «Le Seigneur jugera son peuple.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'C\'est une chose terrible que de tomber entre les mains du Dieu vivant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Rappelez en votre mémoire ces premiers temps, où, après avoir été éclairés, vous avez soutenu un grand et douloureux combat,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'tantôt étant exposés devant tout le monde aux outrages et aux persécutions, tantôt prenant part aux souffrances de ceux qui se trouvaient dans la même situation que vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Vous avez, en effet, montré de la compassion pour les prisonniers, et vous vous êtes résignés avec joie à la perte de vos biens, sachant que vous avez, pour votre part, une fortune meilleure et qui durera toujours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'N\'abandonnez donc point votre assurance: une grande récompense y est attachée;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'et vous avez besoin de persévérance, afin qu\'après avoir fait la volonté de Dieu, vous obteniez ce qui vous est promis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Encore un peu, bien peu de temps, et «celui qui doit venir, viendra: il se fera point attendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Et mon juste vivra par la foi; mais s\'il se retire lâchement, mon âme ne mettra point son affection en lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Pour nous, nous ne sommes pas de ceux qui se retirent, et se perdent; mais de ceux qui gardent la foi, et sauvent leur âme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Or la foi est une ferme persuasion des choses qu\'on espère, une démonstration de celles qu\'on ne voit point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'C\'est pour l\'avoir possédée que les anciens ont reçu un honorable témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'C\'est par la foi que nous reconnaissons que le monde a été fait par la parole de Dieu, en sorte que ce qu\'on voit n\'a pas été fait de choses qui se vissent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'C\'est par la foi qu\'Abel offrit à Dieu un sacrifice plus excellent que celui de Caïn; c\'est par elle qu\'il fut déclaré juste, puisque Dieu approuva son offrande; et, quoique mort, il parle encore par elle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'C\'est par la foi qu\'Hénoch fut enlevé, afin qu\'il ne vît point la mort: «on ne le trouva plus, parce que Dieu l’avait enlevé;» car, avant cet enlèvement, on lui rend le témoignage «qu\'il avait plu à Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Or, sans la foi, il est impossible de lui plaire; car il faut que celui qui s\'approche de Dieu, croie que Dieu est, et qu\'il est le rémunérateur de ceux qui le cherchent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'C\'est par la foi que Noé, averti des événements que l\'on ne voyait pas encore, construisit, avec une pieuse crainte, une arche pour sauver sa famille. C\'est par sa foi qu\'il condamna le monde, et devint héritier de la justice qui vient de la foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'C\'est par la foi qu\'Abraham, l\'appelé, obéit à l\'ordre de se rendre dans le pays qu\'il devait recevoir en héritage, et partit sans savoir où il allait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'C\'est par la foi qu\'il vint s\'établir dans la terre promise, comme dans une terre étrangère, habitant sous des tentes, ainsi qu\'Isaac et Jacob, héritiers comme lui de la même promesse;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'car il attendait la cité aux solides fondements, dont Dieu est l\'architecte et le constructeur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'C\'est par la foi que Sarah, elle aussi, reçut malgré son âge la puissance de donner naissance à une race, parce qu\'elle avait cru à la fidélité de celui qui lui en avait fait la promesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'C\'est pour cela aussi, que naquit d\'un seul homme, et même d\'un homme décrépit, une postérité aussi nombreuse que les étoiles du ciel et que les grains de sable du bord de la mer, qui sont innombrables.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Conformément à la nature même de la foi, tous ces patriarches sont morts sans avoir reçu l’objet des promesses; mais ils l\'ont vu et salué de loin, et ont déclaré être «étrangers et voyageurs sur la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ceux qui tiennent un tel langage, font bien voir qu\'ils cherchent une patrie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'S\'ils eussent entendu par là, la terre d\'où ils étaient sortis, ils auraient eu le temps d\'y retourner;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'mais c\'est à une patrie meilleure qu\'ils aspiraient, nous voulons dire celle qui est dans le ciel. Aussi Dieu n\'a-t-il point honte de s\'appeler «leur Dieu,» car il leur a préparé une cité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'C\'est par la foi qu\'Abraham, étant mis à l\'épreuve, offrit Isaac en sacrifice, et que celui qui avait reçu les promesses,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'à qui l\'on avait dit: «C\'est la postérité d\'Isaac, qui sera dite ta postérité,» offrit son fils unique:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'il pensait que Dieu a la puissance même de ressusciter les morts; aussi recouvra-t-il son fils au moment même où il l\'exposait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'C\'est par la foi, et en vue de l\'avenir, qu\'Isaac bénit Jacob et Ésaü.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'C\'est par la foi que Jacob mourant bénit chacun des fils de Joseph, et «qu\'il adora appuyé sur le haut de son bâton.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'C\'est par la foi que Joseph, sur le point de mourir, fit mention de la sortie des fils d\'Israël, et qu\'il ordonna ce qu\'on devait faire de ses os.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'C\'est par la foi que, lorsque Moïse fut né, son père et sa mère voyant que c\'était un bel enfant, le tinrent caché pendant trois mois, et qu\'ils ne se laissèrent pas effrayer par l\'ordre du roi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'C\'est par la foi que Moïse, devenu grand, répudia le titre de fils d\'une fille de Pharaon,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'et aima mieux être maltraité avec le peuple de Dieu que de goûter une jouissance passagère due au péché:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'il considéra l\'opprobre de Christ comme une richesse plus grande que les trésors de l\'Egypte, parce qu\'il portait ses regards sur la rémunération finale.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'C\'est par la foi qu\'il quitta l\'Egypte, sans se laisser intimider par le courroux du roi: car il tint ferme comme s\'il voyait celui qui est invisible.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'C\'est par la foi qu\'il célébra la Pâque et fit l\'aspersion du sang, afin que l\'exterminateur des premiers-nés ne touchât point à ceux des Israélites.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'C\'est par la foi que les Israélites traversèrent la mer Rouge, comme un lieu sec, tandis que les Égyptiens qui tentèrent le passage, furent engloutis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'C\'est par la foi que les murailles de Jéricho tombèrent, après qu\'on en eut fait le tour pendant sept jours consécutifs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'C\'est par la foi que Rahab, la femme de mauvaise vie, ne périt pas avec les rebelles, parce qu\'elle avait accueilli favorablement les espions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Et que dirai-je encore? Le temps me manquerait, si je voulais parler de Gédéon, de Barac, de Samson, de Jephté, de David, de Samuel et des prophètes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'qui par la foi ont conquis des royaumes, exercé la justice, obtenu des promesses, fermé la gueule des lions,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'éteint la violence du feu, échappé au tranchant de l\'épée, triomphé de la maladie, montré leur vaillance dans la guerre, mis en fuite des armées ennemies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Des femmes ont recouvré leurs morts par une résurrection; d\'autres ont péri dans les tortures, repoussant la délivrance, afin d\'obtenir une plus heureuse résurrection;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'd\'autres ont souffert les moqueries et les verges; bien plus, les fers et les cachots:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'ils ont été lapidés, sciés, tentés; ils sont morts par le tranchant de l\'épée; ils ont erré çà et là, couverts de peaux de moutons, de peaux de chèvres, dénués de tout, persécutés, maltraités, —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'eux, dont le monde n\'était pas digne, — ils ont été errants dans les déserts, dans les montagnes, dans les cavernes et dans les crevasses de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Et tous ces héros, à la foi desquels l\'Écriture rend témoignage, n\'ont point reçu l\'objet de la promesse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'parce que Dieu avait arrêté pour nous quelque chose de meilleur, ne voulant pas qu\'ils parvinssent sans nous à la glorification finale.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Nous donc aussi, puisque nous sommes environnés d\'une si grande nuée de témoins, rejetant tout fardeau, et le péché qui nous entrave fort, courons avec persévérance dans la carrière qui nous est ouverte,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'les yeux fixés sur Jésus, l\'auteur et le consommateur de la foi: lui qui, en vue de la joie qui lui était offerte, a souffert la croix, méprisé l\'ignominie, et «s\'est assis à la droite du trône de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Considérez bien celui qui a supporté une telle opposition de la part des pécheurs, afin que vous ne vous lassiez point en abandonnant vos coeurs au découragement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vous n\'avez pas encore résisté jusqu\'au sang dans votre lutte contre le péché,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'et vous avez oublié l\'exhortation de Dieu qui vous dit comme à des fils: «Mon fils, ne méprise point le châtiment du Seigneur, et ne perds point courage, lorsqu\'il te reprend;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'car le Seigneur châtie celui qu\'il aime, et il frappe de ses verges tous ceux qu\'il reconnaît pour ses fils.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Si vous endurez le châtiment, c\'est que Dieu vous traite comme des fils, car quel est le fils que son père ne châtie pas?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Si vous êtes exempts du châtiment auquel tous ont eu part, vous êtes donc des enfants illégitimes, et non de vrais fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'D\'ailleurs, si nous avons eu du respect pour nos pères selon la chair, lorsqu\'ils nous châtiaient, ne devons-nous pas, à bien plus forte raison, être soumis au Père des esprits pour avoir la vie?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Quant à nos pères, ils nous châtiaient pour un peu de temps, comme il leur semblait bon; mais Dieu nous châtie pour notre bien, afin de nous rendre participants de sa sainteté.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Il est vrai que tout châtiment semble, au premier moment, un sujet de tristesse, et non pas de joie; mais, plus tard, il produit pour ceux qui ont été ainsi exercés, un fruit paisible de justice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'En conséquence, raffermissez les mains qui sont défaillantes et les genoux qui sont chancelants;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'faites suivre à vos pieds le chemin droit, afin que ce qui est boiteux, au lieu de se disloquer, se rétablisse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Recherchez la paix avec tout le monde, et la sanctification sans laquelle personne ne verra le Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Veillez à ce que personne ne se détourne de la grâce de Dieu; à ce qu\'aucune racine vénéneuse venant à pousser, n\'incommode et n\'empoisonne la plupart d’entre vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Qu\'il n\'y ait point de libertin parmi vous, ni de profane comme Ésaü, qui vendit son droit d\'aînesse pour un simple mets:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'vous savez que, plus tard, lorsqu\'il voulut obtenir la bénédiction de son père, il fut repoussé, et ne put le faire changer de sentiment, bien qu\'il le suppliât avec larmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Vous ne vous êtes pas approchés d\'une montagne qu\'on puisse toucher de la main et que le feu embrase, ni de l\'obscurité, ni des ténèbres, ni d\'une tempête,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'ni du bruit des trompettes, ni d\'une voix si retentissante que ceux qui l\'entendirent demandèrent qu\'on ne leur adressât pas une parole de plus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'car ils ne pouvaient supporter cette menace: «Toute bête même qui touchera cette montagne, sera lapidée»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'et ce spectacle était si terrible que Moïse lui-même dit: «Je suis épouvanté et tout tremblant.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Mais vous vous êtes approchés de la montagne de Sion, de la cité du Dieu vivant, qui est la Jérusalem céleste, du choeur joyeux des myriades d\'anges,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'de l\'assemblée des premiers-nés dont les noms sont inscrits dans le ciel, du Juge, le Dieu de tous, des esprits des justes exaltés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'de Jésus, le médiateur de la nouvelle alliance, et du sang de l\'aspersion, qui dit de meilleures choses que celui d\'Abel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Prenez garde de refuser d\'écouter Celui qui vous parle; car si les Israélites n\'échappèrent point à la punition, pour avoir refusé d\'écouter Celui qui dictait ses oracles sur la terre, combien moins pourrons-nous échapper, si nous le repoussons quand il parle des cieux:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Lui, dont la voix alors ébranla la terre, mais qui a fait pour le temps où nous sommes, cette promesse: «J\'ébranlerai une fois encore, non seulement la terre, mais aussi le ciel,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Ces mots, «une fois encore,» indiquent clairement le changement des choses qui vont être ébranlées, comme étant une création passagère, afin que celles qui ne doivent pas être ébranlées, demeurent éternellement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Puis donc que nous allons entrer en possession d\'un royaume qui ne sera point ébranlé, soyons pénétrés d\'une reconnaissance qui nous fasse servir Dieu d\'une manière qui lui soit agréable, avec respect et avec crainte;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'car notre Dieu est aussi un feu dévorant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que l\'amour fraternel règne parmi vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'N\'oubliez pas l\'hospitalité: c\'est en l\'exerçant que quelques-uns ont logé des anges, sans le savoir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Souvenez-vous des prisonniers, comme si vous étiez aussi dans les chaînes, et de ceux qu\'on maltraite, comme étant aussi vous-mêmes dans un corps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Que le mariage soit en honneur chez tous, et le lit nuptial sans souillure, car Dieu jugera les libertins et les adultères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Que votre conduite soit désintéressée: soyez contents de ce que vous avez, car Dieu lui-même a dit: «Je ne te laisserai point, non, je ne t\'abandonnerai point;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'de sorte que nous pouvons dire avec assurance: «Le Seigneur est mon aide; je ne me laisserai point effrayer. Qu\'est-ce que l’homme pourra me faire?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Souvenez-vous des conducteurs qui vous ont annoncé la parole de Dieu, et, considérant comment ils ont terminé leur carrière, sachez imiter leur foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jésus-Christ est le même, hier, aujourd\'hui, éternellement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Ne vous laissez pas détourner par toutes sortes de doctrines étrangères, car il est bon que le coeur s\'affermisse par la grâce, et non par des aliments, qui ne sont d\'aucune utilité à ceux qui en usent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Pour nous, nous avons un autel sur lequel a été immolée une victime, dont ceux qui rendent un culte dans le tabernacle, n\'ont pas le droit de manger;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'car les corps des animaux, dont le sang est porté par le souverain sacrificateur dans le Lieu très-saint, sont brûlés hors du camp;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'et c\'est pour cela que Jésus, afin de sanctifier le peuple par son propre sang, a souffert hors de la porte de la ville.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Aussi, sortons du camp pour aller à lui en portant son opprobre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'car nous n\'avons point ici de cité permanente, mais nous cherchons celle qui est à venir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Que ce soit donc par lui que nous offrions continuellement à Dieu «un sacrifice de louanges,» c’est-à-dire, «le fruit de nos lèvres» qui célèbrent son nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Et n\'oubliez pas d\'exercer la bienfaisance, et de faire part de vos biens aux autres, car c\'est à de tels sacrifices que Dieu prend plaisir.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obéissez à vos conducteurs et déférez à leurs avis; car ils veillent pour vos âmes, comme devant en rendre compte; obéissez-leur, afin qu\'ils s\'acquittent de ce ministère avec joie, et non en gémissant; ce qui ne vous serait pas avantageux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Priez pour nous, car nous sommes assurés d\'avoir une bonne conscience, ayant la volonté de nous bien conduire en toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Je vous demande instamment de le faire, afin que je vous sois plus tôt rendu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Puisse le Dieu de paix, qui a ramené du milieu des morts celui qui, par le sang de l\'alliance éternelle, est devenu le grand Pasteur des brebis, notre Seigneur Jésus,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vous rendre propres à toute bonne oeuvre, pour faire sa volonté, en opérant en vous, par Jésus-Christ, ce qui lui est agréable: à Lui soit la gloire éternellement! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Je vous prie, mes frères, de prendre en bonne part cette exhortation, car je vous écris brièvement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sachez que notre frère Timothée a été relâché. J\'irai vous voir avec lui, s\'il vient assez tôt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saluez tous vos conducteurs et tous les saints. Ceux d\'Italie vous saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Que la grâce soit avec vous tous! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jacques, serviteur de Dieu et du Seigneur Jésus-Christ, aux douze tribus qui sont dans la dispersion, salut!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Mes frères, considérez comme le sujet d\'une joie entière les épreuves diverses par lesquelles vous passez,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'sachant que l\'épreuve de votre foi produit la constance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Mais que la constance soit accompagnée de l\'oeuvre, d’une oeuvre parfaite, afin que vous soyez parfaits et accomplis, ne laissant à désirer en rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Si quelqu\'un parmi vous manque de sagesse, qu\'il la demande à Dieu qui donne à tous généreusement, sans rien reprocher: elle lui sera donnée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Mais qu\'il demande avec foi, sans hésiter, car celui qui hésite est semblable au flot de la mer, agité et ballotté par le vent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'que cet homme-là, homme irrésolu, inconstant dans toutes ses voies,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'ne s\'imagine pas qu\'il recevra quelque chose du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Que le frère de condition humble se glorifie de son élévation,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'et le riche, de ce qui l\'humilie, parce qu\'il passera comme la fleur de l\'herbe:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'le soleil s\'est levé, sa chaleur brûlante a desséché l\'herbe, et la fleur de l\'herbe est tombée, et la beauté de sa forme a péri: ainsi se flétrira le riche au milieu de ses entreprises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Heureux l\'homme qui supporte l\'épreuve avec constance, car lorsqu\'il sera devenu un homme éprouvé, il recevra la couronne de vie, que le Seigneur a promise à ceux qui l\'aiment.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Que personne, lorsqu\'il est tenté, ne dise: «C\'est Dieu qui me tente,» car Dieu ne peut être tenté par le mal, et il ne tente personne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Chacun est tenté, quand il est attiré et amorcé par sa propre convoitise;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'puis, la convoitise, ayant conçu, enfante le péché; et le péché, étant consommé, produit la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne vous y trompez pas, mes frères bien-aimés,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'tout bon présent et tout don parfait descendent d\'en haut, du Père des lumières, en qui il n\'y a ni changement ni ombre de variation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'C\'est lui qui, par sa volonté, nous a enfantés par la parole de vérité, pour que nous soyons l\'élite en quelque sorte de ses créatures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Sachez-le bien, mes chers frères. Que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'car la colère de l\'homme n\'exécute pas la justice de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'C\'est pourquoi, rejetant toute souillure et tout reste de méchanceté, accueillez avec douceur la parole qui a été plantée en vous, et qui peut sauver vos âmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mais mettez-la en pratique, et ne vous contentez pas de l\'écouter, en vous trompant par de faux raisonnements.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Car si quelqu\'un écoute la Parole et ne la met pas en pratique, il est semblable à un homme qui considère dans un miroir son visage naturel,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'et qui, après s\'être considéré, s\'en va, et oublie aussitôt quel il est.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mais celui qui aura plongé ses regards dans la loi parfaite, la loi de la liberté, et qui les y tiendra attachés, non en auditeur oublieux, mais en observateur du commandement, celui-là trouvera son bonheur dans son obéissance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Si quelqu\'un croit être religieux, et qu\'il ne tienne pas sa langue en bride, il se trompe lui-même, et sa religion est vaine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'La religion pure et sans tache devant Dieu, notre Père, consiste à visiter les orphelins et les veuves dans leur affliction, et à se préserver des souillures du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mes frères, n\'alliez aucune acception de personnes avec la foi en notre glorieux Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Si, par exemple, il entre dans votre assemblée un homme ayant des bagues d\'or aux doigts et un habit magnifique, et qu\'il y entre aussi un pauvre ayant un méchant habit,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'et que, jetant les yeux sur celui qui porte l\'habit magnifique, vous lui disiez: «Toi, assieds-toi ici, à cette place d\'honneur,» et que vous disiez au pauvre: «Toi, tiens-toi là, debout, ou assieds-toi au bas de mon marchepied,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'n\'y a-t-il pas de l\'inconséquence en vous, et n\'êtes-vous pas des juges qui cédez à de mauvaises pensées?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Écoutez, mes frères bien-aimés, Dieu n\'a-t-il pas choisi ceux qui sont pauvres aux yeux du monde pour être riches en foi, et héritiers du royaume qu\'il a promis à ceux qui l\'aiment?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Et vous, vous méprisez le pauvre! Ne sont-ce pas les riches qui vous oppriment et qui vous traînent devant les tribunaux?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ne sont-ce pas eux qui insultent le beau nom qui vous a été donné?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Pourtant, si vous accomplissez à leur égard la loi royale, selon cette parole, «tu aimeras ton prochain comme toi-même,» vous faites bien;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'mais si vous faites acception des personnes, vous commettez un péché: la loi vous condamne comme transgresseurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Quiconque, en effet, aura observé toute la loi, s\'il vient à faillir en un seul point, est coupable de tous;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'car celui qui a dit: «ne commets point d’adultère,» a dit aussi, «ne tue point;» or, si tu tues, bien que tu ne commettes pas d\'adultère, tu es transgresseur de la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Parlez et agissez, comme devant être jugés par la loi de la liberté,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'car celui qui n\'aura pas fait miséricorde, sera jugé sans miséricorde: la miséricorde brave le jugement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Mes frères, que sert-il à un homme de dire qu\'il a la foi, s\'il n\'a pas les oeuvres? Cette foi pourra-t-elle le sauver?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Si un frère ou une soeur sont dépourvus de vêtements et qu\'ils manquent de la nourriture quotidienne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'et que l\'un de vous dise: «Allez en paix, chauffez-vous et vous rassasiez,» sans leur donner ce qui est nécessaire au corps, à quoi cela sert-il?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'De même aussi la foi qui n\'a pas les oeuvres, est morte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Mais quelqu\'un dira: «Tu as la foi, moi, j\'ai les oeuvres.» — Montre-moi ta foi sans oeuvres, moi, je te montrerai ma foi par mes oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crois qu\'il n\'y a qu\'un Dieu, tu fais bien; les démons le croient aussi... et ils tremblent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Veux-tu te convaincre, ô homme vain, que la foi sans les oeuvres est inutile?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham, notre père, ne fut-il pas justifié par les oeuvres, lorsqu\'il offrit son fils Isaac sur l\'autel?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Tu vois que la foi agissait concurremment avec ses oeuvres, et que, par ses oeuvres, sa foi fut rendue parfaite:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'ainsi s\'accomplit la parole de l\'Écriture: «Abraham eut foi en Dieu, et cela lui fut imputé à justice;» et il fut appelé «ami de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vous voyez que c\'est par les oeuvres que l\'homme est justifié, et non par la foi seulement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'N\'est-ce pas également par les oeuvres que Rahab, la femme de mauvaise vie, fut aussi justifiée, parce qu\'elle accueillit les messagers, et les fit partir par un autre chemin?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'De même que le corps sans âme est mort, de même la foi sans les oeuvres est morte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mes frères, qu\'il n\'y ait pas parmi vous tant de gens qui s\'érigent en docteurs; vous savez que par là on s\'expose à un arrêt plus sévère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Tous, en effet, nous bronchons fort. Si quelqu\'un ne bronche pas en paroles, c\'est un homme parfait, capable de tenir en bride son corps tout entier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Si, pour nous faire obéir des chevaux, nous leur mettons le mors dans la bouche, nous gouvernons aussi leur corps tout entier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Voyez encore les navires: tout grands qu\'ils sont, et quoique poussés par des vents violents, ils sont dirigés au gré du pilote, par un bien petit gouvernail.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'De même aussi la langue est un petit membre, et elle peut se vanter de grandes choses. Voyez quelle grande forêt un petit feu allume!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'La langue aussi est un feu, le monde de la méchanceté: c\'est la langue qui, parmi les membres, a l\'art de souiller le corps tout entier, et d\'enflammer tout le cours de la vie, étant enflammée elle-même du feu de la Géhenne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Toute espèce de bêtes sauvages et d\'oiseaux, de reptiles et d\'animaux marins se domptent, et ont été domptés par l\'espèce humaine,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'mais la langue, aucun homme ne peut la dompter: c\'est un fléau qu\'on ne peut arrêter; elle est pleine d\'un venin mortel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Avec la langue, nous bénissons le Seigneur, notre Père; et avec la langue, nous maudissons les hommes, qui sont faits à la ressemblance de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'de la même bouche sortent la bénédiction et la malédiction! Il ne faut pas, mes frères, qu\'il en soit ainsi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'est-ce que la source jette par la même ouverture le doux et l\'amer?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'est-ce qu\'un figuier, mes frères, peut donner des olives, ou une vigne des figues? de l\'eau salée ne peut non plus donner de l\'eau douce.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Y a-t-il parmi vous quelque homme sage et instruit, qu\'il montre par sa bonne conduite qu\'il agit avec la douceur de la sagesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Si vous avez dans le coeur un zèle amer et un esprit de dispute, ne vous glorifiez pas de votre sagesse, vous parleriez contre toute vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ce n\'est point là la sagesse qui vient d\'en haut; c\'est une sagesse terrestre, animale, diabolique,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'car là où il y a zèle et esprit de dispute, il y a du désordre et toutes sortes de mauvaises choses;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'tandis que la sagesse qui vient d\'en haut est premièrement pure, ensuite paisible, douce, traitable, pleine de miséricorde et de bons fruits, sans partialité, sans hypocrisie:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'le fruit de justice se sème dans la paix par ceux qui apportent la paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'D\'où viennent les guerres, et d\'où viennent les luttes parmi vous? N\'est-ce pas de vos passions qui se déchaînent dans vos membres?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Vous désirez et vous n\'obtenez pas; vous tuez, vous enviez, et vous ne pouvez arriver à rien; vous êtes dans un état de lutte et de guerre. Vous n\'obtenez pas, parce que vous ne demandez pas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'vous demandez, et vous ne recevez pas, parce que vous demandez mal, et dans le but de satisfaire vos passions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ames adultères, ne savez-vous pas que l\'amour du monde est inimitié contre Dieu? Celui donc qui veut être ami du monde est ennemi de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'ou bien, pensez-vous que l\'Écriture parle en vain? C\'est avec jalousie que Dieu chérit l’âme qu\'il a mise au dedans de nous,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'et il accorde une grâce supérieure à celle que le monde accorde; c\'est pourquoi l\'Écriture dit: «Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Soumettez-vous donc à Dieu; résistez au diable, et il s\'enfuira de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Approchez-vous de Dieu, et il s\'approchera de vous. Nettoyez vos mains, pécheurs; purifiez vos âmes, hommes irrésolus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Sentez votre misère, affligez-vous et pleurez: que votre rire se change en pleurs et votre joie en tristesse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humiliez-vous devant le Seigneur, et il vous élèvera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Mes frères, ne parlez point mal les uns des autres: celui qui dit du mal d\'un frère ou qui juge son frère, dit du mal de la loi et juge la loi; or, si tu juges la loi, tu n\'es pas un observateur de la loi, mais tu t\'en fais juge.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Un seul est législateur et juge, c\'est Celui qui a la puissance de sauver et de perdre; mais qui es-tu, toi, qui juges le prochain?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'A vous maintenant qui dites: «Aujourd\'hui et demain nous irons dans telle ville, nous y passerons une année, nous trafiquerons et nous gagnerons»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '— vous, qui ne savez pas ce qu\'il en sera de demain, car qu\'est-ce que votre vie? Vous êtes une vapeur qui paraît un moment, puis qui disparaît');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, '— tandis que vous devriez dire: «Si le Seigneur le veut, nous vivrons et nous ferons ceci ou cela.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Glorifiez-vous donc avec vos vanteries! Toute jactance semblable est mauvaise.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Celui donc qui sait faire ce qui est bien, et qui ne le fait pas, commet un péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'A vous maintenant riches: pleurez et poussez des cris à cause des malheurs qui vont fondre sur vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vos richesses sont pourries, et vos étoffes sont devenues la proie des gerces;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'votre or et votre argent sont rouillés; et cette rouille s\'élèvera en témoignage contre vous, et, comme du feu, elle dévorera vos chairs. Quel trésor vous vous serez fait dans les derniers jours!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Voici, il crie le salaire dont vous avez frustré les ouvriers qui ont moissonné vos champs, et les cris des moissonneurs sont parvenus aux oreilles du Seigneur des armées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vous avez vécu sur la terre dans les délices et dans les festins, vous avez repu vos coeurs au jour du carnage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'vous avez condamné, vous avez tué le juste: il ne vous résiste pas.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Prenez donc patience, mes frères, jusqu’à l\'avènement du Seigneur. Voyez: le laboureur attend le précieux fruit de la terre, en prenant patience, jusqu’à ce que le grain ait reçu les pluies de la première et de l\'arrière-saison.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Vous aussi, prenez patience, fortifiez vos coeurs, car l\'avènement du Seigneur est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne vous répandez pas en plaintes les uns contre les autres, mes frères, afin que vous ne soyez pas jugés; voici, le juge est à la porte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Prenez, mes frères, pour modèles de souffrance et de patience les prophètes qui ont parlé au nom du Seigneur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Vous voyez que nous proclamons bienheureux ceux qui souffrent avec patience. Vous avez entendu parler de la patience de Job, et vous avez vu la fin que le Seigneur lui a ménagée, car le Seigneur est plein de tendresse et de commisération.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Par-dessus tout, mes frères, ne jurez ni par le ciel, ni par la terre, ni par quelque autre chose que ce soit; mais que votre oui soit oui, et que votre non soit non, afin de ne pas tomber sous le coup du jugement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Quelqu\'un parmi vous souffre-t-il, qu\'il prie. Quelqu\'un est-il joyeux, qu\'il chante des cantiques.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Quelqu\'un parmi vous est-il malade, qu\'il fasse appeler les anciens de l\'église, et que ceux-ci prient pour lui, après l\'avoir oint d\'huile au nom du Seigneur:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'la prière de la foi sauvera le malade, le Seigneur le relèvera, et, s\'il a commis des péchés, ils lui seront pardonnés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Confessez-vous donc réciproquement vos fautes, et priez les uns pour les autres, afin que vous soyez guéris. La prière du juste a une bien grande efficace.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Élie était un homme comme nous: il pria avec ferveur, pour qu\'il ne tombât point de pluie, et il ne tomba point de pluie sur la terre pendant trois ans et demi;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'puis, il pria de nouveau, et le ciel donna de la pluie, et la terre produisit son fruit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Mes frères, si quelqu\'un parmi vous s\'est égaré loin de la vérité, et que quelqu\'un l\'y ramène,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'sachez que celui qui ramènera un pécheur de la voie où il s\'égare, sauvera une âme de la mort, et couvrira une multitude de péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pierre, Apôtre de Jésus-Christ, aux fidèles qui sont étrangers et dispersés dans le Pont, dans la Galatie, dans la Cappadoce, dans l\'Asie et dans la Bithynie,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'qui sont élus selon la prescience de Dieu, le Père, et sanctifiés en leur esprit, pour être obéissants et purifiés par l’aspersion du sang de Jésus-Christ: que la grâce et la paix vous soient données de plus en plus!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Béni soit Dieu, le Père de notre Seigneur Jésus-Christ, de ce que, dans sa grande miséricorde, il nous a régénérés, pour que nous ayons une espérance vivifiante, par la résurrection de Jésus-Christ d\'entre les morts,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'un héritage qui ne se peut ni gâter, ni souiller, ni flétrir. Il nous le réserve dans les cieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'et sa puissance nous garde par la foi, pour nous mettre en possession du salut, qui est prêt à apparaître au moment final.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Cette pensée vous remplit de joie, quoique maintenant, puisqu\'il le faut, vous soyez attristés pour un peu de temps par diverses épreuves,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'afin que la solidité éprouvée de votre foi, qui est plus précieuse que l\'or périssable, qu\'on éprouve cependant par le feu, vous soit un sujet de louange, d\'honneur et de gloire, quand Jésus-Christ paraîtra.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Vous l’aimez, sans l\'avoir vu; et, en croyant en lui quoique vous ne le voyiez point encore, vous tressaillez d\'une joie ineffable et glorieuse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'parce que vous allez remporter le salut de vos âmes, qui est le but de votre foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Ce salut a été l\'objet des recherches et des investigations des prophètes qui ont parlé de la grâce qui vous est destinée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Ils recherchaient à quel temps et à quelles circonstances faisait allusion l\'Esprit de Christ qui était en eux, et qui annonçait d\'avance les souffrances réservées au Christ, et les gloires qui devaient les suivre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Il leur fut révélé que c\'était, non pour eux-mêmes, mais pour nous, que leur ministère était requis pour les choses, que ceux qui vous ont prêché l\'évangile par le Saint-Esprit envoyé du ciel, vous ont maintenant annoncées, et dans lesquelles les anges désirent plonger leurs regards.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'C\'est pourquoi, ayant ceint les reins de votre esprit, étant sobres, attendez avec une parfaite espérance la grâce qui vous sera apportée, quand Jésus-Christ paraîtra.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Comme des enfants obéissants, ne vous laissez point aller aux passions que vous aviez autrefois, quand vous étiez dans l\'ignorance;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'mais, comme Celui qui vous a appelés est saint, vous aussi soyez saints dans toute votre conduite,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'attendu qu\'il est écrit: «Soyez saints, car je suis saint.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Et si vous appelez Père, celui qui juge chacun selon ses oeuvres, sans faire acception des personnes, conduisez-vous avec crainte pendant le temps de votre séjour ici-bas;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'sachant que vous avez été affranchis de la vaine manière de vivre que vous teniez de vos pères, non par des choses périssables, de l\'argent ou de l\'or,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mais par un sang précieux, comme celui d\'un agneau sans défaut et sans tache,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'par le sang de Christ qui a été prédestiné avant la création du monde, et qui a paru à la fin des temps, à cause de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'C\'est par lui que vous croyez en Dieu, qui l’a ressuscité des morts et qui lui a donné la gloire, en sorte que vous avez mis en Dieu votre foi et votre espérance.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Puisqu\'en obéissant à la vérité, vous avez purifié vos âmes par le moyen de l\'Esprit, pour avoir un amour fraternel sincère, aimez-vous les uns les autres du fond du coeur, ardemment,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'vous qui avez été régénérés, non par une semence corruptible, mais par une semence incorruptible, par la parole de Dieu vivifiante et éternelle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'car «toute chair est comme l’herbe, et toute sa gloire comme la fleur de l’herbe: l’herbe sèche et sa fleur tombe,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'mais la parole du Seigneur demeure éternellement:» c\'est cette parole dont la bonne nouvelle vous a été portée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Ayant donc dépouillé toute méchanceté et toute ruse, la dissimulation, l\'envie et toute espèce de médisance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'désirez, comme des enfants nouveau-nés, le pur lait spirituel, afin qu\'il vous fasse grandir pour le salut,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, '«si réellement vous avez goûté que le Seigneur est bon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Approchez-vous de lui, «la pierre» vivante, «mise au rebut,» il est vrai, par les hommes, mais «choisie, précieuse» aux yeux de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'et comme des pierres vivantes, formez vous-mêmes un édifice, une maison spirituelle, pour constituer une sainte sacrificature, et offrir des sacrifices spirituels à Dieu par Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'puisqu\'il est dit dans l\'Ecriture: «Voici, je place en Sion une pierre angulaire, choisie, précieuse: celui qui met en elle sa confiance ne sera point confus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'A vous donc qui avez confiance, l\'honneur; mais pour les incrédules, «cette même pierre que les constructeurs ont mise au rebut, est devenue la pierre angulaire,» et «une pierre d\'achoppement, une pierre qui les fait trébucher,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'eux qui, par leur incrédulité, vont se heurter contre la Parole; comme aussi ils y ont été destinés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Pour vous, vous êtes une race élue, une sacrificature royale, une nation sainte, un peuple que Dieu s\'est acquis, afin que vous publiiez les vertus de Celui qui vous a appelés à sa merveilleuse lumière,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'vous qui autrefois n\'étiez pas un peuple, et qui êtes maintenant le peuple de Dieu; vous qui n\'aviez point obtenu miséricorde et qui maintenant avez obtenu miséricorde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Mes bien-aimés, je vous recommande, comme étrangers et voyageurs, de vous abstenir des passions charnelles, parce qu\'elles font la guerre à l\'âme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Ayez une bonne conduite parmi les Gentils, afin que sur le point même où ils vous calomnient comme si vous étiez des malfaiteurs, ils en viennent, en y regardant de près, à glorifier Dieu pour vos bonnes oeuvres, au jour de la Visitation.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Soyez donc soumis à toute institution humaine, à cause du Seigneur, soit au roi, comme souverain,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'soit aux gouverneurs, comme délégués par lui pour faire justice des malfaiteurs, et pour approuver les gens de bien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Car c\'est la volonté de Dieu, que, par votre bonne conduite, vous fermiez la bouche aux insensés qui vous méconnaissent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Soyez soumis comme des hommes libres, non pas comme des hommes qui se font de la liberté un manteau pour couvrir leur méchanceté, mais comme des esclaves de Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'honorez tous les hommes; aimez les frères; craignez Dieu; honorez le roi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Vous, serviteurs, soyez soumis à vos maîtres avec un profond respect, non seulement à ceux qui sont bons et doux, mais aussi à ceux qui sont d\'une humeur difficile;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'car c\'est une chose agréable à Dieu, quand, pour lui et par motif de conscience, on endure des peines en souffrant injustement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Quelle gloire y a-t-il pour vous à supporter patiemment d\'être battus, quand vous avez commis quelque faute? Mais si vous supportez patiemment d\'être maltraités, quand vous faites bien, voilà qui est agréable à Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'C\'est à cela, en effet, que vous êtes appelés, puisque Christ même a souffert pour vous, vous laissant un exemple, afin que vous suiviez ses traces,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'lui «qui n’a point commis de péché, et dans la bouche duquel il ne s’est point trouvé de fraude,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, '— lui qui, injurié, ne rendait point d\'injure, qui, maltraité, ne faisait point de menaces, mais s\'en remettait à Celui qui juge justement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, '— lui qui a lui-même porté nos péchés en son corps sur le bois, afin qu\'étant morts au péché, nous vivions pour la justice, — lui par les meurtrissures duquel vous avez été guéris,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'car «vous étiez comme des brebis errantes,» mais maintenant vous êtes retournés à celui qui est le pasteur et le gardien de vos âmes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Que les femmes soient soumises à leurs maris, afin que, s\'il y a des maris qui n\'obéissent pas à la Parole, ils soient gagnés par la conduite de leurs femmes, sans le secours de la parole,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'lorsqu\'ils verront leur conduite chaste et respectueuse.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Que leur parure ne soit pas cette parure extérieure, qui consiste à se tresser les cheveux, à se couvrir de bijoux d\'or ou à s\'ajuster des vêtements,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mais qu\'elles ornent l\'être caché du coeur, de la parure impérissable d\'un esprit doux et paisible, qui est d\'un grand prix devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'C\'est ainsi qu\'autrefois se paraient les saintes femmes qui mettaient leur espérance en Dieu, en demeurant soumises à leurs maris:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'telle était Sarah, qui obéissait à Abraham, l\'appelant son seigneur, elle, dont vous êtes devenues les filles par votre bonne conduite, et par votre courage qui ne s\'effraie de rien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Et vous de même, maris, comportez-vous sagement avec vos femmes, comme avec un sexe faible. Traitez-les avec honneur, comme héritant aussi avec vous la grâce de la vie, pour que rien ne vienne vous empêcher, les uns et les autres, de prier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Enfin soyez tous animés des mêmes pensées et des mêmes sentiments, pleins d\'amour fraternel, de tendresse, d\'humilité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Ne rendez point mal pour mal, ni injure pour injure; bénissez au contraire, car c\'est à cela que vous avez été appelés, afin d\'hériter la bénédiction.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Que celui, en effet, qui veut aimer la vie et voir des heureux jours, empêche sa langue de dire du mal et ses lèvres de proférer des paroles trompeuses;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'qu’il se détourne du mal et fasse le bien; qu’il recherche la paix et la poursuive;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'car le Seigneur a les yeux sur les justes, et se oreilles sont attentives à leurs prières; mais la face du Seigneur est contre ceux qui font le mal.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Et qui vous maltraitera, si vous vous portez avec ardeur au bien?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Quand même vous souffririez pour la justice, soyez heureux. «Ne redoutez pas leurs menaces, et ne vous laissez pas troubler;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'mais sanctifiez dans vos coeurs Christ, le Seigneur.» Soyez toujours prêts à répondre, mais avec douceur et respect, à quiconque vous demande raison de votre espérance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'ayant une bonne conscience, afin que, sur le point même où l’on vous calomnie, vous couvriez de confusion ceux qui diffament votre conduite en Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'il vaut mieux souffrir, si telle est la volonté de Dieu, en faisant bien qu\'en faisant mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Christ aussi a bien souffert pour les péchés, lui juste pour les injustes, afin de nous donner accès auprès de Dieu, lorsqu\'il a été mis à mort quant à la chair, mais qu\'il a été rendu vivant quant à l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Esprit, il est allé prêcher aux esprits qui sont en prison, pour avoir été jadis rebelles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'lorsqu\'au temps de Noé la longanimité de Dieu temporisait, pendant que se construisait l\'arche, dans laquelle un petit nombre de personnes, huit seulement, furent sauvées à travers l\'eau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Cette eau, dont le baptême est l\'image — non ce baptême qui ôte les souillures du corps, mais celui qui est l\'aspiration d\'une bonne conscience vers Dieu — nous sauve maintenant, nous aussi, par la résurrection de Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'qui est à la droite de Dieu, dans le ciel où il est allé, et où les anges, les principautés et les puissances lui sont soumis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Puis donc que Christ a souffert pour nous en la chair, vous aussi armez-vous de la même pensée: c\'est que celui qui a souffert en la chair, a rompu avec le péché,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'pour vivre, pendant le temps qui lui reste à passer en la chair, non plus selon les passions des hommes, mais selon la volonté de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'c\'est bien assez d\'avoir accompli autrefois la volonté des Gentils, en vous livrant aux désordres, aux passions, à l\'ivrognerie, aux excès de table et de vin et aux idolâtries criminelles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Ils trouvent étrange que vous ne vous précipitiez pas avec eux dans les mêmes excès de dissolution, et ils se répandent en injures,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'mais ils rendront compte à celui qui est tout prêt à juger les vivants et les morts;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'car, c\'est en vue de ce jugement que la bonne nouvelle a été annoncée aussi aux morts, afin qu\'après avoir été condamnés en la chair, comme on condamne les hommes, ils vivent, comme vit Dieu, par l\'esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'La fin de toutes choses est proche: soyez donc sages et sobres, pour vaquer à la prière;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'surtout ayez une ardente charité les uns pour les autres, car la charité couvrira une multitude de péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Exercez entre vous l\'hospitalité, sans murmurer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Que chacun de vous mette le don qu\'il a reçu au service des autres, comme de bons administrateurs de la grâce de Dieu, laquelle est variée dans ses dons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Si quelqu\'un parle, que ce soit comme il convient à la parole de Dieu; si quelqu\'un exerce un ministère, qu\'il s\'en acquitte comme usant d\'une force que Dieu dispense, afin que tout se fasse à la gloire de Dieu, par Jésus-Christ, à qui appartiennent la gloire et la puissance aux siècles des siècles. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Mes bien-aimés, ne trouvez pas étrange que le feu qui doit vous éprouver, ait éclaté au milieu de vous, comme s\'il vous arrivait quelque chose d\'extraordinaire;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'mais réjouissez-vous dans la mesure même où vous avez part aux souffrances de Christ, afin que vous vous réjouissiez aussi lors de l\'apparition de sa gloire, en tressaillant de joie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Si vous êtes outragés pour le nom de Christ, vous êtes bienheureux, car l\'esprit de gloire, l\'Esprit de Dieu repose sur vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Que nul de vous ne souffre comme meurtrier, comme voleur ou comme s\'ingérant dans les affaires d\'autrui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'mais s\'il souffre comme chrétien, qu\'il n\'en ait point de honte, au contraire, qu\'il glorifie Dieu de ce nom même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'En effet, le moment du jugement est venu; il va commencer par la maison de Dieu, et s\'il débute par nous, quelle sera la fin de ceux qui n\'obéissent point à l’évangile de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Et si le juste se sauve à grand\'peine, qu\'en sera-t-il de l\'impie et du pécheur?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Que ceux donc qui souffrent par la volonté de Dieu, lui remettent leur âme, comme au fidèle créateur, en s\'attachant au bien.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Je m\'adresse maintenant aux anciens qui sont parmi vous, moi qui suis ancien avec eux et témoin des souffrances de Christ, et qui ai part aussi à la gloire qui doit apparaître.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paissez le troupeau de Dieu, qui vous est confié, veillant sur lui, non par contrainte, mais de bon gré; non en vue d\'un gain sordide, mais par dévouement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'non en maîtrisant ceux qui vous sont échus en partage, mais en vous rendant les modèles du troupeau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'et, lorsque le souverain Pasteur paraîtra, vous remporterez la couronne immortelle de gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'De même, vous qui êtes jeunes, soyez soumis aux anciens, et tous revêtez les uns à l\'égard des autres la livrée de l\'humilité, car «Dieu résiste aux orgueilleux, mais il fait grâce aux humbles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Humiliez-vous sous la puissante main de Dieu, afin qu\'il vous élève quand il en sera temps,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'vous déchargeant sur lui de tout ce qui vous inquiète, car lui-même prend soin de vous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Soyez sobres; veillez. Le diable, votre adversaire, rôde autour de vous, comme un lion rugissant, cherchant qui il pourra dévorer:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'résistez-lui par votre fermeté dans la foi, sachant que vos frères dispersés dans le monde subissent les mêmes épreuves que nous; et, après quelque temps de souffrance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'le Dieu de toute grâce, qui vous a appelés en Jésus-Christ à son éternelle gloire, vous rétablira, vous soutiendra, vous fortifiera et vous rendra inébranlables.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A lui soient la gloire et la puissance aux siècles des siècles. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Je vous écris ces quelques mots par Silvain, que j\'estime être un fidèle frère, pour vous exhorter et pour vous assurer que c\'est bien à la vraie grâce de Dieu que vous êtes attachés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'L’église élue qui est à Babylone, vous salue, ainsi que Marc mon fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saluez-vous les uns les autres par un baiser affectueux. Que la paix soit avec vous tous qui êtes en Jésus-Christ!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Syméon Pierre, serviteur et Apôtre de Jésus-Christ, à ceux qui, par la justice de notre Dieu, et de notre Sauveur Jésus-Christ, ont reçu comme nous le don précieux de la foi:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'que la grâce et la paix vous soient données de plus en plus par la connaissance de Dieu et de Jésus, notre Seigneur!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Puisque la divine puissance de Jésus nous a fait don de tout ce qui regarde la vie et la piété, en nous faisant connaître Celui qui nous a appelés par sa gloire propre et par sa vertu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'et qui a accompli pour nous les promesses les plus importantes et les plus précieuses, afin que par elles vous devinssiez participants de la nature divine en fuyant la corruption que les passions ont répandues dans le monde');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, '— faites de votre côté tous vos efforts pour joindre à votre foi la vertu, à la vertu la science,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'à la science la tempérance, à la tempérance la patience, à la patience la piété,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'à la piété l\'amour fraternel, à l\'amour fraternel la charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'La possession et le développement en vous de ces vertus vous fera faire de réels progrès dans la connaissance de notre Seigneur Jésus-Christ;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'car celui à qui elles font défaut est un homme qui a la vue courte, un aveugle; il oublie qu\'il a été purifié de ses anciens péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'En conséquence, mes frères, appliquez-vous d\'autant plus à assurer votre vocation et votre élection, car, si vous agissez de la sorte, vous ne ferez jamais de faux pas:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'c\'est ainsi, en effet, que l\'entrée dans le royaume éternel de notre Seigneur et Sauveur Jésus-Christ vous sera richement accordée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Dans ce but, je devrai toujours vous rappeler ces choses, bien que vous les connaissiez, et que vous soyez fermes dans la vérité dont il s\'agit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Je crois de mon devoir, aussi longtemps que je serai dans cette tente, de vous tenir en éveil en vous les rappelant,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'car je sais que je dois la quitter soudainement, ainsi que notre Seigneur Jésus-Christ me l\'a déclaré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Je ferai également mes efforts, pour qu\'après mon départ, vous conserviez toujours le souvenir de ce que je vous ai dit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Car ce n\'est point en suivant des fables ingénieusement fabriquées, que nous vous avons fait connaître la puissance et l\'avènement de notre Seigneur Jésus-Christ, mais c\'est pour avoir vu sa majesté de nos yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Il reçut, en effet, honneur et gloire de Dieu son Père, quand la Majesté suprême lui adressa cette parole: «Celui-ci est mon Fils bien-aimé, en qui j\'ai mis toute mon affection;»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'et nous avons entendu nous-même cette voix qui venait du ciel, lorsque nous étions avec lui sur la montagne sainte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'D\'ailleurs, ce qui est plus sûr encore, nous possédons les oracles des prophètes, et vous faites bien d\'y prêter attention, comme à une lampe qui brille dans un lieu obscur jusqu’à ce que le jour commence à poindre, et que l\'étoile du matin se lève dans vos coeurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Seulement, sachez bien qu\'aucune prophétie de l\'Ecriture n\'est affaire d\'explication particulière;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'car la prophétie n\'a jamais été inspirée par la volonté de l\'homme, mais c\'est poussés par le Saint-Esprit, que les saints hommes de Dieu ont parlé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Mais, comme il y a eu de faux prophètes parmi le peuple, il y aura aussi parmi vous de faux docteurs, qui introduiront sourdement de pernicieuses hérésies, et qui, reniant le maître qui les a achetés, attireront sur eux-mêmes une soudaine ruine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Bien des gens les suivront dans leurs désordres, en sorte que la voie de la vérité sera diffamée à cause d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Poussés par la cupidité, ils vous exploiteront avec des paroles artificieuses; mais leur sentence a été dès longtemps prononcée, et leur ruine ne s\'endort point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Si Dieu, en effet, n\'a point épargné les anges qui avaient péché, mais les a précipités dans le Tartare, enveloppés de ténèbres comme de liens, et gardés pour le jugement;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 's\'il n\'a point épargné l\'ancien monde, mais a préservé Noé, lui huitième, comme prédicateur de la justice, lorsqu\'il envoya le déluge sur la terre impie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'si, réduisant en cendres les villes de Sodome et de Gomorrhe, il les a condamnées à une ruine totale, pour servir d\'exemple aux impies à venir,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'et a sauvé le juste Loth, qui était las de la conduite désordonnée de ces hommes déréglés');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(car ce juste qui habitait au milieu d\'eux, sentait son âme juste se tourmenter journellement des oeuvres criminelles qui frappaient ses oreilles et ses yeux),');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'c\'est que le Seigneur sait délivrer de l\'épreuve les hommes pieux, et châtier les méchants, qu\'il garde pour le jour du jugement,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'ceux surtout qui, emportés par leur passion de souillure, s\'adonnent aux impuretés de la chair et méprisent l\'autorité. Ces audacieux, ces arrogants, ils ne tremblent pas d\'injurier les Gloires,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'quand des anges, qui leur sont supérieurs en force et en puissance, ne portent point contre elles de jugement en termes injurieux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Pour eux, comme des animaux stupides, nés, comme des êtres matériels, pour être pris et périr, ils se répandent en injures contre ce qu\'ils ignorent, et périront aussi par leur corruption: ce sera le salaire de leur perversité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, '— ces gens qui ne voient de bonheur que dans les voluptés en plein jour, — qui sont une tache, une honte, — qui se délectent de leurs tromperies, quand ils se mêlent à vos festins.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Leurs regards cherchent la femme adultère, et trahissent une soif insatiable de péché; ils prennent à leurs amorces les âmes chancelantes; ils ont le coeur exercé aux adresses de la cupidité: ce sont des enfants maudits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Après avoir abandonné le droit chemin, ils se sont égarés en suivant la voie de Balaam, fils de Bosor. Cet homme amoureux du salaire de l\'iniquité,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'vit sa prévarication démasquée: une bête de somme muette se mettant à parler d\'une voix humaine, arrêta la démence du prophète.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ce sont des sources sans eau, des vapeurs poussées par un ouragan; c\'est à eux que les plus profondes ténèbres sont réservées:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'car par leurs théories pompeuses et vides, ils attirent dans les passions sensuelles, dans les désordres, ceux qui se retiraient réellement des hommes qui vivent dans l\'égarement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Ils leur promettent la liberté, eux qui sont eux-mêmes les esclaves de la corruption, car on est esclave de ce par quoi l\'on est vaincu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'En effet, si, après s\'être retirés des souillures du monde par la connaissance du Seigneur et Sauveur Jésus-Christ, ils se laissent vaincre en s\'y engageant de nouveau, leur dernière condition est pire que la première:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'il leur eût mieux valu n\'avoir point connu la voie de la justice, que de se détourner, après l\'avoir connue, du saint commandement qui leur a été enseigné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Il leur est arrivé ce que dit le proverbe si vrai, «c\'est un chien qui est retourné à ce qu\'il avait vomi,» et, c\'est une truie, qui, après avoir été lavée, est retournée se vautrer dans le bourbier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Voilà déjà, mes bien-aimés, la seconde lettre que je vous écris. Dans l\'une et dans l\'autre, je fais appel à vos souvenirs,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'pour solliciter votre esprit net de se rappeler les paroles prononcées par les saints prophètes, ainsi que le commandement du Seigneur et Sauveur, enseigné par vos apôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Sachez, avant toutes choses, que dans les derniers temps il viendra des moqueurs pleins d\'ironie, vivant au gré de leurs passions,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'qui diront: «où est la promesse de son avènement? car depuis que les pères sont morts, tout continue à subsister comme depuis le commencement de la création.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ces gens-là veulent bien ignorer qu\'il existait jadis des cieux, et une terre que la parole de Dieu avait fait surgir de l\'eau, au moyen de l\'eau,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'et que, par ces cieux et par cette eau, le monde d\'alors périt submergé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Quant aux cieux d\'à présent et à la terre, la parole de Dieu les tient en réserve pour le feu, et les garde pour le jour du jugement et de la ruine des hommes impies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Or, mes bien-aimés, il est un point qui ne doit pas vous échapper, c\'est que, pour le Seigneur, un jour est comme mille ans, et «mille ans sont comme un jour.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Le Seigneur ne tarde pas dans l\'exécution de sa promesse, comme le pensent certaines personnes; il use de patience envers vous, ne voulant pas qu\'aucun périsse, mais que tous viennent à résipiscence.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Le jour du Seigneur viendra comme vient un voleur. Alors les cieux passeront avec un sifflement, les éléments embrasés se dissoudront, et la terre sera consumée avec tous les ouvrages qu\'elle contient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Puis donc que tout doit se dissoudre, quels ne devez-vous pas être par une conduite sainte et pieuse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'en attendant et en hâtant la venue du jour de Dieu, pour lequel les cieux en feu se dissoudront, et les éléments embrasés se fondront?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Nous attendons également, selon sa promesse, «de nouveaux cieux et une nouvelle terre,» où la justice habitera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Dans cette attente, faites tous vos efforts, mes bien-aimés, pour que Dieu vous trouve purs, irréprochables et vivant en paix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Croyez que la longue patience de notre Seigneur est un salut, ainsi que Paul, notre bien-aimé frère, vous l’a aussi écrit, selon la sagesse qui lui a été donnée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'comme il le dit, d\'ailleurs, dans toutes les lettres où il aborde ces sujets, qui, en certains points, sont difficiles à entendre, et que des personnes ignorantes et mal affermies tordent pour leur propre ruine, comme elles tordent aussi les autres Écritures.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vous donc, mes bien-aimés, qui êtes prévenus, tenez-vous sur vos gardes, de peur qu\'en vous laissant entraîner par l’erreur de ces impies, vous ne veniez à perdre votre ferme conviction,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'et croissez dans la grâce et dans la connaissance de notre Seigneur et Sauveur Jésus-Christ. A lui soit la gloire, maintenant et jusqu\'au jour de l\'éternité. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Ce qui était dès le commencement, ce que nous avons entendu, ce que nous avons vu de nos yeux, ce que nous avons contemplé, et ce que nos mains ont touché concernant la parole de vie, nous vous l\'annonçons.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Car la vie s\'est manifestée, et nous l\'avons vue; nous lui rendons témoignage, et nous vous annonçons la vie éternelle qui était avec le Père, et qui s\'est manifestée à nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Ce que nous avons vu et entendu, nous vous l’annonçons, afin que, vous aussi, vous soyez en communion avec nous; et notre communion à nous, est une communion avec le Père et avec son Fils, Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'et nous vous écrivons ces choses, afin que votre joie soit parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'La nouvelle que nous tenons de Jésus, et que nous vous annonçons, c\'est que Dieu est lumière, et qu\'il n\'y a point en lui de ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Si nous disons que nous sommes en communion avec lui, et que nous marchions dans les ténèbres, nous mentons, et nous ne pratiquons pas la vérité;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'mais si nous marchons dans la lumière, comme lui-même est dans la lumière, nous sommes en communion avec lui, et lui avec nous, et le sang de Jésus, son Fils, nous purifie de tout péché.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Si nous disons que nous sommes sans péchés, nous nous séduisons nous-mêmes et la vérité n\'est point en nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Si nous confessons nos péchés, Dieu est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Si nous disons que nous n\'avons point péché, nous le faisons menteur, et sa Parole n\'est point en nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Mes chers enfants, je vous écris ces choses, afin que vous ne péchiez point; toutefois, si quelqu\'un a péché, qu\'il sache que nous avons un avocat auprès du Père, Jésus-Christ le juste,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'et qu\'il est lui-même une victime de propitiation pour nos péchés, non seulement pour les nôtres, mais aussi pour ceux du monde entier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'C\'est à ceci que nous connaissons que nous l\'avons connu: si nous gardons ses commandements.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Celui qui dit, «je l\'ai connu,» et qui ne garde pas ses commandements, est un menteur, et la vérité n\'est point en lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'mais celui qui garde sa Parole est véritablement celui en qui l\'amour de Dieu est parfait: c\'est par là que nous connaissons que nous sommes en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Celui qui dit demeurer en lui, doit, lui aussi, marcher comme Jésus a marché lui-même.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Mes bien-aimés, ce n\'est pas un commandement nouveau que je vous écris, c\'est un commandement ancien, que vous avez reçu dès le commencement; ce commandement ancien, c\'est la parole que vous avez entendue.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'D\'un autre côté, c\'est bien un commandement nouveau que je vous écris, véritablement nouveau en Jésus et en vous, car les ténèbres se dissipent et la véritable lumière luit déjà:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'celui qui dit être dans la lumière, et qui hait son frère, est encore dans les ténèbres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Celui qui aime son frère, demeure dans la lumière, et il n\'y a point en lui de sujet de chute;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'mais celui qui hait son frère est dans les ténèbres. il marche dans les ténèbres et il ne sait où il va, parce que les ténèbres ont obscurci ses yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Chers enfants, je vous écris, parce que vos péchés vous sont pardonnés à cause de son nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pères, je vous écris, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous écris, parce que vous avez vaincu le malin. — Mes petits enfants, je vous ai écrit, parce que vous avez connu le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pères, je vous ai écrit, parce que vous avez connu celui qui est dès le commencement. Jeunes gens, je vous ai écrit, parce que vous êtes forts, et que la parole de Dieu demeure en vous, et que vous avez vaincu le malin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'N\'aimez point le monde, ni ce qui est dans le monde; si quelqu\'un aime le monde, l\'amour du Père n\'est point en lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'car tout ce qui est dans le monde, la convoitise de la chair, la convoitise des yeux et l\'orgueil de la vie, ne vient pas du Père, mais vient du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Le monde passe, et sa convoitise passe avec lui, mais celui qui fait la volonté de Dieu demeure éternellement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Mes petits enfants, c\'est la dernière heure. Comme vous avez appris qu\'un antechrist doit venir, aussi y a-t-il maintenant un grand nombre d’antechrists; par là, nous connaissons que c\'est la dernière heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ils sont sortis du milieu de nous, mais ils n\'étaient pas des nôtres, car s\'ils eussent été des nôtres, ils seraient demeurés avec nous; mais ils en sont sortis, afin qu\'il parût que tous ne sont pas des nôtres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Pour vous, c\'est de celui qui est saint que vous avez reçu l\'onction, en sorte que vous savez toutes choses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Je vous ai écrit, non que vous ne connaissiez pas la vérité, mais parce que vous la connaissez, et que vous savez que nul mensonge ne provient de la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Qui est le menteur, sinon celui qui nie que Jésus est le Christ? Celui-là est l\'antechrist, qui nie le Père et le Fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Quiconque nie le Fils, n\'a pas le Père; celui qui confesse le Fils, a aussi le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Pour vous, que ce que vous avez entendu dès le commencement, demeure en vous: si ce que vous avez entendu dès le commencement demeure en vous, vous aussi vous demeurerez dans le Fils et dans le Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Et la promesse que lui-même nous a faite, c\'est la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Je vous ai écrit ces choses relativement à ceux qui vous égarent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Pour vous, l\'onction que vous avez reçue de lui, demeure en vous, en sorte que vous n\'avez pas besoin que personne vous enseigne; mais comme son onction vous instruit de toutes choses (et cela est vrai, ce n\'est point un mensonge), demeurez en lui, selon qu\'elle vous a instruits.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Eh bien donc, chers enfants, demeurons en lui, afin que, s\'il vient à paraître, nous ayons de la confiance, et que nous ne soyons point confus, loin de lui, à son avènement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Si vous savez qu\'il est juste, reconnaissez que tout homme aussi qui pratique la justice est né de lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Voyez quel amour le Père nous a témoigné, que nous soyons appelés enfants de Dieu! Et nous le sommes. Si le monde ne nous connaît point, c\'est qu\'il ne l\'a point connu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Mes bien-aimés, nous sommes dès à présent enfants de Dieu, et ce que nous serons n\'a pas encore été manifesté, mais nous savons que, dès que ce que nous serons sera manifesté, nous lui serons semblables, parce que nous le verrons tel qu\'il est:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'quiconque a cette espérance en lui, se purifie, comme lui est pur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Quiconque commet le péché, viole la loi, et le péché, c\'est la violation de la loi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Or vous savez que Jésus a paru pour ôter les péchés, et que le péché n\'est point en lui:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'quiconque demeure en lui ne pèche point; quiconque pèche, ne l\'a point vu, et ne l\'a point connu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Chers enfants, que personne ne vous séduise: celui qui pratique la justice est juste, comme lui est juste;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'celui qui commet le péché, est issu du diable, car le diable pèche dès le commencement: c\'est pour détruire les oeuvres du diable, que le Fils de Dieu a paru.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Quiconque est né de Dieu ne commet pas de péché, parce que la semence de Dieu demeure en lui; et il ne peut pécher, parce qu\'il est né de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'C\'est à ceci que l\'on reconnaît les enfants de Dieu et les enfants du diable: quiconque ne pratique pas la justice, n\'est point issu de Dieu, non plus que celui qui n\'aime pas son frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'En effet, voici le message que vous avez entendu dès le commencement: c\'est que nous nous aimions les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Ne soyez pas comme Caïn: il était issu du malin, et il tua son frère. Et pourquoi le tua-t-il? Parce que ses oeuvres étaient mauvaises, au lieu que celles de son frère étaient justes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne soyez pas surpris, mes frères, si le monde vous hait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Pour nous, nous savons que nous sommes passés de la mort à la vie, parce que nous aimons nos frères: celui qui n\'aime pas, demeure dans la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Quiconque hait son frère est un meurtrier, et vous savez qu\'aucun meurtrier n\'a la vie éternelle demeurant en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Nous avons connu l\'amour à ceci, c\'est que Jésus a donné sa vie pour nous; nous aussi, nous devons donner notre vie pour nos frères;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'mais, si quelqu\'un possède les biens de ce monde, et que, voyant son frère dans le besoin, il lui ferme ses entrailles, comment l\'amour de Dieu demeure-t-il en lui?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Chers enfants, n\'aimons pas en paroles et de la langue, mais en actions et véritablement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'nous connaîtrons par là que nous sommes issus de la vérité, et nous rassurerons nos coeurs devant Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'parce que, si notre coeur nous condamne, Dieu est plus grand que notre coeur; il connaît tout.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mes bien-aimés, si notre coeur ne nous condamne point, nous pouvons nous adresser à Dieu avec assurance,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'et, quoi que nous demandions, nous le recevons de lui, parce que nous gardons ses commandements, et que nous faisons ce qui est agréable à ses yeux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Voici son commandement, c\'est que nous croyions au nom de son Fils, Jésus-Christ, et que nous nous aimions les uns les autres, comme il nous l\'a commandé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Celui qui garde ses commandements, demeure en Dieu, et Dieu en lui; et nous connaissons que Dieu demeure en nous à l\'esprit qu\'il nous a donné.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mes bien-aimés, ne vous fiez pas à tout esprit, mais éprouvez les esprits, pour voir s\'ils viennent de Dieu, car beaucoup de faux prophètes ont paru dans le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Vous reconnaîtrez l\'Esprit de Dieu à ceci: tout esprit qui confesse Jésus-Christ venu en chair, vient de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'mais tout esprit qui ne confesse pas ce Jésus, ne vient pas de Dieu: c\'est là l\'esprit de l\'antechrist, dont on vous avait annoncé la venue, et qui est déjà maintenant dans le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Chers enfants, vous êtes issus de Dieu, et vous les avez vaincus, ces faux prophètes, parce que celui qui est en vous est plus grand que celui qui est dans le monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Pour eux, ils sont du monde, aussi parlent-ils le langage du monde, et le monde les écoute;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'pour nous, nous sommes issus de Dieu; celui qui connaît Dieu nous écoute; celui qui n\'est pas issu de Dieu, ne nous écoute pas: nous connaissons par là l\'esprit de vérité et l\'esprit d\'erreur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Mes bien-aimés, aimons-nous les uns les autres; car l\'amour vient de Dieu: quiconque aime est né de Dieu, il connaît Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'celui qui n\'aime pas, n\'a point connu Dieu, car Dieu est amour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Il a manifesté son amour pour nous en envoyant son Fils unique dans le monde, afin que nous vivions par lui;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'et ce qui relève cet amour, c\'est que ce n\'est pas nous qui avons aimé Dieu, c\'est lui qui nous a aimés, et qui a envoyé son Fils comme victime de propitiation pour nos péchés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Mes bien-aimés, si Dieu nous a ainsi aimés, nous devons aussi nous aimer les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Personne n\'a jamais vu Dieu: si nous nous aimons les uns les autres, Dieu demeure en nous, et son amour est parfait en nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Nous reconnaissons que nous demeurons en lui, et qu\'il demeure en nous, à ceci, c\'est qu\'il nous a fait part de son Esprit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Pour nous, nous avons vu, et nous attestons que le Père a envoyé son Fils comme Sauveur du monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Si quelqu\'un confesse que Jésus est le Fils de Dieu, Dieu demeure en lui, et lui, en Dieu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'et nous avons connu l’amour que Dieu a pour nous, et nous y avons cru. Dieu est amour, et celui qui demeure dans l\'amour, demeure en Dieu, et Dieu demeure en lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Le caractère de la perfection de l\'amour en nous, c\'est que nous soyons pleins de confiance au jour du jugement, parce que tel est Dieu, tels nous sommes nous-mêmes dans ce monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Il n\'y a pas de crainte dans l\'amour, mais l\'amour parfait bannit la crainte, car la crainte suppose le châtiment: celui qui craint n\'est pas parfait dans l\'amour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Pour nous, nous aimons, parce que Dieu nous a aimés le premier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Si quelqu\'un dit, «j\'aime Dieu,» et qu\'il haïsse son frère, c\'est un menteur: comment celui qui n\'aime pas son frère qu\'il voit, peut-il aimer Dieu qu\'il n\'a pas vu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Et c\'est ici le commandement que nous tenons de lui: que celui qui aime Dieu, aime aussi son frère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Quiconque croit que Jésus est le Christ, est né de Dieu; et quiconque aime celui qui a engendré, aime aussi celui qui a été engendré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'C\'est à ceci que nous reconnaissons que nous aimons les enfants de Dieu: si nous aimons Dieu et si nous pratiquons ses commandements,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'car c\'est aimer Dieu que de garder ses commandements. Et ses commandements ne sont pas pénibles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'parce que tout ce qui est né de Dieu remporte la victoire sur le monde; et la puissance par laquelle le monde est vaincu, c\'est notre foi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Qui est celui qui est vainqueur du monde, sinon celui qui croit que Jésus est le Fils de Dieu?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ce Jésus est bien celui qui est venu en passant par l\'eau et par le sang, non par l\'eau seulement, mais par l\'eau et par le sang, Jésus le Christ; et l\'Esprit est celui qui l\'atteste, parce que l\'Esprit est la vérité:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'il y en a, en effet, trois qui rendent témoignage,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'l\'Esprit, l\'eau et le sang, et ces trois sont unanimes dans leur témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Si nous recevons le témoignage des hommes, le témoignage de Dieu est d\'un plus grand poids; et c\'est bien le témoignage de Dieu, puisqu\'il a rendu témoignage à son Fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Celui qui croit au Fils de Dieu, possède au dedans de lui ce témoignage: celui qui ne croit pas Dieu, le fait menteur, puisqu\'il n\'ajoute pas foi au témoignage que Dieu a rendu à son Fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Et voici ce témoignage, c\'est que Dieu nous a donné la vie éternelle, et que cette vie est dans son Fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Celui qui a le Fils a la vie; celui qui n\'a pas le Fils de Dieu, n\'a pas la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Je vous ai écrit ces choses, afin que vous sachiez que vous avez la vie éternelle, vous qui croyez au nom du Fils de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Et nous avons cette pleine confiance en Dieu, que, si nous demandons quelque chose selon sa volonté, il nous écoute;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'et dès que nous savons qu\'il nous écoute, quoi que nous lui demandions, nous savons que nous possédons les choses que nous lui avons demandées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Si quelqu\'un voit son frère commettre un péché qui n\'entraîne pas la mort, il priera, et il lui donnera la vie, à celui, dis-je, qui ne commet pas un péché qui entraîne la mort. Il y a tel péché qui entraîne la mort; je ne dis pas qu\'il prie pour ce péché-là.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toute injustice est un péché, et il y a tel péché qui n\'entraîne pas la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Nous savons que quiconque est né de Dieu, ne pèche point: celui qui est né de Dieu, se garde lui-même, et le malin ne le touche point.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Nous savons que nous sommes issus de Dieu, et que le monde entier est plongé dans le mal;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'mais nous savons que le Fils de Dieu est venu, et qu\'il nous a donné l\'intelligence, afin que nous connaissions le vrai Dieu; et nous sommes en ce vrai Dieu, étant en son Fils, Jésus-Christ: il est bien le vrai Dieu et la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Chers enfants, gardez-vous des idoles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Moi, l\'Ancien, à l\'élue Kyria et à ses enfants que j\'aime en la vérité, — et qui sont aimés non seulement de moi, mais encore de tous ceux qui ont connu la vérité, —');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'à cause de cette vérité qui demeure en nous, et qui sera éternellement avec nous:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'que la grâce, la miséricorde, la paix soient avec vous de la part de Dieu, le Père, et de Jésus-Christ, le Fils du Père, dans la vérité et dans la charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'J\'ai eu bien de la joie à rencontrer quelques-uns de tes enfants et à voir qu\'ils marchent dans la vérité, selon le commandement que nous avons reçu du Père.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Eh bien! je te le demande, Kyria, — et je ne pense pas t\'écrire là un commandement nouveau; c\'est le commandement que nous avons reçu dès le commencement, — aimons-nous les uns les autres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'L\'amour consiste à marcher selon le commandement de Dieu, et voici son commandement, comme vous l\'avez entendu dès le commencement, c\'est que nous marchions dans la charité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Car beaucoup de séducteurs ont paru dans le monde; ils ne confessent pas Jésus-Christ venu en chair: c\'est bien là le caractère du séducteur et de l\'antechrist.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Prenez garde à vous, afin que vous ne perdiez pas le fruit de nos travaux, mais que vous receviez une pleine récompense.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Quiconque va trop loin, et ne demeure pas dans la doctrine de Christ, n\'a point Dieu; celui qui demeure dans cette doctrine, a le Père et le Fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Si quelqu\'un vient vous visiter et n\'apporte pas cette doctrine, ne le recevez pas dans votre maison, et ne lui dites pas: «Sois le bienvenu!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'car celui qui lui dit, «sois le bienvenu!» participe à ses mauvaises oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Quoique j\'eusse beaucoup de choses à vous dire, je n\'ai pas voulu le faire avec le papier et l\'encre, mais j\'espère aller vous voir, et m\'entretenir de bouche avec vous, afin que votre joie soit parfaite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Les enfants de ta soeur, l\'élue, te saluent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Moi, l\'Ancien, à mon cher Caïus, que j\'aime en la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Mon cher, je souhaite qu\'à tous égards l\'état de tes affaires et celui de ta santé soient aussi prospères que celui de ton âme;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'car j\'ai eu bien de la joie de l\'arrivée des frères, parce qu\'ils ont rendu témoignage de la manière dont tu marches dans la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Je n\'ai pas de plus grand bonheur que d\'apprendre que mes enfants marchent dans la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Mon cher, tu te conduis fidèlement dans tout ce que tu fais pour les frères, et encore pour des frères étrangers:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'aussi ont-ils rendu témoignage de ta charité en présence de l\'église. Tu feras bien de pourvoir à leur voyage d\'une manière digne de Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'car c\'est pour le nom de Christ qu\'ils sont partis, et ils n\'acceptent rien des païens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'C\'est donc notre devoir, à nous, de soutenir de telles personnes, afin de travailler avec elles pour la vérité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'J\'ai écrit quelques mots à l\'église, mais Diotrèphe, qui aime à y primer, n\'a aucun égard pour nous.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'C\'est pourquoi, dès que je serai arrivé, je rappellerai les actes qu\'il commet, lui qui débite contre nous de méchants propos, et qui, non content de cela, non seulement ne reçoit pas les frères, mais encore empêche ceux qui les veulent recevoir, de le faire, et les chasse de l\'église.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Mon cher, n\'imite point le mal, mais imite le bien: celui qui fait le bien est issu de Dieu; celui qui fait le mal, n\'a point vu Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Tout le monde et la vérité elle-même, rendent un bon témoignage à Démétrius; nous le lui rendons aussi, et vous savez que notre témoignage est véritable.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'J\'aurais beaucoup de choses à te dire, mais je ne veux pas le faire avec l\'encre et la plume.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'J\'espère te voir prochainement, et alors nous nous entretiendrons de bouche. Que la paix soit avec toi! Nos amis te saluent. Salue nos amis, chacun en particulier.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Jude, serviteur de Jésus-Christ et frère de Jacques, à ceux qui ont été appelés, qui sont aimés de Dieu le Père, et gardés par Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'que la miséricorde, la paix et la charité vous soient données de plus en plus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Mes bien-aimés, j\'avais fort à coeur de vous écrire relativement à notre salut commun, et je me vois maintenant dans l\'obligation de le faire, afin de vous inviter à combattre pour la foi, qui a été, une fois pour toutes, enseignée aux saints.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Il s\'est glissé, en effet, parmi vous, certaines gens, dont la condamnation est écrite depuis longtemps, gens impies, qui se sont fait de la grâce de notre Dieu un motif de désordres, et qui renient notre seul Maître et Seigneur Jésus-Christ.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Je désire vous rappeler, bien que vous sachiez toutes choses sans qu\'il soit besoin d\'y revenir, que le Seigneur, après avoir sauvé le peuple de la terre d\'Egypte, fit périr ensuite ceux qui furent incrédules,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'et qu\'il a gardé pour le jugement du grand jour, éternellement enchaînés dans les ténèbres, les anges qui n\'ont pas conservé leur rang, et qui ont déserté leur propre séjour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'De même, Sodome et Gomorrhe, ainsi que les villes voisines, qui s\'étaient livrées, comme ces anges, au libertinage, et avaient recherché des unions contre nature, offrent une image du feu éternel dans la peine qu\'elles subissent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Malgré ces exemples, ces hommes aussi, dans leur délire, souillent pareillement leur chair, méprisent l\'autorité et injurient les Gloires.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'L\'archange Michel, au contraire, quand il contestait avec. le diable et lui disputait le corps de Moïse, n\'osa pas lancer contre lui une parole injurieuse, il lui dit seulement: «Que le Seigneur te punisse!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Pour eux, ils prodiguent l\'injure à tout ce qu\'ils ignorent, et, quant aux choses dont la nature leur donne la connaissance ainsi qu\'aux animaux privés de raison, ils se corrompent en s\'y plongeant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Malheur à eux! car ils ont pris le chemin de Caïn; ils se sont jetés, pour de l\'argent, dans l\'égarement de Balaam, et ils se sont perdus par la révolte de Coré.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ils sont un écueil dans vos agapes, où ils font bonne chère sans retenue et ne pensent qu\'à se gorger; nuées sans eau, que les vents emportent; arbres de fin d\'automne, sans fruits, deux fois morts, déracinés;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'vagues furieuses de la mer, jetant l\'écume de leurs propres impuretés; astres errants, auxquels l\'obscurité des ténèbres est réservée pour l\'éternité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'C\'est à eux aussi que s\'adresse la prophétie d\'Hénoch, le septième patriarche depuis Adam, quand il dit: «Voici que le Seigneur vient avec ses saintes myriades,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'pour juger tous les hommes et convaincre tous les impies d\'entre eux, de toutes les oeuvres d\'impiété qu\'ils ont commises et de toutes les paroles offensantes, qu\'eux, pécheurs impies, ont prononcées contre lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ce sont des gens qui ne font que murmurer, que se plaindre de leur sort, qui vivent au gré de leurs passions tout en ayant à la bouche de pompeuses paroles, et qui se font les admirateurs d’autrui par intérêt.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Pour vous, bien-aimés, souvenez-vous des paroles prophétiques des apôtres de notre Seigneur Jésus-Christ:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'ils vous disaient qu\'il y aurait au tout dernier temps des moqueurs vivant au gré de leurs passions, par suite de leurs principes impies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Vous reconnaissez là ceux qui poussent à la séparation, gent animale qui n\'a point d\'âme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mais vous, mes bien-aimés, élevant l\'édifice de votre piété sur votre foi très-sainte, et priant d\'un coeur saint,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'conservez-vous personnellement dans l\'amour de Dieu, attendant la miséricorde de notre Seigneur Jésus-Christ, pour avoir la vie éternelle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Puis, confondez les uns, s\'ils se séparent;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'sauvez les autres en les arrachant du feu; et, quant à ceux que vous ne pourrez sauver, ayez pitié d\'eux, avec crainte, en haïssant jusqu’à la tunique souillée par la chair.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Or, à celui qui peut vous préserver de tout faux pas et vous faire paraître devant sa gloire, irrépréhensibles et pleins d\'allégresse,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'au seul Dieu notre Sauveur, par Jésus-Christ notre Seigneur, soient gloire, majesté, force et puissance de toute éternité, maintenant et dans tous les siècles. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Révélation de Jésus-Christ. Dieu lui a fait cette révélation pour mettre sous les yeux de ses serviteurs les événements qui doivent bientôt arriver; et Jésus ayant envoyé son ange les annoncer à Jean, son serviteur,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'celui-ci a rapporté la parole de Dieu et le témoignage de Jésus, toutes choses dont il a eu la vision.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, '— Heureux celui qui lit, et ceux qui entendent les paroles de cette prophétie, et qui observent les recommandations qui y sont faites, car le moment est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jean aux sept églises d\'Asie: que la grâce et la paix vous soient données par Celui qui est, qui était et qui va venir, par les sept esprits qui sont devant son trône,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'et par Jésus-Christ, qui est le témoin fidèle, le premier-né d\'entre les morts et le prince des rois de la terre!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'A celui qui nous aime, qui nous a délivrés de nos péchés par son sang, et qui nous a faits rois et sacrificateurs de Dieu son Père, à lui soient la gloire et la force aux siècles des siècles! Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Le voici qui vient sur les nuées. Tout oeil le verra, et ceux même qui l\'ont percé; et toutes les tribus de la terre se frapperont la poitrine en le voyant. Oui. Amen!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Je suis l\'alpha et l\'oméga, dit le Seigneur Dieu, Celui qui est, qui était et qui va venir, le Tout-Puissant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Moi, Jean, qui suis votre frère, et qui ai part avec vous aux afflictions, à la royauté et à la patience en Jésus, j\'étais dans l\'île de Pathmos, pour la parole de Dieu et le témoignage de Jésus-Christ,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'lorsque je fus ravi en esprit le jour du Seigneur, et que j\'entendis derrière moi une voix éclatante, comme le son d\'une trompette,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'qui disait: «Ce que tu vois, écris-le dans un livre, et envoie ce livre aux sept églises, à Éphèse, à Smyrne, à Pergame, à Thyatire, à Sardes, à Philadelphie et à Laodicée.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Alors je me tournai pour découvrir quelle était la voix qui me parlait, et, quand je me fus tourné, je vis sept candélabres d\'or,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'et, au milieu des sept candélabres, un être semblable à un fils d\'homme: il était vêtu d\'une robe qui lui tombait jusqu\'aux pieds, et ceint, vers la poitrine, d\'une ceinture d\'or;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'sa tête et ses cheveux étaient blancs comme de la laine blanche, comme de la neige, et ses yeux étaient flamboyants comme du feu;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'ses pieds étaient semblables à de l\'airain qu\'on aurait chauffé à blanc dans un fourneau, et sa voix égalait le bruit des grosses eaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Il avait sept étoiles dans sa main droite, et de sa bouche sortait une épée aiguë, à deux tranchants, et son visage était comme le soleil, quand il brille dans sa force.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Quand je le vis, je tombai à ses pieds, comme mort. Il posa sa main droite sur moi, en disant: «Ne crains point; je suis le premier et le dernier; je suis le vivant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'j\'ai été mort, et voici, je suis vivant aux siècles des siècles; même je tiens les clefs de la mort et de l\'Hadès.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Mets donc par écrit les choses que tu viens de voir, soit celles qui sont actuellement, soit celles qui doivent arriver ensuite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Voici le mystère des sept étoiles que tu as vues dans ma main droite, et des sept candélabres d\'or: les sept étoiles sont les sept anges des sept églises, et les sept candélabres sont les sept églises.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '«Écris à l\'ange de l\'église d\'Éphèse: «Voici ce que dit celui qui tient les sept étoiles dans sa main droite, celui qui marche au milieu des sept candélabres d\'or:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, '«Je connais tes oeuvres, ton labeur et ta constance; je sais que tu ne peux souffrir les méchants; que tu as éprouvé ceux qui se disent apôtres et ne le sont point, et que tu les a trouvés menteurs;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'que tu as de la constance, car tu as eu à souffrir pour mon nom et tu ne t\'en es point lassé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mais j\'ai un reproche à te faire, c\'est que tu as abandonné ton premier amour.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Souviens-toi donc d\'où tu es tombé, repens-toi, et reviens à tes premières oeuvres, sinon je vais aller vers toi, et j\'ôterai ton candélabre de sa place, si tu ne te repens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Pourtant tu as une qualité, c\'est que tu hais les oeuvres des Nicolaïtes; moi aussi, je les hais.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, '— Que celui qui a des oreilles entende ce que l\'Esprit dit aux églises: «A celui qui vaincra, je lui donnerai à manger de l\'arbre de vie, qui est dans le paradis de mon Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '«Écris à l\'ange de l\'église de Smyrne: «Voici ce que dit celui qui est le premier et le dernier, qui a été mort et qui est revenu à la vie:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, '«Je connais tes oeuvres; je sais la persécution, la pauvreté (pourtant tu es riche) et les insultes que tu endures de la part de ceux qui se disent Juifs et ne le sont point, mais qui sont une synagogue de Satan.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Ne redoute pas les souffrances que tu vas éprouver. Voici, le diable va jeter en prison quelques-uns de vous, afin de vous mettre à l\'épreuve et de vous faire subir une persécution de dix jours. Sois fidèle jusqu’à la mort, et je te donnerai la couronne de vie.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, '— Que celui qui a des oreilles, entende ce que l\'Esprit dit aux églises: «Celui qui vaincra n\'aura point à souffrir la seconde mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, '«Ecris aussi à l’ange de l’église de Pergame: «Voici ce que dit celui qui a l\'épée aiguë, à deux tranchants:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, '«Je connais tes oeuvres et je sais où tu habites; c\'est là qu\'est le trône de Satan. Je sais que tu es fermement attachée mon nom, et que tu n\'as point renié ta foi, même au temps où Antipas, mon fidèle témoin, a été mis à mort chez vous, où Satan habite.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Mais j\'ai un reproche à te faire; c\'est que tu gardes là des gens qui retiennent les leçons de Balaam, celui qui enseignait à Balach à mettre une pierre d\'achoppement devant les fils d\'Israël, en les induisant à manger des viandes sacrifiées aux idoles et à se livrer au libertinage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'De même, tu gardes, toi aussi, des gens qui retiennent pareillement les principes des Nicolaïtes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Repens-toi donc, sinon je vais aller bientôt vers toi, et je leur ferai la guerre avec l\'épée de ma bouche.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux églises: «A celui qui vaincra, je lui donnerai de la manne cachée; je lui donnerai encore un caillou blanc; et sur ce caillou est écrit un nom nouveau, que nul ne connaît que celui qui le reçoit.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, '«Écris aussi à l\'ange de l\'église de Thyatire: «Voici ce que dit le Fils de Dieu, celui qui a des yeux flamboyants comme du feu, et dont les pieds sont semblables à de l\'airain:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, '«Je connais tes oeuvres, ton amour, ta foi, le soin que tu prends des pauvres, ta constance et tes dernières oeuvres plus nombreuses que les premières.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Mais j\'ai un reproche à t\'adresser, c\'est que tu laisses faire ta femme Jésabel, cette soi-disant prophétesse qui enseigne et qui séduit mes serviteurs, les entraînant à se livrer au libertinage et à manger des viandes sacrifiées aux idoles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Je lui ai donné du temps pour se repentir; néanmoins elle ne veut pas se repentir de son libertinage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Voici, je vais la jeter sur un lit de douleur, et plonger ses compagnons d\'adultère dans une grande détresse, à moins qu\'ils ne se repentent des oeuvres qu\'elle leur a enseignées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Je détruirai ses enfants par la mort, et toutes les églises connaîtront que je suis celui qui sonde les reins et les coeurs; et je rendrai à chacun selon ses oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Quant à vous autres qui ne partagez pas ces principes, qui n\'avez pas connu les profondeurs de Satan (comme ils les appellent), je vous dis: «Je ne vous impose, pas de nouvelle charge;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'seulement, tenez ferme ce que vous avez, jusqu’à ce que je vienne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, '— «Et à celui qui vaincra et qui aura accompli jusqu’à la fin les oeuvres que je commande, je lui donnerai pouvoir sur les Gentils;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'et il les gouvernera avec une verge de fer, les brisant comme on brise des vases d\'argile, ainsi que j\'en ai moi-même reçu le pouvoir de mon Père;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'et je lui donnerai l\'étoile du matin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Que celui qui a des oreilles entende ce que l\'Esprit dit aux églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Écris aussi à l\'ange de l\'église de Sardes: «Voici ce que dit celui qui a les sept esprits de Dieu et les sept étoiles: «Je connais tes oeuvres: tu as le renom de vivre, pourtant tu es mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sois vigilant et affermis le reste qui s\'en va mourir; car je n\'ai pas trouvé tes oeuvres parfaites devant mon Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Souviens-toi donc de quelle manière tu as reçu et entendu la Parole; garde-la, et repens-toi. Si tu ne veilles pas, je viendrai comme un voleur, et tu ne sais point à quelle heure je viendrai te surprendre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Toutefois, tu as à Sardes quelques personnes qui n\'ont pas souillé leurs vêtements, eh bien! elles marcheront avec moi en vêtements blancs, parce qu\'elles en sont dignes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, '— «Celui qui vaincra, sera ainsi paré de vêtements blancs; je n\'effacerai point son nom du livre de vie, et je confesserai son nom devant mon Père et devant ses anges.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Que celui qui a des oreilles entende ce que l\'Esprit dit aux églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '«Écris aussi à l\'ange de l\'église de Philadelphie: «Voici ce que dit le Saint, le Vrai, celui qui a la clef de David, celui qui ouvre et personne ne ferme, qui ferme et personne n\'ouvre:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, '«Je connais tes oeuvres: voici, j\'ai ouvert devant toi une porte que personne ne peut fermer; je l\'ai fait parce que tu as peu de puissance, que tu as gardé ma parole et que tu n\'as pas renié mon nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Voici, je te donne quelques membres de la synagogue de Satan, quelques-uns de ceux qui se disent Juifs: ils ne le sont point, mais ils mentent. Je ferai en sorte qu\'ils viennent eux-mêmes, qu\'ils se prosternent à tes pieds et qu\'ils sachent que je t\'ai aimé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Parce que tu as gardé ma parole avec constance, moi aussi je te garderai de l\'heure de l’épreuve qui va venir sur le monde entier pour éprouver les habitants de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Je viendrai bientôt: tiens ferme ce que tu as, afin que personne ne te ravisse ta couronne.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, '— «Celui qui vaincra, je ferai de lui une colonne dans le sanctuaire de mon Dieu, et il n\'en sortira jamais; j\'écrirai aussi sur lui le nom de mon Dieu, et le nom de la ville de mon Dieu, de la nouvelle Jérusalem qui va descendre du ciel d\'auprès de mon Dieu, et mon nom nouveau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Que celui qui a des oreilles, entende ce que l\'Esprit dit aux églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, '«Écris aussi à l\'ange de l\'église de Laodicée: «Voici ce que dit l\'Amen, le témoin fidèle et véritable, le chef des créatures de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, '«Je connais tes oeuvres: tu n\'es ni froid ni bouillant. Plût à Dieu que tu fusses froid ou bouillant!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Ainsi, parce que tu es tiède, et que tu n\'es ni froid ni bouillant, je te vomirai de ma bouche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Tu dis: «Je suis riche, j\'ai acquis de grands biens; je n\'ai besoin de rien;» tu ne sais donc pas que tu es, toi, le malheureux, le misérable; que tu es pauvre, aveugle et nu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Je te conseille d\'acheter de moi de l\'or affiné au feu, afin que tu sois riche, — et des vêtements blancs pour te vêtir, pour ne pas laisser voir la honte de ta nudité, — et un collyre pour oindre tes yeux, afin que tu voies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Pour moi, je reprends et je châtie tous ceux que j\'aime; aie donc du zèle et repens-toi.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Voici, je me tiens à la porte et je frappe: si quelqu\'un entend ma voix et ouvre la porte, j\'entrerai chez lui, je souperai avec lui et lui avec moi.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, '— «Celui qui vaincra, je le ferai asseoir avec moi sur mon trône, comme moi-même, j\'ai vaincu et je me suis assis avec mon Père sur son trône.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Que celui qui a des oreilles entende ce que l\'Esprit dit aux églises.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Après cela, je regardai, et voici, une porte était ouverte dans le ciel, et la première voix que j\'avais entendue, comme le son d\'une trompette, et qui m\'avait parlé, disait: «Monte ici, je te ferai voir ce qui doit arriver dans la suite.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, '— Aussitôt je fus ravi en esprit; et voici, un trône était dressé dans le ciel, et sur ce trône, quelqu\'un était assis.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Celui qui était assis, avait l\'aspect d\'une pierre de jaspe et de cornaline; et le trône était environné d\'un arc-en-ciel de la couleur de l\'émeraude.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Tout autour du trône étaient vingt-quatre trônes, et je vis des vieillards assis sur ces vingt-quatre trônes: ils étaient vêtus de blanc, et avaient des couronnes d\'or sur la tête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Du trône sortent des éclairs, des bruits et des tonnerres; et sept lampes ardentes brûlent devant le trône: ce sont les sept esprits de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Devant le trône, s\'étend comme une mer de verre semblable à du cristal; et au milieu de chacun des quatre côtés du trône se tient un animal couvert d\'yeux devant et derrière:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'le premier animal ressemble à un lion, le second ressemble à un jeune taureau, le troisième a la face comme celle d\'un homme, et le quatrième animal ressemble à un aigle qui vole.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Ces quatre animaux ont chacun six ailes; ils sont couverts d\'yeux tout autour du corps et sous les ailes, et ils ne cessent jour et nuit de dire: «Saint, saint, saint est le Seigneur Dieu, le Tout Puissant, Celui qui était, qui est et qui va venir!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Et toutes les fois que les animaux rendent gloire, honneur et actions de grâces à celui qui est assis sur le trône, à celui qui vit aux siècles des siècles,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'les vingt-quatre vieillards se prosternent devant celui qui est assis sur le trône, et adorent celui qui vit aux siècles des siècles, et ils jettent leurs couronnes devant le trône, en disant:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '«Tu es digne, notre Seigneur et notre Dieu, de recevoir la gloire, l\'honneur et la puissance, car c\'est toi qui as créé toutes choses, c\'est par ta volonté qu\'elles ont eu l\'être, qu\'elles ont été créées.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Puis je vis dans la main droite de celui qui était assis sur le trône un rouleau écrit en dedans et en dehors, scellé de sept sceaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Ensuite je vis un ange vigoureux, qui criait d\'une voix forte: «Qui est-ce qui est digne d\'ouvrir le livre et d\'en rompre les sceaux?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Et personne, ni dans le ciel, ni sur la terre, ni sous la terre, ne pouvait ouvrir le livre ni voir ce qu\'il contenait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Pour moi, je me mis à fondre en larmes, de ce qu\'il ne se trouvait personne qui fût digne d\'ouvrir le livre, ni de voir ce qu\'il contenait.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Alors un des vieillards me dit: «Ne pleure point; voici, il a vaincu, le lion de la tribu de Juda, le rejeton de David, c\'est lui qui va ouvrir le livre et briser les sept sceaux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Et je vis, debout près du trône, entre les quatre animaux et les vieillards, un agneau qu\'on aurait dit avoir été immolé: il avait sept cornes et sept yeux qui sont les sept esprits de Dieu envoyés par toute la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Il s\'avança, et prit le livre de la main droite de celui qui était assis sur le trône;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'et quand il eut pris le livre, les quatre animaux et les vingt-quatre vieillards se prosternèrent devant l\'agneau. Ils avaient tous des harpes, et des coupes d\'or pleines de parfums, qui sont les prières des saints;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'et ils chantaient un cantique nouveau, disant: «Tu es digne de prendre le livre et d\'en briser les sceaux, car tu as été immolé; et, par ton sang, tu as acheté pour Dieu des gens de toute tribu, de toute langue, de tout peuple et de toute nation;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'et tu les as faits rois et sacrificateurs, et ils vont régner sur la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Et je vis, et j\'entendis tout autour du trône, autour des animaux et des vieillards, la voix d\'une multitude d\'anges: le nombre de ces anges s\'élevait à des myriades de myriades et des milliers de milliers,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'et ils disaient d\'une voix forte: «L\'agneau qui a été immolé, est digne de recevoir la puissance, la richesse, la sagesse, la force, l\'honneur, la gloire et la louange.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Et j\'entendis toutes les créatures, dans le ciel, sur la terre, sous la terre, sur la mer, et les choses qui y sont, je les entendis toutes, qui disaient: «A celui qui est assis sur le trône et à l\'agneau, soient la louange, l\'honneur, la gloire et la force aux siècles des siècles!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Et les quatre animaux disaient: «Amen!» Et les vieillards se prosternèrent et adorèrent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Quand l\'agneau eut brisé l\'un des sept sceaux, j\'entendis l\'un des quatre animaux, qui disait comme d\'une voix de tonnerre: «Viens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Et je vis paraître un cheval blanc. Celui qui le montait avait un arc, on lui donna une couronne, et il partit en vainqueur pour aller remporter la victoire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Quand l\'agneau eut brisé le deuxième sceau, j\'entendis le second animal qui disait: «Viens,»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Et il sortit un autre cheval, qui était rouge. Celui qui le montait, reçut le pouvoir d\'ôter la paix de dessus la terre, afin que ses habitants s’entr’égorgeassent; et on lui donna une grande épée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Quand l\'agneau eut brisé le troisième sceau, j\'entendis le troisième animal qui disait: «Viens.» Et je vis paraître un cheval noir. Celui qui le montait tenait une balance à la main;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'et j\'entendis au milieu des quatre animaux, comme une voix qui disait: «A un denier le chénice de froment! A un denier les trois chénices d\'orge!» — et: «Ne gâte pas l\'huile, ni le vin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Quand l\'agneau eut brisé le quatrième sceau, j\'entendis la voix du quatrième animal qui disait: «Viens.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Et je vis paraître un cheval de couleur pâle. Celui qui le montait se nommait la Mort, l\'Hadès le suivait. On leur donna le pouvoir sur le quart de la terre, pour en faire périr les habitants par l’épée, par la famine, par la mortalité et par les bêtes féroces.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Quand l\'agneau eut brisé le cinquième sceau, je vis sous l\'autel les âmes de ceux qui avaient été immolés pour avoir gardé la parole de Dieu et le témoignage de Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Et elles crièrent d\'une voix forte: «Maître, toi qui es saint et véritable, jusques à quand différeras-tu de faire justice et de demander compte de notre sang à ceux qui habitent sur la terre?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Alors on leur donna à chacun une robe blanche, et on leur dit de demeurer en repos encore un peu de temps, jusqu’à ce que fût complet le nombre de leurs compagnons de service et de leurs frères, qui devaient être mis à mort comme eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Quand l\'agneau eut brisé le sixième sceau, je regardai, et il se fit un grand tremblement de terre: le soleil devint noir comme un sac de crin, la lune tout entière parut comme du sang,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'et les étoiles du ciel tombèrent sur la terre, comme les figues vertes tombent d\'un figuier secoué par un gros vent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Le ciel se retira comme un parchemin qu\'on enroule, et toutes les montagnes et les îles furent remuées de leur place.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Et les rois de la terre, les grands, les généraux, les riches, les hommes forts, tout esclave et tout homme libre se cachèrent dans les cavernes et dans les rochers des montagnes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'et ils disaient aux montagnes et aux rochers: «Tombez sur nous et dérobez-nous à la vue de celui qui est assis sur le trône, et à la colère de l\'agneau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'car il est venu, le grand jour de sa colère, et qui peut subsister?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Ensuite je vis quatre anges qui étaient debout aux quatre coins de la terre et qui retenaient les quatre vents de la terre, afin qu\'aucun vent ne soufflât, ni sur la terre, ni sur la mer, ni sur aucun arbre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Et je vis un autre ange qui montait du côté où se lève le soleil; il tenait le sceau du Dieu vivant, et il cria d\'une voix forte aux quatre anges à qui il avait été donné de sévir contre la terre et contre la mer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'disant: «Ne sévissez pas encore contre la terre, ni contre la mer, ni contre les arbres, jusqu’à ce que nous ayons marqué au front les serviteurs de notre Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Et j\'entendis que le nombre de ceux qui avaient été marqués, était de cent quarante-quatre mille, choisis dans toutes les tribus des fils d\'Israël:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'dans la tribu de Juda douze mille de marqués; dans la tribu de Ruben, douze mille; dans la tribu de Gad, douze mille;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'dans la tribu d\'Asser, douze mille; dans la tribu de Nephthali, douze mille; dans la tribu de Manassé, douze mille;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'dans la tribu de Syméon, douze mille; dans la tribu de Lévi, douze mille; dans la tribu d\'Issachar, douze mille;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'dans la tribu de Zabulon, douze mille; dans la tribu de Joseph, douze mille; dans la tribu de Benjamin douze mille de marqués.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Ensuite je vis une foule immense, que personne n\'aurait pu compter, composée de gens de toute nation, de toute tribu, de tout peuple et de toute langue, qui étaient debout devant le trône et devant l\'agneau: ils étaient vêtus de robes blanches, et tenaient des palmes dans leurs mains,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'ils criaient d\'une voix forte, disant: «Le salut vient de notre Dieu qui est assis sur le trône, et de l\'agneau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Tous les anges étaient debout autour du trône, autour des vieillards et des quatre animaux; ils se prosternèrent devant le trône et adorèrent Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'disant: «Amen! Louange, gloire, sagesse, actions de grâces, honneur, puissance, et force à notre Dieu, aux siècles des siècles!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Alors un des vieillards prenant la parole, me dit: «Ceux qui sont vêtus de robes blanches, qui sont-ils et d\'où viennent-ils?');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Je lui dis: «Mon Seigneur, tu le sais.» Et il me dit: «Ce sont ceux qui viennent de la grande tribulation; ils ont lavé leurs robes et les ont blanchies dans le sang de l\'agneau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'C\'est pour cela qu\'ils sont devant le trône de Dieu, et qu\'ils servent Dieu jour et nuit dans son sanctuaire. Et celui qui est assis sur le trône les abritera:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'ils n\'auront plus faim, ils n\'auront plus soif; le soleil ni aucune chaleur brûlante ne les accablera;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'car l\'agneau qui est là au milieu, devant le trône, les paîtra, et les conduira aux sources des eaux de la vie; et Dieu essuiera toute larme de leurs yeux.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Lorsqu\'il eut brisé le septième sceau, il se fit dans le ciel un silence d\'environ une demi-heure.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Et je vis les sept anges qui se tiennent en la présence de Dieu, et on leur donna sept trompettes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Puis il vint un autre ange qui se tint debout sur l\'autel, un encensoir d\'or à la main: on lui donna une quantité de parfums, afin qu\'il les mêlât aux prières de tous les saints, sur l\'autel d\'or qui est devant le trône;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'et la fumée des parfums, mêlée aux prières des saints, monta de la main de l\'ange devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Et l\'ange prit l\'encensoir, le remplit du feu de l\'autel et jeta ce feu sur la terre, et il y eut des bruits, des tonnerres, des éclairs, et la terre trembla.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Et les sept anges qui avaient les sept trompettes, se préparèrent à en sonner.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Le premier sonna de la trompette, et il y eut de la grêle et du feu, mêlés de sang, qui furent jetés sur la terre. Et le tiers de la terre, ainsi que le tiers des arbres, et toute l\'herbe verte furent consumés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Le second ange sonna de la trompette, et une masse semblable à une grosse montagne ardente fut jetée dans la mer. Et le tiers de la mer fut changé en sang,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'et le tiers des créatures marines qui ont vie, périt, et le tiers des navires fut détruit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Le troisième ange sonna de la trompette, et une grosse étoile enflammée comme une torche, tomba du ciel sur le tiers des fleuves et sur les sources des eaux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Le nom de cette étoile est Absinthe. Et le tiers des eaux fut changé en absinthe, et une multitude d\'hommes moururent de ces eaux, parce qu\'elles avaient été rendues amères.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Le quatrième ange sonna de la trompette, et le tiers du soleil fut frappé, ainsi que le tiers de la lune et le tiers des étoiles, afin que le tiers de chacun d\'eux fut rendu obscur et que la clarté du jour fût réduite d\'un tiers, et celle de la nuit pareillement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Et je regardai, et j\'entendis un aigle qui volait dans le haut des airs, disant d\'une voix forte: Malheur! Malheur! Malheur à ceux qui habitent sur la terre, à cause du son des trompettes, dont les trois autres anges vont sonner!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Et le cinquième ange sonna de la trompette, et je vis une étoile qui était tombée du ciel sur la terre, et on lui donna la clef du puits de l\'abîme.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Elle ouvrit le puits de l\'abîme, et il s\'éleva du puits une fumée comme celle d\'un grand fourneau, et le soleil et l\'atmosphère furent obscurcis par la fumée du puits;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'de cette fumée, il sortit des sauterelles qui se répandirent sur la terre: on leur donna un pouvoir pareil à celui des scorpions de la terre,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'et on leur commanda de ne point faire de mal à l\'herbe de la terre, ni à la verdure, ni à aucun arbre, mais seulement aux hommes qui n\'ont pas le sceau de Dieu sur le front.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Il leur fut donné, non de les tuer, mais de les tourmenter durant cinq mois; et le tourment qu\'elles faisaient éprouver était pareil à celui que cause à un homme la piqûre du scorpion.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'En ces jours-là, les hommes chercheront la mort, et ils ne la trouveront pas; ils souhaiteront de mourir, et la mort fuira loin d\'eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Ces sauterelles ressemblaient à des chevaux caparaçonnés pour le combat: elles avaient sur la tête comme des diadèmes d\'or, leurs visages étaient comme des visages d\'hommes,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'leurs cheveux comme des cheveux de femmes, et leurs dents comme des dents de lions.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Elles avaient des poitrines comme des cuirasses de fer, et le bruit de leurs ailes était comme un bruit de chariots à plusieurs chevaux qui courent au combat.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Elles ont des queues semblables à celles des scorpions, et des aiguillons; c\'est dans leurs queues qu\'est leur pouvoir de faire aux hommes un mal qui dure cinq mois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Elles ont à leur tête, comme roi, l\'ange de l\'abîme, qui se nomme en hébreu, Abaddon, et en grec, Apollyon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Ce premier «malheur!» est passé; en voici venir encore deux autres après lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Le sixième ange sonna de la trompette, et j\'entendis une voix sortir des cornes de l\'autel d\'or qui est devant Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Elle disait au sixième ange qui avait la trompette: «Délie les quatre anges qui sont liés au bord du grand fleuve de l’Euphrate.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Alors furent déliés les quatre anges qui s\'étaient tenus prêts pour l\'heure, le jour, le mois et l\'année, où ils devaient tuer le tiers des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Les corps de cavalerie de ces anges s\'élevaient à deux cents millions de cavaliers: j\'en entendis articuler le nombre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Et voici comment les chevaux me parurent dans la vision, ainsi que ceux qui les montaient: les cavaliers avaient des cuirasses couleur de feu, d\'hyacinthe et de soufre; les têtes des chevaux étaient comme des têtes de lions et leur bouche jetait du feu, de la fumée et du soufre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Le tiers des hommes fut tué par ces trois fléaux, par le feu, par la fumée, et par le soufre qui sortaient de la bouche des chevaux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'car la puissance de ces chevaux est dans leur bouche et dans leur queue: ces queues, semblables à des serpents, ont des têtes, et c\'est avec ces queues qu\'ils blessent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Les autres hommes qui ne furent pas tués par ces fléaux, ne se repentirent point des oeuvres de leurs mains: ils ne cessèrent pas d\'adorer les démons, ni les idoles d\'or, d\'argent, d\'airain, de pierre, de bois, qui ne peuvent ni voir, ni entendre, ni marcher;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'ils ne se repentirent ni de leurs meurtres, ni de leurs enchantements, ni de leurs débauches, ni de leurs vols.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Je vis un autre ange vigoureux, qui descendait du ciel, enveloppé d\'un nuage; l\'arc-en-ciel brillait au-dessus de sa tête; son visage était comme le soleil, et ses pieds étaient comme des colonnes de feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Il tenait à la main un petit livre ouvert; il posa le pied droit sur la mer et le pied gauche sur la terre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'puis il poussa un cri d\'une voix forte, comme un lion qui rugit, et, quand il eut poussé ce cri, les sept tonnerres firent entendre leurs voix.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Après que les tonnerres eurent parlé, je me disposais à écrire, lorsque j\'entendis une voix qui venait du ciel, et qui me disait: «Tiens secret ce qu\'ont dit les sept tonnerres, ne l\'écris point.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Alors l\'ange que j\'avais vu debout sur la mer et sur la terre, leva sa main droite vers le ciel,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'et jura par celui qui vit aux siècles des siècles, qui a créé le ciel et les choses qui y sont, la terre et les choses qui y sont, et la mer et les choses qui y sont, qu\'il n\'y aurait plus de délai,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'mais qu\'aux jours où le septième ange ferait entendre sa voix en sonnant de la trompette, le mystère de Dieu s\'accomplirait aussi, comme il l\'a annoncé à ses serviteurs, les prophètes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Et la voix que j\'avais entendue venant du ciel, me parla de nouveau, et me dit: «Va, prends le petit livre ouvert dans la main de l\'ange qui se tient debout sur la mer et sur la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'J\'allai donc vers l\'ange, et je lui demandai le petit livre, et il me dit: «Prends-le et l\'avale; il sera amer à tes entrailles, mais ta bouche le trouvera doux comme du miel.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Je pris le petit livre de la main de l\'ange, et je l\'avalai; il fut doux à ma bouche comme du miel, puis, quand je l\'eus avalé, je sentis de l\'amertume dans les entrailles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Et l’on me dit: «Il faut que tu prophétises de nouveau sur des peuples, des nations, des langues diverses et des rois en grand nombre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Alors on me donna un roseau semblable à un bâton, en me disant: «Lève-toi, et mesure le sanctuaire de Dieu, l\'autel, et l\'espace occupé par les adorateurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Quant au parvis extérieur du sanctuaire, laisse-le en dehors, ne le mesure pas, car il a été abandonné aux nations: elles fouleront aux pieds la ville sainte pendant quarante-deux mois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Et je donnerai à mes deux témoins de prophétiser, et, revêtus de sacs, ils prophétiseront pendant douze cent soixante jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ces deux témoins sont les deux oliviers et les deux candélabres qui sont devant le Seigneur de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Si quelqu\'un veut leur faire du mal, il sort de leur bouche un feu qui dévore leurs ennemis: c\'est ainsi que doit périr quiconque voudra leur faire du mal.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ils ont le pouvoir de fermer le ciel, afin qu\'il ne tombe point de pluie pendant les jours de leur prédication. Ils ont aussi le pouvoir de changer les eaux en sang, et de frapper la terre de toutes sortes de plaies, aussi souvent qu\'ils le voudront.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Quand ils auront achevé de rendre leur témoignage, la bête qui monte de l’abîme leur fera la guerre, les vaincra et les tuera;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'et leurs cadavres resteront gisant dans la rue de la grande ville qui est appelée figurément Sodome et Egypte; c\'est là que leur Seigneur même a été crucifié.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Des gens de tout peuple, de toute tribu, de toute langue et de toute nation regardent leurs cadavres pendant trois jours et demi, sans permettre qu\'on leur donne la sépulture.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Les habitants de la terre sont dans la joie de ce qui est arrivé aux prophètes; ils se livrent à l\'allégresse et s\'envoient des présents les uns aux autres, parce que ces deux prophètes ont fait le tourment de ceux qui habitent sur la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Au bout de trois jours et demi, un esprit de vie venant de Dieu, pénètre dans ces cadavres; ils se dressent sur leurs pieds; et une grande terreur s\'empare de ceux qui les regardaient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Et j\'entendis une voix forte qui venait du ciel, et qui disait aux prophètes: «Montez ici.» Et ils montèrent au ciel dans la nuée, et leurs ennemis les virent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'En ce même moment, il se fit un grand tremblement de terre; la dixième partie de la ville s\'écroula, et sept mille personnes périrent dans ce tremblement de terre; toutes les autres, saisies d\'effroi, rendirent gloire au Dieu du ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Le second «malheur!» est passé; voici venir bientôt le troisième.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Le septième ange sonna de la trompette, et des voix fortes se firent entendre dans le ciel, et elles disaient: «L\'empire du monde appartient maintenant à notre Seigneur et à son Oint, et il régnera aux siècles des siècles.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Et les vingt-quatre vieillards, qui sont assis devant Dieu sur leurs trônes, se prosternèrent et adorèrent Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'en disant: «Nous te rendons grâces, Seigneur Dieu, Tout-Puissant, toi qui es et qui étais, de ce que tu t\'es armé de ta grande puissance et de ce que tu es entré dans ton règne.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Les nations se sont irritées, et ta colère est venue. Et il est venu, le moment de juger les morts, de donner la récompense à tes serviteurs, aux prophètes, aux saints, à ceux qui craignent ton nom, petits et grands, et de perdre ceux qui perdent la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Alors le sanctuaire de Dieu, qui est dans le ciel, s\'ouvrit, et l’on vit l\'arche de l\'alliance dans son sanctuaire. Et il y eut des éclairs, des bruits, des tonnerres, un tremblement de terre et une forte grêle.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Et il parut dans le ciel un grand prodige, une femme enveloppée de la lumière du soleil, ayant la lune sous ses pieds, et sur sa tête une couronne de douze étoiles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Elle était enceinte, et elle criait, parce qu\'elle était dans le travail et les douleurs de l\'enfantement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Un autre prodige parut aussi dans le ciel: tout à coup on vit un grand dragon rouge; il avait sept têtes et dix cornes, et sur ses têtes sept diadèmes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'de sa queue, il entraînait le tiers des étoiles du ciel, et il les jeta sur la terre; et il se dressa devant la femme qui allait enfanter, afin de dévorer son enfant, dès qu\'elle l\'aurait mis au monde.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'La femme donna le jour à un fils, un enfant mâle, qui devait gouverner toutes les nations avec une verge de fer. L\'enfant fut enlevé auprès de Dieu et vers son trône,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'et la femme s\'enfuit au désert, où Dieu lui avait préparé une retraite, afin qu\'elle y fût nourrie pendant douze cent soixante jours.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Alors il y eut un combat dans le ciel: Michel et ses anges s\'avancèrent pour combattre le dragon; et le dragon et ses anges combattirent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'mais ils ne purent vaincre, et la place même qu\'ils occupaient ne se retrouva plus dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Il fut précipité, le grand dragon, le serpent ancien, celui qui est appelé le diable et Satan, le séducteur de toute la terre, il fut précipité sur la terre, et ses anges avec lui.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Et j\'entendis dans le ciel une voix forte, qui disait: «Maintenant, le salut, la puissance et l\'empire appartiennent à notre Dieu, et l\'autorité, à son Oint; car il a été précipité, l\'accusateur de nos frères, celui qui les accusait jour et nuit devant notre Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Eux aussi l\'ont vaincu par le sang de l\'agneau et par la fermeté de leur témoignage, ayant renoncé à l\'amour de la vie, jusqu’à souffrir la mort.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'C\'est pourquoi, tressaillez de joie, cieux, et vous qui les habitez! Malheur à la terre et à la mer! parce que le diable est descendu vers vous, plein d\'une grande fureur, sachant qu\'il ne lui reste que peu de temps.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Lorsque le dragon se vit précipité sur la terre, il poursuivit la femme qui avait mis au monde l\'enfant mâle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'mais la femme reçut deux ailes de grand aigle, pour s\'envoler au désert, en sa retraite, où elle devait être nourrie pendant un temps, des temps et la moitié d\'un temps, loin de la vue du dragon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Alors le dragon lança de sa gueule, après la femme, de l\'eau comme un fleuve, pour l\'entraîner dans le fleuve;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'mais la terre vint au secours de la femme, elle s\'entr\'ouvrit, et engloutit le fleuve que le dragon avait vomi de sa gueule.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Et le dragon fut transporté de fureur contre la femme; il alla faire la guerre au reste de ses enfants, à ceux qui observent les commandements de Dieu et qui gardent le témoignage de Jésus; et il s\'arrêta sur le sable de la mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Je vis alors monter de la mer, une bête féroce qui avait dix cornes et sept têtes, et sur ses cornes, dix diadèmes, et sur ses têtes, un nom de blasphème.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'La bête que je vis, ressemblait à un léopard; ses pieds étaient comme ceux d\'un ours, et sa gueule comme une gueule de lion. Le dragon lui donna sa puissance, son trône et une grande autorité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'On aurait dit que l\'une de ses têtes avait été blessée à mort, mais sa blessure mortelle avait été guérie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Tous les habitants de la terre, saisis d\'admiration, suivaient la bête; ils adorèrent le dragon, parce qu\'il avait donné l\'autorité à la bête, et ils adorèrent la bête, en disant: «Qui est semblable à la bête, et qui peut se mesurer avec elle?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'On lui donna une bouche qui profère des paroles arrogantes et blasphématoires, et le pouvoir d\'agir pendant quarante-deux mois.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Elle ouvrit donc la bouche pour blasphémer contre Dieu, pour blasphémer son nom, son tabernacle, et ceux qui habitent dans le ciel.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Et on lui donna de faire la guerre aux saints et de les vaincre, ainsi que le pouvoir sur toute tribu, tout peuple, toute langue et toute nation:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'et tous les habitants de la terre l\'adoreront, ceux du moins dont le nom n\'a pas été écrit, dès la fondation du monde, dans le livre de vie de l\'agneau qui a été immolé.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Que celui qui a des oreilles entende.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Celui qui mène en captivité, sera mené lui-même en captivité; celui qui tue par l\'épée, doit être tué lui-même par l\'épée. C\'est ici que la patience et la foi des saints doivent se montrer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Je vis ensuite monter de la terre une autre bête féroce qui avait deux cornes semblables à celles d\'un agneau, et qui parlait comme un dragon.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Elle exerçait toute l\'autorité de la première bête, sous ses yeux, et elle amenait la terre et ses habitants à adorer la première bête, dont la blessure mortelle avait été guérie;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'elle opérait aussi de grands prodiges, jusqu’à faire descendre du ciel du feu sur la terre, à la vue des hommes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Séduisant les habitants de la terre par les prodiges qu\'il lui avait été donné d\'opérer sous les yeux de la bête, elle leur persuada de faire une image en l\'honneur de la bête qui porte la blessure du glaive, et qui a repris vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Et il lui fut donné d\'animer l\'image de la bête, afin que cette image parlât, et qu\'elle fît mettre à mort tous ceux qui n\'adoreraient pas l\'image de la bête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Elle amena tous les hommes, petits et grands, riches et pauvres, libres et esclaves, à s\'imprimer eux-mêmes une marque sur la main droite ou sur le front,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'afin que nul ne pût acheter ni vendre, s\'il n\'avait pas la marque, savoir le nom de la bête ou le nombre de son nom.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'C\'est ici que la sagesse doit se montrer. Que celui qui a de l\'intelligence, calcule le nombre de la bête, car c\'est le nombre d\'un homme, et son nombre est six cent soixante-six.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Puis je regardai, et voici, l\'agneau était sur la montagne de Sion, et avec lui cent quarante-quatre mille personnes, qui avaient son nom et le nom de son Père, écrits sur leurs fronts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Et j\'entendis une voix qui venait du ciel, forte comme le bruit des grosses eaux et comme celui d\'un puissant tonnerre, et harmonieuse comme le son des harpes jouées par des musiciens.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'On chantait un cantique nouveau devant le trône et devant les quatre animaux et les vieillards: nul ne pouvait apprendre ce cantique, que les cent quarante-quatre mille qui ont été achetés de la terre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ceux-ci ne se sont point souillés avec des femmes, car ils sont vierges ceux qui accompagnent l\'agneau partout où il va; ils ont été achetés d\'entre les hommes, comme des prémices consacrées à Dieu et à l\'agneau;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'et il ne s\'est point trouvé de mensonge dans leur bouche, car ils sont irréprochables.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Après cela, je vis un autre ange qui volait dans le haut des airs, tenant un évangile éternel, pour l\'annoncer à ceux qui sont sur la terre, à toute nation, à toute tribu, à toute langue et à tout peuple.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Il disait d\'une voix forte: «Craignez Dieu et lui donnez gloire, car l\'heure de son jugement est venue; adorez celui qui a fait le ciel, la terre, la mer et les sources d\'eau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Et un autre ange, un second, suivit, qui disait: «Elle est tombée, elle est tombée, Babylone la grande, celle qui a abreuvé toutes les nations du vin de la fureur de son libertinage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Et un autre ange, un troisième, les suivit, qui disait d\'une voix forte: «Si quelqu\'un adore la bête et son image, et en prend la marque sur son front ou sur sa main,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'il boira, lui aussi, du vin de la fureur de Dieu, du vin pur versé dans la coupe de sa colère; et il sera tourmenté dans le feu et le soufre sous les yeux des saints anges et de l\'agneau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'La fumée de son supplice s\'élèvera aux siècles des siècles; et il n\'y aura de repos, ni jour ni nuit, pour ceux qui adorent la bête et son image, ni pour quiconque aura pris la marque de son nom.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'C\'est ici que doit se montrer la patience des saints qui gardent les commandements de Dieu et la foi en Jésus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Alors j\'entendis une voix venant du ciel, qui disait: «Ecris: Heureux dès à présent ceux qui meurent dans le Seigneur!» — «Oui,» dit l\'Esprit, «ils se reposent de leurs travaux, et leurs oeuvres les suivent.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Puis je regardai, et voici, une nuée blanche parut, et sur la nuée était assis quelqu\'un qui ressemblait à un fils d\'homme; il avait sur la tête une couronne d\'or, et dans sa main une faucille tranchante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Et un autre ange sortit du sanctuaire, en criant d\'une voix forte à celui qui était assis sur la nuée: «Sers-toi de ta faucille et moissonne, car le moment de moissonner est venu, parce que la moisson de la terre est mûre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Alors celui qui était assis sur la nuée passa sa faucille sur la terre, et la terre fut moissonnée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Un autre ange sortit du sanctuaire qui est dans le ciel; il tenait, lui aussi, une serpette tranchante.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Et un autre ange, celui qui a pouvoir sur le feu, sortit de l\'autel, et s\'adressa d\'une voix forte à celui qui tenait la serpette tranchante, disant: «Sers-toi de ta serpette tranchante, et coupe les grappes de la vigne de la terre, car les raisins en sont mûrs.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Alors l\'ange passa sa serpette sur la terre, et il vendangea la vigne de la terre; puis il en jeta les grappes dans la grande cuve de la fureur de Dieu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'on foula la cuve hors de la ville, et il en sortit du sang jusqu’à la hauteur des mors des chevaux sur un espace de mille six cents stades.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Et je vis un autre prodige dans le ciel, un grand, un étonnant prodige, sept anges ayant en main les sept derniers fléaux, car c\'est par ces fléaux que doit se consommer le courroux de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Et je vis comme une mer de verre mêlée de feu, et au bord de cette mer de verre étaient debout les vainqueurs de la bête, de son image et du nombre de son nom, ayant en main les harpes sacrées.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Ils chantaient le cantique de Moïse, serviteur de Dieu, et le cantique de l\'agneau, disant: «Tes oeuvres sont grandes et admirables, Seigneur Dieu, Tout-Puissant! Tes voies sont justes et véritables, ô Roi des nations!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Qui ne craindrait, Seigneur, et ne glorifierait ton nom, car toi seul es Saint. Et toutes les nations viendront se prosterner devant toi, parce que tes jugements ont éclaté.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Après cela, je vis s\'ouvrir le sanctuaire qui est dans le ciel et qui renferme le tabernacle du témoignage.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Les sept anges qui ont en main les sept fléaux sortirent du sanctuaire; ils étaient vêtus d\'un lin pur et éclatant, et portaient des ceintures d\'or autour de la poitrine.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Alors l\'un des quatre animaux donna aux sept anges sept coupes d\'or pleines du courroux du Dieu qui vit aux siècles des siècles;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'et le sanctuaire fut rempli du parfum de la gloire de Dieu et de sa puissance; et nul ne pouvait entrer dans le sanctuaire, jusqu’à ce que les sept fléaux des sept anges eussent été consommés.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Alors j\'entendis une voix forte qui sortait du sanctuaire, et qui disait aux sept anges: «Allez, et versez sur la terre les sept coupes de la colère de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Le premier ange partit, et répandit sa coupe sur la terre: et un ulcère malin et douloureux frappa les hommes qui avaient la marque de la bête, et ceux qui en adoraient l\'image.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Le second ange répandit sa coupe dans la mer; et la mer devint comme le sang d\'un mort, et tout être vivant qui était dans la mer, mourut.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Le troisième répandit sa coupe dans les fleuves et dans les sources d\'eau; et les eaux furent changées en sang.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Alors j\'entendis l\'ange des eaux qui disait: «Tu es juste, ô toi qui es et qui étais; tu es saint, d\'avoir rendu ce jugement:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'ils ont versé le sang des saints et des prophètes, et tu leur as donné du sang à boire: ils en sont dignes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Et j\'entendis l\'autel qui disait: «Oui, Seigneur, Dieu tout-puissant, tes jugements sont véritables et justes.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Le quatrième répandit sa coupe sur le soleil, et il lui fut donné de brûler les hommes par le feu:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'et les hommes furent frappés d\'une chaleur brûlante, ils blasphémèrent le nom de Dieu qui dispose de ces fléaux, et ils ne se repentirent point pour lui rendre gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Le cinquième ange répandit sa coupe sur le trône de la bête; et le royaume de la bête fut plongé dans les ténèbres; les hommes se mordaient la langue de douleur;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'et ils blasphémèrent le Dieu du ciel, à cause de leurs tourments et de leurs ulcères; et ils ne se repentirent point de leurs oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Le sixième répandit sa coupe sur le grand fleuve de l\'Euphrate; et les eaux en furent desséchées, afin de livrer passage aux rois qui venaient de l\'Orient.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Et je vis sortir de la gueule du dragon, et de la gueule de la bête, et de la bouche du faux-prophète, trois esprits impurs semblables à des crapauds.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Ce sont, en effet, des esprits de démons, qui font des prodiges et qui vont rassembler les rois de l\'univers entier pour la bataille du grand jour du Dieu tout-puissant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(«Voici, je viens comme un voleur. Heureux celui qui veille et qui conserve ses vêtements, afin de ne pas aller nu et de ne pas laisser voir sa honte!»)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, '— Et ces esprits rassemblèrent les rois en un lieu nommé en hébreu, «Harmagédon.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Le septième ange répandit sa coupe sur l\'atmosphère; et il sortit du sanctuaire du ciel, du trône même, une voix forte qui disait: «C\'en est fait!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Et il y eut des éclairs, des bruits, des tonnerres; il se fit un tremblement de terre tel qu\'il n\'y en a jamais eu un semblable depuis qu\'il y a des hommes sur la terre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'la grande ville se partagea en trois, et les villes des nations croulèrent: et Dieu se souvint de Babylone la grande, pour lui faire boire la coupe pleine du vin de son ardente colère.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Toutes les îles disparurent, et l\'on ne retrouva plus de montagnes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Une forte grêle, dont les grêlons pouvaient peser un talent, tomba du ciel sur les hommes; et les hommes blasphémèrent Dieu à cause du fléau de la grêle, parce que ses dégâts étaient immenses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'L\'un des sept anges qui tenaient les sept coupes, vint, et me dit: «Viens, je te montrerai le jugement de la grande prostituée qui est assise sur les grandes eaux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'avec laquelle les rois de la terre se sont souillés, et qui a enivré les habitants de la terre du vin de son libertinage.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Et il m\'emmena en esprit dans un désert. Et je vis une femme assise sur une bête écarlate, couverte de noms de blasphème, et qui avait sept têtes et dix cornes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Cette femme était vêtue de pourpre et d\'écarlate, elle était couverte d\'or, de pierres précieuses et de perles; elle tenait à la main une coupe d\'or pleine d\'abominations et des souillures de son libertinage;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'sur son front était écrit un nom, nom mystérieux, «Babylone la grande, la mère des prostituées et des abominations de la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Je vis cette femme ivre du sang des saints et du sang des martyrs de Jésus, et sa vue me jeta dans un grand étonnement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Alors l\'ange me dit: «Pourquoi t\'étonnes-tu? Je te dirai, moi, le mystère de la femme et de la bête qui la porte, et qui a les sept têtes et les dix cornes.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'La bête que tu vois, était et elle n\'est plus; elle doit monter de l\'abîme et s\'en aller à sa perte. Et les habitants de la terre, dont le nom n\'est pas écrit dans le livre de vie, dès la fondation du monde, seront dans l\'étonnement, en voyant la bête, parce qu\'elle était et qu\'elle n\'est plus, et qu\'elle reparaîtra.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, '(C\'est ici que doit se montrer l\'esprit doué de sagesse.) «Les sept têtes sont sept montagnes sur lesquelles la femme est assise;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'ce sont aussi sept rois: les cinq premiers sont tombés, l\'un subsiste, l\'autre n\'est pas encore venu, et quand il sera venu, il ne doit demeurer que peu de temps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Et la bête qui était et qui n\'est plus, est elle-même un huitième roi et en même temps l’un des sept rois, et elle s\'en va à sa perte.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Les dix cornes que tu as vues, sont dix rois qui n\'ont pas encore reçu de royaumes, mais qui recevront un pouvoir de rois pour une heure, avec la bête.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ils n\'ont qu\'une seule et même pensée, et ils mettent au service de la bête leur puissance et leur autorité.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ils feront la guerre à l\'agneau; mais l\'agneau les vaincra, parce qu\'il est Seigneur des seigneurs et Roi des rois, et ceux qui l\'accompagnent, les appelés, les élus, les fidèles, les vaincront avec lui.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Et il me dit: «Les eaux que tu as vues, sur lesquelles la prostituée est assise, ce sont des peuples, des foules, des nations et des langues;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'et les dix cornes que tu as vues et la bête haïront elles-mêmes la prostituée; elles la rendront désolée et nue; elles mangeront ses chairs et la consumeront par le feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Car Dieu leur a mis au coeur d\'exécuter la pensée de la bête, une seule et même pensée, et de mettre leur royauté au service de la bête, jusqu’à ce que ses paroles à lui soient accomplies.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Quant à la femme que tu as vue, c\'est la grande ville qui possède l\'empire sur les rois de la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Après cela, je vis descendre du ciel un autre ange, qui avait un grand pouvoir; et la terre fut illuminée de sa gloire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Il cria d\'une voix puissante, disant: «Elle est tombée, elle est tombée, Babylone la grande! Elle est devenue une habitation de démons, un réceptacle de toutes sortes d\'esprits impurs et un repaire de toutes sortes d\'oiseaux immondes et odieux,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'parce que toutes les nations ont bu du vin de son libertinage furieux, que les rois de la terre se sont souillés avec elle et que les marchands de la terre se sont enrichis par l\'excès de son luxe.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Et j\'entendis une autre voix qui venait du ciel, et qui disait: «Sortez de cette ville, vous qui êtes mon peuple, afin de ne point participer à ses péchés, et de n\'être point enveloppés dans ses calamités,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'car ses péchés se sont accumulés jusqu\'au ciel, et Dieu s\'est souvenu de ses iniquités.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Faites-lui comme elle a fait elle-même, et rendez-lui au double selon ses oeuvres; faites-lui boire double dose dans le calice où elle vous a fait boire:');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'autant elle s\'est glorifiée et plongée dans le luxe, autant il faut lui donner de tourment et de deuil. Elle dit dans son coeur: «Je suis une reine sur son trône, je ne suis point veuve, et je ne connaîtrai point le deuil.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Eh bien! en un même jour, les calamités fondront sur elle, la mort, le deuil, la famine, et elle sera consumée par le feu, parce que Dieu qui l\'a jugée, est un puissant Seigneur.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Les rois de la terre, qui se sont plongés avec elle dans le libertinage et dans le luxe, pleurent et se lamentent sur son sort en voyant la fumée de son embrasement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Ils se tiennent à distance dans la crainte de partager ses tourments, et ils disent: «Malheur! Malheur! Toi, la grande ville, Babylone la puissante cité, en une seule heure est venu ton jugement!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Et les marchands de la terre la pleurent et se désolent, parce que personne n\'achète plus leur cargaison,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'une cargaison d\'or, d\'argent, de pierres précieuses, de perles, de fin lin, de pourpre, de soie et d\'écarlate, de bois de senteur de toute espèce, d\'objets d\'ivoire, de bois très précieux, d\'airain, de fer et de marbre, de toutes sortes;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'de cannelle, d\'essence, de parfums, de myrrhe, d\'encens, de vin, d\'huile, de fine farine, de blé, de bestiaux, de moutons, de chevaux, d\'équipages, de cochers et d\'esclaves.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Les fruits, dont tu faisais tes délices, s\'en sont allés loin de toi; toutes les choses exquises et magnifiques sont perdues pour toi; tu ne les retrouveras plus.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Ces marchands, qui se sont enrichis avec elle, se tiennent à distance, dans la crainte de partager ses tourments; ils pleurent et se désolent,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'disant: «Malheur! Malheur! Qu\'est devenue la grande ville, celle qui était vêtue de fin lin, de pourpre et d\'écarlate, et qui était couverte d\'or, de pierres précieuses et de perles? En une seule heure ont été détruites tant de richesses!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Et tous les pilotes, tous ceux qui naviguent à destination de la grande ville, les matelots et ceux qui exploitent la mer se tiennent à distance');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'et crient en voyant la fumée de son embrasement: «Quelle ville était semblable à la grande cité?»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Ils se jettent de la poussière sur la tête, et ils crient en pleurant et en se désolant: «Malheur! Malheur! La grande ville, dont l\'opulence a enrichi tous ceux qui avaient des vaisseaux sur mer, en une heure elle a été détruite!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Ciel, réjouis-toi de sa catastrophe; vous aussi, saints, apôtres, prophètes: en la jugeant, Dieu vous a fait justice..');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Alors un ange vigoureux prit une pierre aussi grosse qu\'une meule, et la jeta dans la mer, en disant: «Ainsi sera précipitée avec fracas Babylone la grande ville, et on ne la retrouvera plus.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'On n\'entendra plus chez toi les sons des joueurs de harpe, des musiciens, des joueurs de flûte ni des trompettes; on n\'y trouvera plus d\'artisan d\'aucun métier; on n\'y entendra plus le bruit de la meule;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'on n\'y verra plus briller la lumière de la lampe; on n\'y entendra plus la voix de l\'époux et de l\'épouse, parce que tes marchands étaient les grands de la terre, parce que toutes les nations ont été égarées par tes enchantements,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'et qu\'on a trouvé chez toi le sang des prophètes et des saints, et de tous ceux qui ont été égorgés sur la terre.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Après cela, j\'entendis dans le ciel comme la grande voix d\'une foule immense qui disait: «Alléluia! Le salut, la gloire et la puissance appartiennent à notre Dieu,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'parce que ses jugements sont véritables et justes. Il a jugé la grande prostituée qui a corrompu la terre par son libertinage, et il lui a demandé compte du sang de ses serviteurs, versé par sa main.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Et la voix dit une seconde fois: «Alléluia!» Et la fumée de la grande cité monte aux siècles des siècles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Et les vingt-quatre vieillards et les quatre animaux se prosternèrent et adorèrent Dieu, qui est assis sur le trône, et dirent: «Amen! Alléluia!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Et il sortit du trône une voix qui disait: «Louez notre Dieu, Vous tous ses serviteurs, qui le craignez, petits et grands.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Et j\'entendis une voix forte, comme celle d\'une foule immense, comme le bruit de grosses eaux, comme le bruit de violents tonnerres; elle disait: «Alléluia! car il règne, le Seigneur Dieu tout-puissant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Réjouissons -nous, tressaillons d\'allégresse et lui rendons gloire: les noces de l\'agneau sont venues, son épouse s\'est préparée,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'et il lui a été donné de se vêtir de lin fin, magnifique et pur.» (Ce fin lin, ce sont les vertus des saints.)');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Et l\'ange me dit: «Écris: Heureux ceux qui sont invités au repas des noces de l\'agneau!» Et il ajouta: «Ces paroles sont de véritables paroles de Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Je tombai à ses pieds pour l\'adorer, mais il me dit: «Garde-toi de le faire; je suis ton compagnon de service, et celui de tes frères qui gardent le témoignage de Jésus-Christ: adore Dieu.» — En effet, le témoignage de Jésus, c\'est l\'esprit de la prophétie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Alors je vis le ciel ouvert, et il parut un cheval blanc: celui qui le montait s\'appelle Fidèle et Véritable; il juge et combat avec justice.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Ses yeux sont une flamme ardente; il a sur la tête plusieurs diadèmes, et porte un nom écrit, que nul ne connaît que lui-même;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'il est vêtu d\'un manteau teint de sang; son nom est La Parole de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Les armées du ciel l\'accompagnent sur des chevaux blancs; les cavaliers sont vêtus de fin lin, blanc et pur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'De sa bouche sort une épée aiguë, pour frapper les nations; c\'est lui qui les gouvernera avec une verge de fer; c\'est lui qui foule la cuve du vin de l\'ardente colère du Dieu tout-puissant.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Sur son manteau et sur sa cuisse, il porte écrit ce nom, Roi des rois, et Seigneur des seigneurs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Et je vis un ange qui était debout dans le soleil, et qui cria d\'une voix forte à tous les oiseaux qui volaient dans le haut des airs: «Venez, rassemblez-vous pour le grand festin que Dieu vous donne,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'pour manger la chair des rois, la chair des généraux, la chair des hommes forts, la chair des chevaux et de ceux qui les montent, la chair de tous les hommes, libres et esclaves, petits et grands.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Et je vis la bête et les rois de la terre, avec leurs armées rassemblées pour livrer bataille à celui qui est monté sur le cheval blanc, et à son armée.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'La bête fut prise, ainsi que le faux-prophète qui l\'accompagnait, et qui, par ses prodiges faits devant elle, avait séduit ceux qui avaient pris la marque de la bête, et ceux qui en adoraient l\'image. Tous les deux furent jetés vivants dans l\'étang de feu où le soufre brûle;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'le reste fut tué par l\'épée qui sort de la bouche de celui qui est monté sur le cheval; et tous les oiseaux se rassasièrent de leurs chairs.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Et je vis descendre du ciel un ange qui tenait dans sa main la clef de l\'abîme et une grosse chaîne;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'il saisit le dragon, le serpent ancien, qui est le diable, Satan, et il l\'enchaîna pour mille ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Puis il le jeta dans l\'abîme, qu\'il ferma à clef et scella sur lui, afin qu\'il n\'égarât plus les nations, jusqu’à ce que les mille ans fussent écoulés. Après cela, il doit être relâché pour un peu de temps.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Et je vis des trônes: des personnes s\'assirent sur ces trônes, et le jugement leur fut remis. Je vis aussi les âmes de ceux qui avaient été décapités pour le témoignage de Jésus et pour la parole de Dieu, et celles de ceux qui n\'avaient point adoré la bête ni son image, et qui n\'en avaient point pris la marque sur le front, ni sur la main: ils revinrent à la vie, et régnèrent avec Christ pendant mille ans;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'mais le reste des morts ne revint point à la vie, jusqu’à ce que les mille ans fussent écoulés. C\'est la première résurrection.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Heureux et saints ceux qui ont part à la première résurrection! La seconde mort n\'a point de pouvoir sur eux; ils seront sacrificateurs de Dieu et de Christ, et régneront avec lui pendant mille ans.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Quand les mille ans seront écoulés, Satan sera relâché de sa prison,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'et il en sortira pour égarer les nations qui sont aux quatre extrémités de la terre, Gog et Magog, afin de les rassembler pour le combat. Nombreuses comme le sable de la mer,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'elles se répandront sur l\'étendue de la terre, elles cerneront le camp des saints et la ville bien-aimée, mais un feu tombera du ciel et les dévorera.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Le diable, qui les égarait, sera jeté dans l\'étang de feu et de soufre, où sont plongés la bête et le faux-prophète; et ils seront tourmentés jour et nuit aux siècles des siècles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Je vis un grand trône blanc et celui qui était assis dessus: le ciel et la terre s\'enfuirent de devant sa face, de sorte qu\'il n\'y eut plus de place pour eux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Je vis les morts, grands et petits, debout devant le trône: des livres furent ouverts; on ouvrit encore un autre livre, qui est le livre de vie; et les morts furent jugés selon leurs oeuvres, d\'après ce qui était consigné dans ces livres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'La mer rendit ses morts: la Mort et l’Hadès rendirent les leurs; et ces morts furent jugés, chacun selon ses oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Après quoi la Mort et l’Hadès furent jetés dans l\'étang de feu: c\'est la seconde mort, l’étang de feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Quiconque ne fut pas trouvé inscrit dans le livre de vie fut jeté dans l\'étang de feu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Alors je vis un nouveau ciel et une nouvelle terre, car le premier ciel et la première terre avaient disparu, et il n\'y avait plus de mer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Et je vis descendre du ciel, d\'auprès de Dieu, la ville sainte, une Jérusalem nouvelle, prête comme une épouse qui s\'est parée pour son époux.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Et j\'entendis une voix forte qui venait du ciel, et qui disait: «Voici le tabernacle de Dieu, qui va être dressé au milieu des hommes: il habitera avec eux, et ils seront son peuple, et Dieu même sera avec eux comme leur Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Il essuiera toute larme de leurs yeux, la mort ne sera plus, il n\'y aura plus ni deuil, ni cri, ni labeur, car les premières choses ont disparu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Et celui qui était assis sur le trône, dit: «Voici, je vais faire toutes choses nouvelles.» Et il ajouta: «Ecris, car cette parole est sûre et véritable.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Puis il me dit: «C\'est fait! Je suis l\'alpha et l\'oméga, le commencement et la fin. A celui qui a soif, je donnerai gratuitement de la source d\'eau de la vie.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Celui qui vaincra possédera ces choses; je serai son Dieu et il sera mon fils.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Quant aux lâches, aux incrédules, aux abominables, aux meurtriers, aux libertins, aux magiciens et à tous les menteurs, leur part sera dans l‘étang ardent de feu et de soufre: c\'est la seconde mort.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Alors l\'un des sept anges qui tenaient les sept coupes pleines des sept derniers fléaux, vint me parler, et me dit: «Viens, je te montrerai l’épouse, la femme de l’agneau.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Et m\'ayant transporté en esprit sur une grande et haute montagne, il me montra la ville sainte, Jérusalem, qui descendait du ciel d\'auprès de Dieu, resplendissante de la gloire de Dieu.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'L\'astre qui l\'éclaire est semblable à une pierre très précieuse, on dirait une pierre de jaspe cristallin.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Elle a une grande et haute muraille avec douze portes; à ces portes sont douze anges, et sur ces portes sont des noms écrits, ceux des douze tribus des fils d\'Israël.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Il y a trois portes à l\'orient, trois portes au nord, trois portes au midi et trois portes à l\'occident.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'La muraille de la ville a pour fondements douze pierres, sur lesquelles sont douze noms, ceux des douze apôtres de l’agneau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'L\'ange qui me parlait, tenait une mesure, un roseau d\'or, pour mesurer la ville, ses portes et sa muraille.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'La ville est quadrangulaire, d\'une longueur égale à sa largeur. Il mesura la ville avec son roseau, et trouva douze mille stades; la longueur, la largeur et la hauteur en sont égales.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Il en mesura aussi la muraille, et trouva cent quarante-quatre coudées, mesure d\'homme qui est aussi mesure d\'ange.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'La muraille est construite en jaspe; la ville est d\'un or pur semblable à du verre pur.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Les fondements de la ville sont faits de toutes sortes de pierres précieuses: le premier fondement est du jaspe; le second, du saphir; le troisième, de calcédoine; le quatrième, de l’émeraude;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'le cinquième, du sardonyx; le sixième, de la cornaline; le septième, de la chrysolithe: le huitième, du béryl; le neuvième, de la topaze; le dixième, de la chrysoprase; le onzième, de l\'hyacinthe; le douzième de l\'améthyste.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Les douze portes sont douze perles; chacune des portes est d\'une seule perle; la rue de la ville est d\'un or pur, comme du verre transparent.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Je n\'y vis point de sanctuaire, car le Seigneur Dieu tout-puissant et l\'agneau en sont le sanctuaire.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'La ville n\'a besoin ni du soleil, ni même de la lune pour l\'éclairer, car la gloire de Dieu l\'illumine, et l’agneau en est le flambeau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Les nations marcheront à sa lumière, et les rois de la terre y apporteront leurs magnificences et leurs richesses.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Les portes ne seront point fermées chaque jour, car il n\'y aura point de nuit.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'On y apportera les magnificences et les richesses des nations;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'et il n\'y entrera rien de souillé, ni personne qui se livre à l\'abomination ou au mensonge, mais ceux-là seulement qui sont inscrits dans le livre de vie de l\'agneau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Et l\'ange me montra le fleuve d\'eau de la vie, clair comme du cristal; il sortait du trône de Dieu et de l\'agneau.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Au milieu de la rue de la ville et des deux côtés du fleuve, se trouvent des arbres de vie qui donnent douze récoltes, une récolte par mois, et dont les feuilles servent à la guérison des nations.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Il n\'y aura plus d\'anathème. Le trône de Dieu et de l\'agneau sera dans la ville; les serviteurs de Dieu le serviront,');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'ils verront sa face, son nom sera sur leurs fronts.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Il n\'y aura point de nuit, et ils n\'auront besoin ni de lampe, ni de lumière, parce que le Seigneur Dieu les illuminera; et ils régneront aux siècles des siècles.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Et l’ange me dit: «Ces paroles sont sûres et véritables; et le Seigneur, le Dieu des esprits des prophètes, a envoyé son ange, pour montrer à ses serviteurs les événements qui doivent bientôt arriver.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '«Voici, je viens bientôt. «Heureux celui qui garde les paroles de la prophétie de ce livre!»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'C\'est moi, Jean, qui ai entendu et vu ces choses, et, après les avoir entendues et vues, je tombai aux pieds de l\'ange qui me les montrait, pour l\'adorer.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Mais il me dit: «Garde-toi de le faire; je suis ton compagnon de service, le compagnon de tes frères, les prophètes, et de ceux qui gardent les paroles de ce livre: adore Dieu.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Et il me dit: «Ne tiens point secrètes les paroles de la prophétie de ce livre; le moment est proche.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, '«Que l\'injuste fasse encore le mal; que l\'impur se souille encore; que le juste pratique encore la justice, et que le saint se sanctifie encore.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Voici, je viens bientôt, et la rétribution est avec moi: je rendrai à chacun selon ses oeuvres.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Je suis l\'alpha et l\'oméga, le premier et le dernier, le commencement et la fin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Heureux ceux qui pratiquent ses commandements, afin d\'avoir droit à l\'arbre de vie, et d\'entrer dans la ville par les portes!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Dehors, les chiens, les magiciens, les libertins, les meurtriers, les idolâtres, et quiconque aime le mensonge et s\'y adonne!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '«C\'est moi, Jésus, qui ai envoyé mon ange, pour vous annoncer ces choses, à vous, églises. C\'est moi qui suis le rejeton et le fils de David, l\'étoile brillante du matin.»');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Et l\'Esprit et l\'épouse disent: «Viens.» Que celui qui entend, dise aussi: «Viens.» Que celui qui a soif, vienne. Que celui qui désire l\'eau de la vie, en prenne gratuitement.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Je déclare à quiconque entend les paroles de ce livre, que si quelqu\'un y ajoute, Dieu le frappera des calamités qui sont décrites dans ce livre;');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'et que, si quelqu\'un retranche des paroles de ce livre prophétique, Dieu lui retranchera sa part de l\'arbre de vie et l’exclura de la ville sainte, qui sont décrits dans ce livre.');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Celui qui atteste ces choses, dit: «Oui, je viens bientôt.» — «Amen! Viens, Seigneur Jésus!');
INSERT INTO `FreOltramare1874_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Que la grâce du Seigneur Jésus soit avec tous!');
